def handed(product: str, names: Iterable[str]) -> None:
    """The route's record that a stage handed `product` on, field by field."""
    for name in names:
        ledger.record(f"{product}.{name}.produced")


def reads(product: str, names: Iterable[str], stage: str) -> None:
    """The route's record, at the point of reading, of which fields of `product` `stage` read."""
    for name in names:
        ledger.record(f"{product}.{name}.consumed_by.{stage}")


def field_names(value: Any) -> list[str]:
    """The fields of a stage's product, a dataclass, in their declared order."""
    return [field.name for field in fields(value)]


def frame_reading(series: Series, z: int) -> PlaneFrame | ValueError:
    """One slice's frame in the scanner's millimetres, or the error its header raised: made once
    per slice and handed to every stage that asks for it (the squint, which reads every slice's
    first, then the middle slice and each part's own slice)."""

    def make() -> PlaneFrame | ValueError:
        reads("series", ("geometry",), "frame")
        geometry = series.geometry
        if geometry is None:
            return ValueError("the series has no geometry")
        try:
            return PlaneFrame.from_dicom(
                geometry.position[z], geometry.orientation[z], geometry.spacing[z]
            )
        except ValueError as error:
            return error

    return once("frame", (series.row.series_uid, z), make)


def plane_frame(series: Series, index: int) -> PlaneFrame | str:
    """One slice's frame (`frame_reading`), or why its header does not read as one."""
    if series.geometry is None:
        return "geometry_unreadable"
    frame = frame_reading(series, index)
    return f"geometry_unreadable: {frame}" if isinstance(frame, ValueError) else frame


def finite_of(series: Series) -> np.ndarray:
    """Which of a series' stored values are finite, (Z, R, C): read once for the series and handed
    to the background split, the squint and every lens read on its slices."""
    return once(
        "finite", series.row.series_uid, lambda: np.isfinite(np.asarray(series.volume))
    )


def margin_of(series_uid: str, z: int, plane: np.ndarray) -> np.ndarray:
    """One slice's black margin (`margin`), found once per slice and handed to every stage that
    asks: the slice's naming, its reading with its partner, and each part laid onto or from it."""
    return once("margin", (series_uid, z), lambda: margin(plane))


def matched(
    onto_series: Series,
    onto: dict,
    onto_frame: PlaneFrame,
    onto_shape: tuple[int, int],
    source: dict,
    source_frame: PlaneFrame,
    source_plane: np.ndarray,
) -> np.ndarray | str:
    """The places of one slice (`onto`, its record) matched to those of another slice of the same
    knee (`source`), by `places_from`: made once for the pair, in this direction, and handed to
    every stage that lays a reading across (the partner reading, the tendons, the rest of the
    field, a part laid onto its own slice); or why not: this slice's thickness is not in its
    header ("no_slice_thickness"), or the two are not the same place ("not_the_same_place")."""

    def make() -> np.ndarray | str:
        reads("series", ("slice_thickness_mm",), "match")
        thickness = onto_series.slice_thickness_mm[onto["slice_index"]]
        if thickness is None:
            return "no_slice_thickness"
        places = places_from(
            ~margin_of(source["series_uid"], source["slice_index"], source_plane),
            source_frame,
            onto_frame,
            onto_shape,
            thickness,
        )
        return "not_the_same_place" if places is None else places

    key = (
        onto["series_uid"],
        onto["slice_index"],
        source["series_uid"],
        source["slice_index"],
    )
    return once("match", key, make)


@dataclass(frozen=True, slots=True)
class Measured:
    """One series as `measure` read it: the record and arrays the run keeps, its squint, the named
    objects of its middle slice, and that slice's frame."""

    series: Series
    record: dict
    arrays: dict[str, np.ndarray]
    stack: SquintStack
    assignment: PlaneAssignment
    frame: PlaneFrame


def measure(series: Series, drawn: bool) -> Measured | str:
    """One series' readings: its background split and its squint, each read once over the whole
    series, and the interiors and named objects at its middle slice; or why no plane was read.
    Which of its values are finite, and every slice's frame, are read once here and handed to the
    split, the squint and the lens. `drawn` says whether the study's pictures will be drawn, the
    only reader of the middle slice's border readings."""
    reads("series", ("volume", "geometry"), "measure")
    if series.volume is None:
        return "no_stacked_volume"
    if series.geometry is None:
        return "geometry_unreadable"
    index = selected_slice(len(series.volume), None)
    if index is None:
        return "slice_unavailable"
    frame = plane_frame(series, index)
    if isinstance(frame, str):
        return frame
    finite = finite_of(series)
    # The background split: the valley after the background's mode in the series' own histogram
    # (`knee.collapse.noise.background_split`), the level the lens reads low signal under.
    reads("series", ("volume",), "background")
    split = background_split(finite_values(series.volume, finite))
    handed("background", ("split",))
    # The squint, made once for the series and kept with it for any stage to consult; it records
    # its own reading of the series and its counted work on the ledger. It reads every slice's
    # frame, made once for the squint and every stage after it.
    reads("series", ("volume", "geometry", "row", "stack"), "squint_stack")
    stack = read_squint_stack(
        series, SQUINT_TILE_MM, lambda z: frame_reading(series, z), finite
    )
    handed("squint_stack", field_names(stack))
    # The header's own word for which knee this is ("R", "L", or blank); it sides the menisci.
    reads("series", ("slices",), "naming")
    knee = str(getattr(series.slices[index].header, "Laterality", "") or "").strip()
    record, arrays, assignment = name_plane(
        series, index, series.volume[index], frame, split, knee, borders=drawn
    )
    record["squint"] = {
        "code": stack.code,
        "why": stack.why,
        "tile_mm": stack.tile_mm,
        "tile_shape_rc": list(stack.tile_shape_rc),
    }
    for name in SQUINT_ARRAYS:
        arrays[f"squint_{name}"] = np.asarray(getattr(stack, name))
    return Measured(series, record, arrays, stack, assignment, frame)


def lens_of(
    series: Series,
    index: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    split: float,
    reader: str | None = None,
    *,
    borders: bool = False,
) -> tuple[np.ndarray, InteriorRegions, dict]:
    """One slice's lens reading, made once per slice and handed to every stage that asks for that
    slice (its naming, and a part named on it, whose slice may be the middle slice or another
    part's): the acquired plane, the interiors, and what the record says of them. `reader` is the
    part whose own slice this is, whose lens readings the ledger counts.

    With `borders` the border readings across the territories are read too (`read_interiors`).
    Only the pictures read them, so only a middle slice of a run that draws asks for them; every
    other reading is the territories alone (`interior_regions`, the same arrays), and a run that
    draws nothing reads no border. The middle slices are read first (`measure`), so a part's slice
    that is a middle slice is handed the middle slice's lens."""

    def read() -> tuple[np.ndarray, InteriorRegions, dict]:
        reads("series", ("volume", "row", "slices"), "interiors")
        reads("background", ("split",), "interiors")
        reading: InteriorRegions
        if borders:
            axes = frame.basis_lps / frame.spacing_rc
            reading = read_interiors(
                plane,
                frame.spacing_rc,
                split,
                PROMINENCE_MM,
                np.asarray(OFFSETS_MM),
                BACKEND,
                metric_rc=axes.T @ axes,
                available=finite_of(series)[index],
            )
        else:
            reading = interior_regions(
                plane,
                frame.spacing_rc,
                split,
                PROMINENCE_MM,
                available=finite_of(series)[index],
            )
        handed("interiors", field_names(reading))
        ledger.record(
            "interiors.work", planes=1, territories=int(reading.labels.max(initial=0))
        )
        if reader is not None:
            ledger.record(f"{reader}.lens_readings", planes=1)
        interiors: dict[str, Any] = {
            "code": reading.code,
            "territories": int(reading.labels.max(initial=0)),
        }
        # what the border readings found, where they were read
        if isinstance(reading, InteriorReading):
            interiors.update(
                edge_counts={
                    kind: int(np.count_nonzero(reading.edge_kinds == value))
                    for kind, value in EDGE_KINDS.items()
                },
                trace_counts={
                    code: int(np.count_nonzero(reading.trace_codes == value))
                    for code, value in TRACE_CODES.items()
                },
                backend=BACKEND,
            )
        # frozen, as the interiors' own fields are: every stage that reads the slice is handed it
        return handed_on(plane.copy()), reading, interiors

    return once("lens", (series.row.series_uid, index), read)


def field_of(
    series: Series,
    index: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    reading: InteriorRegions,
) -> Field:
    """One slice's field (`read_field`: the leg, the air and the skin, the territories' peaks, which
    way the slice faces), made once per slice and handed to its naming and to any part named on
    it, which reads nothing more."""
    uid = series.row.series_uid

    def read() -> Field:
        reads("interiors", ("dark", "labels", "distance_mm"), "field")
        field = read_field(
            plane, reading, frame.basis_lps, margin_of(uid, index, plane)
        )
        handed("field", field_names(field))
        return field

    return once("field", (uid, index), read)


def measures_of(uid: str, index: int, plane: np.ndarray, frame: PlaneFrame) -> Measures:
    """One slice's shared measures (`knee.objects.assignments.Measures`), kept under its series and
    index: each stage that weighs a place on the slice is handed what an earlier one read there."""
    return Measures((uid, index), plane, frame.basis_lps)


def enclosed_depth_of(
    plane: np.ndarray, series_uid: str | None = None, slice_index: int | None = None
) -> np.ndarray:
    """The native enclosed-darkness reading, shared only for the exact same stored plane."""
    if series_uid is None or slice_index is None:
        return enclosed_darkness(plane)
    return once(
        "enclosed_darkness",
        (series_uid, slice_index, digest(np.asarray(plane))),
        lambda: enclosed_darkness(plane),
    )


def slice_record(
    series: Series,
    index: int,
    split: float,
    knee: str,
    lens: tuple[np.ndarray, InteriorRegions, dict],
    field: Field,
) -> tuple[dict, dict[str, np.ndarray]]:
    """The record and arrays one slice's reading makes before a part is named on it: the lens's
    arrays and what the record says of them, the field's names and peaks, and every part of a
    slice's naming (`SLICE_PARTS`) not named there, until the stage that names one says so. The
    border readings are kept where the lens read them, for the pictures."""
    acquired, reading, interiors = lens
    arrays = {
        "acquired_plane": acquired,
        "b1_dark": reading.dark,
        "b1_available": reading.available,
        "b1_distance_mm": reading.distance_mm,
        "b1_markers": reading.markers,
        "b1_labels": reading.labels,
    }
    if isinstance(reading, InteriorReading):
        arrays.update(
            b1_edge_points_rc=reading.edge_points_rc,
            b1_edge_normals_rc=reading.edge_normals_rc,
            b1_trace_codes=reading.trace_codes,
            b1_trace_points_rc=reading.trace_points_rc,
        )
    arrays["a1_objects"] = field.objects
    row = series.row
    record = {
        "series_uid": row.series_uid,
        "view": [row.anatomical_plane, row.fluid_sensitive, row.fat_suppression],
        "slice_index": index,
        "source_plane": series.slices[index].path.name,
        "background_split": split,
        "interiors": dict(interiors),
        "assignments": {
            "knee": knee,
            "codes": dict.fromkeys(SLICE_PARTS, "not_named_on_this_slice"),
            "femur": None,
            "tibia": None,
            "patella": None,
            "peaks": [asdict(peak) for peak in field.peaks],
        },
    }
    return record, arrays


def name_plane(
    series: Series,
    index: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    split: float,
    knee: str,
    *,
    borders: bool,
) -> tuple[dict, dict[str, np.ndarray], PlaneAssignment]:
    """A middle slice read and named: its lens (`lens_of`, with its border readings when `borders`,
    for a run that draws) and its field (`field_of`), and the parts named on it alone
    (`assign_plane`, with the slice's shared measures), each made once per slice; the record and
    arrays the renderers read, and the named objects themselves."""
    uid = series.row.series_uid
    lens = lens_of(series, index, plane, frame, split, borders=borders)
    # the middle slices are read before any part's slice, so a run that draws reads their borders
    if borders and not isinstance(lens[1], InteriorReading):
        raise RuntimeError("middle_slice_lens_read_without_its_borders")
    field = field_of(series, index, plane, frame, lens[1])

    def name() -> PlaneAssignment:
        reads("field", field_names(field), "naming")
        reads("interiors", ("dark", "labels"), "naming")
        fat_suppressed = (
            int(series.row.fat_suppression) == 1
        )  # the tags are stored as text
        fluid_sensitive = int(series.row.fluid_sensitive) == 1
        assignment = assign_plane(
            plane,
            lens[1],
            frame.basis_lps,
            knee,
            fat_suppressed,
            fluid_sensitive,
            margin_of(uid, index, plane),
            field,
            measures_of(uid, index, plane, frame),
        )
        handed("naming", field_names(assignment))
        return assignment

    assignment = once("naming", (uid, index), name)
    record, arrays = slice_record(series, index, split, knee, lens, field)
    arrays["a1_objects"] = assignment.objects
    # a copy: the stages after this change the record's codes, never the slice's own
    record["assignments"].update(
        codes=dict(assignment.codes),
        femur=assignment.femur,
        tibia=assignment.tibia,
        patella=assignment.patella,
    )
    return record, arrays, assignment


def read_part_slice(
    series: Series,
    index: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    split: float,
    knee: str,
    reader: str | None = None,
) -> tuple[dict, dict[str, np.ndarray], Field]:
    """A part's own slice read: its lens (`lens_of`) and its field (`field_of`), each made once per
    slice, and nothing else named on it, since the part's own rule names it and reads nothing more;
    every other part of a slice's naming is not named there. `reader` is the part, whose lens
    readings the ledger counts."""
    lens = lens_of(series, index, plane, frame, split, reader)
    field = field_of(series, index, plane, frame, lens[1])
    record, arrays = slice_record(series, index, split, knee, lens, field)
    return record, arrays, field


def partner_of(measured: list[Measured], index: int) -> Measured | None:
    """The series whose middle slice is the same place in the other sequence: the first of the same
    plane with the other fat-suppression tag that `laid_on` finds on the same plane. None when there
    is none."""
    reads("series", ("row",), "partner")
    own = measured[index]
    for other in measured:
        same = other.series.row.anatomical_plane == own.series.row.anatomical_plane
        other_sequence = (
            other.series.row.fat_suppression != own.series.row.fat_suppression
        )
        if other is not own and same and other_sequence:
            return other
    return None


def read_with_partner(own: Measured, partner: Measured) -> str:
    """Read one series' middle slice with its partner's (`with_partner`), keeping the result in its
    record and arrays; or say why it was not: the two slices are not the same place, or this
    slice's thickness is not in its header to say so. The two slices' places are matched once
    (`matched`), and every later stage that lays a reading across reuses the match."""
    plane = own.arrays["acquired_plane"]
    source = matched(
        own.series,
        own.record,
        own.frame,
        plane.shape,
        partner.record,
        partner.frame,
        partner.arrays["acquired_plane"],
    )
    if isinstance(source, str):
        return source
    reads("naming", ("objects", "codes", "peaks"), "partner")
    reads("interiors", ("labels",), "partner")
    objects, codes = with_partner(
        own.assignment,
        own.arrays["b1_labels"],
        own.frame.basis_lps,
        margin_of(own.record["series_uid"], own.record["slice_index"], plane),
        laid_by(partner.assignment.objects, source),
        partner.assignment.codes,
    )
    handed("partner", ("objects", "codes"))
    own.arrays["a1_objects"] = objects
    own.record["assignments"]["codes"] = codes
    # A bone the two slices do not agree on, or one laid on from the partner, has no territory of
    # this slice's own.
    for name in ("femur", "tibia", "patella"):
        if codes.get(name) not in ("identified", "agreed_with_its_partner"):
            own.record["assignments"][name] = None
    return "read_with_" + partner.record["series_uid"]


def leg_on(
    leg: "Leg",
    series: Series,
    z: int,
    frame: PlaneFrame,
    shape: tuple[int, int],
    thickness: float,
) -> tuple[np.ndarray, np.ndarray]:
    """The leg's femur and tibia carried by place onto one slice of a series the leg runs through
    (`places_on_slice`): made once per slice and handed to every stage that asks for it (the
    search for the top of the tibia, and the back of the knee's parts on their slices)."""
    return once(
        "leg_on_slice",
        (series.row.series_uid, z, leg.identity or leg_identity(leg)),
        lambda: (
            places_on_slice(leg.femur_lps, frame, shape, thickness),
            places_on_slice(leg.tibia_lps, frame, shape, thickness),
        ),
    )


@dataclass(frozen=True, slots=True)
class Leg:
    """The femur and the tibia named on a study's middle slices where the leg runs in the plane, in
    the scanner's millimetres, and the notch's plane, where the first middle sagittal slice passes
    (None without one), its normal toward the patient's left: one leg, one set of objects, made
    once for every slice it is carried onto. The native named patella is retained too. `identity`
    names exactly these places (`leg_identity`), so a slice's carried projection is cached per leg:
    the leg refined by the later native bone sections (`refine_leg`) is never answered with the
    early leg's projection."""

    femur_lps: np.ndarray
    tibia_lps: np.ndarray
    notch_origin_lps: np.ndarray | None
    notch_normal: np.ndarray | None
    patella_lps: np.ndarray
    identity: str = ""

    def __post_init__(self) -> None:
        # The identity names these places, so they never change after it is made: each array is
        # the leg's own read-only copy (an array already read-only is the leg's and kept as is).
        for name in (
            "femur_lps",
            "tibia_lps",
            "notch_origin_lps",
            "notch_normal",
            "patella_lps",
        ):
            value = getattr(self, name)
            if value is None:
                continue
            array = np.asarray(value)
            if array.flags.writeable:
                array = array.copy()
                array.flags.writeable = False
            object.__setattr__(self, name, array)


def leg_identity(leg: "Leg") -> str:
    """The digest of the leg's places and notch: equal places, equal identity."""
    parts = [digest(leg.femur_lps), digest(leg.tibia_lps), digest(leg.patella_lps)]
    for value in (leg.notch_origin_lps, leg.notch_normal):
        parts.append("none" if value is None else digest(np.asarray(value)))
    return ":".join(parts)


@dataclass(frozen=True, slots=True)
class Carried:
    """The leg's bones carried onto one slice the leg runs through: the femur's and the tibia's
    places there, each place's position toward the back, and its distance toward the patient's
    left of the notch (None when the study has no sagittal slice)."""

    femur: np.ndarray
    tibia: np.ndarray
    back_mm: np.ndarray
    toward_left_mm: np.ndarray | None


def leg_of(measured: list[Measured]) -> Leg:
    """The study's leg: the femur and the tibia of its middle slices where the leg runs in the
    plane, as their partner reading left them, in the scanner's millimetres; and the notch's plane
    from the first of them that side to side runs through, a sagittal one. Which way each slice
    faces is its naming's (`PlaneAssignment.in_plane`), read once. The patella comes from the
    first native identification, without resampling its laid twin."""
    reads("partner", ("objects", "codes"), "leg")
    reads("naming", ("in_plane",), "leg")
    femur, tibia = [np.zeros((0, 3))], [np.zeros((0, 3))]
    patella = np.zeros((0, 3))
    notch_origin = notch_normal = None
    for other in measured:
        sides_in_plane, _, leg_in_plane = other.assignment.in_plane
        if not leg_in_plane:
            continue
        objects = other.arrays["a1_objects"]
        for name, found in (("femur", femur), ("tibia", tibia)):
            places = np.argwhere(objects == OBJECT_CODES[name]).astype(float)
            found.append(other.frame.to_patient(places))
        # The native FS definition supplies one patella, rather than resampling its laid twin.
        if (
            not len(patella)
            and other.record["assignments"]["codes"].get("patella") == "identified"
        ):
            places = np.argwhere(objects == OBJECT_CODES["patella"]).astype(float)
            patella = other.frame.to_patient(places)
        if notch_origin is None and not sides_in_plane:
            normal = other.frame.normal()
            notch_origin = other.frame.origin_lps
            notch_normal = normal if normal[0] > 0 else -normal
    leg = Leg(
        np.concatenate(femur),
        np.concatenate(tibia),
        notch_origin,
        notch_normal,
        patella,
    )
    leg = replace(leg, identity=leg_identity(leg))
    handed("leg", field_names(leg))
    return leg


def carry_onto(
    leg: Leg,
    series: Series,
    z: int,
    frame: PlaneFrame,
    shape: tuple[int, int],
    thickness: float,
) -> Carried:
    """The leg's bones carried by place onto one slice the leg runs through (`leg_on`, made once
    per slice), with each place's position toward the back and toward the patient's left of the
    notch."""
    reads(
        "leg", ("femur_lps", "tibia_lps", "notch_origin_lps", "notch_normal"), "carry"
    )
    femur, tibia = leg_on(leg, series, z, frame, shape, thickness)
    rows, cols = np.indices(shape)
    places = frame.to_patient(
        np.column_stack((rows.ravel(), cols.ravel())).astype(float)
    ).reshape(*shape, 3)
    toward_left = None
    if leg.notch_origin_lps is not None and leg.notch_normal is not None:
        toward_left = (places - leg.notch_origin_lps) @ leg.notch_normal
    carried = Carried(femur, tibia, places[..., 1], toward_left)
    handed("carried", field_names(carried))
    return carried


def name_the_back_of_the_knee(own: Measured, leg: Leg | None) -> dict[str, str]:
    """Both gastrocnemius heads named on this series' middle slice (their paragraphs in
    `knee.objects.assignments`), from the lens the run has already read there and the study's leg
    carried onto it (`carry_onto`), which is carried only once its first three descriptions hold,
    so nothing is carried that no part reads; each head's code, or why the bones were not carried.
    Both use the same operations on opposite physical sides. No lens is read again."""
    assigned = own.record["assignments"]
    names = ("medial_gastrocnemius", "lateral_gastrocnemius")
    for name in names:
        assigned[name] = None
    vessel_names = ("popliteal_artery", "popliteal_vein")
    vessel_codes = assigned["codes"]
    vessel_shape = own.arrays["b1_labels"].shape
    own.arrays["a2_popliteal_artery"] = np.zeros(vessel_shape, dtype=bool)
    own.arrays["a2_popliteal_vein"] = np.zeros(vessel_shape, dtype=bool)
    for name in vessel_names:
        assigned[name] = None
        vessel_codes[name] = "not_named_on_this_slice"

    def abstain_vessels(code: str) -> None:
        for vessel in vessel_names:
            vessel_codes[vessel] = code

    knee = assigned["knee"]
    reads("series", ("row",), "gastrocnemius")
    reads("naming", ("in_plane",), "gastrocnemius")
    # the tag is stored as text
    fat_suppressed = int(own.series.row.fat_suppression) == 1
    code = gastrocnemius_code(
        not own.assignment.in_plane[2], knee, fat_suppressed, True, True, True, True
    )
    if code != "identified":
        abstain_vessels(code)
        return dict.fromkeys(names, code)
    if leg is None:
        abstain_vessels("abstain_no_bone_carried")
        return dict.fromkeys(names, "abstain_no_bone_carried")
    reads("series", ("slice_thickness_mm",), "gastrocnemius")
    thickness = own.series.slice_thickness_mm[own.record["slice_index"]]
    if thickness is None:
        abstain_vessels("abstain_no_slice_thickness")
        return dict.fromkeys(names, "no_slice_thickness")
    carried = carry_onto(
        leg,
        own.series,
        own.record["slice_index"],
        own.frame,
        own.arrays["acquired_plane"].shape,
        float(thickness),
    )
    reads("carried", ("femur", "tibia", "back_mm", "toward_left_mm"), "gastrocnemius")
    bone = carried.femur | carried.tibia
    notch = carried.toward_left_mm
    if not bone.any() or notch is None:
        code = gastrocnemius_code(
            True, knee, True, bool(bone.any()), notch is not None, False, False
        )
        abstain_vessels(code)
        return dict.fromkeys(names, code)
    reads("naming", ("peaks",), "gastrocnemius")
    reads("interiors", ("labels",), "gastrocnemius")
    labels = own.arrays["b1_labels"]
    peaks = own.assignment.peaks
    # the inner side is toward the other knee: the patient's left for a right knee
    inner_mm = notch if knee == "R" else -notch
    # a copy: the names the slice made alone (`Measured.assignment`) stay as made
    objects = own.arrays["a1_objects"].copy()
    head_codes = {}
    head_masks = {}
    head_peaks = {}
    condyles = {}
    lateral_codes = {
        "abstain_no_inner_condyle": "abstain_no_outer_condyle",
        "abstain_no_body_behind_the_inner_condyle": "abstain_no_body_behind_the_outer_condyle",
    }
    placed_any = False
    for name, toward in ((names[0], inner_mm), (names[1], -inner_mm)):
        condyle = inner_condyle(peaks, labels, bone, toward)
        head = np.zeros(labels.shape, dtype=bool)
        if condyle is not None:
            head = gastrocnemius_head(
                peaks, labels, bone, condyle, carried.back_mm, toward
            )
        condyles[name] = condyle
        head_masks[name] = head
        placed = head & (objects == 0)
        objects[placed] = OBJECT_CODES[name]
        assigned[name] = int(labels[head].max()) if head.any() else None
        if head.any():
            territory = int(labels[head].max())
            head_peaks[name] = next(
                peak for peak in peaks if peak.territory == territory
            )
        placed_any |= bool(placed.any())
        code = gastrocnemius_code(
            True, knee, True, True, True, condyle is not None, bool(placed.any())
        )
        head_codes[name] = lateral_codes.get(code, code) if name == names[1] else code
    own.arrays["a1_objects"] = objects
    if placed_any:
        handed("gastrocnemius", ("region",))

    if not all(
        head_codes.get(name) == "identified" and name in head_peaks for name in names
    ):
        abstain_vessels("abstain_requires_both_gastrocnemius_heads")
        return head_codes
    condyle_peaks = [condyles[name] for name in names]
    if any(peak is None for peak in condyle_peaks):
        abstain_vessels("abstain_requires_both_gastrocnemius_heads")
        return head_codes

    reads(
        "carried",
        ("back_mm", "toward_left_mm"),
        "popliteal_lumens",
    )
    reads("naming", ("peaks",), "popliteal_lumens")
    reads("interiors", ("labels",), "popliteal_lumens")
    head_side = [float(inner_mm[head_peaks[name].peak_rc]) for name in names]
    front_of_condyles = max(
        float(carried.back_mm[peak.peak_rc])
        for peak in condyle_peaks
        if peak is not None
    )
    behind_heads = max(float(carried.back_mm[head_masks[name]].max()) for name in names)
    corridor = (
        (inner_mm > min(head_side))
        & (inner_mm < max(head_side))
        & (carried.back_mm > front_of_condyles)
        & (carried.back_mm < behind_heads)
    )
    depth = enclosed_depth_of(
        own.arrays["acquired_plane"],
        own.record.get("series_uid"),
        own.record["slice_index"],
    )
    handed("popliteal_lumens", ("enclosed_darkness", "corridor"))
    reads("popliteal_lumens", ("enclosed_darkness", "corridor"), "popliteal_lumens")
    artery, vein, components, vessel_code = popliteal_lumens(
        depth, corridor, carried.back_mm, np.asarray(own.frame.spacing_rc)
    )
    own.arrays.update(
        a2_enclosed_darkness=depth,
        a2_vessel_corridor=corridor,
        a2_closed_lumens=components,
        a2_popliteal_artery=artery,
        a2_popliteal_vein=vein,
    )
    for name in vessel_names:
        vessel_codes[name] = vessel_code
    # every closed lumen the rule weighed is kept with the reading; no stage reads them
    handed("popliteal_lumens", ("components",))
    if vessel_code == "identified":
        handed("popliteal_lumens", ("artery", "vein"))
    return head_codes


def name_the_extensor_tendons(own: Measured, partner: Measured | None) -> None:
    """The patellar and quadriceps tendons named on this series' middle slice where their band is
    plain (their paragraph in `knee.objects.assignments`): a sagittal slice without fat
    suppression, from the dark bands its PCL was read from (`PlaneAssignment.bands`) and the
    patella laid on from its partner, the fat-suppressed slice of the same place; then laid onto
    that partner by place, where its fat pads beside the patella yield to them. Each slice's codes
    are set; no lens is read again."""
    reads("naming", ("bands",), "tendons")
    bands = own.assignment.bands
    if bands is None:
        return
    reads("partner", ("objects",), "tendons")
    # a copy: the names the slice made alone (`Measured.assignment`) stay as made
    objects = own.arrays["a1_objects"].copy()
    patellar, quadriceps = extensor_tendons(
        bands,
        objects,
        np.asarray(own.frame.spacing_rc),
        own.frame.basis_lps,
        measures_of(
            own.record["series_uid"],
            own.record["slice_index"],
            own.arrays["acquired_plane"],
            own.frame,
        ),
    )
    ends = bool(
        (objects == OBJECT_CODES["patella"]).any()
        and (objects == OBJECT_CODES["tibia"]).any()
    )
    codes = own.record["assignments"]["codes"]
    for name, tendon, above in (
        ("patellar_tendon", patellar, False),
        ("quadriceps_tendon", quadriceps, True),
    ):
        objects[tendon] = OBJECT_CODES[name]
        codes[name] = tendon_code(True, False, ends, bool(tendon.any()), above)
    own.arrays["a1_objects"] = objects
    if not (patellar.any() or quadriceps.any()):
        return
    handed("tendons", ("region",))
    if partner is None:
        return
    fat = (OBJECT_CODES["hoffa_fat_pad"], OBJECT_CODES["suprapatellar_fat"])
    laid = lay_parts(
        partner,
        (partner.record, partner.arrays, partner.frame),
        (own.record, own.arrays, own.frame),
        ("patellar_tendon", "quadriceps_tendon"),
        fat,
        # with fat suppression the band is the border between two of the lens's regions
        onto_borders=True,
        product="tendons",
    )
    for name, code in laid.items():
        if code is not None:
            partner.record["assignments"]["codes"][name] = code


def partner_white(own: Measured, partner: Measured | None) -> np.ndarray:
    """At this series' middle slice's places, where its partner, the other sequence's slice of the
    same place, sees white as fluid: the white the partner kept where it is fat-suppressed and
    fluid-sensitive (`PlaneAssignment.white`), laid on by the pair's one match (`matched`). None
    of it where there is no such partner, this slice's thickness is not in its header, the two are
    not the same place, or the partner's picture does not reach: there nothing tells fluid apart."""
    none = np.zeros(own.arrays["acquired_plane"].shape, dtype=bool)
    if partner is None:
        return none
    reads("naming", ("white",), "rest_of_the_field")
    white = partner.assignment.white
    if white is None:
        return none
    source = matched(
        own.series,
        own.record,
        own.frame,
        none.shape,
        partner.record,
        partner.frame,
        partner.arrays["acquired_plane"],
    )
    if isinstance(source, str):
        return none
    return laid_by(white.astype(np.int8), source) == 1


def name_the_rest_of_the_field(own: Measured, partner: Measured | None) -> None:
    """The rest of the field (their paragraphs in `knee.objects.assignments`), the fat under the
    skin and then muscle, on this series' middle slice where fat is not suppressed, once it is read
    with its partner: the fat where the slice read the skin only once its partner's was laid on,
    from its light; muscle on every such slice, outside every part named and the white its partner
    sees as fluid where that partner is fat-suppressed and fluid-sensitive (`partner_white`, laid
    on only where muscle can be named). The femur's marrow light both weigh their places against
    is the slice's shared measure (`measures_of`), read once, and each part a slice names from its
    own light is laid onto its partner by the pair's one match. No lens is read again."""
    reads("series", ("row",), "rest_of_the_field")
    # the tags are stored as text
    if int(own.series.row.fat_suppression) == 1:
        return
    reads("partner", ("objects", "codes"), "rest_of_the_field")
    codes = own.record["assignments"]["codes"]
    # a copy: the names the slice made alone (`Measured.assignment`) stay as made
    objects = own.arrays["a1_objects"].copy()
    plane = own.arrays["acquired_plane"]
    spacing = np.asarray(own.frame.spacing_rc)
    measures = measures_of(
        own.record["series_uid"], own.record["slice_index"], plane, own.frame
    )
    femur_named = bool((objects == OBJECT_CODES["femur"]).any())
    air_named = bool((objects == OBJECT_CODES["air"]).any())
    laid_skin = codes.get("subcutaneous_fat") == "abstain_no_skin" and bool(
        (objects == OBJECT_CODES["skin"]).any()
    )
    if laid_skin:
        fat = fat_under_the_skin(plane, objects, spacing, measures)
        objects[fat] = OBJECT_CODES["subcutaneous_fat"]
        codes["subcutaneous_fat"] = subcutaneous_code(
            False, True, femur_named, bool(fat.any())
        )
    # muscle is named only where the slice names air and the femur, so only there is the white
    # its partner sees laid on
    white = (
        partner_white(own, partner)
        if air_named and femur_named
        else np.zeros(plane.shape, dtype=bool)
    )
    muscle = muscle_bodies(
        plane,
        objects,
        spacing,
        margin_of(own.record["series_uid"], own.record["slice_index"], plane),
        white,
        measures,
    )
    objects[muscle] = OBJECT_CODES["muscle"]
    codes["muscle"] = muscle_code(False, air_named, femur_named, bool(muscle.any()))
    own.arrays["a1_objects"] = objects
    # only a slice that names them from its own light lays them on: one they were laid onto does
    # not lay them back
    parts = tuple(
        name
        for name in ("subcutaneous_fat", "muscle")
        if codes.get(name) == "identified"
    )
    if not parts:
        return
    handed("rest_of_the_field", ("region",))
    if partner is None:
        return
    laid = lay_parts(
        partner,
        (partner.record, partner.arrays, partner.frame),
        (own.record, own.arrays, own.frame),
        parts,
        product="rest_of_the_field",
    )
    for name, code in laid.items():
        if code is not None:
            partner.record["assignments"]["codes"][name] = code


def name_joint_boundaries(own: Measured, partner: Measured | None) -> None:
    """Locate the anterior recess, its lining surface, and the side recesses' capsular wall.

    Save separate masks where tissue surfaces coexist with fluid or collateral structures.
    Reuse the white reading, shared physical positions, and the pair's physical-place match.
    Each part the slice identifies is handed on, and read by the partner where it is laid on.
    """
    reads("series", ("row",), "joint_boundaries")
    reads("naming", ("in_plane", "white"), "joint_boundaries")
    reads("partner", ("objects", "codes"), "joint_boundaries")
    objects = own.arrays["a1_objects"]
    codes = own.record["assignments"]["codes"]
    sagittal = own.assignment.in_plane[1] and own.assignment.in_plane[2]
    coronal = own.assignment.in_plane[0] and own.assignment.in_plane[2]
    bright = (
        int(own.series.row.fat_suppression) == 1
        and int(own.series.row.fluid_sensitive) == 1
    )
    has_patella = bool((objects == OBJECT_CODES["patella"]).any())
    has_femur = bool((objects == OBJECT_CODES["femur"]).any())
    has_menisci = all(
        (objects == OBJECT_CODES[name]).any()
        for name in ("medial_meniscus", "lateral_meniscus")
    )
    white = own.assignment.white
    recess = lining = capsule = np.zeros(objects.shape, dtype=bool)
    measures = measures_of(
        own.record["series_uid"],
        own.record["slice_index"],
        own.arrays["acquired_plane"],
        own.frame,
    )
    if sagittal and bright and has_patella and has_femur and white is not None:
        recess, lining = anterior_synovial_recess(
            white,
            objects,
            own.frame.basis_lps,
            measures,
        )
    if coronal and bright and has_femur and has_menisci and white is not None:
        reads("interiors", ("dark",), "joint_boundaries")
        boundary = capsule_at_side_recesses(
            own.arrays["b1_dark"],
            white,
            objects,
            own.frame.basis_lps,
            np.asarray(own.frame.spacing_rc),
            measures,
        )
        capsule = boundary["capsule"]
        own.arrays.update(
            {
                f"a4_coronal_{name}": value
                for name, value in boundary.items()
                if name != "capsule"
            }
        )
        handed(
            "coronal_lining",
            tuple(
                "side_edge" if name == "lining" else name
                for name in boundary
                if name != "capsule"
            ),
        )
    recess_code = synovium_code(
        sagittal, bright, has_patella, has_femur, bool(recess.any())
    )
    lining_code = (
        recess_code
        if lining.any() or recess_code != "identified"
        else "abstain_no_fat_facing_surface"
    )
    wall_code = capsule_code(
        coronal, bright, has_femur, has_menisci, bool(capsule.any())
    )
    parts = tuple(
        (field, name, mask, code)
        for (field, name), mask, code in zip(
            JOINT_BOUNDARIES,
            (recess, lining, capsule),
            (recess_code, lining_code, wall_code),
            strict=True,
        )
    )
    for _, name, mask, code in parts:
        own.arrays[f"a2_{name}"] = mask
        codes[name] = code
    identified = tuple(field for field, _, _, code in parts if code == "identified")
    if not identified:
        return
    handed("joint_boundaries", identified)
    if partner is None:
        return
    source = matched(
        partner.series,
        partner.record,
        partner.frame,
        partner.arrays["acquired_plane"].shape,
        own.record,
        own.frame,
        own.arrays["acquired_plane"],
    )
    if isinstance(source, str):
        return
    reads("joint_boundaries", identified, "partner")
    for _, name, mask, code in parts:
        if code != "identified":
            continue
        placed = laid_by(mask.astype(np.int16), source) == 1
        partner.arrays[f"a2_{name}"] = placed
        partner.record["assignments"]["codes"][name] = (
            "laid_from_its_partner"
            if placed.any()
            else "abstain_outside_partner_picture"
        )


def name_suprapatellar_pads(own: Measured, partner: Measured | None) -> None:
    """Separate the two pads from their named combined field and the two acquired signals.
    Only the FS source resolves them; the same physical-place matches carry its result back."""
    reads("series", ("row",), "suprapatellar_pads")
    reads("naming", ("in_plane",), "suprapatellar_pads")
    reads("partner", ("objects", "codes"), "suprapatellar_pads")
    plane = own.arrays["acquired_plane"]
    names = ("quadriceps_fat_pad", "prefemoral_fat_pad")
    fields = (*names, "suprapatellar_recess_ridge")
    for name in fields:
        own.arrays[f"a2_{name}"] = np.zeros(plane.shape, dtype=bool)
    codes = own.record["assignments"]["codes"]

    def refuse(code: str) -> None:
        for name in names:
            codes[name] = code

    sagittal = own.assignment.in_plane[1] and own.assignment.in_plane[2]
    if not sagittal:
        refuse("abstain_not_a_sagittal_slice")
        return
    if not (
        int(own.series.row.fat_suppression) == 1
        and int(own.series.row.fluid_sensitive) == 1
    ):
        refuse("abstain_requires_fluid_sensitive_fat_suppression")
        return
    combined = own.arrays["a1_objects"] == OBJECT_CODES["suprapatellar_fat"]
    if not combined.any():
        refuse("abstain_no_suprapatellar_fat")
        return
    if partner is None or int(partner.series.row.fat_suppression) != 0:
        refuse("abstain_no_non_fat_suppressed_twin")
        return
    source = matched(
        own.series,
        own.record,
        own.frame,
        plane.shape,
        partner.record,
        partner.frame,
        partner.arrays["acquired_plane"],
    )
    if isinstance(source, str):
        refuse("abstain_" + source)
        return
    reads("series", ("volume",), "relative_signal")
    paired = laid_by(partner.arrays["acquired_plane"].astype(np.float64), source)
    paired[source < 0] = np.nan
    handed("paired_light", ("signal",))
    reads("paired_light", ("signal",), "relative_signal")
    ratio = relative_signal(plane, paired)
    handed("signal_ratio", ("value",))
    reads("signal_ratio", ("value",), "suprapatellar_pads")
    shared = measures_of(
        own.record["series_uid"], own.record["slice_index"], plane, own.frame
    )
    anterior, posterior, ridge, code = suprapatellar_pads(
        ratio, combined, own.frame.basis_lps, shared.along(1)
    )
    own.arrays["a2_nonfs_signal"] = paired
    own.arrays["a2_relative_signal"] = ratio
    for name, mask in zip(fields, (anterior, posterior, ridge), strict=True):
        own.arrays[f"a2_{name}"] = mask
    refuse(code)
    if code != "identified":
        return
    handed("suprapatellar_pads", fields)
    reverse = matched(
        partner.series,
        partner.record,
        partner.frame,
        partner.arrays["acquired_plane"].shape,
        own.record,
        own.frame,
        plane,
    )
    if isinstance(reverse, str):
        return
    reads("suprapatellar_pads", fields, "partner")
    for name in fields:
        placed = laid_by(own.arrays[f"a2_{name}"].astype(np.int16), reverse) == 1
        partner.arrays[f"a2_{name}"] = placed
        if name in names:
            partner.record["assignments"]["codes"][name] = (
                "laid_from_its_partner"
                if placed.any()
                else "abstain_outside_partner_picture"
            )


def name_iliotibial_band(own: Measured, partner: Measured | None) -> None:
    """Read the ITB on the existing middle coronal, then lay its trace onto the twin.
    The middle slice's native fat and bone names provide the targets; no lens is read again.
    FS targets are initialized before non-FS sources, as for the joint boundaries.
    """
    plane = own.arrays["acquired_plane"]
    reads("series", ("row",), "iliotibial_band")
    reads("partner", ("objects", "codes"), "iliotibial_band")
    reads("interiors", ("available",), "iliotibial_band")
    mask, readings, code = iliotibial_band_on_slice(
        plane,
        own.arrays["a1_objects"],
        own.arrays["b1_available"],
        own.frame.basis_lps,
        own.record["assignments"]["knee"],
        int(own.series.row.fat_suppression) == 1,
        measures=measures_of(
            own.record["series_uid"], own.record["slice_index"], plane, own.frame
        ),
    )
    own.arrays["a2_iliotibial_band"] = mask
    for name, value in readings.items():
        own.arrays[f"a2_itb_{name}"] = value
    own.record["assignments"]["codes"]["iliotibial_band"] = code
    if code != "identified":
        return
    handed("iliotibial_band", ("region",))
    if partner is None or int(partner.series.row.fat_suppression) != 1:
        return
    laid = lay_parts(
        partner,
        (partner.record, partner.arrays, partner.frame),
        (own.record, own.arrays, own.frame),
        ("iliotibial_band",),
        product="iliotibial_band",
    )
    partner.record["assignments"]["codes"]["iliotibial_band"] = (
        laid["iliotibial_band"] or "abstain_outside_partner_picture"
    )


def semimembranosus_slice(
    own: Measured, leg: Leg | None
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The semimembranosus tendon's slice of one series, read (its paragraph in
    `knee.objects.assignments`): the slice through the top of the tibia, just below the joint
    line, found by carrying the study's leg onto each slice of the series (no lens; `leg_on`, each
    slice's once), where the lens is then read once more; the tendon named at the tibia's
    back-inner corner; or why it was not read."""
    assigned = own.record["assignments"]
    knee = assigned["knee"]
    reads("naming", ("in_plane",), "semimembranosus")
    code = semimembranosus_code(
        not own.assignment.in_plane[2], knee, True, True, True, True, True
    )
    if code != "identified" or leg is None:
        return code
    reads("leg", ("tibia_lps", "notch_origin_lps"), "semimembranosus")
    if not len(leg.tibia_lps) or leg.notch_origin_lps is None:
        return semimembranosus_code(
            True, knee, bool(len(leg.tibia_lps)), False, False, False, False
        )
    reads("series", ("volume", "geometry", "slice_thickness_mm"), "semimembranosus")
    volume, thicknesses = own.series.volume, own.series.slice_thickness_mm
    if volume is None:
        return "no_stacked_volume"
    femur_held, tibia_held, up_mm = [], [], []
    for z in range(len(volume)):
        frame, thickness = plane_frame(own.series, z), thicknesses[z]
        shape = np.asarray(volume[z]).shape
        held = [False, False]
        if not isinstance(frame, str) and thickness is not None:
            held = [
                bool(places.any())
                for places in leg_on(leg, own.series, z, frame, shape, thickness)
            ]
        femur_held.append(held[0])
        tibia_held.append(held[1])
        up_mm.append(0.0 if isinstance(frame, str) else float(frame.origin_lps[2]))
    z = tibia_top_slice(femur_held, tibia_held, up_mm)
    frame = None if z is None else plane_frame(own.series, z)
    if z is None or frame is None or isinstance(frame, str):
        return semimembranosus_code(True, knee, True, True, False, False, False)
    reads("background", ("split",), "semimembranosus")
    record, arrays, field = read_part_slice(
        own.series,
        z,
        volume[z],
        frame,
        own.record["background_split"],
        knee,
        "semimembranosus",
    )
    labels, plane = arrays["b1_labels"], arrays["acquired_plane"]
    uid = own.series.row.series_uid
    carried = carry_onto(
        leg, own.series, z, frame, labels.shape, float(thicknesses[z] or 0.0)
    )
    reads("carried", ("femur", "tibia", "back_mm", "toward_left_mm"), "semimembranosus")
    reads("field", ("peaks", "objects"), "semimembranosus")
    toward_left = carried.toward_left_mm
    condyle = tendon = None
    semitendinosus = np.zeros(labels.shape, dtype=bool)
    st_code = "abstain_no_semimembranosus_reference"
    gracilis = np.zeros(labels.shape, dtype=bool)
    gr_code = "abstain_no_semimembranosus_reference"
    if toward_left is not None:
        # the inner side is toward the other knee: the patient's left for a right knee
        inner_mm = toward_left if knee == "R" else -toward_left
        condyle = inner_condyle(
            field.peaks, labels, carried.femur | carried.tibia, inner_mm
        )
        if condyle is not None:
            spacing = np.asarray(frame.spacing_rc)
            shared = measures_of(uid, z, plane, frame)
            reads("interiors", ("dark",), "hamstring_bodies")
            reads("carried", ("back_mm", "toward_left_mm"), "hamstring_bodies")
            bodies = dark_tendon_bodies(
                arrays["b1_dark"],
                # the places neither the air, the skin nor the black margin hold
                (field.objects == 0) & ~margin_of(uid, z, plane),
                spacing,
                carried.back_mm,
                inner_mm,
            )
            handed("hamstring_bodies", field_names(bodies))
            arrays["a2_dark_tendon_candidates"] = bodies.labels
            arrays["a2_dark_tendon_back_mm"] = bodies.back_mm
            arrays["a2_dark_tendon_inner_mm"] = bodies.inner_mm
            reads("hamstring_bodies", field_names(bodies), "semimembranosus")
            tendon = semimembranosus_on_slice(
                bodies,
                labels == condyle.territory,
                condyle,
                carried.back_mm,
                inner_mm,
                spacing,
                shared,
            )
            reads("hamstring_bodies", field_names(bodies), "semitendinosus")
            reads("semimembranosus", ("region",), "semitendinosus")
            reads("carried", ("back_mm", "toward_left_mm"), "semitendinosus")
            reads("field", ("peaks",), "semitendinosus")
            semitendinosus, st_code = semitendinosus_on_slice(
                bodies, tendon, condyle, carried.back_mm, inner_mm, spacing, shared
            )
            if tendon.any() and semitendinosus.any():
                reads("interiors", ("dark",), "native_hamstring_bodies")
                reads(
                    "carried", ("back_mm", "toward_left_mm"), "native_hamstring_bodies"
                )
                native_bodies = native_dark_bodies(
                    arrays["b1_dark"],
                    (field.objects == 0) & ~margin_of(uid, z, plane),
                    carried.back_mm,
                    inner_mm,
                )
                handed("native_hamstring_bodies", field_names(native_bodies))
                reads("native_hamstring_bodies", field_names(native_bodies), "gracilis")
                reads("semimembranosus", ("region",), "gracilis")
                reads("semitendinosus", ("region",), "gracilis")
                gracilis, gr_readings, gr_code = gracilis_on_slice(
                    native_bodies,
                    tendon,
                    semitendinosus,
                    carried.back_mm,
                    inner_mm,
                    spacing,
                    knee,
                    shared,
                )
                for name, value in gr_readings.items():
                    arrays[f"a2_gracilis_{name}"] = value
            elif tendon.any():
                gr_code = "abstain_no_semitendinosus_reference"
    arrays["a2_gracilis"] = gracilis
    record["assignments"]["codes"]["gracilis"] = gr_code
    if gr_code == "identified":
        handed("gracilis", ("region",))
    arrays["a2_semitendinosus"] = semitendinosus
    record["assignments"]["codes"]["semitendinosus"] = st_code
    if st_code == "identified":
        handed("semitendinosus", ("region",))
    # The tendons share this slice; the middle slice keeps its own tissue names.
    objects = np.zeros(labels.shape, dtype=np.int8)
    if tendon is not None:
        objects[tendon] = OBJECT_CODES["semimembranosus"]
    arrays["a1_objects"] = objects
    record["assignments"]["codes"]["semimembranosus"] = semimembranosus_code(
        True, knee, True, True, True, condyle is not None, bool(objects.any())
    )
    # The bursa reads this same slice and its already carried leg; no lens is read again.
    bright = (
        int(own.series.row.fat_suppression) == 1
        and int(own.series.row.fluid_sensitive) == 1
    )
    posterior = np.zeros(labels.shape, dtype=bool)
    bursal = np.zeros(labels.shape, dtype=bool)
    if (
        bright
        and tendon is not None
        and tendon.any()
        and condyle is not None
        and toward_left is not None
    ):
        posterior = gastrocnemius_head(
            field.peaks,
            labels,
            carried.femur | carried.tibia,
            condyle,
            carried.back_mm,
            inner_mm,
        )
        shared = measures_of(uid, z, plane, frame)
        marrow = shared.light(carried.femur | carried.tibia)
        white = (
            (plane > FLUID_BRIGHTER * marrow)
            if marrow > 0
            else np.zeros(labels.shape, dtype=bool)
        )
        arrays["a2_fluid_signal"] = white
        handed("bursal_fluid", ("white",))
        reads("bursal_fluid", ("white",), "bursa")
        reads("carried", ("back_mm", "toward_left_mm"), "bursa")
        bursal = bursa_on_slice(
            white,
            tendon,
            posterior,
            carried.back_mm,
            inner_mm,
            np.asarray(frame.spacing_rc),
            shared,
        )
    arrays["a2_gastrocnemius_semimembranosus_bursa"] = bursal
    if bursal.any():
        handed("bursa", ("region",))
    record["assignments"]["codes"]["gastrocnemius_semimembranosus_bursa"] = bursa_code(
        bright,
        tendon is not None and bool(tendon.any()),
        bool(posterior.any()),
        bool(bursal.any()),
    )
    record["main_slice"] = {"object": "semimembranosus"}
    return record, arrays, frame


# What the sartorius rule reads of its own readings, and what it keeps without reading.
SARTORIUS_READ = (
    "gracilis_target",
    "smooth",
    "surround",
    "lightness",
    "grey_bodies",
    "body_inner_mm",
    "body_back_mm",
    "body_size_pixels",
    "eligible_ids",
    "target_distance_mm",
    "eligible_reach_mm",
)
SARTORIUS_KEPT = (
    "gracilis_source_lps",
    "surround_window_pixels",
    "gracilis_source_separation_mm",
    "body_status",
    "contrast_scope_window_rc",
    "contrast_scope_offset_rc",
    "contrast_scope_shape_rc",
    "contrast_scope_clipped",
    "contrast_scope_half_span_pixels_rc",
    "contrast_scope_target_bbox_rc",
    "contrast_query_window",
    "contrast_effective_available",
    "contrast_context_rc",
    "contrast_halo_pixels_rc",
    "contrast_context_raw",
    "contrast_context_excluded",
    "contrast_context_available",
    "contrast_context_not_low",
    "contrast_context_finite",
    "contrast_context_effective_available",
    "contrast_context_lightness",
    "contrast_context_smooth",
    "contrast_context_surround",
    "contrast_input_finite",
    "contrast_finite",
    "contrast_actual_available",
    "contrast_not_low",
)


def gracilis_source(
    measured: list[Measured], found: list[tuple[dict, dict[str, np.ndarray]]]
) -> np.ndarray | str:
    """The gracilis's places in the scanner's millimetres, put there once from the first of the
    study's semimembranosus-group records (`find_part`, the ones that name the tendon) whose
    gracilis its own lens named (`identified`, not one laid from a partner), through the frame of
    the slice it was named on (`plane_frame`); or why there are none. Handed on to every middle
    axial's sartorius, which projects them (`name_sartorius`): they are a location there, not a
    mask."""
    for record, arrays in found:
        if record["assignments"]["codes"].get("gracilis") != "identified":
            continue
        reads("gracilis", ("region",), "gracilis_places")
        places = np.argwhere(arrays["a2_gracilis"])
        if not len(places):
            continue
        series = next(
            m.series for m in measured if m.record["series_uid"] == record["series_uid"]
        )
        frame = plane_frame(series, record["slice_index"])
        if isinstance(frame, str):
            return "abstain_gracilis_source_geometry_unreadable"
        handed("gracilis_places", ("lps",))
        return frame.to_patient(places.astype(float))
    return "abstain_no_native_gracilis"


def sartorius_scope(target: np.ndarray, frame, shape: tuple[int, int]) -> dict | None:
    """The sartorius search window around the projected gracilis target: the authored full
    extent plus `GRACILIS_REACH_MM` on each side, handed to `source_window` as a full span
    (the target is a location, not the object's centre). None when there is no target."""
    if not target.any():
        return None
    span = anatomy_map.target_span_mm("sartorius")
    if span is None:
        return {"status": "no_authored_sartorius_span"}
    full = (
        2.0 * (float(span[0]) + GRACILIS_REACH_MM),
        2.0 * (float(span[1]) + GRACILIS_REACH_MM),
        2.0 * (float(span[2]) + GRACILIS_REACH_MM),
    )
    return source_window(
        np.argwhere(target).astype(np.float64),
        full,
        frame,
        (int(shape[0]), int(shape[1])),
    )


def name_sartorius(own: Measured, source: np.ndarray | str) -> None:
    """The sartorius named on this series' middle slice where the leg does not run in its plane, an
    axial one, fat-suppressed and fluid-sensitive (its paragraph in `knee.objects.assignments`),
    from the lens already read there and the gracilis's places (`gracilis_source`, `source`, or why
    there are none) projected onto it. Its mask is separate (`a2_sartorius`) and every reading the
    rule made is kept beside it (`a2_sartorius_<reading>`); the slice's own names are left as they
    are. The places are projected once and a search window around them (the authored extent plus
    the gracilis reach) is built from that target before any contrast is read; the contrast is
    then read at most once, only inside that window and the context it needs, and only once the
    cheap prerequisites hold; no lens is read again."""
    plane = own.arrays["acquired_plane"]
    own.arrays["a2_sartorius"] = np.zeros(plane.shape, dtype=bool)
    codes = own.record["assignments"]["codes"]
    reads("naming", ("in_plane",), "sartorius")
    reads("series", ("row",), "sartorius")
    if own.assignment.in_plane[2]:
        codes["sartorius"] = "abstain_leg_runs_in_the_plane"
        return
    if not (
        int(own.series.row.fat_suppression) == 1
        and int(own.series.row.fluid_sensitive) == 1
    ):
        codes["sartorius"] = "abstain_requires_fluid_sensitive_fat_suppression"
        return
    if isinstance(source, str):
        codes["sartorius"] = source
        return
    uid, index = own.record["series_uid"], own.record["slice_index"]
    reads("interiors", ("dark", "available"), "sartorius")
    reads("gracilis_places", ("lps",), "sartorius")
    places = np.asarray(source, dtype=np.float64)
    target = scope = None
    if places.size:
        target = projected_places(places, own.frame, plane.shape)  # once
        scope = sartorius_scope(target, own.frame, plane.shape)
    mask, readings, code = sartorius_on_slice(
        plane,
        own.arrays["b1_dark"],
        ~own.arrays["b1_available"] | margin_of(uid, index, plane),
        source,
        own.frame,
        own.record["assignments"]["knee"],
        measures_of(uid, index, plane, own.frame),
        target,
        scope,
        own.arrays["b1_available"],
    )
    own.arrays["a2_sartorius"] = mask
    for name, value in readings.items():
        own.arrays[f"a2_sartorius_{name}"] = value
    codes["sartorius"] = code
    made = [name for name in (*SARTORIUS_READ, *SARTORIUS_KEPT) if name in readings]
    handed("sartorius_readings", made)
    reads(
        "sartorius_readings",
        [name for name in made if name in SARTORIUS_READ],
        "sartorius",
    )
    if "lightness" in readings:
        ledger.record("sartorius.contrast_readings", planes=1)
    if "contrast_context_raw" in readings:
        ledger.record(
            "sartorius.contrast_scope_work",
            context_pixels=int(readings["contrast_context_raw"].size),
            query_pixels=int(readings["contrast_query_window"].sum()),
            effective_pixels=int(readings["contrast_effective_available"].sum()),
        )
    if code == "identified":
        handed("sartorius", ("region",))


def retinacula_z(
    own: Measured, leg: Leg | None, patella_centre: np.ndarray | None
) -> tuple[int, list[float], str] | str:
    """The axial slice through the already named patella (the retinacula's bootstrap), its slices'
    thicknesses and the knee's side, or why this series has none: the one statement of the selection,
    read by the retinacula stage and by the recess family's extra planes alike."""
    reads("naming", ("in_plane",), "patellar_retinacula")
    reads("series", ("row",), "patellar_retinacula")
    if own.assignment.in_plane[2]:
        return "abstain_leg_runs_in_the_plane"
    knee = own.record["assignments"]["knee"]
    if knee not in ("R", "L"):
        return "abstain_header_names_no_knee"
    if not (
        int(own.series.row.fat_suppression) == 1
        and int(own.series.row.fluid_sensitive) == 1
    ):
        return "abstain_requires_fluid_sensitive_fat_suppression"
    if leg is None:
        return "abstain_no_bone_carried"
    if patella_centre is None:
        return "abstain_no_patella_carried"
    if not len(leg.femur_lps):
        return "abstain_no_femur_carried"
    reads("patella", ("centre_lps",), "patellar_retinacula")
    reads("leg", ("femur_lps", "patella_lps"), "patellar_retinacula")
    reads("series", ("volume", "geometry", "slice_thickness_mm"), "patellar_retinacula")
    volume, geometry = own.series.volume, own.series.geometry
    if volume is None or geometry is None:
        return "abstain_no_readable_series"
    thicknesses = own.series.slice_thickness_mm
    if any(t is None for t in thicknesses):
        return "abstain_no_slice_thickness"
    thickness_values = [float(t) for t in thicknesses if t is not None]
    z = slice_through(
        patella_centre, geometry.position, own.frame.normal(), thickness_values
    )
    if z is None:
        return "abstain_patella_off_the_slices"
    return z, thickness_values, str(knee)


def retinacula_slice(
    own: Measured, leg: Leg | None, patella_centre: np.ndarray | None
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The axial slice through the already named patella, read once for both retinacula."""
    chosen = retinacula_z(own, leg, patella_centre)
    if isinstance(chosen, str) or leg is None:
        return chosen if isinstance(chosen, str) else "abstain_no_bone_carried"
    z, thickness_values, knee = chosen
    return retinacula_on(own, leg, z, thickness_values, knee, "patellar_retinacula")


def retinacula_on(
    own: Measured,
    leg: Leg,
    z: int,
    thickness_values: list[float],
    knee: str,
    reader: str,
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The existing retinacula rule (`retinacular_walls`) on ONE axial slice `z` of a series: its
    lens and field (once per slice, so a plane another family read is handed on), the carried femur
    and patella on it, the white the fluid-to-marrow relation reads, and both walls with their
    decisions. `reader` is the stage whose lens readings the ledger counts."""
    volume = own.series.volume
    if volume is None:
        return "abstain_no_readable_series"
    frame = plane_frame(own.series, z)
    if isinstance(frame, str):
        return frame
    reads("background", ("split",), "patellar_retinacula")
    record, arrays, field = read_part_slice(
        own.series,
        z,
        volume[z],
        frame,
        own.record["background_split"],
        knee,
        reader,
    )
    reads("interiors", ("labels", "available"), "patellar_retinacula")
    reads("field", ("peaks", "objects"), "patellar_retinacula")
    plane = arrays["acquired_plane"]
    femur, _ = leg_on(leg, own.series, z, frame, plane.shape, thickness_values[z])
    patella = places_on_slice(leg.patella_lps, frame, plane.shape, thickness_values[z])
    available = (
        arrays["b1_available"]
        & (field.objects == 0)
        & ~margin_of(own.record["series_uid"], z, plane)
    )
    shared = measures_of(own.record["series_uid"], z, plane, frame)
    marrow_places = femur & available
    light = shared.light(marrow_places) if marrow_places.any() else 0.0
    white = (
        (plane > FLUID_BRIGHTER * light) & available
        if light > 0
        else np.zeros(plane.shape, bool)
    )
    handed("retinacular_fluid", ("white",))
    reads("retinacular_fluid", ("white",), "patellar_retinacula")
    back, side = shared.along(1), shared.along(0)
    inner = side if knee == "R" else -side
    readings, codes = retinacular_walls(
        plane,
        white,
        arrays["b1_labels"],
        field.peaks,
        patella,
        femur,
        frame.basis_lps,
        back,
        inner,
        np.asarray(frame.spacing_rc),
        available,
        shared,
    )
    handed("axial_lining", ("medial_edge", "lateral_edge"))
    arrays["a2_retinacula_carried_patella"] = patella
    arrays["a2_retinacula_carried_femur"] = femur
    arrays["a2_retinacula_field_objects"] = field.objects
    for name, value in readings.items():
        arrays[f"a2_{name}"] = value
    # This record names the two walls; the field's air/skin remain retained as readings above.
    arrays["a1_objects"] = np.zeros(plane.shape, dtype=np.int8)
    record["assignments"]["codes"].update(codes)
    record["assignments"]["codes"]["patellar_retinacula"] = (
        "identified"
        if any(code in NAMED for code in codes.values())
        else "abstain_no_retinacular_wall"
    )
    record["main_slice"] = {"object": "patellar_retinacula"}
    return record, arrays, frame


@dataclass(frozen=True)
class FibulaProfile:
    """The fibula's cheap profile through depth, one entry per slice of the series, stack order:
    the pointer's status (`FIBULA_POINTER_STATUS`), the area in square millimetres of the largest
    whole body that could be the fibula (0.0 where measured absent, NaN where it is not read, not
    readable or cut), that body's middle in the scanner's millimetres (NaN where none) and how many
    bodies could be it; the corridor's squint tiles and those of them that could hold marrow-like
    light (the extrema over every tile a finer block with a pixel in the tile can touch do not
    exclude it); the native window the finer reading ran over (-1 where none) and the block's size
    in millimetres (NaN where none) and in native pixels (-1 where none); the finer readings
    themselves, one per slice read (`fine`: the block medians and the pointer's body and tibia
    reference bodies on that block grid, at their own small resolution); and what it was read
    against: the tibia's marrow light on the middle slice, the tibia's top and its middle in the
    scanner's millimetres."""

    status: np.ndarray
    area_mm2: np.ndarray
    centroid_lps: np.ndarray
    candidates: np.ndarray
    corridor: np.ndarray
    could: np.ndarray
    window_rc: np.ndarray
    cell_mm: np.ndarray
    block_px: np.ndarray
    fine: tuple[FineReading, ...]
    light: float
    top_mm: float
    middle_lps: np.ndarray


def fibula_profile(
    series: Series,
    stack: SquintStack,
    tibia: np.ndarray,
    middle_rc: tuple[int, int],
    light: float,
    top_mm: float,
    middle_lps: np.ndarray,
    knee: str,
    visit: np.ndarray | None = None,
) -> FibulaProfile:
    """The fibula's cheap profile through the series' depth: where each visited slice's corridor holds a body
    that could be the fibula (`fibula_pointer`), read without the lens.

    On each slice the corridor's squint tiles (`fibula_corridor`: the tibia's outer back, below its
    top) are first asked, by their minimum and maximum, whether any could hold a block as bright as
    the tibia's marrow. A block's median is taken over its footprint, which can cross into the next
    tile, so a tile is asked over every tile a block with a pixel in it can touch
    (`footprint_reach`, `could_hold_level_in_reach`, the block's size from the slice's own pixel
    pitch), never over its own extrema alone: where none can and no tile in reach was unseen, the
    corridor holds no marrow-like body (measured absent, 0.0); where none can but a tile in reach was
    not seen, nothing is said (NaN). Otherwise the finer reading runs over the window of the tiles that could,
    with `BONE_MM` of context round them so that the tibia's reference body and a whole body lie in
    it (`block_medians` at `LIGAMENT_SMOOTH_MM`, the length over which the light is read as uniform
    and not speckled), and the pointer reads that, with the tibia's carried places and its middle
    (`middle_rc`, the deepest peak of its territory on the middle slice) as its two anchors. A slice whose corridor is empty is not read: it
    lies wholly off the corridor, which says nothing of the fibula and is not zero either. The
    unseen places of a slice (`seen_native`) are NaN in the blocks, never darkness. The counts of
    slices read finely and excluded by the tiles are on the ledger (`fibula.cheap_readings`,
    `fibula.tile_exclusions`)."""
    reads("squint_stack", ("minimum", "maximum", "centres_lps", "bounds_rc"), "fibula")
    depth = int(stack.median.shape[0])
    tiles = stack.median.shape[1:]
    status = np.full(depth, FIBULA_POINTER_STATUS["not_read"], dtype=np.int8)
    area = np.full(depth, np.nan)
    centroid = np.full((depth, 3), np.nan)
    candidates = np.zeros(depth, dtype=np.int32)
    corridor = np.zeros((depth, *tiles), dtype=bool)
    could = np.zeros((depth, *tiles), dtype=bool)
    window_rc = np.full((depth, 4), -1, dtype=np.int32)
    cell_mm = np.full((depth, 2), np.nan)
    cell_px = np.full((depth, 2), -1, dtype=np.int32)
    fine: list[FineReading] = []
    reach_of: dict[tuple[int, int], Any] = {}
    low, high = LIKE_THE_TIBIA
    finely = excluded = 0
    middle = np.zeros(tibia.shape, dtype=bool)
    middle[middle_rc] = True
    # a marrow light that is not a positive finite number is no anchor to ask the tiles against: a
    # comparison with it is false for every tile, which would read as an exclusion, so no corridor
    # slice is excluded or read on it
    anchored = bool(np.isfinite(light) and light > 0)
    for z in range(depth):
        if visit is not None and not visit[z]:
            continue
        corridor[z] = fibula_corridor(stack.centres_lps[z], top_mm, middle_lps, knee)
        if not corridor[z].any():
            continue
        frame = plane_frame(series, z)
        if isinstance(frame, str) or not anchored:
            status[z] = FIBULA_POINTER_STATUS["unreadable"]
            continue
        # a block is read over its footprint, which crosses tile boundaries: ask over every tile
        # a block with a pixel in the corridor's tile can touch, never over the tile alone
        block = block_pixels(frame.spacing_rc, LIGAMENT_SMOOTH_MM)
        if block not in reach_of:
            reach_of[block] = footprint_reach(stack.bounds_rc, block)
        possible, unseen_tiles = could_hold_level_in_reach(
            stack.minimum[z],
            stack.maximum[z],
            low * light,
            high * light,
            reach_of[block],
        )
        could[z] = corridor[z] & possible
        if not could[z].any():
            if (corridor[z] & unseen_tiles).any():
                status[z] = FIBULA_POINTER_STATUS["unreadable"]
            else:
                status[z], area[z] = FIBULA_POINTER_STATUS["none"], 0.0
                excluded += 1
            continue
        plane, unseen = seen_native(series, z, "fibula")
        rows, cols = plane.shape
        spacing = np.asarray(frame.spacing_rc)
        bounds = stack.bounds_rc[could[z]]
        reach = np.ceil(BONE_MM / spacing).astype(int)
        window = (
            max(0, int(bounds[:, 0].min()) - int(reach[0])),
            min(rows, int(bounds[:, 1].max()) + int(reach[0])),
            max(0, int(bounds[:, 2].min()) - int(reach[1])),
            min(cols, int(bounds[:, 3].max()) + int(reach[1])),
        )
        reading = block_medians(
            plane, unseen, frame.spacing_rc, LIGAMENT_SMOOTH_MM, window
        )
        centres = frame.to_patient(block_centres_rc(reading).reshape(-1, 2)).reshape(
            *reading.median.shape, 3
        )
        cut = np.zeros(reading.median.shape, dtype=bool)
        cut[0, :] = window[0] > 0
        cut[-1, :] = window[1] < rows
        cut[:, 0] = window[2] > 0
        cut[:, -1] = window[3] < cols
        point = fibula_pointer(
            reading.median,
            np.asarray(reading.block_mm),
            centres,
            block_holds(tibia, reading),
            block_holds(middle, reading),
            light,
            top_mm,
            middle_lps,
            knee,
            cut,
        )
        finely += 1
        status[z], area[z], centroid[z] = (
            point.status,
            point.area_mm2,
            point.centroid_lps,
        )
        candidates[z] = point.candidates
        window_rc[z], cell_mm[z], cell_px[z] = (
            window,
            reading.block_mm,
            reading.block_px,
        )
        # kept as made, at its own small resolution: the block medians and the bodies drawn on them
        fine.append(
            FineReading(
                z,
                reading.window_rc,
                reading.block_px,
                reading.block_mm,
                reading.median,
                point.body,
                point.tibia,
            )
        )
    ledger.record("fibula.cheap_readings", planes=finely)
    ledger.record("fibula.tile_exclusions", planes=excluded)
    handed("fibula_profile", ("status", "area_mm2"))
    # kept, not read: no stage after the pointer reads the blocks or the bodies it drew
    handed("fibula_profile", ("fine",))
    return FibulaProfile(
        status,
        area,
        centroid,
        candidates,
        corridor,
        could,
        window_rc,
        cell_mm,
        cell_px,
        tuple(fine),
        float(light),
        float(top_mm),
        np.asarray(middle_lps, dtype=np.float64),
    )


def finite_or_none(value: float) -> float | None:
    """A measured number, or None where it is NaN: an unknown is never written as a value."""
    return float(value) if np.isfinite(value) else None


def fibula_support(
    series: Series,
    middle: PlaneFrame,
    frame: PlaneFrame,
    main_z: int,
    profile: FibulaProfile,
    pointed: tuple[list[tuple[int, int]], list[np.ndarray], list[int]],
    planes: list[int],
    accepted: tuple[int, ...],
    places: np.ndarray | None,
    marrow: float,
    knee: str,
) -> tuple[dict, dict[str, np.ndarray], list[str]]:
    """The fibula's support through depth, as measured: its record, its arrays and what is not known.

    Three things are kept apart. The RAW POINTER SUPPORT is the profile's runs (`fibula_profile`,
    `positive_runs`), a cheap marrow-like body through depth; each run says what the established
    rule (`planes` it was read on, `accepted` those it identified the fibula on) made of the planes
    read for it: confirmed, rejected or not read. The CONFIRMED EXTENT is only what a native reading
    holds: the slices the rule identified it on, the confirmed pointer runs, and the head's outward
    continuation from the selected slice (`lateral_to_the_head`, the biceps femoris tendon's walk, made
    once for both: `head_walk`), a walk that stays connected to the identified slice. A pointer run the
    rule rejected on every plane read for it is not the bone's extent; it is a named unresolved
    candidate range (`unresolved_candidate_ranges`) with its envelope, and in the confirmed
    support's status it is `UNCONFIRMED_CANDIDATE`, neither body nor measured absent. The head's body
    on each slice it walked is kept, with its target, even where the biceps femoris tendon later
    abstains.

    The runs are given in the scanner's millimetres along the series' normal from the selected slice
    (`depth_offsets_mm`) as ENVELOPES over the sampled slabs (`support_intervals_mm`), never dense
    occupancy: each run keeps its sampled slabs and the gaps between them (`run_slabs_mm`,
    `slab_gaps_mm`), nothing interpolated, and for each end what it touches (`run_neighbours`: the
    scan's edge, a slice measured empty, a slice not read or not readable). A slice the profile
    could not read and the head did not settle is named unknown, never empty, and not read is never
    measured empty. The corridor it was read in, the frame it was measured from and the profile's
    finer readings at their own small resolution (`pack_fine_readings`, ragged, with each slice's
    window, block size and shape) are kept. Support is not a segmentation and joins no slices the
    readings did not."""
    runs, maxima, confirm = pointed
    depth = len(profile.status)
    reads("series", ("geometry", "slice_thickness_mm"), "fibula")
    origins = np.asarray(
        [np.asarray(p, dtype=float) for p in series.geometry.position]
        if series.geometry is not None
        else [],
        dtype=float,
    )
    known = [None if t is None else float(t) for t in series.slice_thickness_mm]
    thick = np.asarray([np.nan if t is None else t for t in known], dtype=float)
    sound = (
        origins.ndim == 2
        and origins.shape == (depth, 3)
        and bool(np.all(np.isfinite(origins)))
        and len(thick) == depth
    )
    normal = middle.normal()
    offsets = (
        depth_offsets_mm(origins, normal, main_z) if sound else np.full(depth, np.nan)
    )
    head_area = np.full(depth, np.nan)
    head_status = np.zeros(depth, dtype=np.int8)
    walk_code, face = "abstain_no_front_to_back_places", None
    walk: HeadWalk | None = None
    if places is not None and sound:
        walk = head_walk(series, places, knee, origins, normal, known, lambda: marrow)
        reads("head_walk", ("areas", "status"), "fibula")
        face, head_area, head_status, walk_code = (
            walk.face,
            walk.areas,
            walk.status,
            walk.code,
        )
    ledger.record("fibula.head_readings", planes=int(np.isfinite(head_area).sum()))
    # what the established rule made of the planes read for each pointer run
    read_planes, identified = set(planes), {int(z) for z in accepted}
    run_planes: list[list[int]] = []
    confirmation = np.zeros(len(runs), dtype=np.int8)
    for i, ((start, stop), peaks) in enumerate(zip(runs, maxima, strict=True)):
        here = sorted(
            {int(z) for z in peaks}
            | {int(z) for z in confirm if z in (start - 1, stop)}
        )
        run_planes.append(here)
        if any(z in identified for z in here):
            confirmation[i] = RUN_CONFIRMATION["confirmed_by_the_native_rule"]
        elif any(z in read_planes for z in here):
            confirmation[i] = RUN_CONFIRMATION["rejected_by_the_native_rule"]
        else:
            confirmation[i] = RUN_CONFIRMATION["not_read_natively"]
    confirmed_code = RUN_CONFIRMATION["confirmed_by_the_native_rule"]
    names_of = {value: key for key, value in RUN_CONFIRMATION.items()}
    combined = profile.status.copy()
    for (start, stop), code in zip(runs, confirmation, strict=True):
        if code != confirmed_code:
            combined[start:stop] = UNCONFIRMED_CANDIDATE
    combined[head_status == HEAD_SLICE_STATUS["head_still_a_disc"]] = (
        FIBULA_POINTER_STATUS["body"]
    )
    combined[head_status == HEAD_SLICE_STATUS["head_no_longer_a_disc"]] = (
        FIBULA_POINTER_STATUS["none"]
    )
    # a plane the established rule identified the fibula on is native support, whatever else says
    native = np.asarray(sorted(identified), dtype=np.int32)
    contradicted = native[
        head_status[native] == HEAD_SLICE_STATUS["head_no_longer_a_disc"]
    ]
    combined[native] = FIBULA_POINTER_STATUS["body"]
    held = (combined == FIBULA_POINTER_STATUS["body"]).astype(float)
    extent = positive_runs(held)
    ends = run_neighbours(extent, combined)
    pointer_ends = run_neighbours(runs, profile.status)
    intervals = (
        support_intervals_mm(offsets, thick, extent)
        if sound
        else np.full((len(extent), 2), np.nan)
    )
    pointer_intervals = (
        support_intervals_mm(offsets, thick, runs)
        if sound
        else np.full((len(runs), 2), np.nan)
    )
    slab = np.column_stack((offsets - thick / 2.0, offsets + thick / 2.0))
    unresolved = (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"])
    unknown = [int(z) for z in np.flatnonzero(np.isin(combined, unresolved))]
    ambiguities = ["only_the_pointed_planes_are_resolved_the_rest_is_support"]
    if len(extent) > 1:
        ambiguities.append("support_is_disjoint")
    if unknown:
        ambiguities.append("slices_the_profile_could_not_read_are_unknown_not_empty")
    if confirm:
        ambiguities.append(
            "a_maximum_beside_a_cut_body_was_read_whole_on_the_full_slice"
        )
    if confirmations(
        runs, maxima, profile.status, (FIBULA_POINTER_STATUS["unreadable"],)
    ):
        # nothing can tell a larger body there from the tibia's own place: named, not confirmed
        ambiguities.append(
            "a_maximum_lies_beside_an_unreadable_slice_a_larger_body_is_not_ruled_out"
        )
    if places is None:
        ambiguities.append("front_to_back_is_not_in_plane_so_no_head_continuation")
    disagree = np.flatnonzero(
        (profile.status == FIBULA_POINTER_STATUS["none"])
        & (head_status == HEAD_SLICE_STATUS["head_still_a_disc"])
    )
    if disagree.size:
        ambiguities.append("the_pointer_and_the_head_disagree")
    if contradicted.size:
        ambiguities.append("the_native_rule_and_the_head_disagree")
    if (confirmation == RUN_CONFIRMATION["rejected_by_the_native_rule"]).any():
        ambiguities.append(
            "a_pointer_run_the_native_rule_rejected_is_not_confirmed_extent"
        )
    if (confirmation == RUN_CONFIRMATION["not_read_natively"]).any():
        ambiguities.append("a_pointer_run_not_read_natively_is_not_confirmed_extent")

    def described(spans, neighbours, spans_mm):
        found = []
        for (a, b), end, (lo, hi) in zip(spans, neighbours, spans_mm, strict=True):
            order = (
                np.argsort(offsets[a:b], kind="stable") if sound else np.arange(b - a)
            )
            slabs = (
                run_slabs_mm(offsets, thick, [(a, b)])[0] if sound else np.empty((0, 2))
            )
            found.append(
                {
                    "slices": [int(a), int(b) - 1],
                    "envelope_mm": [finite_or_none(lo), finite_or_none(hi)],
                    "sampled_slices": [int(a + i) for i in order],
                    "slabs_mm": [[finite_or_none(v) for v in row] for row in slabs],
                    "gaps_mm": [
                        finite_or_none(v)
                        for v in (slab_gaps_mm(slabs) if len(slabs) else [])
                    ],
                    "occupancy": "envelope_over_the_sampled_slabs_never_dense",
                    "ends": [RUN_END_NAMES[int(e)] for e in end],
                }
            )
        return found

    raw = described(runs, pointer_ends, pointer_intervals)
    for entry, here, code in zip(raw, run_planes, confirmation, strict=True):
        entry["planes_read_for_it"] = here
        entry["native_rule"] = names_of[int(code)]
    candidates = []
    for i, ((a, b), entry) in enumerate(zip(runs, raw, strict=True)):
        if confirmation[i] != confirmed_code:
            candidates.append(
                {
                    **entry,
                    "why": entry["native_rule"],
                    "pointer_area_mm2_greatest": float(
                        np.nanmax(profile.area_mm2[a:b])
                    ),
                }
            )
    support = {
        "source": {
            "series_uid": series.row.series_uid,
            "selected_slice": int(main_z),
            "normal": [float(v) for v in normal],
            "frame_origin_lps": [float(v) for v in frame.origin_lps],
        },
        "corridor": {
            "tibia_light": float(profile.light),
            "tibia_top_mm": float(profile.top_mm),
            "tibia_middle_lps": [float(v) for v in profile.middle_lps],
            "side": knee,
            "below_the_tibias_top_mm": float(FIBULA_BELOW_MM),
            "behind_the_tibias_middle": True,
            "block_mm": float(LIGAMENT_SMOOTH_MM),
            "context_mm": float(BONE_MM),
        },
        "pointer_runs": raw,
        "pointer_representatives": [[int(z) for z in peaks] for peaks in maxima],
        "native_resolved_slices": [int(z) for z in native],
        "head": {
            "walk": walk_code,
            "face_slice": None if face is None else int(face),
            "slices": [
                int(z)
                for z in np.flatnonzero(
                    head_status == HEAD_SLICE_STATUS["head_still_a_disc"]
                )
            ],
            "walked": [] if walk is None else [int(z) for z in walk.walked],
            "codes": {}
            if walk is None
            else {
                str(z): head[2] for z, head in zip(walk.walked, walk.heads, strict=True)
            },
        },
        "confirmed_extent": described(extent, ends, intervals),
        "unresolved_candidate_ranges": candidates,
        "unknown_slices": unknown,
    }
    walked = () if walk is None else walk.walked
    arrays: dict[str, np.ndarray] = {
        "a3_fibula_profile_status": profile.status,
        "a3_fibula_profile_area_mm2": profile.area_mm2,
        "a3_fibula_profile_centroid_lps": profile.centroid_lps,
        "a3_fibula_profile_candidates": profile.candidates,
        "a3_fibula_profile_corridor_tiles": profile.corridor,
        "a3_fibula_profile_could_tiles": profile.could,
        "a3_fibula_profile_window_rc": profile.window_rc,
        "a3_fibula_profile_block_mm": profile.cell_mm,
        "a3_fibula_profile_block_px": profile.block_px,
        "a3_fibula_reference_light": np.asarray(profile.light, dtype=np.float64),
        "a3_fibula_reference_top_mm": np.asarray(profile.top_mm, dtype=np.float64),
        "a3_fibula_reference_middle_lps": profile.middle_lps,
        "a3_fibula_pointer_runs": np.asarray(runs, dtype=np.int32).reshape(-1, 2),
        "a3_fibula_pointer_run_ends": pointer_ends.astype(np.int32),
        "a3_fibula_pointer_run_envelope_mm": pointer_intervals,
        "a3_fibula_pointer_run_confirmation": confirmation,
        "a3_fibula_pointer_planes": np.asarray(planes, dtype=np.int32),
        "a3_fibula_native_resolved_slices": native,
        "a3_fibula_head_area_mm2": head_area,
        "a3_fibula_head_status": head_status,
        "a3_fibula_head_walked_slices": np.asarray(walked, dtype=np.int32),
        "a3_fibula_head_bodies": np.stack([h[0] for h in walk.heads])
        if walk is not None and walk.heads
        else np.zeros((0, 0, 0), dtype=bool),
        "a3_fibula_head_targets": np.stack([h[1] for h in walk.heads])
        if walk is not None and walk.heads
        else np.zeros((0, 0, 0), dtype=bool),
        "a3_fibula_support_status": combined,
        "a3_fibula_support_runs": np.asarray(extent, dtype=np.int32).reshape(-1, 2),
        "a3_fibula_support_run_ends": ends.astype(np.int32),
        "a3_fibula_support_run_envelope_mm": intervals,
        "a3_fibula_depth_offsets_mm": offsets,
        "a3_fibula_slice_thickness_mm": thick,
        "a3_fibula_slab_mm": slab,
        "a3_fibula_slice_origins_lps": origins if sound else np.empty((0, 3)),
        "a3_fibula_series_normal": normal,
        "a3_fibula_source_origin_lps": np.asarray(frame.origin_lps, dtype=np.float64),
        "a3_fibula_source_basis_lps": np.asarray(frame.basis_lps, dtype=np.float64),
    }
    for name, value in pack_fine_readings(profile.fine).items():
        arrays[f"a3_fibula_fine_{name}"] = value
    handed("fibula_profile", ("support", "head"))
    return support, arrays, ambiguities


@dataclass(frozen=True)
class FibulaFound:
    """The fibula as found, the one value every stage after it is handed: the main slice's record
    and arrays and its frame; the fibula's places in the scanner's millimetres (`physical`, always;
    `places`, the same where front to back lies in the slice's plane so its front edge can be read,
    else None, which the LCL and the biceps femoris tendon need); the marrow's light over those
    places on that slice (NaN where none is seen); the series and slice it was found on; every plane
    the established rule identified it on (slice, area in square millimetres, pixels); and, once the
    transfer onto the same place of the other sequence is read, that slice's series, index and the
    marrow's light there (None, None, NaN until then, and where it cannot be)."""

    record: dict
    arrays: dict[str, np.ndarray]
    frame: PlaneFrame
    places: np.ndarray | None
    physical: np.ndarray
    light: float
    series_uid: str
    slice_index: int
    resolved: tuple[tuple[int, float, int], ...]
    twin_uid: str | None = None
    twin_index: int | None = None
    twin_light: float = float("nan")


def fibula_head(
    series: Series, z: int, places: np.ndarray, light: float
) -> tuple[np.ndarray, np.ndarray, str, float]:
    """The fibular head's body on native slice z (`fibula_like_head`), the places it was sought
    from (the fibula's, projected onto the slice, `projected_places`), the reading's code and the
    body's area in square millimetres (`head_area_mm2`: NaN where it cannot be said, 0.0 where it
    was measured absent). Made once for the series, the slice, the places and the marrow's light
    it was read against: the fibula's continuation and the biceps femoris tendon's walk are
    handed the same reading, and no head is measured twice."""

    def read() -> tuple[np.ndarray, np.ndarray, str, float]:
        frame = plane_frame(series, z)
        plane, unseen = seen_native(series, z, "fibula_head")
        if isinstance(frame, str):
            none = np.zeros(plane.shape, dtype=bool)
            return none, none, "geometry_unreadable", float("nan")
        target = projected_places(places, frame, plane.shape)
        body, code = fibula_like_head(np.where(unseen, np.nan, plane), target, light)
        area = head_area_mm2(body, code, np.asarray(frame.spacing_rc))
        handed("fibula_head", ("body", "area"))
        return body, target, code, area

    return once(
        "fibula_head",
        (series.row.series_uid, z, digest(places), repr(float(light))),
        read,
    )


@dataclass(frozen=True)
class HeadWalk:
    """The outward walk to the fibular head's lateral face, made once (`head_walk`): `face` the
    first slice where the head is no longer a disc (None where the walk found none), `areas` and
    `status` per native slice (NaN and `HEAD_SLICE_STATUS["unread"]` where it never went), `code`
    its reading, `walked` the slices it asked a head of in the order it asked, `heads` the shared
    reading of each (`fibula_head`: body, target, code, area) and `light` the marrow's light the
    heads were read against (None where the walk never reached a head): every head it measured, kept
    for each consumer even where a later consumer abstains."""

    face: int | None
    areas: np.ndarray
    status: np.ndarray
    code: str
    walked: tuple[int, ...]
    heads: tuple[tuple[np.ndarray, np.ndarray, str, float], ...]
    light: float | None


def head_walk(
    series: Series,
    places: np.ndarray,
    knee: str,
    origins: np.ndarray,
    normal: np.ndarray,
    thicknesses: Sequence[float | None],
    light_of: Callable[[], float],
) -> HeadWalk:
    """The walk to the head's lateral face (`lateral_to_the_head`) with every head it measured, made
    once for the measurement it is: the series, the fibula's places, the knee's side, the slices'
    origins and thicknesses and the series' normal, and the marrow's light the heads are read
    against. `light_of` gives that light and is asked only when the walk reaches its first head,
    so a walk that abstains before any head reads nothing for it. The fibula's continuation and the
    biceps femoris tendon's rule are each handed the same value when all of those are the same; a
    walk read against another light, and one over other places, series or thicknesses, is another
    walk, never an alias."""
    base = (
        series.row.series_uid,
        digest(np.asarray(places, dtype=np.float64)),
        knee,
        digest(np.asarray(origins, dtype=np.float64)),
        digest(np.asarray(normal, dtype=np.float64)),
        tuple(None if t is None else float(t) for t in thicknesses),
    )

    def make() -> HeadWalk:
        walked: list[int] = []
        heads: list[tuple[np.ndarray, np.ndarray, str, float]] = []
        used: list[float] = []

        def area(z: int) -> float:
            light = float(light_of())
            used.append(light)
            head = fibula_head(series, z, places, light)
            reads("fibula_head", ("area",), "head_walk")
            walked.append(int(z))
            heads.append(head)
            return head[3]

        face, areas, status, code = lateral_to_the_head(
            places, origins, normal, thicknesses, knee, area
        )
        handed("head_walk", ("face", "areas", "status", "heads"))
        return HeadWalk(
            face,
            areas,
            status,
            code,
            tuple(walked),
            tuple(heads),
            used[0] if used else None,
        )

    # The walks made for this measurement, by the light each was read against (None where it read
    # no head, which holds for any light). The light is asked of only when an earlier walk of the
    # same measurement shows this one will reach a head: the conditions before the first head
    # do not depend on it.
    walks: dict[str | None, HeadWalk] = once("head_walk_index", base, dict)
    if None in walks:
        ledger.record("head_walk.handed_on")
        return walks[None]
    if walks:
        wanted = repr(float(light_of()))
        if wanted in walks:
            ledger.record("head_walk.handed_on")
            return walks[wanted]
    made = make()
    walks[None if made.light is None else repr(made.light)] = made
    ledger.record("head_walk.made")
    return made


def retain_fibula_profile(
    record: dict,
    arrays: dict[str, np.ndarray],
    profile: FibulaProfile,
    pointed: Sequence[int],
    read_at: dict[int, tuple],
    outcome: str,
) -> None:
    """Keep what the profile and the pointed planes measured when no fibula was named: with no main
    record, the series' own middle record (`record`, `arrays`, saved by the caller) is where the
    finer readings, the profile and every pointed plane's lens readings stay, under the same
    names a named fibula's record uses, with the outcome beside them. Nothing is read from them
    afterwards; they are kept, as the named case's are."""
    arrays.update(
        {
            "a3_fibula_profile_status": profile.status,
            "a3_fibula_profile_area_mm2": profile.area_mm2,
            "a3_fibula_profile_centroid_lps": profile.centroid_lps,
            "a3_fibula_profile_candidates": profile.candidates,
            "a3_fibula_profile_window_rc": profile.window_rc,
            "a3_fibula_profile_block_mm": profile.cell_mm,
            "a3_fibula_profile_block_px": profile.block_px,
            "a3_fibula_reference_light": np.asarray(profile.light, dtype=np.float64),
        }
    )
    for name, value in pack_fine_readings(profile.fine).items():
        arrays[f"a3_fibula_fine_{name}"] = value
    planes = list(read_at)
    arrays["a3_fibula_other_plane_slices"] = np.asarray(planes, dtype=np.int32)
    for name in OTHER_PLANE_READINGS:
        if planes:
            arrays[f"a3_fibula_other_plane_{name}"] = np.stack(
                [read_at[z][1][f"b1_{name}"] for z in planes]
            )
    record["fibula_profile_retained"] = {
        "outcome": outcome,
        "pointed_slices": [int(z) for z in pointed],
        "lens_read_slices": [int(z) for z in planes],
        "note": "no fibula named: the measured profile, finer readings and pointed planes' lens readings are kept here and read by nothing",
    }
    handed("fibula", ("other_planes",))


def merge_fibula_profiles(
    first: FibulaProfile, second: FibulaProfile, visited: np.ndarray
) -> FibulaProfile:
    """Join disjoint profile reads of the same series, slice by slice."""

    def take(a: np.ndarray, b: np.ndarray) -> np.ndarray:
        shape = (-1, *([1] * (a.ndim - 1)))
        return np.where(visited.reshape(shape), b, a)

    return FibulaProfile(
        take(first.status, second.status),
        take(first.area_mm2, second.area_mm2),
        take(first.centroid_lps, second.centroid_lps),
        take(first.candidates, second.candidates),
        take(first.corridor, second.corridor),
        take(first.could, second.could),
        take(first.window_rc, second.window_rc),
        take(first.cell_mm, second.cell_mm),
        take(first.block_px, second.block_px),
        tuple(sorted(first.fine + second.fine, key=lambda reading: reading.index)),
        first.light,
        first.top_mm,
        first.middle_lps,
    )


def fibula_guided_slices(
    series: Series, profile: FibulaProfile, guide: Guide | None
) -> dict[int, bool]:
    """Which retained fibula bodies overlap the map's expected slice and in-plane places.

    A guide without a usable in-plane allowance or an in-image placement cannot narrow the
    detailed read. The profile is already the cheap, shared search; this only consumes its fine
    body readings to decide which of its pointed slices the map supports.
    """
    if (
        guide is None
        or guide.status != "guided"
        or not guide.slices
        or guide.half_px is None
    ):
        return {}
    placements = [
        row
        for row in guide.placements
        if row.get("status") == "ok" and row.get("point_lps") is not None
    ]
    if not placements:
        return {}
    fine_at = {reading.index: reading for reading in profile.fine}
    hits: dict[int, bool] = {}
    row_half, col_half = (float(v) + 0.5 for v in guide.half_px)
    for z in guide.slices:
        reading = fine_at.get(int(z))
        frame = plane_frame(series, int(z))
        if reading is None or isinstance(frame, str):
            hits[int(z)] = False
            continue
        r0, _r1, c0, _c1 = reading.window_rc
        br, bc = reading.block_px
        row_grid, col_grid = np.indices(reading.body.shape)
        row_start = r0 + row_grid * br
        col_start = c0 + col_grid * bc
        for placement in placements:
            center = frame.to_native(
                np.asarray([placement["point_lps"]], dtype=np.float64)
            )[0]
            overlaps = (
                (row_start < center[0] + row_half)
                & (row_start + br > center[0] - row_half)
                & (col_start < center[1] + col_half)
                & (col_start + bc > center[1] - col_half)
            )
            if bool(np.any(reading.body & overlaps)):
                hits[int(z)] = True
                break
        else:
            hits[int(z)] = False
    return hits


def fibula_detail_groups(
    pointed: Sequence[int],
    guide_hits: dict[int, bool],
    runs: Sequence[tuple[int, int]] | None = None,
    maxima: Sequence[np.ndarray] | None = None,
    run_confirmations: Sequence[int] = (),
) -> list[tuple[str, list[int]]]:
    """Group native reads by map-supported runs, retaining all ties and end confirmations.

    A mapped slice makes its whole positive profile run relevant. If run context is omitted, keep
    the legacy per-pointer grouping for direct callers and small helper tests.
    """
    if runs is not None and maxima is not None:
        guided_runs = {
            run_index
            for run_index, (start, stop) in enumerate(runs)
            if any(guide_hits.get(z, False) for z in range(start, stop))
        }
        guided_set = {int(z) for run_index in guided_runs for z in maxima[run_index]}
        confirmations = {int(z) for z in run_confirmations}
        for run_index in guided_runs:
            start, stop = runs[run_index]
            peaks = maxima[run_index]
            if start in peaks and start - 1 in confirmations:
                guided_set.add(start - 1)
            if stop - 1 in peaks and stop in confirmations:
                guided_set.add(stop)
        guided = [int(z) for z in pointed if int(z) in guided_set]
    else:
        guided = [int(z) for z in pointed if guide_hits.get(int(z), False)]
    if not guided:
        return [("full_supported", [int(z) for z in pointed])]
    held = set(guided)
    return [
        ("guided", guided),
        ("broadened", [int(z) for z in pointed if int(z) not in held]),
    ]


def find_fibula(
    series: Series,
    record: dict,
    arrays: dict[str, np.ndarray],
    stack: SquintStack,
    mapping: "MapContext | None" = None,
) -> FibulaFound | str:
    """The fibula named on its main slice, from the middle slice's tibia, as a `FibulaFound` with its
    places in the scanner's millimetres where front to back lies in that slice's plane, so its
    front edge can be read (what the LCL's slice is found from, one leg, one set of objects); or why
    it was not named.

    The middle slice is the bootstrap, as ever: its tibia gives the tibia's light, its top and its
    middle. Without a usable guide, the fibula's corridor is read through the whole depth cheaply
    (`fibula_profile`: the kept squint's tiles, and a finer reading of the corridor's native
    window where the tiles cannot exclude it), never the lens. With a usable map, that shared
    profile starts in the expected window and expands edge maxima to completion; an unconfirmed
    guided window is broadened through the unvisited depth. The lens (`read_part_slice`) and the
    established rule (`fibula_on_slice`, the fibula's description: the region that looks like the
    tibia, well below its top and behind its middle, apart from the tibia and whole) run only on the
    planes the profile points to: the slice or slices where each run of support reaches its maximum,
    every tie kept, and a slice beside such a maximum where the corridor window cut a body, whose
    whole the full slice can tell (`confirmations`). The profile points only where the tibia can be
    told from the bone beside it, which is the established rule's own reference, so the rule is
    never run on a plane whose reference it cannot read. It is named on the one of them where its
    region is largest (`main_slice`). The profile's support, with its ends in the scanner's millimetres, the
    head's continuation outward from that slice, and what is not known are kept beside it."""
    assigned = record["assignments"]
    knee = assigned["knee"]
    reads("series", ("row",), "fibula")
    fat_suppressed = int(series.row.fat_suppression) == 1  # the tag is stored as text
    reads("naming", ("tibia", "objects"), "fibula")
    tibia = arrays["a1_objects"] == OBJECT_CODES["tibia"]
    tibia_named = assigned["tibia"] is not None and bool(tibia.any())
    code = fibula_code(knee, tibia_named, fat_suppressed, True)
    if code != "identified":
        return code
    volume = series.volume
    index = record["slice_index"]
    middle = plane_frame(series, index)
    if volume is None or isinstance(middle, str):
        return "geometry_unreadable"
    reads("naming", ("peaks",), "fibula")
    top_mm = float(middle.to_patient(np.argwhere(tibia).astype(float))[:, 2].max())
    peak = next(p for p in assigned["peaks"] if p["territory"] == assigned["tibia"])
    middle_rc = (int(peak["peak_rc"][0]), int(peak["peak_rc"][1]))
    middle_lps = middle.to_patient(np.asarray([middle_rc], dtype=float))[0]
    reads("squint_stack", ("code",), "fibula")
    if stack.code != "present":
        return f"squint_{stack.code}"
    reads("background", ("split",), "fibula")
    split = record["background_split"]
    uid = series.row.series_uid
    tibia_light = float(
        measures_of(uid, index, arrays["acquired_plane"], middle).light(tibia)
    )
    guide = (
        None
        if mapping is None
        else mapping.guide(
            "fibula",
            cast(Measured, SimpleNamespace(series=series, arrays=arrays)),
        )
    )
    depth = len(volume)
    guided_window = np.zeros(depth, dtype=bool)
    if guide is not None and guide.status == "guided" and guide.half_px is not None:
        for z in guide.slices:
            if 0 <= int(z) < depth:
                guided_window[int(z)] = True
    guided_profile = bool(guided_window.any())

    def read_profile(visit: np.ndarray | None = None) -> FibulaProfile:
        return fibula_profile(
            series,
            stack,
            tibia,
            middle_rc,
            tibia_light,
            top_mm,
            middle_lps,
            knee,
            visit,
        )

    visited = guided_window.copy() if guided_profile else np.ones(depth, dtype=bool)
    profile = read_profile(visited if guided_profile else None)
    if guided_profile:
        # A profile run whose maximum touches the read window's edge is still rising or tied
        # beyond it. Read that adjacent slice and repeat until each edge maximum is resolved.
        while True:
            edge_slices = np.zeros(depth, dtype=bool)
            current_runs = positive_runs(profile.area_mm2)
            for (a, b), peaks in zip(
                current_runs,
                run_maxima(profile.area_mm2, current_runs),
                strict=True,
            ):
                if a in peaks and a > 0 and not visited[a - 1]:
                    edge_slices[a - 1] = True
                if b - 1 in peaks and b < depth and not visited[b]:
                    edge_slices[b] = True
            if not edge_slices.any():
                break
            profile = merge_fibula_profiles(
                profile, read_profile(edge_slices), edge_slices
            )
            visited |= edge_slices
    reads("fibula_profile", ("status", "area_mm2"), "fibula")
    runs = positive_runs(profile.area_mm2)
    maxima = run_maxima(profile.area_mm2, runs)
    unresolved = (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"])
    # A body the window cut is read whole on the full slice, which tells more. A slice the tibia
    # cannot be told on is not: the established rule reads the same tibia there, so it would name
    # whatever dark tissue lies behind it, and it is left unknown.
    confirm = confirmations(
        runs, maxima, profile.status, (FIBULA_POINTER_STATUS["cut"],)
    )
    pointed = sorted({int(z) for peaks in maxima for z in peaks} | set(confirm))
    reads("fibula_profile", ("fine",), "fibula_map_guidance")
    guide_hits = fibula_guided_slices(series, profile, guide)
    detail_groups = fibula_detail_groups(pointed, guide_hits, runs, maxima, confirm)
    guided_pointed = detail_groups[0][1] if detail_groups[0][0] == "guided" else []
    map_guidance = None
    if mapping is not None:
        map_guidance = {
            "status": "no_map_supplied" if guide is None else guide.status,
            "expected_slices": [] if guide is None else list(guide.slices),
            "anchors": [] if guide is None else list(guide.anchors),
            "placements": [] if guide is None else list(guide.placements),
            "half_px": None if guide is None else guide.half_px,
            "profile_spatial_hits": {
                str(z): hit for z, hit in sorted(guide_hits.items())
            },
            "guided_pointed_slices": guided_pointed,
            "pointed_supported_slices": pointed,
        }
    read_at: dict[int, tuple] = {}
    groups_read: list[str] = []

    def read_native(z: int) -> None:
        if z in read_at:
            return
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            return
        part_record, part_arrays, part_field = read_part_slice(
            series, z, volume[z], frame, split, knee, "fibula"
        )
        labels = part_arrays["b1_labels"]
        rows, cols = np.indices(labels.shape)
        places_lps = frame.to_patient(
            np.column_stack((rows.ravel(), cols.ravel())).astype(float)
        ).reshape(*labels.shape, 3)
        territory, area = fibula_on_slice(
            labels,
            np.asarray(volume[z], dtype=float),
            frame.spacing_rc[0] * frame.spacing_rc[1],
            places_lps,
            tibia,
            middle_lps,
            np.zeros(labels.shape, dtype=bool),
        )
        read_at[z] = (
            part_record,
            part_arrays,
            part_field,
            frame,
            labels,
            territory,
            area,
        )

    if guided_profile and guided_pointed:
        groups_read.append("guided")
        for z in guided_pointed:
            read_native(z)
    guided_named = any(
        read_at[z][5] is not None for z in guided_pointed if z in read_at
    )
    broadened = guided_profile and not guided_named
    if broadened and not visited.all():
        remainder = ~visited
        reads("fibula_profile", ("status", "area_mm2", "fine"), "fibula_profile_merge")
        profile = merge_fibula_profiles(profile, read_profile(remainder), remainder)
        visited[:] = True
        runs = positive_runs(profile.area_mm2)
        maxima = run_maxima(profile.area_mm2, runs)
        confirm = confirmations(
            runs, maxima, profile.status, (FIBULA_POINTER_STATUS["cut"],)
        )
        pointed = sorted({int(z) for peaks in maxima for z in peaks} | set(confirm))
        detail_groups = fibula_detail_groups(pointed, guide_hits, runs, maxima, confirm)
        guided_pointed = detail_groups[0][1] if detail_groups[0][0] == "guided" else []
    if map_guidance is not None:
        map_guidance.update(
            profile_spatial_hits={str(z): hit for z, hit in sorted(guide_hits.items())},
            guided_pointed_slices=guided_pointed,
            pointed_supported_slices=pointed,
            profile_slices_visited=int(visited.sum()),
            profile_slices_unvisited=[int(z) for z in np.flatnonzero(~visited)],
        )
    if not guided_named:
        groups_read.append("full_supported" if not guided_profile else "broadened")
        for z in pointed:
            read_native(z)
    if not pointed:
        outcome = (
            FIBULA_UNREADABLE
            if np.isin(profile.status, unresolved).any()
            else fibula_code(knee, True, False, False)
        )
        if mapping is not None:
            assert map_guidance is not None  # created above for every supplied map
            use = (
                "unguided_full_search"
                if guide is None or guide.status != "guided"
                else "guided_miss_then_full_search_none"
            )
            mapping.smap.note_use("fibula", uid, use, stopped="no_supported_pointer")
            ledger.record(f"study_map.{use}", series=1)
            map_guidance.update(
                detailed_groups=groups_read,
                detailed_slices=sorted(read_at),
                stopped="no_supported_pointer",
                use=use,
            )
        retain_fibula_profile(record, arrays, profile, pointed, read_at, outcome)
        if map_guidance is not None:
            record["fibula_profile_retained"]["map_guidance"] = map_guidance
        return outcome
    ledger.record("fibula.pointed_planes", planes=len(pointed))
    stopped = "guided_key_slice_named" if guided_named else "full_supported_search"
    if mapping is not None:
        assert map_guidance is not None  # created above for every supplied map
        use = (
            "unguided_full_search"
            if guide is None or guide.status != "guided"
            else "guided_hit"
            if guided_named
            else "guided_miss_then_full_search_found"
            if any(row[5] is not None for row in read_at.values())
            else "guided_miss_then_full_search_none"
        )
        mapping.smap.note_use(
            "fibula",
            uid,
            use,
            guided_slices=guided_pointed,
            detailed_groups=groups_read,
            stopped=stopped,
        )
        ledger.record(f"study_map.{use}", series=1)
        map_guidance.update(
            detailed_groups=groups_read,
            detailed_slices=sorted(read_at),
            stopped=stopped,
            profile_slices_visited=int(visited.sum()),
            profile_slices_unvisited=[int(z) for z in np.flatnonzero(~visited)],
            broadened_to_full_profile=bool(broadened),
            use=use,
        )
    # Map-guided production selects within its justified neighbourhood; legacy direct calls still
    # read and compare the full supported search. Preserve slice order and every tie either way.
    planes = sorted(read_at)
    chosen = main_slice([read_at[z][6] for z in planes])
    if chosen is None:
        outcome = fibula_code(knee, True, False, False)
        retain_fibula_profile(record, arrays, profile, pointed, read_at, outcome)
        if map_guidance is not None:
            record["fibula_profile_retained"]["map_guidance"] = map_guidance
        return outcome
    main_z = planes[chosen]
    part_record, part_arrays, part_field, frame, labels, territory, _area = read_at[
        main_z
    ]
    tibia_here = region_holding(labels, tibia)
    # On its main slice only the fibula is named, beside the tibia it was found against; each is
    # drawn whole as the full slice's own region. The middle slice's other objects are not named
    # here: their rules belong to the middle slice.
    objects = np.zeros(labels.shape, dtype=np.int8)
    objects[tibia_here] = OBJECT_CODES["tibia"]
    objects[labels == territory] = OBJECT_CODES["fibula"]
    part_arrays["a1_objects"] = objects
    main_assigned = part_record["assignments"]
    codes = main_assigned["codes"]
    codes["tibia"] = "carried_from_the_middle_slice"
    codes["fibula"] = "identified"
    main_assigned.update(tibia=int(labels[tibia_here][0]), fibula=int(territory))
    # Where front to back lies in the main slice's plane (its field's `in_plane`), the fibula's front
    # edge can be read, and its places in millimetres are what the LCL's slice is found from.
    reads("field", ("in_plane",), "fibula")
    mask = objects == OBJECT_CODES["fibula"]
    physical = frame.to_patient(np.argwhere(mask).astype(float))
    places = physical if part_field.in_plane[1] else None
    plane, unseen = seen_native(series, main_z, "fibula")
    support_px = projected_places(physical, frame, plane.shape) & ~unseen
    marrow = (
        float(measures_of(uid, main_z, plane, frame).light(support_px))
        if support_px.any()
        else float("nan")
    )
    resolved = tuple(
        (z, float(read_at[z][6]), int(np.count_nonzero(read_at[z][4] == read_at[z][5])))
        for z in planes
        if read_at[z][5] is not None
    )
    support, support_arrays, ambiguities = fibula_support(
        series,
        middle,
        frame,
        main_z,
        profile,
        (runs, maxima, confirm),
        planes,
        tuple(z for z in planes if read_at[z][5] is not None),
        places,
        marrow,
        knee,
    )
    # a bone's thin ends run off the picture or into the black margin the scan never filled
    around = ndi.binary_dilation(mask, structure=FOUR_NEIGHBOURS) & ~mask
    edge = bool(
        (around & unseen).any()
        or mask[0].any()
        or mask[-1].any()
        or mask[:, 0].any()
        or mask[:, -1].any()
    )
    if edge:
        ambiguities.append("section_runs_to_the_picture_edge_or_unseen_places")
    best = max(read_at[z][6] for z in planes)
    if sum(read_at[z][6] == best for z in planes) > 1:
        ambiguities.append("detailed_planes_tie_for_the_largest_region")
    part_arrays.update(support_arrays)
    part_arrays["a3_fibula_places_lps"] = physical
    part_arrays["a3_fibula_detailed_slices"] = np.asarray(planes, dtype=np.int32)
    part_arrays["a3_fibula_detailed_areas_mm2"] = np.asarray(
        [read_at[z][6] for z in planes], dtype=np.float64
    )
    part_arrays["a3_fibula_detailed_regions"] = np.stack(
        [
            read_at[z][4] == read_at[z][5]
            if read_at[z][5] is not None
            else np.zeros(labels.shape, bool)
            for z in planes
        ]
    )
    part_arrays["a3_fibula_marrow_light"] = np.asarray(marrow, dtype=np.float64)
    # Every selected detailed plane was read in full (the lens, the field, the rule), and the
    # selected one's readings are this record's own arrays. The others' lens readings are kept too,
    # the very arrays the lens made, stacked in the order of `a3_fibula_other_plane_slices`, with the
    # territory the rule chose on each plane (-1 where none) in the order of the detailed planes.
    others = [z for z in planes if z != main_z]
    part_arrays["a3_fibula_detailed_territories"] = np.asarray(
        [-1 if read_at[z][5] is None else int(read_at[z][5]) for z in planes],
        dtype=np.int32,
    )
    part_arrays["a3_fibula_other_plane_slices"] = np.asarray(others, dtype=np.int32)
    for name in OTHER_PLANE_READINGS:
        kept = [read_at[z][1][f"b1_{name}"] for z in others]
        part_arrays[f"a3_fibula_other_plane_{name}"] = (
            np.stack(kept)
            if kept
            else np.empty((0, *labels.shape), dtype=part_arrays[f"b1_{name}"].dtype)
        )
    handed("fibula", ("other_planes",))
    pointed_planes = []
    for row, z in enumerate(planes):
        other = others.index(z) if z in others else None
        plane_record = read_at[z][0]
        pointed_planes.append(
            {
                "slice": int(z),
                "detailed_row": row,
                "selected": z == main_z,
                "territory": None if read_at[z][5] is None else int(read_at[z][5]),
                "area_mm2": float(read_at[z][6]),
                "identified": read_at[z][5] is not None,
                # where this plane's own lens readings are: this record's `b1_*` for the selected
                # plane, else a row of each `a3_fibula_other_plane_*` stack
                "readings": {
                    "arrays": [
                        f"b1_{name}"
                        if other is None
                        else f"a3_fibula_other_plane_{name}"
                        for name in OTHER_PLANE_READINGS
                    ],
                    "row": other,
                },
                "interiors": plane_record["interiors"],
                "peaks": plane_record["assignments"]["peaks"],
            }
        )
    part_record["main_slice"] = {
        "object": "fibula",
        "selected_slice": int(main_z),
        "pointed_slices": [int(z) for z in planes],
        "confirmed_slices": [int(z) for z in confirm],
        "detailed_areas_mm2": {str(z): float(read_at[z][6]) for z in planes},
        "pointed_planes": pointed_planes,
        "support": support,
        "ambiguities": ambiguities,
        "status_codes": {
            **FIBULA_POINTER_STATUS,
            "unconfirmed_candidate": UNCONFIRMED_CANDIDATE,
        },
        "run_confirmation_codes": dict(RUN_CONFIRMATION),
    }
    if map_guidance is not None:
        part_record["main_slice"]["map_guidance"] = map_guidance
    handed("fibula", ("main_slice", "region", "places", "physical", "light"))
    return FibulaFound(
        part_record,
        part_arrays,
        frame,
        places,
        physical,
        marrow,
        uid,
        int(main_z),
        resolved,
    )


def fibula_twin(
    own: Measured, twin: Measured, fibula: FibulaFound
) -> tuple[dict, dict[str, np.ndarray], int, float, int] | str:
    """The fibula laid onto the same place of the other sequence (one leg, one set of objects): that
    sequence's slice through the fibula's main slice (`biceps_twin`: found by the scanner's
    millimetres, never by equal indices, and its places matched once), read for its lens and field
    only (`read_part_slice`), and the fibula laid onto its regions by the pair's one match
    (`lay_parts`, the way every part named in one sequence is laid onto the other). The twin's own
    decision stays what it was (`FIBULA_LAID_WHEN`) until the lay. Returns the twin's record and
    arrays, its slice index, the marrow's light over the fibula's places as the twin sees them (NaN
    where it sees none), and how many of the twin's pixels have no place on the native slice and
    so are left out; or why it could not be laid."""
    laid = biceps_twin(own, twin, fibula.slice_index, "fibula")
    if isinstance(laid, str):
        return laid
    light_map, index = laid
    series = twin.series
    volume = series.volume
    frame = plane_frame(series, index)
    if volume is None or isinstance(frame, str):
        return "geometry_unreadable"
    reads("background", ("split",), "fibula")
    record, arrays, _ = read_part_slice(
        series,
        index,
        volume[index],
        frame,
        twin.record["background_split"],
        twin.record["assignments"]["knee"],
        "fibula",
    )
    # on this slice the fibula is the native one's, laid; until then nothing is named
    arrays["a1_objects"] = np.zeros(arrays["acquired_plane"].shape, dtype=np.int8)
    codes = record["assignments"]["codes"]
    codes["fibula"] = FIBULA_LAID_WHEN
    record["main_slice"] = {
        "object": "fibula",
        "native_series_uid": fibula.record["series_uid"],
        "native_slice_index": int(fibula.record["slice_index"]),
    }
    placed = lay_parts(
        twin,
        (record, arrays, frame),
        (fibula.record, fibula.arrays, fibula.frame),
        ("fibula",),
        product="fibula",
    )["fibula"]
    if placed != "laid_from_its_partner":
        return placed or "abstain_no_fibula_in_the_twins_picture"
    codes["fibula"] = placed
    source = matched(
        series,
        record,
        frame,
        arrays["acquired_plane"].shape,
        fibula.record,
        fibula.frame,
        fibula.arrays["acquired_plane"],
    )
    unmapped = (
        int(np.count_nonzero(source < 0)) if isinstance(source, np.ndarray) else -1
    )
    plane, unseen = seen_native(own.series, fibula.slice_index, "fibula")
    support = projected_places(fibula.physical, fibula.frame, plane.shape) & ~unseen
    return record, arrays, index, twin_marrow_light(light_map, support), unmapped


def slab_thicknesses(series: Series) -> tuple[list[float], str | None]:
    """Each slice's thickness in millimetres, or why a series cannot say it (no stacked volume, no
    geometry, a slice without a thickness): the fact a slab, or a projection onto a slice, needs."""
    if series.volume is None:
        return [], "no_stacked_volume"
    if series.geometry is None:
        return [], "geometry_unreadable"
    thick = list(series.slice_thickness_mm)
    if not thick or any(t is None for t in thick):
        return [], "no_slice_thickness"
    return [float(t) for t in thick], None


@dataclass(frozen=True)
class AxialRead:
    """What one axial slice's own lens territories say under the fibula's places on its slab: the
    series, view and slice; the `code` (`territory_holding_most`, `tie`, `unavailable`,
    `no_territory_under_the_places` or `empty_target`); the slab's thickness, the slice's frame, how
    many of the fibula's places lie within the slab (`on_slab_points`), the other slices holding
    exactly as many (`tied_slices`, none broken silently), the mean distance of the on-slab places
    from the plane (None where there are none to measure), and how many seen target pixels they
    fall on. The readings (None where no slice was read, as for `empty_target`): the lens's labels
    and availability, the on-slab target pixels, the territory holding most of them (empty on a tie
    or where none holds any) and its label; `hits` (territory label -> seen target pixels) and
    `tied_labels` (the territories sharing the most)."""

    series_uid: str
    view: tuple[str, str, str]
    slice_index: int
    code: str
    thickness_mm: float
    frame: PlaneFrame
    on_slab_points: int
    tied_slices: tuple[int, ...]
    off_plane_mm: float | None
    target_pixels: int
    hits: dict[int, int]
    tied_labels: tuple[int, ...] = ()
    labels: np.ndarray | None = None
    available: np.ndarray | None = None
    target: np.ndarray | None = None
    region: np.ndarray | None = None
    label: int | None = None


def axial_territory(
    series: Series,
    index: int,
    frame: PlaneFrame,
    split: float,
    physical: np.ndarray,
    thickness: float,
) -> tuple[
    np.ndarray, np.ndarray, np.ndarray, np.ndarray, int | None, str, dict, tuple
]:
    """The lens territory of axial slice `index` holding most of the places of `physical` (scanner
    millimetres) that lie within its slab (`places_on_slice`; the places off the slab are not
    projected): the lens's labels and availability, the on-slab target pixels, the region, its
    label (None where none), the code, the seen target pixels each territory holds and the
    territories tied for the most. Only the lens is read (`lens_of`, once per slice and shared with
    anything else that reads that slice), never the field. Made once for the series, the slice, the
    places and the settings, so every view whose places are the same reads it once."""

    def read() -> tuple:
        plane = np.asarray(series.volume[index])
        _, reading, _ = lens_of(series, index, plane, frame, split, "fibula")
        reads("interiors", ("labels", "available"), "fibula_axial")
        labels = reading.labels
        available = np.asarray(reading.available, dtype=bool)
        target = places_on_slice(physical, frame, labels.shape, thickness)
        seen = target & available
        held = labels[seen & (labels > 0)]
        counts = np.bincount(held) if held.size else np.zeros(0, dtype=np.int64)
        hits = {int(k): int(v) for k, v in enumerate(counts) if v}
        tied = (
            tuple(int(k) for k in np.flatnonzero(counts == counts.max()))
            if held.size
            else ()
        )
        region = np.zeros(labels.shape, dtype=bool)
        label = None
        if not seen.any():
            code = "unavailable"
        elif not held.size:
            code = "no_territory_under_the_places"
        elif len(tied) > 1:
            code = "tie"
        else:
            region = region_holding(labels, seen)
            label = tied[0]
            code = "territory_holding_most"
        handed("fibula_axial", ("target", "region"))
        return (
            labels,
            available,
            handed_on(target),
            handed_on(region),
            label,
            code,
            hits,
            tied if len(tied) > 1 else (),
        )

    return once(
        "fibula_axial",
        (
            series.row.series_uid,
            index,
            digest(physical),
            repr(float(thickness)),
            repr(float(split)),
        ),
        read,
    )


def fibula_axial(other: Measured, physical: np.ndarray) -> list[AxialRead] | str:
    """The fibula's places (`physical`, scanner millimetres) read against one axial series: the
    slice the places' centre selects, of those whose slab (half its thickness about the slice's
    origin along its own normal) holds any of them (every slice at the same distance is read and
    names the others, `tied_slices`; each slice's own count is its `on_slab_points`),
    with only the places within the slab mapped onto its pixels and the lens territory holding
    most of them (`axial_territory`). No place on any slab is `empty_target` (nothing is read, and
    the slice named is the nearest to the places' middle). Why the series cannot be asked at all
    (no volume, geometry or thickness, a frame its header does not give) is the returned string,
    an unknown and never an absence. The slabs are the slices' own, so reversed or oblique stacks
    need no assumption."""
    series = other.series
    thick, why = slab_thicknesses(series)
    if why is not None:
        return why
    volume = series.volume
    if volume is None or len(thick) != len(volume):
        return "no_slice_thickness"
    frames: list[PlaneFrame] = []
    for z in range(len(volume)):
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            return frame
        frames.append(frame)
    points = np.asarray(physical, dtype=np.float64)
    offsets = np.stack([np.abs((points - f.origin_lps) @ f.normal()) for f in frames])
    on = offsets <= (np.asarray(thick) / 2.0)[:, None]
    counts = on.sum(axis=1)
    uid, view = series.row.series_uid, tuple(other.record["view"])
    if int(counts.max()) == 0:
        finite = points[np.isfinite(points).all(axis=1)]
        nearest, distance = 0, None
        if finite.size:
            middle = finite.mean(axis=0)
            away = [abs(float((middle - f.origin_lps) @ f.normal())) for f in frames]
            nearest, distance = int(np.argmin(away)), float(min(away))
        return [
            AxialRead(
                uid,
                view,
                nearest,
                "empty_target",
                thick[nearest],
                frames[nearest],
                0,
                (),
                distance,
                0,
                {},
            )
        ]
    # The plane is the one the places' centre selects: of the slices whose slab holds any of the
    # places, the one nearest their centre along its own normal. (The slice holding the most places
    # is a plateau where a section is long, not a place.) Equal distances are tied, none dropped.
    finite = points[np.isfinite(points).all(axis=1)]
    middle = finite.mean(axis=0)
    centre = np.asarray(
        [abs(float((middle - f.origin_lps) @ f.normal())) for f in frames]
    )
    holding = np.flatnonzero(counts > 0)
    nearest_centre = float(centre[holding].min())
    tied_slices = tuple(
        int(z)
        for z in holding
        if np.isclose(centre[z], nearest_centre, rtol=0, atol=1e-9)
    )
    split = float(other.record["background_split"])
    out = []
    for z in tied_slices:
        labels, available, target, region, label, code, hits, tied = axial_territory(
            series, z, frames[z], split, points, thick[z]
        )
        out.append(
            AxialRead(
                uid,
                view,
                z,
                code,
                thick[z],
                frames[z],
                int(counts[z]),
                tuple(t for t in tied_slices if t != z),
                float(offsets[z][on[z]].mean()),
                int(np.count_nonzero(target & available)),
                hits,
                tied,
                labels,
                available,
                target,
                region,
                label,
            )
        )
    return out


def retain_fibula_axial(
    fibula: FibulaFound, axial: list[AxialRead]
) -> list[Observation]:
    """Keep what the axial readings measured inside the fibula's own record and arrays, and say each
    as a native reading: the source's frame (`a3_fibula_source_*`, beside the physical places
    `a3_fibula_places_lps`) and, for every slice read, one row of the `a3_fibula_axial_*` arrays,
    indexed by `a3_fibula_axial_slices`: the lens labels, availability, on-slab target pixels and
    the region, each a flat array of the slices' pixels in row order (`a3_fibula_axial_shapes` and
    `_offsets` cut row i out as `[offsets[i]:offsets[i + 1]].reshape(shapes[i])`, for axial series
    whose pictures differ in size), with each slice's origin, basis, normal, thickness and on-slab
    point count. The record's `axial_evidence` names, per reading, its series, slice, row, code and
    territory counts. Nothing reads these afterwards; the record is saved by the caller (the ledger
    lists the territory and target as produced and read by no stage, retained only)."""
    if not axial:
        return []
    arrays, record = fibula.arrays, fibula.record
    # the record already keeps the source frame's origin and basis under these names (the support's
    # own arrays); the normal is the one fact added, and nothing kept is written over
    arrays.setdefault(
        "a3_fibula_source_origin_lps",
        np.asarray(fibula.frame.origin_lps, dtype=np.float64),
    )
    arrays.setdefault(
        "a3_fibula_source_basis_lps",
        np.asarray(fibula.frame.basis_lps, dtype=np.float64),
    )
    arrays.setdefault("a3_fibula_source_normal_lps", fibula.frame.normal())
    kept = [a for a in axial if a.labels is not None]
    if kept:
        shapes = np.asarray([np.shape(a.labels) for a in kept], dtype=np.int32)
        sizes = shapes[:, 0].astype(np.int64) * shapes[:, 1]
        arrays["a3_fibula_axial_slices"] = np.asarray(
            [a.slice_index for a in kept], dtype=np.int32
        )
        arrays["a3_fibula_axial_shapes"] = shapes
        arrays["a3_fibula_axial_offsets"] = np.concatenate(([0], np.cumsum(sizes)))
        for name in ("labels", "available", "target", "region"):
            arrays[f"a3_fibula_axial_{name}"] = np.concatenate(
                [getattr(a, name).ravel() for a in kept]
            )
        arrays["a3_fibula_axial_origin_lps"] = np.stack(
            [a.frame.origin_lps for a in kept]
        )
        arrays["a3_fibula_axial_basis_lps"] = np.stack(
            [a.frame.basis_lps for a in kept]
        )
        arrays["a3_fibula_axial_normal_lps"] = np.stack(
            [a.frame.normal() for a in kept]
        )
        arrays["a3_fibula_axial_thickness_mm"] = np.asarray(
            [a.thickness_mm for a in kept], dtype=np.float64
        )
        arrays["a3_fibula_axial_on_slab_points"] = np.asarray(
            [a.on_slab_points for a in kept], dtype=np.int64
        )
    artifact = record.get("artifact")
    evidence: list[dict] = []
    out: list[Observation] = []
    row = 0
    for a in axial:
        here = None
        if a.labels is not None:
            here = row
            row += 1
        region = 0 if a.region is None else int(np.count_nonzero(a.region))
        evidence.append(
            {
                "series_uid": a.series_uid,
                "view": list(a.view),
                "slice": a.slice_index,
                "row": here,
                "code": a.code,
                "thickness_mm": a.thickness_mm,
                "on_slab_points": a.on_slab_points,
                "tied_slices": list(a.tied_slices),
                "target_pixels": a.target_pixels,
                "territory_hits": {str(k): v for k, v in sorted(a.hits.items())},
                "tied_labels": list(a.tied_labels),
                "label": a.label,
                "region_pixels": region,
            }
        )
        said = (
            "a lens territory of this axial slice under the fibula's places within its slab: "
            "a reading, not the bone's boundary; places off the slab are not projected"
        )
        if here is not None:
            # the support is a flat packed boolean array: the row's places are its slice of it,
            # and the lens territory's number is in the companion labelled array, not a selector
            said += (
                f"; row {here} is a3_fibula_axial_region[a3_fibula_axial_offsets[{here}]:"
                f"a3_fibula_axial_offsets[{here + 1}]] reshaped to a3_fibula_axial_shapes[{here}]"
            )
            if a.label is not None:
                said += (
                    f"; the territory's number ({a.label}) is the value of the same slice "
                    "of a3_fibula_axial_labels"
                )
        if a.tied_slices:
            said += f"; slices {list(a.tied_slices)} hold as many places"
        if a.tied_labels:
            said += (
                f"; territories {list(a.tied_labels)} hold as many pixels, none chosen"
            )
        out.append(
            Observation(
                "fibula",
                "native",
                "reading",
                a.series_uid,
                a.view,
                (a.slice_index,),
                a.code,
                a.target_pixels,
                a.off_plane_mm,
                "a3_fibula_axial_region"
                if here is not None
                else "a3_fibula_places_lps",
                said,
                artifact,
                here,
                None,
            )
        )
    record["axial_evidence"] = evidence
    return out


def fibula_observations(
    own: Measured,
    fibula: FibulaFound,
    partner: Measured | None,
    twin: tuple | str | None,
    measured: list[Measured],
) -> tuple[list[Observation], list[Unresolved]]:
    """What each view says of the fibula, by where the saying comes from (`knee.collapse.observations`),
    derived from the records and masks the run made and counting nothing again; and what could not be
    said, kept as an unknown with its code and never as an absence.

    Native: each plane the established rule identified it on (resolved; the selected one's places
    are `a1_objects` where it is the fibula's code, another's are one row of
    `a3_fibula_detailed_regions`), each plane the profile pointed to and the rule rejected (a reading,
    one row of `a3_fibula_other_plane_labels`), and the cheap readings of its body through depth: the
    pointer's runs, confirmed or not by the rule, and the head's outward continuation (readings: no
    boundary claimed, and the support is not the bone's section; the slices index the profile's
    own per-slice arrays). Laid: the same place of the other sequence, with the pixels of that
    picture the match has no place for left out. Projected: its places in the scanner's millimetres
    onto the slice of every other series nearest them, however far off its plane (targets: where a
    native question may be asked, never a boundary seen there); which of them lie on a slice, between
    slices or beyond the scan is each target's code. Native again, for every other axial series
    (`fibula_axial`): the slice whose slab holds most of the places, and the lens territory holding
    most of the places within that slab, kept as the `a3_fibula_axial_*` arrays of the fibula's own
    record (`retain_fibula_axial`: retained, read by no stage) and said as readings, never a
    boundary. Every observation names the artifact that holds
    its support (`record["artifact"]`, as `save` made it), and the row or label that selects its
    places in it. A transfer that failed, a partner the study does not have and a series whose
    geometry cannot place a projection are `Unresolved`, each with its code."""
    view = tuple(own.record["view"])
    uid = fibula.series_uid
    native_artifact = fibula.record.get("artifact")
    detailed = [int(z) for z in fibula.arrays.get("a3_fibula_detailed_slices", ())]
    others = [int(z) for z in fibula.arrays.get("a3_fibula_other_plane_slices", ())]
    identified = {int(z) for z, _, _ in fibula.resolved}
    out: list[Observation] = []
    for z, _, pixels in fibula.resolved:
        selected = z == fibula.slice_index
        out.append(
            Observation(
                "fibula",
                "native",
                "resolved",
                uid,
                view,
                (z,),
                "identified",
                pixels,
                0.0,
                "a1_objects" if selected else "a3_fibula_detailed_regions",
                "the section on this slice, not the whole bone",
                native_artifact,
                None if selected else detailed.index(z),
                OBJECT_CODES["fibula"] if selected else None,
            )
        )
    for z in detailed:
        if z not in identified:
            out.append(
                Observation(
                    "fibula",
                    "native",
                    "reading",
                    uid,
                    view,
                    (z,),
                    "pointed_plane_rejected_by_the_native_rule",
                    None,
                    0.0,
                    "a3_fibula_other_plane_labels",
                    "the plane was read in full and the established rule named no fibula on it",
                    native_artifact,
                    others.index(z),
                )
            )
    runs = fibula.arrays.get("a3_fibula_pointer_runs", np.empty((0, 2), dtype=np.int32))
    confirmed_run = (
        fibula.arrays.get("a3_fibula_pointer_run_confirmation", np.zeros(len(runs)))
        == RUN_CONFIRMATION["confirmed_by_the_native_rule"]
    )
    head = np.flatnonzero(
        fibula.arrays["a3_fibula_head_status"] == HEAD_SLICE_STATUS["head_still_a_disc"]
    )
    for name, slices, support, note in (
        (
            "pointer_body",
            np.asarray(
                [
                    z
                    for (a, b), ok in zip(runs, confirmed_run, strict=True)
                    if ok
                    for z in range(a, b)
                ],
                dtype=int,
            ),
            "a3_fibula_profile_area_mm2",
            (
                "a cheap marrow-like body through depth, on a run the native rule confirmed: "
                "no boundary, and not the bone's whole extent"
            ),
        ),
        (
            "pointer_body_unconfirmed",
            np.asarray(
                [
                    z
                    for (a, b), ok in zip(runs, confirmed_run, strict=True)
                    if not ok
                    for z in range(a, b)
                ],
                dtype=int,
            ),
            "a3_fibula_profile_area_mm2",
            (
                "a cheap marrow-like body through depth on a run the native rule did not "
                "confirm: a candidate, not the bone's extent"
            ),
        ),
        (
            "head_still_a_disc",
            head,
            "a3_fibula_head_area_mm2",
            (
                "the head's body walked outward from the identified slice: no boundary, and "
                "not the bone's whole extent"
            ),
        ),
    ):
        if slices.size:
            out.append(
                Observation(
                    "fibula",
                    "native",
                    "reading",
                    uid,
                    view,
                    tuple(int(z) for z in slices),
                    name,
                    None,
                    None,
                    support,
                    note,
                    native_artifact,
                )
            )
    unresolved: list[Unresolved] = []
    laid_uid = None
    if partner is None:
        unresolved.append(
            Unresolved("fibula", "laid", None, None, "none_of_the_other_sequence")
        )
    elif isinstance(twin, str):
        unresolved.append(
            Unresolved(
                "fibula",
                "laid",
                partner.series.row.series_uid,
                tuple(partner.record["view"]),
                twin,
            )
        )
    elif isinstance(twin, tuple):
        record, arrays, index, _, unmapped = twin
        laid_uid = partner.series.row.series_uid
        frame = plane_frame(partner.series, index)
        off = (
            float(
                abs((fibula.physical.mean(axis=0) - frame.origin_lps) @ frame.normal())
            )
            if not isinstance(frame, str)
            else None
        )
        out.append(
            Observation(
                "fibula",
                "laid",
                "resolved",
                laid_uid,
                tuple(partner.record["view"]),
                (index,),
                record["assignments"]["codes"]["fibula"],
                int(np.count_nonzero(arrays["a1_objects"] == OBJECT_CODES["fibula"])),
                off,
                "a1_objects",
                f"the same place of the other sequence by the pair's match; {unmapped} pixels "
                "of its picture have no place on the native slice and are left out",
                record.get("artifact"),
                None,
                OBJECT_CODES["fibula"],
            )
        )
    skip = {own.record["series_uid"], laid_uid}
    middle = fibula.physical.mean(axis=0)
    axial_series = 0
    axial_reads: list[AxialRead] = []
    for other in measured:
        series = other.series
        other_uid, other_view = series.row.series_uid, tuple(other.record["view"])
        if other_uid in skip:
            continue
        if other_view[0].lower() == "axial":
            # native evidence from this series' own territories, beside (never instead of) the
            # projected target below
            axial_series += 1
            got = fibula_axial(other, fibula.physical)
            if isinstance(got, str):
                unresolved.append(
                    Unresolved("fibula", "native", other_uid, other_view, got)
                )
            else:
                axial_reads.extend(got)
        thick, why = slab_thicknesses(series)
        if why is not None:
            unresolved.append(
                Unresolved("fibula", "projected", other_uid, other_view, why)
            )
            continue
        origins = np.asarray(
            [np.asarray(p, dtype=float) for p in series.geometry.position]
        )
        normal = other.frame.normal()
        signed = (middle - origins) @ normal
        nearest = int(np.argmin(np.abs(signed)))
        along = origins @ normal
        low = float(along.min()) - float(thick[int(np.argmin(along))]) / 2.0
        high = float(along.max()) + float(thick[int(np.argmax(along))]) / 2.0
        distance = float(abs(signed[nearest]))
        if distance <= float(thick[nearest]) / 2.0:
            where = "on_the_slice"
        elif not low <= float(middle @ normal) <= high:
            where = "beyond_the_scan"
        else:
            where = "between_slices"
        frame = plane_frame(series, nearest)
        if isinstance(frame, str):
            unresolved.append(
                Unresolved("fibula", "projected", other_uid, other_view, frame)
            )
            continue
        out.append(
            Observation(
                "fibula",
                "projected",
                "target",
                other_uid,
                other_view,
                (nearest,),
                where,
                int(
                    np.count_nonzero(
                        projected_places(
                            fibula.physical, frame, series.volume[nearest].shape
                        )
                    )
                ),
                distance,
                "a3_fibula_places_lps",
                "a location target projected from the fibula's places: where a native question may "
                "be asked, not a boundary seen on this slice",
                native_artifact,
            )
        )
    if not axial_series:
        unresolved.append(Unresolved("fibula", "native", None, None, "no_axial_series"))
    out.extend(retain_fibula_axial(fibula, axial_reads))
    return out, unresolved


def fibula_key_planes(
    measured: list[Measured],
    mapping: "MapContext",
    found_fibulas: list[tuple[Measured, FibulaFound]],
    leg: Leg,
    study_uid: str,
) -> None:
    """Scout the fibula's axial key plane from its native sagittal and coronal sections.

    Every native section the recognizer found (`FibulaFound.physical`, with its own series' frame and
    slice thickness) is a sparse location seed, never a boundary. A seed reaches an axial slice only if
    that slice's slab meets the section's actual voxel extent (the formula of `patella_key_planes`), and
    only where a seed pixel lies in the picture is anything read: the shared 2 mm coarse enclosure
    (`coarse_axial_blocks`, `coarse_axial_depth`, the same cached readings the bones and the patella
    use) and the whole enclosed section holding the seeds. The tibia of `leg` carried onto the slice
    marks the blocks of the other bone, so a section shared with it is refused by `coarse_section`,
    never cut apart; the driver hands it the leg refined by the bones' later native sections
    (`refine_leg`), a location prior, and `leg_on` keeps each leg's projection apart by its identity.
    The largest competent sections' slices, every tie, are offered to the map once each.

    The first found fibula is the evidence holder: its main record is saved after this runs. Per axial
    series, under that series' full uid, it keeps every reading's status, the seed pixels and blocks, the
    section bodies and the frames and thicknesses read, as `a4_fibula_coarse_<uid>_*`, and the readings
    as native `reading` observations of that axial series (packed boolean rows, no label), beside the
    observations it already holds. A source whose frame or thickness is unavailable, a slice whose
    geometry is, and a series without competent sections are named refusals, never absences.
    """
    sources: list[tuple[np.ndarray, PlaneFrame, float]] = []
    unusable_sources: list[dict] = []

    def thickness_of(series: Series, z: int) -> float | None:
        values = getattr(series, "slice_thickness_mm", None)
        if values is None or not 0 <= z < len(values) or values[z] is None:
            return None
        value = float(values[z])
        return value if np.isfinite(value) and value > 0 else None

    for source, fibula in found_fibulas:
        if str(source.record["view"][0]).lower() not in ("sagittal", "coronal"):
            continue
        z = int(fibula.slice_index)
        places = np.asarray(fibula.physical, dtype=np.float64)
        source_frame = plane_frame(source.series, z)
        source_thickness = thickness_of(source.series, z)
        code = None
        if places.ndim != 2 or places.shape[1] != 3:
            code = "native_places_malformed"
        elif not np.isfinite(places).all(axis=1).any():
            code = "native_places_empty"
        elif isinstance(source_frame, str):
            code = source_frame
        elif source_thickness is None:
            code = "source_slice_thickness_unavailable"
        if (
            code is not None
            or isinstance(source_frame, str)
            or source_thickness is None
        ):
            unusable_sources.append(
                {
                    "series_uid": source.record["series_uid"],
                    "slice": z,
                    "code": code or "source_unavailable",
                }
            )
            continue
        sources.append(
            (places[np.isfinite(places).all(axis=1)], source_frame, source_thickness)
        )
    if sources:
        reads("fibula", ("physical",), "fibula_key_planes")

    holder = found_fibulas[0][1] if found_fibulas else None
    # only a holder has observations to address; without one nothing is persisted or addressed
    holder_artifact = (
        "" if holder is None else str(artifact_of(study_uid, holder.record))
    )
    summaries: dict[str, dict] = {}
    said: list[Observation] = []
    missing: list[Unresolved] = []
    planes_read = 0
    planes_offered = 0
    targets = [m for m in measured if str(m.record["view"][0]).lower() == "axial"]

    for own in targets:
        series = own.series
        uid = own.record["series_uid"]
        view = tuple(own.record["view"])
        volume = getattr(series, "volume", None)
        depth_count = 0 if volume is None or not sources else len(volume)
        marrow_is_dark = int(series.row.fat_suppression) == 1
        source_extent = np.zeros(depth_count, dtype=bool)
        readings = []
        depths = []
        sections = []
        tibia_blocks = []
        seed_pixels = []
        read_slices: list[int] = []
        read_frames: list[PlaneFrame] = []
        read_thicknesses: list[float] = []
        areas = np.full(depth_count, np.nan, dtype=np.float64)
        status_counts: dict[str, int] = {}
        unreadable: dict[str, list[int]] = {}
        extent_without_seed: list[int] = []
        source_points_count = 0
        for z in range(depth_count):
            assert (
                volume is not None
            )  # depth_count is zero when the volume is unavailable
            frame = plane_frame(series, z)
            target_thickness = thickness_of(series, z)
            if isinstance(frame, str) or target_thickness is None:
                why = frame if isinstance(frame, str) else "slice_thickness_unavailable"
                unreadable.setdefault(why, []).append(z)
                continue
            normal = frame.normal()
            offset = float(normal @ frame.origin_lps)
            target_half = target_thickness / 2.0
            shape = (int(np.shape(volume[z])[0]), int(np.shape(volume[z])[1]))
            native_seed = np.zeros(shape, dtype=bool)
            for points, source_frame, source_thickness in sources:
                # the voxel extent of patella_key_planes: the target slab's half thickness plus the
                # source pixel's half widths and half thickness, each projected on the target normal
                source_half = 0.5 * (
                    abs(float(normal @ source_frame.basis_lps[:, 0]))
                    + abs(float(normal @ source_frame.basis_lps[:, 1]))
                    + abs(float(normal @ source_frame.normal())) * source_thickness
                )
                distance = np.abs(points @ normal - offset)
                held = distance <= (target_half + source_half)
                if not held.any():
                    continue
                source_extent[z] = True
                projected = frame.to_native(points[held])
                in_picture = (
                    np.isfinite(projected).all(axis=1)
                    & (projected[:, 0] >= -0.5)
                    & (projected[:, 0] < shape[0] - 0.5)
                    & (projected[:, 1] >= -0.5)
                    & (projected[:, 1] < shape[1] - 0.5)
                )
                if in_picture.any():
                    pixels = np.floor(projected[in_picture] + 0.5).astype(np.int64)
                    native_seed[pixels[:, 0], pixels[:, 1]] = True
                    source_points_count += int(in_picture.sum())
            if not source_extent[z]:
                continue
            if not native_seed.any():
                extent_without_seed.append(z)
                continue
            plane = np.asarray(volume[z], dtype=np.float64)
            reading = once(
                "coarse_axial_blocks",
                (uid, z, LIGAMENT_SMOOTH_MM),
                lambda plane=plane, spacing_rc=frame.spacing_rc: block_medians(
                    plane,
                    margin(plane) | ~np.isfinite(plane),
                    spacing_rc,
                    float(LIGAMENT_SMOOTH_MM),
                ),
            )
            coarse = once(
                "coarse_axial_depth",
                (uid, z, marrow_is_dark),
                lambda reading=reading, dark=marrow_is_dark: handed_on(
                    coarse_depth(reading.median, dark)
                ),
            )
            tibia_seed = leg_on(leg, series, z, frame, shape, target_thickness)[1]
            other_bone = block_holds(tibia_seed, reading)
            result = coarse_section(
                coarse,
                block_holds(native_seed, reading),
                float(np.prod(reading.block_mm)),
                {"tibia": other_bone},
            )
            read_slices.append(z)
            read_frames.append(frame)
            read_thicknesses.append(target_thickness)
            readings.append(reading)
            depths.append(coarse)
            sections.append(result)
            tibia_blocks.append(other_bone)
            seed_pixels.append(np.argwhere(native_seed).astype(np.int32))
            status_counts[result.status] = status_counts.get(result.status, 0) + 1
            if result.body is not None:
                areas[z] = result.area_mm2
            ledger.record("coarse_axial_fibula.sections", planes=1)
        planes_read += len(read_slices)
        keys = coarse_key_slices(areas)
        prefix = f"a4_fibula_coarse_{uid}"
        if holder is not None and read_slices:
            packed = pack_sections(read_slices, readings, depths, {"fibula": sections})
            holder.arrays.update({f"{prefix}_{name}": v for name, v in packed.items()})
            holder.arrays[f"{prefix}_tibia_seeds"] = np.concatenate(
                [blocks.ravel() for blocks in tibia_blocks]
            )
            holder.arrays[f"{prefix}_native_seed_pixels"] = np.concatenate(seed_pixels)
            holder.arrays[f"{prefix}_native_seed_pixel_offsets"] = np.concatenate(
                ([0], np.cumsum([len(p) for p in seed_pixels]))
            ).astype(np.int64)
            holder.arrays[f"{prefix}_source_extent"] = source_extent
            holder.arrays[f"{prefix}_origin_lps"] = np.asarray(
                [f.origin_lps for f in read_frames], dtype=np.float64
            )
            holder.arrays[f"{prefix}_basis_lps"] = np.asarray(
                [f.basis_lps for f in read_frames], dtype=np.float64
            )
            holder.arrays[f"{prefix}_normal_lps"] = np.asarray(
                [f.normal() for f in read_frames], dtype=np.float64
            )
            holder.arrays[f"{prefix}_thickness_mm"] = np.asarray(
                read_thicknesses, dtype=np.float64
            )
        summaries[uid] = {
            "orientation": "axial",
            "source": "native_fibula_main_sections_of_sagittal_and_coronal_series",
            "source_sections": len(sources),
            "unusable_sources": unusable_sources,
            "source_points_projected": source_points_count,
            "marrow": "dark_enclosed_by_brighter"
            if marrow_is_dark
            else "bright_enclosed_by_darker",
            "block_mm": float(LIGAMENT_SMOOTH_MM),
            "arrays_prefix": prefix,
            "slices_read": read_slices,
            "source_extent_slices": [int(z) for z in np.flatnonzero(source_extent)],
            "extent_without_in_picture_seed": extent_without_seed,
            "unreadable_slices": unreadable,
            "statuses": status_counts,
            "key_slices": [int(z) for z in keys],
            "rule": "largest whole enclosed 2 mm section holding projected native fibula location seeds, refused where it holds the carried tibia's blocks; ties retained",
            "seed_note": "native section pixels are location seeds only; the coarse body is a reading, not a native fibula boundary",
        }
        if holder is not None:
            for row, (z, result) in enumerate(zip(read_slices, sections, strict=True)):
                support = (
                    f"{prefix}_fibula_body"
                    if result.body is not None
                    else f"{prefix}_fibula_seeds"
                )
                held = result.body if result.body is not None else result.seeds
                said.append(
                    observe_in(
                        own.record,
                        "fibula",
                        "native",
                        "reading",
                        (z,),
                        result.status,
                        int(np.count_nonzero(held)),
                        0.0,
                        support,
                        "coarse enclosed section and projected native fibula location seed on this slice, "
                        f"row {row} of the packed array; reading only, not the fibula boundary",
                        holder_artifact,
                        row,
                    )
                )
        for z in keys:
            mapping.smap.offer(
                "fibula",
                map_plane(
                    own,
                    "fibula",
                    z,
                    "largest whole enclosed 2 mm section holding native sagittal/coronal fibula location seeds",
                    "coarse_section",
                ),
                float(areas[z]),
                f"fibula_scout:{uid}",
            )
            planes_offered += 1
        if not keys:
            if volume is None:
                reason = "axial_volume_unavailable"
            elif depth_count == 0 and sources:
                reason = "axial_volume_empty"
            elif not sources:
                reason = "no_native_fibula_sections" + "".join(
                    f"; {u['series_uid']}={u['code']}" for u in unusable_sources
                )
            elif not read_slices:
                reason = "no_in_picture_fibula_seed_on_any_axial_slice" + "".join(
                    f"; {why}={len(zs)}_slices"
                    for why, zs in sorted(unreadable.items())
                )
            else:
                reason = "no_competent_coarse_section; " + ",".join(
                    f"{name}={count}" for name, count in sorted(status_counts.items())
                )
            summaries[uid]["refusal"] = reason
            missing.append(Unresolved("fibula", "native", uid, view, reason))
            mapping.smap.offer(
                "fibula",
                rel.unresolved_plane(
                    "fibula",
                    "axial",
                    rel.REFUSED,
                    reason=reason,
                    provenance="coarse_section",
                ),
                None,
                f"fibula_scout:{uid}",
            )
    if not targets:
        reason = "no_axial_series_for_fibula_key_plane"
        missing.append(Unresolved("fibula", "native", None, None, reason))
        mapping.smap.offer(
            "fibula",
            rel.unresolved_plane(
                "fibula",
                "axial",
                rel.REFUSED,
                reason=reason,
                provenance="coarse_section",
            ),
            None,
            "fibula_scout:no_axial_series",
        )
    if holder is not None:
        holder.record["fibula_key_planes"] = {
            **holder.record.get("fibula_key_planes", {}),
            **summaries,
        }
        keep_on_record(holder.record, said, missing)
    if planes_read:
        # the selection of the largest sections is the one consumer of the coarse sections; the
        # arrays kept on the holder are storage, which declares no read
        handed("fibula_key_planes", ("coarse_sections",))
        reads("fibula_key_planes", ("coarse_sections",), "fibula_key_slices")
    if planes_offered:
        handed("fibula_key_planes", ("key_slices",))
        reads("fibula_key_planes", ("key_slices",), "study_map")


# -- THE BONES: the femur's and the tibia's marrow body through depth, pointed planes, extent ----
# The carried places are thinned to a lattice of half a finer block before they are projected for
# the cheap profile, so that every block of the finer reading holds a place; the pointed planes are
# named against the carried places whole.
BONE_PLACES_STEP_MM = LIGAMENT_SMOOTH_MM / 2.0


def thinned(points_lps: np.ndarray) -> np.ndarray:
    """The places of a bone on a lattice of `BONE_PLACES_STEP_MM`: one place per cell, the cell's
    own corner, so the cheap profile projects thousands of places and not every pixel's. Places that
    are not finite are not places."""
    points = np.asarray(points_lps, dtype=np.float64).reshape(-1, 3)
    points = points[np.isfinite(points).all(axis=1)]
    if not len(points):
        return points
    cells = np.rint(points / BONE_PLACES_STEP_MM).astype(np.int64)
    low = cells.min(axis=0)
    # Python integers: the subtraction of two int64 extremes can wrap before the guard sees it
    span = [
        int(hi) - int(lo) + 1 for hi, lo in zip(cells.max(axis=0), low, strict=True)
    ]
    if span[0] * span[1] * span[2] >= 2**62:
        # a lattice too wide for one integer per cell: the rows themselves, sorted
        return np.unique(cells, axis=0) * BONE_PLACES_STEP_MM
    # One integer per cell, most significant column first, so that sorting the integers sorts the
    # rows (`np.unique(cells, axis=0)` sorts them as bytes, about 3.5 times slower on 200 thousand
    # places, measured): the same cells in the same order (`tests/test_thinned_places.py`).
    key = ((cells[:, 0] - low[0]) * span[1] + (cells[:, 1] - low[1])) * span[2] + (
        cells[:, 2] - low[2]
    )
    key = np.unique(key)
    rest, z = np.divmod(key, span[2])
    x, y = np.divmod(rest, span[1])
    cells = np.column_stack((x + low[0], y + low[1], z + low[2]))
    return cells * BONE_PLACES_STEP_MM


def bone_footprint(
    series: Series,
    z: int,
    frame: PlaneFrame,
    shape: tuple[int, int],
    places: np.ndarray,
    key: str,
) -> np.ndarray:
    """The pixels of slice z that a bone's carried `places` project onto along the slice's normal
    (`projected_places`, however far off the plane): where the bone could lie there, an upper bound
    and not its section. Made once for the series, the slice and the places (`key`, their digest)."""
    return once(
        "bone_footprint",
        (series.row.series_uid, z, key),
        lambda: handed_on(projected_places(places, frame, shape)),
    )


@dataclass(frozen=True)
class BoneProfile:
    """A bone's cheap profile through depth, one entry per slice of the series in stack order: the
    pointer's status (`FIBULA_POINTER_STATUS`, the same words), the supported broad marrow-body
    area in square millimetres (0.0 measured absent, NaN not read, not readable or cut), how many
    separate pieces the body has, whether a piece was merged with the other bone's places; the
    corridor's tiles (the bone's carried places and one tile round them), those of them that could
    hold marrow-like light and those the tiles' own extrema confirm wholly in the level; the native
    window of the finer reading, its block in millimetres and pixels (-1 where none) and the finer
    readings themselves (`fine`; the reference body on each block grid is the bone's own carried
    footprint); and the marrow light everything was read against."""

    status: np.ndarray
    area_mm2: np.ndarray
    pieces: np.ndarray
    merged: np.ndarray
    corridor: np.ndarray
    could: np.ndarray
    confirmed: np.ndarray
    window_rc: np.ndarray
    cell_mm: np.ndarray
    block_px: np.ndarray
    fine: tuple[FineReading, ...]
    light: float


def bone_profile(
    series: Series,
    stack: SquintStack,
    places: np.ndarray,
    others: np.ndarray,
    light: float,
    name: str,
    own_footprint: Callable[[int, PlaneFrame, tuple[int, int]], np.ndarray]
    | None = None,
    level: tuple[float, float] = LIKE_THE_TIBIA,
    visit: np.ndarray | None = None,
) -> BoneProfile:
    """One bone's cheap profile through the series' depth, without the lens: the whole depth, or
    the slices `visit` names (a slice not visited is not read, `not_read`: unknown, never empty).

    On each slice the corridor is the tiles the bone's carried `places` project onto and one tile
    round them (`tiles_touched`, `tiles_around`); no tile of it, and the bone's places lie off the
    picture: not read. A bone whose place is a relation to another (the patella, in front of the
    femur) gives `own_footprint` (slice, frame, shape -> the pixels where it could lie there), read
    in place of the projection of `places`; every other step is the same. The tiles' extrema over every tile a finer block with a pixel in the tile can
    touch (`could_hold_level_in_reach`, as the fibula's profile asks) say where the level of the
    bone's marrow, a quarter either way of its own `light` (`LIKE_THE_TIBIA`), cannot be: none can
    and none was blind, the corridor holds no marrow body (measured absent); none can but a tile in
    reach was unseen, unreadable. Where every tile that could is wholly inside the level (its own
    minimum and maximum are) the tiles confirm, and the body is the tiles', at the tile's own
    resolution, read by `carried_bone` against the bone's own tiles. Otherwise the finer reading
    runs over the window of the tiles that could, with `BONE_MM` of context (`block_medians` at
    `LIGAMENT_SMOOTH_MM`) and `marrow_body` reads it. A light that is not positive and finite is no
    anchor: every slice of the corridor is unreadable and none is excluded. Counts of both readings
    are on the ledger (`bones.cheap_readings`, `bones.tile_confirmations`,
    `bones.tile_exclusions`)."""
    reads("squint_stack", ("minimum", "maximum", "coverage", "bounds_rc"), name)
    depth = int(stack.median.shape[0])
    tiles = stack.median.shape[1:]
    bounds = stack.bounds_rc
    shape = (int(bounds[..., 1].max()), int(bounds[..., 3].max()))
    tile_px = (bounds[..., 1] - bounds[..., 0]) * (bounds[..., 3] - bounds[..., 2])
    status = np.full(depth, FIBULA_POINTER_STATUS["not_read"], dtype=np.int8)
    area = np.full(depth, np.nan)
    pieces = np.zeros(depth, dtype=np.int32)
    merged = np.zeros(depth, dtype=bool)
    corridor = np.zeros((depth, *tiles), dtype=bool)
    could = np.zeros((depth, *tiles), dtype=bool)
    confirmed = np.zeros((depth, *tiles), dtype=bool)
    window_rc = np.full((depth, 4), -1, dtype=np.int32)
    cell_mm = np.full((depth, 2), np.nan)
    cell_px = np.full((depth, 2), -1, dtype=np.int32)
    fine: list[FineReading] = []
    reach_of: dict[tuple[int, int], Any] = {}
    low, high = level
    anchored = bool(np.isfinite(light) and light > 0)
    own_key, other_key = digest(places), digest(others)
    finely = excluded = by_tiles = 0
    for z in range(depth):
        if visit is not None and not visit[z]:
            continue
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            status[z] = FIBULA_POINTER_STATUS["unreadable"]
            continue
        foot = (
            bone_footprint(series, z, frame, shape, places, own_key)
            if own_footprint is None
            else own_footprint(z, frame, shape)
        )
        if not foot.any():
            continue  # the bone's places lie off this slice's picture: nothing is said
        near = tiles_touched(foot, bounds)
        # a bone's footprint is an upper bound, so one tile of context is read round it; a
        # relation's corridor is already every tile that can hold a place of it
        corridor[z] = tiles_around(near) if own_footprint is None else near
        if not anchored:
            status[z] = FIBULA_POINTER_STATUS["unreadable"]
            continue
        block = block_pixels(frame.spacing_rc, LIGAMENT_SMOOTH_MM)
        if block not in reach_of:
            reach_of[block] = footprint_reach(bounds, block)
        lows, highs = stack.minimum[z], stack.maximum[z]
        possible, blind = could_hold_level_in_reach(
            lows, highs, low * light, high * light, reach_of[block]
        )
        could[z] = corridor[z] & possible
        inside = (
            np.isfinite(lows)
            & np.isfinite(highs)
            & (lows >= low * light)
            & (highs <= high * light)
        )
        confirmed[z] = corridor[z] & inside
        if not could[z].any():
            if (corridor[z] & blind).any():
                status[z] = FIBULA_POINTER_STATUS["unreadable"]
            else:
                status[z], area[z] = FIBULA_POINTER_STATUS["none"], 0.0
                excluded += 1
            continue
        other_foot = bone_footprint(series, z, frame, shape, others, other_key)
        if not (corridor[z] & blind).any() and (could[z] == confirmed[z]).all():
            # the tiles confirm: the body is the tiles', at the tile's own resolution
            by_tiles += 1
            other_near = tiles_touched(other_foot, bounds)
            kept = carried_bone(ndi.label(could[z])[0], near)
            body = kept & ~other_near
            merged[z] = bool((kept & other_near).any())
            pieces[z] = int(ndi.label(body)[1])
            seen_px = float(np.nansum((stack.coverage[z] * tile_px)[body]))
            total = seen_px * float(np.prod(frame.spacing_rc))
            status[z], area[z] = (
                (FIBULA_POINTER_STATUS["body"], total)
                if total > 0
                else (FIBULA_POINTER_STATUS["none"], 0.0)
            )
            cell_px[z] = stack.tile_shape_rc
            cell_mm[z] = np.asarray(stack.tile_shape_rc) * np.asarray(frame.spacing_rc)
            continue
        plane, unseen = seen_native(series, z, name)
        rows, cols = plane.shape
        spacing = np.asarray(frame.spacing_rc)
        held = bounds[could[z]]
        context = np.ceil(BONE_MM / spacing).astype(int)
        window = (
            max(0, int(held[:, 0].min()) - int(context[0])),
            min(rows, int(held[:, 1].max()) + int(context[0])),
            max(0, int(held[:, 2].min()) - int(context[1])),
            min(cols, int(held[:, 3].max()) + int(context[1])),
        )
        reading = block_medians(
            plane, unseen, frame.spacing_rc, LIGAMENT_SMOOTH_MM, window
        )
        open_edge = np.zeros(reading.median.shape, dtype=bool)
        open_edge[0, :] = window[0] > 0
        open_edge[-1, :] = window[1] < rows
        open_edge[:, 0] |= window[2] > 0
        open_edge[:, -1] |= window[3] < cols
        mine = block_holds(foot, reading)
        # a relation's corridor cuts the pieces where it ends: marrow-like blocks beyond it (the
        # femur's own marrow, in front of which the patella lies) never join a piece to the body
        median = (
            reading.median
            if own_footprint is None
            else np.where(mine, reading.median, np.nan)
        )
        got = marrow_body(
            median,
            reading.block_mm,
            light,
            level,
            mine,
            block_holds(other_foot, reading),
            open_edge,
        )
        finely += 1
        pieces[z], merged[z] = got.pieces, got.merged
        if got.cut:
            status[z] = FIBULA_POINTER_STATUS["cut"]
        elif got.area_mm2 > 0:
            status[z], area[z] = FIBULA_POINTER_STATUS["body"], got.area_mm2
        else:
            status[z], area[z] = FIBULA_POINTER_STATUS["none"], 0.0
        window_rc[z], cell_mm[z], cell_px[z] = (
            window,
            reading.block_mm,
            reading.block_px,
        )
        fine.append(
            FineReading(
                z,
                reading.window_rc,
                reading.block_px,
                reading.block_mm,
                reading.median,
                got.body,
                mine,
            )
        )
    ledger.record(f"{name}.cheap_readings", planes=finely)
    ledger.record(f"{name}.tile_confirmations", planes=by_tiles)
    ledger.record(f"{name}.tile_exclusions", planes=excluded)
    handed("bone_profile", ("status", "area_mm2"))
    # kept, not read: no stage after the profile reads the blocks or the bodies it drew
    handed("bone_profile", ("fine",))
    return BoneProfile(
        status,
        area,
        pieces,
        merged,
        corridor,
        could,
        confirmed,
        window_rc,
        cell_mm,
        cell_px,
        tuple(fine),
        float(light),
    )


@dataclass(frozen=True)
class BonePlane:
    """One plane the profile pointed to, as it was read: its `slice`, whether it is the series'
    `middle` slice (the bootstrap's own naming of the bone, `IDENTIFIED`), the `code` (an outcome of
    `knee.collapse.bones.OUTCOMES`, or `unreadable_geometry`), the lens's `labels` and `available`
    there (None for the middle slice, whose own arrays hold them, and where the frame cannot be
    read), the `region` named (the bone's whole section on the middle slice), the `naming`, and the
    shared crop-local lens reading for a non-middle plane."""

    slice: int
    middle: bool
    code: str
    labels: np.ndarray | None
    available: np.ndarray | None
    region: np.ndarray
    naming: Naming | None
    local_lens: "BoneLocalLens | None" = None


@dataclass(frozen=True)
class BonePlaneScope:
    """The native half-open crop selected from both bones' existing profile windows."""

    window_rc: tuple[int, int, int, int]
    code: str
    reason: str


@dataclass(frozen=True)
class BoneLocalLens:
    """One bounded lens reading and its crop-local measurements, before scattering for naming."""

    window_rc: tuple[int, int, int, int]
    scope_code: str
    scope_reason: str
    reading_code: str
    raw_crop: np.ndarray
    available_crop: np.ndarray
    dark_crop: np.ndarray
    distance_mm_crop: np.ndarray
    markers_crop: np.ndarray
    labels_crop: np.ndarray
    labels_full: np.ndarray
    available_full: np.ndarray


def integer_bounds(value: Any) -> tuple[int, int, int, int] | None:
    """(r0, r1, c0, c1) as integers when `value` is four finite whole numbers (Python or NumPy
    integers, or floats with no fraction); None for anything else (fractional, non-finite,
    boolean, a string, a wrong length or shape). Never truncates and never raises."""
    if isinstance(value, (str, bytes)):
        return None
    try:
        items = list(value)
    except (TypeError, ValueError):
        return None
    if len(items) != 4:
        return None
    bounds = []
    for item in items:
        if isinstance(item, (bool, np.bool_)):
            return None
        if isinstance(item, (int, np.integer)) or (
            isinstance(item, (float, np.floating))
            and np.isfinite(item)
            and float(item).is_integer()
        ):
            bounds.append(int(item))
        else:
            return None
    return (bounds[0], bounds[1], bounds[2], bounds[3])


def map_boxes_of(
    in_plane: Any,
) -> list[tuple[float, float, float, float]] | None:
    """The map's boxes (centre row, centre column, half-extents) that are four finite real numbers
    with nonnegative half-extents. None stays None (no map was asked); a collection that cannot be
    read gives no boxes (asked, nothing usable); a malformed member is left out. Never raises."""
    if in_plane is None:
        return None
    try:
        members = list(in_plane)
    except (TypeError, ValueError):
        return []
    boxes = []
    for member in members:
        if isinstance(member, (str, bytes)):
            continue
        try:
            items = list(member)
            if len(items) != 4 or any(
                isinstance(v, (bool, np.bool_))
                or not isinstance(v, (int, float, np.integer, np.floating))
                for v in items
            ):
                continue
            r, c, hr, hc = (float(v) for v in items)
        except (TypeError, ValueError, OverflowError):
            continue
        if np.isfinite((r, c, hr, hc)).all() and hr >= 0 and hc >= 0:
            boxes.append((r, c, hr, hc))
    return boxes


@dataclass(frozen=True)
class PatellaScope:
    """Where the patella question is measured: the half-open native `window_rc` (r0, r1, c0, c1),
    or None for the whole frame, with the `code` and `reason` that say why."""

    window_rc: tuple[int, int, int, int] | None
    code: str
    reason: str


def patella_scope(
    shape: tuple[int, int],
    profile_window: Any,
    boxes: Sequence[tuple[float, float, float, float]] | None,
    footprints: Sequence[np.ndarray],
) -> PatellaScope:
    """The clamped half-open union of the profile's window, the map's boxes (the pixels the peak
    filter accepts, `|p - centre| <= half`) and the bounding boxes of the nonempty bone footprints
    (calibration context, not segmentations). Without a usable profile window or map box the whole
    frame is read, and says why; a union that is the whole frame is named as such. Invalid inputs
    are named in the reason and never raise."""
    rows, cols = shape
    notes: list[str] = []

    def clamp(r0: int, r1: int, c0: int, c1: int):
        r0, c0 = max(r0, 0), max(c0, 0)
        r1, c1 = min(r1, rows), min(c1, cols)
        return (r0, r1, c0, c1) if r1 > r0 and c1 > c0 else None

    found: list[tuple[int, int, int, int]] = []
    sources: list[str] = []
    domain = False
    if profile_window is None:
        notes.append("profile_window_not_given")
    else:
        bounds = integer_bounds(profile_window)
        if bounds is None:
            notes.append("profile_window_invalid")
        else:
            got = clamp(*bounds)
            if got is None:
                notes.append("profile_window_empty_after_clamp")
            else:
                found.append(got)
                sources.append("profile_window")
                domain = True
                if got != bounds:
                    notes.append("profile_window_clamped")
    if not boxes:
        notes.append("map_boxes_not_given")
    else:
        taken = 0
        for r, c, hr, hc in boxes:
            got = clamp(
                int(np.ceil(r - hr)),
                int(np.floor(r + hr)) + 1,
                int(np.ceil(c - hc)),
                int(np.floor(c + hc)) + 1,
            )
            if got is None:
                notes.append("map_box_outside_frame")
            else:
                found.append(got)
                taken += 1
        if taken:
            sources.append("map_boxes")
            domain = True
    if not domain:
        return PatellaScope(
            None, "full_frame_no_profile_or_map_domain", ",".join(notes)
        )
    for name, foot in zip(
        ("femur_footprint", "tibia_footprint"), footprints, strict=False
    ):
        mask = np.asarray(foot, dtype=bool)
        if mask.shape != tuple(shape) or not mask.any():
            notes.append(f"{name}_empty")
            continue
        r_in, c_in = np.flatnonzero(mask.any(axis=1)), np.flatnonzero(mask.any(axis=0))
        found.append((int(r_in[0]), int(r_in[-1]) + 1, int(c_in[0]), int(c_in[-1]) + 1))
        sources.append(name)
    window = (
        min(w[0] for w in found),
        max(w[1] for w in found),
        min(w[2] for w in found),
        max(w[3] for w in found),
    )
    reason = ",".join(sources + notes)
    if window == (0, rows, 0, cols):
        return PatellaScope(None, "scope_union_is_full_frame", reason)
    return PatellaScope(window, "scope_union", reason)


def local_frame(frame: PlaneFrame, window: tuple[int, int, int, int]) -> PlaneFrame:
    """The frame of a native crop: the same basis and spacing, the origin moved to the crop's
    first pixel (`basis @ (r0, c0)`), so crop-local (row, column) lands on the same millimetres."""
    origin = frame.origin_lps + frame.basis_lps @ np.array(
        [window[0], window[2]], dtype=np.float64
    )
    return PlaneFrame(handed_on(origin), frame.basis_lps, frame.spacing_rc)


def scope_key(
    uid: str,
    z: int,
    window_rc: tuple[int, int, int, int],
    split: float,
    spacing_rc: Sequence[float],
) -> tuple:
    """What a scoped measurement of a slice depends on: the series, the slice, the window, the
    background split, the prominence and the pixel size. Two requests are the same measurement
    only when every one of these is."""
    return (
        uid,
        int(z),
        tuple(window_rc),
        float(split),
        float(PROMINENCE_MM),
        tuple(float(s) for s in spacing_rc),
    )


@dataclass(frozen=True)
class ScopedInterior:
    """The lens read once inside a native half-open window, for every family that asks the same
    scope: the cropped `raw`, the `finite` crop of the series' own finite support (`finite_of`,
    not recomputed), and the `reading` the original lens made there (crop-local). It carries no
    family's reason for the scope."""

    window_rc: tuple[int, int, int, int]
    split: float
    prominence_mm: float
    spacing_rc: tuple[float, float]
    raw: np.ndarray
    finite: np.ndarray
    reading: InteriorRegions


def scoped_interior_of(
    series: Series,
    index: int,
    plane: np.ndarray,
    spacing_rc: Sequence[float],
    split: float,
    window_rc: tuple[int, int, int, int],
    reader: str | None = None,
) -> ScopedInterior:
    """The original lens (`interior_regions`) measured only inside `window_rc`, once for the
    series, slice, window, split, prominence and pixel size. The crop is taken before any heavy
    work; availability is the series' finite support cropped from `finite_of`."""
    uid = series.row.series_uid
    spacing = (float(spacing_rc[0]), float(spacing_rc[1]))

    def read() -> ScopedInterior:
        reads("series", ("volume", "row", "slices"), "interiors")
        reads("background", ("split",), "interiors")
        r0, r1, c0, c1 = window_rc
        window = (slice(r0, r1), slice(c0, c1))
        raw = np.asarray(plane)[window].copy()
        finite = np.asarray(finite_of(series)[index][window], dtype=bool)
        reading = interior_regions(raw, spacing, split, PROMINENCE_MM, available=finite)
        handed("interiors", field_names(reading))
        if reader is not None:
            ledger.record(f"{reader}.lens_readings", planes=1)
        ledger.record(
            "interiors.work", planes=1, territories=int(reading.labels.max(initial=0))
        )
        ledger.record(
            "scoped_interior.work",
            window_pixels=int(raw.size),
            full_frame_pixels=int(np.asarray(plane).size),
        )
        record = ScopedInterior(
            tuple(window_rc),
            float(split),
            float(PROMINENCE_MM),
            spacing,
            handed_on(raw),
            handed_on(finite),
            reading,
        )
        handed("scoped_interior", field_names(record))
        return record

    return once(
        "scoped_interior", scope_key(uid, index, window_rc, split, spacing), read
    )


def bone_local_lens_of(
    series: Series,
    index: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    split: float,
    scope: BonePlaneScope,
    reader: str,
) -> BoneLocalLens:
    """Read the established lens inside a shared profile window, once for the slice and box: the
    measurement is the shared scoped interior (`scoped_interior_of`, also read by the patella for
    the same scope); this keeps the bones' scope metadata and scatters it to the native shape."""

    def read() -> BoneLocalLens:
        values = np.asarray(plane)
        r0, r1, c0, c1 = scope.window_rc
        window = (slice(r0, r1), slice(c0, c1))
        shared = scoped_interior_of(
            series, index, values, frame.spacing_rc, split, scope.window_rc, reader
        )
        reading = shared.reading
        reads("scoped_interior", ("raw", "reading"), "bones.local_lens")
        reads("interiors", ("labels", "available"), "bones.local_lens")
        labels_full = np.zeros(values.shape, dtype=reading.labels.dtype)
        available_full = np.zeros(values.shape, dtype=bool)
        labels_full[window] = reading.labels
        available_full[window] = reading.available
        handed(
            "bone_local_lens",
            (
                "window_rc",
                "scope_code",
                "scope_reason",
                "reading_code",
                "raw_crop",
                "available_crop",
                "dark_crop",
                "distance_mm_crop",
                "markers_crop",
                "labels_crop",
                "labels_full",
                "available_full",
            ),
        )
        ledger.record(
            "bones.local_lens_pixels",
            window_pixels=int(shared.raw.size),
            full_frame_pixels=int(values.size),
            full_frame_fallback=int(scope.code.startswith("full_frame_fallback")),
        )
        return BoneLocalLens(
            scope.window_rc,
            scope.code,
            scope.reason,
            reading.code,
            shared.raw,
            handed_on(np.asarray(reading.available, dtype=bool)),
            reading.dark,
            reading.distance_mm,
            reading.markers,
            reading.labels,
            handed_on(labels_full),
            handed_on(available_full),
        )

    return once(
        "bone_local_lens",
        (
            scope_key(
                series.row.series_uid, index, scope.window_rc, split, frame.spacing_rc
            ),
            scope.code,
            scope.reason,
        ),
        read,
    )


@dataclass(frozen=True)
class PatellaScopeContext:
    """One slice and window as the patella measures it, shared by every request for it: the
    shared scoped `interior`, the crop's `frame`, its black `outside` (`margin` of the crop), the
    `field` read there and the slice's `measures` (keyed by series, slice and window)."""

    window_rc: tuple[int, int, int, int]
    interior: ScopedInterior
    frame: PlaneFrame
    outside: np.ndarray
    field: Field
    measures: Measures


def patella_scope_of(
    series: Series,
    z: int,
    plane: np.ndarray,
    frame: PlaneFrame,
    split: float,
    window: tuple[int, int, int, int],
    reader: str,
) -> PatellaScopeContext:
    """The original field measured inside `window` on the shared scoped interior, once per
    series, slice and window. Its black margin is the crop's own (a scoped measurement: its
    connectivity is the crop's). Never shares a key with the full-frame lens, field or margin."""
    uid = series.row.series_uid

    def read() -> PatellaScopeContext:
        shared = scoped_interior_of(
            series, z, plane, frame.spacing_rc, split, window, reader
        )
        reads("scoped_interior", ("raw", "reading"), reader)
        local = local_frame(frame, window)
        reads("interiors", ("dark", "labels", "distance_mm"), "field")
        outside = handed_on(margin(shared.raw))
        field = read_field(shared.raw, shared.reading, local.basis_lps, outside)
        handed("field", field_names(field))
        ledger.record(
            "patella.scope_pixels",
            window_pixels=int(shared.raw.size),
            full_frame_pixels=int(np.size(plane)),
        )
        context = PatellaScopeContext(
            window,
            shared,
            local,
            outside,
            field,
            Measures((uid, z, window), shared.raw, local.basis_lps),
        )
        handed("patella_scope", field_names(context))
        return context

    return once(
        "patella_scope", scope_key(uid, z, window, split, frame.spacing_rc), read
    )


@dataclass(frozen=True)
class PatellaAttempt:
    """One bounded reading kept whole, in crop-local coordinates unless said native: its
    `window_rc` (native, half-open), the scope's code and reason, the patella `code` it reached
    with the `femur`/`tibia` codes, all part `codes` and the `where` of the guidance, the lens's
    `reading_code`, the field's `field_codes` and `axes_in_plane` (side to side, front to back,
    along the leg), the femur's marrow `light` and `body_held`, the crop's frame
    (`frame_origin_lps`, `frame_basis_lps`), and every array computed: `raw`, `finite`, `dark`,
    `distance_mm`, `markers`, `labels`, `available`, `outside` (the crop's margin), the field's
    `leg` and `field_objects`, and the naming `objects`. `peak` is native (row, column); each row
    of `peaks` is (territory, depth_mm, native row, native column, local_superior_mm), deepest first."""

    window_rc: tuple[int, int, int, int]
    scope_code: str
    scope_reason: str
    code: str
    femur: str
    tibia: str
    codes: dict[str, str]
    where: str
    reading_code: str
    field_codes: dict[str, str]
    axes_in_plane: tuple[bool, bool, bool]
    light: float | None
    body_held: int | None
    frame_origin_lps: np.ndarray
    frame_basis_lps: np.ndarray
    raw: np.ndarray
    finite: np.ndarray
    dark: np.ndarray
    distance_mm: np.ndarray
    markers: np.ndarray
    labels: np.ndarray
    available: np.ndarray
    outside: np.ndarray
    leg: np.ndarray
    field_objects: np.ndarray
    objects: np.ndarray
    peak: tuple[int, int] | None
    peaks: np.ndarray


@dataclass(frozen=True)
class PatellaPlane:
    """One plane the profile pointed to, as the patella's own rule read it: its `slice`, whether it
    is the series' `middle` slice (the bootstrap's own naming, not read again), the patella's
    `code` (`PATELLA_OUTCOMES`, or `UNREADABLE_GEOMETRY`), the `codes` of the parts the plane's
    naming made (`PLANE_PARTS`), what the carried places named of the femur and the tibia
    (`femur`, `tibia`: `knee.collapse.bones` outcomes), the lens's `labels` and `available`, the
    plane's own naming `objects` (int8, `OBJECT_CODES`: the bones, the joint, the patella, the
    fluid and the two pads beside the patella; the tendons are laid on afterwards), the
    `peak` the patella was read at and the femur's marrow `light`, and how many pixels of the
    profile's marrow body the patella holds (`body_held`, None where the profile read none here).

    A bounded reading scatters into the full shape: outside its `window_rc` the plane is
    unavailable (labels 0, available False), not air. `window_rc` is None for a whole-frame
    reading; `scope_code`/`scope_reason` say how the scope was chosen, or why it was broadened;
    `attempts` keep every bounded reading made, including one that missed."""

    slice: int
    middle: bool
    code: str
    codes: dict[str, str]
    femur: str
    tibia: str
    labels: np.ndarray | None
    available: np.ndarray | None
    objects: np.ndarray | None
    peak: tuple[int, int] | None
    light: float | None
    body_held: int | None
    in_plane: str = "unguided_in_plane"
    window_rc: tuple[int, int, int, int] | None = None
    scope_code: str = "full_frame_unscoped"
    scope_reason: str = ""
    attempts: tuple[PatellaAttempt, ...] = ()


@dataclass(frozen=True)
class PatellaNaming:
    """What the patella's rule named on one domain (a crop or the whole frame), in that domain's
    own coordinates: the bones' codes, the naming `objects`, the `peak_rc` read at, the femur's
    `light`, the parts' `codes`, which peaks were looked at (`where`) and `held`."""

    femur: str
    tibia: str
    objects: np.ndarray
    peak_rc: tuple[int, int] | None
    light: float | None
    codes: dict[str, str]
    where: str
    held: int | None


def patella_named(
    series: Series,
    plane: np.ndarray,
    labels: np.ndarray,
    available: np.ndarray,
    field: Field,
    outside: np.ndarray,
    measures: Measures,
    basis: np.ndarray,
    femur_foot: np.ndarray,
    tibia_foot: np.ndarray,
    boxes: list[tuple[float, float, float, float]] | None,
    body: np.ndarray | None,
) -> PatellaNaming:
    """The patella's established rule and the fat beside it on one domain, exactly as
    `patella_plane` always read them; every array is in the domain's own coordinates."""
    shape = plane.shape
    femur = name_territory(labels, available, femur_foot, tibia_foot)
    tibia = name_territory(labels, available, tibia_foot, femur_foot)
    none = np.zeros(shape, dtype=bool)
    femur_places = femur.region if femur.code == IDENTIFIED else none
    tibia_places = tibia.region if tibia.code == IDENTIFIED else none
    objects = field.objects.copy()
    objects[femur_places] = OBJECT_CODES["femur"]
    objects[tibia_places] = OBJECT_CODES["tibia"]
    spacing = np.linalg.norm(basis, axis=0)
    front_in_plane = bool(field.in_plane[1])
    bones_named = bool(femur_places.any() and tibia_places.any())
    if bones_named:
        joint = (
            between_along_the_leg(femur_places, tibia_places, basis)
            & (objects == 0)
            & ~outside
        )
        objects[joint] = OBJECT_CODES["joint"]
    # the patella: the deepest peak in front of the femur, the piece as bright as its marrow
    light = float(measures.light(femur_places)) if femur_places.any() else None

    def attempt(peaks):
        found = (
            patella_peak(peaks, femur_places, basis)
            if front_in_plane and femur_places.any()
            else None
        )
        cut = none
        if found is not None and light is not None:
            cut = patella_piece(plane, labels, found, light, spacing) & (objects == 0)
        return (
            found,
            cut,
            patella_code(
                front_in_plane,
                bool(femur_places.any()),
                True,
                found is not None,
                bool(cut.any()),
            ),
        )

    # the map's expectation of where in this domain the patella lies is looked at first: only the
    # peaks inside it; where that names nothing, every peak, as before (the fallback)
    where = "unguided_in_plane"
    if boxes is not None:
        inside = [
            pk
            for pk in field.peaks
            if any(
                abs(pk.peak_rc[0] - r) <= hr and abs(pk.peak_rc[1] - c) <= hc
                for r, c, hr, hc in boxes
            )
        ]
        peak, piece, code = attempt(inside)
        where = "map_in_plane_hit"
        if code != "identified":
            peak, piece, code = attempt(field.peaks)
            where = "map_in_plane_miss_all_peaks"
    else:
        peak, piece, code = attempt(field.peaks)
    codes = {"patella": code}
    territory = peak.territory if peak is not None and code == "identified" else None
    if territory is not None:
        objects[piece] = OBJECT_CODES["patella"]
    # the joint's fluid: white against the bones' marrow, in the joint's recesses
    fluid_bright = int(series.row.fluid_sensitive) == 1
    white = (
        white_as_fluid(plane, objects, measures)
        if fluid_bright and bones_named
        else None
    )
    fluid = none
    if white is not None:
        fluid = fluid_in_the_recesses(
            white, objects, field.leg, outside, spacing, measures
        )
    codes["joint_fluid"] = fluid_code(fluid_bright, bones_named, bool(fluid.any()))
    objects[fluid] = OBJECT_CODES["joint_fluid"]
    # Hoffa's fat pad and the suprapatellar fat: the rest of the patella's territory beyond it
    patella_places = objects == OBJECT_CODES["patella"]
    for name, upward in (("hoffa_fat_pad", False), ("suprapatellar_fat", True)):
        pad = none
        if front_in_plane and territory is not None:
            pad = rest_of_the_patellas_territory(
                labels, territory, patella_places, objects, basis, upward, measures
            )
        codes[name] = fat_pad_code(
            front_in_plane, True, territory is not None, bool(pad.any()), upward
        )
        objects[pad] = OBJECT_CODES[name]
    held = (
        None
        if body is None
        else int(np.count_nonzero(body & (objects == OBJECT_CODES["patella"])))
    )
    return PatellaNaming(
        femur.code,
        tibia.code,
        objects,
        None if peak is None else (int(peak.peak_rc[0]), int(peak.peak_rc[1])),
        light,
        codes,
        where,
        held,
    )


def patella_plane(
    own: Measured,
    z: int,
    femur_lps: np.ndarray,
    tibia_lps: np.ndarray,
    keys: tuple[str, str],
    body: np.ndarray | None,
    reader: str = "patella",
    in_plane: Sequence[tuple[float, float, float, float]] | None = None,
    *,
    profile_window: Any = None,
) -> PatellaPlane:
    """The patella's established rule, and the fat beside it, on ONE pointed plane of a
    fat-suppressed series: the lens and its field, the femur and the tibia named by the carried
    places (`name_territory`, the established `carried_bone`); the patella by `patella_peak` and
    `patella_piece` against that femur's marrow light, as `assign_plane` reads them; then the
    joint, the joint's fluid, Hoffa's fat pad and the suprapatellar fat as it names them. Nothing
    here is a new definition, and the rest of `assign_plane` is not run. `body` is the profile's
    marrow body on this plane's pixels, kept against the piece as a second measurement.

    The question is asked locally first: the original lens and field are measured only inside the
    scope (`patella_scope`: the profile's window on this plane `profile_window`, the map's boxes
    and the bones' footprints), a useful prior and not a boundary. Where no profile window or map
    box gives a domain, or the union is the whole frame, the whole frame is read as before, with
    the reason named. Where the local reading does not name the patella, it is kept whole
    (`attempts`) and the whole frame is read, named as a broadening: a miss of the prior, not an
    absence."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return PatellaPlane(
            z,
            False,
            UNREADABLE_GEOMETRY,
            {},
            "",
            "",
            None,
            None,
            None,
            None,
            None,
            None,
        )
    plane = np.asarray(series.volume[z])
    shape = plane.shape
    split = float(record["background_split"])
    boxes = map_boxes_of(in_plane)
    if body is not None:
        body = np.asarray(body, dtype=bool)
        if body.shape != shape:
            body = None
    femur_foot = bone_footprint(series, z, frame, shape, femur_lps, keys[0])
    tibia_foot = bone_footprint(series, z, frame, shape, tibia_lps, keys[1])
    scope = patella_scope(shape, profile_window, boxes, (femur_foot, tibia_foot))

    def whole(
        code: str, reason: str, attempts: tuple[PatellaAttempt, ...]
    ) -> PatellaPlane:
        _, reading, _ = lens_of(series, z, plane, frame, split, reader)
        field = field_of(series, z, plane, frame, reading)
        reads("interiors", ("labels", "available"), reader)
        reads("field", ("objects", "peaks", "leg"), reader)
        labels, available = reading.labels, np.asarray(reading.available, dtype=bool)
        named = patella_named(
            series,
            plane,
            labels,
            available,
            field,
            margin_of(uid, z, plane),
            measures_of(uid, z, plane, frame),
            frame.basis_lps,
            femur_foot,
            tibia_foot,
            boxes,
            body,
        )
        handed("patella_plane", ("objects",))
        return PatellaPlane(
            z,
            False,
            named.codes["patella"],
            named.codes,
            named.femur,
            named.tibia,
            labels,
            available,
            handed_on(named.objects),
            named.peak_rc,
            named.light,
            named.held,
            named.where,
            None,
            code,
            reason,
            attempts,
        )

    window = scope.window_rc
    if window is None:
        ledger.record("patella.scope_full_frame", planes=1)
        return whole(scope.code, scope.reason, ())
    r0, r1, c0, c1 = window
    crop = (slice(r0, r1), slice(c0, c1))
    context = patella_scope_of(series, z, plane, frame, split, window, reader)
    reads("interiors", ("labels", "available"), reader)
    reads("field", ("objects", "peaks", "leg"), reader)
    reads(
        "patella_scope", ("frame", "outside", "field", "measures", "interior"), reader
    )
    reads("scoped_interior", ("raw", "finite", "reading"), reader)
    reading, field = context.interior.reading, context.field
    local_available = np.asarray(reading.available, dtype=bool)
    named = patella_named(
        series,
        context.interior.raw,
        reading.labels,
        local_available,
        field,
        context.outside,
        context.measures,
        context.frame.basis_lps,
        femur_foot[crop],
        tibia_foot[crop],
        None if boxes is None else [(r - r0, c - c0, hr, hc) for r, c, hr, hc in boxes],
        None if body is None else body[crop],
    )
    peak = (
        None
        if named.peak_rc is None
        else (named.peak_rc[0] + r0, named.peak_rc[1] + c0)
    )
    attempt = PatellaAttempt(
        window,
        scope.code,
        scope.reason,
        named.codes["patella"],
        named.femur,
        named.tibia,
        named.codes,
        named.where,
        reading.code,
        dict(field.codes),
        (
            bool(field.in_plane[0]),
            bool(field.in_plane[1]),
            bool(field.in_plane[2]),
        ),
        named.light,
        named.held,
        context.frame.origin_lps,
        context.frame.basis_lps,
        context.interior.raw,
        context.interior.finite,
        reading.dark,
        reading.distance_mm,
        reading.markers,
        reading.labels,
        local_available,
        context.outside,
        field.leg,
        field.objects,
        handed_on(named.objects),
        peak,
        np.asarray(
            [
                (
                    pk.territory,
                    pk.depth_mm,
                    pk.peak_rc[0] + r0,
                    pk.peak_rc[1] + c0,
                    pk.superior_mm,
                )
                for pk in field.peaks
            ],
            dtype=np.float64,
        ).reshape(-1, 5),
    )
    if named.codes["patella"] != "identified":
        ledger.record("patella.scope_broadened", planes=1)
        return whole(
            "broadened_full_frame_local_scope_missed",
            f"{scope.code}:{scope.reason};local_patella_code={named.codes['patella']}",
            (attempt,),
        )
    ledger.record("patella.scope_local", planes=1)
    labels = np.zeros(shape, dtype=reading.labels.dtype)
    available = np.zeros(shape, dtype=bool)
    objects = np.zeros(shape, dtype=np.int8)
    labels[crop] = reading.labels
    available[crop] = local_available
    objects[crop] = named.objects
    handed("patella_plane", ("objects",))
    return PatellaPlane(
        z,
        False,
        named.codes["patella"],
        named.codes,
        named.femur,
        named.tibia,
        handed_on(labels),
        handed_on(available),
        handed_on(objects),
        peak,
        named.light,
        named.held,
        named.where,
        window,
        scope.code,
        scope.reason,
        (attempt,),
    )


@dataclass(frozen=True)
class BoneRead:
    """One bone in one series, as `read_bone` read it: the profile, the planes it pointed to, how
    the bone came out (`outcome`: identified, ambiguous, unresolved, unreadable, no_body_found), the
    record's description of it (`record`, plain data) and the arrays it keeps (`arrays`, named
    `a3_<bone>_*`; the lens's labels of the pointed planes are kept once for both bones by
    `keep_bone_planes`)."""

    bone: str
    profile: BoneProfile
    planes: tuple[BonePlane, ...]
    outcome: str
    record: dict
    arrays: dict[str, np.ndarray]
    sections: tuple[tuple[int, np.ndarray, PlaneFrame], ...]


def body_pixels(fine: FineReading, shape: tuple[int, int]) -> np.ndarray:
    """A finer reading's marrow body on the plane's own pixels (`shape`): each block's pixels over
    its window, nothing outside the window."""
    r0, r1, c0, c1 = fine.window_rc
    wide = np.repeat(
        np.repeat(fine.body, fine.block_px[0], axis=0), fine.block_px[1], axis=1
    )
    found = np.zeros(shape, dtype=bool)
    found[r0:r1, c0:c1] = wide[: r1 - r0, : c1 - c0]
    return found


def series_depth(
    series: Series, middle: PlaneFrame, index: int
) -> tuple[np.ndarray, np.ndarray, np.ndarray, bool]:
    """A series' slice origins (empty where unsound), thicknesses (NaN where a header gives none),
    each slice's place along the middle slice's normal in the scanner's millimetres
    (`depth_offsets_mm`, whatever order and spacing the stack has; NaN where unsound), and whether
    the geometry is sound: finite origins for every slice."""
    reads("series", ("geometry", "slice_thickness_mm"), "bones")
    depth = len(series.volume) if series.volume is not None else 0
    origins = np.asarray(
        [np.asarray(p, dtype=float) for p in series.geometry.position]
        if series.geometry is not None
        else [],
        dtype=float,
    )
    thick = np.asarray(
        [np.nan if t is None else float(t) for t in series.slice_thickness_mm],
        dtype=float,
    )
    sound = bool(
        origins.ndim == 2
        and origins.shape == (depth, 3)
        and np.all(np.isfinite(origins))
        and len(thick) == depth
    )
    offsets = (
        depth_offsets_mm(origins, middle.normal(), index)
        if sound
        else np.full(depth, np.nan)
    )
    return (origins if sound else np.empty((0, 3))), thick, offsets, sound


def describe_runs(
    runs: list[tuple[int, int]],
    status: np.ndarray,
    offsets: np.ndarray,
    thick: np.ndarray,
    sound: bool,
) -> tuple[list[dict], np.ndarray, np.ndarray]:
    """The profile's runs of support as ENVELOPES over their sampled slabs, never dense occupancy:
    for each its slices, its envelope along the series' normal in the scanner's millimetres
    (`support_intervals_mm`), the sampled slabs and the gaps between them (`run_slabs_mm`,
    `slab_gaps_mm`) and what each end touches (`run_neighbours`: the scan's edge, a measured
    absence, an unread or unreadable slice). Also the ends and envelopes as arrays."""
    ends = run_neighbours(runs, status)
    spans = (
        support_intervals_mm(offsets, thick, runs)
        if sound
        else np.full((len(runs), 2), np.nan)
    )
    found = []
    for (a, b), end, (lo, hi) in zip(runs, ends, spans, strict=True):
        slabs = run_slabs_mm(offsets, thick, [(a, b)])[0] if sound else np.empty((0, 2))
        found.append(
            {
                "slices": [int(a), int(b) - 1],
                "envelope_mm": [finite_or_none(lo), finite_or_none(hi)],
                "slabs_mm": [[finite_or_none(v) for v in row] for row in slabs],
                "gaps_mm": [
                    finite_or_none(v)
                    for v in (slab_gaps_mm(slabs) if len(slabs) else [])
                ],
                "occupancy": "envelope_over_the_sampled_slabs_never_dense",
                "ends": [RUN_END_NAMES[int(e)] for e in end],
            }
        )
    return found, ends, spans


def merge_profiles(
    first: BoneProfile, second: BoneProfile, visited: np.ndarray
) -> BoneProfile:
    """Two profiles of the same series and bone, the second read on the slices `visited` and the
    first on the others: each slice's entries are those of the profile that read it, so the two
    together are the profile of the whole depth (`bone_profile` with no `visit`)."""

    def take(a: np.ndarray, b: np.ndarray) -> np.ndarray:
        return np.where(visited.reshape(-1, *([1] * (a.ndim - 1))), b, a)

    return BoneProfile(
        take(first.status, second.status),
        take(first.area_mm2, second.area_mm2),
        take(first.pieces, second.pieces),
        take(first.merged, second.merged),
        take(first.corridor, second.corridor),
        take(first.could, second.could),
        take(first.confirmed, second.confirmed),
        take(first.window_rc, second.window_rc),
        take(first.cell_mm, second.cell_mm),
        take(first.block_px, second.block_px),
        tuple(sorted(first.fine + second.fine, key=lambda f: f.index)),
        first.light,
    )


def bone_reading_basis(
    own: Measured, bone: str, places: np.ndarray
) -> tuple[np.ndarray, float] | str:
    """What a bone's cheap profile in one series is read against: the bone's section on the
    series' middle slice (the bootstrap's own naming) and its marrow light there; or why the series
    cannot be read for this bone, a string code, an unknown and never an absence. Only a series
    without fat suppression is profiled (its marrow is the light the level is read against; a
    fat-suppressed twin is handed the bone by place), and only one that named the bone on its
    middle slice, whose marrow light is the anchor."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    mask = own.arrays["a1_objects"] == OBJECT_CODES[bone]
    if record["assignments"][bone] is None or not mask.any():
        return "bone_not_named_on_the_middle_slice"
    if int(series.row.fat_suppression) != 0:  # the tag is stored as text
        return "fat_suppressed_not_profiled"
    reads("squint_stack", ("code",), "bones")
    if own.stack.code != "present":
        return f"squint_{own.stack.code}"
    if series.volume is None:
        return "no_stacked_volume"
    if not len(places):
        return "no_carried_places"
    light = float(
        measures_of(
            uid, record["slice_index"], own.arrays["acquired_plane"], own.frame
        ).light(mask)
    )
    return mask, light


def bone_profile_of(
    own: Measured, bone: str, places: np.ndarray, others: np.ndarray, light: float
) -> BoneProfile:
    """One bone's cheap profile through the whole depth of one series, made once per series, bone,
    carried places and light, and handed to every stage that asks for it (the study's reference,
    which reads it first, and the bone's own pointed planes)."""
    return once(
        "bone_profile",
        (
            own.series.row.series_uid,
            bone,
            digest(places),
            digest(others),
            light,
            None,
        ),
        lambda: bone_profile(
            own.series, own.stack, thinned(places), thinned(others), light, "bones"
        ),
    )


def _profile_window_at(
    profile: BoneProfile | str, z: int, shape: tuple[int, int], bone: str
) -> tuple[tuple[int, int, int, int] | None, str]:
    """Read one profile window, clamping a valid half-open box to its native plane."""
    if isinstance(profile, str):
        return None, f"{bone}_profile_unavailable:{profile}"
    windows = np.asarray(profile.window_rc)
    if (
        windows.ndim != 2
        or windows.shape[1] != 4
        or z < 0
        or z >= windows.shape[0]
        or not np.issubdtype(windows.dtype, np.integer)
    ):
        return None, f"{bone}_profile_window_malformed"
    raw = tuple(int(value) for value in windows[z])
    if raw == (-1, -1, -1, -1):
        return None, f"{bone}_profile_no_fine_window"
    if any(value < 0 for value in raw):
        return None, f"{bone}_profile_window_malformed"
    rows, cols = shape
    r0, r1, c0, c1 = raw
    clipped = (
        max(0, min(rows, r0)),
        max(0, min(rows, r1)),
        max(0, min(cols, c0)),
        max(0, min(cols, c1)),
    )
    if not (clipped[0] < clipped[1] and clipped[2] < clipped[3]):
        return None, f"{bone}_profile_window_empty_after_clamp"
    return clipped, f"{bone}_profile_window_clamped" if clipped != raw else "present"


def bone_plane_window_map(
    profiles: dict[str, BoneProfile | str],
    shapes: Sequence[tuple[int, int]],
) -> dict[int, BonePlaneScope]:
    """Union useful existing marrow-profile windows per slice; fall back only when none exist."""
    scopes: dict[int, BonePlaneScope] = {}
    for z, shape in enumerate(shapes):
        femur, femur_code = _profile_window_at(profiles["femur"], z, shape, "femur")
        tibia, tibia_code = _profile_window_at(profiles["tibia"], z, shape, "tibia")
        named_windows = (
            ("femur", femur, femur_code),
            ("tibia", tibia, tibia_code),
        )
        useful = [
            (bone, box, code) for bone, box, code in named_windows if box is not None
        ]
        if useful:
            boxes = [box for _, box, _ in useful]
            r0 = min(box[0] for box in boxes)
            r1 = max(box[1] for box in boxes)
            c0 = min(box[2] for box in boxes)
            c1 = max(box[3] for box in boxes)
            missing = ";".join(code for _, box, code in named_windows if box is None)
            scopes[z] = BonePlaneScope(
                (r0, r1, c0, c1),
                "profile_window_union" if len(useful) == 2 else "profile_window_single",
                ";".join(f"{bone}_{code}" for bone, _, code in useful)
                + (f";missing_{missing}" if missing else ""),
            )
            continue
        rows, cols = shape
        missing = ";".join(
            code
            for box, code in ((femur, femur_code), (tibia, tibia_code))
            if box is None
        )
        scopes[z] = BonePlaneScope(
            (0, rows, 0, cols),
            "full_frame_fallback_missing_profile_window",
            missing,
        )
    return scopes


def bone_plane_read(
    own: Measured,
    bone: str,
    z: int,
    places: np.ndarray,
    others: np.ndarray,
    profile: BoneProfile,
    reader: str = "bones",
    *,
    plane_windows: dict[int, BonePlaneScope] | None = None,
) -> BonePlane:
    """One plane a bone's profile pointed to, read natively and once: the series' middle slice is
    the bootstrap's own naming (not read again); any other is the lens on the union of both bones'
    profile windows (or a named full-frame fallback) and the established carried-bone rule
    (`name_territory`) against the bone's carried places,
    with the profile's marrow body there as a second measurement. Made once for the series, bone,
    plane and places, so the study's reference and the bone's own reading share the plane."""
    series, record = own.series, own.record
    shape = np.shape(own.arrays["acquired_plane"])
    own_key, other_key = digest(places), digest(others)
    scope = None if plane_windows is None else plane_windows.get(z)
    if scope is None:
        rows, cols = shape
        scope = BonePlaneScope(
            (0, rows, 0, cols),
            "full_frame_fallback_missing_profile_window_map",
            "no_shared_profile_window_for_slice",
        )

    def read() -> BonePlane:
        if z == record["slice_index"]:
            mask = own.arrays["a1_objects"] == OBJECT_CODES[bone]
            return BonePlane(z, True, IDENTIFIED, None, None, mask, None)
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            return BonePlane(
                z,
                False,
                "unreadable_geometry",
                None,
                None,
                np.zeros(shape, dtype=bool),
                None,
            )
        local_lens = bone_local_lens_of(
            series,
            z,
            np.asarray(series.volume[z]),
            frame,
            float(record["background_split"]),
            scope,
            reader,
        )
        reads(
            "bone_local_lens",
            (
                "window_rc",
                "scope_code",
                "scope_reason",
                "reading_code",
                "labels_full",
                "available_full",
            ),
            reader,
        )
        fine = next((f for f in profile.fine if f.index == z), None)
        naming = name_territory(
            local_lens.labels_full,
            local_lens.available_full,
            bone_footprint(series, z, frame, shape, places, own_key),
            bone_footprint(series, z, frame, shape, others, other_key),
            None if fine is None else body_pixels(fine, shape),
        )
        return BonePlane(
            z,
            False,
            naming.code,
            local_lens.labels_full,
            local_lens.available_full,
            naming.region,
            naming,
            local_lens,
        )

    return once(
        "bone_plane",
        (
            series.row.series_uid,
            bone,
            z,
            own_key,
            other_key,
            scope.window_rc,
            scope.code,
            scope.reason,
        ),
        read,
    )


def read_bone(
    own: Measured,
    bone: str,
    places: np.ndarray,
    others: np.ndarray,
    extra_planes: Collection[int] = (),
    *,
    plane_windows: dict[int, BonePlaneScope] | None = None,
) -> BoneRead | str:
    """One bone of one series: the cheap profile of its marrow body through the whole depth
    (`bone_profile`), the pointed planes (each run of support's maximum, every tie kept, every run
    kept, and the slice beside a maximum where the window cut the body: `positive_runs`,
    `run_maxima`, `confirmations`), and on only those planes the lens (the shared union of both
    bones' existing profile windows, with a named full-frame fallback) against the bone's carried places
    (`name_territory`, the established `carried_bone`); the series' middle slice is the bootstrap's
    own naming and is not read again. Its physical extent along the leg is the heights of the
    sections named (the middle slice's and every pointed plane that identified it), each end
    observed, clipped by the scan or unresolved (`section_extent`); the pointed planes' places
    along the stack's normal in the scanner's millimetres are kept. Or why the series cannot be
    read for this bone: a string code, an unknown and never an absence.

    `extra_planes` are planes the OTHER bone was pointed to: the joint lies between the two, so a
    plane that points for one is asked of both (`name_the_bones`). The bounded lens is shared by
    its series, slice and native window, and only where this bone's own profile read a marrow body
    finely there (a bone's identity needs its body: a plane without one stays unasked, not absent).

    Only a series without fat suppression is profiled (its marrow is the light the level is read
    against; a fat-suppressed twin is handed the bone by place); and only one that named the bone
    on its middle slice, whose marrow light is the anchor."""
    basis = bone_reading_basis(own, bone, places)
    if isinstance(basis, str):
        return basis
    mask, light = basis
    series, record = own.series, own.record
    index = record["slice_index"]
    profile = bone_profile_of(own, bone, places, others, light)
    reads("bone_profile", ("status", "area_mm2"), "bones")
    reads("bone_profile", ("fine",), "bones")
    runs = positive_runs(profile.area_mm2)
    maxima = run_maxima(profile.area_mm2, runs)
    confirm = confirmations(
        runs, maxima, profile.status, (FIBULA_POINTER_STATUS["cut"],)
    )
    pointed = sorted({int(z) for peaks in maxima for z in peaks} | set(confirm))
    held_body = {f.index for f in profile.fine}
    pointed = sorted(set(pointed) | {int(z) for z in extra_planes if z in held_body})
    # each pointed plane is read once: a plane the study's reference already read is handed on
    read_planes = [
        bone_plane_read(
            own, bone, z, places, others, profile, plane_windows=plane_windows
        )
        for z in pointed
    ]
    sections: list[tuple[int, np.ndarray, PlaneFrame]] = [(index, mask, own.frame)]
    sections += [
        (p.slice, p.region, plane_frame(series, p.slice))
        for p in read_planes
        if not p.middle and p.code == IDENTIFIED
    ]
    sections = [s for s in sections if not isinstance(s[2], str)]
    if not pointed:
        outcome = (
            "unreadable"
            if np.isin(
                profile.status,
                (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"]),
            ).any()
            else "no_body_found"
        )
    elif any(p.code == IDENTIFIED for p in read_planes):
        outcome = "identified"
    elif any(p.code in (AMBIGUOUS, TIE) for p in read_planes):
        outcome = "ambiguous"
    else:
        outcome = "unresolved"
    origins, thick, offsets, sound = series_depth(series, own.frame, index)
    described, ends, spans = describe_runs(runs, profile.status, offsets, thick, sound)
    named = {p.slice for p in read_planes if p.code == IDENTIFIED}
    asked = {p.slice for p in read_planes}
    rule = np.zeros(len(runs), dtype=np.int8)
    for i, ((a, b), peaks) in enumerate(zip(runs, maxima, strict=True)):
        here = sorted(
            {int(z) for z in peaks} | {int(z) for z in confirm if z in (a - 1, b)}
        )
        described[i]["planes_read_for_it"] = here
        rule[i] = (
            RUN_CONFIRMATION["confirmed_by_the_native_rule"]
            if any(z in named for z in here)
            else RUN_CONFIRMATION["rejected_by_the_native_rule"]
            if any(z in asked for z in here)
            else RUN_CONFIRMATION["not_read_natively"]
        )
        described[i]["native_rule"] = {v: k for k, v in RUN_CONFIRMATION.items()}[
            int(rule[i])
        ]
    # the extent along the leg: the heights of the sections named, each end observed, clipped or not
    # The bone's supported body is what the extent is read from: the marrow body the profile drew
    # (its finer blocks, upsampled to the plane's pixels) inside the region named; where the profile
    # kept no finer reading there (the tiles confirmed it), the region named.
    fine_at = {f.index: f for f in profile.fine}
    heights = []
    skipped = []
    for z, region, frame in sections:
        rows, cols = np.shape(region)
        if z in fine_at:
            region = region & body_pixels(fine_at[z], (rows, cols))
            if not region.any():
                skipped.append(z)
                continue
        r, c = np.indices((rows, cols))
        up = frame.to_patient(np.column_stack((r.ravel(), c.ravel())).astype(float))[
            :, 2
        ]
        available = (
            own.arrays["b1_available"]
            if z == index
            else next(p.available for p in read_planes if p.slice == z)
        )
        got = section_extent(
            region, up.reshape(rows, cols), available, float(max(frame.spacing_rc))
        )
        if got is not None:
            heights.append((z, *got))
    extent: dict[str, Any] = {
        "along": "the scanner's z, up (millimetres)",
        "sections": [
            {"slice": z, "low_mm": lo, "high_mm": hi, "low_end": le, "high_end": he}
            for z, lo, hi, le, he in heights
        ],
        "sections_without_a_body_in_the_region": skipped,
    }
    if heights:
        low = min(heights, key=lambda h: h[1])
        high = max(heights, key=lambda h: h[2])
        extent.update(
            low_mm=low[1],
            low_end=low[3],
            high_mm=high[2],
            high_end=high[4],
            note="the extent of the sections named: the bone beyond a named plane's own is not "
            "claimed, and an end that is clipped or unresolved is a bound, not the bone's end",
        )
    landmarks = {
        "femur": {
            "femur_lower_end_mm": extent.get("low_mm"),
            "end": extent.get("low_end"),
        },
        "tibia": {"tibia_top_mm": extent.get("high_mm"), "end": extent.get("high_end")},
    }[bone]
    ambiguities = []
    if profile.merged.any():
        ambiguities.append(
            "a_piece_joined_the_other_bones_places_only_its_own_blocks_count"
        )
    if (rule == RUN_CONFIRMATION["rejected_by_the_native_rule"]).any():
        ambiguities.append("a_run_the_native_rule_rejected_is_not_the_bones_extent")
    if (rule == RUN_CONFIRMATION["not_read_natively"]).any():
        ambiguities.append("a_run_not_read_natively_is_not_the_bones_extent")
    unknown = [
        int(z)
        for z in np.flatnonzero(
            np.isin(
                profile.status,
                (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"]),
            )
        )
    ]
    if unknown:
        ambiguities.append("slices_the_profile_could_not_read_are_unknown_not_empty")
    if not sound:
        ambiguities.append("slice_geometry_unsound_so_no_physical_depth")
    names = {value: key for key, value in FIBULA_POINTER_STATUS.items()}
    pointed_rows = []
    for p in read_planes:
        pointed_rows.append(
            {
                "slice": p.slice,
                "middle": p.middle,
                "code": p.code,
                "labels": [] if p.naming is None else list(p.naming.labels),
                "tied_labels": [] if p.naming is None else list(p.naming.tied),
                "shared_labels": [] if p.naming is None else list(p.naming.shared),
                "territory_hits": {}
                if p.naming is None
                else {str(k): v for k, v in sorted(p.naming.hits.items())},
                "region_pixels": int(np.count_nonzero(p.region)),
                "position_mm": finite_or_none(offsets[p.slice]) if sound else None,
                "window_rc": None
                if p.local_lens is None
                else list(p.local_lens.window_rc),
                "window_code": None
                if p.local_lens is None
                else p.local_lens.scope_code,
                "window_reason": None
                if p.local_lens is None
                else p.local_lens.scope_reason,
                "lens_reading_code": None
                if p.local_lens is None
                else p.local_lens.reading_code,
            }
        )
    record_part = {
        "bone": bone,
        "outcome": outcome,
        "marrow_light": finite_or_none(profile.light),
        "level_of_the_light": list(LIKE_THE_TIBIA),
        "block_mm": float(LIGAMENT_SMOOTH_MM),
        "context_mm": float(BONE_MM),
        "status_codes": dict(FIBULA_POINTER_STATUS),
        "pointer_runs": described,
        "pointer_representatives": [[int(z) for z in peaks] for peaks in maxima],
        "confirmed_slices": [int(z) for z in confirm],
        "pointed_planes": pointed_rows,
        "extent": extent,
        "landmarks": landmarks,
        "unknown_slices": unknown,
        "ambiguities": ambiguities,
        "slice_status": {
            names[int(c)]: int(np.count_nonzero(profile.status == c))
            for c in np.unique(profile.status)
        },
    }
    pointed_origin = origins[pointed] if sound and pointed else np.empty((0, 3))
    arrays: dict[str, np.ndarray] = {
        f"a3_{bone}_profile_status": profile.status,
        f"a3_{bone}_profile_area_mm2": profile.area_mm2,
        f"a3_{bone}_profile_pieces": profile.pieces,
        f"a3_{bone}_profile_merged": profile.merged,
        f"a3_{bone}_profile_corridor_tiles": profile.corridor,
        f"a3_{bone}_profile_could_tiles": profile.could,
        f"a3_{bone}_profile_confirmed_tiles": profile.confirmed,
        f"a3_{bone}_profile_window_rc": profile.window_rc,
        f"a3_{bone}_profile_block_mm": profile.cell_mm,
        f"a3_{bone}_profile_block_px": profile.block_px,
        f"a3_{bone}_reference_light": np.asarray(profile.light, dtype=np.float64),
        f"a3_{bone}_pointer_runs": np.asarray(runs, dtype=np.int32).reshape(-1, 2),
        f"a3_{bone}_pointer_run_ends": ends.astype(np.int32),
        f"a3_{bone}_pointer_run_envelope_mm": spans,
        f"a3_{bone}_pointer_run_native_rule": rule,
        f"a3_{bone}_depth_offsets_mm": offsets,
        f"a3_{bone}_slice_thickness_mm": thick,
        f"a3_{bone}_pointed_slices": np.asarray(pointed, dtype=np.int32),
        f"a3_{bone}_pointed_origin_lps": pointed_origin,
        f"a3_{bone}_pointed_position_mm": offsets[pointed]
        if sound and pointed
        else np.empty(0),
        f"a3_{bone}_pointed_along_normal_mm": (pointed_origin @ own.frame.normal())
        if len(pointed_origin)
        else np.empty(0),
        f"a3_{bone}_leg_extent_mm": np.asarray(
            [extent.get("low_mm", np.nan), extent.get("high_mm", np.nan)],
            dtype=np.float64,
        ),
        f"a3_{bone}_source_normal_lps": own.frame.normal(),
    }
    for name, value in pack_fine_readings(profile.fine).items():
        arrays[
            f"a3_{bone}_fine_{'carried_footprint' if name == 'tibia_reference' else name}"
        ] = value
    handed("bones", ("pointed", "sections", "extent", "landmarks"))
    return BoneRead(
        bone, profile, tuple(read_planes), outcome, record_part, arrays, tuple(sections)
    )


def keep_bone_planes(own: Measured, bones: dict[str, BoneRead]) -> None:
    """Keep what the pointed planes read inside the series' own middle arrays: for both bones, the
    lens's labels and availability of every pointed plane but the middle slice (which holds its
    own), once per plane whichever bone pointed to it (`a3_bone_plane_{slices,labels,available}`,
    stacked in slice order), and for each bone its pointed planes (`a3_<bone>_plane_slices`), the
    region named on each (`_region`, stacked; empty where nothing was named), the outcome of each
    (`_outcome`, an index into `OUTCOMES`, -1 where the geometry was unreadable) and the row of the
    shared stack holding its lens (`_lens_row`, -1 where none). The shared local lens crops are
    retained as ragged arrays with per-slice windows, shapes and offsets. The primary plane's mask
    is the middle slice's `a1_objects` and is never copied. Saving is not reading: nothing reads
    these."""
    shape = np.shape(own.arrays["acquired_plane"])
    lens: dict[int, BonePlane] = {}
    for read in bones.values():
        for p in read.planes:
            if not p.middle and p.labels is not None:
                lens.setdefault(p.slice, p)
    order = sorted(lens)
    own.arrays["a3_bone_plane_slices"] = np.asarray(order, dtype=np.int32)
    for name, pick in (
        ("labels", lambda p: p.labels),
        ("available", lambda p: p.available),
    ):
        own.arrays[f"a3_bone_plane_{name}"] = (
            np.stack([pick(lens[z]) for z in order])
            if order
            else np.empty((0, *shape), dtype=np.int32 if name == "labels" else bool)
        )
    local = {z: lens[z].local_lens for z in order if lens[z].local_lens is not None}
    local_order = sorted(local)
    local_readings = cast(list[BoneLocalLens], [local[z] for z in local_order])
    local_shapes = np.asarray(
        [reading.raw_crop.shape for reading in local_readings], dtype=np.int32
    ).reshape(-1, 2)
    local_sizes = local_shapes[:, 0].astype(np.int64) * local_shapes[:, 1]
    own.arrays["a3_bone_lens_slices"] = np.asarray(local_order, dtype=np.int32)
    own.arrays["a3_bone_lens_windows_rc"] = np.asarray(
        [reading.window_rc for reading in local_readings], dtype=np.int32
    ).reshape(-1, 4)
    own.arrays["a3_bone_lens_scope_code"] = np.asarray(
        [reading.scope_code for reading in local_readings], dtype=np.str_
    )
    own.arrays["a3_bone_lens_scope_reason"] = np.asarray(
        [reading.scope_reason for reading in local_readings], dtype=np.str_
    )
    own.arrays["a3_bone_lens_reading_code"] = np.asarray(
        [reading.reading_code for reading in local_readings], dtype=np.str_
    )
    own.arrays["a3_bone_lens_crop_shapes"] = local_shapes
    own.arrays["a3_bone_lens_crop_offsets"] = np.concatenate(
        ([0], np.cumsum(local_sizes))
    ).astype(np.int64)
    for name, pick, dtype in (
        ("raw", lambda value: value.raw_crop, None),
        ("available", lambda value: value.available_crop, bool),
        ("dark", lambda value: value.dark_crop, bool),
        ("distance_mm", lambda value: value.distance_mm_crop, np.float64),
        ("markers", lambda value: value.markers_crop, np.int32),
        ("labels", lambda value: value.labels_crop, np.int32),
    ):
        pieces = [
            np.asarray(pick(value), dtype=dtype).ravel() for value in local_readings
        ]
        own.arrays[f"a3_bone_lens_crop_{name}"] = np.concatenate(
            pieces or [np.empty(0, dtype=dtype or np.float64)]
        )
    for bone, read in bones.items():
        mine = [p for p in read.planes if not p.middle]
        own.arrays[f"a3_{bone}_plane_slices"] = np.asarray(
            [p.slice for p in mine], dtype=np.int32
        )
        own.arrays[f"a3_{bone}_plane_region"] = (
            np.stack([p.region for p in mine])
            if mine
            else np.empty((0, *shape), dtype=bool)
        )
        own.arrays[f"a3_{bone}_plane_outcome"] = np.asarray(
            [OUTCOMES.index(p.code) if p.code in OUTCOMES else -1 for p in mine],
            dtype=np.int8,
        )
        own.arrays[f"a3_{bone}_plane_lens_row"] = np.asarray(
            [order.index(p.slice) if p.slice in lens else -1 for p in mine],
            dtype=np.int32,
        )
        own.arrays.update(read.arrays)
    handed("bones", ("planes",))


def lay_bone_sections(
    own: Measured, twin: Measured, read: BoneRead
) -> list[tuple[int, int | None, str, np.ndarray | None, float | None]]:
    """Each section of the bone named in `own` laid onto the same place of the twin: the twin's
    slice through the section's plane (by the scanner's millimetres, never equal indices:
    `slice_through`), the pair's one match of places (`matched`, shared with every other part laid
    across) and the section's region carried onto the twin's pixels (`laid_by`), the places the
    match cannot map left out. Returns (native slice, twin slice or None, code, laid mask or None,
    distance of the section's places from the twin's plane or None); the code is
    `laid_from_its_partner` or why not, and is never an absence."""
    series, other = own.series, twin.series
    out: list[tuple[int, int | None, str, np.ndarray | None, float | None]] = []
    known = [] if other.geometry is None else list(other.slice_thickness_mm)
    for z, region, frame in read.sections:
        if other.geometry is None or other.volume is None:
            out.append((z, None, "geometry_unreadable", None, None))
            continue
        if not known or any(t is None for t in known):
            out.append((z, None, "no_slice_thickness", None, None))
            continue
        origins = np.asarray(
            [np.asarray(p, dtype=float) for p in other.geometry.position]
        )
        index = slice_through(
            frame.origin_lps, origins, twin.frame.normal(), [float(t) for t in known]
        )
        if index is None:
            out.append((z, None, "twin_has_no_slice_at_this_place", None, None))
            continue
        twin_frame = plane_frame(other, index)
        if isinstance(twin_frame, str):
            out.append((z, index, twin_frame, None, None))
            continue
        source = matched(
            other,
            {"series_uid": other.row.series_uid, "slice_index": index},
            twin_frame,
            np.shape(other.volume[index]),
            {"series_uid": series.row.series_uid, "slice_index": z},
            frame,
            np.asarray(series.volume[z]),
        )
        if isinstance(source, str):
            out.append((z, index, source, None, None))
            continue
        laid = (source >= 0) & laid_by(region, source) & finite_of(other)[index]
        places = frame.to_patient(np.argwhere(region).astype(float))
        off = float(
            abs((places.mean(axis=0) - twin_frame.origin_lps) @ twin_frame.normal())
        )
        if not laid.any():
            out.append(
                (z, index, "nothing_of_the_section_lands_on_the_twin", None, off)
            )
            continue
        out.append((z, index, "laid_from_its_partner", laid, off))
    return out


def bone_target(
    places: np.ndarray, other: Measured
) -> tuple[int, str, float, int] | str:
    """Where a bone's `places` (scanner millimetres) project onto another series: its nearest slice
    along that series' own normal, whether they lie on it, between slices or beyond the scan, how
    far off its plane, and how many pixels they project onto; or why the series cannot say
    (`slab_thicknesses`, an unreadable frame). A location, never a boundary."""
    series = other.series
    thick, why = slab_thicknesses(series)
    if why is not None:
        return why
    origins = np.asarray([np.asarray(p, dtype=float) for p in series.geometry.position])
    normal = other.frame.normal()
    middle = places.mean(axis=0)
    signed = (middle - origins) @ normal
    nearest = int(np.argmin(np.abs(signed)))
    along = origins @ normal
    low = float(along.min()) - float(thick[int(np.argmin(along))]) / 2.0
    high = float(along.max()) + float(thick[int(np.argmax(along))]) / 2.0
    distance = float(abs(signed[nearest]))
    if distance <= float(thick[nearest]) / 2.0:
        where = "on_the_slice"
    elif not low <= float(middle @ normal) <= high:
        where = "beyond_the_scan"
    else:
        where = "between_slices"
    frame = plane_frame(series, nearest)
    if isinstance(frame, str):
        return frame
    count = int(
        np.count_nonzero(
            projected_places(places, frame, np.shape(series.volume[nearest]))
        )
    )
    return nearest, where, distance, count


def name_the_bones(
    measured: list[Measured],
    partners: list[Measured | None],
    leg: Leg | None,
    study_uid: str,
) -> None:
    """The femur and the tibia through the stacks (`read_bone`) of every series that names them on
    its middle slice without fat suppression, and what each view says of them, kept in the series'
    own middle records and arrays (saved by the caller), never a record of its own.

    Native: the middle slice (the accepted bootstrap, `a1_objects`, resolved), each pointed plane
    the carried places named a territory on (resolved; one row of `a3_<bone>_plane_region`), each
    pointed plane that did not (a reading with its code, one row of the shared
    `a3_bone_plane_labels`) and the profile's support through depth (readings; the slices index
    `a3_<bone>_profile_area_mm2`). Laid: every named section onto the same place of the other
    sequence (`lay_bone_sections`, stacked in the twin's `a3_<bone>_laid_region`). Projected: the
    largest named section's places onto the slice of every other series nearest them (targets,
    never a boundary). What could not be said is an `Unresolved` with its code; a series whose
    middle slice does not name the bone, a fat-suppressed series, and a study with no partner are
    named, never skipped. Each series' record gets `bones` (outcome and extent per bone),
    `observations`, `observations_by_provenance` and `observations_unresolved`. The extent and
    landmarks (the femur's lower end, the tibia's top, each pointed plane's place along the stack's
    normal) are produced and no stage reads them: the existing consumers (the fibula's corridor, the
    carried leg) read the middle slice's bones and are not changed by them."""
    carried = leg if leg is not None else leg_of(measured)
    places = {"femur": carried.femur_lps, "tibia": carried.tibia_lps}
    results = []
    for own in measured:
        profiles: dict[str, BoneProfile | str] = {}
        for bone, other in (("femur", "tibia"), ("tibia", "femur")):
            basis = bone_reading_basis(own, bone, places[bone])
            if isinstance(basis, str):
                profiles[bone] = basis
                continue
            _, light = basis
            profile = bone_profile_of(own, bone, places[bone], places[other], light)
            reads("bone_profile", ("window_rc",), "bones")
            profiles[bone] = profile
        volume = own.series.volume
        shapes = (
            [
                tuple(int(axis) for axis in np.shape(volume[z]))
                for z in range(len(volume))
            ]
            if volume is not None
            else []
        )
        windows = bone_plane_window_map(profiles, shapes)
        read = {
            bone: read_bone(
                own,
                bone,
                places[bone],
                places[other],
                plane_windows=windows,
            )
            for bone, other in (("femur", "tibia"), ("tibia", "femur"))
        }
        # the joint lies between them: a plane that pointed for one bone is asked of the other too,
        # on the lens already read for it and its own profile's marrow body (the profile is the
        # same once-made value)
        pointed_for = {
            b: {p.slice for p in r.planes}
            for b, r in read.items()
            if isinstance(r, BoneRead)
        }
        for bone, other in (("femur", "tibia"), ("tibia", "femur")):
            if bone in pointed_for and other in pointed_for:
                more = pointed_for[other] - pointed_for[bone]
                if more:
                    read[bone] = read_bone(
                        own,
                        bone,
                        places[bone],
                        places[other],
                        extra_planes=more,
                        plane_windows=windows,
                    )
        for r in read.values():
            if isinstance(r, BoneRead):
                ledger.record("bones.pointed_planes", planes=len(r.planes))
        results.append(read)
    said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    for i, own in enumerate(measured):
        uid, view = own.record["series_uid"], tuple(own.record["view"])
        artifact = str(artifact_of(study_uid, own.record))
        here, missing = said[i]
        found = {b: r for b, r in results[i].items() if isinstance(r, BoneRead)}
        if found:
            keep_bone_planes(own, found)
        own.record["bones"] = {
            "outcomes": list(OUTCOMES),
            "codes": {
                b: (r.outcome if isinstance(r, BoneRead) else r)
                for b, r in results[i].items()
            },
            **{b: r.record for b, r in found.items()},
        }
        partner = partners[i]
        at = (
            None
            if partner is None
            else next(j for j, m in enumerate(measured) if m is partner)
        )
        skip = {uid} | (
            {partner.record["series_uid"]} if partner is not None else set()
        )
        for bone, read in results[i].items():
            if isinstance(read, str):
                missing.append(Unresolved(bone, "native", uid, view, read))
                continue
            index = own.record["slice_index"]
            rows = [p for p in read.planes if not p.middle]
            for p in read.planes:
                if p.middle:
                    here.append(
                        Observation(
                            bone,
                            "native",
                            "resolved",
                            uid,
                            view,
                            (index,),
                            IDENTIFIED,
                            int(np.count_nonzero(p.region)),
                            0.0,
                            "a1_objects",
                            "the middle slice's own naming (the bootstrap), the section on this slice, not the whole bone",
                            artifact,
                            None,
                            OBJECT_CODES[bone],
                        )
                    )
            for row, p in enumerate(rows):
                if p.code == IDENTIFIED:
                    here.append(
                        Observation(
                            bone,
                            "native",
                            "resolved",
                            uid,
                            view,
                            (p.slice,),
                            IDENTIFIED,
                            int(np.count_nonzero(p.region)),
                            0.0,
                            f"a3_{bone}_plane_region",
                            "the carried places name these lens territories here: the section on this plane, not the whole bone",
                            artifact,
                            row,
                            None,
                        )
                    )
                else:
                    held = None if p.naming is None else p.naming.labels
                    here.append(
                        Observation(
                            bone,
                            "native",
                            "reading",
                            uid,
                            view,
                            (p.slice,),
                            p.code,
                            None,
                            0.0,
                            "a3_bone_plane_labels",
                            (
                                f"the pointed plane was read in its recorded shared profile window ({p.local_lens.scope_code}); no territory is named the bone here"
                                if p.local_lens is not None
                                else "the pointed plane's geometry was unreadable; no territory is named the bone here"
                            ),
                            artifact,
                            int(own.arrays[f"a3_{bone}_plane_lens_row"][row])
                            if p.labels is not None
                            else None,
                            held[0] if held and len(held) == 1 else None,
                        )
                    )
            runs = read.arrays[f"a3_{bone}_pointer_runs"]
            rule = read.arrays[f"a3_{bone}_pointer_run_native_rule"]
            for name, wanted in (
                ("pointer_body", True),
                ("pointer_body_unconfirmed", False),
            ):
                slices = tuple(
                    int(z)
                    for (a, b), code in zip(runs, rule, strict=True)
                    if (code == RUN_CONFIRMATION["confirmed_by_the_native_rule"])
                    == wanted
                    for z in range(a, b)
                )
                if slices:
                    here.append(
                        Observation(
                            bone,
                            "native",
                            "reading",
                            uid,
                            view,
                            slices,
                            name,
                            None,
                            None,
                            f"a3_{bone}_profile_area_mm2",
                            "a cheap marrow-body area through depth: no boundary, and not the bone's whole extent",
                            artifact,
                        )
                    )
            # laid: every named section onto the same place of the other sequence
            if partner is None or at is None:
                missing.append(
                    Unresolved(bone, "laid", None, None, "none_of_the_other_sequence")
                )
            else:
                twin_view = tuple(partner.record["view"])
                laid = lay_bone_sections(own, partner, read)
                kept = [item for item in laid if item[3] is not None]
                # a twin that is laid onto from more than one series keeps each one's rows
                # under its own name, so no row ever points into another's array
                laid_name = source_prefix(
                    f"a3_{bone}_laid", partner.arrays, own.series.row.series_uid
                )
                partner.arrays[f"{laid_name}_native_slices"] = np.asarray(
                    [k[0] for k in kept], dtype=np.int32
                )
                partner.arrays[f"{laid_name}_slices"] = np.asarray(
                    [k[1] for k in kept], dtype=np.int32
                )
                partner.arrays[f"{laid_name}_region"] = (
                    np.stack([k[3] for k in kept])
                    if kept
                    else np.empty(
                        (0, *np.shape(partner.arrays["acquired_plane"])), dtype=bool
                    )
                )
                partner_artifact = str(artifact_of(study_uid, partner.record))
                row = 0
                for z, twin_index, code, mask, off in laid:
                    if mask is None or twin_index is None:
                        missing.append(
                            Unresolved(
                                bone,
                                "laid",
                                partner.record["series_uid"],
                                twin_view,
                                code,
                            )
                        )
                        continue
                    said[at][0].append(
                        Observation(
                            bone,
                            "laid",
                            "resolved",
                            partner.record["series_uid"],
                            twin_view,
                            (twin_index,),
                            code,
                            int(np.count_nonzero(mask)),
                            off,
                            f"{laid_name}_region",
                            f"the section named on native slice {z} laid by the pair's match of places; pixels with no place on the native slice are left out",
                            partner_artifact,
                            row,
                            None,
                        )
                    )
                    row += 1
            # projected: the largest section's places, onto every other series' nearest slice
            if read.sections:
                z, region, frame = max(
                    read.sections, key=lambda s: int(np.count_nonzero(s[1]))
                )
                from_middle = z == index
                source_row = None if from_middle else [p.slice for p in rows].index(z)
                physical = frame.to_patient(np.argwhere(region).astype(float))
                for other in measured:
                    other_uid = other.record["series_uid"]
                    if other_uid in skip:
                        continue
                    other_view = tuple(other.record["view"])
                    target = bone_target(physical, other)
                    if isinstance(target, str):
                        missing.append(
                            Unresolved(bone, "projected", other_uid, other_view, target)
                        )
                        continue
                    nearest, where, distance, count = target
                    here.append(
                        Observation(
                            bone,
                            "projected",
                            "target",
                            other_uid,
                            other_view,
                            (nearest,),
                            where,
                            count,
                            distance,
                            "a1_objects" if from_middle else f"a3_{bone}_plane_region",
                            f"a location target projected from the section named on slice {z} (its places are the region the support names, in the frame of that slice): where a native question may be asked, not a boundary seen on this slice",
                            artifact,
                            source_row,
                            OBJECT_CODES[bone] if from_middle else None,
                        )
                    )
    for own, (here, missing) in zip(measured, said, strict=True):
        own.record["observations"] = observation_rows(here)
        own.record["observations_by_provenance"] = tally(here)
        own.record["observations_unresolved"] = unresolved_rows(missing)


def refine_leg(leg: Leg, measured: list[Measured]) -> Leg:
    """The leg with the later native bone sections published once: to the early middle-slice places
    (`leg_of`) are added the places of every pointed plane `name_the_bones` resolved natively
    (`a3_<bone>_plane_region` rows whose outcome is `identified`), each converted through its own
    slice's frame. Laid, projected and reading-only rows are not support and are not added. Each
    contributing series records which of its slices it published (`bones.published_to_leg`), so
    every added place is addressable. Where no section was resolved the early leg is returned as it
    is; otherwise a new leg with its own identity, so a cache keyed by the leg never hands on the
    early leg's projection for it. The readers that ran before the bones keep the early leg."""
    reads("bones", ("planes",), "leg_refined")
    identified = OUTCOMES.index(IDENTIFIED)
    added: dict[str, list[np.ndarray]] = {"femur": [], "tibia": []}
    for own in measured:
        published: dict[str, list[int]] = {}
        for bone in ("femur", "tibia"):
            slices = own.arrays.get(f"a3_{bone}_plane_slices")
            regions = own.arrays.get(f"a3_{bone}_plane_region")
            outcomes = own.arrays.get(f"a3_{bone}_plane_outcome")
            if slices is None or regions is None or outcomes is None:
                continue
            for row, (z, outcome) in enumerate(zip(slices, outcomes, strict=True)):
                if int(outcome) != identified or not regions[row].any():
                    continue
                frame = plane_frame(own.series, int(z))
                if isinstance(frame, str):
                    continue
                added[bone].append(
                    frame.to_patient(np.argwhere(regions[row]).astype(float))
                )
                published.setdefault(bone, []).append(int(z))
        if published:
            own.record.setdefault("bones", {})["published_to_leg"] = {
                bone: {"support": f"a3_{bone}_plane_region", "slices": zs}
                for bone, zs in published.items()
            }
    sections = len(added["femur"]) + len(added["tibia"])
    ledger.record(
        "leg.refined",
        sections=sections,
        femur_places=int(sum(len(p) for p in added["femur"])),
        tibia_places=int(sum(len(p) for p in added["tibia"])),
    )
    if not sections:
        return leg
    refined = Leg(
        np.concatenate([leg.femur_lps, *added["femur"]]),
        np.concatenate([leg.tibia_lps, *added["tibia"]]),
        leg.notch_origin_lps,
        leg.notch_normal,
        leg.patella_lps,
    )
    refined = replace(refined, identity=leg_identity(refined))
    handed("leg", field_names(refined))
    return refined


# -- THE STUDY MAP: three key planes per object -> one 3D position -> every pair -> where to look ------
# (`knee.collapse.study_map`, `docs/RELATIVE_POSITION_MAP.md` §8.8). Built once the bones' own cheap
# profiles have selected their planes, BEFORE any other family searches; the families read where it
# expects them first and fall back to their full search; each family's resolved sections then enter
# it (`refine_map`), so the later families and the receipt read the updated map.
MAP_OBJECTS = MAP_NAMES
AXIAL_OVERLAP = "slice_within_the_other_bones_native_extent_not_attributed"
DIFFUSE_REASON = (
    "diffuse_field_class_no_single_key_plane_authored_by_the_anatomy_reference"
)


@dataclass
class MapContext:
    """The study map with the anatomy it is read against: `ideal` (the anatomical reference's ideal vector of
    one object from another, or None where that relation has no authored reference) and `span` (its search allowance per
    object), and the series' frames, made once."""

    smap: StudyMap
    ideal: Callable[[str, str, float | None], Any] | None
    span: Callable[[str, float | None], tuple[float, float, float] | None] | None
    frames: dict[str, list[PlaneFrame | None]] = dc_field(default_factory=dict)
    diffuse: set[str] = dc_field(default_factory=set)

    def guide(self, name: str, own: "Measured") -> Guide:
        uid = own.series.row.series_uid
        if uid not in self.frames:
            volume = getattr(own.series, "volume", None)
            depth = len(volume) if volume is not None else 0
            self.frames[uid] = [
                None if isinstance(f := plane_frame(own.series, z), str) else f
                for z in range(depth)
            ]
        span = None if self.span is None else self.span(name, self.smap.scale.mm)
        half = None if span is None else tuple(float(v) / 2.0 for v in span)
        got = self.smap.guide(
            name,
            uid,
            self.frames[uid],
            tuple(np.shape(own.arrays["acquired_plane"])),
            self.ideal,
            half_span_lps=half,
        )
        ledger.record("study_map.guides", series=1)
        return got


def anatomical_reference() -> tuple[Callable, Callable, set[str]]:
    """The anatomy module's ideal vector, search allowance and diffuse classes (`knee.collapse.anatomy_map`,
    authored from the atlas and anatomy, never from the studies). A name the reference does not hold has no
    ideal: no expectation, never a guess. A known knee breadth scales both vectors and search spans;
    otherwise the reference's own millimetres remain explicit."""

    def ideal(origin: str, target: str, knee_scale_mm: float | None = None):
        try:
            return anatomy_map.ideal_vector(origin, target, knee_scale_mm)
        except KeyError:
            return None

    def span(name: str, knee_scale_mm: float | None = None):
        try:
            return anatomy_map.target_span_mm(name, knee_scale_mm)
        except KeyError:
            return None

    diffuse = {
        n
        for n, site in anatomy_map.reference_sites().items()
        if site.status == "reference_not_defined" and n in MAP_OBJECTS
    }
    return ideal, span, diffuse


def map_plane(
    own: "Measured", name: str, z: int, reason: str, provenance: str
) -> rel.KeyPlane:
    """One series' slice as the key plane it would be, from that slice's own frame; the named reason a
    plane cannot be made otherwise."""
    orientation = str(own.record["view"][0]).lower()
    uid = own.series.row.series_uid
    frame = plane_frame(own.series, z)
    if isinstance(frame, str):
        return rel.invalid_plane(
            name,
            orientation,
            "frame_unavailable",
            series_uid=uid,
            slice=z,
            reason=reason,
        )
    thicknesses = getattr(own.series, "slice_thickness_mm", None)
    try:
        thick = None if thicknesses is None else thicknesses[z]
        precision = float("nan") if thick is None else float(thick) / 2.0
    except (IndexError, TypeError, ValueError, OverflowError):
        return rel.invalid_plane(
            name,
            orientation,
            "precision_unreadable",
            series_uid=uid,
            slice=z,
            reason=reason,
            provenance=provenance,
        )
    return rel.plane_of_frame(
        name,
        orientation,
        series_uid=uid,
        slice=z,
        frame=frame,
        precision_mm=precision,
        reason=reason,
        provenance=provenance,
    )


def bone_key_planes(smap: StudyMap, own: "Measured") -> None:
    """A bone's key plane on one series without fat suppression: among the planes its cheap profile pointed
    to (and the middle slice's bootstrap) that the lens named as the bone, the strongest supported marrow
    body (`select_reference`'s rule); every tie is offered, the map never breaks one."""
    kept = own.record.get("bones", {})
    for bone in REFERENCE_BONES:
        part = kept.get(bone)
        area = own.arrays.get(f"a3_{bone}_profile_area_mm2")
        if part is None or area is None:
            continue
        named = {r["slice"] for r in part["pointed_planes"] if r["code"] == IDENTIFIED}
        if own.record["assignments"][bone] is not None:
            named.add(int(own.record["slice_index"]))
        held = {z: float(area[z]) for z in named if np.isfinite(area[z])}
        chosen = (
            [z for z, a in held.items() if a == max(held.values())]
            if held
            else sorted(named)
        )
        for z in chosen:
            smap.offer(
                bone,
                map_plane(
                    own,
                    bone,
                    z,
                    "strongest supported marrow body of the bone through depth, named by the lens",
                    "bones.read_bone",
                ),
                held.get(z),
                f"bones:{own.series.row.series_uid}",
            )


def axial_bone_planes(smap: StudyMap, own: "Measured", leg: Leg) -> dict[str, dict]:
    """Find axial bone key planes from shared 2 mm block readings and carried location seeds.

    The coarse section is a physical pointer only; the existing anatomy lenses still name the bones.
    `leg` supplies the seeds (its places carried onto each slice, `leg_on`), a location prior and never
    native bone, and the extent that attributes a slice to one bone: the femur's lowest and the tibia's
    highest carried place. That extent IS used as a hard cut, not as a prior: a slice wholly within the
    other bone's extent is named (`AXIAL_OVERLAP`), not attributed, and gives that bone no section there
    for its key plane.

    Where a bone is attributed, its section is the scale-filtered coarse section ESTIMATE
    (`scale_filtered_section`): the enclosed bodies its seeds touch whose narrowest breadth is at least
    `BONE_MM`, holes filled, SHARED judged on the estimate's own body. It is a lossy scale filter, not
    the cortex-enclosed section and not a proof of identity: a touched body under `BONE_MM` is left out
    whatever it is (bone pieces too), and a curved thin strip with a broad hull, or a non-bone body of
    bone scale the seeds touch, can remain. The estimate chooses the key plane (its area, every tie
    kept, in `a4_axial_<bone>_section_area_mm2`) and, for the femur, sets the knee's scale (its
    left-right extent). The unfiltered section stays beside it, exactly as `coarse_section` returns
    it, in the `a4_axial_coarse_<bone>_*` arrays, and the estimate, the omitted bodies and every touched
    body's block count and breadth are packed with them (`a4_axial_coarse_<bone>_estimate_*`,
    `_omitted`, `_component_*`; `pack_estimates`).
    """
    series = own.series
    uid = series.row.series_uid
    dark = int(series.row.fat_suppression) == 1
    volume = getattr(series, "volume", None)
    depth = len(volume) if volume is not None else 0
    shape = tuple(np.shape(own.arrays["acquired_plane"]))
    said: dict[str, dict] = {}
    areas = {b: np.full(depth, np.nan) for b in REFERENCE_BONES}
    statuses: dict[str, dict[str, int]] = {b: {} for b in REFERENCE_BONES}
    unfiltered_statuses: dict[str, dict[str, int]] = {b: {} for b in REFERENCE_BONES}
    readings = []
    read_frames = []
    depths = []
    # Per slice read: the unfiltered section of each bone (the call the bone always had), and the
    # scale-filtered estimate where the bone is attributed there (None where it is not).
    sections = {b: [] for b in REFERENCE_BONES}
    estimates: dict[str, list[ScaleEstimate | None]] = {b: [] for b in REFERENCE_BONES}
    read_slices = []
    identity_excluded = {b: np.zeros(depth, dtype=bool) for b in REFERENCE_BONES}
    # A sparse carried line can lie in a body that is the OTHER bone's (the proof's femoral condyles at the
    # joint, seeded by the tibia's top). A bone's section is attributed only on slices wholly outside the
    # other bone's own native extent along the leg: the tibia's below the femur's lowest carried place, the
    # femur's above the tibia's highest; the joint's overlap is named, not attributed.
    femur_low = tibia_top = None
    if depth:
        femur_places = np.asarray(leg.femur_lps).reshape(-1, 3)
        tibia_places = np.asarray(leg.tibia_lps).reshape(-1, 3)
        femur_low = float(femur_places[:, 2].min()) if len(femur_places) else None
        tibia_top = float(tibia_places[:, 2].max()) if len(tibia_places) else None
    for z in range(depth):
        assert (
            volume is not None
        )  # a nonempty depth is established only from this volume
        frame = plane_frame(series, z)
        thick = series.slice_thickness_mm[z]
        if isinstance(frame, str) or thick is None:
            continue
        centre = frame.to_patient(
            np.array([[shape[0] / 2.0, shape[1] / 2.0]], dtype=float)
        )[0, 2]
        half = float(thick) / 2.0
        allowed = {
            "femur": tibia_top is None or centre - half > tibia_top,
            "tibia": femur_low is None or centre + half < femur_low,
        }
        seeds = dict(
            zip(
                REFERENCE_BONES,
                leg_on(leg, series, z, frame, shape, float(thick)),
                strict=True,
            )
        )
        for bone in REFERENCE_BONES:
            if seeds[bone].any() and not allowed[bone]:
                identity_excluded[bone][z] = True
                for counted in (statuses[bone], unfiltered_statuses[bone]):
                    counted[AXIAL_OVERLAP] = counted.get(AXIAL_OVERLAP, 0) + 1
        active = {
            bone: bool(seeds[bone].any() and allowed[bone]) for bone in REFERENCE_BONES
        }
        if not any(active.values()):
            continue
        plane = np.asarray(volume[z], dtype=np.float64)
        measured = once(
            "coarse_axial_blocks",
            (uid, z, LIGAMENT_SMOOTH_MM),
            lambda plane=plane, frame=frame: block_medians(
                plane,
                margin(plane) | ~np.isfinite(plane),
                frame.spacing_rc,
                LIGAMENT_SMOOTH_MM,
            ),
        )
        readings.append(measured)
        read_frames.append(frame)
        read_slices.append(z)
        coarse = once(
            "coarse_axial_depth",
            (uid, z, dark),
            lambda measured=measured, dark=dark: handed_on(
                coarse_depth(measured.median, dark)
            ),
        )
        depths.append(coarse)
        block_area = float(np.prod(measured.block_mm))
        marked = {b: block_holds(seeds[b], measured) for b in REFERENCE_BONES}
        for bone in REFERENCE_BONES:
            if not active[bone]:
                sections[bone].append(coarse_section(coarse, marked[bone], block_area))
                estimates[bone].append(None)
                continue
            others = {
                other: marked[other] for other in REFERENCE_BONES if other != bone
            }
            both = scale_filtered_section(
                coarse, marked[bone], block_area, measured.block_mm, BONE_MM, others
            )
            sections[bone].append(both.unfiltered)
            estimates[bone].append(both.estimate)
            for counted, status in (
                (unfiltered_statuses[bone], both.unfiltered.status),
                (statuses[bone], both.estimate.status),
            ):
                counted[status] = counted.get(status, 0) + 1
            if both.estimate.status == SECTION and both.estimate.body is not None:
                areas[bone][z] = both.estimate.area_mm2
        ledger.record("coarse_axial_bone.sections", planes=1)
    own.arrays.update(
        {
            f"a4_axial_coarse_{name}": value
            for name, value in {
                **pack_sections(read_slices, readings, depths, sections),
                **pack_estimates(readings, estimates),
            }.items()
        }
    )
    for bone in REFERENCE_BONES:
        own.arrays[f"a4_axial_{bone}_identity_excluded"] = identity_excluded[bone]
    for bone in REFERENCE_BONES:
        keys = coarse_key_slices(areas[bone])
        # Named for what it holds now: the scale-filtered estimate's area on the slices read where the
        # bone is attributed (NaN elsewhere); the unfiltered areas are `a4_axial_coarse_<bone>_area_mm2`.
        own.arrays[f"a4_axial_{bone}_section_area_mm2"] = areas[bone]
        said[bone] = {
            "key_slices": list(keys),
            "statuses": statuses[bone],
            # What `statuses` held before the estimate: the unfiltered section's, and the overlap named.
            "unfiltered_statuses": unfiltered_statuses[bone],
            "scale_floor_mm": BONE_MM,
            "marrow": "dark_enclosed_by_brighter"
            if dark
            else "bright_enclosed_by_darker",
            "rule": "knee.collapse.coarse_section.scale_filtered_section: the scale-filtered whole 2 mm axial section estimate, the enclosed bodies the carried location seeds touch kept where their narrowest breadth is at least scale_floor_mm (a lossy scale filter, not the cortex-enclosed section and not an identity proof), holes filled; `statuses`, `key_slices` and `a4_axial_<bone>_section_area_mm2` read this estimate, `unfiltered_statuses` and `a4_axial_coarse_<bone>_*` the unfiltered section; largest estimate, ties kept",
        }
        extents = []
        if bone == "femur":
            for z in keys:
                if z not in read_slices:
                    continue
                at = read_slices.index(z)
                estimate = estimates[bone][at]
                if estimate is not None and estimate.body is not None:
                    extents.append(
                        body_extent_mm(
                            estimate.body,
                            readings[at],
                            read_frames[at],
                            (1.0, 0.0, 0.0),
                        )
                    )
        if bone == "femur" and keys:
            finite_extents = [
                float(x) for x in extents if x is not None and np.isfinite(x)
            ]
            if len(finite_extents) == len(keys) and all(
                x == finite_extents[0] for x in finite_extents
            ):
                supports = ",".join(f"{z}:{areas[bone][z]:.6g}mm2" for z in keys)
                smap.set_scale(
                    rel.KneeScale(
                        finite_extents[0],
                        f"femur scale-filtered coarse axial body extent along LPS left-right (a lossy scale filter, not the cortex-enclosed section); {uid} slice/support_mm2 {supports}",
                        "measured_femur_ml_breadth",
                    )
                )
            else:
                smap.set_scale(
                    rel.KneeScale(
                        None,
                        "femur breadth unavailable or tied key planes disagree",
                        "unknown",
                    )
                )
        for z in keys:
            if z not in read_slices:
                continue
            smap.offer(
                bone,
                map_plane(
                    own,
                    bone,
                    z,
                    "largest scale-filtered whole 2 mm axial bone section estimate: the enclosed bodies the carried location seeds touch, kept where their narrowest breadth is at least BONE_MM (a lossy scale filter, not the cortex-enclosed section and not an identity proof)",
                    "scale_filtered_section",
                ),
                float(areas[bone][z]),
                f"axial_bone:{uid}",
            )
    own.record["axial_bone"] = said
    handed("axial_bone", ("section_area_mm2",))
    reads("axial_bone", ("section_area_mm2",), "study_map")
    return said


def build_study_map(
    measured: list[Measured], leg: Leg, ideal_parts: tuple
) -> MapContext:
    """The study's map from what the bones' own cheap readings selected: the sagittal and coronal key planes of
    the femur and the tibia from every series without fat suppression, their axial key planes from every
    axial series' scale-filtered section estimate (`axial_bone_planes`); the diffuse field classes named as
    having no single key plane. The
    other objects enter as their families resolve them (`refine_map`). `leg` is the leg the axial
    sections are seeded from: the driver hands it the leg refined by the bones' later native sections
    (`refine_leg`)."""
    ideal, span, diffuse = ideal_parts
    knee = next(
        (
            str(m.record["assignments"]["knee"])
            for m in measured
            if str(m.record["assignments"]["knee"]) in ("R", "L")
        ),
        None,
    )
    smap = StudyMap(knee=knee)
    for name in sorted(diffuse):
        for orientation in rel.ORIENTATIONS:
            smap.offer(
                name,
                rel.unresolved_plane(
                    name, orientation, rel.REFUSED, reason=DIFFUSE_REASON
                ),
            )
    for own in measured:
        view = str(own.record["view"][0]).lower()
        if view in ("sagittal", "coronal"):
            bone_key_planes(smap, own)
        elif view == "axial":
            axial_bone_planes(smap, own, leg)
    handed("study_map", ("record", "guide"))
    return MapContext(smap, ideal, span, diffuse=set(diffuse))


def refine_map(
    context: MapContext,
    measured: list[Measured],
    main_records: list[dict] | None = None,
) -> int:
    """Every object a family has since resolved natively enters the map as a candidate key plane in its
    series' orientation, supported by its pixel area in mm2. New native sections on a previously seen series
    remain evidence, including equal-support planes; identical offers are reused. The strongest supported
    section is a pointer, not a universal definition of obviousness. The bones are not re-offered (their
    planes came from their own profiles). Returns how many objects gained evidence."""
    by_uid = {m.series.row.series_uid: m for m in measured}
    fresh: dict[str, list[tuple[rel.KeyPlane, float | None, str]]] = {}
    rows = [row for m in measured for row in m.record.get("observations", [])] + [
        row for r in (main_records or []) for row in r.get("observations", [])
    ]
    for row in rows:
        name = row["object"]
        if (
            row["provenance"] != "native"
            or row["kind"] != "resolved"
            or name not in context.smap.names
            or name in REFERENCE_BONES
            or name in context.diffuse
            or not row["slices"]
            or row["series_uid"] not in by_uid
        ):
            continue
        own = by_uid[row["series_uid"]]
        z = int(row["slices"][0])
        frame = plane_frame(own.series, z)
        if isinstance(frame, str) or not row["count"]:
            continue
        area = float(row["count"]) * float(np.prod(frame.spacing_rc))
        uid = row["series_uid"]
        plane = map_plane(
            own,
            name,
            int(row["slices"][0]),
            f"strongest native-resolved section of the object on this series ({row['code']}); "
            "a pointer, not a definition of where the anatomy is most obvious",
            "observations.native_resolved",
        )
        source = f"native:{uid}"
        offered = (plane, area, source)
        if any(
            c.plane == plane and c.support == area and c.source == source
            for c in context.smap.candidates.get((name, plane.orientation), [])
        ) or offered in fresh.get(name, []):
            continue
        fresh.setdefault(name, []).append(offered)
    for name, planes in fresh.items():
        context.smap.refine(name, planes)
    ledger.record("study_map.refined", objects=len(fresh))
    return len(fresh)


def offer_map_rows(
    context: MapContext, measured: list[Measured], product: str, rows: list[dict]
) -> int:
    """Offer one already-published map-row product to the shared map."""
    if not rows:
        return 0
    reads(product, ("observations",), "refine_map")
    return refine_map(context, measured, rows)


def offer_native_family(
    context: MapContext,
    measured: list[Measured],
    family: str,
    said: list[tuple[list[Observation], list[Unresolved]]],
) -> tuple[str, list[dict], int]:
    """Convert a completed family's observations once and offer its named map rows."""
    if not any(rows for rows, _ in said):
        return f"{family}.map_rows", [], 0
    if family in (
        "sagittal_menisci_said",
        "axial_menisci_said",
        "axial_pcl_said",
        "coronal_pcl_said",
    ):
        reads(family, ("observations",), "map_rows")
    product = f"{family}.map_rows"
    rows = [
        {"observations": observation_rows(observations)}
        for observations, _ in said
        if observations
    ]
    if not rows:
        return product, [], 0
    handed(product, ("observations",))
    return product, rows, offer_map_rows(context, measured, product, rows)


def finish_map(context: MapContext, run_dir: Path, study_uid: str) -> dict:
    """The final map, whole, in a file of the study's folder (every object's status, key planes and every
    candidate, every ordered pair complete or named unresolved, every prediction and the guides' uses); the
    compact summary the series' record keeps. Counts are on the ledger."""
    record = context.smap.record(context.ideal)
    path = run_dir / study_uid / "study_map.json"
    path.write_text(json.dumps(record, indent=1, default=plain) + "\n")
    counts = record["counts"]
    ledger.record(
        "study_map.work",
        objects=counts["objects"],
        complete=counts["complete"],
        partial=counts["partial"],
        pairs_complete=counts["pairs_complete"],
        pairs_unresolved=counts["pairs_unresolved"],
        predictions=counts["predictions"],
        refinements=counts["refinements"],
    )
    compact = context.smap.summary(context.ideal)
    compact["counts"] = counts
    compact["construction"] = record["construction"]
    compact["file"] = str(Path(study_uid) / "study_map.json")
    compact["pairs_complete_count"] = counts["pairs_complete"]
    compact["pairs_unresolved_count"] = counts["pairs_unresolved"]
    compact["uses_count"] = counts["uses"]
    return compact


# -- THE PATELLA: its marrow body through depth, pointed planes, and what the extensor mechanism ----
# and the fat pads read on each of them -----------------------------------------------------------
# What the patella's rule (`patella_code`) can say on a pointed plane; the index is what the saved
# outcome array holds (-1: the plane's geometry could not be read).
PATELLA_OUTCOMES = (
    "identified",
    "abstain_front_to_back_runs_through_the_plane",
    "abstain_no_femur",
    "abstain_fat_as_bright_as_marrow",
    "abstain_no_peak_in_front_of_the_femur",
    "abstain_nothing_like_the_femur_at_its_peak",
)
UNREADABLE_GEOMETRY = "unreadable_geometry"
# The tendons, and the pads the seam parts.
TENDONS = ("patellar_tendon", "quadriceps_tendon")
PAD_FIELDS = ("quadriceps_fat_pad", "prefemoral_fat_pad", "suprapatellar_recess_ridge")
# A squint tile stands for a patch this wide: its centre is in front of the femur when any of the
# tile can be, half a tile either way.
PATELLA_TILE_MARGIN_MM = SQUINT_TILE_MM / 2.0


def patella_corridor(
    series: Series,
    z: int,
    frame: PlaneFrame,
    shape: tuple[int, int],
    landmarks: tuple[float, float],
) -> np.ndarray:
    """The pixels of slice z in front of the femur and no higher than `PATELLA_ABOVE_MM` above its
    lowest carried place (`in_front_of_the_femur`): where the patella can lie there, an upper bound
    and never its section. Made once for the series, the slice and the landmarks."""

    def make() -> np.ndarray:
        rows, cols = np.indices(shape)
        places = frame.to_patient(
            np.column_stack((rows.ravel(), cols.ravel())).astype(float)
        ).reshape(*shape, 3)
        return handed_on(in_front_of_the_femur(places, *landmarks))

    return once("patella_corridor", (series.row.series_uid, z, landmarks), make)


@dataclass(frozen=True)
class TwinReading:
    """What the other sequence's slice through one pointed plane says beside the plane: the twin's
    `slice` (None where it has none) and the `code` (`read`, or why not: an unknown, never an
    absence); on the twin's own pixels the `objects` the plane's naming laid on (the bones, the
    patella, both pads), the dark `bands` its light reads there, the two tendons `patellar` and
    `quadriceps` (the extensor mechanism's established rule) and the `pads` laid on; their
    `tendon_codes`; `off_mm` the patella's distance from the twin's plane; and, on the plane's
    own pixels, its naming with the tendons laid on (`fs_objects`), the paired acquisitions'
    `ratio` and the seam the pads are parted about (`anterior`, `posterior`, `ridge`) with
    their `pad_code`."""

    slice: int | None
    code: str
    objects: np.ndarray | None
    bands: np.ndarray | None
    patellar: np.ndarray | None
    quadriceps: np.ndarray | None
    tendon_codes: dict[str, str]
    off_mm: float | None
    pads: tuple[np.ndarray, np.ndarray, np.ndarray] | None
    fs_objects: np.ndarray
    ratio: np.ndarray | None
    seam: tuple[np.ndarray, np.ndarray, np.ndarray] | None
    pad_code: str


def twin_reading(
    own: Measured, twin: Measured | None, plane: PatellaPlane
) -> TwinReading:
    """The extensor tendons and the two suprapatellar pads on ONE pointed plane, from the other
    sequence's slice through the same place (found by the scanner's millimetres, never equal
    indices: `slice_through`), by the established rules and the pair's matches of places
    (`matched`, once per direction and pair): the plane's bones, patella and pads laid onto the twin;
    there the dark bands (`dark_bands`) and the tendon joining the patella and the tibia
    (`extensor_tendons`: below the patella the patellar tendon, above it the quadriceps tendon),
    read once for the twin's slice and the naming laid on it; the tendons laid back onto the plane
    (where nothing holds the place but the fat beside the patella, as `lay_parts` does) and the
    seam of the paired acquisitions' ratio (`relative_signal`, `suprapatellar_pads`) in the
    suprapatellar fat that is left. No lens is read on the twin. Every failure is a code, and the
    plane's own reading is kept beside it."""
    if plane.objects is None:
        raise ValueError("a_pointed_plane_that_was_read")
    objects = np.asarray(plane.objects)

    def failed(code: str, index: int | None = None) -> TwinReading:
        return TwinReading(
            index,
            code,
            None,
            None,
            None,
            None,
            dict.fromkeys(TENDONS, code),
            None,
            None,
            objects,
            None,
            None,
            code,
        )

    if twin is None:
        return failed("none_of_the_other_sequence")
    other = twin.series
    thick, why = slab_thicknesses(other)
    if why is not None:
        return failed(why)
    frame = plane_frame(own.series, plane.slice)
    if isinstance(frame, str):
        return failed(frame)
    origins = np.asarray([np.asarray(p, dtype=float) for p in other.geometry.position])
    index = slice_through(frame.origin_lps, origins, twin.frame.normal(), thick)
    if index is None:
        return failed("twin_has_no_slice_at_this_place")
    twin_frame = plane_frame(other, index)
    if isinstance(twin_frame, str):
        return failed(twin_frame, index)
    uid, twin_uid = own.series.row.series_uid, other.row.series_uid
    here = {"series_uid": uid, "slice_index": plane.slice}
    there = {"series_uid": twin_uid, "slice_index": index}
    plane_here = np.asarray(own.series.volume[plane.slice])
    plane_there = np.asarray(other.volume[index])
    forward = matched(
        other, there, twin_frame, plane_there.shape, here, frame, plane_here
    )
    if isinstance(forward, str):
        return failed(forward, index)
    backward = matched(
        own.series, here, frame, plane_here.shape, there, twin_frame, plane_there
    )
    if isinstance(backward, str):
        return failed(backward, index)
    # the plane's naming laid on the twin, where the twin has places of it
    laid = laid_by(objects, forward)
    named = np.zeros(plane_there.shape, dtype=np.int8)
    for name in ("femur", "tibia", "patella", "hoffa_fat_pad", "suprapatellar_fat"):
        named[laid == OBJECT_CODES[name]] = OBJECT_CODES[name]
    seen = finite_of(other)[index]
    named[~seen] = 0  # a place the twin never saw holds nothing laid on it
    spacing = np.linalg.norm(twin_frame.basis_lps, axis=0)
    measures = measures_of(twin_uid, index, plane_there, twin_frame)

    def read() -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        reads("series", ("volume",), "patella_tendons")
        bands = dark_bands(
            plane_there,
            named,
            spacing,
            margin_of(twin_uid, index, plane_there),
            measures,
        )
        below, above = extensor_tendons(
            bands, named, spacing, twin_frame.basis_lps, measures
        )
        handed("patella_tendons", ("bands", "region"))
        return handed_on(bands), below, above

    bands, patellar, quadriceps = once(
        "patella_tendons", (twin_uid, index, digest(named)), read
    )
    reads("patella_tendons", ("bands",), "patella_extensor_rule")
    reads("patella_tendons", ("region",), "patella_tendons_laid")
    reads("patella_plane", ("objects",), "patella_twin")
    ends = bool(
        (named == OBJECT_CODES["patella"]).any()
        and (named == OBJECT_CODES["tibia"]).any()
    )
    front = bool(own.assignment.in_plane[1])
    tendon_codes = {
        name: tendon_code(front, False, ends, bool(mask.any()), above)
        for name, mask, above in (
            ("patellar_tendon", patellar, False),
            ("quadriceps_tendon", quadriceps, True),
        )
    }
    # the tendons laid back onto the plane, where nothing holds the place but the fat pads
    fat = (OBJECT_CODES["hoffa_fat_pad"], OBJECT_CODES["suprapatellar_fat"])
    named_here = objects.copy()
    open_to_them = np.isin(named_here, (0, *fat))
    for name, mask in (
        ("patellar_tendon", patellar),
        ("quadriceps_tendon", quadriceps),
    ):
        placed = (laid_by(mask.astype(np.int8), backward) == 1) & open_to_them
        named_here[placed] = OBJECT_CODES[name]
    # the pads: the seam of the paired acquisitions' ratio inside the suprapatellar fat left
    combined = named_here == OBJECT_CODES["suprapatellar_fat"]
    ratio = None
    seam = None
    pad_code = "abstain_no_suprapatellar_fat"
    if combined.any():
        paired = laid_by(plane_there.astype(np.float64), backward)
        paired[backward < 0] = np.nan
        ratio = relative_signal(plane_here, paired)
        back_mm = measures_of(uid, plane.slice, plane_here, frame).along(1)
        anterior, posterior, ridge, pad_code = suprapatellar_pads(
            ratio, combined, frame.basis_lps, back_mm
        )
        seam = (anterior, posterior, ridge)
    # what the plane named, laid onto the twin's slice by the same match

    def onto_twin(mask: np.ndarray) -> np.ndarray:
        return (laid_by(mask.astype(np.int16), forward) == 1) & seen

    pads = (
        None
        if seam is None
        else (onto_twin(seam[0]), onto_twin(seam[1]), onto_twin(seam[2]))
    )
    places = frame.to_patient(
        np.argwhere(objects == OBJECT_CODES["patella"]).astype(float)
    )
    off = (
        float(abs((places.mean(axis=0) - twin_frame.origin_lps) @ twin_frame.normal()))
        if len(places)
        else None
    )
    return TwinReading(
        index,
        "read",
        named,
        bands,
        patellar,
        quadriceps,
        tendon_codes,
        off,
        pads,
        named_here,
        ratio,
        seam,
        pad_code,
    )


@dataclass(frozen=True)
class PatellaRead:
    """The patella in one series, as `read_patella` read it: the cheap `profile` through depth, the
    `planes` it pointed to (the middle slice's bootstrap among them where it was), the twin's reading
    beside each plane that named the patella (`twins`, aligned with the planes but the middle one;
    None where none was asked), how the bone came out (`outcome`), the record's description
    (`record`, plain data), the arrays it keeps on the series (`arrays`, `a3_patella_*`; what the
    twin keeps is `patella_twin_arrays`) and the sections named (`sections`: slice, region,
    frame), the middle slice's bootstrap among them where it names the patella."""

    profile: BoneProfile
    planes: tuple[PatellaPlane, ...]
    twins: tuple[TwinReading | None, ...]
    outcome: str
    record: dict
    arrays: dict[str, np.ndarray]
    sections: tuple[tuple[int, np.ndarray, PlaneFrame], ...]


def stack_of(items: list[np.ndarray], shape: tuple[int, int], dtype: Any) -> np.ndarray:
    """A stack of equal planes (n, R, C), empty (0, R, C) for none: one row per read plane."""
    return np.stack(items) if items else np.empty((0, *shape), dtype=dtype)


def patella_local_arrays(planes: list[PatellaPlane]) -> dict[str, np.ndarray]:
    """Every bounded reading the planes kept, ragged. Attempt i's crop arrays are
    `a3_patella_local_<array>[crop_offsets[i]:crop_offsets[i + 1]]` reshaped to `crop_shapes[i]`
    (crop-local, native pixel size; `window_rc[i]` is its native half-open place and
    `slices[i]` the plane it belongs to). Its territories' peaks are
    `peaks[peak_offsets[i]:peak_offsets[i + 1]]` (territory, depth_mm, native row, native column,
    local_superior_mm); `a3_patella_local_peak_columns` names these five columns. Code dictionaries are
    ragged key/value arrays (`part_code_*`, `field_code_*`, each with
    `_offsets`). `outcome` indexes `outcome_names`, `in_plane` columns are `in_plane_axes`, and
    `objects`/`field_objects` values are named by `object_code_names`/`object_code_values`.
    `frame_origin_lps` and `frame_basis_lps` are the crop's own frame. Empty when none was made."""
    owned = [(p.slice, a) for p in planes for a in p.attempts]
    attempts = [a for _, a in owned]
    count = len(attempts)

    def offsets(sizes: list[int]) -> np.ndarray:
        return np.concatenate(([0], np.cumsum(sizes, dtype=np.int64))).astype(np.int64)

    def flat(name: str, empty: Any) -> np.ndarray:
        parts = []
        for a in attempts:
            value = np.asarray(getattr(a, name))
            if value.shape != np.shape(a.raw):
                raise ValueError(f"patella_local_{name}_shape_differs_from_the_crop")
            parts.append(value.ravel())
        return np.concatenate(parts) if parts else np.empty(0, dtype=empty)

    def ragged(rows: list[dict[str, str]]) -> tuple[np.ndarray, ...]:
        keys = [key for row in rows for key in sorted(row)]
        values = [row[key] for row in rows for key in sorted(row)]
        return (
            np.asarray(keys, dtype=str),
            np.asarray(values, dtype=str),
            offsets([len(row) for row in rows]),
        )

    def text(name: str) -> np.ndarray:
        return np.asarray([getattr(a, name) for a in attempts], dtype=str)

    part_keys, part_values, part_offsets = ragged([a.codes for a in attempts])
    field_keys, field_values, field_offsets = ragged([a.field_codes for a in attempts])
    object_codes = sorted(OBJECT_CODES.items(), key=lambda item: item[1])
    return {
        "a3_patella_local_slices": np.asarray([z for z, _ in owned], dtype=np.int32),
        "a3_patella_local_window_rc": np.asarray(
            [a.window_rc for a in attempts], dtype=np.int32
        ).reshape(count, 4),
        "a3_patella_local_crop_shapes": np.asarray(
            [np.shape(a.raw) for a in attempts], dtype=np.int32
        ).reshape(count, 2),
        "a3_patella_local_crop_offsets": offsets(
            [int(np.size(a.raw)) for a in attempts]
        ),
        "a3_patella_local_outcome": np.asarray(
            [
                PATELLA_OUTCOMES.index(a.code) if a.code in PATELLA_OUTCOMES else -1
                for a in attempts
            ],
            dtype=np.int8,
        ),
        "a3_patella_local_outcome_names": np.asarray(PATELLA_OUTCOMES, dtype=str),
        "a3_patella_local_scope_code": text("scope_code"),
        "a3_patella_local_scope_reason": text("scope_reason"),
        "a3_patella_local_reading_code": text("reading_code"),
        "a3_patella_local_where": text("where"),
        "a3_patella_local_femur": text("femur"),
        "a3_patella_local_tibia": text("tibia"),
        "a3_patella_local_part_code_keys": part_keys,
        "a3_patella_local_part_code_values": part_values,
        "a3_patella_local_part_code_offsets": part_offsets,
        "a3_patella_local_field_code_keys": field_keys,
        "a3_patella_local_field_code_values": field_values,
        "a3_patella_local_field_code_offsets": field_offsets,
        "a3_patella_local_in_plane": np.asarray(
            [a.axes_in_plane for a in attempts], dtype=bool
        ).reshape(count, 3),
        "a3_patella_local_in_plane_axes": np.asarray(
            ("side_to_side", "front_to_back", "along_the_leg"), dtype=str
        ),
        "a3_patella_local_light": np.asarray(
            [np.nan if a.light is None else a.light for a in attempts],
            dtype=np.float64,
        ),
        "a3_patella_local_body_held": np.asarray(
            [-1 if a.body_held is None else a.body_held for a in attempts],
            dtype=np.int32,
        ),
        "a3_patella_local_peak_rc": np.asarray(
            [(-1, -1) if a.peak is None else a.peak for a in attempts], dtype=np.int32
        ).reshape(count, 2),
        "a3_patella_local_frame_origin_lps": np.asarray(
            [a.frame_origin_lps for a in attempts], dtype=np.float64
        ).reshape(count, 3),
        "a3_patella_local_frame_basis_lps": np.asarray(
            [a.frame_basis_lps for a in attempts], dtype=np.float64
        ).reshape(count, 3, 2),
        "a3_patella_local_raw": flat("raw", np.float64),
        "a3_patella_local_finite": flat("finite", bool),
        "a3_patella_local_dark": flat("dark", bool),
        "a3_patella_local_distance_mm": flat("distance_mm", np.float64),
        "a3_patella_local_markers": flat("markers", np.int32),
        "a3_patella_local_labels": flat("labels", np.int32),
        "a3_patella_local_available": flat("available", bool),
        "a3_patella_local_outside": flat("outside", bool),
        "a3_patella_local_leg": flat("leg", bool),
        "a3_patella_local_field_objects": flat("field_objects", np.int8),
        "a3_patella_local_objects": flat("objects", np.int8),
        "a3_patella_local_object_code_names": np.asarray(
            [name for name, _ in object_codes], dtype=str
        ),
        "a3_patella_local_object_code_values": np.asarray(
            [value for _, value in object_codes], dtype=np.int16
        ),
        "a3_patella_local_peak_offsets": offsets([len(a.peaks) for a in attempts]),
        "a3_patella_local_peak_columns": np.asarray(
            ["territory", "depth_mm", "native_row", "native_col", "local_superior_mm"],
            dtype=str,
        ),
        "a3_patella_local_peaks": np.concatenate(
            [np.asarray(a.peaks, dtype=np.float64).reshape(-1, 5) for a in attempts]
        )
        if attempts
        else np.empty((0, 5), dtype=np.float64),
    }


def patella_arrays(
    own: Measured, planes: list[PatellaPlane], twins: list[TwinReading | None]
) -> dict[str, np.ndarray]:
    """The planes' own readings as stacks, one row per pointed plane but the middle slice (whose
    arrays hold its own): the plane's `slices` and `outcome` (an index into `PATELLA_OUTCOMES`, -1
    where the geometry was unreadable), the lens's `labels` and `available`, its naming `objects`
    (with the tendons laid on where the twin was read), the femur's marrow `light`, the `peak_rc` the
    patella was read at and `body_held` (-1 where none), and the pads: the seam's `pad_anterior`,
    `pad_posterior` and `pad_ridge` and the paired acquisitions' `relative_signal`. Each plane's
    `scope_code`, `scope_reason` and final `window_rc` (-1 for the whole frame, broadened or not)
    say how it was bounded, and `patella_local_arrays` keeps every bounded reading made,
    including those that missed."""
    shape = np.shape(own.arrays["acquired_plane"])
    zero, nothing = np.zeros(shape, dtype=bool), np.full(shape, np.nan)
    arrays: dict[str, np.ndarray] = {
        "a3_patella_plane_slices": np.asarray(
            [p.slice for p in planes], dtype=np.int32
        ),
        "a3_patella_plane_outcome": np.asarray(
            [
                PATELLA_OUTCOMES.index(p.code) if p.code in PATELLA_OUTCOMES else -1
                for p in planes
            ],
            dtype=np.int8,
        ),
        "a3_patella_plane_light": np.asarray(
            [np.nan if p.light is None else p.light for p in planes], dtype=np.float64
        ),
        "a3_patella_plane_peak_rc": np.asarray(
            [(-1, -1) if p.peak is None else p.peak for p in planes], dtype=np.int32
        ).reshape(len(planes), 2),
        "a3_patella_plane_body_held": np.asarray(
            [-1 if p.body_held is None else p.body_held for p in planes], dtype=np.int32
        ),
        "a3_patella_plane_scope_code": np.asarray(
            [p.scope_code for p in planes], dtype=str
        ),
        "a3_patella_plane_scope_reason": np.asarray(
            [p.scope_reason for p in planes], dtype=str
        ),
        "a3_patella_plane_window_rc": np.asarray(
            [(-1, -1, -1, -1) if p.window_rc is None else p.window_rc for p in planes],
            dtype=np.int32,
        ).reshape(len(planes), 4),
        "a3_patella_plane_labels": stack_of(
            [
                np.zeros(shape, np.int32) if p.labels is None else p.labels
                for p in planes
            ],
            shape,
            np.int32,
        ),
        "a3_patella_plane_available": stack_of(
            [zero if p.available is None else p.available for p in planes], shape, bool
        ),
    }
    objects, ratio = [], []
    seams: list[list[np.ndarray]] = [[], [], []]
    for plane, twin in zip(planes, twins, strict=True):
        named = (
            twin.fs_objects
            if twin is not None
            else (plane.objects if plane.objects is not None else None)
        )
        objects.append(np.zeros(shape, np.int8) if named is None else np.asarray(named))
        ratio.append(nothing if twin is None or twin.ratio is None else twin.ratio)
        for held, made in zip(
            seams,
            twin.seam if twin is not None and twin.seam is not None else (zero,) * 3,
            strict=True,
        ):
            held.append(made)
    arrays["a3_patella_plane_objects"] = stack_of(objects, shape, np.int8)
    arrays["a3_patella_plane_relative_signal"] = stack_of(ratio, shape, np.float64)
    for field, held in zip(("anterior", "posterior", "ridge"), seams, strict=True):
        arrays[f"a3_patella_plane_pad_{field}"] = stack_of(held, shape, bool)
    arrays.update(patella_local_arrays(planes))
    return arrays


def patella_twin_arrays(
    twin: Measured,
    planes: list[PatellaPlane],
    twins: list[TwinReading | None],
    prefix: str,
) -> dict[str, np.ndarray]:
    """What the twin's slices through the pointed planes say, as stacks on the twin's own pixels,
    named `<prefix>_*`, one row per plane whose twin was read: the plane's slice (`from_slices`)
    and the twin's (`slices`), the plane's naming laid on (`objects`), the dark `bands`, both
    tendons and the pads laid on. (The prefix names the series that asked, so two sequences
    asking one twin never overwrite each other.)"""
    shape = np.shape(twin.arrays["acquired_plane"])
    zero = np.zeros(shape, dtype=bool)
    rows = [
        (p, t)
        for p, t in zip(planes, twins, strict=True)
        if t is not None and t.code == "read"
    ]
    arrays: dict[str, np.ndarray] = {
        f"{prefix}_from_slices": np.asarray([p.slice for p, _ in rows], dtype=np.int32),
        f"{prefix}_slices": np.asarray(
            [-1 if t.slice is None else t.slice for _, t in rows], dtype=np.int32
        ),
        f"{prefix}_objects": stack_of(
            [
                np.zeros(shape, np.int8) if t.objects is None else t.objects
                for _, t in rows
            ],
            shape,
            np.int8,
        ),
        f"{prefix}_bands": stack_of(
            [
                np.zeros(shape, np.int32) if t.bands is None else t.bands
                for _, t in rows
            ],
            shape,
            np.int32,
        ),
        f"{prefix}_patellar_tendon": stack_of(
            [zero if t.patellar is None else t.patellar for _, t in rows], shape, bool
        ),
        f"{prefix}_quadriceps_tendon": stack_of(
            [zero if t.quadriceps is None else t.quadriceps for _, t in rows],
            shape,
            bool,
        ),
    }
    for k, field in enumerate(("anterior", "posterior", "ridge")):
        arrays[f"{prefix}_pad_{field}"] = stack_of(
            [zero if t.pads is None else t.pads[k] for _, t in rows], shape, bool
        )
    return arrays


def patella_neighbourhood(
    own: Measured, reference: Reference | str, guided: Guide | None = None
) -> tuple[np.ndarray | None, dict]:
    """Where along this series' stack the patella is looked for first, relative to the study's
    reference (`select_reference`): which slices lie within the cohort's range of the patella's
    native-resolved sections around the reference's place along THIS series' normal
    (`PATELLA_FROM_REFERENCE_MM`, `knee.collapse.reference`), by the scanner's millimetres and never
    by slice indices. The offset is read medially where the header names the knee on a sagittal
    series and the cohort measured it, else toward the patient's left. The middle slice (the
    bootstrap's own naming) is always among them. None for the slices where anything here is
    unknown (no reference, an axis the offsets were not measured on, a slice with no place, no
    cohort range for this kind of reference): the whole depth is then read, as before. The
    returned dict says which, with every number the window was made from.

    With the study map (`guided`, from `knee.collapse.study_map`) the window is the map's: every slice
    from the lowest to the highest expected place of the patella given each complete anchor, widened by
    the anatomy's allowance, in THIS series' own geometry; the cohort range above is then not read at all.
    A map that cannot guide (no anchor, no ideal) reads the whole depth, with its reason."""
    if guided is not None:
        reads("study_map", ("guide",), "patella")
        if guided.status != "guided":
            return None, {"code": f"map_{guided.status}"}
        depth = len(own.series.volume)
        inside = np.zeros(depth, dtype=bool)
        inside[[z for z in guided.slices if 0 <= z < depth]] = True
        inside[own.record["slice_index"]] = True
        return inside, {
            "code": "map_window",
            "anchors": list(guided.anchors),
            "prediction_spread_mm": guided.spread_mm,
            "half_in_plane_px": None
            if guided.half_px is None
            else list(guided.half_px),
            "predictions": list(guided.placements),
            "slices_in": int(inside.sum()),
        }
    if isinstance(reference, str):
        return None, {"code": f"no_reference_{reference}"}
    reads(
        "reference",
        ("support_lps", "thickness_mm", "series_uid", "bone", "slices"),
        "patella",
    )
    series = own.series
    unit = np.asarray(own.frame.normal(), dtype=np.float64)
    knee = str(own.record["assignments"]["knee"])
    plane = own.record["view"][0]
    origins, _, _, sound = series_depth(series, own.frame, own.record["slice_index"])
    if not sound:
        return None, {"code": "slice_places_unknown_the_geometry_is_unsound"}
    unit = unit / np.linalg.norm(unit)
    position = reference_position(reference.support_lps, unit, reference.thickness_mm)
    if position is None:
        return None, {"code": "reference_position_unknown"}
    mean, low, high, kind = position
    said: dict[str, Any] = {
        "reference_series_uid": reference.series_uid,
        "reference_bone": reference.bone,
        "reference_slices": list(reference.slices),
        "reference_kind": kind,
        "reference_mm": mean,
        "reference_support_mm": [low, high],
    }
    for convention, sign_of in (
        ("medial", (unit, plane, knee)),
        ("left", (unit, "", "")),
    ):
        signed = offset_sign(*sign_of)
        if signed is None or signed[1] != convention:
            continue
        found = PATELLA_FROM_REFERENCE_MM.get((kind, convention))
        if found is None:
            continue
        inside = expected_slices(
            origins @ unit, mean, signed[0], found, own.record["slice_index"]
        )
        if inside is None:
            return None, {**said, "code": "slice_places_unknown"}
        said.update(
            code="window",
            convention=convention,
            expected_offset_mm=list(found),
            offset_sign=signed[0],
            slices_in=int(inside.sum()),
        )
        return inside, said
    return None, {**said, "code": "no_cohort_range_for_this_axis_or_kind_of_reference"}


def read_patella(
    own: Measured,
    partner: Measured | None,
    femur_lps: np.ndarray,
    tibia_lps: np.ndarray,
    reference: Reference | str,
    mapping: "MapContext | None" = None,
) -> PatellaRead | str:
    """The patella of one series through the whole depth: the cheap profile of its marrow body in
    front of the femur (`bone_profile`, with the corridor of `patella_corridor` and the femur's
    light), the pointed planes (each run's maximum, every tie, every run, and the slice beside a
    maximum the window cut: `positive_runs`, `run_maxima`, `confirmations`), and on only those planes
    the established rule (`patella_plane`) and, beside each plane that names the patella, the
    extensor tendons and the pads (`twin_reading`); the middle slice is the bootstrap's own naming
    and is not read again. The extent along the leg is the heights of the sections named, each end
    observed, clipped by the scan or unresolved (`section_extent`), and the planes' places along the
    stack's normal; the patella is ONE bone, so every named plane is one more section of it. Or why
    the series cannot be read: a string code, an unknown and never an absence. The patella is
    named by its light, so only a fat-suppressed series that runs front to back in the plane and
    names the femur on its middle slice is profiled (the existing `patella_code`'s own refusals)."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    index = record["slice_index"]
    objects = own.arrays["a1_objects"]
    mask = objects == OBJECT_CODES["femur"]
    refusal = patella_code(
        bool(own.assignment.in_plane[1]),
        bool(record["assignments"]["femur"] is not None and mask.any()),
        int(series.row.fat_suppression) == 1,
        True,
        True,
    )
    if refusal != "identified":
        return refusal
    reads("squint_stack", ("code",), "patella")
    if own.stack.code != "present":
        return f"squint_{own.stack.code}"
    if series.volume is None:
        return "no_stacked_volume"
    landmarks = femur_landmarks(femur_lps)
    if landmarks is None:
        return "no_carried_places"
    light = float(
        measures_of(uid, index, own.arrays["acquired_plane"], own.frame).light(mask)
    )
    shape = np.shape(own.arrays["acquired_plane"])
    keys = (digest(femur_lps), digest(tibia_lps))
    # Where to look first: the expected neighbourhood of the study's reference (`patella_neighbourhood`),
    # else the whole depth at once.
    guided = None if mapping is None else mapping.guide("patella", own)
    window, search = patella_neighbourhood(own, reference, guided)
    partial = window is not None and not window.all()
    boxes_of: dict[int, list[tuple[float, float, float, float]] | None] = {}

    def in_plane_boxes(z: int):
        """The map's expected places of the patella on slice z, as boxes of the anatomy's allowance in this
        slice's pixels; None where the map gives no place or no allowance."""
        if guided is None or guided.status != "guided" or guided.half_px is None:
            return None
        if z not in boxes_of:
            frame = plane_frame(series, z)
            boxes_of[z] = (
                None
                if isinstance(frame, str)
                else [
                    (float(r), float(c), guided.half_px[0], guided.half_px[1])
                    for r, c in frame.to_native(
                        np.array(
                            [row["point_lps"] for row in guided.placements], dtype=float
                        )
                    )
                ]
            )
        return boxes_of[z]

    depth = len(series.volume)
    read_at: dict[int, tuple[PatellaPlane, TwinReading | None]] = {}

    def ask(z: int, fine_of: dict[int, FineReading]) -> None:
        """One pointed plane read natively, once: the middle slice is the bootstrap's own naming;
        any other is the established rule (`patella_plane`) and, where it names the patella, the
        extensor tendons and the pads on the twin's slice (`twin_reading`)."""
        if z == index:
            code = record["assignments"]["codes"].get("patella", "")
            read_at[z] = (
                PatellaPlane(
                    z, True, code, {}, "", "", None, None, None, None, None, None
                ),
                None,
            )
            return
        windows = profile.window_rc
        got = patella_plane(
            own,
            z,
            femur_lps,
            tibia_lps,
            keys,
            body_pixels(fine_of[z], shape) if z in fine_of else None,
            "patella",
            in_plane_boxes(z),
            profile_window=windows[z] if 0 <= z < len(windows) else None,
        )
        if mapping is not None and got.in_plane != "unguided_in_plane":
            mapping.smap.note_use("patella", uid, got.in_plane, slice=z, code=got.code)
        read_at[z] = (
            got,
            twin_reading(own, partner, got)
            if got.code == "identified" and got.objects is not None
            else None,
        )

    def cheap(visit: np.ndarray | None) -> BoneProfile:
        """The cheap profile of the patella's marrow body over the slices `visit` names (the whole
        depth for None); the others stay `not_read`, unknown and never empty."""
        return bone_profile(
            series,
            own.stack,
            np.empty((0, 3)),
            thinned(np.concatenate((femur_lps, tibia_lps))),
            light,
            "patella",
            lambda z, frame, shape: patella_corridor(
                series, z, frame, shape, landmarks
            ),
            LIKE_THE_FEMUR,
            visit,
        )

    visited = window.copy() if partial and window is not None else np.ones(depth, bool)
    profile = cheap(visited if partial else None)
    passes = 1
    stopped = "no_run_named_the_patella"
    for step in (0, 1):
        if step == 1:
            # the expected neighbourhood did not name the patella: the rest of the depth
            rest = ~visited
            if not (partial and rest.any()):
                break
            profile = merge_profiles(profile, cheap(rest), rest)
            visited = np.ones(depth, dtype=bool)
            passes = 2
        reads("bone_profile", ("status", "area_mm2"), "patella")
        while step == 0 and partial:
            # A run whose strongest slice lies at the edge of what was read has its maximum
            # beyond it, not here: the profile walks on, one slice at a time, to where the run
            # peaks, so that the plane asked is the run's own representative and not the
            # window's edge.
            runs = positive_runs(profile.area_mm2)
            more = np.zeros(depth, dtype=bool)
            for (a, b), peaks in zip(
                runs, run_maxima(profile.area_mm2, runs), strict=True
            ):
                if a in peaks and a > 0 and not visited[a - 1]:
                    more[a - 1] = True
                if b - 1 in peaks and b < depth and not visited[b]:
                    more[b] = True
            if not more.any():
                break
            profile = merge_profiles(profile, cheap(more), more)
            visited |= more
            ledger.record("patella.walked_slices", planes=int(more.sum()))
        runs = positive_runs(profile.area_mm2)
        maxima = run_maxima(profile.area_mm2, runs)
        confirm = confirmations(
            runs, maxima, profile.status, (FIBULA_POINTER_STATUS["cut"],)
        )
        fine_of = {f.index: f for f in profile.fine}
        # Each run is asked at its own maxima (every tie) and the slice beside a maximum its
        # window cut, the strongest run first, until one names the patella: the representative
        # question is answered, and the runs not asked stay pointers (`not_read_natively`).
        order = sorted(
            range(len(runs)), key=lambda i: -float(profile.area_mm2[maxima[i][0]])
        )
        stopped = "no_run_named_the_patella"
        for i in order:
            a, b = runs[i]
            here = sorted(
                {int(z) for z in maxima[i]}
                | {int(z) for z in confirm if z in (a - 1, b)}
            )
            for z in here:
                if z not in read_at:
                    ask(z, fine_of)
            if any(read_at[z][0].code == "identified" for z in here):
                stopped = "a_run_named_the_patella_the_rest_stay_pointers"
                break
        if stopped.startswith("a_run"):
            break
    pointed = sorted({int(z) for peaks in maxima for z in peaks} | set(confirm))
    ledger.record("patella.pointed_planes", planes=len(pointed))
    ledger.record("patella.planes_asked", planes=len(read_at))
    broadened = passes > 1
    found_patella = stopped.startswith("a_run")
    if mapping is not None:
        use = (
            "unguided_full_search"
            if window is None
            else "guided_hit"
            if not broadened and found_patella
            else "guided_miss_then_full_search_found"
            if found_patella
            else "guided_miss_then_full_search_none"
        )
        mapping.smap.note_use("patella", uid, use, passes=passes)
        ledger.record(f"study_map.{use}", series=1)
    if window is not None:
        ledger.record("patella.window_slices_in", planes=int(window.sum()))
        ledger.record(
            "patella.window_slices_unvisited", planes=int(np.count_nonzero(~visited))
        )
        ledger.record("patella.window_broadened", planes=int(broadened))
    planes = [read_at[z][0] for z in sorted(read_at)]
    twins = [read_at[z][1] for z in sorted(read_at) if not read_at[z][0].middle]
    # the bootstrap's own naming of the patella is a section whether or not the profile pointed to it
    sections: list[tuple[int, np.ndarray, PlaneFrame]] = []
    middle = objects == OBJECT_CODES["patella"]
    if record["assignments"]["codes"].get("patella") == "identified" and middle.any():
        sections.append((index, middle, own.frame))
    for p in planes:
        frame = plane_frame(series, p.slice)
        if isinstance(frame, str) or p.middle:
            continue
        if p.code == "identified" and p.objects is not None:
            reads("patella_plane", ("objects",), "patella")
            sections.append((p.slice, p.objects == OBJECT_CODES["patella"], frame))
    if not pointed:
        outcome = (
            "unreadable"
            if np.isin(
                profile.status,
                (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"]),
            ).any()
            else "no_body_found"
        )
    elif any(p.code == "identified" for p in planes):
        outcome = "identified"
    else:
        outcome = "unresolved"
    origins, thick, offsets, sound = series_depth(series, own.frame, index)
    described, ends, spans = describe_runs(runs, profile.status, offsets, thick, sound)
    named = {p.slice for p in planes if p.code == "identified"}
    asked = {p.slice for p in planes}
    rule = np.zeros(len(runs), dtype=np.int8)
    for i, ((a, b), peaks) in enumerate(zip(runs, maxima, strict=True)):
        here = sorted(
            {int(z) for z in peaks} | {int(z) for z in confirm if z in (a - 1, b)}
        )
        described[i]["planes_read_for_it"] = here
        rule[i] = (
            RUN_CONFIRMATION["confirmed_by_the_native_rule"]
            if any(z in named for z in here)
            else RUN_CONFIRMATION["rejected_by_the_native_rule"]
            if any(z in asked for z in here)
            else RUN_CONFIRMATION["not_read_natively"]
        )
        described[i]["native_rule"] = {v: k for k, v in RUN_CONFIRMATION.items()}[
            int(rule[i])
        ]
    # the extent along the leg: the heights of every section named, each end observed or not
    heights = []
    for z, region, frame in sections:
        rows, cols = np.shape(region)
        r, c = np.indices((rows, cols))
        up = frame.to_patient(np.column_stack((r.ravel(), c.ravel())).astype(float))[
            :, 2
        ]
        available = (
            own.arrays["b1_available"]
            if z == index
            else next(p.available for p in planes if p.slice == z)
        )
        got_extent = section_extent(
            region, up.reshape(rows, cols), available, float(max(frame.spacing_rc))
        )
        if got_extent is not None:
            heights.append((z, *got_extent))
    extent: dict[str, Any] = {
        "along": "the scanner's z, up (millimetres)",
        "sections": [
            {"slice": z, "low_mm": lo, "high_mm": hi, "low_end": le, "high_end": he}
            for z, lo, hi, le, he in heights
        ],
        "lateral_positions_mm": [
            finite_or_none(offsets[z]) if sound else None for z, _, _ in sections
        ],
    }
    if heights:
        low = min(heights, key=lambda h: h[1])
        high = max(heights, key=lambda h: h[2])
        extent.update(
            lower_pole_mm=low[1],
            lower_pole_end=low[3],
            upper_pole_mm=high[2],
            upper_pole_end=high[4],
            note="the extent of the sections named: the patella beyond a named plane's own is not "
            "claimed, and an end that is clipped or unresolved is a bound, not the bone's end",
        )
    unknown = [
        int(z)
        for z in np.flatnonzero(
            np.isin(
                profile.status,
                (FIBULA_POINTER_STATUS["unreadable"], FIBULA_POINTER_STATUS["cut"]),
            )
        )
    ]
    ambiguities = []
    if (rule == RUN_CONFIRMATION["rejected_by_the_native_rule"]).any():
        ambiguities.append("a_run_the_native_rule_rejected_is_not_the_patellas_extent")
    if (rule == RUN_CONFIRMATION["not_read_natively"]).any():
        ambiguities.append("a_run_not_read_natively_is_not_the_patellas_extent")
    if unknown:
        ambiguities.append("slices_the_profile_could_not_read_are_unknown_not_empty")
    if not sound:
        ambiguities.append("slice_geometry_unsound_so_no_physical_depth")
    ambiguities.append(
        "the_corridor_is_every_place_in_front_of_the_femurs_carried_places_an_upper_bound"
    )
    if not visited.all():
        ambiguities.append(
            "slices_outside_the_expected_neighbourhood_were_not_visited_unknown_not_empty"
        )
    rows_in = [p for p in planes if not p.middle]
    names = {value: key for key, value in FIBULA_POINTER_STATUS.items()}
    pointed_rows = []
    twin_of = {id(p): t for p, t in zip(rows_in, twins, strict=True)}
    for p in planes:
        row = {
            "slice": p.slice,
            "middle": p.middle,
            "code": p.code,
            "codes": dict(p.codes),
            "femur": p.femur,
            "tibia": p.tibia,
            "marrow_light": None if p.light is None else finite_or_none(p.light),
            "peak_rc": None if p.peak is None else list(p.peak),
            "profile_body_in_the_patella_pixels": p.body_held,
            "patella_pixels": int(
                np.count_nonzero(
                    objects == OBJECT_CODES["patella"]
                    if p.middle
                    else (p.objects == OBJECT_CODES["patella"])
                    if p.objects is not None
                    else 0
                )
            ),
            "position_mm": finite_or_none(offsets[p.slice]) if sound else None,
            "scope": {
                "code": p.scope_code,
                "reason": p.scope_reason,
                "window_rc": None if p.window_rc is None else list(p.window_rc),
                "where": p.in_plane,
                "attempts": [
                    {
                        "window_rc": list(a.window_rc),
                        "scope_code": a.scope_code,
                        "scope_reason": a.scope_reason,
                        "code": a.code,
                        "codes": dict(a.codes),
                        "femur": a.femur,
                        "tibia": a.tibia,
                        "reading_code": a.reading_code,
                        "where": a.where,
                        "field_codes": dict(a.field_codes),
                        "axes_in_plane": list(a.axes_in_plane),
                        "marrow_light": None
                        if a.light is None
                        else finite_or_none(a.light),
                        "body_held": a.body_held,
                        "peak_rc": None if a.peak is None else list(a.peak),
                    }
                    for a in p.attempts
                ],
            },
        }
        if not p.middle:
            twin = twin_of[id(p)]
            row["twin"] = (
                None
                if twin is None
                else {
                    "slice": twin.slice,
                    "code": twin.code,
                    "tendon_codes": dict(twin.tendon_codes),
                    "pad_code": twin.pad_code,
                    "patella_off_the_twin_plane_mm": twin.off_mm,
                }
            )
        pointed_rows.append(row)
    record_part = {
        "outcome": outcome,
        "marrow_light": finite_or_none(profile.light),
        "level_of_the_light": list(LIKE_THE_FEMUR),
        "block_mm": float(LIGAMENT_SMOOTH_MM),
        "context_mm": float(BONE_MM),
        "corridor": {
            "front_y_mm": landmarks[0],
            "femur_lowest_z_mm": landmarks[1],
            "above_the_lowest_mm": float(PATELLA_ABOVE_MM),
            "tile_margin_mm": float(PATELLA_TILE_MARGIN_MM),
            "frame": "the scanner's LPS millimetres: y toward the back, z toward the head",
        },
        "outcomes": list(PATELLA_OUTCOMES),
        "status_codes": dict(FIBULA_POINTER_STATUS),
        "pointer_runs": described,
        "pointer_representatives": [[int(z) for z in peaks] for peaks in maxima],
        "confirmed_slices": [int(z) for z in confirm],
        "pointed_planes": pointed_rows,
        "extent": extent,
        "unknown_slices": unknown,
        "ambiguities": ambiguities,
        "search": {
            **search,
            "passes": passes,
            "broadened_to_the_whole_depth": bool(broadened),
            "stopped": stopped,
            "slices_visited": int(visited.sum()),
            "slices_unvisited": [int(z) for z in np.flatnonzero(~visited)],
            "planes_read_natively": sorted(read_at),
            "planes_the_profile_pointed_to": pointed,
            "reference_key": "record `reference` of the series named by reference_series_uid",
        },
        "slice_status": {
            names[int(c)]: int(np.count_nonzero(profile.status == c))
            for c in np.unique(profile.status)
        },
    }
    pointed_origin = origins[pointed] if sound and pointed else np.empty((0, 3))
    arrays: dict[str, np.ndarray] = {
        "a3_patella_search_window": np.ones(len(profile.area_mm2), dtype=bool)
        if window is None
        else window,
        "a3_patella_search_visited": visited,
        "a3_patella_profile_status": profile.status,
        "a3_patella_profile_area_mm2": profile.area_mm2,
        "a3_patella_profile_pieces": profile.pieces,
        "a3_patella_profile_merged": profile.merged,
        "a3_patella_profile_corridor_tiles": profile.corridor,
        "a3_patella_profile_could_tiles": profile.could,
        "a3_patella_profile_confirmed_tiles": profile.confirmed,
        "a3_patella_profile_window_rc": profile.window_rc,
        "a3_patella_profile_block_mm": profile.cell_mm,
        "a3_patella_profile_block_px": profile.block_px,
        "a3_patella_reference_light": np.asarray(profile.light, dtype=np.float64),
        "a3_patella_pointer_runs": np.asarray(runs, dtype=np.int32).reshape(-1, 2),
        "a3_patella_pointer_run_ends": ends.astype(np.int32),
        "a3_patella_pointer_run_envelope_mm": spans,
        "a3_patella_pointer_run_native_rule": rule,
        "a3_patella_depth_offsets_mm": offsets,
        "a3_patella_slice_thickness_mm": thick,
        "a3_patella_pointed_slices": np.asarray(pointed, dtype=np.int32),
        "a3_patella_pointed_origin_lps": pointed_origin,
        "a3_patella_pointed_position_mm": offsets[pointed]
        if sound and pointed
        else np.empty(0),
        "a3_patella_pole_extent_mm": np.asarray(
            [extent.get("lower_pole_mm", np.nan), extent.get("upper_pole_mm", np.nan)],
            dtype=np.float64,
        ),
        "a3_patella_corridor_landmarks_lps": np.asarray(landmarks, dtype=np.float64),
        "a3_patella_source_normal_lps": own.frame.normal(),
    }
    for name, value in pack_fine_readings(profile.fine).items():
        arrays[
            f"a3_patella_fine_{'corridor' if name == 'tibia_reference' else name}"
        ] = value
    arrays.update(patella_arrays(own, rows_in, twins))
    handed("patella", ("pointed", "sections", "extent", "planes", "twins"))
    return PatellaRead(
        profile,
        tuple(planes),
        tuple(twins),
        outcome,
        record_part,
        arrays,
        tuple(sections),
    )


def source_prefix(base: str, arrays: dict[str, np.ndarray], source_uid: str) -> str:
    """The name under which a series' readings are laid onto a twin's arrays: `base` for the first
    source, and `base` with the source's FULL series uid (its exact identity, never an abbreviation)
    where the twin already holds another source's, so that a twin laid onto from several series
    keeps every source's arrays addressable and no row ever points into another's."""
    return f"{base}_{source_uid}" if f"{base}_slices" in arrays else base


def coded_label(name: str, support: str) -> int | None:
    """The label that selects `name`'s places in the array `support`, or None. A label selects only
    in an array coded by `OBJECT_CODES` (`a1_objects` and the plane stacks' `..._objects`); a
    boolean mask, such as a twin's tendon, has none and is addressed by its row alone."""
    return OBJECT_CODES[name] if support.endswith("objects") else None


def observe(
    name: str,
    provenance: str,
    kind: str,
    on: Measured,
    slices: tuple[int, ...],
    code: str,
    count: int | None,
    off_plane_mm: float | None,
    support: str,
    note: str,
    artifact: str,
    row: int | None = None,
    label: int | None = None,
) -> Observation:
    """One observation of `name` in the series `on`, its series and view read from its record."""
    return observe_in(
        on.record,
        name,
        provenance,
        kind,
        slices,
        code,
        count,
        off_plane_mm,
        support,
        note,
        artifact,
        row,
        label,
    )


def observe_in(
    record: dict,
    name: str,
    provenance: str,
    kind: str,
    slices: tuple[int, ...],
    code: str,
    count: int | None,
    off_plane_mm: float | None,
    support: str,
    note: str,
    artifact: str,
    row: int | None = None,
    label: int | None = None,
) -> Observation:
    """One observation of `name` in the series a record (a middle slice's or a part's own slice's)
    belongs to, its series and view read from the record."""
    return Observation(
        name,
        provenance,
        kind,
        record["series_uid"],
        tuple(record["view"]),
        slices,
        code,
        count,
        off_plane_mm,
        support,
        note,
        artifact,
        row,
        label,
    )


def keep_observations(
    own: Measured, here: list[Observation], missing: list[Unresolved]
) -> None:
    """Add observations to the ones a series' record already holds (`name_the_bones` writes the
    bones'), counted again by provenance: earlier rows stay as written, in their order."""
    keep_on_record(own.record, here, missing)


def keep_on_record(
    record: dict, here: list[Observation], missing: list[Unresolved]
) -> None:
    """`keep_observations` for any record: a middle slice's or a part's own slice's."""
    rows = [*record.get("observations", []), *observation_rows(here)]
    counts = dict.fromkeys(PROVENANCES, 0)
    for row in rows:
        counts[row["provenance"]] += 1
    record["observations"] = rows
    record["observations_by_provenance"] = counts
    record["observations_unresolved"] = [
        *record.get("observations_unresolved", []),
        *unresolved_rows(missing),
    ]


def retinacula_feed(
    measured: list[Measured], leg: Leg, read: PatellaRead
) -> list[dict]:
    """Whether the patella's sections across planes could feed the axial retinacula slice, as a
    READING kept beside its consumer: the centre of every section named against the centre of the
    first native identification (`Leg.patella_lps`), and for each axial series the slice through
    each. The retinacula stage reads the centre of every section (`retinacula_centre`), the
    patella's whole observed extent in place of the one plane that named it first; where no
    section was named it keeps the first identification's."""
    if not len(leg.patella_lps) or not read.sections:
        return []
    points = np.concatenate(
        [
            frame.to_patient(np.argwhere(region).astype(float))
            for _, region, frame in read.sections
        ]
    )
    used, wider = leg.patella_lps.mean(axis=0), points.mean(axis=0)
    found = []
    for other in measured:
        if other.assignment.in_plane[2] or other.series.geometry is None:
            continue
        thick, why = slab_thicknesses(other.series)
        if why is not None:
            found.append({"series_uid": other.record["series_uid"], "unreadable": why})
            continue
        position = other.series.geometry.position
        normal = other.frame.normal()
        now = slice_through(used, position, normal, thick)
        then = slice_through(wider, position, normal, thick)
        found.append(
            {
                "series_uid": other.record["series_uid"],
                "slice_from_the_centre_the_stage_reads": now,
                "slice_from_every_section": then,
                "same_slice": now == then,
            }
        )
    return [
        {
            "centre_the_stage_reads_lps": [float(v) for v in used],
            "centre_of_every_section_lps": [float(v) for v in wider],
            "shift_mm": float(np.linalg.norm(wider - used)),
            "axial": found,
            "wired": True,
        }
    ]


def name_the_patella(
    measured: list[Measured],
    partners: list[Measured | None],
    leg: Leg | None,
    study_uid: str,
    reference: Reference | str,
    mapping: "MapContext | None" = None,
) -> None:
    """The patella through the stacks (`read_patella`) of every fat-suppressed series that runs
    front to back in the plane and names the femur on its middle slice, with the extensor tendons,
    Hoffa's fat pad and the two suprapatellar pads read on the planes it names, kept in the series'
    own middle records and arrays (saved by the caller) beside the observations the bones made.

    Native: the middle slice's own naming of each part (the bootstrap), the patella on each pointed
    plane (resolved where the carried places name it, else a reading with its code), Hoffa's fat
    pad, the suprapatellar fat and the two pads (`quadriceps_fat_pad`, `prefemoral_fat_pad`) on
    each plane where the established rules read them, and the two tendons on the twin's slice
    through each plane (read there from the bands, with the plane's patella and bones laid on).
    Laid: the patella, both fat pads and the pads onto the twin's slice, and the tendons onto the
    plane. Projected: the patella and each tendon onto every other series' nearest slice (a target
    for a native question, never a boundary): on an axial series the tendons' cross-section is
    that question, which no rule yet reads, and is named unresolved. What could not be said is an
    `Unresolved` with its code, an unknown and never an absence; pads on planes the patella does
    not name are unknown, not absent. The extent and what the retinacula could read are kept and
    nothing reads them: the retinacula stage keeps its own centre."""
    carried = leg if leg is not None else leg_of(measured)
    results = [
        read_patella(
            own, partners[i], carried.femur_lps, carried.tibia_lps, reference, mapping
        )
        for i, own in enumerate(measured)
    ]
    where = {id(m): i for i, m in enumerate(measured)}
    said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    for i, own in enumerate(measured):
        read = results[i]
        uid, view = own.record["series_uid"], tuple(own.record["view"])
        here, missing = said[i]
        artifact = str(artifact_of(study_uid, own.record))
        if isinstance(read, str):
            own.record["patella"] = {"outcomes": list(PATELLA_OUTCOMES), "code": read}
            missing.append(Unresolved("patella", "native", uid, view, read))
            continue
        partner = partners[i]
        at = None if partner is None else where[id(partner)]
        index = own.record["slice_index"]
        codes = own.record["assignments"]["codes"]
        rows_in = [p for p in read.planes if not p.middle]
        twins = list(read.twins)
        own.arrays.update(read.arrays)
        prefix = "a3_patella_twin"
        if partner is not None:
            prefix = source_prefix(prefix, partner.arrays, uid)
            partner.arrays.update(patella_twin_arrays(partner, rows_in, twins, prefix))
        own.record["patella"] = {
            **read.record,
            "twin_arrays_prefix": prefix if partner is not None else None,
            "retinacula_feed": retinacula_feed(measured, carried, read),
        }
        handed("patella", ("retinacula_feed",))
        got: set[str] = set()
        # the middle slice: the bootstrap's own naming of each part, as the run made it
        for name in ("patella", "hoffa_fat_pad", "suprapatellar_fat"):
            if codes.get(name) == "identified":
                got.add(name)
                here.append(
                    observe(
                        name,
                        "native",
                        "resolved",
                        own,
                        (index,),
                        "identified",
                        int(
                            np.count_nonzero(
                                own.arrays["a1_objects"] == OBJECT_CODES[name]
                            )
                        ),
                        0.0,
                        "a1_objects",
                        "the middle slice's own naming (the bootstrap): the part on this slice, not the whole",
                        artifact,
                        None,
                        OBJECT_CODES[name],
                    )
                )
        for name in PAD_FIELDS[:2]:
            if codes.get(name) == "identified":
                got.add(name)
                here.append(
                    observe(
                        name,
                        "native",
                        "resolved",
                        own,
                        (index,),
                        "identified",
                        int(np.count_nonzero(own.arrays[f"a2_{name}"])),
                        0.0,
                        f"a2_{name}",
                        "the middle slice's own naming (the bootstrap), parted about the seam of the paired acquisitions",
                        artifact,
                    )
                )
        for name in TENDONS:
            if codes.get(name) in NAMED and codes.get(name) != "identified":
                got.add(name)
                here.append(
                    observe(
                        name,
                        "laid",
                        "resolved",
                        own,
                        (index,),
                        str(codes[name]),
                        int(
                            np.count_nonzero(
                                own.arrays["a1_objects"] == OBJECT_CODES[name]
                            )
                        ),
                        None,
                        "a1_objects",
                        "longitudinal course: laid from the twin's slice of the same place by the pair's match",
                        artifact,
                        None,
                        OBJECT_CODES[name],
                    )
                )
        # the pointed planes: the rules read on each, row by row of the stacks kept
        reason: dict[str, set[str]] = {
            n: set()
            for n in (
                "patella",
                "hoffa_fat_pad",
                "suprapatellar_fat",
                *TENDONS,
                *PAD_FIELDS[:2],
            )
        }
        objects = own.arrays["a3_patella_plane_objects"]
        twin_row = 0
        patella_sections: list[tuple[int, np.ndarray, PlaneFrame, str, int | None]] = []
        if codes.get("patella") == "identified":
            middle = own.arrays["a1_objects"] == OBJECT_CODES["patella"]
            patella_sections.append((index, middle, own.frame, "a1_objects", None))
        tendon_sources: dict[
            str, list[tuple[int, np.ndarray, PlaneFrame, str, int | None, int]]
        ] = {n: [] for n in TENDONS}
        twin_artifact = (
            str(artifact_of(study_uid, partner.record)) if partner is not None else ""
        )
        for row, (p, t) in enumerate(zip(rows_in, twins, strict=True)):
            for name, why in p.codes.items():
                if name in reason:
                    reason[name].add(why)
            if p.code != "identified":
                held = None if p.labels is None else row
                here.append(
                    observe(
                        "patella",
                        "native",
                        "reading",
                        own,
                        (p.slice,),
                        p.code,
                        None,
                        0.0,
                        "a3_patella_plane_labels",
                        "the plane was pointed to and read in full; no patella is named here",
                        artifact,
                        held,
                    )
                )
                continue
            frame = plane_frame(own.series, p.slice)
            got.add("patella")
            region = objects[row] == OBJECT_CODES["patella"]
            here.append(
                observe(
                    "patella",
                    "native",
                    "resolved",
                    own,
                    (p.slice,),
                    "identified",
                    int(np.count_nonzero(region)),
                    0.0,
                    "a3_patella_plane_objects",
                    "the established rule names the patella here: the section on this plane, not the whole bone",
                    artifact,
                    row,
                    OBJECT_CODES["patella"],
                )
            )
            if not isinstance(frame, str):
                patella_sections.append(
                    (p.slice, region, frame, "a3_patella_plane_objects", row)
                )
            for name in ("hoffa_fat_pad", "suprapatellar_fat"):
                if p.codes.get(name) == "identified":
                    got.add(name)
                    here.append(
                        observe(
                            name,
                            "native",
                            "resolved",
                            own,
                            (p.slice,),
                            "identified",
                            int(np.count_nonzero(objects[row] == OBJECT_CODES[name])),
                            0.0,
                            "a3_patella_plane_objects",
                            "the rest of the patella's territory beyond it along the leg, on this plane only; the plane's pads beside the patella beyond it are unknown, not absent",
                            artifact,
                            row,
                            OBJECT_CODES[name],
                        )
                    )
            if t is None:
                continue
            for name in TENDONS:
                reason[name].add(t.tendon_codes[name])
            for name in PAD_FIELDS[:2]:
                reason[name].add(t.pad_code)
            if t.code != "read":
                continue
            for k, (name, field) in enumerate(
                zip(PAD_FIELDS[:2], ("anterior", "posterior"), strict=True)
            ):
                if t.seam is not None and t.pad_code == "identified":
                    got.add(name)
                    here.append(
                        observe(
                            name,
                            "native",
                            "resolved",
                            own,
                            (p.slice,),
                            "identified",
                            int(np.count_nonzero(t.seam[k])),
                            0.0,
                            f"a3_patella_plane_pad_{field}",
                            "the suprapatellar fat parted about the internal seam of the paired acquisitions' ratio; the seam is `a3_patella_plane_pad_ridge`, no membrane thickness",
                            artifact,
                            row,
                        )
                    )
            if partner is None or at is None or t.slice is None or t.objects is None:
                continue  # a read twin has all of them; this only narrows the types
            twin_frame = plane_frame(partner.series, t.slice)
            for name in ("patella", "hoffa_fat_pad", "suprapatellar_fat"):
                if p.codes.get(name) != "identified":
                    continue
                count = int(np.count_nonzero(t.objects == OBJECT_CODES[name]))
                if count:
                    said[at][0].append(
                        observe(
                            name,
                            "laid",
                            "resolved",
                            partner,
                            (t.slice,),
                            "laid_from_its_partner",
                            count,
                            t.off_mm,
                            f"{prefix}_objects",
                            f"the part named on native slice {p.slice} laid by the pair's match of places; places the twin never saw are left out",
                            twin_artifact,
                            twin_row,
                            OBJECT_CODES[name],
                        )
                    )
                else:
                    said[at][1].append(
                        Unresolved(
                            name,
                            "laid",
                            partner.record["series_uid"],
                            tuple(partner.record["view"]),
                            "nothing_of_the_part_lands_on_the_twin",
                        )
                    )
            if t.pads is not None:
                for name, field, mask in zip(
                    PAD_FIELDS[:2], ("anterior", "posterior"), t.pads, strict=False
                ):
                    if np.any(mask):
                        said[at][0].append(
                            observe(
                                name,
                                "laid",
                                "resolved",
                                partner,
                                (t.slice,),
                                "laid_from_its_partner",
                                int(np.count_nonzero(mask)),
                                t.off_mm,
                                f"{prefix}_pad_{field}",
                                f"the pad parted on native slice {p.slice} laid by the pair's match of places",
                                twin_artifact,
                                twin_row,
                            )
                        )
            for name, field, mask in (
                ("patellar_tendon", "patellar_tendon", t.patellar),
                ("quadriceps_tendon", "quadriceps_tendon", t.quadriceps),
            ):
                if t.tendon_codes[name] != "identified" or mask is None:
                    continue
                got.add(name)
                said[at][0].append(
                    observe(
                        name,
                        "native",
                        "resolved",
                        partner,
                        (t.slice,),
                        "identified",
                        int(np.count_nonzero(mask)),
                        0.0,
                        f"{prefix}_{field}",
                        f"longitudinal course: the dark band joining the patella and the tibia read on this slice, with the bones and the patella of native slice {p.slice} laid on; no cross-section",
                        twin_artifact,
                        twin_row,
                    )
                )
                if not isinstance(twin_frame, str):
                    tendon_sources[name].append(
                        (
                            t.slice,
                            mask,
                            twin_frame,
                            f"{prefix}_{field}",
                            twin_row,
                            int(np.count_nonzero(mask)),
                        )
                    )
                placed = int(np.count_nonzero(objects[row] == OBJECT_CODES[name]))
                if placed:
                    here.append(
                        observe(
                            name,
                            "laid",
                            "resolved",
                            own,
                            (p.slice,),
                            "laid_from_its_partner",
                            placed,
                            t.off_mm,
                            "a3_patella_plane_objects",
                            "longitudinal course: laid onto this plane by the pair's match, only where nothing but the fat beside the patella held the place",
                            artifact,
                            row,
                            OBJECT_CODES[name],
                        )
                    )
            twin_row += 1
        # the middle slice's existing tendons on the twin, a candidate source for the targets too
        if partner is not None:
            pcodes = partner.record["assignments"]["codes"]
            for name in TENDONS:
                if pcodes.get(name) == "identified":
                    got.add(name)
                    mask = partner.arrays["a1_objects"] == OBJECT_CODES[name]
                    said[at][0].append(
                        observe(
                            name,
                            "native",
                            "resolved",
                            partner,
                            (partner.record["slice_index"],),
                            "identified",
                            int(np.count_nonzero(mask)),
                            0.0,
                            "a1_objects",
                            "longitudinal course: the middle slice's own naming (the bootstrap), from the dark bands with the patella laid on from the fat-suppressed twin",
                            twin_artifact,
                            None,
                            OBJECT_CODES[name],
                        )
                    )
                    tendon_sources[name].append(
                        (
                            partner.record["slice_index"],
                            mask,
                            partner.frame,
                            "a1_objects",
                            None,
                            int(np.count_nonzero(mask)),
                        )
                    )
                else:
                    reason[name].add(str(pcodes.get(name)))
        # what no plane read is unknown: each part with no native saying names why, never absent
        for name, codes_here in reason.items():
            if name in got:
                continue
            if not codes_here:
                codes_here = {"no_plane_pointed_to_read_it"}
            on_partner = name in TENDONS and partner is not None
            who = partner if on_partner and partner is not None else own
            said[where[id(who)]][1].append(
                Unresolved(
                    name,
                    "native",
                    who.record["series_uid"],
                    tuple(who.record["view"]),
                    "|".join(sorted(codes_here)),
                )
            )
        # projected: the largest section of the patella, and of each tendon, onto every other series
        skip = {uid} | (
            {partner.record["series_uid"]} if partner is not None else set()
        )
        projections: list[
            tuple[
                str,
                tuple[int, np.ndarray, PlaneFrame, str, int | None],
                str,
                int | None,
            ]
        ] = []
        if patella_sections:
            best = max(patella_sections, key=lambda s: int(np.count_nonzero(s[1])))
            projections.append(
                (
                    "patella",
                    best,
                    artifact,
                    coded_label("patella", best[3]),
                )
            )
        for name in TENDONS:
            if tendon_sources[name]:
                best_t = max(tendon_sources[name], key=lambda s: s[5])
                projections.append(
                    (
                        name,
                        best_t[:5],
                        twin_artifact,
                        coded_label(name, best_t[3]),
                    )
                )
        for name, (
            z,
            region,
            frame,
            support,
            source_row,
        ), source_artifact, label in projections:
            physical = frame.to_patient(np.argwhere(region).astype(float))
            for other in measured:
                other_uid = other.record["series_uid"]
                if other_uid in skip:
                    continue
                other_view = tuple(other.record["view"])
                cross = name in TENDONS and not other.assignment.in_plane[2]
                if cross:
                    said[where[id(other)]][1].append(
                        Unresolved(
                            name,
                            "native",
                            other_uid,
                            other_view,
                            "cross_section_not_read_no_rule_reads_the_axial",
                        )
                    )
                target = bone_target(physical, other)
                if isinstance(target, str):
                    said[where[id(other)]][1].append(
                        Unresolved(name, "projected", other_uid, other_view, target)
                    )
                    continue
                nearest, place, distance, count = target
                said[where[id(other)]][0].append(
                    observe(
                        name,
                        "projected",
                        "target",
                        other,
                        (nearest,),
                        place,
                        count,
                        distance,
                        support,
                        f"a location target projected from {name} on slice {z} ({'where its cross-section may be asked' if cross else 'its longitudinal course'}): where a native question may be asked, not a boundary seen on this slice",
                        source_artifact,
                        source_row,
                        label,
                    )
                )
    for m, (here, missing) in zip(measured, said, strict=True):
        if here or missing:
            keep_observations(m, here, missing)


def patella_key_planes(
    measured: list[Measured], mapping: MapContext, study_uid: str
) -> None:
    """Scout the patella's coronal and axial key planes from its native sagittal sections.

    The sagittal masks are the existing recognizer's actual sections. Their native pixels are
    carried into the other views only as location seeds, and only to slice slabs their physical
    voxel extent intersects. The target view's own 2 mm enclosed section is the reading; it is
    retained as a reading and offered to the study map, never as a native patella boundary.
    """
    source_sections: list[tuple[np.ndarray, PlaneFrame, float]] = []
    for source in measured:
        if str(source.record["view"][0]).lower() != "sagittal":
            continue
        for observation in source.record.get("observations", []):
            if (
                observation.get("object") != "patella"
                or observation.get("provenance") != "native"
                or observation.get("kind") != "resolved"
                or observation.get("code") != "identified"
            ):
                continue
            support = str(observation.get("support", ""))
            if support not in ("a1_objects", "a3_patella_plane_objects"):
                continue
            values = source.arrays.get(support)
            if values is None:
                continue
            label = observation.get("label")
            row = observation.get("row")
            section = np.asarray(values)
            if row is not None:
                row = int(row)
                prefix = support.removesuffix("_objects")
                offsets = source.arrays.get(f"{prefix}_offsets")
                shapes = source.arrays.get(f"{prefix}_shapes")
                if offsets is not None and shapes is not None and section.ndim == 1:
                    lo, hi = int(offsets[row]), int(offsets[row + 1])
                    section = section[lo:hi].reshape(tuple(int(v) for v in shapes[row]))
                elif section.ndim >= 3:
                    section = section[row]
                else:
                    continue
            if label is None:
                if section.dtype != np.bool_:
                    continue
                region = section
            else:
                region = section == int(label)
            if region.ndim != 2 or not region.any():
                continue
            slices = observation.get("slices", ())
            if len(slices) != 1:
                continue
            z = int(slices[0])
            frame = plane_frame(source.series, z)
            if isinstance(frame, str):
                continue
            rows, cols = np.nonzero(region)
            points = frame.to_patient(np.column_stack((rows, cols)).astype(float))
            thicknesses = getattr(source.series, "slice_thickness_mm", None)
            thickness = (
                0.0
                if thicknesses is None
                or z >= len(thicknesses)
                or thicknesses[z] is None
                else float(thicknesses[z])
            )
            if not np.isfinite(thickness) or thickness < 0:
                thickness = 0.0
            source_sections.append((points, frame, thickness))
    reads("patella", ("observations",), "patella_key_planes")

    for own in measured:
        orientation = str(own.record["view"][0]).lower()
        if orientation not in ("coronal", "axial"):
            continue
        series = own.series
        uid = own.record["series_uid"]
        volume = getattr(series, "volume", None)
        depth_count = 0 if volume is None else len(volume)
        marrow_is_dark = int(series.row.fat_suppression) == 1
        source_extent = np.zeros(depth_count, dtype=bool)
        readings = []
        depths = []
        sections = []
        read_slices: list[int] = []
        read_frames: list[PlaneFrame] = []
        read_thicknesses: list[float] = []
        areas = np.full(depth_count, np.nan, dtype=np.float64)
        status_counts: dict[str, int] = {}
        source_points_count = 0
        for z in range(depth_count):
            assert (
                volume is not None
            )  # depth_count is zero when the volume is unavailable
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                continue
            normal = frame.normal()
            offset = float(normal @ frame.origin_lps)
            thicknesses = getattr(series, "slice_thickness_mm", None)
            target_thickness = (
                0.0
                if thicknesses is None
                or z >= len(thicknesses)
                or thicknesses[z] is None
                else float(thicknesses[z])
            )
            if not np.isfinite(target_thickness) or target_thickness < 0:
                target_thickness = 0.0
            target_half = target_thickness / 2.0
            native_seed = np.zeros(np.shape(volume[z]), dtype=bool)
            for points, source_frame, source_thickness in source_sections:
                source_half = 0.5 * (
                    abs(float(normal @ source_frame.basis_lps[:, 0]))
                    + abs(float(normal @ source_frame.basis_lps[:, 1]))
                    + abs(float(normal @ source_frame.normal())) * source_thickness
                )
                distance = np.abs(points @ normal - offset)
                held = distance <= (target_half + source_half)
                if not held.any():
                    continue
                source_extent[z] = True
                projected = frame.to_native(points[held])
                shape = native_seed.shape
                in_picture = (
                    np.isfinite(projected).all(axis=1)
                    & (projected[:, 0] >= -0.5)
                    & (projected[:, 0] < shape[0] - 0.5)
                    & (projected[:, 1] >= -0.5)
                    & (projected[:, 1] < shape[1] - 0.5)
                )
                if in_picture.any():
                    pixels = np.floor(projected[in_picture] + 0.5).astype(np.int64)
                    native_seed[pixels[:, 0], pixels[:, 1]] = True
                    source_points_count += int(in_picture.sum())
            if not source_extent[z]:
                continue
            plane = np.asarray(volume[z], dtype=np.float64)
            reading = once(
                "coarse_axial_blocks",
                (uid, z, LIGAMENT_SMOOTH_MM),
                lambda plane=plane, spacing_rc=frame.spacing_rc: block_medians(
                    plane,
                    margin(plane) | ~np.isfinite(plane),
                    spacing_rc,
                    float(LIGAMENT_SMOOTH_MM),
                ),
            )
            coarse = once(
                "coarse_axial_depth",
                (uid, z, marrow_is_dark),
                lambda reading=reading, dark=marrow_is_dark: handed_on(
                    coarse_depth(reading.median, dark)
                ),
            )
            result = coarse_section(
                coarse,
                block_holds(native_seed, reading),
                float(np.prod(reading.block_mm)),
            )
            read_slices.append(z)
            read_frames.append(frame)
            read_thicknesses.append(target_thickness)
            readings.append(reading)
            depths.append(coarse)
            sections.append(result)
            status_counts[result.status] = status_counts.get(result.status, 0) + 1
            if result.body is not None:
                areas[z] = result.area_mm2
        packed = pack_sections(read_slices, readings, depths, {"patella": sections})
        own.arrays.update(
            {f"a4_patella_coarse_{name}": value for name, value in packed.items()}
        )
        own.arrays["a4_patella_coarse_source_extent"] = source_extent
        own.arrays["a4_patella_coarse_origin_lps"] = np.asarray(
            [frame.origin_lps for frame in read_frames], dtype=np.float64
        )
        own.arrays["a4_patella_coarse_normal_lps"] = np.asarray(
            [frame.normal() for frame in read_frames], dtype=np.float64
        )
        own.arrays["a4_patella_coarse_thickness_mm"] = np.asarray(
            read_thicknesses,
            dtype=np.float64,
        )
        own.record["patella_key_planes"] = {
            "orientation": orientation,
            "source": "native_resolved_sagittal_patella_sections",
            "source_sections": len(source_sections),
            "source_points_projected": source_points_count,
            "marrow": "dark_enclosed_by_brighter"
            if marrow_is_dark
            else "bright_enclosed_by_darker",
            "block_mm": float(LIGAMENT_SMOOTH_MM),
            "slices_read": read_slices,
            "source_extent_slices": [int(z) for z in np.flatnonzero(source_extent)],
            "statuses": status_counts,
            "key_slices": [],
            "rule": "largest whole enclosed 2 mm section holding projected native patella location seeds; ties retained",
            "seed_note": "projected source pixels are location seeds only; the coarse body is a reading, not a native patella boundary",
        }
        artifact = str(artifact_of(study_uid, own.record))
        said: list[Observation] = []
        missing: list[Unresolved] = []
        keys = coarse_key_slices(areas)
        row_for_slice = {z: row for row, z in enumerate(read_slices)}
        for row, (z, result) in enumerate(zip(read_slices, sections, strict=True)):
            support = (
                "a4_patella_coarse_patella_body"
                if result.body is not None
                else "a4_patella_coarse_patella_seeds"
            )
            said.append(
                observe(
                    "patella",
                    "native",
                    "reading",
                    own,
                    (z,),
                    result.status,
                    None,
                    0.0,
                    support,
                    "coarse enclosed section and projected location seed on this slice; reading only, not the patella boundary",
                    artifact,
                    row,
                )
            )
        for z in keys:
            row = row_for_slice[z]
            own.record["patella_key_planes"]["key_slices"].append(z)
            mapping.smap.offer(
                "patella",
                map_plane(
                    own,
                    "patella",
                    z,
                    "largest whole enclosed 2 mm section holding native sagittal patella location seeds",
                    "coarse_section",
                ),
                float(areas[z]),
                f"patella_scout:{uid}",
            )
        if not keys:
            reason = (
                "no_native_sagittal_patella_sections"
                if not source_sections
                else "no_competent_coarse_section; "
                + ",".join(
                    f"{name}={count}" for name, count in sorted(status_counts.items())
                )
            )
            missing.append(
                Unresolved("patella", "native", uid, tuple(own.record["view"]), reason)
            )
            mapping.smap.offer(
                "patella",
                rel.unresolved_plane(
                    "patella",
                    orientation,
                    rel.REFUSED,
                    reason=reason,
                    provenance="coarse_section",
                ),
                None,
                f"patella_scout:{uid}",
            )
        keep_observations(own, said, missing)
        reads("patella_key_planes", ("coarse_sections", "key_slices"), "study_map")
        handed("patella_key_planes", ("coarse_sections", "key_slices"))


# -- THE JOINT: the sided menisci, the articular cartilage, the cruciates and the collaterals -----
# The joint is what lies between the femur and the tibia (its existing definition), asked of every
# slice from the bones' carried places; four separate quantities of its corridor
# (`knee.collapse.joint`) each point at the planes where one property is worth a native reading.
SIDED_MENISCI = ("medial_meniscus", "lateral_meniscus", "meniscus")
JOINT_PARTS = (
    *SIDED_MENISCI,
    "femoral_cartilage",
    "tibial_cartilage",
    "mcl",
    "pcl",
    "acl",
)
# Each part's existing rule, by the key of its code in a plane's codes.
JOINT_RULE = {
    "medial_meniscus": "meniscus",
    "lateral_meniscus": "meniscus",
    "meniscus": "meniscus",
    "femoral_cartilage": "cartilage",
    "tibial_cartilage": "cartilage",
    "mcl": "mcl",
    "pcl": "pcl",
    "acl": "acl",
}
JOINT_NOT_READ = FIBULA_POINTER_STATUS["not_read"]
JOINT_NONE = FIBULA_POINTER_STATUS["none"]
JOINT_BODY = FIBULA_POINTER_STATUS["body"]
JOINT_UNREADABLE = FIBULA_POINTER_STATUS["unreadable"]
HORNS = "horn_candidates"
CARTILAGE_CANDIDATES = "cartilage_candidates"


@dataclass(frozen=True)
class JointProfile:
    """The joint's cheap profile through depth, one entry per slice of the series in stack order, one
    profile per quantity (`knee.collapse.joint.QUANTITIES`, never combined): the pointer's `status`
    (`FIBULA_POINTER_STATUS`, the same words; "none" is a measured absence, "unreadable" is unknown)
    and the `area_mm2` of the 2 mm blocks of the corridor that read the quantity (0.0 measured absent,
    NaN not read or unreadable; with `unseen_blocks` it is a lower bound); the blocks of the corridor
    seen and not (`seen_blocks`, `unseen_blocks`, -1 where no finer reading was made), the corridor's
    `corridor_px` (its reach, pixels) and its tiles, and for each quantity the tiles that could hold
    its level; the native window of the finer reading, its block in millimetres and pixels, the finer
    readings themselves (`fine`; its `body` is the blocks that hold a place of the corridor's reach)
    and the level each quantity was read at (None: no usable anchor)."""

    names: tuple[str, ...]
    status: dict[str, np.ndarray]
    area_mm2: dict[str, np.ndarray]
    seen_blocks: np.ndarray
    unseen_blocks: np.ndarray
    corridor_px: np.ndarray
    corridor: np.ndarray
    could: dict[str, np.ndarray]
    window_rc: np.ndarray
    cell_mm: np.ndarray
    block_px: np.ndarray
    fine: tuple[FineReading, ...]
    level: dict[str, tuple[float, float] | None]


def joint_profile(
    series: Series,
    stack: SquintStack,
    femur_places: np.ndarray,
    tibia_places: np.ndarray,
    level: dict[str, tuple[float, float] | None],
    names: tuple[str, ...],
    own_reach: Callable[[int, PlaneFrame, tuple[int, int]], np.ndarray] | None = None,
    name: str = "joint",
    bones_unestablished: np.ndarray | None = None,
    visit: np.ndarray | None = None,
) -> JointProfile:
    """The joint's four-quantity profile through the series' whole depth, without the lens.

    A family whose compartment is a relation to parts already located (the recesses, in front of the
    femur and behind the patella) gives `own_reach` (slice, frame, shape -> the pixels where it can lie
    there), read in place of the joint's own corridor; every other step is the same, under the ledger
    name `name`. `bones_unestablished` (one flag per slice) marks the slices where the bones' family
    did not natively identify both bones (`bones_identified_at`): the joint is what lies between
    them, so no corridor is read there and no lens is asked for it (counted
    `joint.slices_without_both_bones_identified`; nothing is said of such a slice: it is unknown,
    not a joint-free one). `visit` (one flag per slice, None for the whole depth, as the recess
    family asks) names the slices read at all: any other keeps `JOINT_NOT_READ` and NaN, unknown and
    never empty, and is not counted among the slices without the bones (`joint.slices_not_visited`).

    On each slice the corridor is where the joint can lie there (`joint_reach`: the carried femur's
    and tibia's places projected onto the slice, `bone_footprint`, the places between them along the
    leg and their reach); no place of it on the slice, nothing is said (not read). The squint's tile
    extrema over every tile a 2 mm block with a place of the corridor can touch (`could_hold_level_in_reach`,
    as the bones' and the fibula's profiles ask) say, per quantity, where its level cannot be: none can
    and no unseen tile is in reach, a measured absence (`none`); none can but one is, unreadable. Where
    some can, ONE finer reading of the window of the tiles that could (`block_medians` at
    `LIGAMENT_SMOOTH_MM`) gives every wanted quantity its area over the blocks that hold a place of
    the corridor (`block_support`): a positive area is `body` (a lower bound where blocks were
    unseen), zero with every block seen is `none`, zero with an unseen block is unreadable. A level
    with no usable anchor (`level` None) leaves every slice of the corridor unreadable for that
    quantity and excludes nothing. Counts are on the ledger (`joint.cheap_readings`,
    `joint.tile_exclusions`)."""
    reads("squint_stack", ("minimum", "maximum", "bounds_rc"), name)
    depth = int(stack.median.shape[0])
    tiles = stack.median.shape[1:]
    bounds = stack.bounds_rc
    shape = (int(bounds[..., 1].max()), int(bounds[..., 3].max()))
    status = {q: np.full(depth, JOINT_NOT_READ, dtype=np.int8) for q in names}
    area = {q: np.full(depth, np.nan) for q in names}
    seen_blocks = np.full(depth, -1, dtype=np.int32)
    unseen_blocks = np.full(depth, -1, dtype=np.int32)
    corridor_px = np.zeros(depth, dtype=np.int32)
    corridor = np.zeros((depth, *tiles), dtype=bool)
    could = {q: np.zeros((depth, *tiles), dtype=bool) for q in names}
    window_rc = np.full((depth, 4), -1, dtype=np.int32)
    cell_mm = np.full((depth, 2), np.nan)
    cell_px = np.full((depth, 2), -1, dtype=np.int32)
    fine: list[FineReading] = []
    reach_of: dict[tuple[int, int], Any] = {}
    femur_key, tibia_key = digest(femur_places), digest(tibia_places)
    finely = excluded = lacking = skipped = 0
    for z in range(depth):
        if visit is not None and not bool(visit[z]):
            skipped += 1
            continue
        if bones_unestablished is not None and bool(bones_unestablished[z]):
            lacking += 1
            continue
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            for q in names:
                status[q][z] = JOINT_UNREADABLE
            continue
        if own_reach is not None:
            reach = own_reach(z, frame, shape)
        else:
            _, reach = joint_reach(
                bone_footprint(series, z, frame, shape, femur_places, femur_key),
                bone_footprint(series, z, frame, shape, tibia_places, tibia_key),
                frame.basis_lps,
                np.asarray(frame.spacing_rc),
            )
        if not reach.any():
            continue  # the bones' places leave no joint on this slice: nothing is said
        corridor_px[z] = int(np.count_nonzero(reach))
        near = tiles_touched(reach, bounds)
        corridor[z] = near
        block = block_pixels(frame.spacing_rc, LIGAMENT_SMOOTH_MM)
        if block not in reach_of:
            reach_of[block] = footprint_reach(bounds, block)
        lows, highs = stack.minimum[z], stack.maximum[z]
        wanted: dict[str, tuple[float, float]] = {}
        for q in names:
            at = level[q]
            if at is None:
                status[q][z] = JOINT_UNREADABLE
                continue
            possible, blind = could_hold_level_in_reach(
                lows, highs, at[0], at[1], reach_of[block]
            )
            could[q][z] = near & possible
            if could[q][z].any():
                wanted[q] = at
            elif (near & blind).any():
                status[q][z] = JOINT_UNREADABLE
            else:
                status[q][z], area[q][z] = JOINT_NONE, 0.0
                excluded += 1
        if not wanted:
            continue
        held_tiles = np.zeros(tiles, dtype=bool)
        for q in wanted:
            held_tiles |= could[q][z]
        held = bounds[held_tiles]
        plane, unseen = seen_native(series, z, name)
        rows, cols = plane.shape
        # the far edge is one block wider, so a block with a place in the last tile is not cut
        window = (
            int(held[:, 0].min()),
            min(rows, int(held[:, 1].max()) + block[0] - 1),
            int(held[:, 2].min()),
            min(cols, int(held[:, 3].max()) + block[1] - 1),
        )
        reading = block_medians(
            plane, unseen, frame.spacing_rc, LIGAMENT_SMOOTH_MM, window
        )
        blocks = block_holds(reach, reading)
        got, seen_n, unseen_n = block_support(
            reading.median, blocks, reading.block_mm, wanted
        )
        finely += 1
        seen_blocks[z], unseen_blocks[z] = seen_n, unseen_n
        for q in wanted:
            if got[q] > 0:
                status[q][z], area[q][z] = JOINT_BODY, got[q]
            elif unseen_n:
                status[q][z] = JOINT_UNREADABLE  # an unseen block: unknown, not absent
            else:
                status[q][z], area[q][z] = JOINT_NONE, 0.0
        window_rc[z], cell_mm[z], cell_px[z] = (
            window,
            reading.block_mm,
            reading.block_px,
        )
        fine.append(
            FineReading(
                z,
                reading.window_rc,
                reading.block_px,
                reading.block_mm,
                reading.median,
                blocks,
                blocks,
            )
        )
    ledger.record(f"{name}.cheap_readings", planes=finely)
    ledger.record(f"{name}.tile_exclusions", planes=excluded)
    ledger.record(f"{name}.slices_without_both_bones_identified", planes=lacking)
    if visit is not None:
        ledger.record(f"{name}.slices_not_visited", planes=skipped)
    handed(f"{name}_profile", ("status", "area_mm2"))
    # kept, not read: no stage after the profile reads the blocks or the corridor it drew
    handed(f"{name}_profile", ("fine",))
    return JointProfile(
        names,
        status,
        area,
        seen_blocks,
        unseen_blocks,
        corridor_px,
        corridor,
        could,
        window_rc,
        cell_mm,
        cell_px,
        tuple(fine),
        level,
    )


def merge_joint_profiles(
    first: JointProfile, second: JointProfile, visited: np.ndarray
) -> JointProfile:
    """Two profiles of the same series, the second read on the slices `visited` and the first on
    the others: each slice's entries are those of the profile that read it, so the two together are
    the joint's profile of every slice either read (`joint_profile` with no `visit`)."""

    def take(a: np.ndarray, b: np.ndarray) -> np.ndarray:
        return np.where(visited.reshape(-1, *([1] * (a.ndim - 1))), b, a)

    return JointProfile(
        first.names,
        {q: take(first.status[q], second.status[q]) for q in first.names},
        {q: take(first.area_mm2[q], second.area_mm2[q]) for q in first.names},
        take(first.seen_blocks, second.seen_blocks),
        take(first.unseen_blocks, second.unseen_blocks),
        take(first.corridor_px, second.corridor_px),
        take(first.corridor, second.corridor),
        {q: take(first.could[q], second.could[q]) for q in first.names},
        take(first.window_rc, second.window_rc),
        take(first.cell_mm, second.cell_mm),
        take(first.block_px, second.block_px),
        tuple(sorted(first.fine + second.fine, key=lambda f: f.index)),
        first.level,
    )


def joint_questions(
    coronal: bool, fat_suppressed: bool, sided: tuple[str, ...]
) -> dict[str, str]:
    """The questions the joint family asks of a series, each with the quantity that points at it
    (never combined), by what the existing rules' gates admit on this view: on a coronal plane
    each SIDED meniscus's body (a compartment is its own question: a plane naming one side leaves
    the other open), the MCL (decided where the medial meniscus it hangs from is named) and, with fat
    suppression, the femoral and the tibial cartilage; on a sagittal plane each compartment's horn
    candidates, the PCL without fat suppression, and with it the cartilage candidates and the ACL. A
    quantity no question names on this view (the ligament and the fluid pointers on a coronal plane,
    whose cruciate rules the plane's gate refuses) keeps its pointers and is asked nothing."""
    asks: dict[str, str] = {}
    if coronal:
        for name in sided:
            asks[f"body:{name}"] = DARK
        if "medial_meniscus" in sided:
            asks["mcl"] = DARK
        if fat_suppressed:
            asks["cartilage:femoral_cartilage"] = BRIGHT
            asks["cartilage:tibial_cartilage"] = BRIGHT
        return asks
    for name in sided:
        asks[f"horns:{name}"] = DARK
    if fat_suppressed:
        asks["cartilage_reading"] = BRIGHT
        asks["acl"] = FLUID
    else:
        asks["pcl"] = LIGAMENT
    return asks


def joint_answers(
    plane: "JointPlane", coronal: bool, middle: np.ndarray | None = None
) -> set[str]:
    """The questions one plane read answers, by what the existing rules named on it (the rule's own
    decision: a candidate the gate refuses is an answer only to its own candidate question). The
    series' middle slice (`middle`, its `a1_objects`; the bootstrap's own naming, not read again)
    answers by what that naming holds. A plane that was not read answers nothing."""
    got: set[str] = set()
    codes = plane.codes
    objects = middle if plane.middle else plane.objects
    if objects is None or (not plane.middle and plane.code != "read"):
        return got

    def has(name: str) -> bool:
        return bool(np.any(np.asarray(objects) == OBJECT_CODES[name]))

    if coronal:
        for name in SIDED_MENISCI:
            if has(name):
                got.add(f"body:{name}")
        if has("medial_meniscus"):
            got.add("mcl")
        for name in ("femoral_cartilage", "tibial_cartilage"):
            if has(name):
                got.add(f"cartilage:{name}")
        return got
    if has("pcl"):
        got.add("pcl")
    if plane.middle:
        return got
    if codes.get("horns") == HORNS:
        side = (
            "meniscus"
            if plane.compartment in (None, "meniscus")
            else f"{plane.compartment}_meniscus"
        )
        got.add(f"horns:{side}")
    if codes.get("cartilage_reading") == CARTILAGE_CANDIDATES:
        got.add("cartilage_reading")
    if codes.get("pcl") == "identified":
        got.add("pcl")
    if codes.get("acl") == "identified":
        got.add("acl")
    return got


def joint_neighbourhood(
    own: Measured,
    reference: Reference | str,
    questioned: tuple[str, ...],
    fat_suppressed: bool,
    mapping: MapContext | None = None,
) -> tuple[np.ndarray | None, dict]:
    """Where along this series' stack the joint family is looked for first, relative to the
    study's reference (`select_reference`): for every quantity a question names, the slices within
    the cohort's measured range of the reference's place along THIS series' normal
    (`JOINT_FROM_REFERENCE_MM`, keyed by quantity, plane, fat suppression, kind of reference and the
    physical direction `offset_direction` names: toward the back for a coronal series, medially or
    toward the left for a sagittal one), by the scanner's millimetres and never slice indices;
    the middle slice is always among them. None where anything is unknown or no range is
    measured and supported for a question (no reference, an unusable axis, a slice with no place,
    a kind of reference no cohort range exists for): the whole established depth is then read, as
    before, and the dict says which question had none. With `mapping`, the anatomical guides replace
    that historical window: admitted question slices are unioned, and a question without a guide
    requires the full depth. Every number or placement is retained in the returned detail."""
    if mapping is not None:
        assigned = own.record["assignments"]
        sided = (
            SIDED_MENISCI[:2] if assigned["knee"] in ("R", "L") else SIDED_MENISCI[2:]
        )
        asks = joint_questions(bool(own.assignment.in_plane[0]), fat_suppressed, sided)
        return joint_map_neighbourhood(own, mapping, asks)
    if isinstance(reference, str):
        return None, {"code": f"no_reference_{reference}"}
    reads(
        "reference",
        ("support_lps", "thickness_mm", "series_uid", "bone", "slices"),
        "joint",
    )
    series = own.series
    index = own.record["slice_index"]
    origins, _, _, sound = series_depth(series, own.frame, index)
    if not sound:
        return None, {"code": "slice_places_unknown_the_geometry_is_unsound"}
    unit = np.asarray(own.frame.normal(), dtype=np.float64)
    unit = unit / np.linalg.norm(unit)
    position = reference_position(reference.support_lps, unit, reference.thickness_mm)
    if position is None:
        return None, {"code": "reference_position_unknown"}
    mean, low, high, kind = position
    said: dict[str, Any] = {
        "reference_series_uid": reference.series_uid,
        "reference_bone": reference.bone,
        "reference_slices": list(reference.slices),
        "reference_kind": kind,
        "reference_mm": mean,
        "reference_support_mm": [low, high],
    }
    plane = str(own.record["view"][0])
    direction = offset_direction(unit, plane, str(own.record["assignments"]["knee"]))
    if direction is None:
        return None, {**said, "code": "no_measured_offsets_on_this_axis"}
    window = np.zeros(len(origins), dtype=bool)
    ranges: dict[str, list[float]] = {}
    sequence = "1" if fat_suppressed else "0"
    for q in questioned:
        found = JOINT_FROM_REFERENCE_MM.get((q, plane, sequence, kind, direction[1]))
        if found is None:
            return None, {
                **said,
                "code": "no_supported_cohort_range_for_a_question",
                "quantity_without_range": q,
                "convention": direction[1],
            }
        inside = expected_slices(origins @ unit, mean, direction[0], found, index)
        if inside is None:
            return None, {**said, "code": "slice_places_unknown"}
        window |= inside
        ranges[q] = list(found)
    said.update(
        code="window",
        convention=direction[1],
        offset_sign=direction[0],
        expected_offset_mm=ranges,
        slices_in=int(window.sum()),
    )
    return window, said


def joint_map_neighbourhood(
    own: Measured, mapping: MapContext, asks: dict[str, str]
) -> tuple[np.ndarray | None, dict]:
    """Union the anatomical map's slice pointers for the questions this view admits.

    A question without any usable target guide requires the full depth. The returned detail keeps
    every target guide and its anchor placements; `None` means an explicit full-depth look."""
    depth = len(own.series.volume) if own.series.volume is not None else 0
    window = np.zeros(depth, dtype=bool)
    by_question: dict[str, dict] = {}
    unguided: dict[str, list[str]] = {}
    for question in asks:
        targets = JOINT_GUIDE_TARGETS.get(question, ())
        entries = []
        for target in targets:
            guide = mapping.guide(target, own)
            entries.append(
                {
                    "object": target,
                    "status": guide.status,
                    "slices": list(guide.slices),
                    "rcs": [
                        {"slice": int(z), "rc": [float(rc[0]), float(rc[1])]}
                        for z, rc in guide.rcs
                    ],
                    "placements": list(guide.placements),
                    "anchors": list(guide.anchors),
                    "half_px": None if guide.half_px is None else list(guide.half_px),
                }
            )
            if guide.status == "guided" and guide.slices:
                for z in guide.slices:
                    if 0 <= int(z) < depth:
                        window[int(z)] = True
        usable = [
            entry
            for entry in entries
            if entry["status"] == "guided" and entry["slices"]
        ]
        if usable:
            by_question[question] = {"targets": entries, "guided": True}
        else:
            reasons = [str(entry["status"]) for entry in entries]
            unguided[question] = reasons or ["no_map_object_for_question"]
            by_question[question] = {
                "targets": entries,
                "guided": False,
                "reason": unguided[question],
            }
    if unguided:
        return None, {
            "code": "full_depth_required_for_unguided_questions",
            "map_questions": by_question,
            "unguided_questions": unguided,
        }
    index = int(own.record["slice_index"])
    if 0 <= index < depth:
        window[index] = True  # the middle slice remains the bootstrap
    return window, {
        "code": "anatomical_map_guides",
        "map_questions": by_question,
        "slices_in": int(window.sum()),
    }


JOINT_GUIDE_TARGETS = {
    **{f"body:{name}": (name,) for name in SIDED_MENISCI},
    **{f"horns:{name}": (name,) for name in SIDED_MENISCI},
    "mcl": ("mcl",),
    "pcl": ("pcl",),
    "acl": ("acl",),
    "cartilage:femoral_cartilage": ("femoral_cartilage",),
    "cartilage:tibial_cartilage": ("tibial_cartilage",),
    "cartilage_reading": ("femoral_cartilage", "tibial_cartilage"),
}


def joint_guide_spatial_hits(
    profile: JointProfile,
    asks: dict[str, str],
    guidance: dict,
    own: Measured | None = None,
) -> dict[str, dict[int, bool]]:
    """Whether existing fine quantity support overlaps each expected in-plane guide box."""
    fine_at = {reading.index: reading for reading in profile.fine}
    hits: dict[str, dict[int, bool]] = {}
    for question, quantity in asks.items():
        question_guides = (
            guidance.get("map_questions", {}).get(question, {}).get("targets", [])
        )
        placements = []
        half_boxes = []
        for entry in question_guides:
            if entry.get("status") != "guided":
                continue
            half = entry.get("half_px") or (0.0, 0.0)
            for placement in entry.get("placements", []):
                if (
                    placement.get("status") == "ok"
                    and placement.get("slice") is not None
                    and placement.get("rc") is not None
                ):
                    candidates = [
                        (
                            int(placement["slice"]),
                            tuple(float(v) for v in placement["rc"]),
                        )
                    ]
                    if own is not None and placement.get("point_lps") is not None:
                        candidates = []
                        for z in entry.get("slices", []):
                            if int(z) not in fine_at:
                                continue
                            frame = plane_frame(own.series, int(z))
                            if isinstance(frame, str):
                                continue
                            rc = frame.to_native(
                                np.asarray([placement["point_lps"]], dtype=float)
                            )[0]
                            if np.isfinite(rc).all():
                                candidates.append(
                                    (int(z), (float(rc[0]), float(rc[1])))
                                )
                    placements.extend(candidates)
                    half_boxes.extend(
                        [(float(half[0]), float(half[1]))] * len(candidates)
                    )
        by_slice: dict[int, bool] = {}
        level = profile.level.get(quantity)
        for (slice_index, center), half in zip(placements, half_boxes, strict=True):
            reading = fine_at.get(slice_index)
            if reading is None or level is None:
                by_slice[slice_index] = False
                continue
            r0, _r1, c0, _c1 = reading.window_rc
            br, bc = reading.block_px
            valid = (
                reading.body
                & np.isfinite(reading.median)
                & (reading.median >= level[0])
                & (reading.median <= level[1])
            )
            row_grid, col_grid = np.indices(valid.shape)
            row_start = r0 + row_grid * br
            col_start = c0 + col_grid * bc
            row_half = half[0] + 0.5
            col_half = half[1] + 0.5
            overlaps = (
                (row_start < center[0] + row_half)
                & (row_start + br > center[0] - row_half)
                & (col_start < center[1] + col_half)
                & (col_start + bc > center[1] - col_half)
            )
            by_slice[slice_index] = by_slice.get(slice_index, False) or bool(
                np.any(valid & overlaps)
            )
        hits[question] = by_slice
    return hits


def order_joint_runs(
    order: list[tuple[float, str, list[int]]],
    asks: dict[str, str],
    spatial_hits: dict[str, dict[int, bool]],
) -> list[tuple[float, str, list[int]]]:
    """Use each question's existing support order, promoting only its map-supported runs."""
    result = list(order)
    by_quantity: dict[str, list[int]] = {}
    for position, (_, quantity, _) in enumerate(result):
        by_quantity.setdefault(quantity, []).append(position)
    for quantity, positions in by_quantity.items():
        questions = [q for q, at_quantity in asks.items() if at_quantity == quantity]

        def guided_first(
            row: tuple[float, str, list[int]], questions: list[str] = questions
        ) -> bool:
            _, _q, slices = row
            return any(
                spatial_hits.get(question, {}).get(z, False)
                for question in questions
                for z in slices
            )

        selected = [result[position] for position in positions]
        selected.sort(key=lambda row: (not guided_first(row), -row[0]))
        for position, row in zip(positions, selected, strict=True):
            result[position] = row
    return result


def joint_run_groups(
    order: list[tuple[float, str, list[int]]],
) -> list[list[tuple[float, str, list[int]]]]:
    """Consume every equal-support run together, including ties made noncontiguous by map order."""
    pending = list(range(len(order)))
    groups = []
    while pending:
        first = pending[0]
        group_indices = [i for i in pending if order[i][0] == order[first][0]]
        groups.append([order[i] for i in group_indices])
        removed = set(group_indices)
        pending = [i for i in pending if i not in removed]
    return groups


@dataclass(frozen=True)
class JointPlane:
    """One plane the profile pointed to, as the existing rules read it: its `slice`, whether it is the
    series' `middle` slice (the bootstrap's own naming, not read again), `code` ("read", or
    `UNREADABLE_GEOMETRY`), the `codes` each existing rule gave there (`meniscus`, `meniscus_side`,
    `cartilage`, `pcl`, `mcl`, `acl`, and the readings `horns`, `cartilage_reading` where the
    existing rule's gate refuses the plane), what the carried places named of the femur and the tibia
    (`femur`, `tibia`: `knee.collapse.bones` outcomes), the lens's `labels` and `available`, the
    plane's naming `objects` (int8, `OBJECT_CODES`), the `reading` stack of candidates the existing
    rules do not license there (the horns, the cartilage on a sagittal plane) and `horn_end` (1 the
    piece at the front of the joint, 2 at the back), the sagittal plane's `compartment` and its place
    toward the patient's left of the notch (`toward_left_mm`), the femur's marrow `light` and the
    quantities that pointed here (`asked`)."""

    slice: int
    middle: bool
    code: str
    codes: dict[str, str]
    femur: str
    tibia: str
    labels: np.ndarray | None
    available: np.ndarray | None
    objects: np.ndarray | None
    reading: np.ndarray | None
    horn_end: np.ndarray | None
    compartment: str | None
    toward_left_mm: float | None
    light: float | None
    asked: tuple[str, ...]


def joint_plane(
    own: Measured,
    z: int,
    femur_lps: np.ndarray,
    tibia_lps: np.ndarray,
    keys: tuple[str, str],
    asked: tuple[str, ...],
    toward_left_mm: float | None,
) -> JointPlane:
    """The existing rules of the sided menisci, the cartilage, the PCL, the ACL and the MCL on ONE
    pointed plane: the lens (`lens_of`, once per slice, so a plane the bones or another family read is
    handed on) and its field (`field_of`); the femur and the tibia named by the carried places
    (`name_territory`, the established `carried_bone`), the joint between them as `assign_plane`
    makes it; then each rule as `assign_plane` orders them, from the same operations: the menisci (the
    thick low signal touching the joint, the piece nearest each end, sided by the header), the
    cartilage (fat suppression), the PCL (no fat suppression), the MCL, and the ACL as `acl_slice`
    reads it, from the bones carried to the plane. A rule's own gate is kept as its code: on a sagittal
    plane the menisci and the cartilage are refused (side to side runs through the plane) and what the
    same operation finds there (`horn_pieces`, `cartilage_on`) is only a reading, in `reading`, never
    a name. Nothing here is a new definition, and the rest of `assign_plane` is not run."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return JointPlane(
            z,
            False,
            UNREADABLE_GEOMETRY,
            {},
            "",
            "",
            None,
            None,
            None,
            None,
            None,
            None,
            toward_left_mm,
            None,
            asked,
        )
    plane = np.asarray(series.volume[z])
    _, lens, _ = lens_of(
        series, z, plane, frame, float(record["background_split"]), "joint"
    )
    field = field_of(series, z, plane, frame, lens)
    reads("interiors", ("labels", "available", "dark"), "joint")
    reads("field", ("objects", "peaks", "leg"), "joint")
    shape = plane.shape
    labels, available = lens.labels, np.asarray(lens.available, dtype=bool)
    femur_foot = bone_footprint(series, z, frame, shape, femur_lps, keys[0])
    tibia_foot = bone_footprint(series, z, frame, shape, tibia_lps, keys[1])
    femur = name_territory(labels, available, femur_foot, tibia_foot)
    tibia = name_territory(labels, available, tibia_foot, femur_foot)
    none = np.zeros(shape, dtype=bool)
    femur_places = femur.region if femur.code == IDENTIFIED else none
    tibia_places = tibia.region if tibia.code == IDENTIFIED else none
    objects = field.objects.copy()
    objects[femur_places] = OBJECT_CODES["femur"]
    objects[tibia_places] = OBJECT_CODES["tibia"]
    basis = frame.basis_lps
    spacing = np.linalg.norm(basis, axis=0)
    sides_in_plane, front_in_plane, _ = field.in_plane
    fat_suppressed = int(series.row.fat_suppression) == 1  # the tag is stored as text
    knee = str(record["assignments"]["knee"])
    outside = margin_of(uid, z, plane)
    measures = measures_of(uid, z, plane, frame)
    bones_named = bool(femur_places.any() and tibia_places.any())
    if bones_named:
        objects[
            between_along_the_leg(femur_places, tibia_places, basis)
            & (objects == 0)
            & ~outside
        ] = OBJECT_CODES["joint"]
    joint = objects == OBJECT_CODES["joint"]
    codes: dict[str, str] = {}
    # the menisci, as `assign_plane` reads them
    menisci = 0
    if sides_in_plane and joint.any():
        pieces, _ = ndi.label(
            thick_parts(lens.dark & ~outside, spacing, MENISCUS_THICKNESS_MM)
        )
        touching = np.unique(
            pieces[ndi.binary_dilation(joint, structure=FOUR_NEIGHBOURS) & (pieces > 0)]
        )
        pieces, count = ndi.label(np.isin(pieces, touching) & (pieces > 0))
        leftward = measures.along(0)
        for piece, toward_left in end_pieces(
            pieces, count, leftward, float(leftward[joint].mean())
        ):
            side = meniscus_side(knee, toward_left)
            name = "meniscus" if side == "meniscus" else f"{side}_meniscus"
            objects[pieces == piece] = OBJECT_CODES[name]
            menisci += 1
    codes["meniscus"] = meniscus_code(sides_in_plane, joint.any(), menisci)
    codes["meniscus_side"] = side_code(knee, menisci)
    # the cartilage: a fat-suppressed plane side to side runs in
    femoral = tibial = none
    if sides_in_plane and fat_suppressed and joint.any():
        femoral, tibial = cartilage_on(plane, objects, spacing, measures)
    codes["cartilage"] = cartilage_code(
        sides_in_plane,
        fat_suppressed,
        bool(joint.any()),
        bool(femoral.any() or tibial.any()),
    )
    objects[femoral] = OBJECT_CODES["femoral_cartilage"]
    objects[tibial] = OBJECT_CODES["tibial_cartilage"]
    # the PCL: a sagittal plane without fat suppression, the thick dark band joining the bones
    pcl = none
    if front_in_plane and not fat_suppressed and bones_named:
        pcl = band_joining(
            dark_bands(plane, objects, spacing, outside, measures),
            objects == OBJECT_CODES["femur"],
            objects == OBJECT_CODES["tibia"],
            spacing,
            measures,
        ) & np.isin(objects, (0, OBJECT_CODES["joint"]))
    # a ligament inside the joint is enclosed by the picture: a band that runs to the picture's own
    # edge is the dark soft tissue behind the knee, which reaches the bones' posterior corners
    edge = np.zeros(shape, dtype=bool)
    edge[0], edge[-1], edge[:, 0], edge[:, -1] = True, True, True, True
    runs_off = bool(pcl.any() and (pcl & edge).any())
    if runs_off:
        pcl = none
    codes["pcl"] = (
        "abstain_band_runs_to_the_picture_edge"
        if runs_off
        else pcl_code(front_in_plane, fat_suppressed, bones_named, bool(pcl.any()))
    )
    objects[pcl] = OBJECT_CODES["pcl"]
    # the MCL: the low signal left on the medial meniscus's side that joins the bones
    medial = bool((objects == OBJECT_CODES["medial_meniscus"]).any())
    mcl = none
    if sides_in_plane and medial:
        mcl = ligament_on_the_inner_side(lens.dark, objects, basis, outside, measures)
    codes["mcl"] = mcl_code(sides_in_plane, medial, bool(mcl.any()))
    objects[mcl] = OBJECT_CODES["mcl"]
    # the ACL, as `acl_slice` reads it, from the bones carried to this plane by place
    acl = none
    if front_in_plane and fat_suppressed and bones_named:
        acl = acl_on_slice(
            labels, field.peaks, femur_places, tibia_places, basis, outside
        )
    # an ACL lies BETWEEN the bones: a territory that holds the carried bones' own places is a lens
    # territory leaking over a bone (seen on the lateral planes), kept unnamed
    leaks = bool(acl.any() and (acl & (femur_places | tibia_places)).any())
    if leaks:
        acl = none
    codes["acl"] = (
        "abstain_region_holds_the_bones_places"
        if leaks
        else acl_code(
            front_in_plane, knee, bones_named, fat_suppressed, bool(acl.any())
        )
    )
    objects[acl & np.isin(objects, (0, OBJECT_CODES["joint"]))] = OBJECT_CODES["acl"]
    # what the same operations find where the existing rule's gate refuses the plane: readings only
    candidates = np.zeros(shape, dtype=np.int8)
    ends = np.zeros(shape, dtype=np.int8)
    side = compartment(knee, np.nan if toward_left_mm is None else toward_left_mm)
    name = "meniscus" if side == "meniscus" else f"{side}_meniscus"
    if front_in_plane and not sides_in_plane:
        if joint.any():
            kept, ends = horn_pieces(
                lens.dark, joint, outside, spacing, measures.along(1)
            )
            candidates[kept] = OBJECT_CODES[name]
            codes["horns"] = (
                HORNS if kept.any() else "abstain_no_thick_low_signal_in_the_joint"
            )
        else:
            codes["horns"] = "abstain_no_joint"
        if fat_suppressed and joint.any():
            femoral, tibial = cartilage_on(plane, objects, spacing, measures)
            candidates[femoral] = OBJECT_CODES["femoral_cartilage"]
            candidates[tibial] = OBJECT_CODES["tibial_cartilage"]
            codes["cartilage_reading"] = (
                CARTILAGE_CANDIDATES
                if femoral.any() or tibial.any()
                else "abstain_nothing_bright_against_the_bones"
            )
    light = float(measures.light(femur_places)) if femur_places.any() else None
    handed("joint_plane", ("objects",))
    return JointPlane(
        z,
        False,
        "read",
        codes,
        femur.code,
        tibia.code,
        labels,
        available,
        handed_on(objects),
        candidates,
        ends,
        side if front_in_plane and not sides_in_plane else None,
        toward_left_mm,
        light,
        asked,
    )


@dataclass(frozen=True)
class JointTwin:
    """What the other sequence's slice through one pointed plane holds of the plane's parts: the
    twin's `slice` (None where it has none), the `code` ("read", or why not: an unknown, never an
    absence), the plane's parts laid onto the twin's own pixels (`objects`, int8) and the distance of
    their places from the twin's plane (`off_mm`). No lens is read on the twin."""

    slice: int | None
    code: str
    objects: np.ndarray | None
    off_mm: float | None


def joint_twin(own: Measured, twin: Measured | None, plane: JointPlane) -> JointTwin:
    """A pointed plane's named parts (`JOINT_PARTS`) laid onto the other sequence's slice through the
    same place, by the scanner's millimetres (never equal indices: `slice_through`) and the pair's one
    match of places (`matched`, shared with every other part laid across); the places the twin never
    saw hold nothing laid on them. Every failure is a code."""
    if plane.objects is None:
        raise ValueError("a_pointed_plane_that_was_read")
    objects = np.asarray(plane.objects)
    parts = [OBJECT_CODES[name] for name in JOINT_PARTS]
    if twin is None:
        return JointTwin(None, "none_of_the_other_sequence", None, None)
    other = twin.series
    thick, why = slab_thicknesses(other)
    if why is not None:
        return JointTwin(None, why, None, None)
    frame = plane_frame(own.series, plane.slice)
    if isinstance(frame, str):
        return JointTwin(None, frame, None, None)
    origins = np.asarray([np.asarray(p, dtype=float) for p in other.geometry.position])
    index = slice_through(frame.origin_lps, origins, twin.frame.normal(), thick)
    if index is None:
        return JointTwin(None, "twin_has_no_slice_at_this_place", None, None)
    twin_frame = plane_frame(other, index)
    if isinstance(twin_frame, str):
        return JointTwin(index, twin_frame, None, None)
    uid, twin_uid = own.series.row.series_uid, other.row.series_uid
    plane_here = np.asarray(own.series.volume[plane.slice])
    plane_there = np.asarray(other.volume[index])
    forward = matched(
        other,
        {"series_uid": twin_uid, "slice_index": index},
        twin_frame,
        plane_there.shape,
        {"series_uid": uid, "slice_index": plane.slice},
        frame,
        plane_here,
    )
    if isinstance(forward, str):
        return JointTwin(index, forward, None, None)
    reads("joint_plane", ("objects",), "joint_twin")
    laid = laid_by(objects, forward)
    named = np.where(np.isin(laid, parts), laid, 0).astype(np.int8)
    named[~finite_of(other)[index]] = (
        0  # a place the twin never saw holds nothing laid on it
    )
    places = frame.to_patient(np.argwhere(np.isin(objects, parts)).astype(float))
    off = (
        float(abs((places.mean(axis=0) - twin_frame.origin_lps) @ twin_frame.normal()))
        if len(places)
        else None
    )
    return JointTwin(index, "read", named, off)


# What a run of a quantity's support says once the existing rule read the planes read for it.
JOINT_RUN_RULE = {
    **RUN_CONFIRMATION,
    "candidates_only_the_existing_rule_does_not_license_the_plane": 4,
}
# The rule each quantity points at, in a plane's codes.
JOINT_POINTED_RULE = {
    DARK: "meniscus",
    LIGAMENT: "pcl",
    BRIGHT: "cartilage",
    FLUID: "acl",
}
JOINT_CANDIDATE_KEY = {DARK: "horns", BRIGHT: "cartilage_reading"}
JOINT_CANDIDATE_CODE = {DARK: HORNS, BRIGHT: CARTILAGE_CANDIDATES}


def says_of(plane: JointPlane, quantity: str, middle_codes: dict[str, str]) -> str:
    """What the existing rule a quantity points at said on one plane read for it: "confirmed" (the
    rule named it), "candidates" (only the reading its gate refuses), "rejected" (read, nothing) or
    "not_read" (the plane is the middle slice, whose own naming has no rule for it)."""
    rule = JOINT_POINTED_RULE[quantity]
    if plane.middle:
        code = middle_codes.get(rule)
        return (
            "confirmed"
            if code in NAMED
            else "not_read"
            if quantity == FLUID
            else "rejected"
        )
    if plane.codes.get(rule) == "identified":
        return "confirmed"
    key = JOINT_CANDIDATE_KEY.get(quantity)
    if key is not None and plane.codes.get(key) == JOINT_CANDIDATE_CODE[quantity]:
        return "candidates"
    return "rejected"


def joint_arrays(
    own: Measured,
    profile: JointProfile,
    planes: list[JointPlane],
    twins: list[JointTwin | None],
    pointed: list[int],
    runs: dict[str, list[tuple[int, int]]],
    origins: np.ndarray,
    offsets: np.ndarray,
    sound: bool,
    thick: np.ndarray,
) -> dict[str, np.ndarray]:
    """What the joint's profile and pointed planes keep, named `a3_joint_*`, in the series' own middle
    arrays: per quantity its status and area through depth, the tiles that could hold its level, its
    runs and their ends and envelopes; the corridor's pixels and tiles and the finer readings at their
    own resolution (ragged, nothing padded); the pointed slices' places along the stack's normal; and,
    one row per pointed plane but the middle slice (whose naming is `a1_objects`), the plane's naming
    `objects`, the `reading` candidates, the `horn_end` and the place toward the left of the notch. The
    lens's labels of a plane the bones already kept are not copied: `bone_lens_row` names its row of
    `a3_bone_plane_labels`; the others are one row of `a3_joint_plane_labels`."""
    shape = np.shape(own.arrays["acquired_plane"])
    rows_in = [p for p in planes if not p.middle]
    pointed_origin = origins[pointed] if sound and pointed else np.empty((0, 3))
    arrays: dict[str, np.ndarray] = {
        "a3_joint_corridor_px": profile.corridor_px,
        "a3_joint_corridor_tiles": profile.corridor,
        "a3_joint_seen_blocks": profile.seen_blocks,
        "a3_joint_unseen_blocks": profile.unseen_blocks,
        "a3_joint_profile_window_rc": profile.window_rc,
        "a3_joint_profile_block_mm": profile.cell_mm,
        "a3_joint_profile_block_px": profile.block_px,
        "a3_joint_depth_offsets_mm": offsets,
        "a3_joint_slice_thickness_mm": thick,
        "a3_joint_pointed_slices": np.asarray(pointed, dtype=np.int32),
        "a3_joint_pointed_origin_lps": pointed_origin,
        "a3_joint_pointed_position_mm": offsets[pointed]
        if sound and pointed
        else np.empty(0),
        "a3_joint_pointed_along_normal_mm": (pointed_origin @ own.frame.normal())
        if len(pointed_origin)
        else np.empty(0),
        "a3_joint_source_normal_lps": own.frame.normal(),
    }
    for q in profile.names:
        at = profile.level[q]
        arrays[f"a3_joint_{q}_status"] = profile.status[q]
        arrays[f"a3_joint_{q}_area_mm2"] = profile.area_mm2[q]
        arrays[f"a3_joint_{q}_could_tiles"] = profile.could[q]
        arrays[f"a3_joint_{q}_level"] = np.asarray(
            (np.nan, np.nan) if at is None else at, dtype=np.float64
        )
        _, ends, spans = describe_runs(
            runs[q], profile.status[q], offsets, thick, sound
        )
        arrays[f"a3_joint_{q}_runs"] = np.asarray(runs[q], dtype=np.int32).reshape(
            -1, 2
        )
        arrays[f"a3_joint_{q}_run_ends"] = ends.astype(np.int32)
        arrays[f"a3_joint_{q}_run_envelope_mm"] = spans
    for name, value in pack_fine_readings(profile.fine).items():
        if name != "tibia_reference":
            arrays[
                f"a3_joint_fine_{'reach_blocks' if name == 'pointer_body' else name}"
            ] = value
    bone_slices = [int(z) for z in own.arrays.get("a3_bone_plane_slices", ())]
    own_rows = [
        p for p in rows_in if p.labels is not None and p.slice not in bone_slices
    ]
    zero = np.zeros(shape, dtype=bool)
    arrays["a3_joint_plane_slices"] = np.asarray(
        [p.slice for p in rows_in], dtype=np.int32
    )
    arrays["a3_joint_plane_bone_lens_row"] = np.asarray(
        [bone_slices.index(p.slice) if p.slice in bone_slices else -1 for p in rows_in],
        dtype=np.int32,
    )
    own_slices = [p.slice for p in own_rows]
    arrays["a3_joint_plane_lens_row"] = np.asarray(
        [own_slices.index(p.slice) if p.slice in own_slices else -1 for p in rows_in],
        dtype=np.int32,
    )
    arrays["a3_joint_plane_labels"] = stack_of(
        [np.asarray(p.labels) for p in own_rows], shape, np.int32
    )
    arrays["a3_joint_plane_available"] = stack_of(
        [zero if p.available is None else p.available for p in own_rows], shape, bool
    )
    arrays["a3_joint_plane_objects"] = stack_of(
        [
            np.zeros(shape, np.int8) if p.objects is None else np.asarray(p.objects)
            for p in rows_in
        ],
        shape,
        np.int8,
    )
    arrays["a3_joint_plane_reading"] = stack_of(
        [
            np.zeros(shape, np.int8) if p.reading is None else np.asarray(p.reading)
            for p in rows_in
        ],
        shape,
        np.int8,
    )
    arrays["a3_joint_plane_horn_end"] = stack_of(
        [
            np.zeros(shape, np.int8) if p.horn_end is None else np.asarray(p.horn_end)
            for p in rows_in
        ],
        shape,
        np.int8,
    )
    arrays["a3_joint_plane_toward_left_mm"] = np.asarray(
        [np.nan if p.toward_left_mm is None else p.toward_left_mm for p in rows_in],
        dtype=np.float64,
    )
    arrays["a3_joint_plane_light"] = np.asarray(
        [np.nan if p.light is None else p.light for p in rows_in], dtype=np.float64
    )
    return arrays


@dataclass(frozen=True)
class JointRead:
    """The joint in one series, as `read_joint` read it: the `profile` through depth, the planes it
    pointed to (`planes`, the middle slice's bootstrap among them where it was), the twin's laying
    beside each plane but the middle one (`twins`), how it came out (`outcome`), the record's
    description (`record`, plain data) and the arrays it keeps on the series (`arrays`)."""

    profile: JointProfile
    planes: tuple[JointPlane, ...]
    twins: tuple[JointTwin | None, ...]
    outcome: str
    record: dict
    arrays: dict[str, np.ndarray]


def read_joint(
    own: Measured,
    partner: Measured | None,
    leg: Leg,
    reference: Reference | str = "no_reference_given",
    mapping: MapContext | None = None,
) -> JointRead | str:
    """The joint of one series: the four-quantity profile of its corridor (`joint_profile`, from
    the bones' carried places, the series' background split and the bones' marrow light), each
    quantity's pointed planes (the maximum of each run of support, every tie, every run, and the
    slice beside a maximum that was unreadable: `positive_runs`, `run_maxima`, `confirmations`),
    and on only the planes the questions need the existing rules (`joint_plane`) with the plane's
    parts laid onto the twin's slice of the same place (`joint_twin`); the series' middle slice is
    the bootstrap's own naming and is not read again. Or why the series cannot be read: a string
    code, an unknown and never an absence. Only a series the leg runs along is read (a sagittal or
    coronal one) that named both bones on its middle slice.

    The search (`joint_questions`, `joint_neighbourhood`): the questions this view's gates admit
    (each sided meniscus, the cartilage, the cruciate candidates), each with its own quantity. With
    the production map, the profile is read first on the union of those questions' anatomical guide
    slices, and same-question runs whose existing fine support overlaps a guide's in-plane box are
    asked first; a question without a guide requires the full established depth. Without a map, the
    legacy reference window remains for direct callers. The profile is read only on slices the
    bones' family established; a run whose strongest slice
    lies at the edge of what was read is walked on to its own peak; the runs are asked strongest
    first (every tie, every slice of a plateau) while a question their quantity points at is open,
    and every plane read answers every question its rules can; once every question is answered the
    rest stay pointers (`not_read_natively`), and where one is not, the rest of the established
    depth is read (the second pass merges: no slice read twice, no plane asked twice). Slices never
    read are NOT_READ, unknown and never empty."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    if not own.assignment.in_plane[2]:
        return "abstain_leg_runs_through_the_plane"
    objects = own.arrays["a1_objects"]
    femur_mask = objects == OBJECT_CODES["femur"]
    tibia_mask = objects == OBJECT_CODES["tibia"]
    assigned = record["assignments"]
    if (
        assigned["femur"] is None
        or assigned["tibia"] is None
        or not (femur_mask.any() and tibia_mask.any())
    ):
        return "bones_not_named_on_the_middle_slice"
    reads("squint_stack", ("code",), "joint")
    if own.stack.code != "present":
        return f"squint_{own.stack.code}"
    if series.volume is None:
        return "no_stacked_volume"
    femur_lps, tibia_lps = leg.femur_lps, leg.tibia_lps
    if not len(femur_lps) or not len(tibia_lps):
        return "no_carried_places"
    index = record["slice_index"]
    measures = measures_of(uid, index, own.arrays["acquired_plane"], own.frame)
    fat_suppressed = int(series.row.fat_suppression) == 1  # the tag is stored as text
    level = levels(
        float(record["background_split"]),
        float(measures.light(femur_mask)),
        float(measures.light(femur_mask | tibia_mask)),
    )
    names = (DARK, BRIGHT, FLUID) if fat_suppressed else (DARK, LIGAMENT)
    established = bones_identified_at(own, partner)
    depth = len(series.volume)
    unestablished = (
        None
        if established is None
        else np.asarray([z not in established for z in range(depth)], dtype=bool)
    )
    readable = np.ones(depth, dtype=bool) if unestablished is None else ~unestablished
    coronal = bool(own.assignment.in_plane[0])
    sided = SIDED_MENISCI[:2] if assigned["knee"] in ("R", "L") else SIDED_MENISCI[2:]
    asks = joint_questions(coronal, fat_suppressed, sided)
    asking = tuple(q for q in names if q in set(asks.values()))
    # Where to look first: the expected neighbourhood of the study's reference, else the whole depth
    window, search = joint_neighbourhood(
        own, reference, asking, fat_suppressed, mapping
    )
    partial = window is not None and not window.all()
    middle_codes = record["assignments"]["codes"]

    def cheap(visit: np.ndarray | None) -> JointProfile:
        """The joint's cheap profile over the slices `visit` names (the whole depth for None); the
        others stay NOT_READ, unknown and never empty."""
        return joint_profile(
            series,
            own.stack,
            femur_lps,
            tibia_lps,
            level,
            names,
            bones_unestablished=unestablished,
            visit=visit,
        )

    visited = window.copy() if partial and window is not None else np.ones(depth, bool)
    profile = cheap(visited if partial else None)
    reads("joint_profile", ("status", "area_mm2"), "joint")
    if mapping is not None:
        reads("joint_profile", ("fine",), "joint_map_guidance")
    spatial_hits = (
        joint_guide_spatial_hits(profile, asks, search, own=own)
        if mapping is not None
        else {}
    )
    keys = (digest(femur_lps), digest(tibia_lps))
    sagittal = not coronal
    read_at: dict[int, JointPlane] = {}
    twin_at: dict[int, JointTwin | None] = {}
    answered: dict[str, int] = {}
    passes = 1

    def ask(z: int) -> None:
        """One pointed plane read natively, once: the middle slice is the bootstrap's own naming; any
        other the existing rules (`joint_plane`) and the twin's laying of what they named; what the
        plane answers is kept with its slice, for every question it answers."""
        if z in read_at:
            return
        if z == index:
            plane = JointPlane(
                z,
                True,
                "bootstrap",
                {},
                "",
                "",
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                (),
            )
            twin_at[z] = None
        else:
            left = None
            place = plane_frame(series, z)
            if (
                sagittal
                and not isinstance(place, str)
                and leg.notch_origin_lps is not None
                and leg.notch_normal is not None
            ):
                left = float(
                    (place.origin_lps - leg.notch_origin_lps) @ leg.notch_normal
                )
            plane = joint_plane(own, z, femur_lps, tibia_lps, keys, (), left)
            twin_at[z] = (
                joint_twin(own, partner, plane)
                if plane.code == "read" and plane.objects is not None
                else None
            )
        read_at[z] = plane
        for question in joint_answers(plane, coronal, objects):
            answered.setdefault(question, z)

    def pointers(
        current: JointProfile,
    ) -> tuple[
        dict[str, list[tuple[int, int]]],
        dict[str, list[np.ndarray]],
        dict[str, list[int]],
    ]:
        runs_of = {q: positive_runs(current.area_mm2[q]) for q in names}
        peaks_of = {q: run_maxima(current.area_mm2[q], runs_of[q]) for q in names}
        confirm_of = {
            q: confirmations(
                runs_of[q], peaks_of[q], current.status[q], (JOINT_UNREADABLE,)
            )
            for q in names
        }
        return runs_of, peaks_of, confirm_of

    def open_for(q: str) -> bool:
        return any(a == q and question not in answered for question, a in asks.items())

    stopped = "a_question_stayed_open_every_pointed_plane_was_asked"
    for step in (0, 1):
        if step == 1:
            # the expected neighbourhood did not answer every question: the rest of the
            # established depth, merged so no slice is read twice
            rest = ~visited
            if not (partial and (rest & readable).any()):
                break
            profile = merge_joint_profiles(profile, cheap(rest), rest)
            visited = np.ones(depth, dtype=bool)
            passes = 2
        while step == 0 and partial:
            # A run whose strongest slice lies at the edge of what was read has its maximum beyond
            # it, not here: the profile walks on, one established slice at a time, to where the run
            # peaks, so that the plane asked is the run's own representative.
            runs_of, peaks_of, _ = pointers(profile)
            more = np.zeros(depth, dtype=bool)
            for q in asking:
                for (a, b), peaks in zip(runs_of[q], peaks_of[q], strict=True):
                    if a in peaks and a > 0 and not visited[a - 1] and readable[a - 1]:
                        more[a - 1] = True
                    if b - 1 in peaks and b < depth and not visited[b] and readable[b]:
                        more[b] = True
            if not more.any():
                break
            profile = merge_joint_profiles(profile, cheap(more), more)
            visited |= more
            ledger.record("joint.walked_slices", planes=int(more.sum()))
        runs_of, peaks_of, confirm_of = pointers(profile)
        order: list[tuple[float, str, list[int]]] = []
        for q in asking:
            for (a, b), peaks in zip(runs_of[q], peaks_of[q], strict=True):
                here = sorted(
                    {int(z) for z in peaks}
                    | {int(z) for z in confirm_of[q] if z in (a - 1, b)}
                )
                order.append((float(profile.area_mm2[q][peaks[0]]), q, here))
        # strongest first; runs of equal support are one group and each is asked while its own
        # quantity's question is open, so a tie is never broken
        order.sort(key=lambda row: -row[0])
        if mapping is not None:
            # Keep the global support order, but use its slots for each question to put runs whose
            # existing fine support overlaps a map placement before that question's other runs.
            order = order_joint_runs(order, asks, spatial_hits)
        for group in joint_run_groups(order):
            for _, _q, here in [row for row in group if open_for(row[1])]:
                for z in here:
                    ask(z)
        if all(question in answered for question in asks):
            stopped = "every_question_was_answered_the_rest_stay_pointers"
            break
    runs, maxima, confirm = pointers(profile)
    pointed_by: dict[int, list[str]] = {}
    for q in names:
        for z in {int(z) for peaks in maxima[q] for z in peaks} | set(confirm[q]):
            pointed_by.setdefault(z, []).append(q)
    pointed = sorted(pointed_by)
    ledger.record("joint.pointed_planes", planes=len(pointed))
    ledger.record("joint.planes_asked", planes=len(read_at))
    if window is not None:
        ledger.record("joint.window_slices_in", planes=int(window.sum()))
        ledger.record(
            "joint.window_slices_unvisited", planes=int(np.count_nonzero(~visited))
        )
        ledger.record("joint.window_broadened", planes=int(passes > 1))
    # each plane keeps every quantity that pointed at it
    planes = [
        replace(read_at[z], asked=tuple(pointed_by.get(z, ()))) for z in sorted(read_at)
    ]
    twins = [twin_at[z] for z in sorted(read_at) if z != index]
    origins, thick, offsets, sound = series_depth(series, own.frame, index)
    asked_of = {p.slice: p for p in planes}
    quantity_rows: dict[str, dict] = {}
    for q in names:
        described, _, _ = describe_runs(
            runs[q], profile.status[q], offsets, thick, sound
        )
        for i, ((a, b), peaks) in enumerate(zip(runs[q], maxima[q], strict=True)):
            here = sorted(
                {int(z) for z in peaks}
                | {int(z) for z in confirm[q] if z in (a - 1, b)}
            )
            said = [
                says_of(asked_of[z], q, middle_codes) if z in asked_of else "unasked"
                for z in here
            ]
            described[i]["planes_read_for_it"] = [z for z in here if z in asked_of]
            described[i]["planes_pointed_to"] = here
            described[i]["native_rule"] = (
                "confirmed_by_the_native_rule"
                if "confirmed" in said
                else "candidates_only_the_existing_rule_does_not_license_the_plane"
                if "candidates" in said
                else "rejected_by_the_native_rule"
                if "rejected" in said
                else "not_read_natively"
            )
        at_level = profile.level[q]
        quantity_rows[q] = {
            "points_at": POINTS_AT[q],
            "level": None
            if at_level is None
            else [None if np.isinf(v) else float(v) for v in at_level],
            "status": {
                name: int(np.count_nonzero(profile.status[q] == code))
                for name, code in FIBULA_POINTER_STATUS.items()
                if np.count_nonzero(profile.status[q] == code)
            },
            "questions": sorted(k for k, a in asks.items() if a == q),
            "pointer_runs": described,
            "pointer_representatives": [[int(z) for z in peaks] for peaks in maxima[q]],
            "confirmed_slices": [int(z) for z in confirm[q]],
            "unknown_slices": [
                int(z) for z in np.flatnonzero(profile.status[q] == JOINT_UNREADABLE)
            ],
        }
    rows_in = [p for p in planes if not p.middle]
    twin_of = {id(p): t for p, t in zip(rows_in, twins, strict=True)}
    pointed_rows = []
    for p in planes:
        row: dict[str, Any] = {
            "slice": p.slice,
            "middle": p.middle,
            "pointed_by": list(p.asked),
            "code": p.code,
            "codes": dict(p.codes),
            "femur": p.femur,
            "tibia": p.tibia,
            "compartment": p.compartment,
            "toward_left_of_the_notch_mm": p.toward_left_mm,
            "femur_marrow_light": None if p.light is None else finite_or_none(p.light),
            "position_mm": finite_or_none(offsets[p.slice]) if sound else None,
            "parts_pixels": {
                name: int(np.count_nonzero(p.objects == OBJECT_CODES[name]))
                for name in JOINT_PARTS
                if p.objects is not None
                and np.count_nonzero(p.objects == OBJECT_CODES[name])
            },
        }
        if not p.middle:
            twin = twin_of[id(p)]
            row["twin"] = (
                None
                if twin is None
                else {"slice": twin.slice, "code": twin.code, "off_mm": twin.off_mm}
            )
        pointed_rows.append(row)
    if not pointed:
        outcome = (
            "unreadable"
            if any((profile.status[q] == JOINT_UNREADABLE).any() for q in names)
            else "no_support_found"
        )
    else:
        outcome = "read"
    ambiguities = [
        "the_corridor_is_where_the_bones_carried_places_leave_a_joint_an_upper_bound_never_a_section",
        "a_quantity_is_support_never_a_name_the_existing_rules_name_on_the_pointed_planes_only",
    ]
    if any(profile.unseen_blocks > 0):
        ambiguities.append("blocks_never_seen_make_an_area_a_lower_bound")
    if any(row["unknown_slices"] for row in quantity_rows.values()):
        ambiguities.append("slices_the_profile_could_not_read_are_unknown_not_empty")
    if not sound:
        ambiguities.append("slice_geometry_unsound_so_no_physical_depth")
    if not visited.all():
        ambiguities.append(
            "slices_outside_the_expected_neighbourhood_were_not_visited_unknown_not_empty"
        )
    if any(
        z not in asked_of
        for z in pointed
        if any(a == q for q in pointed_by[z] for a in asks.values())
    ):
        ambiguities.append(
            "a_pointed_plane_not_read_natively_is_a_pointer_not_an_absence"
        )
    record_part = {
        "outcome": outcome,
        "block_mm": float(LIGAMENT_SMOOTH_MM),
        "reach_mm": float(SHELL_MM),
        "quantities": quantity_rows,
        "run_rule_codes": dict(JOINT_RUN_RULE),
        "status_codes": dict(FIBULA_POINTER_STATUS),
        "pointed_planes": pointed_rows,
        "ambiguities": ambiguities,
        "search": {
            **search,
            "map_guidance": search.get("map_questions", {}),
            "in_plane_support": {
                question: {str(z): hit for z, hit in slices.items()}
                for question, slices in spatial_hits.items()
            },
            "questions": {
                question: {
                    "quantity": a,
                    "answered_on_slice": answered.get(question),
                }
                for question, a in asks.items()
            },
            "quantities_with_no_question_on_this_view": [
                q for q in names if q not in asking
            ],
            "passes": passes,
            "broadened_to_the_whole_established_depth": passes > 1,
            "stopped": stopped,
            "slices_visited": int(visited.sum()),
            "slices_unvisited": [int(z) for z in np.flatnonzero(~visited)],
            "planes_read_natively": sorted(read_at),
            "planes_the_profile_pointed_to": pointed,
            "reference_key": "record `reference` of the series named by reference_series_uid",
        },
    }
    arrays = joint_arrays(
        own, profile, planes, twins, pointed, runs, origins, offsets, sound, thick
    )
    arrays["a3_joint_search_window"] = (
        np.ones(depth, dtype=bool) if window is None else window
    )
    arrays["a3_joint_search_visited"] = visited
    handed("joint", ("pointed", "planes", "twins"))
    if mapping is not None:
        for question in asks:
            guided = bool(
                search.get("map_questions", {}).get(question, {}).get("guided")
            )
            answer = answered.get(question)
            spatial = spatial_hits.get(question, {})
            if not guided:
                use = "unguided_full_search"
            elif answer is not None and spatial.get(answer, False):
                use = "guided_hit"
            elif passes > 1:
                use = "guided_miss_then_full_search"
            elif answer is not None:
                use = "guided_miss_then_other_pointer"
            else:
                use = "guided_no_answer"
            search.get("map_questions", {}).get(question, {})["outcome"] = use
            for target in (
                search.get("map_questions", {}).get(question, {}).get("targets", [])
            ):
                mapping.smap.note_use(
                    target["object"],
                    uid,
                    use,
                    question=question,
                    anchors=target.get("anchors", []),
                    answered_on_slice=answer,
                    spatial_hit=None if answer is None else spatial.get(answer, False),
                    full_depth=not visited.any() or bool(visited.all()) or passes > 1,
                )
            ledger.record(f"study_map.joint_guidance.{use}", questions=1)
    return JointRead(profile, tuple(planes), tuple(twins), outcome, record_part, arrays)


def sided_menisci(
    own: Measured, read: JointRead, bodies: list[dict], names: tuple[str, ...]
) -> dict[str, dict]:
    """ONE sided meniscus is its coronal body and its sagittal horns, kept as separate descriptions
    of the same object: for each compartment, the planes that named its body (where the coronal rules
    name it) and the planes whose horn candidates lie in its compartment, with the pixels of each.
    A compartment with neither is kept empty: unknown, not absent."""
    found: dict[str, dict] = {
        name: {"coronal_body": [], "sagittal_horns": []} for name in names
    }
    for body in bodies:
        found.setdefault(body["object"], {"coronal_body": [], "sagittal_horns": []})[
            "coronal_body"
        ].append({k: v for k, v in body.items() if k != "object"})
    rows_in = [p for p in read.planes if not p.middle]
    for row, p in enumerate(rows_in):
        if p.codes.get("horns") != HORNS or p.reading is None or p.horn_end is None:
            continue
        name = (
            "meniscus"
            if p.compartment in (None, "meniscus")
            else f"{p.compartment}_meniscus"
        )
        found.setdefault(name, {"coronal_body": [], "sagittal_horns": []})[
            "sagittal_horns"
        ].append(
            {
                "slice": p.slice,
                "row": row,
                "toward_left_of_the_notch_mm": p.toward_left_mm,
                "front_pixels": int(np.count_nonzero(p.horn_end == 1)),
                "back_pixels": int(np.count_nonzero(p.horn_end == 2)),
                "provenance": "native",
                "kind": "reading",
            }
        )
    return found


def joint_twin_arrays(
    twin: Measured,
    planes: list[JointPlane],
    twins: list[JointTwin | None],
    prefix: str,
) -> dict[str, np.ndarray]:
    """What the twin's slices through the pointed planes hold of the planes' parts, as a stack on the
    twin's own pixels, named `<prefix>_*`, one row per plane whose twin was read: the plane's slice
    (`from_slices`), the twin's (`slices`) and the parts laid on (`objects`, `OBJECT_CODES`). (The
    prefix names the series that asked, so two sequences asking one twin never overwrite each
    other.)"""
    shape = np.shape(twin.arrays["acquired_plane"])
    rows = [
        (p, t)
        for p, t in zip(planes, twins, strict=True)
        if t is not None and t.code == "read"
    ]
    return {
        f"{prefix}_from_slices": np.asarray([p.slice for p, _ in rows], dtype=np.int32),
        f"{prefix}_slices": np.asarray(
            [-1 if t.slice is None else t.slice for _, t in rows], dtype=np.int32
        ),
        f"{prefix}_objects": stack_of(
            [
                np.zeros(shape, np.int8) if t.objects is None else t.objects
                for _, t in rows
            ],
            shape,
            np.int8,
        ),
    }


# What a rule says of a plane its own gate refuses by orientation or by sequence: expected, so no
# reading is made of it (the plane's codes keep it).
JOINT_GATES = (
    "abstain_side_to_side_runs_through_the_plane",
    "abstain_front_to_back_runs_through_the_plane",
    "abstain_not_brighter_than_marrow_without_fat_suppression",
    "abstain_marrow_as_dark_as_a_ligament_with_fat_suppression",
    "abstain_not_walled_off_without_fat_suppression",
)
JOINT_NOTES = {
    "meniscus": "the existing menisci description names the dark wedge on this coronal plane: the body's section here, not the whole meniscus (its horns are the sagittal planes' readings)",
    "cartilage": "the layer on this bone in the joint on this plane: the section here, not the whole surface",
    "mcl": "the low signal left on the medial meniscus's side that joins the bones, on this coronal plane: the section here",
    "pcl": "the thick uniformly dark band joining the bones on this sagittal plane: the section here",
    "acl": "the region walled off by fluid whose peak lies in the joint on this sagittal plane, the bones carried here by place: the section here",
}


def bones_identified_at(own: Measured, partner: Measured | None) -> set[int] | None:
    """The slices of `own`'s stack where the bones' family natively identified BOTH the femur and
    the tibia (`a3_<bone>_plane_outcome` identified, and the middle slice, the bootstrap's own
    naming), read from the series' own bone arrays where it was profiled and otherwise from its
    twin's, at the twin's slice through the same place (`slice_through`: a warranted same-place
    transfer of the identity, not a projection). None where no series of the pair was profiled."""
    source = own if "a3_femur_plane_slices" in own.arrays else partner
    if source is None or "a3_femur_plane_slices" not in source.arrays:
        return None
    reads("bones", ("planes",), "joint")
    both: set[int] | None = None
    for bone in ("femur", "tibia"):
        named = {int(source.record["slice_index"])} | {
            int(z)
            for z, outcome in zip(
                source.arrays[f"a3_{bone}_plane_slices"],
                source.arrays[f"a3_{bone}_plane_outcome"],
                strict=True,
            )
            if int(outcome) == OUTCOMES.index(IDENTIFIED)
        }
        both = named if both is None else both & named
    assert both is not None
    if source is own:
        return both
    other = source.series
    origins = np.asarray([np.asarray(q, dtype=float) for q in other.geometry.position])
    thick = [float("nan") if t is None else float(t) for t in other.slice_thickness_mm]
    normal = source.frame.normal()
    depth = len(own.series.volume) if own.series.volume is not None else 0
    found: set[int] = set()
    for z in range(depth):
        place = plane_frame(own.series, z)
        if isinstance(place, str):
            continue
        at = slice_through(place.origin_lps, origins, normal, thick)
        if at is not None and at in both:
            found.add(z)
    return found


def name_the_joint(
    measured: list[Measured],
    partners: list[Measured | None],
    leg: Leg | None,
    study_uid: str,
    reference: Reference | str = "no_reference_given",
    mapping: MapContext | None = None,
) -> None:
    """The sided menisci, the articular cartilage, the cruciates and the MCL through the stacks
    (`read_joint`) of every series the leg runs along that names both bones on its middle slice,
    kept in the series' own middle records and arrays (saved by the caller) beside the observations
    the bones and the patella made.

    Native: the middle slice's own naming of each part (the bootstrap), each part on each pointed
    plane where its existing rule names it (resolved, one row of `a3_joint_plane_objects`), what a
    rule found where its gate refuses the plane (the horn candidates of a sagittal plane in its
    compartment, the cartilage there: readings, never names, one row of `a3_joint_plane_reading`),
    and a rule that read a plane it was pointed to and named nothing (a reading with its code). Laid:
    each pointed plane's parts onto the other sequence's slice of the same place
    (`joint_twin`, `<prefix>_objects` of the twin). Projected: each part's largest section onto the
    slice of every other series nearest it (a target for a native question, never a boundary; the
    coronal body of a meniscus onto the sagittal series is where its horns are asked). One sided
    meniscus is its coronal body and its sagittal horns: the same object name carries both, and the
    record lists them apart per compartment (`sided_menisci`). What could not be said is an
    `Unresolved` with its code: a part no pointed plane named, a lateral plane beyond the compartment,
    a series the leg runs through, is unknown and never absent. The profile and every plane are kept
    and no stage reads them: the existing consumers (the MCL and the cartilage on the middle slice,
    the cruciates' own slices) are not changed by them."""
    carried = leg if leg is not None else leg_of(measured)
    results = [
        read_joint(own, partners[i], carried, reference, mapping)
        for i, own in enumerate(measured)
    ]
    where = {id(m): i for i, m in enumerate(measured)}
    said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    for i, own in enumerate(measured):
        read = results[i]
        uid, view = own.record["series_uid"], tuple(own.record["view"])
        here, missing = said[i]
        artifact = str(artifact_of(study_uid, own.record))
        if isinstance(read, str):
            own.record["joint"] = {"code": read, "quantities": list(POINTS_AT)}
            missing.append(Unresolved("joint", "native", uid, view, read))
            continue
        partner = partners[i]
        at = None if partner is None else where[id(partner)]
        index = own.record["slice_index"]
        assigned = own.record["assignments"]
        codes = assigned["codes"]
        sided = (
            SIDED_MENISCI[:2] if assigned["knee"] in ("R", "L") else SIDED_MENISCI[2:]
        )
        wanted = (*sided, *JOINT_PARTS[3:])
        rows_in = [p for p in read.planes if not p.middle]
        twins = list(read.twins)
        own.arrays.update(read.arrays)
        # the joint lies between the bones: a pointed plane's names are resolved only where the
        # bones' family natively identified both bones at that place (marrow body agreeing with the
        # territory); elsewhere the existing rules' decisions are kept as readings, never names
        confirmed_at = bones_identified_at(own, partner)
        prefix = "a3_joint_twin"
        if partner is not None:
            prefix = source_prefix(prefix, partner.arrays, uid)
            partner.arrays.update(joint_twin_arrays(partner, rows_in, twins, prefix))
        twin_artifact = (
            str(artifact_of(study_uid, partner.record)) if partner is not None else ""
        )
        got: set[str] = set()
        reason: dict[str, set[str]] = {name: set() for name in wanted}
        bodies: list[dict] = []
        sections: dict[
            str, list[tuple[int, np.ndarray, PlaneFrame, str, int | None]]
        ] = {name: [] for name in wanted}
        # the middle slice: the bootstrap's own naming of each part, as the run made it
        middle = own.arrays["a1_objects"]
        for name in wanted:
            if name == "acl":
                continue  # the ACL is named on its own slice, not the middle (see `joint_existing`)
            code = codes.get(JOINT_RULE[name])
            mask = middle == OBJECT_CODES[name]
            reason[name].add(str(code))
            if code in NAMED and mask.any():
                got.add(name)
                native = code == "identified"
                here.append(
                    observe(
                        name,
                        "native" if native else "laid",
                        "resolved",
                        own,
                        (index,),
                        str(code),
                        int(np.count_nonzero(mask)),
                        0.0 if native else None,
                        "a1_objects",
                        "the middle slice's own naming (the bootstrap): the section on this slice, not the whole part",
                        artifact,
                        None,
                        OBJECT_CODES[name],
                    )
                )
                sections[name].append((index, mask, own.frame, "a1_objects", None))
                if name in SIDED_MENISCI:
                    bodies.append(
                        {
                            "object": name,
                            "slice": index,
                            "row": None,
                            "pixels": int(np.count_nonzero(mask)),
                            "provenance": "native" if native else "laid",
                            "kind": "resolved",
                            "code": str(code),
                        }
                    )
        # the pointed planes: the rules read on each, row by row of the stacks kept
        stack_objects = own.arrays["a3_joint_plane_objects"]
        stack_reading = own.arrays["a3_joint_plane_reading"]
        twin_row = 0
        for row, (p, t) in enumerate(zip(rows_in, twins, strict=True)):
            if p.code != "read":
                missing.append(Unresolved("joint", "native", uid, view, p.code))
                continue
            frame = plane_frame(own.series, p.slice)
            for name in wanted:
                reason[name].add(str(p.codes[JOINT_RULE[name]]))
                mask = stack_objects[row] == OBJECT_CODES[name]
                count = int(np.count_nonzero(mask))
                if not count:
                    continue
                # the cruciates on the extra planes were found, on the proof, to outline soft tissue
                # behind the knee and over the tibia: the existing rule's decision is kept as a
                # reading (never resolved, never projected) until a relation tells them apart
                unconfirmed = confirmed_at is None or p.slice not in confirmed_at
                cruciate = name in ("pcl", "acl") or unconfirmed
                if not cruciate:
                    got.add(name)
                here.append(
                    observe(
                        name,
                        "native",
                        "reading" if cruciate else "resolved",
                        own,
                        (p.slice,),
                        str(p.codes[JOINT_RULE[name]]),
                        count,
                        0.0,
                        "a3_joint_plane_objects",
                        JOINT_NOTES[JOINT_RULE[name]]
                        + (
                            "; a reading only: the existing rule's decision on an additional plane, not validated anatomy"
                            if name in ("pcl", "acl")
                            else "; a reading only: the bones' family did not natively identify both bones at this place, so the joint between them is not established here"
                            if unconfirmed
                            else ""
                        ),
                        artifact,
                        row,
                        OBJECT_CODES[name],
                    )
                )
                if not isinstance(frame, str) and not cruciate:
                    sections[name].append(
                        (p.slice, mask, frame, "a3_joint_plane_objects", row)
                    )
                if name in SIDED_MENISCI:
                    bodies.append(
                        {
                            "object": name,
                            "slice": p.slice,
                            "row": row,
                            "pixels": count,
                            "provenance": "native",
                            "kind": "reading" if unconfirmed else "resolved",
                            "code": str(p.codes["meniscus"]),
                        }
                    )
            # a rule that read a plane it was pointed to and named nothing: a reading with its code
            for quantity, rule, name in (
                (DARK, "meniscus", "meniscus"),
                (DARK, "mcl", "mcl"),
                (BRIGHT, "cartilage", "cartilage"),
                (LIGAMENT, "pcl", "pcl"),
                (FLUID, "acl", "acl"),
            ):
                code = str(p.codes[rule])
                resolved = any(
                    np.any(stack_objects[row] == OBJECT_CODES[w])
                    for w in wanted
                    if JOINT_RULE[w] == rule
                )
                if (
                    quantity in p.asked
                    and code != "identified"
                    and code not in JOINT_GATES
                    and not resolved
                ):
                    here.append(
                        observe(
                            name,
                            "native",
                            "reading",
                            own,
                            (p.slice,),
                            code,
                            None,
                            0.0,
                            "a3_joint_plane_objects",
                            f"the plane was pointed to by the {quantity} quantity and read in full; the existing rule names nothing here",
                            artifact,
                            row,
                        )
                    )
            # what the same operations find where the rule's gate refuses the plane: readings only
            for key, code in (
                ("horns", HORNS),
                ("cartilage_reading", CARTILAGE_CANDIDATES),
            ):
                if p.codes.get(key) != code:
                    continue
                for name in (
                    (
                        "meniscus"
                        if p.compartment in (None, "meniscus")
                        else f"{p.compartment}_meniscus",
                    )
                    if key == "horns"
                    else ("femoral_cartilage", "tibial_cartilage")
                ):
                    count = int(
                        np.count_nonzero(stack_reading[row] == OBJECT_CODES[name])
                    )
                    if not count:
                        continue
                    here.append(
                        observe(
                            name,
                            "native",
                            "reading",
                            own,
                            (p.slice,),
                            code,
                            count,
                            0.0,
                            "a3_joint_plane_reading",
                            "meniscal horns on a sagittal plane in the compartment its place toward the left of the notch names (`a3_joint_plane_horn_end`: 1 the front end of the joint, 2 the back): the existing menisci description with the plane's own in-plane axis, whose rule is gated to side-to-side planes, so a candidate and never a name; the other planes of the compartment are unknown, not absent"
                            if key == "horns"
                            else "the cartilage rule's operation on a sagittal plane, whose rule is gated to side-to-side planes: a candidate layer, never a name",
                            artifact,
                            row,
                            OBJECT_CODES[name],
                        )
                    )
            # laid: the plane's parts onto the twin's slice of the same place
            if t is None:
                continue
            present = [
                name
                for name in wanted
                if np.any(stack_objects[row] == OBJECT_CODES[name])
                and name not in ("pcl", "acl")
                and confirmed_at is not None
                and p.slice in confirmed_at
            ]
            if t.code != "read" or t.objects is None or t.slice is None:
                for name in present:
                    missing.append(
                        Unresolved(
                            name,
                            "laid",
                            None if partner is None else partner.record["series_uid"],
                            None if partner is None else tuple(partner.record["view"]),
                            t.code,
                        )
                    )
                continue
            if partner is None or at is None:
                continue
            for name in present:
                count = int(np.count_nonzero(t.objects == OBJECT_CODES[name]))
                if count:
                    said[at][0].append(
                        observe(
                            name,
                            "laid",
                            "resolved",
                            partner,
                            (t.slice,),
                            "laid_from_its_partner",
                            count,
                            t.off_mm,
                            f"{prefix}_objects",
                            f"the part named on native slice {p.slice} laid by the pair's match of places; places the twin never saw are left out",
                            twin_artifact,
                            twin_row,
                            OBJECT_CODES[name],
                        )
                    )
                else:
                    said[at][1].append(
                        Unresolved(
                            name,
                            "laid",
                            partner.record["series_uid"],
                            tuple(partner.record["view"]),
                            "nothing_of_the_part_lands_on_the_twin",
                        )
                    )
            twin_row += 1
        # what no plane named is unknown, each part naming why, never absent
        for name in wanted:
            if name not in got:
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        "|".join(
                            sorted(reason[name] or {"no_plane_pointed_to_read_it"})
                        ),
                    )
                )
        # projected: each part's largest section onto every other series' nearest slice
        skip = {uid} | (
            {partner.record["series_uid"]} if partner is not None else set()
        )
        for name in wanted:
            if not sections[name]:
                continue
            z, region, frame, support, source_row = max(
                sections[name], key=lambda s: int(np.count_nonzero(s[1]))
            )
            physical = frame.to_patient(np.argwhere(region).astype(float))
            for other in measured:
                other_uid = other.record["series_uid"]
                if other_uid in skip:
                    continue
                other_view = tuple(other.record["view"])
                target = bone_target(physical, other)
                if isinstance(target, str):
                    said[where[id(other)]][1].append(
                        Unresolved(name, "projected", other_uid, other_view, target)
                    )
                    continue
                nearest, place, distance, count = target
                said[where[id(other)]][0].append(
                    observe(
                        name,
                        "projected",
                        "target",
                        other,
                        (nearest,),
                        place,
                        count,
                        distance,
                        support,
                        f"a location target projected from {name} on slice {z} of the series it was named in: where a native question may be asked (the coronal body of a meniscus onto a sagittal series: where its horns are), not a boundary seen on this slice",
                        artifact,
                        source_row,
                        OBJECT_CODES[name] if support == "a1_objects" else None,
                    )
                )
        for planned in read.record["pointed_planes"]:
            # what the recess family reads: a plane's menisci are names only where the bones are
            planned["bones_identified_at_this_place"] = (
                None
                if confirmed_at is None
                else bool(planned["middle"] or planned["slice"] in confirmed_at)
            )
        own.record["joint"] = {
            **read.record,
            "twin_arrays_prefix": prefix if partner is not None else None,
            "sided_menisci": sided_menisci(own, read, bodies, sided),
            "existing_slices": [],
        }
    for m, (here, missing) in zip(measured, said, strict=True):
        if here or missing:
            keep_observations(m, here, missing)


def joint_existing(
    measured: list[Measured],
    found: dict[str, list[tuple[dict, dict[str, np.ndarray]]]],
    study_uid: str,
) -> None:
    """The ACL's and the LCL's own slices as observations of the series they lie in, beside the
    planes `name_the_joint` pointed to: the middle slice's outer neighbour (the ACL) and the coronal
    slice through the fibula's attachment (the LCL) stay valid observations, and the extra planes add
    to them, never replace them. Each is the part's own rule's naming on its slice (resolved where it
    named it itself, laid where its partner did), the artifact the main run saved it in; the record's
    `joint.existing_slices` lists them. Called once the parts are found, so the observations are
    appended after those `name_the_joint` made, earlier rows untouched."""
    by_uid = {m.record["series_uid"]: m for m in measured}
    for part, records in found.items():
        for record, arrays in records:
            own = by_uid.get(record["series_uid"])
            if own is None:
                continue
            code = record["assignments"]["codes"].get(part)
            mask = arrays["a1_objects"] == OBJECT_CODES[part]
            if code not in NAMED or not mask.any():
                continue
            native = code == "identified"
            keep_observations(
                own,
                [
                    observe(
                        part,
                        "native" if native else "laid",
                        "resolved",
                        own,
                        (int(record["slice_index"]),),
                        str(code),
                        int(np.count_nonzero(mask)),
                        0.0 if native else None,
                        "a1_objects",
                        "the part's own slice, its existing rule's naming there (the main run's record): the section on this slice, not the whole part",
                        str(artifact_of(study_uid, record)),
                        None,
                        OBJECT_CODES[part],
                    )
                ],
                [],
            )
            if isinstance(own.record.get("joint"), dict):
                own.record["joint"].setdefault("existing_slices", []).append(
                    {
                        "part": part,
                        "slice": int(record["slice_index"]),
                        "code": str(code),
                        "pixels": int(np.count_nonzero(mask)),
                    }
                )


# -- THE RECESSES: the anterior recess and its lining, the joint fluid, the side recesses' capsule and
# the patellar retinacula ---------------------------------------------------------------------------
# What points here is a squint tile whose MAXIMUM can hold fluid (four times the bones' marrow), read
# only inside the compartment the earlier families located (`knee.collapse.recess`); the existing
# definitions (`anterior_synovial_recess`, `joint_fluid`, `capsule_at_side_recesses`,
# `retinacular_walls`) run only on the planes it points to, on lens readings the earlier families
# already made wherever they read the plane.
RECESS_PARTS = {
    "anterior": (
        ("anterior_synovial_recess", "recess"),
        ("synovium", "lining"),
        ("joint_fluid", "fluid"),
    ),
    "side": (("joint_capsule", "capsule"), ("joint_fluid", "fluid")),
    "retinacula": ((RETINACULA[0], "medial_wall"), (RETINACULA[1], "lateral_wall")),
}
# Why a slice's corridor was not read, by the code kept per slice (`a3_recess_slice_reason`): 0 is a
# slice whose corridor was read (or none was asked for), the rest are named unknowns, never absence.
RECESS_REASONS = (
    "read",
    "patella_measured_absent_there",
    "patella_support_unknown_there",
    "patella_corridor_not_read_there",
    "no_earlier_family_read_it",
    "both_menisci_not_named_there",
    "no_femur_there",
    "patella_not_on_this_slab",
    "femur_not_on_this_slab",
    "interval_empty",
    "corridor_empty_on_this_slice",
)
RECESS_SOURCES = ("patella_plane_row", "joint_plane_row", "read_here", "retinacula_on")
RECESS_NOTES = {
    "anterior_synovial_recess": "the existing recess rule (the largest whole white body behind the patella, in front of the femur and above the patella's lower end) on this plane: the section here, fluid in the named compartment, not the whole synovial compartment",
    "synovium": "the fat-facing half of that body's boundary, sampled on the cavity side: it localizes the lining and measures no membrane thickness; kept apart from the cavity",
    "joint_fluid": "white as fluid (four times the bones' marrow) outside every part named but the joint, in the pieces touching the joint or within 2 mm of a bone: the section here",
    "joint_capsule": "the dark wall outside a side recess, beside it and over its height, on this coronal plane: where the rule reads low signal next to the recess, not the capsule's envelope; a neighbour's band bounds the search, it does not establish the wall",
    RETINACULA[
        0
    ]: "the whole tied minimum band outboard of the selected recess on this axial plane (darker than the recess beside it): the wall's section here, neither its thickness nor its course",
    RETINACULA[
        1
    ]: "the whole tied minimum band outboard of the selected recess on this axial plane (darker than the recess beside it): the wall's section here, neither its thickness nor its course",
}


def plane_places(frame: PlaneFrame, shape: tuple[int, int]) -> np.ndarray:
    """Every pixel's place in the scanner's millimetres, (R, C, 3)."""
    rows, cols = np.indices(shape)
    return frame.to_patient(
        np.column_stack((rows.ravel(), cols.ravel())).astype(float)
    ).reshape(*shape, 3)


@dataclass(frozen=True)
class RecessPlane:
    """One plane the fluid pointer asked for, as the existing definitions read it: its `slice`, whether
    it is the series' `middle` slice (the bootstrap's own naming, not read again), the `kind` of
    compartment (`RECESS_PARTS`), the `code` ("read", "bootstrap", `UNREADABLE_GEOMETRY` or the
    retinacula rule's refusal), what each part's rule said (`codes`, by the part's name), where its
    parts came from (`source`: `RECESS_SOURCES`, and `source_row` the row of the earlier family's
    stack it reused, -1 where none), the part `masks` on the plane's pixels (the white, the cavity, the
    lining, the fluid, the capsule, the retinacula's recess, strip and wall), small readings `values`
    (the wall's per-section minima, the interval), the naming `objects` and the lens's `labels` and
    `available` where this stage read them itself (None where the earlier family's are kept), and
    what pointed here (`asked`)."""

    slice: int
    middle: bool
    kind: str
    code: str
    codes: dict[str, str]
    source: str
    source_row: int
    masks: dict[str, np.ndarray]
    values: dict[str, np.ndarray]
    objects: np.ndarray | None
    labels: np.ndarray | None
    available: np.ndarray | None
    asked: tuple[str, ...]


def recess_blank(
    z: int,
    kind: str,
    code: str,
    asked: tuple[str, ...],
    middle: bool = False,
    codes: dict[str, str] | None = None,
) -> RecessPlane:
    """A plane the stage could not read, or the bootstrap's own: no masks, the code says why."""
    return RecessPlane(
        z, middle, kind, code, codes or {}, "", -1, {}, {}, None, None, None, asked
    )


def recess_anterior_plane(
    own: Measured,
    z: int,
    leg: Leg,
    keys: tuple[str, str],
    patella_rows: dict[int, int],
    asked: tuple[str, ...],
) -> RecessPlane:
    """The anterior recess, its lining and the joint's fluid on ONE pointed sagittal plane of a
    fat-suppressed fluid-sensitive series, by the existing rules: the plane's naming is the patella
    family's own row where it read this plane (`a3_patella_plane_objects`, its lens handed on), else
    `patella_plane` makes it here (the lens made once, counted for this stage); the white is
    `white_as_fluid`, the recess and its fat-facing lining `anterior_synovial_recess`, the fluid the
    plane's own `joint_fluid`. Nothing here is a new definition."""
    series = own.series
    uid = series.row.series_uid
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return recess_blank(z, "anterior", UNREADABLE_GEOMETRY, asked)
    plane = np.asarray(series.volume[z])
    labels = available = None
    row = patella_rows.get(z, -1)
    if row >= 0:
        reads("patella_plane", ("objects",), "recess")
        objects = np.asarray(own.arrays["a3_patella_plane_objects"][row])
        source = RECESS_SOURCES[0]
    else:
        got = patella_plane(own, z, leg.femur_lps, leg.tibia_lps, keys, None, "recess")
        if got.objects is None:
            return recess_blank(z, "anterior", UNREADABLE_GEOMETRY, asked)
        objects, labels, available = got.objects, got.labels, got.available
        source = RECESS_SOURCES[2]
    measures = measures_of(uid, z, plane, frame)
    femur = objects == OBJECT_CODES["femur"]
    tibia = objects == OBJECT_CODES["tibia"]
    has_patella = bool((objects == OBJECT_CODES["patella"]).any())
    none = np.zeros(plane.shape, dtype=bool)
    white = white_as_fluid(plane, objects, measures)
    recess = lining = none
    if has_patella and femur.any() and white is not None:
        recess, lining = anterior_synovial_recess(
            white, objects, frame.basis_lps, measures
        )
    fluid = objects == OBJECT_CODES["joint_fluid"]
    recess_code = synovium_code(
        True, True, has_patella, bool(femur.any()), bool(recess.any())
    )
    codes = {
        "anterior_synovial_recess": recess_code,
        "synovium": recess_code
        if lining.any() or recess_code != "identified"
        else "abstain_no_fat_facing_surface",
        "joint_fluid": fluid_code(
            True, bool(femur.any() and tibia.any()), bool(fluid.any())
        ),
    }
    handed("recess_plane", ("masks",))
    return RecessPlane(
        z,
        False,
        "anterior",
        "read",
        codes,
        source,
        row,
        {
            "white": none if white is None else white,
            "recess": recess,
            "lining": lining,
            "fluid": fluid,
        },
        {},
        None if row >= 0 else handed_on(objects),
        labels,
        available,
        asked,
    )


def recess_side_plane(
    own: Measured,
    z: int,
    objects: np.ndarray,
    row: int,
    asked: tuple[str, ...],
) -> RecessPlane:
    """The side recesses' capsule and the joint's fluid on ONE pointed coronal plane of a
    fat-suppressed fluid-sensitive series the joint family already read (`objects`, its naming, the
    lens handed on): the white is `white_as_fluid`, the wall `capsule_at_side_recesses` (the largest
    recess outboard of each meniscus, the dark wall outside it) and the fluid
    `fluid_in_the_recesses`, by the existing rules."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return recess_blank(z, "side", UNREADABLE_GEOMETRY, asked)
    plane = np.asarray(series.volume[z])
    _, lens, _ = lens_of(
        series, z, plane, frame, float(record["background_split"]), "recess"
    )
    field = field_of(series, z, plane, frame, lens)
    reads("interiors", ("dark", "available"), "recess")
    reads("field", ("leg",), "recess")
    reads("joint_plane", ("objects",), "recess")
    measures = measures_of(uid, z, plane, frame)
    spacing = np.asarray(frame.spacing_rc)
    femur = objects == OBJECT_CODES["femur"]
    tibia = objects == OBJECT_CODES["tibia"]
    menisci = all(
        (objects == OBJECT_CODES[name]).any()
        for name in ("medial_meniscus", "lateral_meniscus")
    )
    none = np.zeros(plane.shape, dtype=bool)
    white = white_as_fluid(plane, objects, measures)
    capsule = fluid = none
    boundary: dict[str, np.ndarray] = {}
    if white is not None and femur.any() and menisci:
        boundary = capsule_at_side_recesses(
            lens.dark, white, objects, frame.basis_lps, spacing, measures
        )
        capsule = boundary["capsule"]
        handed(
            "coronal_lining",
            tuple(
                "side_edge" if name == "lining" else name
                for name in boundary
                if name != "capsule"
            ),
        )
    if white is not None:
        fluid = fluid_in_the_recesses(
            white, objects, field.leg, margin_of(uid, z, plane), spacing, measures
        )
    codes = {
        "joint_capsule": capsule_code(
            True, True, bool(femur.any()), menisci, bool(capsule.any())
        ),
        "joint_fluid": fluid_code(
            True, bool(femur.any() and tibia.any()), bool(fluid.any())
        ),
    }
    handed("recess_plane", ("masks",))
    return RecessPlane(
        z,
        False,
        "side",
        "read",
        codes,
        RECESS_SOURCES[1],
        row,
        {
            "white": none if white is None else white,
            "capsule": capsule,
            "fluid": fluid,
            **{
                f"side_{name}": value
                for name, value in boundary.items()
                if name != "capsule" and value.ndim == 2
            },
        },
        {f"side_{name}": value for name, value in boundary.items() if value.ndim != 2},
        None,
        None,
        None,
        asked,
    )


def recess_axial_plane(
    own: Measured,
    z: int,
    leg: Leg,
    thick: list[float],
    knee: str,
    asked: tuple[str, ...],
) -> RecessPlane:
    """Both patellar retinacula on ONE axial plane, by the existing rule on its own plane
    (`retinacula_on`: the lens made once per slice, the carried patella and femur on it, the white,
    the recess either side of the patella, the outboard minimum band). Its refusal is the plane's
    code, and what it read of the white and the carried places stays with it."""
    got = retinacula_on(own, leg, z, thick, knee, "recess")
    if isinstance(got, str):
        return recess_blank(z, "retinacula", got, asked)
    record, arrays, _ = got
    names = {"positive_inner": RETINACULA[0], "negative_inner": RETINACULA[1]}
    masks = {
        "white": arrays["a2_retinacula_white"],
        "patella": arrays["a2_retinacula_carried_patella"],
        "femur": arrays["a2_retinacula_carried_femur"],
        "interval": arrays["a2_retinacula_posterior_interval"],
    }
    values: dict[str, np.ndarray] = {
        "interval_bounds_mm": arrays["a2_retinacula_posterior_interval_bounds_mm"],
        "femur_peak_depth_mm": arrays["a2_retinacula_femur_peak_depth_mm"],
    }
    for side, name in names.items():
        wall = "medial_wall" if name == RETINACULA[0] else "lateral_wall"
        stem = wall.removesuffix("_wall")
        masks[f"{stem}_recess"] = arrays[f"a2_retinacula_{side}_selected_recess"]
        masks[f"{stem}_strip"] = arrays[f"a2_retinacula_{side}_strip"]
        masks[wall] = arrays[f"a2_{name}"]
        masks[f"{stem}_lining"] = arrays[f"a2_retinacula_{side}_lining"]
        for key in ("row_minimum", "adjacent_white_median", "row_status"):
            values[f"{stem}_{key}"] = arrays[f"a2_retinacula_{side}_{key}"]
    codes = {name: str(record["assignments"]["codes"][name]) for name in names.values()}
    handed("recess_plane", ("masks",))
    return RecessPlane(
        z,
        False,
        "retinacula",
        "read",
        codes,
        RECESS_SOURCES[3],
        -1,
        masks,
        values,
        None,
        arrays["b1_labels"],
        arrays["b1_available"],
        asked,
    )


@dataclass(frozen=True)
class RecessTwin:
    """What the other sequence's slice through one pointed plane holds of the plane's parts: the
    twin's `slice` (None where it has none), the `code` ("read", or why not: an unknown, never an
    absence), the part masks laid onto the twin's own pixels (`masks`) and the distance of their
    places from the twin's plane (`off_mm`). No lens is read on the twin."""

    slice: int | None
    code: str
    masks: dict[str, np.ndarray] | None
    off_mm: float | None


def recess_twin(
    own: Measured, twin: Measured | None, plane: RecessPlane, parts: tuple[str, ...]
) -> RecessTwin:
    """The named parts' masks of a pointed plane (`parts`: mask names) laid onto the other sequence's
    slice through the same place, by the scanner's millimetres (never equal indices: `slice_through`)
    and the pair's one match of places (`matched`); the places the twin never saw hold nothing laid
    on them. Every failure is a code."""
    if twin is None:
        return RecessTwin(None, "none_of_the_other_sequence", None, None)
    other = twin.series
    thick, why = slab_thicknesses(other)
    if why is not None:
        return RecessTwin(None, why, None, None)
    frame = plane_frame(own.series, plane.slice)
    if isinstance(frame, str):
        return RecessTwin(None, frame, None, None)
    origins = np.asarray([np.asarray(p, dtype=float) for p in other.geometry.position])
    index = slice_through(frame.origin_lps, origins, twin.frame.normal(), thick)
    if index is None:
        return RecessTwin(None, "twin_has_no_slice_at_this_place", None, None)
    twin_frame = plane_frame(other, index)
    if isinstance(twin_frame, str):
        return RecessTwin(index, twin_frame, None, None)
    uid, twin_uid = own.series.row.series_uid, other.row.series_uid
    plane_there = np.asarray(other.volume[index])
    forward = matched(
        other,
        {"series_uid": twin_uid, "slice_index": index},
        twin_frame,
        plane_there.shape,
        {"series_uid": uid, "slice_index": plane.slice},
        frame,
        np.asarray(own.series.volume[plane.slice]),
    )
    if isinstance(forward, str):
        return RecessTwin(index, forward, None, None)
    reads("recess_plane", ("masks",), "recess_twin")
    seen = finite_of(other)[index]
    laid = {
        name: (laid_by(plane.masks[name].astype(np.int16), forward) == 1) & seen
        for name in parts
        if name in plane.masks
    }
    points = [
        frame.to_patient(np.argwhere(plane.masks[name]).astype(float))
        for name in parts
        if name in plane.masks and plane.masks[name].any()
    ]
    places = np.concatenate(points) if points else np.empty((0, 3))
    off = (
        float(abs((places.mean(axis=0) - twin_frame.origin_lps) @ twin_frame.normal()))
        if len(places)
        else None
    )
    return RecessTwin(index, "read", laid, off)


@dataclass(frozen=True)
class RecessRead:
    """The recess family in one series, as `read_recess` read it: the `kind` of compartment, the
    `profile` of the fluid pointer through depth, the `planes` it pointed to (the middle slice's
    bootstrap among them where it was), the twin's laying beside each plane but the middle one
    (`twins`), how it came out (`outcome`), the record's description (`record`, plain data) and the
    arrays it keeps on the series (`arrays`)."""

    kind: str
    profile: JointProfile
    planes: tuple[RecessPlane, ...]
    twins: tuple[RecessTwin | None, ...]
    outcome: str
    record: dict
    arrays: dict[str, np.ndarray]


def patella_sections_lps(own: Measured) -> list[np.ndarray]:
    """The places of every section of the patella the patella family named on this series: the
    middle slice's own naming and each pointed plane that identified it, each in the scanner's
    millimetres (one array per section). Empty when none was named."""
    sections: list[np.ndarray] = []
    codes = own.record["assignments"]["codes"]
    middle = own.arrays["a1_objects"] == OBJECT_CODES["patella"]
    if codes.get("patella") in NAMED and middle.any():
        sections.append(own.frame.to_patient(np.argwhere(middle).astype(float)))
    rows = [p for p in own.record["patella"]["pointed_planes"] if not p["middle"]]
    stack = own.arrays.get("a3_patella_plane_objects")
    for row, p in enumerate(rows):
        frame = plane_frame(own.series, int(p["slice"]))
        if p["code"] != "identified" or stack is None or isinstance(frame, str):
            continue
        mask = stack[row] == OBJECT_CODES["patella"]
        if mask.any():
            sections.append(frame.to_patient(np.argwhere(mask).astype(float)))
    return sections


def recess_corridor(
    own: Measured,
    kind: str,
    leg: Leg,
    patella_centre: np.ndarray | None,
    why: np.ndarray,
) -> tuple[Callable[[int, PlaneFrame, tuple[int, int]], np.ndarray], dict] | str:
    """The compartment the fluid pointer is read in, by the relation the existing definition states
    for it, from parts the earlier families located: `own_reach` for `joint_profile` (slice, frame,
    shape -> the pixels where it can lie there) and the landmarks it was read by; or why the
    compartment is not located here (a code, never an absence). `why` receives, for each slice no
    corridor was read on, the index into `RECESS_REASONS`."""
    reason = {name: i for i, name in enumerate(RECESS_REASONS)}
    if kind == "anterior":
        info = own.record.get("patella")
        status = own.arrays.get("a3_patella_profile_status")
        if not isinstance(info, dict) or "pointed_planes" not in info or status is None:
            return "abstain_patella_not_profiled"
        sections = patella_sections_lps(own)
        if not sections:
            return "abstain_no_patella_section_named"
        femur = leg.femur_lps[np.isfinite(leg.femur_lps).all(axis=1)]
        if not len(femur):
            return "abstain_no_femur_carried"
        back = float(min(np.median(s[:, 1]) for s in sections))
        low = float(min(s[:, 2].min() for s in sections))
        femur_back = float(np.median(femur[:, 1]))
        marks = FIBULA_POINTER_STATUS

        def anterior(z: int, frame: PlaneFrame, shape: tuple[int, int]) -> np.ndarray:
            held = int(status[z])
            if held in (marks["body"], marks["cut"]):
                return anterior_pocket(
                    plane_places(frame, shape), back, femur_back, low
                )
            why[z] = reason[
                "patella_measured_absent_there"
                if held == marks["none"]
                else "patella_support_unknown_there"
                if held == marks["unreadable"]
                else "patella_corridor_not_read_there"
            ]
            return np.zeros(shape, dtype=bool)

        return anterior, {
            "patella_back_y_mm": back,
            "patella_lowest_z_mm": low,
            "femur_back_y_mm": femur_back,
            "patella_sections": len(sections),
            "frame": "the scanner's LPS millimetres: y toward the back, z toward the head",
        }
    if kind == "side":
        stack = own.arrays.get("a3_joint_plane_objects")
        joint = own.record.get("joint")
        if (
            stack is None
            or not isinstance(joint, dict)
            or "pointed_planes" not in joint
        ):
            return "abstain_joint_not_read"
        both = ("medial_meniscus", "lateral_meniscus")
        located: dict[int, np.ndarray] = {}
        middle = own.arrays["a1_objects"]
        if all((middle == OBJECT_CODES[n]).any() for n in both):
            located[int(own.record["slice_index"])] = middle
        rows = [p for p in joint["pointed_planes"] if not p["middle"]]
        read_rows = {int(p["slice"]) for p in rows}
        for row, p in enumerate(rows):
            if (
                p["code"] == "read"
                and p.get("bones_identified_at_this_place") is True
                and all((stack[row] == OBJECT_CODES[n]).any() for n in both)
            ):
                located[int(p["slice"])] = np.asarray(stack[row])
        if not located:
            return "abstain_no_plane_names_both_menisci"

        def side(z: int, frame: PlaneFrame, shape: tuple[int, int]) -> np.ndarray:
            objects = located.get(z)
            if objects is None:
                why[z] = reason[
                    "both_menisci_not_named_there"
                    if z in read_rows
                    else "no_earlier_family_read_it"
                ]
                return np.zeros(shape, dtype=bool)
            places = plane_places(frame, shape)
            first = objects == OBJECT_CODES[both[0]]
            second = objects == OBJECT_CODES[both[1]]
            femur = objects == OBJECT_CODES["femur"]
            if not femur.any():
                why[z] = reason["no_femur_there"]
                return np.zeros(shape, dtype=bool)
            held = gutter_landmarks(
                places[first][:, 0],
                places[second][:, 0],
                places[first][:, 2],
                places[second][:, 2],
            )
            span = places[femur][:, 0]
            if held is None or not np.isfinite(span).any():
                why[z] = reason["corridor_empty_on_this_slice"]
                return np.zeros(shape, dtype=bool)
            return side_gutters(
                places,
                held[0],
                held[1],
                (float(np.nanmin(span)), float(np.nanmax(span))),
            )

        return side, {
            "slices_naming_both_menisci": sorted(located),
            "slices_the_joint_family_read": sorted(read_rows),
            "frame": "the scanner's LPS millimetres: x toward the left, z toward the head",
        }
    chosen = retinacula_z(own, leg, patella_centre)
    if isinstance(chosen, str):
        return chosen
    _, thick, _ = chosen
    patella_points = np.asarray(leg.patella_lps, dtype=np.float64)
    femur_points = np.asarray(leg.femur_lps, dtype=np.float64)

    def axial(z: int, frame: PlaneFrame, shape: tuple[int, int]) -> np.ndarray:
        half = thick[z] / 2.0
        mine = patella_points[
            np.abs((patella_points - frame.origin_lps) @ frame.normal()) <= half
        ]
        theirs = femur_points[
            np.abs((femur_points - frame.origin_lps) @ frame.normal()) <= half
        ]
        mine = mine[np.isfinite(mine).all(axis=1)]
        theirs = theirs[np.isfinite(theirs).all(axis=1)]
        if not len(mine):
            why[z] = reason["patella_not_on_this_slab"]
            return np.zeros(shape, dtype=bool)
        if not len(theirs):
            why[z] = reason["femur_not_on_this_slab"]
            return np.zeros(shape, dtype=bool)
        reach = patellofemoral_interval(
            plane_places(frame, shape),
            float(mine[:, 1].mean()),
            float(np.median(theirs[:, 1])),
            (float(theirs[:, 0].min()), float(theirs[:, 0].max())),
        )
        if not reach.any():
            why[z] = reason["interval_empty"]
        return reach

    return axial, {
        "frame": "the scanner's LPS millimetres: x toward the left, y toward the back",
        "bootstrap_slice": int(chosen[0]),
    }


def recess_says(plane: RecessPlane, middle_codes: dict[str, str]) -> str:
    """What the existing rules said of one plane read for the fluid: "confirmed" (some part was
    named), "rejected" (read, nothing named) or "not_read" (the plane is a bootstrap's own, whose
    stage is not run again here and whose naming is read from its codes where it has them)."""
    codes = plane.codes if not plane.middle else middle_codes
    if plane.middle and not codes:
        return "not_read"
    if any(code == "identified" for code in codes.values()):
        return "confirmed"
    return "not_read" if plane.middle else "rejected"


def stacked(
    rows: list[dict[str, np.ndarray]], key: str, shape: tuple[int, ...], dtype: Any
) -> np.ndarray:
    """One named reading of each row of a stack, (n, ...): a row without it is zero (NaN for a
    float), never a copy of another's."""
    blank = (
        np.full(shape, np.nan)
        if np.dtype(dtype).kind == "f"
        else np.zeros(shape, dtype)
    )
    return (
        np.stack([np.asarray(r.get(key, blank), dtype=dtype) for r in rows])
        if rows
        else np.empty((0, *shape), dtype=dtype)
    )


def recess_arrays(
    own: Measured,
    kind: str,
    profile: JointProfile,
    planes: list[RecessPlane],
    pointed: list[int],
    runs: list[tuple[int, int]],
    origins: np.ndarray,
    offsets: np.ndarray,
    sound: bool,
    thick: np.ndarray,
    why: np.ndarray,
) -> dict[str, np.ndarray]:
    """What the recess family keeps in the series' own middle arrays, named `a3_recess_*`: the fluid
    pointer's status and area through depth, the tiles that could hold the level, its runs with their
    ends and envelopes, the corridor's pixels and tiles, the finer readings at their own resolution
    (ragged, nothing padded), why each slice's corridor was not read, the pointed slices' places along
    the stack's normal; and, one row per pointed plane but the bootstrap's own, the plane's slice, the
    stack it reused or `read_here` (`a3_recess_plane_source`, `_source_row`), every part mask and small
    reading as a stack, and the naming and lens this stage read itself (`_objects`, `_labels`,
    `_available`, with the rows `_objects_row`, `_lens_row`; -1 where the earlier family's are kept)."""
    shape = np.shape(own.arrays["acquired_plane"])
    rows_in = [p for p in planes if not p.middle]
    pointed_origin = origins[pointed] if sound and pointed else np.empty((0, 3))
    at = profile.level[FLUID]
    _, ends, spans = describe_runs(runs, profile.status[FLUID], offsets, thick, sound)
    arrays: dict[str, np.ndarray] = {
        "a3_recess_profile_status": profile.status[FLUID],
        "a3_recess_profile_area_mm2": profile.area_mm2[FLUID],
        "a3_recess_profile_could_tiles": profile.could[FLUID],
        "a3_recess_profile_level": np.asarray(
            (np.nan, np.nan) if at is None else at, dtype=np.float64
        ),
        "a3_recess_corridor_px": profile.corridor_px,
        "a3_recess_corridor_tiles": profile.corridor,
        "a3_recess_seen_blocks": profile.seen_blocks,
        "a3_recess_unseen_blocks": profile.unseen_blocks,
        "a3_recess_profile_window_rc": profile.window_rc,
        "a3_recess_profile_block_mm": profile.cell_mm,
        "a3_recess_profile_block_px": profile.block_px,
        "a3_recess_pointer_runs": np.asarray(runs, dtype=np.int32).reshape(-1, 2),
        "a3_recess_pointer_run_ends": ends.astype(np.int32),
        "a3_recess_pointer_run_envelope_mm": spans,
        "a3_recess_slice_reason": why,
        "a3_recess_depth_offsets_mm": offsets,
        "a3_recess_slice_thickness_mm": thick,
        "a3_recess_pointed_slices": np.asarray(pointed, dtype=np.int32),
        "a3_recess_pointed_origin_lps": pointed_origin,
        "a3_recess_pointed_position_mm": offsets[pointed]
        if sound and pointed
        else np.empty(0),
        "a3_recess_source_normal_lps": own.frame.normal(),
    }
    for name, value in pack_fine_readings(profile.fine).items():
        if name != "tibia_reference":
            arrays[
                f"a3_recess_fine_{'reach_blocks' if name == 'pointer_body' else name}"
            ] = value
    arrays["a3_recess_plane_slices"] = np.asarray(
        [p.slice for p in rows_in], dtype=np.int32
    )
    arrays["a3_recess_plane_source"] = np.asarray(
        [RECESS_SOURCES.index(p.source) if p.source else -1 for p in rows_in],
        dtype=np.int8,
    )
    arrays["a3_recess_plane_source_row"] = np.asarray(
        [p.source_row for p in rows_in], dtype=np.int32
    )
    mask_names = sorted({n for p in rows_in for n in p.masks})
    for n in mask_names:
        arrays[f"a3_recess_plane_{n}"] = stacked(
            [p.masks for p in rows_in], n, shape, bool
        )
    value_names = sorted({n for p in rows_in for n in p.values})
    for n in value_names:
        first = next(p.values[n] for p in rows_in if n in p.values)
        arrays[f"a3_recess_plane_value_{n}"] = stacked(
            [p.values for p in rows_in],
            n,
            np.shape(first),
            np.asarray(first).dtype,
        )
    objects_rows = [p for p in rows_in if p.objects is not None]
    lens_rows = [p for p in rows_in if p.labels is not None]
    arrays["a3_recess_plane_objects_row"] = np.asarray(
        [objects_rows.index(p) if p in objects_rows else -1 for p in rows_in],
        dtype=np.int32,
    )
    arrays["a3_recess_plane_lens_row"] = np.asarray(
        [lens_rows.index(p) if p in lens_rows else -1 for p in rows_in], dtype=np.int32
    )
    arrays["a3_recess_plane_objects"] = (
        np.stack([np.asarray(p.objects) for p in objects_rows])
        if objects_rows
        else np.empty((0, *shape), dtype=np.int8)
    )
    arrays["a3_recess_plane_labels"] = (
        np.stack([np.asarray(p.labels) for p in lens_rows])
        if lens_rows
        else np.empty((0, *shape), dtype=np.int32)
    )
    arrays["a3_recess_plane_available"] = (
        np.stack([np.asarray(p.available, dtype=bool) for p in lens_rows])
        if lens_rows
        else np.empty((0, *shape), dtype=bool)
    )
    return arrays


def recess_map_neighbourhood(
    own: Measured, mapping: MapContext, kind: str
) -> tuple[np.ndarray | None, dict]:
    """The map's expected slice and native location for this recess family.

    A missing or unusable target leaves the established whole-depth search in place. The map only
    selects where the first profile is read; `joint_guide_spatial_hits` checks that the existing
    fluid support reaches its in-plane boxes before a native plane is tried.
    """
    targets = {
        "anterior": ("anterior_synovial_recess", "synovium", "joint_fluid"),
        "side": ("joint_capsule", "joint_fluid"),
        "retinacula": RETINACULA,
    }[kind]
    depth = len(own.series.volume) if own.series.volume is not None else 0
    window = np.zeros(depth, dtype=bool)
    entries: list[dict] = []
    unusable: dict[str, str] = {}
    for target in targets:
        guide = mapping.guide(target, own)
        entries.append(
            {
                "object": target,
                "status": guide.status,
                "slices": list(guide.slices),
                "rcs": [
                    {"slice": int(z), "rc": [float(rc[0]), float(rc[1])]}
                    for z, rc in guide.rcs
                ],
                "placements": list(guide.placements),
                "anchors": list(guide.anchors),
                "half_px": None if guide.half_px is None else list(guide.half_px),
            }
        )
        placements = [
            p
            for p in guide.placements
            if p.get("status") == "ok"
            and p.get("slice") is not None
            and p.get("rc") is not None
        ]
        if guide.status != "guided" or not guide.slices or not placements:
            unusable[target] = guide.status
            continue
        for z in guide.slices:
            if 0 <= int(z) < depth:
                window[int(z)] = True
    if unusable or not window.any():
        return None, {
            "code": "full_depth_required_for_unusable_anatomical_guide",
            "targets": entries,
            "unguided_targets": unusable,
        }
    index = int(own.record["slice_index"])
    if 0 <= index < depth:
        window[index] = True
    return window, {
        "code": "anatomical_map_guides",
        "targets": entries,
        "slices_in": int(window.sum()),
    }


def recess_walk_boundary_peaks(profile, visited: np.ndarray, profile_on):
    """Walk unread neighbours while a recess run's maximum touches the visited edge."""
    seen = visited.copy()
    walked = np.zeros_like(seen)
    depth = len(seen)
    while not seen.all():
        runs = positive_runs(profile.area_mm2[FLUID])
        maxima = run_maxima(profile.area_mm2[FLUID], runs)
        more = np.zeros(depth, dtype=bool)
        for (a, b), peaks in zip(runs, maxima, strict=True):
            if a in peaks and a > 0 and not seen[a - 1]:
                more[a - 1] = True
            if b - 1 in peaks and b < depth and not seen[b]:
                more[b] = True
        if not more.any():
            break
        profile = merge_joint_profiles(profile, profile_on(more), more)
        seen |= more
        walked |= more
    return profile, seen, walked


def recess_complete_unvisited_profile(profile, visited: np.ndarray, profile_on):
    """Complete the recess profile once, reading only slices not already visited."""
    rest = ~visited
    if not rest.any():
        return profile, visited, False
    profile = merge_joint_profiles(profile, profile_on(rest), rest)
    return profile, np.ones_like(visited), True


def recess_guided_points(
    profile: JointProfile, guidance: dict, own: Measured | None = None
) -> tuple[dict[int, list[str]], dict[str, dict[int, bool]]]:
    """Point every tied best plane in a fluid run whose existing support meets a map box."""
    spatial = joint_guide_spatial_hits(
        profile,
        {"recess": FLUID},
        {"map_questions": {"recess": guidance}},
        own=own,
    )
    hit_slices = {int(z) for z, hit in spatial.get("recess", {}).items() if hit}
    runs = positive_runs(profile.area_mm2[FLUID])
    maxima = run_maxima(profile.area_mm2[FLUID], runs)
    confirm = confirmations(runs, maxima, profile.status[FLUID], (JOINT_UNREADABLE,))
    asked: dict[int, list[str]] = {}
    for (a, b), peaks in zip(runs, maxima, strict=True):
        if not any(a <= z < b for z in hit_slices):
            continue
        for z in {int(z) for z in peaks} | {int(z) for z in confirm if z in (a - 1, b)}:
            asked.setdefault(z, []).append("fluid")
    return asked, spatial


def read_recess(
    own: Measured,
    partner: Measured | None,
    leg: Leg,
    patella_centre: np.ndarray | None,
    feed: dict[str, int | None],
    mapping: MapContext | None = None,
) -> RecessRead | str:
    """Read the recess family's fluid profile and existing native rules.

    With a usable anatomical map, the profile first visits its expected slices and the existing
    fluid support is checked against the map's in-plane boxes. Every tied best plane in a supported
    run is read by the existing recess rule. If those rules do not identify a mapped candidate, the
    remaining slices are profiled once and all pointed runs are read. Without a usable map, the
    whole-depth profile and its existing pointed-plane semantics apply directly. `feed` remains an
    additional axial plane selected by the patella family's extent-based centre.
    """
    series, record = own.series, own.record
    uid = series.row.series_uid
    reads("series", ("row",), "recess")
    if not (
        int(series.row.fat_suppression) == 1 and int(series.row.fluid_sensitive) == 1
    ):
        return "abstain_fluid_not_bright_on_this_sequence"
    sides, front, along = own.assignment.in_plane
    kind = (
        "anterior"
        if front and along
        else "side"
        if sides and along
        else "retinacula"
        if not along
        else ""
    )
    if not kind:
        return "abstain_plane_not_read_by_a_relation"
    reads("squint_stack", ("code",), "recess")
    if own.stack.code != "present":
        return f"squint_{own.stack.code}"
    if series.volume is None:
        return "no_stacked_volume"
    index = record["slice_index"]
    objects = own.arrays["a1_objects"]
    femur_mask = objects == OBJECT_CODES["femur"]
    tibia_mask = objects == OBJECT_CODES["tibia"]
    measures = measures_of(uid, index, own.arrays["acquired_plane"], own.frame)
    if kind == "retinacula":
        if not len(leg.femur_lps):
            return "no_carried_places"
        thick_here, why_not = slab_thicknesses(series)
        if why_not is not None:
            return why_not
        femur_on, _ = leg_on(
            leg, series, index, own.frame, femur_mask.shape, thick_here[index]
        )
        anchored = femur_on & own.arrays["b1_available"]
        femur_light = (
            float(measures.light(anchored)) if anchored.any() else float("nan")
        )
        bones_light = femur_light
    else:
        assigned = record["assignments"]
        if (
            assigned["femur"] is None
            or assigned["tibia"] is None
            or not (femur_mask.any() and tibia_mask.any())
        ):
            return "bones_not_named_on_the_middle_slice"
        femur_light = float(measures.light(femur_mask))
        bones_light = float(measures.light(femur_mask | tibia_mask))
    depth = len(series.volume)
    why = np.zeros(depth, dtype=np.int8)
    got = recess_corridor(own, kind, leg, patella_centre, why)
    if isinstance(got, str):
        return got
    own_reach, landmarks = got
    level = levels(float(record["background_split"]), femur_light, bones_light)
    map_detail: dict[str, Any]
    map_window, map_detail = (
        (None, {"code": "no_map_supplied"})
        if mapping is None
        else recess_map_neighbourhood(own, mapping, kind)
    )

    def profile_on(visit: np.ndarray | None):
        return joint_profile(
            series,
            own.stack,
            np.empty((0, 3)),
            np.empty((0, 3)),
            {FLUID: level[FLUID]},
            (FLUID,),
            own_reach,
            "recess",
            visit=visit,
        )

    profile = profile_on(map_window)
    reads("recess_profile", ("status", "area_mm2"), "recess")

    def pointers(current):
        current_runs = positive_runs(current.area_mm2[FLUID])
        current_maxima = run_maxima(current.area_mm2[FLUID], current_runs)
        current_confirm = confirmations(
            current_runs, current_maxima, current.status[FLUID], (JOINT_UNREADABLE,)
        )
        return current_runs, current_maxima, current_confirm

    def pointed_for(current, spatial: set[int] | None = None):
        current_runs, current_maxima, current_confirm = pointers(current)
        asked: dict[int, list[str]] = {}
        for (a, b), peaks in zip(current_runs, current_maxima, strict=True):
            if spatial is not None and not any(int(z) in spatial for z in peaks):
                continue
            for z in {int(z) for z in peaks} | {
                int(z) for z in current_confirm if z in (a - 1, b)
            }:
                asked.setdefault(z, []).append("fluid")
        return asked, current_runs, current_maxima, current_confirm

    bootstrap = index
    thick_values: list[float] = []
    knee = str(record["assignments"]["knee"])
    if kind == "retinacula":
        chosen = retinacula_z(own, leg, patella_centre)
        if isinstance(chosen, str):
            return chosen
        bootstrap, thick_values, knee = chosen
        reads("patella", ("retinacula_feed",), "recess")
    keys = (digest(leg.femur_lps), digest(leg.tibia_lps))
    patella_rows: dict[int, int] = {}
    side_rows: dict[int, int] = {}
    if kind == "anterior":
        for row, p in enumerate(
            p for p in record["patella"]["pointed_planes"] if not p["middle"]
        ):
            patella_rows[int(p["slice"])] = row
    if kind == "side":
        for row, p in enumerate(
            p for p in record["joint"]["pointed_planes"] if not p["middle"]
        ):
            side_rows[int(p["slice"])] = row
    parts = tuple(name for _, name in RECESS_PARTS[kind])

    def read_point(z: int, asked: tuple[str, ...]):
        if z == bootstrap:
            return recess_blank(z, kind, "bootstrap", asked, True), None
        if kind == "anterior":
            got_plane = recess_anterior_plane(own, z, leg, keys, patella_rows, asked)
        elif kind == "side":
            stack = own.arrays["a3_joint_plane_objects"]
            row = side_rows.get(z, -1)
            got_plane = (
                recess_side_plane(own, z, np.asarray(stack[row]), row, asked)
                if row >= 0
                else recess_blank(z, kind, "no_earlier_family_read_it", asked)
            )
        else:
            got_plane = recess_axial_plane(own, z, leg, thick_values, knee, asked)
        twin = (
            recess_twin(own, partner, got_plane, parts)
            if got_plane.code == "read" and kind != "retinacula"
            else None
        )
        return got_plane, twin

    plane_by_slice: dict[int, RecessPlane] = {}
    twin_by_slice: dict[int, RecessTwin | None] = {}
    guided_points: set[int] = set()
    search_hits: dict[str, dict[int, bool]] = {}
    guided_outcome = "unmapped_full_search"
    passes = 1
    visited = np.ones(depth, dtype=bool) if map_window is None else map_window.copy()
    if map_window is not None:
        profile, visited, walked = recess_walk_boundary_peaks(
            profile, visited, profile_on
        )
        if walked.any():
            ledger.record("recess.walked_slices", planes=int(walked.sum()))
    asked_by, runs, maxima, confirm = pointed_for(profile)
    if map_window is not None and mapping is not None:
        guidance = {"map_questions": {"recess": {"targets": map_detail["targets"]}}}
        reads("recess_profile", ("fine",), "recess_map_guidance")
        guided_by, search_hits = recess_guided_points(
            profile, guidance["map_questions"]["recess"], own=own
        )
        guided_points = set(guided_by)
        # The map points to a location; every tied best slice in a supported run is still read.
        for z in sorted(guided_points):
            asked = tuple(guided_by[z])
            plane, twin = read_point(z, asked)
            plane_by_slice[z], twin_by_slice[z] = plane, twin
        middle_codes = {
            name: str(record["assignments"]["codes"].get(name, ""))
            for name, _ in RECESS_PARTS[kind]
        }
        if kind == "retinacula":
            middle_codes = {}
        if guided_points and any(
            recess_says(plane_by_slice[z], middle_codes) == "confirmed"
            for z in guided_points
        ):
            guided_outcome = "guided_hit"
            asked_by = guided_by
        else:
            guided_outcome = "guided_miss_then_full_search"
            profile, visited, broadened = recess_complete_unvisited_profile(
                profile, visited, profile_on
            )
            if broadened:
                passes = 2
            else:
                guided_outcome = "guided_miss_profile_already_full"
            asked_by, runs, maxima, confirm = pointed_for(profile)
    elif mapping is not None:
        guided_outcome = "unusable_guide_full_search"

    if mapping is not None:
        for target in map_detail.get("targets", []):
            mapping.smap.note_use(
                target["object"],
                uid,
                guided_outcome,
                question="recess",
                anchors=target.get("anchors", []),
                candidate_slices=sorted(guided_points),
                full_depth=bool(visited.all()),
            )
        ledger.record(f"study_map.recess_guidance.{guided_outcome}", series=1)

    status = profile.status[FLUID]
    # A slice deliberately outside a successful map window remains unknown, not empty.
    empty = RECESS_REASONS.index("corridor_empty_on_this_slice")
    why[(status == JOINT_NOT_READ) & visited & (why == 0)] = empty
    ledger.record("recess.unread_slices", planes=int(np.count_nonzero(why)))

    if kind == "retinacula":
        wider = feed.get(uid)
        if wider is not None and wider != bootstrap:
            asked_by.setdefault(int(wider), []).append("patella_extent_centre")
    pointed = sorted(asked_by)
    ledger.record("recess.pointed_planes", planes=len(pointed))
    for z in pointed:
        if z in plane_by_slice:
            continue
        plane, twin = read_point(z, tuple(asked_by[z]))
        plane_by_slice[z], twin_by_slice[z] = plane, twin
    planes = [plane_by_slice[z] for z in sorted(plane_by_slice)]
    twins = [
        twin_by_slice[z] for z in sorted(plane_by_slice) if not plane_by_slice[z].middle
    ]
    origins, thick, offsets, sound = series_depth(series, own.frame, index)
    middle_codes = {
        name: str(record["assignments"]["codes"].get(name, ""))
        for name, _ in RECESS_PARTS[kind]
    }
    if kind == "retinacula":
        middle_codes = {}
    read_by = {p.slice: p for p in planes}
    described, _, _ = describe_runs(runs, status, offsets, thick, sound)
    for i, ((a, b), peaks) in enumerate(zip(runs, maxima, strict=True)):
        here = sorted(
            {int(z) for z in peaks} | {int(z) for z in confirm if z in (a - 1, b)}
        )
        said = [
            recess_says(read_by[z], middle_codes) if z in read_by else "not_read"
            for z in here
        ]
        described[i]["planes_read_for_it"] = [z for z in here if z in read_by]
        described[i]["native_rule"] = (
            "confirmed_by_the_native_rule"
            if "confirmed" in said
            else "rejected_by_the_native_rule"
            if "rejected" in said
            else "not_read_natively"
        )
    rows_in = [p for p in planes if not p.middle]
    twin_of = {id(p): t for p, t in zip(rows_in, twins, strict=True)}
    pointed_rows = []
    for p in planes:
        row_record: dict[str, Any] = {
            "slice": p.slice,
            "middle": p.middle,
            "pointed_by": list(p.asked),
            "code": p.code,
            "codes": dict(p.codes),
            "source": p.source or None,
            "source_row": p.source_row if p.source_row >= 0 else None,
            "position_mm": finite_or_none(offsets[p.slice]) if sound else None,
            "parts_pixels": {
                name: int(np.count_nonzero(p.masks[name]))
                for name in (*parts, "white")
                if name in p.masks and np.count_nonzero(p.masks[name])
            },
        }
        if not p.middle:
            twin = twin_of[id(p)]
            row_record["twin"] = (
                None
                if twin is None
                else {"slice": twin.slice, "code": twin.code, "off_mm": twin.off_mm}
            )
        pointed_rows.append(row_record)
    outcome = (
        "read"
        if pointed
        else "unreadable"
        if (status == JOINT_UNREADABLE).any()
        else "no_support_found"
    )
    ambiguities = [
        "a_tile_maximum_points_it_never_names_a_pocket_and_the_blocks_that_read_the_level_are_support_not_a_name",
        "the_corridor_is_the_relation_the_existing_definition_states_read_on_the_carried_places_an_upper_bound_never_a_section",
        "a_neighbours_band_bounds_the_search_for_a_thin_wall_it_does_not_establish_the_wall_throughout_the_band",
    ]
    if any(profile.unseen_blocks > 0):
        ambiguities.append("blocks_never_seen_make_an_area_a_lower_bound")
    if (status == JOINT_UNREADABLE).any():
        ambiguities.append("slices_the_profile_could_not_read_are_unknown_not_empty")
    if np.count_nonzero(why):
        ambiguities.append(
            "slices_whose_corridor_was_not_read_are_unknown_not_empty_see_slice_reason"
        )
    if not sound:
        ambiguities.append("slice_geometry_unsound_so_no_physical_depth")
    names = {value: key for key, value in FIBULA_POINTER_STATUS.items()}
    record_part = {
        "kind": kind,
        "outcome": outcome,
        "points_at": "tiles whose maximum can hold fluid (four times the bones' marrow), then 2 mm blocks that read it, inside the compartment the earlier families located",
        "level": None
        if level[FLUID] is None
        else [None if np.isinf(v) else float(v) for v in level[FLUID]],
        "block_mm": float(LIGAMENT_SMOOTH_MM),
        "status": {
            names[int(c)]: int(np.count_nonzero(status == c)) for c in np.unique(status)
        },
        "reasons_not_read": {
            RECESS_REASONS[int(c)]: int(np.count_nonzero(why == c))
            for c in np.unique(why)
            if c
        },
        "reason_codes": list(RECESS_REASONS),
        "source_codes": list(RECESS_SOURCES),
        "corridor": landmarks,
        "pointer_runs": described,
        "pointer_representatives": [[int(z) for z in peaks] for peaks in maxima],
        "confirmed_slices": [int(z) for z in confirm],
        "unknown_slices": [int(z) for z in np.flatnonzero(status == JOINT_UNREADABLE)],
        "pointed_planes": pointed_rows,
        "ambiguities": ambiguities,
        "status_codes": dict(FIBULA_POINTER_STATUS),
        "search": {
            "map_guidance": map_detail,
            "outcome": guided_outcome,
            "guided_support": {
                question: {str(z): hit for z, hit in slices.items()}
                for question, slices in search_hits.items()
            },
            "guided_candidate_slices": sorted(guided_points),
            "passes": passes,
            "broadened_to_full_depth": passes > 1,
            "slices_visited": int(visited.sum()),
            "slices_unvisited": [int(z) for z in np.flatnonzero(~visited)],
        },
    }
    if kind == "retinacula":
        record_part["bootstrap_slice"] = int(bootstrap)
        record_part["patella_extent_centre_slice"] = feed.get(uid)
    arrays = recess_arrays(
        own, kind, profile, planes, pointed, runs, origins, offsets, sound, thick, why
    )
    handed("recess", ("pointed", "planes", "twins"))
    return RecessRead(
        kind, profile, tuple(planes), tuple(twins), outcome, record_part, arrays
    )


def recess_twin_arrays(
    twin: Measured,
    planes: list[RecessPlane],
    twins: list[RecessTwin | None],
    prefix: str,
    parts: tuple[str, ...],
) -> dict[str, np.ndarray]:
    """What the twin's slices through the pointed planes hold of the planes' parts, as stacks on the
    twin's own pixels, named `<prefix>_*`, one row per plane whose twin was read: the plane's slice
    (`from_slices`), the twin's (`slices`) and each part's mask. (The prefix names the series that
    asked, so two sequences asking one twin never overwrite each other.)"""
    shape = np.shape(twin.arrays["acquired_plane"])
    rows = [
        (p, t)
        for p, t in zip(planes, twins, strict=True)
        if t is not None and t.code == "read"
    ]
    found: dict[str, np.ndarray] = {
        f"{prefix}_from_slices": np.asarray([p.slice for p, _ in rows], dtype=np.int32),
        f"{prefix}_slices": np.asarray(
            [-1 if t.slice is None else t.slice for _, t in rows], dtype=np.int32
        ),
    }
    for name in parts:
        found[f"{prefix}_{name}"] = stack_of(
            [
                t.masks[name]
                if t.masks is not None and name in t.masks
                else np.zeros(shape, bool)
                for _, t in rows
            ],
            shape,
            bool,
        )
    return found


def retinacula_centre(
    measured: list[Measured], patella_centre: np.ndarray | None
) -> np.ndarray | None:
    """The place the axial retinacula slice is chosen through: the centre of every patella section
    the patella family named across planes (`retinacula_feed`, kept on the record that made it),
    else the first identification's centre. The retinacula's own rules still decide on that slice."""
    for m in measured:
        info = m.record.get("patella")
        for entry in (
            (info.get("retinacula_feed") or []) if isinstance(info, dict) else []
        ):
            reads("patella", ("retinacula_feed",), "patellar_retinacula")
            return np.asarray(entry["centre_of_every_section_lps"], dtype=float)
    return patella_centre


def recess_feed(measured: list[Measured]) -> dict[str, int | None]:
    """The axial slice the patella family's extent-based centre selects, for each axial series it
    named (`record["patella"]["retinacula_feed"]`, the first series that holds one): read by the
    recess family as an additional plane, never in place of the retinacula stage's own slice."""
    found: dict[str, int | None] = {}
    for m in measured:
        info = m.record.get("patella")
        entries = info.get("retinacula_feed") if isinstance(info, dict) else None
        for entry in entries or []:
            for axial in entry.get("axial", []):
                if "slice_from_every_section" in axial:
                    found.setdefault(
                        axial["series_uid"], axial["slice_from_every_section"]
                    )
        if found:
            break
    return found


def name_the_recess(
    measured: list[Measured],
    partners: list[Measured | None],
    leg: Leg | None,
    patella_centre: np.ndarray | None,
    study_uid: str,
    mapping: MapContext | None = None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """The anterior recess and its lining, the joint's fluid, the side recesses' capsule and the
    patellar retinacula through the stacks (`read_recess`) of every fat-suppressed fluid-sensitive
    series, kept in the series' own middle records and arrays (saved by the caller) beside the
    observations the earlier families made.

    Native: the middle slice's own naming of each part (the bootstrap), each part on each pointed
    plane where its existing rule names it (resolved, one row of the `a3_recess_plane_*` stacks), and a
    rule that read a pointed plane and named nothing (a reading with its code, never an absence), and
    the pointer's support through depth (a reading: no boundary, no name). Laid: each pointed plane's
    parts onto the other sequence's slice of the same place (`recess_twin`, `<prefix>_<part>` of the
    twin). Projected: each part's largest section onto the slice of every other series nearest it (a
    target for a native question, never a boundary). The cavity, its lining, the fluid, the capsule
    and each retinaculum are separate objects with separate decisions. What could not be said is an
    `Unresolved` with its code: a part no pointed plane named, a slice whose compartment no earlier
    family located, a series whose sequence does not show fluid, is unknown and never absent. The
    profile and every plane are kept; the one thing read downstream is the patella family's
    extent-based centre (`retinacula_feed`), which adds an axial plane and replaces nothing. The
    observations are returned per series, in the order of `measured`, for `keep_recess` to append
    once the ACL's and the LCL's own slices are, so every earlier row stays an unchanged prefix."""
    carried = leg if leg is not None else leg_of(measured)
    feed = recess_feed(measured)
    results = [
        read_recess(own, partners[i], carried, patella_centre, feed, mapping)
        for i, own in enumerate(measured)
    ]
    where = {id(m): i for i, m in enumerate(measured)}
    said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    for i, own in enumerate(measured):
        read = results[i]
        uid, view = own.record["series_uid"], tuple(own.record["view"])
        here, missing = said[i]
        artifact = str(artifact_of(study_uid, own.record))
        if isinstance(read, str):
            own.record["recess"] = {"code": read}
            missing.append(Unresolved("recess", "native", uid, view, read))
            continue
        partner = partners[i]
        at = None if partner is None else where[id(partner)]
        index = own.record["slice_index"]
        codes = own.record["assignments"]["codes"]
        kind = read.kind
        parts = RECESS_PARTS[kind]
        mask_names = tuple(mask for _, mask in parts)
        rows_in = [p for p in read.planes if not p.middle]
        twins = list(read.twins)
        own.arrays.update(read.arrays)
        prefix = "a3_recess_twin"
        if partner is not None and kind != "retinacula":
            prefix = source_prefix(prefix, partner.arrays, uid)
            partner.arrays.update(
                recess_twin_arrays(partner, rows_in, twins, prefix, mask_names)
            )
        twin_artifact = (
            str(artifact_of(study_uid, partner.record)) if partner is not None else ""
        )
        got: set[str] = set()
        reason: dict[str, set[str]] = {name: set() for name, _ in parts}
        sections: dict[
            str, list[tuple[int, np.ndarray, PlaneFrame, str, int | None]]
        ] = {name: [] for name, _ in parts}
        # the series' bootstrap: the middle slice's own naming (the retinacula's own slice is read
        # by its stage, after this one, and joins the observations then: `recess_existing`)
        if kind != "retinacula":
            middle = own.arrays["a1_objects"]
            for name, _ in parts:
                code = codes.get(name)
                reason[name].add(str(code))
                held = (
                    middle == OBJECT_CODES[name]
                    if name == "joint_fluid"
                    else own.arrays.get(f"a2_{name}")
                )
                if code not in NAMED or held is None or not np.any(held):
                    continue
                got.add(name)
                native = code == "identified"
                here.append(
                    observe(
                        name,
                        "native" if native else "laid",
                        "resolved",
                        own,
                        (index,),
                        str(code),
                        int(np.count_nonzero(held)),
                        0.0 if native else None,
                        "a1_objects" if name == "joint_fluid" else f"a2_{name}",
                        "the middle slice's own naming (the bootstrap): the section on this slice, not the whole part",
                        artifact,
                        None,
                        OBJECT_CODES[name] if name == "joint_fluid" else None,
                    )
                )
                sections[name].append(
                    (
                        index,
                        np.asarray(held, dtype=bool),
                        own.frame,
                        "a1_objects" if name == "joint_fluid" else f"a2_{name}",
                        None,
                    )
                )
        twin_row = 0
        for row, (p, t) in enumerate(zip(rows_in, twins, strict=True)):
            if p.code != "read":
                missing.append(Unresolved("recess", "native", uid, view, p.code))
                continue
            frame = plane_frame(own.series, p.slice)
            for name, mask_name in parts:
                code = p.codes.get(name, "")
                reason[name].add(str(code))
                mask = p.masks.get(mask_name)
                count = 0 if mask is None else int(np.count_nonzero(mask))
                if code == "identified" and count:
                    got.add(name)
                    here.append(
                        observe(
                            name,
                            "native",
                            "resolved",
                            own,
                            (p.slice,),
                            "identified",
                            count,
                            0.0,
                            f"a3_recess_plane_{mask_name}",
                            RECESS_NOTES[name],
                            artifact,
                            row,
                        )
                    )
                    if not isinstance(frame, str) and mask is not None:
                        sections[name].append(
                            (p.slice, mask, frame, f"a3_recess_plane_{mask_name}", row)
                        )
                else:
                    here.append(
                        observe(
                            name,
                            "native",
                            "reading",
                            own,
                            (p.slice,),
                            str(code),
                            None,
                            0.0,
                            f"a3_recess_plane_{mask_name}",
                            "the plane was pointed to by the fluid pointer and read in full by the existing rule; it names nothing here (never an absence of the part elsewhere)",
                            artifact,
                            row,
                        )
                    )
            if t is None:
                continue
            if t.code != "read" or t.masks is None or t.slice is None:
                for name, _ in parts:
                    if p.codes.get(name) == "identified":
                        missing.append(
                            Unresolved(
                                name,
                                "laid",
                                None
                                if partner is None
                                else partner.record["series_uid"],
                                None
                                if partner is None
                                else tuple(partner.record["view"]),
                                t.code,
                            )
                        )
                continue
            if partner is None or at is None:
                continue
            for name, mask_name in parts:
                if p.codes.get(name) != "identified":
                    continue
                count = int(np.count_nonzero(t.masks.get(mask_name, 0)))
                if count:
                    said[at][0].append(
                        observe(
                            name,
                            "laid",
                            "resolved",
                            partner,
                            (t.slice,),
                            "laid_from_its_partner",
                            count,
                            t.off_mm,
                            f"{prefix}_{mask_name}",
                            f"the part named on native slice {p.slice} laid by the pair's match of places; places the twin never saw are left out",
                            twin_artifact,
                            twin_row,
                        )
                    )
                else:
                    said[at][1].append(
                        Unresolved(
                            name,
                            "laid",
                            partner.record["series_uid"],
                            tuple(partner.record["view"]),
                            "nothing_of_the_part_lands_on_the_twin",
                        )
                    )
            twin_row += 1
        # the pointer's own support through depth: a reading with no name and no boundary
        positive = tuple(
            int(z)
            for z in np.flatnonzero(read.arrays["a3_recess_profile_area_mm2"] > 0)
        )
        if positive:
            here.append(
                observe(
                    "joint_fluid",
                    "native",
                    "reading",
                    own,
                    positive,
                    "pointer_fluid_support",
                    None,
                    None,
                    "a3_recess_profile_area_mm2",
                    "2 mm blocks at the fluid level inside the compartment the earlier families located, area through depth: support that points, no boundary and no name; the planes it asked are read by the existing rules",
                    artifact,
                )
            )
        for name, _ in parts:
            if name not in got:
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        "|".join(
                            sorted(reason[name] or {"no_plane_pointed_to_read_it"})
                        ),
                    )
                )
        skip = {uid} | (
            {partner.record["series_uid"]} if partner is not None else set()
        )
        for name, _ in parts:
            usable = [s for s in sections[name] if s[1].any()]
            if not usable:
                continue
            z, region, frame, support, source_row = max(
                usable, key=lambda s: int(np.count_nonzero(s[1]))
            )
            physical = frame.to_patient(np.argwhere(region).astype(float))
            # Retain the physical target already made for cross-view observations.
            if (
                name == "anterior_synovial_recess"
                and kind == "anterior"
                and any(
                    o.object == name
                    and o.provenance == "native"
                    and o.kind == "resolved"
                    and o.slices == (z,)
                    and o.support == support
                    and o.row == source_row
                    for o in here
                )
            ):
                own.arrays["a4_anterior_recess_source_lps"] = physical
                own.record["anterior_recess_source"] = {
                    "series_uid": uid,
                    "slice": z,
                    "support": support,
                    "row": source_row,
                    "artifact": artifact,
                    "count": len(physical),
                    "area_mm2": float(len(physical) * np.prod(frame.spacing_rc)),
                    "provenance": "native",
                }
                handed("anterior_recess_source", ("lps",))
            if (
                name == "joint_capsule"
                and kind == "side"
                and str(view[0]).casefold() == "coronal"
            ):
                native_source = next(
                    (
                        observation
                        for observation in here
                        if observation.object == name
                        and observation.provenance == "native"
                        and observation.kind == "resolved"
                        and observation.slices == (z,)
                        and observation.support == support
                        and observation.row == source_row
                    ),
                    None,
                )
                if native_source is not None:
                    own.arrays["a4_capsule_source_lps"] = physical
                    own.record["capsule_source"] = {
                        "series_uid": uid,
                        "slice": z,
                        "support": support,
                        "row": source_row,
                        "artifact": artifact,
                        "count": len(physical),
                        "area_mm2": float(len(physical) * np.prod(frame.spacing_rc)),
                        "provenance": "native",
                    }
                    handed("capsule_source", ("lps",))
            for other in measured:
                other_uid = other.record["series_uid"]
                if other_uid in skip:
                    continue
                other_view = tuple(other.record["view"])
                target = bone_target(physical, other)
                if isinstance(target, str):
                    said[where[id(other)]][1].append(
                        Unresolved(name, "projected", other_uid, other_view, target)
                    )
                    continue
                nearest, place, distance, count = target
                said[where[id(other)]][0].append(
                    observe(
                        name,
                        "projected",
                        "target",
                        other,
                        (nearest,),
                        place,
                        count,
                        distance,
                        support,
                        f"a location target projected from {name} on slice {z} of the series it was named in: where a native question about the compartment may be asked, not a boundary seen on this slice",
                        artifact,
                        source_row,
                        OBJECT_CODES[name] if support == "a1_objects" else None,
                    )
                )
        own.record["recess"] = {
            **read.record,
            "twin_arrays_prefix": prefix
            if partner is not None and kind != "retinacula"
            else None,
            "existing_slices": [],
        }
    for own, partner in zip(measured, partners, strict=True):
        # the twin's bootstrap, where the pair laid the recess and the capsule onto it
        sibling = None if partner is None else results[where[id(partner)]]
        if sibling is None or isinstance(sibling, str):
            continue
        for name, _ in RECESS_PARTS[sibling.kind]:
            code = own.record["assignments"]["codes"].get(name)
            held = (
                own.arrays["a1_objects"] == OBJECT_CODES[name]
                if name == "joint_fluid"
                else own.arrays.get(f"a2_{name}")
            )
            if code in NAMED and held is not None and np.any(held):
                said[where[id(own)]][0].append(
                    observe(
                        name,
                        "laid",
                        "resolved",
                        own,
                        (int(own.record["slice_index"]),),
                        str(code),
                        int(np.count_nonzero(held)),
                        None,
                        "a1_objects" if name == "joint_fluid" else f"a2_{name}",
                        "the middle slice's part, laid from the other sequence's own naming by the pair's match (the bootstrap)",
                        str(artifact_of(study_uid, own.record)),
                        None,
                        OBJECT_CODES[name] if name == "joint_fluid" else None,
                    )
                )
    return said


def coronal_anterior_recess(
    own: Measured,
    points: np.ndarray | None,
    source: dict | None,
    targets: list[Observation],
    study_uid: str,
    mapping: MapContext | None,
) -> tuple[list[Observation], list[Unresolved]]:
    """Resolve a native coronal cavity body where a native sagittal recess points.

    Projected source samples locate the question; they never supply the coronal
    boundary. Reuse the coronal recess profile's fluid level (or its same shared
    marrow reading). Sample only projected coordinates through depth, starting
    with map slices and the existing physical target. Extend a supported peak
    at a visited boundary; on a miss, read the remaining samples once. Label
    whole native white bodies only at tied positive-run maxima. The same source
    and actual acquisition frames remain explicit, including off-plane distance.
    """
    name, product = "anterior_synovial_recess", "coronal_anterior_recess"
    here: list[Observation] = []
    missing: list[Unresolved] = []
    if str(own.record["view"][0]).casefold() != "coronal":
        return here, missing
    detail: dict[str, Any] = {"source": source}
    own.record[product] = detail

    def refuse(code: str):
        detail["code"] = code
        missing.append(
            Unresolved(
                name,
                "native",
                own.record["series_uid"],
                tuple(own.record["view"]),
                f"coronal_anterior_recess:{code}",
            )
        )
        return here, missing

    series = own.series
    if not (
        int(series.row.fat_suppression) == 1 and int(series.row.fluid_sensitive) == 1
    ):
        return refuse("fluid_not_bright_on_this_sequence")
    if points is None or source is None:
        return refuse(
            "tied_native_sagittal_recess_sources"
            if source is not None and source.get("status") == "tied"
            else "no_native_sagittal_recess_source"
        )
    points = np.asarray(points, dtype=float)
    if (
        points.ndim != 2
        or points.shape[1] != 3
        or not len(points)
        or not np.isfinite(points).all()
    ):
        return refuse("invalid_native_source_points")
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return refuse("no_stacked_volume")
    addressed = [
        o
        for o in targets
        if o.object == name
        and o.provenance == "projected"
        and o.kind == "target"
        and o.artifact == source.get("artifact")
        and o.support == source.get("support")
        and o.row == source.get("row")
        and o.series_uid == own.record["series_uid"]
    ]
    if not addressed or all(o.code == "beyond_the_scan" for o in addressed):
        return refuse("native_source_not_located_in_acquired_stack")
    depth, rows, cols = np.shape(volume)
    center_lps = points.mean(axis=0)
    recess_record = own.record.get("recess")
    level_record = (
        recess_record.get("level") if isinstance(recess_record, dict) else None
    )
    if level_record is not None and len(level_record) == 2:
        low = level_record[0]
        calibration = "existing_recess_profile"
    else:
        objects = own.arrays["a1_objects"]
        femur = objects == OBJECT_CODES["femur"]
        tibia = objects == OBJECT_CODES["tibia"]
        if not (femur.any() and tibia.any()):
            return refuse("no_native_marrow_reference")
        measures = measures_of(
            series.row.series_uid,
            own.record["slice_index"],
            own.arrays["acquired_plane"],
            own.frame,
        )
        light = measures.light(femur | tibia)
        low = FLUID_BRIGHTER * light
        calibration = "same_shared_combined_marrow"
    if low is None or not np.isfinite(low) or low <= 0:
        return refuse("unreadable_fluid_level")
    low = float(low)
    detail.update(level=low, calibration=calibration)
    reads("anterior_recess_source", ("lps",), product)
    guide = None if mapping is None else mapping.guide(name, own)
    placements = (
        []
        if guide is None
        else [
            p
            for p in guide.placements
            if p.get("status") == "ok" and p.get("point_lps") is not None
        ]
    )
    guided = (
        set()
        if guide is None or guide.status != "guided"
        else {int(z) for z in guide.slices if 0 <= int(z) < depth}
    )
    initial = guided | {
        int(z) for o in addressed for z in o.slices if 0 <= int(z) < depth
    }
    if not initial:
        return refuse("no_usable_starting_plane")
    visited = np.zeros(depth, dtype=bool)
    counts, map_counts = np.full(depth, np.nan), np.full(depth, np.nan)
    offsets_mm = np.full(depth, np.nan)
    status = np.zeros(depth, dtype=np.int8)
    samples: dict[
        int, tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]
    ] = {}
    reasons = (
        "not_visited",
        "frame_unavailable",
        "outside_image",
        "unavailable",
        "sampled",
        "sampled_partial",
    )
    finite = finite_of(series)
    uid = series.row.series_uid

    def sample(indices):
        for z in sorted({int(z) for z in indices}):
            if visited[z]:
                continue
            visited[z] = True
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                status[z] = 1
                continue
            rc = np.unique(np.rint(frame.to_native(points)).astype(np.int64), axis=0)
            inside = (
                (rc[:, 0] >= 0)
                & (rc[:, 0] < rows)
                & (rc[:, 1] >= 0)
                & (rc[:, 1] < cols)
            )
            rc = rc[inside]
            offsets_mm[z] = float((center_lps - frame.origin_lps) @ frame.normal())
            if not len(rc):
                status[z] = 2
                continue
            raw = np.asarray(volume[z])
            margin = margin_of(uid, z, raw)
            rr, cc = rc.T
            light = np.asarray(raw[rr, cc], dtype=float)
            valid = finite[z, rr, cc] & ~margin[rr, cc]
            white = valid & (light >= low)
            in_map = np.zeros(len(rc), dtype=bool)
            if guide is not None and z in guided:
                half = guide.half_px or (0.0, 0.0)
                for p in placements:
                    center = frame.to_native(np.asarray([p["point_lps"]], dtype=float))[
                        0
                    ]
                    in_map |= np.all(
                        np.abs(rc - center) <= np.asarray(half) + 0.5, axis=1
                    )
            samples[z] = (rc, light, valid, white, in_map)
            if not valid.any():
                status[z] = 3
                continue
            complete = bool(valid.all() and inside.all())
            status[z] = 4 if complete else 5
            if white.any() or complete:
                counts[z] = float(np.count_nonzero(white))
                map_counts[z] = float(np.count_nonzero(white & in_map))
        ledger.record(f"{product}.sampled_slices", planes=len(indices))

    def peaks(values):
        return {
            int(z) for run in run_maxima(values, positive_runs(values)) for z in run
        }

    def walk():
        while True:
            more: set[int] = set()
            runs = positive_runs(counts)
            for (a, b), maxima in zip(
                runs,
                run_maxima(counts, runs),
                strict=True,
            ):
                if a in maxima and a > 0 and not visited[a - 1]:
                    more.add(a - 1)
                if b - 1 in maxima and b < depth and not visited[b]:
                    more.add(b)
            if not more:
                break
            sample(more)

    native: dict[int, dict[str, np.ndarray]] = {}
    native_codes: dict[int, str] = {}
    artifact = str(artifact_of(study_uid, own.record))
    support = "a4_coronal_anterior_recess"

    def resolve(indices):
        for z in sorted(indices):
            if z in native or z not in samples:
                continue
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                continue
            raw = np.asarray(volume[z])
            available = finite[z] & ~margin_of(uid, z, raw)
            white = available & (raw >= low)
            target = np.zeros((rows, cols), dtype=bool)
            rc, _, valid, _, _ = samples[z]
            target[tuple(rc[valid].T)] = True
            mask, code, readings = white_body_at_location(white, target)
            native[z] = {
                "mask": mask,
                "white": white,
                "target": target,
                "available": available,
                **readings,
            }
            native_codes[z] = code
            ledger.record(f"{product}.native_body_readings", planes=1)

    sample(initial)
    walk()
    guided_peaks = peaks(map_counts) if guided else peaks(counts)
    resolve(guided_peaks)
    hit = any(native_codes[z] == "selected" for z in guided_peaks if z in native_codes)
    broadened = False
    if not hit:
        unread = {int(z) for z in np.flatnonzero(~visited)}
        broadened = bool(unread)
        sample(unread)
        resolve(peaks(counts))
    outcome = (
        "guided_hit"
        if hit and guided
        else "source_location_hit"
        if hit
        else "broadened_native_search"
    )
    if mapping is not None:
        mapping.smap.note_use(
            name,
            uid,
            outcome,
            question=product,
            anchors=[] if guide is None else list(guide.anchors),
            candidate_slices=sorted(native),
            full_depth=bool(visited.all()),
        )
    ordered = sorted(native)
    own.arrays["a4_coronal_anterior_source_lps"] = points
    own.arrays["a4_coronal_anterior_profile_count"] = counts
    own.arrays["a4_coronal_anterior_profile_map_count"] = map_counts
    own.arrays["a4_coronal_anterior_profile_status"] = status
    own.arrays["a4_coronal_anterior_source_offset_mm"] = offsets_mm
    own.arrays["a4_coronal_anterior_slices"] = np.asarray(ordered, dtype=np.int32)
    for key in ("mask", "white", "target", "available", "labels"):
        key_name = support if key == "mask" else f"a4_coronal_anterior_{key}"
        own.arrays[key_name] = stacked(
            [native[z] for z in ordered],
            key,
            (rows, cols),
            np.int32 if key == "labels" else bool,
        )
    # Ragged samples and component evidence retain exact rows without object arrays.
    sample_offsets, sample_slices = [0], sorted(samples)
    for z in sample_slices:
        sample_offsets.append(sample_offsets[-1] + len(samples[z][0]))
    own.arrays["a4_coronal_anterior_sample_slices"] = np.asarray(
        sample_slices, dtype=np.int32
    )
    own.arrays["a4_coronal_anterior_sample_offsets"] = np.asarray(
        sample_offsets, dtype=np.int64
    )
    for col, key, dtype in (
        (0, "rc", np.int64),
        (1, "light", float),
        (2, "valid", bool),
        (3, "white", bool),
        (4, "in_map", bool),
    ):
        chunks = [samples[z][col] for z in sample_slices]
        own.arrays[f"a4_coronal_anterior_sample_{key}"] = (
            np.concatenate(chunks)
            if chunks
            else np.empty((0, 2) if col == 0 else (0,), dtype=dtype)
        )
    plane_details = []
    for row, z in enumerate(ordered):
        values = native[z]
        count = int(np.count_nonzero(values["mask"]))
        code = (
            "identified"
            if native_codes[z] == "selected"
            else f"abstain_{native_codes[z]}"
        )
        # Each ragged component vector is indexed by the actual native slice.
        for key in ("sizes", "eligible_ids", "winner_ids"):
            own.arrays[f"a4_coronal_anterior_{key}_{z}"] = values[key]
        here.append(
            observe(
                name,
                "native",
                "resolved" if count else "reading",
                own,
                (z,),
                code,
                count,
                0.0,
                support,
                "Native connected white cavity body intersecting the projected sagittal recess location; "
                "projection only points, the coronal acquired signal supplies this section, not the whole envelope.",
                artifact,
                row,
            )
        )
        plane_details.append(
            {
                "slice": z,
                "row": row,
                "code": code,
                "count": count,
                "source_offset_mm": float(offsets_mm[z]),
            }
        )
    detail.update(
        code="identified"
        if any(native_codes[z] == "selected" for z in ordered)
        else "no_native_body_resolved",
        search=outcome,
        broadened=broadened,
        status_codes={v: i for i, v in enumerate(reasons)},
        visited_slices=[int(z) for z in np.flatnonzero(visited)],
        unvisited_slices=[int(z) for z in np.flatnonzero(~visited)],
        pointed_planes=plane_details,
        guide=None
        if guide is None
        else {
            "status": guide.status,
            "slices": list(guide.slices),
            "anchors": list(guide.anchors),
            "placements": list(guide.placements),
            "half_px": guide.half_px,
        },
    )
    handed(product, ("profile", "samples", "native_support", "component_context"))
    reads(product, ("profile",), "coronal_anterior_plane_choice")
    if here:
        reads(product, ("native_support",), "coronal_anterior_observations")
    if not any(native_codes[z] == "selected" for z in ordered):
        return refuse(
            "native_body_not_resolved"
            if ordered
            else "source_location_unreadable"
            if not np.isfinite(counts).any()
            else "no_white_support_at_source_location"
        )
    return here, missing


def name_coronal_anterior_recess(
    measured: list[Measured],
    said: list[tuple[list[Observation], list[Unresolved]]],
    study_uid: str,
    mapping: MapContext | None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """One native sagittal location source shared by the coronal acquisition questions."""
    sources = [
        (m.arrays["a4_anterior_recess_source_lps"], m.record["anterior_recess_source"])
        for m in measured
        if "a4_anterior_recess_source_lps" in m.arrays
        and "anterior_recess_source" in m.record
    ]
    if sources:
        largest = max(float(s["area_mm2"]) for _, s in sources)
        choices = [(p, s) for p, s in sources if float(s["area_mm2"]) == largest]
        points, source = (
            choices[0]
            if len(choices) == 1
            else (None, {"status": "tied", "candidates": [s for _, s in choices]})
        )
    else:
        points, source = None, None
    return [
        coronal_anterior_recess(own, points, source, here, study_uid, mapping)
        for own, (here, _) in zip(measured, said, strict=True)
    ]


def sagittal_capsule(
    own: Measured,
    points: np.ndarray | None,
    source: dict | None,
    targets: list[Observation],
    study_uid: str,
    mapping: MapContext | None,
) -> tuple[list[Observation], list[Unresolved]]:
    """Read a native sagittal outer capsule band where its coronal source points."""
    name, product = "joint_capsule", "sagittal_capsule"
    here: list[Observation] = []
    missing: list[Unresolved] = []
    if str(own.record["view"][0]).casefold() != "sagittal":
        return here, missing
    detail: dict[str, Any] = {"source": source}
    own.record[product] = detail

    def refuse(code: str):
        detail["code"] = code
        missing.append(
            Unresolved(
                name,
                "native",
                own.record["series_uid"],
                tuple(own.record["view"]),
                f"sagittal_capsule:{code}",
            )
        )
        return here, missing

    series = own.series
    uid = series.row.series_uid
    if not (
        int(series.row.fat_suppression) == 1 and int(series.row.fluid_sensitive) == 1
    ):
        return refuse("fluid_not_bright_on_this_sequence")
    if points is None or source is None:
        return refuse(
            "tied_native_coronal_capsule_sources"
            if source is not None and source.get("status") == "tied"
            else "no_native_coronal_capsule_source"
        )
    points = np.asarray(points, dtype=float)
    if (
        points.ndim != 2
        or points.shape[1] != 3
        or not len(points)
        or not np.isfinite(points).all()
    ):
        return refuse("invalid_native_source_points")
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return refuse("no_stacked_volume")
    addressed = [
        observation
        for observation in targets
        if observation.object == name
        and observation.provenance == "projected"
        and observation.kind == "target"
        and observation.artifact == source.get("artifact")
        and observation.support == source.get("support")
        and observation.row == source.get("row")
        and observation.series_uid == uid
    ]
    if not addressed or all(o.code == "beyond_the_scan" for o in addressed):
        return refuse("native_source_not_located_in_acquired_stack")

    depth, rows, cols = np.shape(volume)
    level_record = own.record.get("recess", {}).get("level")
    if level_record is not None and len(level_record) == 2:
        low = level_record[0]
        calibration = "existing_recess_profile"
    else:
        objects = own.arrays["a1_objects"]
        femur = objects == OBJECT_CODES["femur"]
        tibia = objects == OBJECT_CODES["tibia"]
        if not (femur.any() and tibia.any()):
            return refuse("no_native_marrow_reference")
        measures = measures_of(
            uid,
            own.record["slice_index"],
            own.arrays["acquired_plane"],
            own.frame,
        )
        combined_light = measures.light(femur | tibia)
        if combined_light is None or not np.isfinite(combined_light):
            return refuse("unreadable_fluid_level")
        low = FLUID_BRIGHTER * float(combined_light)
        calibration = "same_shared_combined_marrow"
    if low is None or not np.isfinite(low) or low <= 0:
        return refuse("unreadable_fluid_level")
    low = float(low)
    detail.update(
        level=low,
        calibration=calibration,
        source_location_allowance_mm=SHELL_MM,
    )
    reads("capsule_source", ("lps",), product)

    guide = None if mapping is None else mapping.guide(name, own)
    placements = (
        []
        if guide is None
        else [
            placement
            for placement in guide.placements
            if placement.get("status") == "ok"
            and placement.get("point_lps") is not None
        ]
    )
    guided = (
        set()
        if guide is None or guide.status != "guided"
        else {int(z) for z in guide.slices if 0 <= int(z) < depth}
    )
    initial = guided | {
        int(z)
        for observation in addressed
        for z in observation.slices
        if 0 <= int(z) < depth
    }
    if not initial:
        return refuse("no_usable_starting_plane")

    finite = finite_of(series)
    visited = np.zeros(depth, dtype=bool)
    counts = np.full(depth, np.nan)
    map_counts = np.full(depth, np.nan)
    offsets_mm = np.full(depth, np.nan)
    status = np.zeros(depth, dtype=np.int8)
    projection_finite = np.zeros(depth, dtype=bool)
    projection_inside = np.zeros(depth, dtype=bool)
    samples: dict[int, tuple[np.ndarray, ...]] = {}
    reasons = (
        "not_visited",
        "frame_unavailable",
        "source_centers_outside_image",
        "outside_image",
        "unavailable",
        "sampled",
        "sampled_partial",
    )

    def sample(indices):
        for z in sorted({int(value) for value in indices}):
            if visited[z]:
                continue
            visited[z] = True
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                status[z] = 1
                continue
            normal = np.asarray(frame.normal(), dtype=float)
            signed_offsets = (points - frame.origin_lps) @ normal
            offsets_mm[z] = float(np.mean(signed_offsets))
            projected = frame.to_native(points)
            finite_rc = np.isfinite(projected).all(axis=1)
            projection_finite[z] = bool(finite_rc.all())
            rounded = np.zeros(projected.shape, dtype=np.int64)
            rounded[finite_rc] = np.rint(projected[finite_rc]).astype(np.int64)
            inside = finite_rc & (rounded[:, 0] >= 0) & (rounded[:, 0] < rows)
            inside &= (rounded[:, 1] >= 0) & (rounded[:, 1] < cols)
            projection_inside[z] = bool(inside.all())
            if not inside.all():
                status[z] = 3
                continue
            center_rc, source_ids = np.unique(rounded, axis=0, return_index=True)
            spacing_rc = np.asarray(frame.spacing_rc, dtype=float)
            radius_rc = np.ceil(SHELL_MM / spacing_rc).astype(int)
            offsets = np.asarray(
                [
                    (dr, dc)
                    for dr in range(-radius_rc[0], radius_rc[0] + 1)
                    for dc in range(-radius_rc[1], radius_rc[1] + 1)
                    if (dr * spacing_rc[0]) ** 2 + (dc * spacing_rc[1]) ** 2
                    <= SHELL_MM**2
                ],
                dtype=np.int64,
            )
            neighborhood = (center_rc[:, None, :] + offsets[None, :, :]).reshape(-1, 2)
            neighborhood = neighborhood[
                (neighborhood[:, 0] >= 0)
                & (neighborhood[:, 0] < rows)
                & (neighborhood[:, 1] >= 0)
                & (neighborhood[:, 1] < cols)
            ]
            rc = np.unique(neighborhood, axis=0)
            nearest_center = np.argmin(
                np.sum((rc[:, None, :] - center_rc[None, :, :]) ** 2, axis=2),
                axis=1,
            )
            sample_source_ids = source_ids[nearest_center]
            raw = np.asarray(volume[z])
            margin = margin_of(uid, z, raw)
            rr, cc = rc.T
            light = np.asarray(raw[rr, cc], dtype=float)
            valid = finite[z, rr, cc] & ~margin[rr, cc]
            white = valid & (light >= low)
            in_map = np.zeros(len(rc), dtype=bool)
            if guide is not None and z in guided:
                half = guide.half_px or (0.0, 0.0)
                for placement in placements:
                    center = frame.to_native(
                        np.asarray([placement["point_lps"]], dtype=float)
                    )[0]
                    in_map |= np.all(
                        np.abs(rc - center) <= np.asarray(half) + 0.5, axis=1
                    )
            samples[z] = (
                rc,
                light,
                valid,
                white,
                in_map,
                signed_offsets[sample_source_ids],
                sample_source_ids,
                center_rc,
            )
            if not valid.any():
                status[z] = 4
                continue
            complete = bool(valid.all())
            status[z] = 5 if complete else 6
            if white.any() or complete:
                counts[z] = float(np.count_nonzero(white))
                map_counts[z] = float(np.count_nonzero(white & in_map))
        ledger.record(f"{product}.sampled_slices", planes=len(indices))

    def peaks(values):
        return {
            int(z) for run in run_maxima(values, positive_runs(values)) for z in run
        }

    def walk():
        while True:
            more: set[int] = set()
            runs = positive_runs(counts)
            for (a, b), maxima in zip(runs, run_maxima(counts, runs), strict=True):
                if a in maxima and a > 0 and not visited[a - 1]:
                    more.add(a - 1)
                if b - 1 in maxima and b < depth and not visited[b]:
                    more.add(b)
            if not more:
                break
            sample(more)

    native: dict[int, dict[str, Any]] = {}
    artifact = str(artifact_of(study_uid, own.record))
    support = "a4_sagittal_capsule_outer_wall"

    def resolve(indices):
        for z in sorted(indices):
            if z in native or z not in samples:
                continue
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                continue
            raw = np.asarray(volume[z])
            available = finite[z] & ~margin_of(uid, z, raw)
            white = available & (raw >= low)
            exact_target = np.zeros((rows, cols), dtype=bool)
            exact_target[tuple(samples[z][7].T)] = True
            target = np.zeros((rows, cols), dtype=bool)
            target[tuple(samples[z][0].T)] = True
            body, body_code, readings = white_body_at_location(white, target)
            basis = np.asarray(frame.basis_lps, dtype=float)
            section_axis = int(np.argmax(np.abs(basis[2, :])))
            wall: dict[str, np.ndarray] = {
                "strip": np.zeros((rows, cols), dtype=bool),
                "minimum_band": np.zeros((rows, cols), dtype=bool),
                "lining_edge": np.zeros((rows, cols), dtype=bool),
                "body_outer_edge_mm": np.full(
                    rows if section_axis == 0 else cols, np.nan
                ),
                "row_minimum": np.full(rows if section_axis == 0 else cols, np.nan),
                "adjacent_median": np.full(rows if section_axis == 0 else cols, np.nan),
                "status": np.full(
                    rows if section_axis == 0 else cols, -1, dtype=np.int8
                ),
                "tied_runs": np.zeros(
                    rows if section_axis == 0 else cols, dtype=np.int16
                ),
                "section_axis": np.asarray(section_axis, dtype=np.int8),
            }
            if body_code == "selected":
                measures = measures_of(uid, z, raw, frame)
                outward_mm = -measures.along(1)
                wall = relative_outer_wall(
                    raw, body, white, available, outward_mm, section_axis, SHELL_MM
                )
                ledger.record(f"{product}.outer_wall_readings", planes=1)
            native[z] = {
                "body": body,
                "body_code": body_code,
                "white": white,
                "target": target,
                "center_target": exact_target,
                "available": available,
                **readings,
                "wall": wall,
            }
            ledger.record(f"{product}.native_body_readings", planes=1)

    sample(initial)
    walk()
    guided_peaks = peaks(map_counts) if guided else peaks(counts)
    resolve(guided_peaks)
    guided_hit = any(
        native[z]["body_code"] == "selected" and native[z]["wall"]["minimum_band"].any()
        for z in guided_peaks
        if z in native
    )
    broadened = False
    source_hit = guided_hit
    if not guided_hit:
        resolve(peaks(counts))
        source_hit = any(
            native[z]["body_code"] == "selected"
            and native[z]["wall"]["minimum_band"].any()
            for z in native
        )
    if not source_hit:
        unvisited = {int(z) for z in np.flatnonzero(~visited)}
        broadened = bool(unvisited)
        sample(unvisited)
        walk()
        resolve(peaks(counts))
    outcome = (
        "guided_hit"
        if guided_hit and guided
        else "source_location_hit"
        if source_hit
        else "broadened_native_search"
    )
    if mapping is not None:
        mapping.smap.note_use(
            name,
            uid,
            outcome,
            question=product,
            anchors=[] if guide is None else list(guide.anchors),
            candidate_slices=sorted(native),
            full_depth=bool(visited.all()),
        )

    ordered = sorted(native)
    own.arrays["a4_sagittal_capsule_source_lps"] = points
    own.arrays["a4_sagittal_capsule_profile_count"] = counts
    own.arrays["a4_sagittal_capsule_profile_map_count"] = map_counts
    own.arrays["a4_sagittal_capsule_profile_status"] = status
    own.arrays["a4_sagittal_capsule_source_offset_mm"] = offsets_mm
    own.arrays["a4_sagittal_capsule_slices"] = np.asarray(ordered, dtype=np.int32)
    mask_arrays = (
        ("body", "body"),
        ("white", "white"),
        ("target", "target"),
        ("center_target", "center_target"),
        ("available", "available"),
        ("labels", "labels"),
    )
    for key, output_name in mask_arrays:
        if key in {
            "body",
            "white",
            "target",
            "available",
            "labels",
            "center_target",
        }:
            own.arrays[f"a4_sagittal_capsule_{output_name}"] = stacked(
                [native[z] for z in ordered],
                key,
                (rows, cols),
                np.int32 if key == "labels" else bool,
            )
    wall_arrays = (
        ("strip", "outer_strip", bool),
        ("minimum_band", "outer_wall", bool),
        ("lining_edge", "body_outer_edge", bool),
        ("body_outer_edge_mm", "body_outer_edge_mm", float),
        ("row_minimum", "row_minimum", float),
        ("adjacent_median", "adjacent_median", float),
        ("status", "wall_status", np.int8),
        ("tied_runs", "tied_runs", np.int16),
    )
    for field, output_name, dtype in wall_arrays:
        shape = (0, rows, cols) if dtype is bool else (0, 0)
        own.arrays[f"a4_sagittal_capsule_{output_name}"] = (
            np.stack([native[z]["wall"][field] for z in ordered])
            if ordered
            else np.empty(shape, dtype=dtype)
        )
    component_fields = ("sizes", "eligible_ids", "winner_ids")
    for z in ordered:
        for key in component_fields:
            own.arrays[f"a4_sagittal_capsule_{key}_{z}"] = native[z][key]
    own.arrays["a4_sagittal_capsule_section_axis"] = np.asarray(
        [native[z]["wall"]["section_axis"] for z in ordered], dtype=np.int8
    )

    sample_slices = sorted(samples)
    sample_offsets, sample_rc = [0], []
    for z in sample_slices:
        sample_rc.append(samples[z][0])
        sample_offsets.append(sample_offsets[-1] + len(samples[z][0]))
    own.arrays["a4_sagittal_capsule_sample_slices"] = np.asarray(
        sample_slices, dtype=np.int32
    )
    own.arrays["a4_sagittal_capsule_sample_offsets"] = np.asarray(
        sample_offsets, dtype=np.int64
    )
    sample_fields = (
        (1, "light", float),
        (2, "valid", bool),
        (3, "white", bool),
        (4, "in_map", bool),
        (5, "offset_mm", float),
        (6, "source_index", np.int64),
    )
    own.arrays["a4_sagittal_capsule_sample_rc"] = (
        np.concatenate(sample_rc) if sample_rc else np.empty((0, 2), dtype=np.int64)
    )
    for column, field, dtype in sample_fields:
        chunks = [samples[z][column] for z in sample_slices]
        own.arrays[f"a4_sagittal_capsule_sample_{field}"] = (
            np.concatenate(chunks) if chunks else np.empty(0, dtype=dtype)
        )
    own.arrays["a4_sagittal_capsule_projection_finite"] = projection_finite
    own.arrays["a4_sagittal_capsule_projection_inside"] = projection_inside

    plane_details = []
    for row, z in enumerate(ordered):
        values = native[z]
        wall_band = values["wall"]["minimum_band"]
        count = int(np.count_nonzero(wall_band))
        if count:
            code = "identified"
        elif values["body_code"] != "selected":
            code = f"abstain_{values['body_code']}"
        elif np.any(values["wall"]["status"] == 2):
            code = "abstain_disconnected_outer_minima"
        elif np.any(values["wall"]["status"] == 3):
            code = "abstain_outer_minimum_not_darker_than_body"
        else:
            code = "abstain_no_outer_band_in_shell"
        here.append(
            observe(
                name,
                "native",
                "resolved" if count else "reading",
                own,
                (z,),
                code,
                count,
                0.0,
                support,
                "Native anterior external low-signal capsule band selected relative to the adjacent white body; source points locate the question, not the band boundary, and the acquired sagittal signal supplies this local section.",
                artifact,
                row,
            )
        )
        plane_details.append(
            {
                "slice": z,
                "row": row,
                "code": code,
                "count": count,
                "body_code": values["body_code"],
                "body_pixels": int(np.count_nonzero(values["body"])),
                "eligible_ids": values["eligible_ids"].astype(int).tolist(),
                "winner_ids": values["winner_ids"].astype(int).tolist(),
                "source_offset_mm": float(offsets_mm[z]),
            }
        )

    resolved = any(item["code"] == "identified" for item in plane_details)
    detail.update(
        code="identified" if resolved else "measured_empty_outer_band",
        search=outcome,
        broadened=broadened,
        profile_status_codes={value: index for index, value in enumerate(reasons)},
        visited_slices=[int(z) for z in np.flatnonzero(visited)],
        unvisited_slices=[int(z) for z in np.flatnonzero(~visited)],
        pointed_planes=plane_details,
        guide=None
        if guide is None
        else {
            "status": guide.status,
            "slices": list(guide.slices),
            "anchors": list(guide.anchors),
            "placements": list(guide.placements),
            "half_px": guide.half_px,
        },
    )
    handed(
        product,
        ("profile", "native_body", "outer_wall", "samples", "component_context"),
    )
    reads(product, ("profile", "samples"), "sagittal_capsule_plane_choice")
    if here:
        reads(product, ("native_body", "outer_wall"), "sagittal_capsule_observations")
    if not resolved:
        if not ordered:
            if not samples or not any(np.isfinite(counts)):
                return refuse("unavailable_native_source_samples")
            return refuse("no_white_support_at_source_location")
        if any(native[z]["body_code"] == "tied_largest_bodies" for z in ordered):
            missing.append(
                Unresolved(
                    name,
                    "native",
                    uid,
                    tuple(own.record["view"]),
                    "sagittal_capsule:tied_largest_native_white_bodies",
                )
            )
    return here, missing


def name_sagittal_capsule(
    measured: list[Measured],
    said: list[tuple[list[Observation], list[Unresolved]]],
    study_uid: str,
    mapping: MapContext | None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Carry the largest unique native coronal capsule source to sagittal acquisitions."""
    sources = [
        (own.arrays["a4_capsule_source_lps"], own.record["capsule_source"])
        for own in measured
        if str(own.record["view"][0]).casefold() == "coronal"
        and "a4_capsule_source_lps" in own.arrays
        and "capsule_source" in own.record
        and own.record["capsule_source"].get("provenance") == "native"
    ]
    if sources:
        largest = max(float(source["area_mm2"]) for _, source in sources)
        choices = [
            (points, source)
            for points, source in sources
            if float(source["area_mm2"]) == largest
        ]
        points, source = (
            choices[0]
            if len(choices) == 1
            else (
                None,
                {"status": "tied", "candidates": [source for _, source in choices]},
            )
        )
    else:
        points, source = None, None
    return [
        sagittal_capsule(own, points, source, here, study_uid, mapping)
        for own, (here, _) in zip(measured, said, strict=True)
    ]


def _extensor_source_projection(
    points: np.ndarray,
    frame: PlaneFrame,
    thickness_mm: float,
    shape: tuple[int, int],
) -> tuple[np.ndarray, np.ndarray, int, bool, str | None]:
    """Project physical source points within this frame's actual half-slice slab."""
    rows, cols = shape
    try:
        normal = np.asarray(frame.normal(), dtype=float)
        origin = np.asarray(frame.origin_lps, dtype=float)
        if normal.shape != (3,) or origin.shape != (3,):
            raise ValueError("frame_geometry_shape")
        signed = (points - origin) @ normal
        if not np.isfinite(signed).all():
            raise ValueError("source_signed_distance_unavailable")
        slab_points = points[np.abs(signed) <= thickness_mm / 2.0]
    except (TypeError, ValueError, FloatingPointError):
        empty = np.empty((0, 2), dtype=np.int32)
        return empty, empty, 0, False, "source_projection_unavailable"
    if not np.isfinite(normal).all() or not np.isfinite(origin).all():
        empty = np.empty((0, 2), dtype=np.int32)
        return empty, empty, len(slab_points), False, "source_projection_unavailable"
    if not len(slab_points):
        empty = np.empty((0, 2), dtype=np.int32)
        return empty, empty, 0, True, None
    try:
        projected = np.asarray(frame.to_native(slab_points), dtype=float)
    except (TypeError, ValueError, OverflowError):
        projected = np.empty((0, 2), dtype=float)
    if projected.shape != (len(slab_points), 2) or not np.isfinite(projected).all():
        empty = np.empty((0, 2), dtype=np.int32)
        return (
            empty,
            empty,
            len(slab_points),
            False,
            "source_projection_unavailable",
        )
    rounded = np.rint(projected).astype(np.int64)
    inside = (
        (rounded[:, 0] >= 0)
        & (rounded[:, 0] < rows)
        & (rounded[:, 1] >= 0)
        & (rounded[:, 1] < cols)
    )
    if not inside.any():
        empty = np.empty((0, 2), dtype=np.int32)
        return (
            empty,
            empty,
            len(slab_points),
            False,
            "source_projection_outside_frame",
        )
    return (
        np.unique(rounded[inside], axis=0).astype(np.int32),
        rounded[inside].astype(np.int32),
        len(slab_points),
        bool(inside.all()),
        None,
    )


def _extensor_native_context(
    own: Measured,
    uid: str,
    z: int,
    raw: np.ndarray,
    frame: PlaneFrame,
) -> tuple[dict[str, Any], str | None]:
    """Measure the shared native dark-body context once for a candidate plane."""
    if raw.ndim != 2 or not np.isfinite(raw).all():
        return {"failure": "native_plane_unavailable"}, "native_plane_unavailable"
    depth_map = enclosed_depth_of(raw, uid, z)
    dark = depth_map > 0
    _, reading, _ = lens_of(
        own.series,
        z,
        raw,
        frame,
        float(own.record["background_split"]),
    )
    field = field_of(own.series, z, raw, frame, reading)
    free = ~margin_of(uid, z, raw)
    free &= (field.objects != OBJECT_CODES["air"]) & (
        field.objects != OBJECT_CODES["skin"]
    )
    measures = measures_of(uid, z, raw, frame)
    bodies = dark_tendon_bodies(
        dark,
        free,
        np.asarray(frame.spacing_rc),
        measures.along(1),
        measures.along(0),
    )
    return {
        "raw": raw,
        "frame": frame,
        "depth": depth_map,
        "dark": dark,
        "free": free,
        "labels": bodies.labels,
        "back_mm": bodies.back_mm,
        "inner_mm": bodies.inner_mm,
        "sizes": np.bincount(bodies.labels.ravel()),
    }, None


def _pack_extensor_native_context(
    arrays: dict[str, np.ndarray],
    prefix: str,
    cache: dict[int, dict[str, Any]],
    shape: tuple[int, int],
) -> list[int]:
    """Persist the retained native context with the reader's orientation prefix."""
    rows, cols = shape
    native_slices = sorted(z for z, value in cache.items() if "failure" not in value)
    arrays[f"{prefix}_native_slices"] = np.asarray(native_slices, dtype=np.int32)
    for key, dtype in (
        ("depth", float),
        ("dark", bool),
        ("free", bool),
        ("labels", np.int32),
    ):
        arrays[f"{prefix}_{key}"] = (
            np.stack([cache[z][key] for z in native_slices])
            if native_slices
            else np.empty((0, rows, cols), dtype=dtype)
        )
    size_offsets = [0]
    size_rows = []
    for z in native_slices:
        sizes = cache[z]["sizes"]
        size_rows.append(sizes)
        size_offsets.append(size_offsets[-1] + len(sizes))
    arrays[f"{prefix}_size_offsets"] = np.asarray(size_offsets, dtype=np.int64)
    arrays[f"{prefix}_sizes"] = (
        np.concatenate(size_rows).astype(np.int64)
        if size_rows
        else np.empty(0, dtype=np.int64)
    )
    for key in ("back_mm", "inner_mm"):
        offsets = [0]
        values = []
        for z in native_slices:
            row_values = cache[z][key]
            values.append(row_values)
            offsets.append(offsets[-1] + len(row_values))
        arrays[f"{prefix}_{key}_offsets"] = np.asarray(offsets, dtype=np.int64)
        arrays[f"{prefix}_{key}"] = (
            np.concatenate(values) if values else np.empty(0, dtype=float)
        )
    return native_slices


def extensor_sections(
    own: Measured,
    sources: dict[str, dict],
    study_uid: str,
    mapping: MapContext | None,
    orientation: str = "axial",
) -> tuple[list[Observation], list[Unresolved]]:
    """Read native axial tendon bodies at their identified sagittal source locations."""
    if orientation == "coronal":
        return coronal_extensor_sections(own, sources, study_uid, mapping)
    here: list[Observation] = []
    missing: list[Unresolved] = []
    if str(own.record["view"][0]).casefold() != "axial":
        return here, missing
    product = "axial_extensor_sections"
    detail: dict[str, Any] = {"sources": {}, "tendons": {}}
    own.record[product] = detail
    uid = own.series.row.series_uid
    view = tuple(own.record["view"])
    tendon_names = ("patellar_tendon", "quadriceps_tendon")

    def refuse(name: str, code: str) -> None:
        detail["tendons"].setdefault(name, {})["code"] = code
        missing.append(Unresolved(name, "native", uid, view, f"{product}:{code}"))

    selected: dict[str, tuple[np.ndarray, dict]] = {}
    for name in tendon_names:
        source = sources.get(name, {})
        detail["sources"][name] = source.get("detail", source.get("status"))
        if source.get("status") == "tied":
            refuse(name, f"tied_native_sagittal_{name}_sources")
            continue
        if source.get("status") != "selected":
            refuse(name, f"no_native_sagittal_{name}_source")
            continue
        try:
            points = np.asarray(source.get("points"), dtype=float)
        except (TypeError, ValueError):
            refuse(name, f"unreadable_native_sagittal_{name}_source")
            continue
        metadata = source.get("metadata")
        if (
            points.ndim != 2
            or points.shape[1:] != (3,)
            or not len(points)
            or not np.isfinite(points).all()
            or not isinstance(metadata, dict)
        ):
            refuse(name, f"unreadable_native_sagittal_{name}_source")
            continue
        selected[name] = (points, metadata)
        reads(f"axial_{name}_source", ("points_lps", "metadata"), product)
    if not selected:
        return here, missing

    series = own.series
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        for name in selected:
            refuse(name, "no_stacked_volume")
        return here, missing
    depth, rows, cols = np.shape(volume)
    raw_thicknesses = series.slice_thickness_mm
    try:
        thicknesses = tuple(
            float(value) for value in raw_thicknesses if value is not None
        )
    except (TypeError, ValueError, OverflowError):
        thicknesses = ()
    if (
        len(thicknesses) != depth
        or not np.isfinite(thicknesses).all()
        or any(value <= 0 for value in thicknesses)
    ):
        for name in selected:
            refuse(name, "actual_slice_thickness_unavailable")
        return here, missing

    guide_data: dict[str, Guide | None] = {}
    profile_counts = {name: np.full(depth, np.nan) for name in selected}
    map_counts = {name: np.full(depth, np.nan) for name in selected}
    profile_status = {name: np.zeros(depth, dtype=np.int8) for name in selected}
    targets: dict[str, dict[int, np.ndarray]] = {name: {} for name in selected}
    map_targets: dict[str, dict[int, np.ndarray]] = {name: {} for name in selected}
    projection_complete = {name: np.zeros(depth, dtype=bool) for name in selected}
    projection_failures: dict[str, dict[int, str]] = {name: {} for name in selected}
    if mapping is not None:
        for name in selected:
            guide_data[name] = mapping.guide(name, own)
    else:
        guide_data = dict.fromkeys(selected, None)

    for z in range(depth):
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            for name in selected:
                profile_status[name][z] = 1
            continue
        for name, (points, _) in selected.items():
            rc, _, slab_count, complete, failure = _extensor_source_projection(
                points, frame, thicknesses[z], (rows, cols)
            )
            if failure is not None:
                projection_failures[name][z] = failure
                profile_status[name][z] = 6
                continue
            if slab_count == 0:
                targets[name][z] = np.empty((0, 2), dtype=np.int32)
                profile_counts[name][z] = 0.0
                map_counts[name][z] = 0.0
                profile_status[name][z] = 2
                continue
            projection_complete[name][z] = complete
            targets[name][z] = rc
            if len(rc):
                profile_counts[name][z] = float(len(rc))
            if not len(rc):
                profile_counts[name][z] = 0.0
                map_counts[name][z] = 0.0
                profile_status[name][z] = 2
                continue
            in_guide = np.zeros(len(rc), dtype=bool)
            guide = guide_data[name]
            if guide is not None and guide.status == "guided" and z in guide.slices:
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    point = placement.get("point_lps")
                    if placement.get("status") != "ok" or point is None:
                        continue
                    try:
                        center = np.asarray(
                            frame.to_native(np.asarray([point])), dtype=float
                        )
                    except (TypeError, ValueError, OverflowError):
                        continue
                    if center.shape == (1, 2) and np.isfinite(center).all():
                        in_guide |= np.all(np.abs(rc - center[0]) <= half + 0.5, axis=1)
            map_counts[name][z] = float(np.count_nonzero(in_guide))
            map_targets[name][z] = in_guide
            profile_status[name][z] = 3 if projection_complete[name][z] else 4

    def maxima(values: np.ndarray) -> set[int]:
        runs = positive_runs(values)
        return {int(z) for run in run_maxima(values, runs) for z in run}

    artifact = str(artifact_of(study_uid, own.record))
    native_cache: dict[int, dict[str, Any]] = {}

    def native_body(name: str, z: int) -> tuple[dict | None, str | None]:
        native: dict[str, Any] | None = native_cache.get(z)
        if native is None:
            raw = np.asarray(volume[z])
            if raw.ndim != 2 or raw.shape != (rows, cols):
                native = {"failure": "native_plane_unavailable"}
            else:
                frame = plane_frame(series, z)
                if isinstance(frame, str):
                    native = {"failure": "native_frame_unavailable"}
                else:
                    native, failure = _extensor_native_context(own, uid, z, raw, frame)
                    if failure is not None:
                        native = {"failure": failure}
            native_cache[z] = native
        if native is None:
            return None, "native_context_unavailable"
        if "failure" in native:
            return None, str(native["failure"])
        labels = native["labels"]
        target = np.zeros((rows, cols), dtype=bool)
        target_rc = targets[name].get(z, np.empty((0, 2), dtype=np.int32))
        if len(target_rc):
            target[target_rc[:, 0], target_rc[:, 1]] = True
        touched = np.unique(labels[target])
        touched = touched[touched > 0]
        mask = np.zeros((rows, cols), dtype=bool)
        if not len(touched):
            code = "no_dark_body_at_source_location"
        else:
            selected_index = unique_largest(native["sizes"][touched])
            if selected_index is None:
                code = "tied_largest_dark_bodies_at_source_location"
            else:
                mask = labels == int(touched[selected_index])
                code = "identified"
        return {
            "code": code,
            "count": int(np.count_nonzero(mask)),
            "touched_ids": touched.astype(int).tolist(),
            "sizes": native["sizes"].astype(int).tolist(),
            "mask": mask,
            "target": target,
        }, None

    for name in selected:
        counts = profile_counts[name]
        guided_peaks = maxima(map_counts[name])
        source_peaks = maxima(counts)
        fallback_slices = sorted(source_peaks - guided_peaks)
        guide = guide_data[name]
        detail["tendons"][name] = {
            "profile_status_codes": {
                "0": "not_read",
                "1": "frame_unavailable",
                "2": "no_source_points_on_slab",
                "3": "complete_source_projection",
                "4": "partially_clipped_source_projection",
                "6": "source_projection_unavailable",
            },
            "guide": None
            if guide is None
            else {
                "status": guide.status,
                "slices": list(guide.slices),
                "placements": list(guide.placements),
                "half_px": guide.half_px,
            },
            "profile": [
                {
                    "slice": int(z),
                    "count": None if not np.isfinite(counts[z]) else int(counts[z]),
                    "map_count": None
                    if not np.isfinite(map_counts[name][z])
                    else int(map_counts[name][z]),
                    "status": int(profile_status[name][z]),
                    "target_pixels": len(targets[name].get(z, ())),
                    "projection_complete": bool(projection_complete[name][z]),
                }
                for z in range(depth)
            ],
            "candidate_order": {
                "map_guided_first": sorted(guided_peaks),
                "source_profile_fallback": fallback_slices,
            },
        }
        profile_slices = list(range(depth))
        own.arrays[f"a4_axial_{name}_profile_slices"] = np.asarray(
            profile_slices, dtype=np.int32
        )
        own.arrays[f"a4_axial_{name}_profile_count"] = counts
        own.arrays[f"a4_axial_{name}_profile_map_count"] = map_counts[name]
        own.arrays[f"a4_axial_{name}_profile_status"] = profile_status[name]
        own.arrays[f"a4_axial_{name}_projection_complete"] = projection_complete[name]
        profile_offsets = [0]
        profile_rc = []
        max_samples = max(
            (len(targets[name].get(z, ())) for z in profile_slices), default=0
        )
        target_rows = np.zeros((len(profile_slices), max_samples), dtype=bool)
        map_rows = np.zeros_like(target_rows)
        for z in profile_slices:
            row_index = len(profile_offsets) - 1
            coordinates = targets[name].get(z, np.empty((0, 2), dtype=np.int32))
            profile_rc.append(coordinates)
            profile_offsets.append(profile_offsets[-1] + len(coordinates))
            target_rows[row_index, : len(coordinates)] = True
            if len(coordinates):
                map_rows[row_index, : len(coordinates)] = map_targets[name][z]
        own.arrays[f"a4_axial_{name}_profile_target"] = target_rows
        own.arrays[f"a4_axial_{name}_profile_in_map"] = map_rows
        own.arrays[f"a4_axial_{name}_profile_offsets"] = np.asarray(
            profile_offsets, dtype=np.int64
        )
        own.arrays[f"a4_axial_{name}_profile_rc"] = (
            np.concatenate(profile_rc, axis=0)
            if profile_rc
            else np.empty((0, 2), dtype=np.int32)
        )
        candidate_failures: dict[int, str] = {}
        evaluated: dict[int, dict] = {}
        candidate_slices: list[int] = []
        broadened = False
        for phase, indices in (
            ("map_guided", sorted(guided_peaks)),
            ("source_profile", fallback_slices),
        ):
            if phase == "source_profile" and any(
                value["code"] == "identified" for value in evaluated.values()
            ):
                break
            if phase == "source_profile" and indices:
                broadened = True
            for z in indices:
                result, failure = native_body(name, z)
                candidate_slices.append(z)
                if failure is not None:
                    candidate_failures[z] = failure
                elif result is None:
                    candidate_failures[z] = "native_context_unavailable"
                else:
                    if (
                        result["code"] == "no_dark_body_at_source_location"
                        and not projection_complete[name][z]
                    ):
                        result["code"] = "partial_source_projection_no_dark_body"
                    evaluated[z] = result
        detail["tendons"][name]["candidate_slices"] = candidate_slices
        detail["tendons"][name]["broadened_after_guided_miss"] = broadened
        guided_hit = any(
            z in evaluated and evaluated[z]["code"] == "identified"
            for z in guided_peaks
        )
        if mapping is not None:
            outcome = (
                "guided_hit"
                if guided_hit
                else "guided_miss_then_source_profile"
                if guide is not None and guide.status == "guided"
                else "source_profile_only"
            )
            mapping.smap.note_use(
                name,
                uid,
                outcome,
                guided_slices=sorted(guided_peaks),
                source_profile_slices=fallback_slices,
                selected_slices=[
                    z for z, value in evaluated.items() if value["code"] == "identified"
                ],
            )
        candidates_saved = list(evaluated)
        candidate_rows = [evaluated[z]["mask"] for z in candidates_saved]
        target_rows = [evaluated[z]["target"] for z in candidates_saved]
        candidate_codes = [evaluated[z]["code"] for z in candidates_saved]
        slices_name = f"a4_axial_{name}_slices"
        support = f"a4_axial_{name}_body"
        own.arrays[slices_name] = np.asarray(candidates_saved, dtype=np.int32)
        own.arrays[support] = (
            np.stack(candidate_rows)
            if candidate_rows
            else np.empty((0, rows, cols), dtype=bool)
        )
        own.arrays[f"a4_axial_{name}_target_slices"] = np.asarray(
            candidates_saved, dtype=np.int32
        )
        own.arrays[f"a4_axial_{name}_target"] = (
            np.stack(target_rows)
            if target_rows
            else np.empty((0, rows, cols), dtype=bool)
        )
        own.arrays[f"a4_axial_{name}_candidate_codes"] = np.asarray(
            candidate_codes, dtype="U64"
        )
        detail["tendons"][name]["native_candidates"] = [
            {
                "slice": z,
                **{
                    key: value
                    for key, value in evaluated[z].items()
                    if key not in ("mask", "target")
                },
            }
            for z in candidates_saved
        ]
        for z, reason in candidate_failures.items():
            missing.append(
                Unresolved(
                    name, "native", uid, view, f"{product}:{reason}_at_slice_{z}"
                )
            )
        for z, reason in projection_failures[name].items():
            missing.append(
                Unresolved(
                    name, "native", uid, view, f"{product}:{reason}_at_slice_{z}"
                )
            )
        for row, z in enumerate(candidates_saved):
            result = evaluated[z]
            if result["code"] == "tied_largest_dark_bodies_at_source_location":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:tied_largest_bodies_at_slice_{z}",
                    )
                )
                continue
            if result["code"] == "partial_source_projection_no_dark_body":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:partial_source_projection_at_slice_{z}",
                    )
                )
                continue
            resolved = result["code"] == "identified"
            here.append(
                observe_in(
                    own.record,
                    name,
                    "native",
                    "resolved" if resolved else "reading",
                    (z,),
                    "identified"
                    if resolved
                    else "abstain_no_dark_body_at_source_location",
                    result["count"],
                    0.0,
                    support,
                    "The existing native dark body at the identified sagittal tendon location."
                    if resolved
                    else "The native axial source location was measured without a selected whole dark body.",
                    artifact,
                    row,
                    None,
                )
            )
        if not candidates_saved and not candidate_slices:
            refuse(name, "no_source_supported_axial_slice")
    native_slices = _pack_extensor_native_context(
        own.arrays, "a4_axial_extensor", native_cache, (rows, cols)
    )
    detail["native_measurements"] = [
        {"slice": int(z), "labels_count": int(native_cache[z]["sizes"].size - 1)}
        for z in native_slices
    ]
    if here:
        detail["code"] = (
            "identified"
            if any(row.kind == "resolved" for row in here)
            else "measured_empty"
        )
    else:
        detail["code"] = (
            "native_candidate_unavailable" if missing else "no_native_candidate"
        )
    handed(product, ("source_locations", "sparse_profiles"))
    reads(
        product,
        ("source_locations", "sparse_profiles"),
        "axial_extensor_candidate_selection",
    )
    if native_slices:
        handed(
            product,
            (
                "native_depth",
                "native_dark",
                "native_free",
                "native_labels",
                "native_positions",
                "component_sizes",
            ),
        )
        reads(
            product,
            (
                "native_depth",
                "native_dark",
                "native_free",
                "native_labels",
                "component_sizes",
            ),
            "axial_extensor_body_selection",
        )
        handed(product, ("native_selected_supports",))
    if any(row.support.endswith("_body") for row in here):
        reads(product, ("native_selected_supports",), "axial_extensor_observations")
    return here, missing


def coronal_extensor_sections(
    own: Measured,
    sources: dict[str, dict],
    study_uid: str,
    mapping: MapContext | None,
) -> tuple[list[Observation], list[Unresolved]]:
    """Read native coronal tendon bodies where sagittal and axial locations meet."""
    here: list[Observation] = []
    missing: list[Unresolved] = []
    if str(own.record["view"][0]).casefold() != "coronal":
        return here, missing
    product = "coronal_extensor_sections"
    detail: dict[str, Any] = {"sources": {}, "tendons": {}}
    own.record[product] = detail
    uid = own.series.row.series_uid
    view = tuple(own.record["view"])
    tendon_names = ("patellar_tendon", "quadriceps_tendon")
    source_groups = ("sagittal", "axial")

    def refuse(name: str, code: str) -> None:
        detail["tendons"].setdefault(name, {})["code"] = code
        missing.append(Unresolved(name, "native", uid, view, f"{product}:{code}"))

    selected: dict[str, dict[str, tuple[np.ndarray, dict]]] = {}
    for name in tendon_names:
        source = sources.get(name, {})
        detail["sources"][name] = source.get("detail", source.get("status"))
        groups: dict[str, tuple[np.ndarray, dict]] = {}
        if source.get("status") == "selected":
            for group in source_groups:
                group_source = source.get("groups", {}).get(group, {})
                try:
                    points = np.asarray(group_source.get("points"), dtype=float)
                except (TypeError, ValueError):
                    points = np.empty((0, 3), dtype=float)
                metadata = group_source.get("metadata")
                if (
                    points.ndim != 2
                    or points.shape[1:] != (3,)
                    or not len(points)
                    or not np.isfinite(points).all()
                    or not isinstance(metadata, dict)
                ):
                    break
                groups[group] = (points, metadata)
        if len(groups) != len(source_groups):
            refuse(name, source.get("failure", f"required_{name}_source_unavailable"))
            continue
        selected[name] = groups
        for group, (_, metadata) in groups.items():
            source_product = (
                f"axial_{name}_source"
                if group == "sagittal"
                else f"coronal_{name}_axial_source"
            )
            reads(source_product, ("points_lps", "metadata"), product)
            detail["tendons"].setdefault(name, {}).setdefault("source_addresses", {})[
                group
            ] = metadata
    if not selected:
        return here, missing

    series = own.series
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        for name in selected:
            refuse(name, "no_stacked_volume")
        return here, missing
    depth, rows, cols = np.shape(volume)
    raw_thicknesses = series.slice_thickness_mm
    try:
        thicknesses = tuple(
            float(value) for value in raw_thicknesses if value is not None
        )
    except (TypeError, ValueError, OverflowError):
        thicknesses = ()
    if (
        len(thicknesses) != depth
        or not np.isfinite(thicknesses).all()
        or any(value <= 0 for value in thicknesses)
    ):
        for name in selected:
            refuse(name, "actual_slice_thickness_unavailable")
        return here, missing

    guide_data: dict[str, Guide | None] = {}
    profile_counts = {
        name: {group: np.full(depth, np.nan) for group in source_groups}
        for name in selected
    }
    map_counts = {
        name: {group: np.full(depth, np.nan) for group in source_groups}
        for name in selected
    }
    profile_status = {
        name: {group: np.zeros(depth, dtype=np.int8) for group in source_groups}
        for name in selected
    }
    targets: dict[str, dict[str, dict[int, np.ndarray]]] = {
        name: {group: {} for group in source_groups} for name in selected
    }
    map_targets: dict[str, dict[str, dict[int, np.ndarray]]] = {
        name: {group: {} for group in source_groups} for name in selected
    }
    projection_complete = {
        name: {group: np.zeros(depth, dtype=bool) for group in source_groups}
        for name in selected
    }
    projection_failures: dict[str, dict[str, dict[int, str]]] = {
        name: {group: {} for group in source_groups} for name in selected
    }
    if mapping is not None:
        for name in selected:
            guide_data[name] = mapping.guide(name, own)
    else:
        guide_data = dict.fromkeys(selected, None)

    for z in range(depth):
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            for name in selected:
                for group in source_groups:
                    profile_status[name][group][z] = 1
            continue
        for name, groups in selected.items():
            guide = guide_data[name]
            for group, (points, _) in groups.items():
                rc, point_rc, slab_count, complete, failure = (
                    _extensor_source_projection(
                        points, frame, thicknesses[z], (rows, cols)
                    )
                )
                if failure is not None:
                    projection_failures[name][group][z] = failure
                    profile_status[name][group][z] = 6
                    continue
                if slab_count == 0:
                    targets[name][group][z] = np.empty((0, 2), dtype=np.int32)
                    profile_counts[name][group][z] = 0.0
                    map_counts[name][group][z] = 0.0
                    profile_status[name][group][z] = 2
                    continue
                projection_complete[name][group][z] = complete
                targets[name][group][z] = rc
                profile_counts[name][group][z] = float(slab_count)
                in_guide = np.zeros(len(rc), dtype=bool)
                point_in_guide = np.zeros(len(point_rc), dtype=bool)
                if guide is not None and guide.status == "guided" and z in guide.slices:
                    half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                    for placement in guide.placements:
                        point = placement.get("point_lps")
                        if placement.get("status") != "ok" or point is None:
                            continue
                        try:
                            center = np.asarray(
                                frame.to_native(np.asarray([point])), dtype=float
                            )
                        except (TypeError, ValueError, OverflowError):
                            continue
                        if center.shape == (1, 2) and np.isfinite(center).all():
                            in_guide |= np.all(
                                np.abs(rc - center[0]) <= half + 0.5, axis=1
                            )
                            point_in_guide |= np.all(
                                np.abs(point_rc - center[0]) <= half + 0.5, axis=1
                            )
                map_counts[name][group][z] = float(np.count_nonzero(point_in_guide))
                map_targets[name][group][z] = in_guide
                profile_status[name][group][z] = (
                    3 if projection_complete[name][group][z] else 4
                )

    def maxima(values: np.ndarray) -> set[int]:
        runs = positive_runs(values)
        return {int(z) for run in run_maxima(values, runs) for z in run}

    artifact = str(artifact_of(study_uid, own.record))
    native_cache: dict[int, dict[str, Any]] = {}

    def native_body(name: str, z: int) -> tuple[dict[str, Any] | None, str | None]:
        native: dict[str, Any] | None = native_cache.get(z)
        if native is None:
            raw = np.asarray(volume[z])
            if raw.ndim != 2 or raw.shape != (rows, cols):
                native = {"failure": "native_plane_unavailable"}
            else:
                frame = plane_frame(series, z)
                if isinstance(frame, str):
                    native = {"failure": "native_frame_unavailable"}
                else:
                    native, failure = _extensor_native_context(own, uid, z, raw, frame)
                    if failure is not None:
                        native = {"failure": failure}
            native_cache[z] = native
        if native is None:
            return None, "native_context_unavailable"
        if "failure" in native:
            return None, str(native["failure"])
        group_touched: dict[str, np.ndarray] = {}
        group_targets: dict[str, np.ndarray] = {}
        labels = native["labels"]
        for group in source_groups:
            target = np.zeros((rows, cols), dtype=bool)
            target_rc = targets[name][group].get(z, np.empty((0, 2), dtype=np.int32))
            if len(target_rc):
                target[target_rc[:, 0], target_rc[:, 1]] = True
            touched = np.unique(labels[target])
            group_touched[group] = touched[touched > 0]
            group_targets[group] = target
        eligible = np.intersect1d(group_touched["sagittal"], group_touched["axial"])
        mask = np.zeros((rows, cols), dtype=bool)
        if not len(eligible):
            code = "no_common_dark_body_at_both_source_locations"
        else:
            selected_index = unique_largest(native["sizes"][eligible])
            if selected_index is None:
                code = "tied_largest_common_dark_bodies_at_source_locations"
            else:
                mask = labels == int(eligible[selected_index])
                code = "identified"
        return {
            "code": code,
            "count": int(np.count_nonzero(mask)),
            "eligible_ids": eligible.astype(int).tolist(),
            "sagittal_touched_ids": group_touched["sagittal"].astype(int).tolist(),
            "axial_touched_ids": group_touched["axial"].astype(int).tolist(),
            "sizes": native["sizes"].astype(int).tolist(),
            "mask": mask,
            "targets": group_targets,
        }, None

    for name in selected:
        guided_peaks = set().union(
            *(maxima(map_counts[name][group]) for group in source_groups)
        )
        source_peaks = set().union(
            *(maxima(profile_counts[name][group]) for group in source_groups)
        )
        fallback_slices = sorted(source_peaks - guided_peaks)
        guide = guide_data[name]
        detail["tendons"][name] = {
            "profile_count_basis": "physical_source_points_on_actual_half_slice_slab",
            "profile_status_codes": {
                "0": "not_read",
                "1": "frame_unavailable",
                "2": "no_source_points_on_slab",
                "3": "complete_source_projection",
                "4": "partially_clipped_source_projection",
                "6": "source_projection_unavailable",
            },
            "guide": None
            if guide is None
            else {
                "status": guide.status,
                "slices": list(guide.slices),
                "placements": list(guide.placements),
                "half_px": guide.half_px,
            },
            "profile": {
                group: [
                    {
                        "slice": int(z),
                        "count": None
                        if not np.isfinite(profile_counts[name][group][z])
                        else int(profile_counts[name][group][z]),
                        "map_count": None
                        if not np.isfinite(map_counts[name][group][z])
                        else int(map_counts[name][group][z]),
                        "status": int(profile_status[name][group][z]),
                        "target_pixels": len(targets[name][group].get(z, ())),
                        "projection_complete": bool(
                            projection_complete[name][group][z]
                        ),
                    }
                    for z in range(depth)
                ]
                for group in source_groups
            },
            "candidate_order": {
                "map_guided_first": sorted(guided_peaks),
                "source_profile_fallback": fallback_slices,
            },
        }

        profile_slices = list(range(depth))
        own.arrays[f"a4_coronal_{name}_profile_slices"] = np.asarray(
            profile_slices, dtype=np.int32
        )
        for group in source_groups:
            own.arrays[f"a4_coronal_{name}_profile_{group}_count"] = profile_counts[
                name
            ][group]
            own.arrays[f"a4_coronal_{name}_profile_{group}_map_count"] = map_counts[
                name
            ][group]
            own.arrays[f"a4_coronal_{name}_profile_{group}_status"] = profile_status[
                name
            ][group]
            own.arrays[f"a4_coronal_{name}_projection_{group}_complete"] = (
                projection_complete[name][group]
            )
            offsets = [0]
            flat_rc = []
            max_samples = max(
                (len(targets[name][group].get(z, ())) for z in profile_slices),
                default=0,
            )
            target_rows = np.zeros((depth, max_samples), dtype=bool)
            map_rows = np.zeros_like(target_rows)
            for row_index, z in enumerate(profile_slices):
                rc = targets[name][group].get(z, np.empty((0, 2), dtype=np.int32))
                flat_rc.append(rc)
                offsets.append(offsets[-1] + len(rc))
                target_rows[row_index, : len(rc)] = True
                if len(rc):
                    map_rows[row_index, : len(rc)] = map_targets[name][group][z]
            own.arrays[f"a4_coronal_{name}_profile_{group}_target"] = target_rows
            own.arrays[f"a4_coronal_{name}_profile_{group}_in_map"] = map_rows
            own.arrays[f"a4_coronal_{name}_profile_{group}_offsets"] = np.asarray(
                offsets, dtype=np.int64
            )
            own.arrays[f"a4_coronal_{name}_profile_{group}_rc"] = (
                np.concatenate(flat_rc, axis=0)
                if flat_rc
                else np.empty((0, 2), dtype=np.int32)
            )

        candidate_failures: dict[int, str] = {}
        evaluated: dict[int, dict[str, Any]] = {}
        candidate_slices: list[int] = []
        broadened = False
        for phase, indices in (
            ("map_guided", sorted(guided_peaks)),
            ("source_profile", fallback_slices),
        ):
            if phase == "source_profile" and any(
                value["code"] == "identified" for value in evaluated.values()
            ):
                break
            if phase == "source_profile" and indices:
                broadened = True
            for z in indices:
                if any(
                    z not in targets[name][group] or not len(targets[name][group][z])
                    for group in source_groups
                ):
                    candidate_failures[z] = "both_source_locations_not_on_slice"
                    candidate_slices.append(z)
                    continue
                result, failure = native_body(name, z)
                candidate_slices.append(z)
                if failure is not None:
                    candidate_failures[z] = failure
                elif result is None:
                    candidate_failures[z] = "native_context_unavailable"
                else:
                    complete = all(
                        projection_complete[name][group][z] for group in source_groups
                    )
                    if (
                        result["code"] == "no_common_dark_body_at_both_source_locations"
                        and not complete
                    ):
                        result["code"] = "partial_source_projection_no_common_body"
                    evaluated[z] = result

        detail["tendons"][name]["candidate_slices"] = candidate_slices
        detail["tendons"][name]["broadened_after_guided_miss"] = broadened
        guided_hit = any(
            z in evaluated and evaluated[z]["code"] == "identified"
            for z in guided_peaks
        )
        if mapping is not None:
            outcome = (
                "guided_hit"
                if guided_hit
                else "guided_miss_then_source_profile"
                if guide is not None and guide.status == "guided"
                else "source_profile_only"
            )
            mapping.smap.note_use(
                name,
                uid,
                outcome,
                guided_slices=sorted(guided_peaks),
                source_profile_slices=fallback_slices,
                selected_slices=[
                    z for z, value in evaluated.items() if value["code"] == "identified"
                ],
            )
        candidates_saved = list(evaluated)
        own.arrays[f"a4_coronal_{name}_slices"] = np.asarray(
            candidates_saved, dtype=np.int32
        )
        own.arrays[f"a4_coronal_{name}_body"] = (
            np.stack([evaluated[z]["mask"] for z in candidates_saved])
            if candidates_saved
            else np.empty((0, rows, cols), dtype=bool)
        )
        for group in source_groups:
            own.arrays[f"a4_coronal_{name}_target_{group}"] = (
                np.stack([evaluated[z]["targets"][group] for z in candidates_saved])
                if candidates_saved
                else np.empty((0, rows, cols), dtype=bool)
            )
        own.arrays[f"a4_coronal_{name}_candidate_codes"] = np.asarray(
            [evaluated[z]["code"] for z in candidates_saved], dtype="U80"
        )
        detail["tendons"][name]["native_candidates"] = [
            {
                key: value
                for key, value in evaluated[z].items()
                if key not in ("mask", "targets")
            }
            | {"slice": z}
            for z in candidates_saved
        ]
        for z, reason in candidate_failures.items():
            missing.append(
                Unresolved(
                    name, "native", uid, view, f"{product}:{reason}_at_slice_{z}"
                )
            )
        for group in source_groups:
            for z, reason in projection_failures[name][group].items():
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:{group}_{reason}_at_slice_{z}",
                    )
                )
        for row, z in enumerate(candidates_saved):
            result = evaluated[z]
            if result["code"] == "tied_largest_common_dark_bodies_at_source_locations":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:tied_largest_common_bodies_at_slice_{z}",
                    )
                )
                continue
            if result["code"] == "partial_source_projection_no_common_body":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:partial_source_projection_at_slice_{z}",
                    )
                )
                continue
            resolved = result["code"] == "identified"
            here.append(
                observe_in(
                    own.record,
                    name,
                    "native",
                    "resolved" if resolved else "reading",
                    (z,),
                    "identified"
                    if resolved
                    else "abstain_no_common_dark_body_at_both_source_locations",
                    result["count"],
                    0.0,
                    f"a4_coronal_{name}_body",
                    "The existing native dark body at both identified sagittal and axial tendon locations."
                    if resolved
                    else "The native coronal locations were measured without a common selected whole dark body.",
                    artifact,
                    row,
                    None,
                )
            )
        if not candidates_saved and not candidate_slices:
            refuse(name, "no_source_supported_coronal_slice")

    handed(product, ("source_locations", "sparse_profiles"))
    reads(
        product,
        ("source_locations", "sparse_profiles"),
        "coronal_extensor_candidate_selection",
    )
    native_slices = _pack_extensor_native_context(
        own.arrays, "a4_coronal_extensor", native_cache, (rows, cols)
    )
    detail["native_measurements"] = [
        {"slice": int(z), "labels_count": int(native_cache[z]["sizes"].size - 1)}
        for z in native_slices
    ]
    if native_slices:
        handed(
            product,
            (
                "native_depth",
                "native_dark",
                "native_free",
                "native_labels",
                "native_positions",
                "component_sizes",
            ),
        )
        reads(
            product,
            (
                "native_depth",
                "native_dark",
                "native_free",
                "native_labels",
                "component_sizes",
            ),
            "coronal_extensor_body_selection",
        )
        handed(product, ("native_selected_supports",))
    if any(row.support.endswith("_body") for row in here):
        reads(product, ("native_selected_supports",), "coronal_extensor_observations")
    return here, missing


def name_axial_extensor_sections(
    measured: list[Measured], study_uid: str, mapping: MapContext | None
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Select each identified non-fat-suppressed sagittal tendon once as a location source."""
    sources: dict[str, dict] = {}
    for name in ("patellar_tendon", "quadriceps_tendon"):
        candidates = []
        considered = []
        for own in measured:
            if str(own.record["view"][0]).casefold() != "sagittal":
                continue
            if int(own.series.row.fat_suppression) != 0:
                continue
            code = own.record["assignments"]["codes"].get(name)
            objects = own.arrays.get("a1_objects")
            if code != "identified" or not isinstance(objects, np.ndarray):
                considered.append(
                    {"series_uid": own.record["series_uid"], "code": code}
                )
                continue
            mask = objects == OBJECT_CODES[name]
            count = int(np.count_nonzero(mask))
            if not count:
                considered.append(
                    {"series_uid": own.record["series_uid"], "code": code, "count": 0}
                )
                continue
            area = count * float(np.prod(own.frame.spacing_rc))
            metadata = {
                "series_uid": own.record["series_uid"],
                "slice": int(own.record["slice_index"]),
                "code": code,
                "count": count,
                "area_mm2": float(area),
                "artifact": str(artifact_of(study_uid, own.record)),
                "support": "a1_objects",
                "label": int(OBJECT_CODES[name]),
                "provenance": "native",
                "row": None,
            }
            considered.append(metadata)
            candidates.append((own, mask, metadata, area))
        if not candidates:
            sources[name] = {
                "status": "unavailable",
                "detail": {"status": "unavailable", "considered": considered},
            }
            continue
        selected = unique_largest(
            np.asarray([candidate[3] for candidate in candidates])
        )
        if selected is None:
            sources[name] = {
                "status": "tied",
                "detail": {
                    "status": "tied",
                    "candidates": [item[2] for item in candidates],
                },
            }
            continue
        owner, mask, metadata, _ = candidates[selected]
        points = owner.frame.to_patient(np.argwhere(mask).astype(float))
        if points.shape != (metadata["count"], 3) or not np.isfinite(points).all():
            sources[name] = {
                "status": "unavailable",
                "detail": {
                    "status": "unavailable",
                    "reason": "source_geometry_unavailable",
                    "considered": considered,
                },
            }
            continue
        owner.arrays[f"a4_axial_{name}_source_lps"] = points
        owner.record[f"a4_axial_{name}_source"] = metadata
        sources[name] = {
            "status": "selected",
            "points": points,
            "metadata": metadata,
            "detail": {"status": "selected", **metadata},
        }
        handed(f"axial_{name}_source", ("points_lps", "metadata"))
    return [
        extensor_sections(own, sources, study_uid, mapping)
        if str(own.record["view"][0]).casefold() == "axial"
        else ([], [])
        for own in measured
    ]


def name_coronal_extensor_sections(
    measured: list[Measured],
    axial_said: list[tuple[list[Observation], list[Unresolved]]],
    study_uid: str,
    mapping: MapContext | None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Reuse identified sagittal locations and selected axial bodies as coronal sources."""
    sources: dict[str, dict] = {}
    for name in ("patellar_tendon", "quadriceps_tendon"):
        sagittal_candidates = []
        for own in measured:
            metadata = own.record.get(f"a4_axial_{name}_source")
            points = own.arrays.get(f"a4_axial_{name}_source_lps")
            if (
                not isinstance(metadata, dict)
                or not isinstance(points, np.ndarray)
                or str(own.record["view"][0]).casefold() != "sagittal"
                or int(own.series.row.fat_suppression) != 0
                or own.record["assignments"]["codes"].get(name) != "identified"
                or metadata.get("code") != "identified"
                or metadata.get("provenance") != "native"
                or metadata.get("support") != "a1_objects"
                or metadata.get("label") != OBJECT_CODES[name]
                or metadata.get("row") is not None
            ):
                continue
            if (
                points.ndim != 2
                or points.shape[1:] != (3,)
                or not np.isfinite(points).all()
            ):
                continue
            sagittal_candidates.append((own, points, metadata))
        if len(sagittal_candidates) != 1:
            sources[name] = {
                "status": "unavailable",
                "failure": "sagittal_source_missing_or_ambiguous",
                "detail": {
                    "sagittal_status": "unavailable",
                    "candidates": [candidate[2] for candidate in sagittal_candidates],
                },
            }
            continue

        axial_candidates = []
        for own, (observations, _) in zip(measured, axial_said, strict=True):
            if str(own.record["view"][0]).casefold() != "axial":
                continue
            support = f"a4_axial_{name}_body"
            slices = own.arrays.get(f"a4_axial_{name}_slices")
            masks = own.arrays.get(support)
            if not isinstance(slices, np.ndarray) or not isinstance(masks, np.ndarray):
                continue
            for observation in observations:
                if (
                    observation.object != name
                    or observation.provenance != "native"
                    or observation.kind != "resolved"
                    or observation.code != "identified"
                    or observation.support != support
                    or observation.label is not None
                    or observation.row is None
                    or observation.series_uid != own.record["series_uid"]
                    or observation.view[0].casefold() != "axial"
                    or len(observation.slices) != 1
                    or observation.artifact != str(artifact_of(study_uid, own.record))
                ):
                    continue
                row = int(observation.row)
                z = int(observation.slices[0])
                if (
                    slices.ndim != 1
                    or masks.ndim != 3
                    or not 0 <= row < len(slices)
                    or row >= masks.shape[0]
                    or int(slices[row]) != z
                ):
                    continue
                mask = masks[row]
                if mask.dtype != np.bool_ or mask.ndim != 2:
                    continue
                count = int(np.count_nonzero(mask))
                if count != observation.count:
                    continue
                frame = plane_frame(own.series, z)
                if isinstance(frame, str):
                    continue
                area = count * float(np.prod(frame.spacing_rc))
                axial_candidates.append((own, mask, observation, frame, area))

        if not axial_candidates:
            sources[name] = {
                "status": "unavailable",
                "failure": "axial_native_resolved_body_unavailable",
                "detail": {
                    "sagittal_status": "selected",
                    "axial_status": "unavailable",
                },
            }
            continue
        selected_index = unique_largest(
            np.asarray([candidate[4] for candidate in axial_candidates], dtype=float)
        )
        if selected_index is None:
            sources[name] = {
                "status": "unavailable",
                "failure": "tied_axial_native_resolved_bodies",
                "detail": {
                    "sagittal_status": "selected",
                    "axial_status": "tied",
                    "candidates": [
                        {
                            "series_uid": item[2].series_uid,
                            "view": list(item[2].view),
                            "slices": list(item[2].slices),
                            "support": item[2].support,
                            "row": item[2].row,
                            "count": item[2].count,
                            "area_mm2": float(item[4]),
                        }
                        for item in axial_candidates
                    ],
                },
            }
            continue

        sagittal_owner, sagittal_points, sagittal_metadata = sagittal_candidates[0]
        axial_owner, axial_mask, axial_observation, axial_frame, axial_area = (
            axial_candidates[selected_index]
        )
        axial_points = axial_frame.to_patient(np.argwhere(axial_mask).astype(float))
        if (
            axial_points.shape != (axial_observation.count, 3)
            or not np.isfinite(axial_points).all()
        ):
            sources[name] = {
                "status": "unavailable",
                "failure": "axial_source_geometry_unavailable",
                "detail": {
                    "sagittal_status": "selected",
                    "axial_status": "unavailable",
                },
            }
            continue
        axial_metadata = {
            "series_uid": axial_observation.series_uid,
            "view": list(axial_observation.view),
            "slice": int(axial_observation.slices[0]),
            "code": axial_observation.code,
            "count": axial_observation.count,
            "area_mm2": float(axial_area),
            "artifact": axial_observation.artifact,
            "support": axial_observation.support,
            "label": axial_observation.label,
            "provenance": axial_observation.provenance,
            "row": axial_observation.row,
        }
        axial_owner.arrays[f"a4_coronal_{name}_axial_source_lps"] = axial_points
        axial_owner.record[f"a4_coronal_{name}_axial_source"] = axial_metadata
        handed(f"coronal_{name}_axial_source", ("points_lps", "metadata"))
        sources[name] = {
            "status": "selected",
            "groups": {
                "sagittal": {
                    "points": sagittal_points,
                    "metadata": sagittal_metadata,
                    "owner": sagittal_owner,
                },
                "axial": {
                    "points": axial_points,
                    "metadata": axial_metadata,
                    "owner": axial_owner,
                },
            },
            "detail": {
                "status": "selected",
                "sagittal": sagittal_metadata,
                "axial": axial_metadata,
            },
        }
    return [
        extensor_sections(own, sources, study_uid, mapping, orientation="coronal")
        if str(own.record["view"][0]).casefold() == "coronal"
        else ([], [])
        for own in measured
    ]


def axial_joint_compartment(
    own: Measured,
    sources: dict[str, dict],
    study_uid: str,
    mapping: MapContext | None,
) -> tuple[list[Observation], list[Unresolved]]:
    """Measure native axial fluid at the two independently selected joint locations."""
    name, product = "joint", "axial_joint_compartment"
    here: list[Observation] = []
    missing: list[Unresolved] = []
    view = tuple(own.record["view"])
    if not view or str(view[0]).casefold() != "axial":
        return here, missing
    detail: dict[str, Any] = {"sources": {}}
    own.record[product] = detail
    uid = own.series.row.series_uid

    def refuse(code: str):
        detail["code"] = code
        missing.append(Unresolved(name, "native", uid, view, f"{product}:{code}"))
        return here, missing

    series = own.series
    if not (
        int(series.row.fat_suppression) == 1 and int(series.row.fluid_sensitive) == 1
    ):
        return refuse("fluid_not_bright_on_this_sequence")
    selected_sources: dict[str, tuple[np.ndarray, dict]] = {}
    for orientation in ("sagittal", "coronal"):
        source = sources.get(orientation, {})
        detail["sources"][orientation] = source.get("detail", source.get("status"))
        if source.get("status") == "tied":
            return refuse(f"tied_native_{orientation}_joint_sources")
        if source.get("status") != "selected":
            return refuse(f"no_native_{orientation}_joint_source")
        try:
            points = np.asarray(source.get("points"), dtype=float)
        except (TypeError, ValueError):
            return refuse(f"unreadable_native_{orientation}_joint_source")
        metadata = source.get("metadata")
        if (
            points.ndim != 2
            or points.shape[1:] != (3,)
            or not len(points)
            or not np.isfinite(points).all()
            or not isinstance(metadata, dict)
        ):
            return refuse(f"unreadable_native_{orientation}_joint_source")
        selected_sources[orientation] = (points, metadata)
    for orientation in selected_sources:
        reads(
            f"axial_joint_source_{orientation}",
            ("points_lps", "metadata"),
            "axial_joint_source_projection",
        )

    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return refuse("no_stacked_volume")
    depth, rows, cols = np.shape(volume)
    raw_thicknesses = series.slice_thickness_mm
    if len(raw_thicknesses) != depth or any(value is None for value in raw_thicknesses):
        return refuse("actual_slice_thickness_unavailable")
    try:
        thickness_mm = tuple(
            float(value) for value in raw_thicknesses if value is not None
        )
    except (TypeError, ValueError, OverflowError):
        return refuse("actual_slice_thickness_unavailable")
    if (
        len(thickness_mm) != depth
        or not np.isfinite(thickness_mm).all()
        or any(value <= 0 for value in thickness_mm)
    ):
        return refuse("actual_slice_thickness_unavailable")
    level_record = own.record.get("recess", {}).get("level")
    if isinstance(level_record, (tuple, list)) and len(level_record) == 2:
        low, calibration = level_record[0], "existing_recess_profile"
    else:
        objects = own.arrays.get("a1_objects")
        if not isinstance(objects, np.ndarray) or objects.shape != (rows, cols):
            return refuse("no_native_marrow_reference")
        femur, tibia = (
            objects == OBJECT_CODES["femur"],
            objects == OBJECT_CODES["tibia"],
        )
        if not femur.any() or not tibia.any():
            return refuse("no_native_marrow_reference")
        measures = measures_of(
            uid, own.record["slice_index"], own.arrays["acquired_plane"], own.frame
        )
        combined_light = measures.light(femur | tibia)
        if combined_light is None or not np.isfinite(combined_light):
            return refuse("unreadable_fluid_level")
        low, calibration = (
            FLUID_BRIGHTER * float(combined_light),
            "same_shared_combined_marrow",
        )
    if low is None:
        return refuse("unreadable_fluid_level")
    try:
        low = float(low)
    except (TypeError, ValueError, OverflowError):
        return refuse("unreadable_fluid_level")
    if not np.isfinite(low) or low <= 0:
        return refuse("unreadable_fluid_level")
    detail.update(level=low, calibration=calibration)
    finite = finite_of(series)
    profile_count = np.full(depth, np.nan)
    profile_map_count = np.full(depth, np.nan)
    profile_status = np.zeros(depth, dtype=np.int8)
    source_slab_points = {
        key: np.zeros(depth, dtype=np.int32) for key in selected_sources
    }
    source_projected_points = {
        key: np.zeros(depth, dtype=np.int32) for key in selected_sources
    }
    source_target_pixels = {
        key: np.zeros(depth, dtype=np.int32) for key in selected_sources
    }
    source_projection_status = {
        key: np.zeros(depth, dtype=np.int8) for key in selected_sources
    }
    source_nearest_mm = {key: np.full(depth, np.nan) for key in selected_sources}
    source_white_count = {key: np.full(depth, np.nan) for key in selected_sources}
    source_valid_count = {
        key: np.zeros(depth, dtype=np.int32) for key in selected_sources
    }
    geometries: dict[int, dict[str, Any]] = {}
    sample_rows: dict[int, dict[str, Any]] = {}
    guide = None if mapping is None else mapping.guide(name, own)
    guided = (
        set()
        if guide is None or guide.status != "guided"
        else {int(z) for z in guide.slices if 0 <= int(z) < depth}
    )
    profile_codes = (
        "not_visited",
        "frame_unavailable",
        "source_projection_unavailable",
        "no_source_target_on_slice",
        "unavailable_target_samples",
        "sampled",
        "sampled_partial",
    )

    def geometry(z: int) -> dict[str, Any] | None:
        if z in geometries:
            return geometries[z]
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            profile_status[z] = 1
            return None
        try:
            normal = np.asarray(frame.normal(), dtype=float)
            origin = np.asarray(frame.origin_lps, dtype=float)
        except (TypeError, ValueError):
            profile_status[z] = 2
            return None
        if (
            normal.shape != (3,)
            or origin.shape != (3,)
            or not np.isfinite(normal).all()
            or not np.isfinite(origin).all()
        ):
            profile_status[z] = 2
            return None
        view_data: dict[str, Any] = {}
        for orientation, (points, _) in selected_sources.items():
            signed = (points - origin) @ normal
            source_nearest_mm[orientation][z] = float(np.min(np.abs(signed)))
            in_slab = np.abs(signed) <= thickness_mm[z] / 2.0
            slab_points = points[in_slab]
            source_slab_points[orientation][z] = len(slab_points)
            if not len(slab_points):
                rc = np.empty((0, 2), dtype=np.int64)
                inside_count = 0
                projection_status = 0
            else:
                try:
                    native = np.asarray(frame.to_native(slab_points), dtype=float)
                except (TypeError, ValueError, OverflowError):
                    native = np.empty((0, 2), dtype=float)
                if native.shape != (len(slab_points), 2):
                    rc = np.empty((0, 2), dtype=np.int64)
                    inside_count = 0
                    projection_status = 3
                else:
                    finite_projection = np.isfinite(native).all(axis=1)
                    rounded = np.zeros(native.shape, dtype=np.int64)
                    rounded[finite_projection] = np.rint(
                        native[finite_projection]
                    ).astype(np.int64)
                    inside = (
                        finite_projection
                        & (rounded[:, 0] >= 0)
                        & (rounded[:, 0] < rows)
                        & (rounded[:, 1] >= 0)
                        & (rounded[:, 1] < cols)
                    )
                    rc = np.unique(rounded[inside], axis=0)
                    inside_count = int(np.count_nonzero(inside))
                    projection_status = (
                        3
                        if inside_count == 0
                        else 2
                        if inside_count < len(slab_points)
                        else 1
                    )
            source_projected_points[orientation][z] = inside_count
            source_target_pixels[orientation][z] = len(rc)
            source_projection_status[orientation][z] = projection_status
            view_data[orientation] = {
                "rc": rc,
                "slab_count": len(slab_points),
                "projected_count": inside_count,
                "complete_projection": inside_count == len(slab_points)
                and len(slab_points) > 0,
            }
        geometries[z] = {"frame": frame, "sources": view_data}
        return geometries[z]

    def sample(indices):
        for z in sorted({int(value) for value in indices if 0 <= int(value) < depth}):
            if profile_status[z] != 0:
                continue
            geo = geometry(z)
            if geo is None:
                continue
            sources_at_z = geo["sources"]
            rc_by_source = {key: value["rc"] for key, value in sources_at_z.items()}
            if not all(len(rc_by_source[key]) for key in selected_sources):
                profile_status[z] = 3
            union_rc = (
                np.unique(
                    np.concatenate(
                        [value for value in rc_by_source.values() if len(value)], axis=0
                    ),
                    axis=0,
                )
                if any(len(value) for value in rc_by_source.values())
                else np.empty((0, 2), dtype=np.int64)
            )
            target_sets = {
                key: {tuple(pixel) for pixel in value.tolist()}
                for key, value in rc_by_source.items()
            }
            if not len(union_rc):
                if any(value["slab_count"] for value in sources_at_z.values()):
                    profile_status[z] = 2
                sample_rows[z] = {
                    "rc": union_rc,
                    "target_sagittal_rc": rc_by_source["sagittal"],
                    "target_coronal_rc": rc_by_source["coronal"],
                    "in_sagittal": np.empty(0, dtype=bool),
                    "in_coronal": np.empty(0, dtype=bool),
                    "light": np.empty(0),
                    "valid": np.empty(0, bool),
                    "white": np.empty(0, bool),
                    "in_map": np.empty(0, bool),
                    "complete_projection": all(
                        value["complete_projection"] for value in sources_at_z.values()
                    ),
                }
                continue
            rr, cc = union_rc.T
            raw = np.asarray(volume[z])
            margin = margin_of(uid, z, raw)
            light = np.asarray(raw[rr, cc], dtype=float)
            valid = finite[z, rr, cc] & ~margin[rr, cc]
            white = valid & (light >= low)
            membership = {}
            for orientation in selected_sources:
                in_source = np.asarray(
                    [tuple(pixel) in target_sets[orientation] for pixel in union_rc],
                    dtype=bool,
                )
                membership[orientation] = in_source
                source_valid_count[orientation][z] = int(
                    np.count_nonzero(in_source & valid)
                )
                if np.any(in_source & white):
                    source_white_count[orientation][z] = float(
                        np.count_nonzero(in_source & white)
                    )
                elif in_source.any() and valid[in_source].all():
                    source_white_count[orientation][z] = 0.0
            in_map = np.zeros(len(union_rc), dtype=bool)
            if guide is not None and z in guided:
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    if (
                        placement.get("status") == "ok"
                        and placement.get("point_lps") is not None
                    ):
                        center = geo["frame"].to_native(
                            np.asarray([placement["point_lps"]], dtype=float)
                        )[0]
                        if np.isfinite(center).all():
                            in_map |= np.all(
                                np.abs(union_rc - center) <= half + 0.5, axis=1
                            )
            complete = bool(
                valid.all()
                and all(value["complete_projection"] for value in sources_at_z.values())
            )
            if np.any(white):
                profile_count[z] = float(np.count_nonzero(white))
                profile_map_count[z] = float(np.count_nonzero(white & in_map))
            elif complete:
                profile_count[z] = 0.0
                profile_map_count[z] = 0.0
            profile_status[z] = 4 if not valid.any() else 5 if complete else 6
            sample_rows[z] = {
                "rc": union_rc,
                "target_sagittal_rc": rc_by_source["sagittal"],
                "target_coronal_rc": rc_by_source["coronal"],
                "in_sagittal": membership["sagittal"],
                "in_coronal": membership["coronal"],
                "light": light,
                "valid": valid,
                "white": white,
                "in_map": in_map,
                "complete_projection": complete,
            }
        ledger.record(f"{product}.profile_sampled_slices", planes=len(indices))

    def peaks(values):
        return {
            int(z) for run in run_maxima(values, positive_runs(values)) for z in run
        }

    def walk():
        while True:
            more: set[int] = set()
            runs = positive_runs(profile_count)
            for (a, b), maxima in zip(
                runs, run_maxima(profile_count, runs), strict=True
            ):
                if a in maxima and a > 0 and profile_status[a - 1] == 0:
                    more.add(a - 1)
                if b - 1 in maxima and b < depth and profile_status[b] == 0:
                    more.add(b)
            if not more:
                break
            sample(more)

    source_slices = set()
    for z in range(depth):
        geo = geometry(z)
        if geo is not None and any(
            value["slab_count"] for value in geo["sources"].values()
        ):
            source_slices.add(z)
    initial = guided | source_slices
    if not initial:
        return refuse("no_guided_or_source_supported_axial_slice")
    visited = np.zeros(depth, dtype=bool)
    sample(initial)
    visited |= profile_status != 0
    walk()
    visited |= profile_status != 0
    native: dict[int, dict[str, Any]] = {}
    artifact = str(artifact_of(study_uid, own.record))
    support = "a4_joint_axial_compartment"

    def resolve(indices):
        for z in sorted(indices):
            if (
                z in native
                or z not in sample_rows
                or not np.isfinite(profile_count[z])
                or profile_count[z] <= 0
            ):
                continue
            geo = geometry(z)
            if geo is None:
                continue
            row = sample_rows[z]
            masks = {}
            for orientation in selected_sources:
                mask = np.zeros((rows, cols), dtype=bool)
                rc = row[f"target_{orientation}_rc"]
                if len(rc):
                    mask[rc[:, 0], rc[:, 1]] = True
                masks[orientation] = mask
            if not masks["sagittal"].any() or not masks["coronal"].any():
                continue
            raw = np.asarray(volume[z])
            available = finite[z] & ~margin_of(uid, z, raw)
            white_plane = available & (raw >= low)
            labels, count = ndi.label(
                white_plane, structure=np.ones((3, 3), dtype=bool)
            )
            sizes = np.bincount(labels.ravel(), minlength=count + 1)[1:]
            touched_sagittal = np.unique(labels[masks["sagittal"]])
            touched_sagittal = touched_sagittal[touched_sagittal > 0].astype(
                np.int64, copy=False
            )
            touched_coronal = np.unique(labels[masks["coronal"]])
            touched_coronal = touched_coronal[touched_coronal > 0].astype(
                np.int64, copy=False
            )
            eligible = np.intersect1d(touched_sagittal, touched_coronal)
            winners = np.empty(0, dtype=np.int64)
            body = np.zeros((rows, cols), dtype=bool)
            if not touched_sagittal.size:
                body_code = "no_white_body_at_sagittal_target"
            elif not touched_coronal.size:
                body_code = "no_white_body_at_coronal_target"
            elif not eligible.size:
                body_code = "no_white_body_touches_both_sources"
            else:
                eligible_sizes = sizes[eligible - 1]
                winners = eligible[eligible_sizes == np.max(eligible_sizes)]
                winner = unique_largest(eligible_sizes)
                if winner is None:
                    body_code = "tied_largest_bodies"
                else:
                    body_code = "selected"
                    body = labels == int(eligible[winner])
            native[z] = {
                **row,
                "frame": geo["frame"],
                "target_sagittal": masks["sagittal"],
                "target_coronal": masks["coronal"],
                "available": available,
                "white_plane": white_plane,
                "labels": labels,
                "body": body,
                "body_code": body_code,
                "sizes": sizes,
                "touched_sagittal_ids": touched_sagittal,
                "touched_coronal_ids": touched_coronal,
                "eligible_ids": eligible,
                "winner_ids": winners,
            }
            ledger.record(f"{product}.native_components", planes=1)
            handed(product, ("native_components", "native_component_selection"))
            reads(product, ("native_components",), "axial_joint_source_concurrence")

    guided_candidates = peaks(profile_map_count) if guided else set()
    resolve(guided_candidates)
    guided_hit = any(
        native[z]["body_code"] == "selected" for z in guided_candidates if z in native
    )
    if not guided_hit:
        resolve(peaks(profile_count))
    source_hit = any(value["body_code"] == "selected" for value in native.values())
    broadened = False
    if not source_hit:
        unvisited = {int(z) for z in np.flatnonzero(~visited)}
        broadened = bool(unvisited)
        sample(unvisited)
        visited |= profile_status != 0
        walk()
        visited |= profile_status != 0
        resolve(peaks(profile_count))
        source_hit = any(value["body_code"] == "selected" for value in native.values())
    outcome = (
        "guided_hit"
        if guided_hit
        else "source_location_hit"
        if source_hit and not broadened
        else "broadened_native_search"
    )
    if mapping is not None:
        mapping.smap.note_use(
            name,
            uid,
            outcome,
            question=product,
            anchors=[] if guide is None else list(guide.anchors),
            candidate_slices=sorted(native),
            full_depth=bool(visited.all()),
        )

    profile_slices = sorted(sample_rows)
    offsets = [0]
    chunks = {
        key: []
        for key in (
            "rc",
            "light",
            "valid",
            "white",
            "in_map",
            "in_sagittal",
            "in_coronal",
        )
    }
    for z in profile_slices:
        row = sample_rows[z]
        rc = row["rc"]
        chunks["rc"].append(rc)
        chunks["light"].append(row["light"])
        chunks["valid"].append(row["valid"])
        chunks["white"].append(row["white"])
        chunks["in_map"].append(row["in_map"])
        chunks["in_sagittal"].append(row["in_sagittal"])
        chunks["in_coronal"].append(row["in_coronal"])
        offsets.append(offsets[-1] + len(rc))
    own.arrays["a4_joint_axial_profile_count"] = profile_count
    own.arrays["a4_joint_axial_profile_map_count"] = profile_map_count
    own.arrays["a4_joint_axial_profile_status"] = profile_status
    own.arrays["a4_joint_axial_profile_slices"] = np.asarray(
        profile_slices, dtype=np.int32
    )
    own.arrays["a4_joint_axial_profile_offsets"] = np.asarray(offsets, dtype=np.int64)
    geometry_slices = sorted(geometries)
    own.arrays["a4_joint_axial_geometry_slices"] = np.asarray(
        geometry_slices, dtype=np.int32
    )
    for orientation in selected_sources:
        geometry_offsets = [0]
        geometry_rc = []
        for z in geometry_slices:
            rc = geometries[z]["sources"][orientation]["rc"]
            geometry_rc.append(rc)
            geometry_offsets.append(geometry_offsets[-1] + len(rc))
        own.arrays[f"a4_joint_axial_geometry_{orientation}_offsets"] = np.asarray(
            geometry_offsets, dtype=np.int64
        )
        own.arrays[f"a4_joint_axial_geometry_{orientation}_rc"] = (
            np.concatenate(geometry_rc, axis=0)
            if geometry_rc
            else np.empty((0, 2), dtype=np.int64)
        )
    for key, chunks_for_key in chunks.items():
        own.arrays[f"a4_joint_axial_profile_{key}"] = (
            np.concatenate(chunks_for_key)
            if chunks_for_key
            else np.empty(
                (0, 2) if key == "rc" else (0,),
                dtype=np.int64
                if key == "rc"
                else (
                    bool
                    if key in ("valid", "white", "in_map", "in_sagittal", "in_coronal")
                    else float
                ),
            )
        )
    for orientation in selected_sources:
        own.arrays[f"a4_joint_axial_profile_{orientation}_slab_points"] = (
            source_slab_points[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_projected_points"] = (
            source_projected_points[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_target_pixels"] = (
            source_target_pixels[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_projection_status"] = (
            source_projection_status[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_nearest_mm"] = (
            source_nearest_mm[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_valid_count"] = (
            source_valid_count[orientation]
        )
        own.arrays[f"a4_joint_axial_profile_{orientation}_white_count"] = (
            source_white_count[orientation]
        )

    native_slices = sorted(native)
    own.arrays["a4_joint_axial_slices"] = np.asarray(native_slices, dtype=np.int32)
    for key, dtype in (
        ("target_sagittal", bool),
        ("target_coronal", bool),
        ("available", bool),
        ("white_plane", bool),
        ("labels", np.int32),
        ("compartment", bool),
    ):
        source_key = "body" if key == "compartment" else key
        own.arrays[f"a4_joint_axial_{key}"] = (
            np.stack([native[z][source_key] for z in native_slices])
            if native_slices
            else np.empty((0, rows, cols), dtype=dtype)
        )
    for z in native_slices:
        for key in (
            "sizes",
            "touched_sagittal_ids",
            "touched_coronal_ids",
            "eligible_ids",
            "winner_ids",
        ):
            own.arrays[f"a4_joint_axial_{key}_{z}"] = native[z][key]

    plane_details = []
    native_row = {z: row for row, z in enumerate(native_slices)}
    profile_row = {z: row for row, z in enumerate(profile_slices)}
    zero_profiles = {
        z
        for z in profile_slices
        if profile_count[z] == 0
        and np.isfinite(profile_count[z])
        and len(sample_rows[z]["target_sagittal_rc"])
        and len(sample_rows[z]["target_coronal_rc"])
    }
    for z in sorted(set(native_slices) | zero_profiles):
        values = native.get(z)
        if values is None:
            row_index = profile_row[z]
            support_name = "a4_joint_axial_profile_white"
            code, kind, count, note = (
                "abstain_no_white_sample_at_source_locations",
                "reading",
                0,
                "Both native joint locations were sampled and no white profile sample was measured; unmeasured pixels remain unknown.",
            )
            row_address = row_index
        else:
            row_index = native_row[z]
            support_name = support
            body_code = values["body_code"]
            if body_code == "tied_largest_bodies":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"{product}:tied_largest_native_white_bodies_at_slice_{z}",
                    )
                )
                plane_details.append(
                    {
                        "slice": z,
                        "row": row_index,
                        "code": "abstain_tied_largest_bodies",
                        "body_code": body_code,
                        "eligible_ids": values["eligible_ids"].astype(int).tolist(),
                        "winner_ids": values["winner_ids"].astype(int).tolist(),
                    }
                )
                continue
            code = {
                "selected": "identified",
                "no_white_body_at_sagittal_target": "abstain_no_white_body_at_sagittal_target",
                "no_white_body_at_coronal_target": "abstain_no_white_body_at_coronal_target",
                "no_white_body_touches_both_sources": "abstain_no_white_body_touches_both_sources",
            }.get(body_code, "abstain_no_white_body_touched_by_both_sources")
            kind = "resolved" if body_code == "selected" else "reading"
            count = int(np.count_nonzero(values["body"]))
            note = (
                "The native axial white body touched by both sagittal and coronal joint locations: a fluid-filled portion of the tibiofemoral/intercondylar joint space, not its whole boundary."
                if kind == "resolved"
                else "The native axial plane was measured at both source locations, without a selected whole white body touching both."
            )
            row_address = row_index
        here.append(
            observe_in(
                own.record,
                name,
                "native",
                kind,
                (z,),
                code,
                count,
                0.0,
                support_name,
                note,
                artifact,
                row_address,
                None,
            )
        )
        plane_details.append(
            {
                "slice": z,
                "row": row_address,
                "support": support_name,
                "code": code,
                "count": count,
                "source_profile_white_count": None
                if not np.isfinite(profile_count[z])
                else int(profile_count[z]),
                "body_code": "measured_empty_profile"
                if values is None
                else values["body_code"],
            }
        )
    resolved = any(item.kind == "resolved" for item in here)
    if not here and not any(
        row["body_code"] == "tied_largest_bodies" for row in native.values()
    ):
        visited_status = profile_status[np.flatnonzero(visited)]
        target_rows = [
            row
            for row in sample_rows.values()
            if len(row["target_sagittal_rc"]) and len(row["target_coronal_rc"])
        ]
        code = (
            "all_native_target_samples_unavailable"
            if target_rows and all(not row["valid"].any() for row in target_rows)
            else "source_projection_unavailable"
            if any(
                np.any(source_projection_status[key][visited] == 3)
                for key in selected_sources
            )
            else "source_projection_unavailable"
            if len(visited_status) and np.all(visited_status == 2)
            else "no_native_white_body_touched_by_both_sources"
        )
        missing.append(Unresolved(name, "native", uid, view, f"{product}:{code}"))
        detail["code"] = code
    else:
        detail["code"] = (
            "identified" if resolved else "measured_empty_at_sampled_slices"
        )
    detail.update(
        search=outcome,
        broadened=broadened,
        profile_status_codes={
            value: index for index, value in enumerate(profile_codes)
        },
        visited_slices=[int(z) for z in np.flatnonzero(visited)],
        unvisited_slices=[int(z) for z in np.flatnonzero(~visited)],
        source_projection_status_codes={
            "no_source_points_in_slab": 0,
            "complete": 1,
            "partly_projected_or_clipped": 2,
            "unavailable_or_outside_frame": 3,
        },
        source_profile=[
            {
                "slice": int(z),
                "count": None
                if not np.isfinite(profile_count[z])
                else int(profile_count[z]),
                "map_count": None
                if not np.isfinite(profile_map_count[z])
                else int(profile_map_count[z]),
                "status": profile_codes[int(profile_status[z])],
                "sagittal_slab_points": int(source_slab_points["sagittal"][z]),
                "coronal_slab_points": int(source_slab_points["coronal"][z]),
                "sagittal_projected_points": int(
                    source_projected_points["sagittal"][z]
                ),
                "coronal_projected_points": int(source_projected_points["coronal"][z]),
                "sagittal_target_pixels": int(source_target_pixels["sagittal"][z]),
                "coronal_target_pixels": int(source_target_pixels["coronal"][z]),
                "sagittal_projection_status": int(
                    source_projection_status["sagittal"][z]
                ),
                "coronal_projection_status": int(
                    source_projection_status["coronal"][z]
                ),
                "sagittal_nearest_mm": None
                if not np.isfinite(source_nearest_mm["sagittal"][z])
                else float(source_nearest_mm["sagittal"][z]),
                "coronal_nearest_mm": None
                if not np.isfinite(source_nearest_mm["coronal"][z])
                else float(source_nearest_mm["coronal"][z]),
                "sagittal_valid_count": int(source_valid_count["sagittal"][z]),
                "coronal_valid_count": int(source_valid_count["coronal"][z]),
                "sagittal_white_count": None
                if not np.isfinite(source_white_count["sagittal"][z])
                else int(source_white_count["sagittal"][z]),
                "coronal_white_count": None
                if not np.isfinite(source_white_count["coronal"][z])
                else int(source_white_count["coronal"][z]),
            }
            for z in np.flatnonzero(visited)
        ],
        pointed_planes=plane_details,
        guide=None
        if guide is None
        else {
            "status": guide.status,
            "slices": list(guide.slices),
            "anchors": list(guide.anchors),
            "placements": list(guide.placements),
            "half_px": guide.half_px,
        },
    )
    handed(
        product,
        (
            "source_geometry",
            "source_targets",
            "profile_count",
            "profile_map_count",
            "sampled_source_values",
        ),
    )
    reads(
        product, ("source_geometry", "source_targets"), "axial_joint_profile_sampling"
    )
    reads(
        product,
        ("profile_count", "profile_map_count", "sampled_source_values"),
        "axial_joint_plane_choice",
    )
    if native:
        reads(product, ("native_component_selection",), "axial_joint_observations")
    return here, missing


def name_axial_joint_compartment(
    measured: list[Measured], study_uid: str, mapping: MapContext | None
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Select the largest unique existing sagittal and coronal joint sections as locations."""
    sources: dict[str, dict] = {}
    for orientation in ("sagittal", "coronal"):
        candidates: list[tuple[Measured, np.ndarray, dict, float]] = []
        considered = []
        for own in measured:
            if str(own.record["view"][0]).casefold() != orientation:
                continue
            if not (
                int(own.series.row.fat_suppression) == 1
                and int(own.series.row.fluid_sensitive) == 1
            ):
                continue
            code = own.record["assignments"]["codes"].get("joint")
            objects = own.arrays.get("a1_objects")
            if code != "identified" or not isinstance(objects, np.ndarray):
                considered.append(
                    {"series_uid": own.record["series_uid"], "code": code}
                )
                continue
            mask = objects == OBJECT_CODES["joint"]
            count = int(np.count_nonzero(mask))
            if not count:
                considered.append(
                    {"series_uid": own.record["series_uid"], "code": code, "count": 0}
                )
                continue
            frame = own.frame
            area = float(count) * float(np.prod(frame.spacing_rc))
            metadata = {
                "series_uid": own.record["series_uid"],
                "slice": int(own.record["slice_index"]),
                "code": code,
                "count": count,
                "area_mm2": area,
                "artifact": str(artifact_of(study_uid, own.record)),
                "support": "a1_objects",
                "label": int(OBJECT_CODES["joint"]),
                "provenance": "native",
                "row": None,
            }
            considered.append(metadata)
            candidates.append((own, mask, metadata, area))
        if not candidates:
            sources[orientation] = {
                "status": "unavailable",
                "detail": {"status": "unavailable", "considered": considered},
            }
            continue
        selected_index = unique_largest(
            np.asarray([candidate[3] for candidate in candidates], dtype=float)
        )
        if selected_index is None:
            sources[orientation] = {
                "status": "tied",
                "detail": {
                    "status": "tied",
                    "candidates": [candidate[2] for candidate in candidates],
                },
            }
            continue
        owner, mask, metadata, _ = candidates[selected_index]
        pixels = np.argwhere(mask).astype(float)
        points = owner.frame.to_patient(pixels)
        if (
            points.ndim != 2
            or points.shape != (metadata["count"], 3)
            or not np.isfinite(points).all()
        ):
            sources[orientation] = {
                "status": "unavailable",
                "detail": {
                    "status": "unavailable",
                    "reason": "source_geometry_unavailable",
                    "considered": considered,
                },
            }
            continue
        owner.arrays[f"a4_joint_axial_source_{orientation}_lps"] = points
        owner.record[f"a4_joint_axial_source_{orientation}"] = metadata
        sources[orientation] = {
            "status": "selected",
            "points": points,
            "metadata": metadata,
            "detail": {"status": "selected", **metadata},
        }
        handed(f"axial_joint_source_{orientation}", ("points_lps", "metadata"))
    return [
        axial_joint_compartment(own, sources, study_uid, mapping)
        if str(own.record["view"][0]).casefold() == "axial"
        else ([], [])
        for own in measured
    ]


def keep_recess(
    measured: list[Measured], said: list[tuple[list[Observation], list[Unresolved]]]
) -> None:
    """The recess family's observations appended to each series' record, after every earlier
    family's (`keep_observations`: earlier rows stay as written, in their order)."""
    for m, (here, missing) in zip(measured, said, strict=True):
        if here or missing:
            keep_observations(m, here, missing)


def retinacular_sources(
    measured: list[Measured],
    pointed: list[tuple[list[Observation], list[Unresolved]]],
    main_found: list[tuple[dict, dict[str, np.ndarray]]],
    study_uid: str,
) -> dict[str, dict[str, Any]]:
    """Choose each side's unique largest native axial wall and retain its physical locations."""
    by_uid = {own.record["series_uid"]: own for own in measured}
    main_by_artifact = {
        str(artifact_of(study_uid, record)): (record, arrays)
        for record, arrays in main_found
    }
    observations = [
        Observation(
            object=row["object"],
            provenance=row["provenance"],
            kind=row["kind"],
            series_uid=row["series_uid"],
            view=tuple(row["view"]),
            slices=tuple(row["slices"]),
            code=row["code"],
            count=row.get("count"),
            off_plane_mm=row.get("off_plane_mm"),
            support=row["support"],
            note=row["note"],
            artifact=row.get("artifact"),
            row=row.get("row"),
            label=row.get("label"),
        )
        for own in measured
        for row in own.record.get("observations", [])
        if isinstance(row, dict)
    ] + [observation for here, _ in pointed for observation in here]
    sources: dict[str, dict[str, Any]] = {}
    for name in RETINACULA:
        side = "medial" if name == RETINACULA[0] else "lateral"
        candidates: list[
            tuple[
                Measured,
                Observation,
                np.ndarray,
                PlaneFrame,
                float,
                dict[str, Any],
            ]
        ] = []
        considered = []
        seen: set[tuple[Any, ...]] = set()
        for observation in observations:
            key = (
                observation.object,
                observation.series_uid,
                observation.slices,
                observation.artifact,
                observation.support,
                observation.row,
            )
            if key in seen or observation.object != name:
                continue
            seen.add(key)
            if (
                observation.provenance != "native"
                or observation.kind != "resolved"
                or observation.code != "identified"
                or observation.view[0].casefold() != "axial"
                or observation.label is not None
                or not observation.artifact
                or len(observation.slices) != 1
                or not isinstance(observation.count, int)
                or observation.count <= 0
            ):
                continue
            owner = by_uid.get(observation.series_uid)
            if owner is None:
                continue
            if observation.artifact == str(artifact_of(study_uid, owner.record)):
                arrays = owner.arrays
                record = owner.record
            else:
                source = main_by_artifact.get(observation.artifact)
                if source is None:
                    continue
                record, arrays = source
            z = int(observation.slices[0])
            if observation.support == f"a2_{name}":
                if (
                    observation.row is not None
                    or int(record.get("slice_index", -1)) != z
                ):
                    continue
                mask = arrays.get(observation.support)
                if not isinstance(mask, np.ndarray) or mask.dtype != np.bool_:
                    continue
            elif observation.support == f"a3_recess_plane_{side}_wall":
                if (
                    isinstance(observation.row, bool)
                    or not isinstance(observation.row, int | np.integer)
                    or observation.row < 0
                ):
                    continue
                slices = arrays.get("a3_recess_plane_slices")
                stack = arrays.get(observation.support)
                row = int(observation.row)
                if (
                    not isinstance(slices, np.ndarray)
                    or not isinstance(stack, np.ndarray)
                    or slices.ndim != 1
                    or stack.ndim != 3
                    or not 0 <= row < min(len(slices), stack.shape[0])
                    or int(slices[row]) != z
                    or stack.dtype != np.bool_
                ):
                    continue
                mask = stack[row]
            else:
                continue
            if int(np.count_nonzero(mask)) != observation.count:
                continue
            frame = plane_frame(owner.series, z)
            if isinstance(frame, str):
                considered.append(
                    {
                        "series_uid": owner.record["series_uid"],
                        "slice": z,
                        "status": frame,
                    }
                )
                continue
            area = float(observation.count) * float(np.prod(frame.spacing_rc))
            metadata = {
                "series_uid": observation.series_uid,
                "view": list(observation.view),
                "slices": list(observation.slices),
                "code": observation.code,
                "count": observation.count,
                "area_mm2": area,
                "artifact": observation.artifact,
                "support": observation.support,
                "row": observation.row,
                "label": observation.label,
                "provenance": observation.provenance,
                "source_observation": asdict(observation),
            }
            considered.append(metadata)
            candidates.append((owner, observation, mask, frame, area, metadata))
        if not candidates:
            sources[name] = {
                "status": "unavailable",
                "detail": {"status": "unavailable", "considered": considered},
            }
            continue
        selected = unique_largest(np.asarray([item[4] for item in candidates]))
        if selected is None:
            sources[name] = {
                "status": "tied",
                "detail": {
                    "status": "tied",
                    "candidates": [item[5] for item in candidates],
                },
            }
            continue
        owner, observation, mask, frame, _, metadata = candidates[selected]
        points = frame.to_patient(np.argwhere(mask).astype(float))
        if points.shape != (observation.count, 3) or not np.isfinite(points).all():
            sources[name] = {
                "status": "unavailable",
                "detail": {
                    "status": "unavailable",
                    "code": "selected_source_geometry_unavailable",
                    "selected": metadata,
                },
            }
            continue
        owner.arrays[f"a4_{name}_cross_view_source_lps"] = points
        owner.record[f"a4_{name}_cross_view_source"] = metadata
        handed(f"retinacula_{name}_source", ("points_lps", "metadata"))
        sources[name] = {
            "status": "selected",
            "points": points,
            "metadata": metadata,
            "detail": {"status": "selected", **metadata},
        }
    return sources


def cross_view_retinacula(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    study_uid: str,
    mapping: MapContext | None,
) -> tuple[list[Observation], list[Unresolved]]:
    """Read native sagittal/coronal fluid pockets and their acquired outer dark bands."""
    view = str(own.record["view"][0]).casefold()
    if view not in ("sagittal", "coronal"):
        return [], []
    product = f"{view}_retinacular_outer_bands"
    uid = own.series.row.series_uid
    view_tuple = tuple(own.record["view"])
    details: dict[str, Any] = {"sources": {}, "sides": {}}
    own.record[product] = details
    found: list[Observation] = []
    missing: list[Unresolved] = []
    series = own.series

    def refuse(name: str, code: str) -> None:
        details["sides"].setdefault(name, {})["code"] = code
        missing.append(Unresolved(name, "native", uid, view_tuple, f"{product}:{code}"))

    if view == "coronal" and own.record["assignments"].get("knee") not in ("R", "L"):
        for name in RETINACULA:
            refuse(name, "knee_laterality_unavailable")
        return found, missing
    try:
        sequence_is_fluid_sensitive = (
            int(series.row.fluid_sensitive) == 1
            and int(series.row.fat_suppression) == 1
        )
    except (TypeError, ValueError, OverflowError):
        sequence_is_fluid_sensitive = False
    if not sequence_is_fluid_sensitive:
        for name in RETINACULA:
            refuse(name, "fluid_not_bright_on_this_sequence")
        return found, missing
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        for name in RETINACULA:
            refuse(name, "no_stacked_volume")
        return found, missing
    depth, rows, cols = np.shape(volume)
    recess = own.record.get("recess")
    level = recess.get("level") if isinstance(recess, dict) else None
    try:
        level_values = np.asarray(level, dtype=float).reshape(-1)
        fluid_level = float(level_values[0]) if len(level_values) else float("nan")
    except (TypeError, ValueError, OverflowError):
        fluid_level = float("nan")
    if not np.isfinite(fluid_level) or fluid_level <= 0:
        for name in RETINACULA:
            refuse(name, "same_series_recess_level_unavailable")
        return found, missing
    thickness_values = series.slice_thickness_mm
    try:
        thicknesses = np.asarray(
            [float(value) for value in thickness_values if value is not None],
            dtype=float,
        )
    except (TypeError, ValueError, OverflowError):
        thicknesses = np.empty(0, dtype=float)
    if (
        thicknesses.shape != (depth,)
        or not np.isfinite(thicknesses).all()
        or np.any(thicknesses <= 0)
    ):
        for name in RETINACULA:
            refuse(name, "actual_slice_thickness_unavailable")
        return found, missing

    finite = finite_of(series)
    guide_data: dict[str, Guide | None] = {}
    profiles: dict[str, dict[int, dict[str, Any]]] = {}
    candidate_order: dict[str, list[int]] = {}
    for name in RETINACULA:
        source = sources.get(name, {})
        details["sources"][name] = source.get("detail", source.get("status"))
        if source.get("status") != "selected":
            refuse(
                name,
                "tied_native_axial_sources"
                if source.get("status") == "tied"
                else "no_native_axial_source",
            )
            continue
        points = np.asarray(source["points"], dtype=float)
        reads(f"retinacula_{name}_source", ("points_lps", "metadata"), product)
        guide = mapping.guide(name, own) if mapping is not None else None
        guide_data[name] = guide
        if guide is not None:
            details["sides"].setdefault(name, {})["guide"] = {
                "status": guide.status,
                "slices": list(guide.slices),
                "anchors": list(guide.anchors),
                "placements": list(guide.placements),
                "half_px": guide.half_px,
            }
        per_slice: dict[int, dict[str, Any]] = {}
        counts = np.full(depth, np.nan, dtype=float)
        map_counts = np.full(depth, np.nan, dtype=float)
        statuses = np.zeros(depth, dtype=np.int8)
        complete = np.zeros(depth, dtype=bool)
        for z in range(depth):
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                statuses[z] = 1
                continue
            unique_rc, sample_rc, slab_count, whole, failure = (
                _extensor_source_projection(
                    points, frame, float(thicknesses[z]), (rows, cols)
                )
            )
            if failure is not None:
                statuses[z] = 6
                continue
            if slab_count == 0:
                unique_rc = np.empty((0, 2), dtype=np.int32)
                sample_rc = np.empty((0, 2), dtype=np.int32)
                counts[z] = 0.0
                map_counts[z] = 0.0
                statuses[z] = 2
                per_slice[z] = {"rc": unique_rc, "samples": sample_rc, "complete": True}
                continue
            complete[z] = whole
            counts[z] = float(len(sample_rc))
            in_guide = np.zeros(len(sample_rc), dtype=bool)
            if guide is not None and guide.status == "guided" and z in guide.slices:
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    point = placement.get("point_lps")
                    if placement.get("status") != "ok" or point is None:
                        continue
                    center = np.asarray(
                        frame.to_native(np.asarray([point], dtype=float)), dtype=float
                    )
                    if center.shape == (1, 2) and np.isfinite(center).all():
                        in_guide |= np.all(
                            np.abs(sample_rc - center[0]) <= half + 0.5, axis=1
                        )
            if guide is not None and z in guide.slices:
                map_counts[z] = float(np.count_nonzero(in_guide))
            else:
                map_counts[z] = 0.0
            statuses[z] = 3 if whole else 4
            per_slice[z] = {
                "rc": unique_rc,
                "samples": sample_rc,
                "in_guide": in_guide,
                "complete": whole,
            }
        profiles[name] = per_slice

        def peak_slices(values: np.ndarray) -> set[int]:
            runs = positive_runs(values)
            return {int(z) for run in run_maxima(values, runs) for z in run}

        guided = (
            peak_slices(map_counts)
            if guide is not None and guide.status == "guided"
            else set()
        )
        source_peaks = peak_slices(counts)
        fallback = source_peaks - guided
        candidate_order[name] = sorted(guided) + sorted(fallback)
        details["sides"].setdefault(name, {})["source_profile_review"] = {
            "guided_resolved_profile_count_max": None,
            "stronger_source_peaks_checked": [],
            "source_peaks_skipped_not_stronger": [],
        }
        info = details["sides"].setdefault(name, {})
        info.update(
            profile_status_codes={
                "0": "not_read",
                "1": "frame_unavailable",
                "2": "no_source_points_on_slab",
                "3": "complete_source_projection",
                "4": "partially_clipped_source_projection",
                "6": "source_projection_unavailable",
            },
            candidate_order={
                "map_guided_first": sorted(guided),
                "source_profile_fallback": sorted(fallback),
            },
        )
        prefix = f"a4_{view}_{name}"
        own.arrays[f"{prefix}_profile_count"] = counts
        own.arrays[f"{prefix}_profile_map_count"] = map_counts
        own.arrays[f"{prefix}_profile_status"] = statuses
        own.arrays[f"{prefix}_projection_complete"] = complete
        own.arrays[f"{prefix}_profile_slices"] = np.arange(depth, dtype=np.int32)
        own.arrays[f"{prefix}_profile_slice_thickness_mm"] = thicknesses.copy()
        offsets, coords, map_rows = [0], [], []
        for z in range(depth):
            samples = per_slice.get(z, {}).get(
                "samples", np.empty((0, 2), dtype=np.int32)
            )
            coords.append(samples)
            offsets.append(offsets[-1] + len(samples))
            map_rows.append(
                per_slice.get(z, {}).get("in_guide", np.zeros(len(samples), dtype=bool))
            )
        own.arrays[f"{prefix}_profile_offsets"] = np.asarray(offsets, dtype=np.int64)
        own.arrays[f"{prefix}_profile_rc"] = (
            np.concatenate(coords) if coords else np.empty((0, 2), dtype=np.int32)
        )
        own.arrays[f"{prefix}_profile_in_map"] = (
            np.concatenate(map_rows) if map_rows else np.empty(0, dtype=bool)
        )

    candidate_zs = sorted({z for slices in candidate_order.values() for z in slices})
    if not candidate_zs:
        handed(product, ("native_profiles",))
        reads(product, ("native_profiles",), "retinacular_candidate_selection")
        for name in RETINACULA:
            if name in sources and sources[name].get("status") == "selected":
                refuse(name, "no_source_supported_native_slice")
        return found, missing

    native: dict[int, dict[str, Any]] = {}
    native_context_handed = False

    def native_context(z: int) -> dict[str, Any]:
        if z in native:
            return native[z]
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            native[z] = {"failure": "native_frame_unavailable"}
            return native[z]
        raw = np.asarray(volume[z])
        if raw.shape != (rows, cols) or not np.isfinite(raw).all():
            native[z] = {"failure": "native_plane_unavailable"}
            return native[z]
        _, reading, _ = lens_of(
            series, z, raw, frame, float(own.record["background_split"]), product
        )
        if reading.available is None:
            native[z] = {"failure": "native_availability_unavailable"}
            return native[z]
        field = field_of(series, z, raw, frame, reading)
        available = (
            np.asarray(reading.available, dtype=bool)
            & np.asarray(field.leg, dtype=bool)
            & np.asarray(finite[z], dtype=bool)
            & ~margin_of(uid, z, raw)
        )
        white = np.asarray(raw > fluid_level, dtype=bool)
        fluid = white & available
        labels, components = white_components(fluid, np.asarray(frame.spacing_rc))
        native[z] = {
            "raw": raw,
            "frame": frame,
            "available": available,
            "white": white,
            "fluid": fluid,
            "labels": labels,
            "components": components,
            "measures": measures_of(uid, z, raw, frame),
        }
        nonlocal native_context_handed
        if not native_context_handed:
            handed(product, ("native_context",))
            native_context_handed = True
        reads(product, ("native_context",), "retinacular_native_body_and_wall")
        return native[z]

    artifact = str(artifact_of(study_uid, own.record))

    def section_axis(frame: PlaneFrame) -> int:
        return int(np.argmax(np.abs(np.asarray(frame.basis_lps)[2, :])))

    for name in RETINACULA:
        if name not in profiles:
            continue
        source = sources[name]
        source_meta = source["metadata"]
        side = "medial" if name == RETINACULA[0] else "lateral"
        bodies: list[np.ndarray] = []
        cores: list[np.ndarray] = []
        bands: list[np.ndarray] = []
        strips: list[np.ndarray] = []
        targets: list[np.ndarray] = []
        outward_rows: list[np.ndarray] = []
        section_axes: list[int] = []
        wall_statuses: list[np.ndarray] = []
        row_minima: list[np.ndarray] = []
        adjacent_medians: list[np.ndarray] = []
        body_edges: list[np.ndarray] = []
        codes: list[str] = []
        candidate_rows: list[int] = []
        candidate_details: list[dict[str, Any]] = []
        guided_slices = set(
            details["sides"][name]["candidate_order"]["map_guided_first"]
        )
        source_profile_review = details["sides"][name]["source_profile_review"]
        for z in candidate_order[name]:
            if z not in guided_slices:
                resolved_guided_counts = [
                    int(own.arrays[f"a4_{view}_{name}_profile_count"][row_z])
                    for code, row_z in zip(codes, candidate_rows, strict=True)
                    if code == "identified"
                    and row_z in guided_slices
                    and np.isfinite(
                        own.arrays[f"a4_{view}_{name}_profile_count"][row_z]
                    )
                ]
                if resolved_guided_counts:
                    strongest_guided_count = max(resolved_guided_counts)
                    source_profile_review["guided_resolved_profile_count_max"] = (
                        strongest_guided_count
                    )
                    profile_count = int(
                        own.arrays[f"a4_{view}_{name}_profile_count"][z]
                    )
                    if profile_count <= strongest_guided_count:
                        source_profile_review[
                            "source_peaks_skipped_not_stronger"
                        ].append({"slice": z, "profile_count": profile_count})
                        continue
                    source_profile_review["stronger_source_peaks_checked"].append(
                        {"slice": z, "profile_count": profile_count}
                    )
            context = native_context(z)
            if "failure" in context:
                candidate_details.append({"slice": z, "code": context["failure"]})
                continue
            source_rc = profiles[name][z]["rc"]
            if not len(source_rc):
                continue
            frame = context["frame"]
            measures = context["measures"]
            if view == "sagittal":
                outward = -np.asarray(measures.along(1), dtype=float)
            else:
                inner = np.asarray(measures.along(0), dtype=float)
                if own.record["assignments"].get("knee") != "R":
                    inner = -inner
                outward = inner if side == "medial" else -inner
            body, core, selection = closest_white_body(
                context["labels"],
                context["components"],
                source_rc,
                frame,
                outward,
                require_inward=view == "coronal",
            )
            axis = section_axis(frame)
            wall = (
                relative_outer_wall(
                    context["raw"],
                    body,
                    context["white"],
                    context["available"],
                    outward,
                    axis,
                    SHELL_MM,
                )
                if body.any()
                else {
                    "strip": np.zeros((rows, cols), dtype=bool),
                    "minimum_band": np.zeros((rows, cols), dtype=bool),
                    "status": np.zeros(
                        rows if section_axis(frame) == 0 else cols, dtype=np.int8
                    ),
                    "body_outer_edge_mm": np.full(
                        rows if section_axis(frame) == 0 else cols, np.nan
                    ),
                    "row_minimum": np.full(
                        rows if section_axis(frame) == 0 else cols, np.nan
                    ),
                    "adjacent_median": np.full(
                        rows if section_axis(frame) == 0 else cols, np.nan
                    ),
                }
            )
            count = int(np.count_nonzero(wall["minimum_band"]))
            code = "identified" if count else str(selection["status"])
            if body.any() and not count:
                if np.any(wall["status"] == 2):
                    code = "disconnected_outer_minima"
                elif np.any(wall["status"] == 3):
                    code = "outer_minimum_not_darker_than_body"
                else:
                    code = "no_outer_band_in_shell"
            if not profiles[name][z]["complete"] and not count:
                code = "partial_source_projection_no_outer_band"
            candidate_rows.append(z)
            candidate_details.append(
                {
                    "slice": z,
                    "code": code,
                    "selection": {
                        key: value
                        for key, value in selection.items()
                        if key != "components"
                    },
                    "component_candidates": selection.get("components", []),
                    "profile_count": None
                    if not np.isfinite(own.arrays[f"a4_{view}_{name}_profile_count"][z])
                    else int(own.arrays[f"a4_{view}_{name}_profile_count"][z]),
                    "profile_map_count": None
                    if not np.isfinite(
                        own.arrays[f"a4_{view}_{name}_profile_map_count"][z]
                    )
                    else int(own.arrays[f"a4_{view}_{name}_profile_map_count"][z]),
                    "projection_complete": bool(profiles[name][z]["complete"]),
                    "body_count": int(body.sum()),
                    "core_count": int(core.sum()),
                    "outer_band_count": count,
                }
            )
            bodies.append(body)
            cores.append(core)
            bands.append(np.asarray(wall["minimum_band"], dtype=bool))
            strips.append(np.asarray(wall["strip"], dtype=bool))
            target = np.zeros((rows, cols), dtype=bool)
            target[source_rc[:, 0], source_rc[:, 1]] = True
            targets.append(target)
            outward_rows.append(outward)
            section_axes.append(axis)
            wall_statuses.append(np.asarray(wall["status"], dtype=np.int8))
            row_minima.append(np.asarray(wall["row_minimum"], dtype=float))
            adjacent_medians.append(np.asarray(wall["adjacent_median"], dtype=float))
            body_edges.append(np.asarray(wall["body_outer_edge_mm"], dtype=float))
            codes.append(code)
            if not profiles[name][z]["complete"]:
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view_tuple,
                        f"{product}:partial_source_projection_at_slice_{z}",
                    )
                )

        prefix = f"a4_{view}_{name}"
        slices_name = f"{prefix}_slices"
        support = f"{prefix}_outer_wall"
        own.arrays[slices_name] = np.asarray(candidate_rows, dtype=np.int32)
        for suffix, items, dtype in (
            ("body", bodies, bool),
            ("core", cores, bool),
            ("outer_wall", bands, bool),
            ("strip", strips, bool),
            ("source_target", targets, bool),
            ("outward_mm", outward_rows, float),
            ("outer_wall_status", wall_statuses, np.int8),
            ("outer_wall_row_minimum", row_minima, float),
            ("outer_wall_adjacent_median", adjacent_medians, float),
            ("body_outer_edge_mm", body_edges, float),
        ):
            own.arrays[f"{prefix}_{suffix}"] = (
                np.stack(items) if items else np.empty((0, rows, cols), dtype=dtype)
            )
        own.arrays[f"{prefix}_candidate_codes"] = np.asarray(codes, dtype="U64")
        own.arrays[f"{prefix}_wall_section_axis"] = np.asarray(
            section_axes, dtype=np.int8
        )
        details["sides"][name].update(
            source=source_meta,
            fluid_level=fluid_level,
            calibration="same_series_recess_profile",
            profile=[
                {
                    "slice": z,
                    "count": None
                    if not np.isfinite(own.arrays[f"{prefix}_profile_count"][z])
                    else int(own.arrays[f"{prefix}_profile_count"][z]),
                    "map_count": None
                    if not np.isfinite(own.arrays[f"{prefix}_profile_map_count"][z])
                    else int(own.arrays[f"{prefix}_profile_map_count"][z]),
                    "status": int(own.arrays[f"{prefix}_profile_status"][z]),
                    "projection_complete": bool(
                        own.arrays[f"{prefix}_projection_complete"][z]
                    ),
                }
                for z in range(depth)
            ],
            native_candidates=candidate_details,
        )
        if not candidate_rows:
            refuse(name, "no_native_candidate_frame_read")
            continue
        handed(product, ("native_selected_supports",))
        reads(product, ("native_selected_supports",), "retinacular_observations")
        for row, z in enumerate(candidate_rows):
            code = codes[row]
            count = int(np.count_nonzero(bands[row]))
            if code == "tied_nearest_native_white_bodies":
                missing.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view_tuple,
                        f"{product}:tied_nearest_white_bodies_at_slice_{z}",
                    )
                )
            resolved = count > 0
            found.append(
                observe_in(
                    own.record,
                    name,
                    "native",
                    "resolved" if resolved else "reading",
                    (z,),
                    "identified" if resolved else f"abstain_{code}",
                    count,
                    0.0,
                    support,
                    "The native low-signal outer band immediately outside the same-series calibrated patellofemoral fluid body; axial retinacular points locate the question, not this band boundary or its full course.",
                    artifact,
                    row,
                    None,
                )
            )
        if mapping is not None:
            guide = guide_data.get(name)
            guided = (
                set(details["sides"][name]["candidate_order"]["map_guided_first"])
                if guide is not None and guide.status == "guided"
                else set()
            )
            hit = any(
                codes[i] == "identified" and z in guided
                for i, z in enumerate(candidate_rows)
            )
            stronger_checked = details["sides"][name]["source_profile_review"][
                "stronger_source_peaks_checked"
            ]
            outcome = (
                "guided_hit_source_profile_stronger_checked"
                if hit and stronger_checked
                else "guided_hit"
                if hit
                else "source_profile_after_map_miss"
                if guide is not None and guide.status == "guided"
                else "source_profile_only"
            )
            mapping.smap.note_use(
                name,
                uid,
                outcome,
                question=product,
                anchors=[] if guide is None else list(guide.anchors),
                candidate_slices=candidate_rows,
                source_profile_review=details["sides"][name]["source_profile_review"],
            )
    handed(product, ("native_profiles",))
    reads(product, ("native_profiles",), "retinacular_candidate_selection")
    if any("failure" not in context for context in native.values()):
        handed(product, ("native_bodies", "outer_strips", "outer_walls"))
        reads(
            product,
            ("native_bodies", "outer_strips", "outer_walls"),
            "retinacular_candidate_measurement",
        )
    context_slices = np.asarray(
        [z for z, context in sorted(native.items()) if "failure" not in context],
        dtype=np.int32,
    )
    own.arrays[f"a4_{view}_retinacula_context_slices"] = context_slices
    for suffix, key, dtype in (
        ("white", "white", bool),
        ("fluid", "fluid", bool),
        ("available", "available", bool),
        ("component_labels", "labels", np.int32),
    ):
        context_rows = [native[int(z)][key] for z in context_slices]
        own.arrays[f"a4_{view}_retinacula_context_{suffix}"] = (
            np.stack(context_rows)
            if context_rows
            else np.empty((0, rows, cols), dtype=dtype)
        )
    return found, missing


def name_cross_view_retinacula(
    measured: list[Measured],
    pointed: list[tuple[list[Observation], list[Unresolved]]],
    main_found: list[tuple[dict, dict[str, np.ndarray]]],
    study_uid: str,
    mapping: MapContext | None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    sources = retinacular_sources(measured, pointed, main_found, study_uid)
    return [cross_view_retinacula(own, sources, study_uid, mapping) for own in measured]


def native_fat_pad_sources(
    measured: list[Measured], study_uid: str
) -> dict[str, dict[str, Any]]:
    """Keep each uniquely largest identified native sagittal fat-pad source in LPS."""
    names = (
        "hoffa_fat_pad",
        "quadriceps_fat_pad",
        "prefemoral_fat_pad",
        "suprapatellar_fat",
    )
    candidates: dict[
        str, list[tuple[Measured, np.ndarray, PlaneFrame, float, dict]]
    ] = {name: [] for name in names}
    considered: dict[str, list[dict[str, Any]]] = {name: [] for name in names}
    for own in measured:
        view = tuple(own.record.get("view", ()))
        try:
            source_sequence = (
                int(own.series.row.fluid_sensitive),
                int(own.series.row.fat_suppression),
            )
        except (AttributeError, TypeError, ValueError, OverflowError):
            continue
        if (
            len(view) != 3
            or str(view[0]).casefold() != "sagittal"
            or source_sequence != (1, 1)
        ):
            continue
        for name in names:
            if (
                own.record.get("assignments", {}).get("codes", {}).get(name)
                != "identified"
            ):
                continue
            support = (
                "a1_objects"
                if name in ("hoffa_fat_pad", "suprapatellar_fat")
                else f"a2_{name}"
            )
            if support == "a1_objects":
                values = own.arrays.get(support)
                mask = (
                    values == OBJECT_CODES[name]
                    if isinstance(values, np.ndarray)
                    and values.ndim == 2
                    and values.dtype.kind in "iu"
                    and values.shape == np.shape(own.arrays.get("acquired_plane"))
                    else None
                )
            else:
                mask = own.arrays.get(support)
            if (
                not isinstance(mask, np.ndarray)
                or mask.dtype.kind != "b"
                or mask.shape != np.shape(own.arrays.get("acquired_plane"))
                or not mask.any()
            ):
                considered[name].append(
                    {
                        "series_uid": own.record.get("series_uid"),
                        "slice": own.record.get("slice_index"),
                        "support": support,
                        "status": "native_source_support_unavailable",
                    }
                )
                continue
            frame = own.frame
            try:
                spacing = np.asarray(frame.spacing_rc, dtype=float)
                if (
                    spacing.shape != (2,)
                    or not np.isfinite(spacing).all()
                    or np.any(spacing <= 0)
                ):
                    raise ValueError("source_spacing_unavailable")
                area = float(np.count_nonzero(mask)) * float(np.prod(spacing))
            except (AttributeError, TypeError, ValueError, OverflowError):
                considered[name].append(
                    {
                        "series_uid": own.record.get("series_uid"),
                        "slice": own.record.get("slice_index"),
                        "support": support,
                        "count": int(np.count_nonzero(mask)),
                        "status": "native_source_geometry_unavailable",
                    }
                )
                continue
            metadata = {
                "series_uid": own.record["series_uid"],
                "view": list(view),
                "slice": int(own.record["slice_index"]),
                "support": support,
                "label": OBJECT_CODES[name] if support == "a1_objects" else None,
                "count": int(np.count_nonzero(mask)),
                "area_mm2": area,
                "artifact": str(artifact_of(study_uid, own.record)),
                "provenance": "native",
                "code": "identified",
            }
            considered[name].append({**metadata, "status": "eligible"})
            candidates[name].append((own, mask, frame, area, metadata))

    sources: dict[str, dict[str, Any]] = {}
    for name in names:
        entries = candidates[name]
        if not entries:
            sources[name] = {
                "status": "unavailable",
                "detail": {"status": "unavailable", "considered": considered[name]},
            }
            continue
        selected = unique_largest(np.asarray([item[3] for item in entries]))
        if selected is None:
            sources[name] = {
                "status": "tied",
                "detail": {
                    "status": "tied",
                    "candidates": [item[4] for item in entries],
                    "considered": considered[name],
                },
            }
            continue
        own, mask, frame, _, metadata = entries[selected]
        try:
            points = np.asarray(
                frame.to_patient(np.argwhere(mask).astype(float)), dtype=float
            )
        except (
            AttributeError,
            FloatingPointError,
            TypeError,
            ValueError,
            np.linalg.LinAlgError,
        ):
            points = np.empty((0, 3), dtype=float)
        if points.shape != (metadata["count"], 3) or not np.isfinite(points).all():
            sources[name] = {
                "status": "unavailable",
                "detail": {
                    "status": "unavailable",
                    "code": "selected_source_geometry_unavailable",
                    "selected": metadata,
                    "considered": considered[name],
                },
            }
            continue
        owner_array = f"a4_{name}_fat_source_lps"
        owner_record = f"a4_{name}_fat_source"
        own.arrays[owner_array] = points
        own.record[owner_record] = metadata
        product = f"native_fat_{name}_source"
        handed(product, ("points_lps", "metadata"))
        sources[name] = {
            "status": "selected",
            "points": points,
            "metadata": metadata,
            "owner": own,
            "detail": {"status": "selected", **metadata},
        }
    return sources


def native_fat_opposed_calibrations(
    measured: list[Measured],
) -> dict[str, dict[str, Any]]:
    """Read each non-fat-suppressed series' own femoral marrow light once."""
    product = "native_fat_opposed_calibration"
    calibrations: dict[str, dict[str, Any]] = {}
    for own in measured:
        uid = str(own.record["series_uid"])
        try:
            fat_suppression = int(own.series.row.fat_suppression)
        except (AttributeError, TypeError, ValueError, OverflowError):
            calibrations[uid] = {"status": "sequence_unavailable"}
            continue
        if fat_suppression != 0:
            continue
        view = tuple(own.record.get("view", ()))
        codes = own.record.get("assignments", {}).get("codes", {})
        femur_code = codes.get("femur")
        objects = own.arrays.get("a1_objects")
        plane = own.arrays.get("acquired_plane")
        if (
            femur_code not in ("identified", "agreed_with_its_partner")
            or not isinstance(objects, np.ndarray)
            or objects.ndim != 2
            or not isinstance(plane, np.ndarray)
            or plane.ndim != 2
            or objects.shape != plane.shape
        ):
            calibrations[uid] = {
                "status": "native_femur_calibration_unavailable",
                "series_uid": uid,
                "view": list(view),
            }
            continue
        femur = objects == OBJECT_CODES["femur"]
        if not femur.any() or not np.isfinite(plane[femur]).all():
            calibrations[uid] = {
                "status": "native_femur_calibration_unavailable",
                "series_uid": uid,
                "view": list(view),
                "support": "a1_objects",
                "count": int(femur.sum()),
            }
            continue
        reads("naming", field_names(own.assignment), product)
        level = measures_of(
            uid, int(own.record["slice_index"]), plane, own.frame
        ).light(femur)
        threshold = float(LIKE_THE_FEMUR[0]) * level
        if not np.isfinite(threshold) or threshold <= 0.0:
            calibrations[uid] = {
                "status": "native_femur_calibration_unavailable",
                "series_uid": uid,
                "view": list(view),
                "support": "a1_objects",
                "count": int(femur.sum()),
                "femur_light": level,
            }
            continue
        calibration = {
            "status": "calibrated",
            "series_uid": uid,
            "view": list(view),
            "support": "a1_objects",
            "source_code": femur_code,
            "count": int(femur.sum()),
            "femur_light": level,
            "threshold": threshold,
            "relation": "LIKE_THE_FEMUR[0] times this series' own middle-slice femoral marrow light",
        }
        own.record["a4_fat_opposed_calibration"] = calibration
        handed(product, ("threshold", "source"))
        calibrations[uid] = calibration
    return calibrations


def native_fat_source_profiles(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    mapping: MapContext | None,
) -> dict[str, dict[str, Any]]:
    """Retain actual-slab source samples and map-window counts on axial/coronal stacks."""
    view = tuple(own.record.get("view", ()))
    if not view or str(view[0]).casefold() not in ("axial", "coronal"):
        return {}
    orientation = str(view[0]).casefold()
    if not any(
        sources.get(name, {}).get("status") == "selected"
        for name in (
            "hoffa_fat_pad",
            "quadriceps_fat_pad",
            "prefemoral_fat_pad",
            "suprapatellar_fat",
        )
    ):
        return {}
    series = own.series
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return {}
    depth, rows, cols = np.shape(volume)
    raw_thicknesses = series.slice_thickness_mm
    try:
        thicknesses = tuple(
            None if value is None else float(value) for value in raw_thicknesses
        )
    except (TypeError, ValueError, OverflowError):
        thicknesses = ()
    if len(thicknesses) != depth:
        thicknesses = (None,) * depth

    def maxima(values: np.ndarray) -> list[int]:
        runs = positive_runs(values)
        return sorted({int(z) for run in run_maxima(values, runs) for z in run})

    output: dict[str, dict[str, Any]] = {}
    for name in (
        "hoffa_fat_pad",
        "quadriceps_fat_pad",
        "prefemoral_fat_pad",
        "suprapatellar_fat",
    ):
        source = sources.get(name, {})
        prefix = f"a4_{orientation}_{name}_source"
        if source.get("status") != "selected":
            own.record.setdefault("a4_native_fat_profiles", {})[name] = {
                "source_status": source.get("status", "unavailable"),
                "detail": source.get("detail"),
            }
            continue
        points = np.asarray(source.get("points"), dtype=float)
        metadata = source.get("metadata")
        if (
            points.ndim != 2
            or points.shape[1:] != (3,)
            or not len(points)
            or not np.isfinite(points).all()
            or not isinstance(metadata, dict)
        ):
            continue
        source_product = f"native_fat_{name}_source"
        reads(source_product, ("points_lps", "metadata"), "native_fat_source_profiles")
        guide = None if mapping is None else mapping.guide(name, own)
        counts = np.full(depth, np.nan, dtype=np.float64)
        map_counts = np.full(depth, np.nan, dtype=np.float64)
        statuses = np.zeros(depth, dtype=np.int8)
        complete = np.zeros(depth, dtype=bool)
        per_slice: dict[int, dict[str, np.ndarray]] = {}
        for z in range(depth):
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                statuses[z] = 1
                continue
            thickness = thicknesses[z]
            if thickness is None or not np.isfinite(thickness) or thickness <= 0:
                statuses[z] = 6
                continue
            unique_rc, sample_rc, slab_count, whole, failure = (
                _extensor_source_projection(points, frame, thickness, (rows, cols))
            )
            if failure is not None:
                statuses[z] = 6
                continue
            if slab_count == 0:
                counts[z] = map_counts[z] = 0.0
                statuses[z] = 2
                complete[z] = True
                per_slice[z] = {
                    "unique_rc": unique_rc,
                    "sample_rc": sample_rc,
                    "in_map": np.zeros(len(sample_rc), dtype=bool),
                }
                continue
            complete[z] = whole
            counts[z] = float(len(sample_rc))
            in_map = np.zeros(len(sample_rc), dtype=bool)
            if guide is not None and guide.status == "guided" and z in guide.slices:
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    point = placement.get("point_lps")
                    if placement.get("status") != "ok" or point is None:
                        continue
                    try:
                        center = np.asarray(
                            frame.to_native(np.asarray([point], dtype=float)),
                            dtype=float,
                        )
                    except (
                        TypeError,
                        ValueError,
                        OverflowError,
                        np.linalg.LinAlgError,
                    ):
                        continue
                    if center.shape == (1, 2) and np.isfinite(center).all():
                        in_map |= np.all(
                            np.abs(sample_rc - center[0]) <= half + 0.5, axis=1
                        )
            map_counts[z] = float(np.count_nonzero(in_map))
            statuses[z] = 3 if whole else 4
            per_slice[z] = {
                "unique_rc": unique_rc,
                "sample_rc": sample_rc,
                "in_map": in_map,
            }
        guided = (
            maxima(map_counts) if guide is not None and guide.status == "guided" else []
        )
        source_peaks = maxima(counts)
        fallback = sorted(set(source_peaks) - set(guided))
        own.arrays[f"{prefix}_profile_slices"] = np.arange(depth, dtype=np.int32)
        own.arrays[f"{prefix}_profile_count"] = counts
        own.arrays[f"{prefix}_profile_map_count"] = map_counts
        own.arrays[f"{prefix}_profile_status"] = statuses
        own.arrays[f"{prefix}_projection_complete"] = complete
        offsets = [0]
        unique_offsets = [0]
        sample_coords: list[np.ndarray] = []
        unique_coords: list[np.ndarray] = []
        map_rows: list[np.ndarray] = []
        for z in range(depth):
            item = per_slice.get(z, {})
            samples = item.get("sample_rc", np.empty((0, 2), dtype=np.int32))
            unique_rc = item.get("unique_rc", np.empty((0, 2), dtype=np.int32))
            map_row = item.get("in_map", np.zeros(len(samples), dtype=bool))
            sample_coords.append(samples)
            unique_coords.append(unique_rc)
            map_rows.append(map_row)
            offsets.append(offsets[-1] + len(samples))
            unique_offsets.append(unique_offsets[-1] + len(unique_rc))
        own.arrays[f"{prefix}_profile_offsets"] = np.asarray(offsets, dtype=np.int64)
        own.arrays[f"{prefix}_profile_rc"] = (
            np.concatenate(sample_coords)
            if sample_coords
            else np.empty((0, 2), dtype=np.int32)
        )
        own.arrays[f"{prefix}_profile_in_map"] = (
            np.concatenate(map_rows) if map_rows else np.empty(0, dtype=bool)
        )
        own.arrays[f"{prefix}_profile_unique_offsets"] = np.asarray(
            unique_offsets, dtype=np.int64
        )
        own.arrays[f"{prefix}_profile_unique_rc"] = (
            np.concatenate(unique_coords)
            if unique_coords
            else np.empty((0, 2), dtype=np.int32)
        )
        details = {
            "source_status": "selected",
            "source": metadata,
            "guide": None
            if guide is None
            else {
                "status": guide.status,
                "slices": list(guide.slices),
                "placements": list(guide.placements),
                "half_px": guide.half_px,
                "anchors": list(guide.anchors),
            },
            "profile_status_codes": {
                "0": "not_read",
                "1": "frame_unavailable",
                "2": "no_source_points_on_slab",
                "3": "complete_source_projection",
                "4": "partially_clipped_source_projection",
                "6": "source_projection_unavailable",
            },
            "profile": [
                {
                    "slice": int(z),
                    "count": None if not np.isfinite(counts[z]) else int(counts[z]),
                    "map_count": None
                    if not np.isfinite(map_counts[z])
                    else int(map_counts[z]),
                    "status": int(statuses[z]),
                    "projection_complete": bool(complete[z]),
                    "unique_pixels": len(per_slice.get(z, {}).get("unique_rc", ())),
                }
                for z in range(depth)
            ],
            "candidate_order": {
                "map_guided_first": guided,
                "source_profile_fallback": fallback,
            },
        }
        own.record.setdefault("a4_native_fat_profiles", {})[name] = details
        output[name] = {
            "counts": counts,
            "map_counts": map_counts,
            "statuses": statuses,
            "complete": complete,
            "per_slice": per_slice,
            "guide": guide,
            "guided": guided,
            "source_peaks": source_peaks,
            "fallback": fallback,
        }
    if output:
        handed("native_fat_source_profiles", ("profiles", "candidate_order"))
    return output


def native_femur_coarse_context(
    own: Measured,
    z: int,
    raw: np.ndarray,
    frame: PlaneFrame,
    leg: "Leg | None",
) -> dict[str, Any]:
    """Share the carried-leg 2 mm femur enclosure for one actual native frame."""
    series = own.series
    uid = str(own.record["series_uid"])

    def measure() -> dict[str, Any]:
        if leg is None:
            return {"status": "carried_leg_unavailable"}
        if raw.ndim != 2:
            return {"status": "native_plane_unavailable"}
        try:
            thicknesses = series.slice_thickness_mm
            raw_thickness = thicknesses[z]
            if raw_thickness is None:
                return {"status": "slice_thickness_unavailable"}
            thickness = float(raw_thickness)
        except (AttributeError, IndexError, TypeError, ValueError, OverflowError):
            return {"status": "slice_thickness_unavailable"}
        if not np.isfinite(thickness) or thickness <= 0.0:
            return {"status": "slice_thickness_unavailable"}
        reads("leg", ("femur_lps", "tibia_lps"), "native_femur_coarse_context")
        try:
            femur_seed, tibia_seed = leg_on(leg, series, z, frame, raw.shape, thickness)
        except (AttributeError, TypeError, ValueError, OverflowError):
            return {"status": "carried_leg_projection_unavailable"}
        if (
            femur_seed.shape != raw.shape
            or tibia_seed.shape != raw.shape
            or femur_seed.dtype.kind != "b"
            or tibia_seed.dtype.kind != "b"
        ):
            return {"status": "carried_leg_projection_unavailable"}
        if not femur_seed.any():
            return {
                "status": "no_femur_seed_on_native_slice",
                "femur_seed": femur_seed,
                "tibia_seed": tibia_seed,
            }
        dark = int(series.row.fat_suppression) == 1
        reading = once(
            "coarse_axial_blocks",
            (uid, z, LIGAMENT_SMOOTH_MM),
            lambda: block_medians(
                raw,
                margin_of(uid, z, raw) | ~np.isfinite(raw),
                frame.spacing_rc,
                LIGAMENT_SMOOTH_MM,
            ),
        )
        depth = once(
            "coarse_axial_depth",
            (uid, z, dark),
            lambda: handed_on(coarse_depth(reading.median, dark)),
        )
        reads(
            "coarse_axial_blocks",
            ("median", "block_px", "block_mm", "window_rc"),
            "native_femur_coarse_context",
        )
        reads("coarse_axial_depth", ("depth",), "native_femur_coarse_context")
        femur_blocks = block_holds(femur_seed, reading)
        tibia_blocks = block_holds(tibia_seed, reading)
        result = coarse_section(
            depth,
            femur_blocks,
            float(np.prod(reading.block_mm)),
            {"tibia": tibia_blocks},
        )
        native_core = np.zeros(raw.shape, dtype=bool)
        if result.body is not None:
            r0, r1, c0, c1 = reading.window_rc
            expanded = np.repeat(
                np.repeat(result.body, reading.block_px[0], axis=0),
                reading.block_px[1],
                axis=1,
            )
            native_core[r0:r1, c0:c1] = expanded[: r1 - r0, : c1 - c0]
        context = {
            "status": result.status,
            "femur_seed": femur_seed,
            "tibia_seed": tibia_seed,
            "femur_blocks": femur_blocks,
            "tibia_blocks": tibia_blocks,
            "block_reading": reading,
            "depth": np.asarray(depth),
            "section": result,
            "native_core": native_core,
            "dark_marrow": dark,
        }
        handed(
            "native_femur_coarse_context",
            (
                "femur_seed",
                "tibia_seed",
                "femur_blocks",
                "tibia_blocks",
                "block_reading",
                "depth",
                "section",
                "native_core",
                "dark_marrow",
                "status",
            ),
        )
        return context

    identity = None if leg is None else (leg.identity or leg_identity(leg))
    key = (uid, int(z), identity, tuple(raw.shape), digest(np.asarray(raw)))
    return once("native_femur_coarse_context", key, measure)


def native_fat_coarse_femur_context(
    own: Measured,
    z: int,
    raw: np.ndarray,
    frame: PlaneFrame,
    leg: "Leg | None",
) -> dict[str, Any]:
    """Keep the fat reader's existing product over the shared native femur context."""
    context = native_femur_coarse_context(own, z, raw, frame, leg)
    if context.get("block_reading") is None:
        return context
    reads(
        "native_femur_coarse_context",
        ("block_reading", "depth", "section", "native_core", "status"),
        "native_fat_femur_core",
    )
    handed(
        "native_fat_femur_core",
        (
            "femur_seed",
            "tibia_seed",
            "block_reading",
            "depth",
            "section",
            "native_core",
        ),
    )
    reads(
        "native_fat_femur_core",
        ("femur_seed", "tibia_seed", "section", "native_core"),
        "native_fat_gradient_markers",
    )
    return context


def native_meniscus_sources(
    measured: list[Measured],
    study_uid: str,
    *,
    orientation: str = "coronal",
    pending: list[tuple[list[Observation], list[Unresolved]]] | None = None,
) -> dict[str, dict[str, Any]]:
    """Keep native source sections, validate their saved addresses, and rank by area."""
    if orientation not in ("coronal", "sagittal"):
        raise ValueError("unsupported_meniscus_source_orientation")
    labels = {
        "medial_meniscus": OBJECT_CODES["medial_meniscus"],
        "lateral_meniscus": OBJECT_CODES["lateral_meniscus"],
    }
    pending_by_owner = {}
    if orientation == "sagittal":
        if pending is None:
            raise ValueError("sagittal_meniscus_pending_observations_required")
        for own, (rows, _) in zip(measured, pending, strict=True):
            pending_by_owner[id(own)] = rows
    collected = {name: [] for name in labels}
    for own in measured:
        record = own.record
        view = tuple(record.get("view", ()))
        if (
            len(view) != 3
            or view[0].casefold() != orientation
            or view[1:] != ("1", "1")
        ):
            continue
        if (
            getattr(own.series.row, "fluid_sensitive", None) != "1"
            or getattr(own.series.row, "fat_suppression", None) != "1"
        ):
            continue
        uid = str(record.get("series_uid", ""))
        artifact = str(artifact_of(study_uid, record))
        if orientation == "coronal":
            rows = record.get("observations", ())
        else:
            rows = pending_by_owner.get(id(own), ())
        for row in rows:
            fields = (
                row
                if isinstance(row, dict)
                else {
                    key: getattr(row, key, None)
                    for key in (
                        "object",
                        "provenance",
                        "kind",
                        "series_uid",
                        "view",
                        "slices",
                        "code",
                        "count",
                        "support",
                        "artifact",
                        "row",
                        "label",
                    )
                }
            )
            name = fields.get("object")
            if name not in labels:
                continue
            label = labels[name]
            slices = tuple(fields.get("slices") or ())
            if len(slices) != 1 or isinstance(slices[0], bool):
                continue
            z = int(slices[0])
            expected_support = (
                "a1_objects" if orientation == "coronal" else f"a4_{name}_z{z}_support"
            )
            if not (
                fields.get("provenance") == "native"
                and fields.get("kind") == "resolved"
                and fields.get("code") == "identified"
                and fields.get("series_uid") == uid
                and tuple(fields.get("view") or ()) == view
                and fields.get("support") == expected_support
                and fields.get("artifact") == artifact
                and fields.get("row") is None
                and (
                    fields.get("label") == label
                    if orientation == "coronal"
                    else fields.get("label") is None
                )
            ):
                continue
            volume = own.series.volume
            if volume is None or not 0 <= z < len(volume):
                continue
            if orientation == "coronal":
                objects = own.arrays.get("a1_objects")
                middle = record.get("slice_index")
                if (
                    not isinstance(objects, np.ndarray)
                    or objects.ndim != 2
                    or objects.dtype.kind not in "iu"
                    or objects.shape != np.shape(volume[z])
                    or isinstance(middle, bool)
                    or middle is None
                    or z != int(middle)
                ):
                    continue
                support = objects == label
            else:
                support = own.arrays.get(expected_support)
                if (
                    not isinstance(support, np.ndarray)
                    or support.ndim != 2
                    or support.dtype.kind != "b"
                    or support.shape != np.shape(volume[z])
                ):
                    continue
                address = own.arrays.get(f"{expected_support}_slices")
                if not isinstance(address, np.ndarray) or np.asarray(address).reshape(
                    -1
                ).tolist() != [z]:
                    continue
            points_rc = np.argwhere(support).astype(np.float64)
            count = len(points_rc)
            if count == 0 or fields.get("count") != count:
                continue
            frame = plane_frame(own.series, z)
            if isinstance(frame, str):
                continue
            try:
                points_lps = np.asarray(frame.to_patient(points_rc), dtype=np.float64)
                pixel_area = float(np.prod(frame.spacing_rc))
            except (
                AttributeError,
                TypeError,
                ValueError,
                FloatingPointError,
                np.linalg.LinAlgError,
            ):
                continue
            if (
                points_lps.shape != (count, 3)
                or not np.isfinite(points_lps).all()
                or not np.isfinite(pixel_area)
                or pixel_area <= 0
            ):
                continue
            metadata = {
                "series_uid": uid,
                "view": list(view),
                "slice": z,
                "support": expected_support,
                "support_slices": [z] if orientation == "sagittal" else None,
                "row": None,
                "label": label if orientation == "coronal" else None,
                "count": count,
                "pixel_area_mm2": pixel_area,
                "physical_area_mm2": count * pixel_area,
                "artifact": artifact,
                "provenance": "native",
                "code": "identified",
                "kind": "resolved",
            }
            collected[name].append((own, points_lps, metadata))

    product = (
        "native_meniscus_sources"
        if orientation == "coronal"
        else "native_sagittal_meniscus_sources"
    )
    array_tag = "" if orientation == "coronal" else "sagittal_"
    record_key = (
        "a4_meniscus_sources"
        if orientation == "coronal"
        else "a4_sagittal_meniscus_sources"
    )
    result = {}
    for name, entries in collected.items():
        owners: dict[int, list] = {}
        for entry in entries:
            owners.setdefault(id(entry[0]), []).append(entry)
        for group in owners.values():
            owner = group[0][0]
            point_rows, metadata, offsets = [], [], [0]
            for _, points, meta in group:
                point_rows.append(points)
                metadata.append({**meta, "point_offset": offsets[-1]})
                offsets.append(offsets[-1] + len(points))
            owner.arrays[f"a4_{array_tag}{name}_source_lps"] = np.concatenate(
                point_rows, axis=0
            )
            owner.arrays[f"a4_{array_tag}{name}_source_offsets"] = np.asarray(
                offsets, dtype=np.int64
            )
            owner.record.setdefault(record_key, {})[name] = metadata
            handed(product, ("points_lps", "offsets", "metadata"))
        ranked = sorted(
            entries, key=lambda entry: entry[2]["physical_area_mm2"], reverse=True
        )
        largest = ranked[0][2]["physical_area_mm2"] if ranked else None
        winners = (
            [entry for entry in ranked if entry[2]["physical_area_mm2"] == largest]
            if ranked
            else []
        )
        result[name] = {
            "status": "selected"
            if len(winners) == 1
            else "tied"
            if winners
            else "unavailable",
            "selected": None
            if len(winners) != 1
            else {
                "owner": winners[0][0],
                "points_lps": winners[0][1],
                "metadata": winners[0][2],
            },
            "entries": [entry[2] for entry in entries],
            "point_count": sum(len(entry[1]) for entry in entries),
            "largest_physical_area_mm2": largest,
            "product": product,
        }
    return result


def native_meniscus_profiles(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    mapping: MapContext | None,
    *,
    orientation: str = "sagittal",
    source_tag: str = "",
    names: tuple[str, ...] = ("medial_meniscus", "lateral_meniscus"),
    profile_product: str | None = None,
    sources_product: str | None = None,
) -> dict[str, Any] | None:
    """Measure source projections through actual target half-slabs and retain every address."""
    if orientation not in ("sagittal", "axial", "coronal"):
        raise ValueError("unsupported_meniscus_profile_orientation")
    view = tuple(own.record.get("view", ()))
    if len(view) != 3 or view[0].casefold() != orientation or view[1:] != ("1", "1"):
        return None
    profiles: dict[str, Any] = {}
    selected_sources = {name: sources.get(name, {}) for name in names}
    for name, source in selected_sources.items():
        if source.get("status") != "selected":
            profiles[name] = {"status": source.get("status", "unavailable")}
    if not any(
        source.get("status") == "selected" for source in selected_sources.values()
    ):
        return profiles
    volume = own.series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        own.record[f"a4_{orientation}_meniscus_profile_status"] = (
            "native_volume_unavailable"
        )
        return profiles
    depth, rows, cols = np.shape(volume)
    thicknesses = tuple(getattr(own.series, "slice_thickness_mm", ()))
    if orientation == "sagittal":
        product = "native_sagittal_meniscus_profiles"
    elif orientation == "axial":
        product = (
            "native_axial_sagittal_meniscus_profiles"
            if source_tag == "sagittal"
            else "native_axial_meniscus_profiles"
        )
    else:
        product = f"native_coronal_pcl_{source_tag or 'sagittal'}_profiles"
    if orientation == "coronal":
        source_product = (
            "native_axial_pcl_sources"
            if source_tag == "axial"
            else "native_pcl_sources"
        )
    else:
        source_product = (
            "native_sagittal_meniscus_sources"
            if source_tag == "sagittal"
            else "native_meniscus_sources"
        )
    product = profile_product or product
    source_product = sources_product or source_product
    for name, source in selected_sources.items():
        if source.get("status") != "selected":
            continue
        points = np.asarray(source["selected"]["points_lps"], dtype=np.float64)
        reads(source_product, ("points_lps",), product)
        guide = None if mapping is None else mapping.guide(name, own)
        counts = np.full(depth, np.nan, dtype=np.float64)
        unique_counts = np.full(depth, np.nan, dtype=np.float64)
        map_counts = np.full(depth, np.nan, dtype=np.float64)
        slab_counts = np.full(depth, np.nan, dtype=np.float64)
        statuses = np.zeros(
            depth, dtype=np.int8
        )  # 0 unvisited,1 geometry,2 thickness,3 empty,4 complete,5 partial,6 projection failure
        complete = np.zeros(depth, dtype=bool)
        per_slice: dict[int, dict[str, np.ndarray]] = {}
        for z in range(depth):
            frame = plane_frame(own.series, z)
            if isinstance(frame, str):
                statuses[z] = 1
                continue
            try:
                thickness = float(thicknesses[z])
            except (IndexError, TypeError, ValueError, OverflowError):
                statuses[z] = 2
                continue
            if not np.isfinite(thickness) or thickness <= 0:
                statuses[z] = 2
                continue
            unique_rc, sample_rc, slab_count, whole, failure = (
                _extensor_source_projection(points, frame, thickness, (rows, cols))
            )
            slab_counts[z] = slab_count
            if failure is not None:
                statuses[z] = 6
                continue
            in_map = np.zeros(len(sample_rc), dtype=bool)
            if (
                mapping is not None
                and guide is not None
                and guide.status == "guided"
                and z in guide.slices
            ):
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    point = placement.get("point_lps")
                    if placement.get("status") != "ok" or point is None:
                        continue
                    try:
                        center = np.asarray(
                            frame.to_native(np.asarray([point], dtype=float)),
                            dtype=float,
                        )
                    except (
                        TypeError,
                        ValueError,
                        OverflowError,
                        np.linalg.LinAlgError,
                    ):
                        continue
                    if center.shape == (1, 2) and np.isfinite(center).all():
                        in_map |= np.all(
                            np.abs(sample_rc - center[0]) <= half + 0.5, axis=1
                        )
            counts[z] = float(len(sample_rc))
            unique_counts[z] = float(len(unique_rc))
            map_counts[z] = float(in_map.sum()) if mapping is not None else np.nan
            statuses[z] = 3 if slab_count == 0 else 4 if whole else 5
            complete[z] = bool(whole)
            per_slice[z] = {
                "unique_rc": unique_rc,
                "sample_rc": sample_rc,
                "in_map": in_map,
            }
        if orientation == "sagittal" and not source_tag:
            prefix = f"a4_sagittal_{name}_source_profile"
        elif orientation == "axial" and source_tag == "sagittal":
            prefix = f"a4_axial_{name}_sagittal_source_profile"
        elif orientation == "coronal":
            prefix = f"a4_coronal_{name}_{source_tag or 'sagittal'}_source_profile"
        else:
            prefix = f"a4_axial_{name}_source_profile"
        own.arrays[f"{prefix}_slices"] = np.arange(depth, dtype=np.int32)
        own.arrays[f"{prefix}_count"] = counts
        own.arrays[f"{prefix}_unique_count"] = unique_counts
        own.arrays[f"{prefix}_map_count"] = map_counts
        own.arrays[f"{prefix}_slab_count"] = slab_counts
        own.arrays[f"{prefix}_status"] = statuses
        own.arrays[f"{prefix}_complete"] = complete
        offsets, unique_offsets, samples, unique_rows, map_rows = [0], [0], [], [], []
        for z in range(depth):
            part = per_slice.get(z, {})
            sample_rc = part.get("sample_rc", np.empty((0, 2), np.int32))
            unique_rc = part.get("unique_rc", np.empty((0, 2), np.int32))
            in_map = part.get("in_map", np.zeros(len(sample_rc), bool))
            samples.append(sample_rc)
            unique_rows.append(unique_rc)
            map_rows.append(in_map)
            offsets.append(offsets[-1] + len(sample_rc))
            unique_offsets.append(unique_offsets[-1] + len(unique_rc))
        own.arrays[f"{prefix}_offsets"] = np.asarray(offsets, dtype=np.int64)
        own.arrays[f"{prefix}_rc"] = (
            np.concatenate(samples) if samples else np.empty((0, 2), np.int32)
        )
        own.arrays[f"{prefix}_in_map"] = (
            np.concatenate(map_rows) if map_rows else np.empty(0, bool)
        )
        own.arrays[f"{prefix}_unique_offsets"] = np.asarray(
            unique_offsets, dtype=np.int64
        )
        own.arrays[f"{prefix}_unique_rc"] = (
            np.concatenate(unique_rows) if unique_rows else np.empty((0, 2), np.int32)
        )
        profiles[name] = {
            "status": "measured",
            "counts": counts,
            "unique_counts": unique_counts,
            "map_counts": map_counts,
            "slab_counts": slab_counts,
            "statuses": statuses,
            "complete": complete,
            "per_slice": per_slice,
            "guide": guide,
            "product": product,
            "source_product": source_product,
        }
        # Retained diagnostics are produced too. Persistence is not a consumer.
        handed(
            product,
            (
                "counts",
                "unique_counts",
                "map_counts",
                "slab_counts",
                "statuses",
                "complete",
                "sample_rc",
                "unique_rc",
                "guide",
                "in_map",
                "offsets",
                "unique_offsets",
            ),
        )
    return profiles


def name_native_menisci(
    measured: list[Measured],
    sources: dict[str, dict[str, Any]],
    study_uid: str,
    mapping: MapContext | None,
    *,
    orientation: str = "sagittal",
    other_sources: dict[str, dict[str, Any]] | None = None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Read bounded native windows from one source family, or contact both AX families."""
    if orientation not in ("sagittal", "axial"):
        raise ValueError("unsupported_meniscus_target_orientation")
    aligned = []
    names = ("medial_meniscus", "lateral_meniscus")
    product = (
        "sagittal_menisci_said" if orientation == "sagittal" else "axial_menisci_said"
    )
    for own in measured:
        observations: list[Observation] = []
        unresolved_rows: list[Unresolved] = []
        record, series = own.record, own.series
        uid, view = str(record["series_uid"]), tuple(record["view"])
        if len(view) != 3 or view[0].casefold() != orientation:
            aligned.append((observations, unresolved_rows))
            continue
        if view[1:] != ("1", "1"):
            unresolved_rows.extend(
                Unresolved(name, "native", uid, view, "unsupported_target_sequence")
                for name in names
            )
            aligned.append((observations, unresolved_rows))
            continue
        eligible = set(names)
        if orientation == "axial":
            eligible = {
                name
                for name in names
                if sources.get(name, {}).get("status") == "selected"
                and other_sources is not None
                and other_sources.get(name, {}).get("status") == "selected"
            }
            if not eligible:
                for name in names:
                    primary_source = sources.get(name, {})
                    secondary_source = (
                        {} if other_sources is None else other_sources.get(name, {})
                    )
                    if primary_source.get("status") != "selected":
                        reason = (
                            "source_tied"
                            if primary_source.get("status") == "tied"
                            else "source_unavailable"
                        )
                    else:
                        reason = (
                            "other_source_tied"
                            if secondary_source.get("status") == "tied"
                            else "other_source_unavailable"
                        )
                    unresolved_rows.append(
                        Unresolved(name, "native", uid, view, reason)
                    )
                aligned.append((observations, unresolved_rows))
                continue
        volume = series.volume
        if volume is None or np.ndim(volume) != 3:
            unresolved_rows.extend(
                Unresolved(name, "native", uid, view, "native_volume_unavailable")
                for name in names
            )
            aligned.append((observations, unresolved_rows))
            continue
        if orientation == "axial":
            eligible_primary = {name: sources[name] for name in eligible}
            eligible_secondary = {name: other_sources[name] for name in eligible}
            primary_profiles = native_meniscus_profiles(
                own, eligible_primary, mapping, orientation="axial"
            )
            secondary_profiles = native_meniscus_profiles(
                own,
                eligible_secondary,
                None,
                orientation="axial",
                source_tag="sagittal",
            )
        else:
            primary_profiles = native_meniscus_profiles(own, sources, mapping)
            secondary_profiles = None
        artifact = str(artifact_of(study_uid, record))
        for name in names:
            primary_source = sources.get(name, {})
            primary = None if primary_profiles is None else primary_profiles.get(name)
            secondary_source = (
                None
                if orientation == "sagittal"
                else ({} if other_sources is None else other_sources.get(name, {}))
            )
            secondary = (
                None if secondary_profiles is None else secondary_profiles.get(name)
            )
            if orientation == "axial" and name not in eligible:
                if primary_source.get("status") != "selected":
                    reason = (
                        "source_tied"
                        if primary_source.get("status") == "tied"
                        else "source_unavailable"
                    )
                else:
                    reason = (
                        "other_source_tied"
                        if secondary_source is not None
                        and secondary_source.get("status") == "tied"
                        else "other_source_unavailable"
                    )
                unresolved_rows.append(Unresolved(name, "native", uid, view, reason))
                continue
            if primary_source.get("status") != "selected":
                reason = (
                    "source_tied"
                    if primary_source.get("status") == "tied"
                    else "source_unavailable"
                )
                unresolved_rows.append(Unresolved(name, "native", uid, view, reason))
                continue
            if orientation == "axial" and (
                secondary_source is None or secondary_source.get("status") != "selected"
            ):
                reason = (
                    "other_source_tied"
                    if secondary_source is not None
                    and secondary_source.get("status") == "tied"
                    else "other_source_unavailable"
                )
                unresolved_rows.append(Unresolved(name, "native", uid, view, reason))
                continue
            if primary is None or primary.get("status") != "measured":
                unresolved_rows.append(
                    Unresolved(name, "native", uid, view, "source_profile_unavailable")
                )
                continue
            if orientation == "axial" and (
                secondary is None or secondary.get("status") != "measured"
            ):
                unresolved_rows.append(
                    Unresolved(
                        name, "native", uid, view, "other_source_profile_unavailable"
                    )
                )
                continue
            profile_product = primary["product"]
            reads(
                profile_product,
                (
                    "counts",
                    "unique_counts",
                    "map_counts",
                    "statuses",
                    "guide",
                    "unique_rc",
                ),
                product,
            )
            if orientation == "axial":
                assert secondary is not None
                reads(
                    secondary["product"],
                    ("counts", "unique_counts", "statuses", "unique_rc"),
                    product,
                )
            primary_selected = primary_source.get("selected")
            if not isinstance(primary_selected, dict):
                unresolved_rows.append(
                    Unresolved(name, "native", uid, view, "source_metadata_unavailable")
                )
                continue
            primary_meta = primary_selected["metadata"]
            primary_source_product = primary_source.get(
                "product", "native_meniscus_sources"
            )
            reads(primary_source_product, ("metadata",), product)
            secondary_meta = None
            if orientation == "axial":
                assert secondary_source is not None and secondary is not None
                secondary_selected = secondary_source.get("selected")
                if not isinstance(secondary_selected, dict):
                    unresolved_rows.append(
                        Unresolved(
                            name,
                            "native",
                            uid,
                            view,
                            "other_source_metadata_unavailable",
                        )
                    )
                    continue
                secondary_meta = secondary_selected["metadata"]
                reads("native_sagittal_meniscus_sources", ("metadata",), product)
            guide = primary.get("guide")

            def maxima(values):
                finite = np.isfinite(values)
                if not finite.any() or float(np.max(values[finite])) <= 0.0:
                    return []
                highest = float(np.max(values[finite]))
                return [int(z) for z in np.flatnonzero(finite & (values == highest))]

            guided = (
                maxima(primary["map_counts"])
                if guide is not None and guide.status == "guided"
                else []
            )
            source_peaks = set(maxima(primary["counts"])) | set(
                maxima(primary["unique_counts"])
            )
            other_peaks = []
            if orientation == "axial":
                assert secondary is not None
                other_peaks = sorted(
                    set(maxima(secondary["counts"]))
                    | set(maxima(secondary["unique_counts"]))
                )
                source_peaks |= set(other_peaks)
            source_peaks = sorted(source_peaks)
            candidate_order = list(dict.fromkeys(guided + source_peaks))
            profile_record = {
                "guide_status": None if guide is None else guide.status,
                "map_guided_first": guided,
                "source_profile_maxima": source_peaks,
            }
            if orientation == "axial":
                assert secondary is not None
                profile_record["other_source_profile_maxima"] = other_peaks
            profile_key = (
                "a4_meniscus_profile"
                if orientation == "sagittal"
                else "a4_axial_meniscus_profile"
            )
            record.setdefault(profile_key, {})[name] = profile_record
            profile_statuses = primary.get("statuses")
            refusal_key = (
                "a4_native_meniscus_profile_refusals"
                if orientation == "sagittal"
                else "a4_axial_meniscus_profile_refusals"
            )
            refusals: list[dict[str, Any]] = (
                []
                if profile_statuses is None
                else [
                    {"slice": int(z), "status": int(status)}
                    for z, status in enumerate(profile_statuses)
                    if int(status) not in (3, 4)
                ]
            )
            if orientation == "axial":
                assert secondary is not None
                secondary_statuses = secondary.get("statuses")
                if secondary_statuses is not None:
                    refusals.extend(
                        {"source": "sagittal", "slice": int(z), "status": int(status)}
                        for z, status in enumerate(secondary_statuses)
                        if int(status) not in (3, 4)
                    )
            record.setdefault(refusal_key, {})[name] = refusals
            if not candidate_order:
                unresolved_rows.append(
                    Unresolved(
                        name, "native", uid, view, "no_positive_candidate_profile"
                    )
                )
                continue
            candidate_codes = []
            candidate_records = []
            for z in candidate_order:
                primary_part = primary["per_slice"].get(z)
                if orientation == "axial":
                    assert secondary is not None
                    secondary_part = secondary["per_slice"].get(z)
                else:
                    secondary_part = None
                if primary_part is None or len(primary_part["unique_rc"]) == 0:
                    reason = "source_not_in_slab"
                    candidate_codes.append(reason)
                    candidate_records.append({"slice": int(z), "status": reason})
                    continue
                if orientation == "axial" and (
                    secondary_part is None or len(secondary_part["unique_rc"]) == 0
                ):
                    reason = "other_source_not_in_slab"
                    candidate_codes.append(reason)
                    candidate_records.append({"slice": int(z), "status": reason})
                    continue
                if orientation == "axial":
                    assert secondary_part is not None
                primary_rc = np.unique(
                    np.rint(primary_part["unique_rc"]).astype(np.int32), axis=0
                )
                secondary_rc = (
                    np.empty((0, 2), dtype=np.int32)
                    if secondary_part is None
                    else np.unique(
                        np.rint(secondary_part["unique_rc"]).astype(np.int32), axis=0
                    )
                )
                frame = plane_frame(series, z)
                if isinstance(frame, str):
                    candidate_codes.append("geometry_unreadable")
                    candidate_records.append(
                        {"slice": int(z), "status": "geometry_unreadable"}
                    )
                    continue
                source_rc = (
                    primary_rc
                    if orientation == "sagittal"
                    else np.unique(
                        np.concatenate((primary_rc, secondary_rc), axis=0), axis=0
                    )
                )
                span_mm = anatomy_map.target_span_mm(
                    name, mapping.smap.scale.mm if mapping is not None else None
                )
                if span_mm is None:
                    candidate_codes.append("anatomical_extent_unavailable")
                    candidate_records.append(
                        {"slice": int(z), "status": "anatomical_extent_unavailable"}
                    )
                    continue
                full_source_span_mm: tuple[float, float, float] = (
                    2.0 * float(span_mm[0]),
                    2.0 * float(span_mm[1]),
                    2.0 * float(span_mm[2]),
                )
                window = source_window(
                    source_rc.astype(np.float64),
                    full_source_span_mm,
                    frame,
                    tuple(np.shape(volume[z])),
                )
                if window.get("status") not in {"present", "window_clipped_to_image"}:
                    refusal = "source_window_" + str(
                        window.get("status", "unavailable")
                    )
                    candidate_codes.append(refusal)
                    candidate_records.append(
                        {"slice": int(z), "status": refusal, "window": window}
                    )
                    continue
                r0, r1, c0, c1 = window["window_rc_exclusive"]
                full_raw = np.asarray(volume[z])
                raw = full_raw[r0:r1, c0:c1]
                available = finite_of(series)[z] & ~margin_of(uid, z, full_raw)
                available = np.asarray(
                    available[r0:r1, c0:c1], dtype=bool
                ) & np.isfinite(raw)

                def crop_target(coords, shape=raw.shape, row0=r0, col0=c0):
                    result = np.zeros(shape, dtype=bool)
                    local = np.rint(coords).astype(int) - np.asarray([row0, col0])
                    inside = (
                        (local[:, 0] >= 0)
                        & (local[:, 0] < shape[0])
                        & (local[:, 1] >= 0)
                        & (local[:, 1] < shape[1])
                    )
                    result[local[inside, 0], local[inside, 1]] = True
                    return result

                target_crop = crop_target(primary_rc)
                other_target_crop = (
                    None if orientation == "sagittal" else crop_target(secondary_rc)
                )
                if not target_crop.any():
                    candidate_codes.append("source_target_outside_window")
                    candidate_records.append(
                        {
                            "slice": int(z),
                            "status": "source_target_outside_window",
                            "window": window,
                        }
                    )
                    continue
                if orientation == "axial" and (
                    other_target_crop is None or not other_target_crop.any()
                ):
                    candidate_codes.append("other_source_target_outside_window")
                    candidate_records.append(
                        {
                            "slice": int(z),
                            "status": "other_source_target_outside_window",
                            "window": window,
                        }
                    )
                    continue
                exact_key = (
                    uid,
                    int(z),
                    tuple(window["window_rc_exclusive"]),
                    tuple(primary_rc.reshape(-1)),
                    tuple(secondary_rc.reshape(-1)),
                )
                prefix = (
                    f"a4_{name}_z{int(z)}"
                    if orientation == "sagittal"
                    else f"a4_axial_{name}_z{int(z)}"
                )

                def select(
                    raw=raw,
                    available=available,
                    target_crop=target_crop,
                    frame=frame,
                    other_target_crop=other_target_crop,
                ):
                    ledger.record(
                        "native_meniscus.window_pixels", pixels=int(raw.size), frames=1
                    )
                    if other_target_crop is None:
                        return meniscus_local_body(raw, available, target_crop, frame)
                    return meniscus_local_body(
                        raw,
                        available,
                        target_crop,
                        frame,
                        other_target=other_target_crop,
                    )

                result = once("native_meniscus_local_body", exact_key, select)
                code = str(result.get("status", "selector_status_missing"))
                selection_status = result.get("selection_status")
                candidate_codes.append(code)
                candidate = {
                    "slice": int(z),
                    "source": primary_meta,
                    "window": window,
                    "target_pixel_count": int(target_crop.sum()),
                    "status": code,
                    "selection_status": selection_status,
                    "result_fields": {
                        key: value
                        for key, value in result.items()
                        if not isinstance(value, np.ndarray)
                    },
                }
                if orientation == "axial":
                    assert other_target_crop is not None
                    candidate.update(
                        {
                            "other_source": secondary_meta,
                            "other_target_pixel_count": int(other_target_crop.sum()),
                        }
                    )
                candidate_records.append(
                    {
                        "slice": int(z),
                        "status": code,
                        "selection_status": selection_status,
                        "window": window,
                    }
                )
                candidate_key = (
                    "a4_native_meniscus_candidates"
                    if orientation == "sagittal"
                    else "a4_axial_native_meniscus_candidates"
                )
                record.setdefault(candidate_key, {}).setdefault(name, []).append(
                    candidate
                )
                own.arrays[f"{prefix}_raw_crop"] = raw
                own.arrays[f"{prefix}_available_crop"] = available
                own.arrays[f"{prefix}_target_crop"] = target_crop
                if orientation == "axial":
                    assert other_target_crop is not None
                    own.arrays[f"{prefix}_other_target_crop"] = other_target_crop
                array_keys = (
                    "availability",
                    "depth_input",
                    "enclosed_depth",
                    "positive_enclosure",
                    "opened",
                    "labels",
                    "distance_to_target",
                    "contacted_components",
                    "selected",
                )
                if orientation == "axial":
                    array_keys += (
                        "distance_to_other_target",
                        "other_contacted_components",
                        "both_contacted_components",
                    )
                for key in array_keys:
                    value = result.get(key)
                    if isinstance(value, np.ndarray):
                        own.arrays[f"{prefix}_{key}"] = value
                if isinstance(result.get("selected"), np.ndarray):
                    own.arrays[f"{prefix}_selected_slices"] = np.asarray(
                        [z], dtype=np.int32
                    )
                crop_record = {
                    "slice": int(z),
                    "window": window,
                    "source": primary_meta,
                    "selection_status": selection_status,
                    "result_fields": {
                        key: value
                        for key, value in result.items()
                        if not isinstance(value, np.ndarray)
                    },
                }
                if orientation == "axial":
                    crop_record.update({"other_source": secondary_meta})
                crop_key = (
                    "a4_native_meniscus_crop_metadata"
                    if orientation == "sagittal"
                    else "a4_axial_native_meniscus_crop_metadata"
                )
                record.setdefault(crop_key, {}).setdefault(name, []).append(crop_record)
                selected = result.get("selected")
                if not isinstance(selected, np.ndarray):
                    selected = np.zeros(raw.shape, dtype=bool)
                # A partial window is distinct from the component decision: unseen
                # places elsewhere do not withdraw a body identified on seen samples.
                resolved = (
                    code in {"identified", "partial_reading"}
                    and selection_status == "identified"
                    and selected.shape == raw.shape
                    and selected.any()
                )
                support_name = f"{prefix}_support"
                if (
                    resolved
                    or (
                        code == "partial_reading"
                        and selected.shape == raw.shape
                        and selected.any()
                    )
                    or (
                        code == "measured_empty"
                        and selection_status == "measured_empty"
                        and selected.shape == raw.shape
                    )
                ):
                    full = np.zeros(tuple(np.shape(volume[z])), dtype=bool)
                    full[r0:r1, c0:c1] = selected
                    own.arrays[support_name] = full
                    own.arrays[f"{support_name}_slices"] = np.asarray(
                        [z], dtype=np.int32
                    )
                if resolved:
                    observations.append(
                        observe(
                            name,
                            "native",
                            "resolved",
                            own,
                            (int(z),),
                            "identified",
                            int(selected.sum()),
                            0.0,
                            support_name,
                            "identified body on available samples in the bounded native window; "
                            "window completeness is retained separately in crop measurements",
                            artifact,
                        )
                    )
                elif code in {
                    "partial_reading",
                    "tied_largest_components",
                    "measured_empty",
                }:
                    if (
                        code == "measured_empty"
                        and selection_status == "measured_empty"
                    ):
                        observations.append(
                            observe(
                                name,
                                "native",
                                "reading",
                                own,
                                (int(z),),
                                code,
                                0,
                                0.0,
                                support_name,
                                "complete bounded local reading selected no support",
                                artifact,
                            )
                        )
                    elif code == "partial_reading" and selected.any():
                        observations.append(
                            observe(
                                name,
                                "native",
                                "reading",
                                own,
                                (int(z),),
                                code,
                                int(selected.sum()),
                                0.0,
                                support_name,
                                "partial local reading; selected support is retained without a native resolution",
                                artifact,
                            )
                        )
                    unresolved_rows.append(
                        Unresolved(name, "native", uid, view, "local_body_" + code)
                    )
                else:
                    unresolved_rows.append(
                        Unresolved(
                            name, "native", uid, view, "local_body_unavailable:" + code
                        )
                    )
            candidate_status_key = (
                "a4_native_meniscus_candidate_status"
                if orientation == "sagittal"
                else "a4_axial_native_meniscus_candidate_status"
            )
            record.setdefault(candidate_status_key, {})[name] = candidate_records
            if not any(row.object == name for row in observations) and not any(
                row.object == name for row in unresolved_rows
            ):
                unresolved_rows.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        "candidate_readings_unresolved:" + "|".join(candidate_codes),
                    )
                )
        aligned.append((observations, unresolved_rows))
    if any(rows or missing for rows, missing in aligned):
        handed(product, ("observations", "unresolved"))
    return aligned


def native_femoral_cartilage_sources(
    measured: list[Measured],
    companions: list[tuple[list[Observation], list[Unresolved]]],
    study_uid: str,
) -> dict[str, dict[str, Any]]:
    """Retain every native sagittal reading and identified coronal source location."""
    collected: dict[str, list[tuple[Measured, np.ndarray, dict[str, Any]]]] = {
        "sagittal": [],
        "coronal": [],
    }
    has_axial_target = False
    for own in measured:
        view = tuple(own.record.get("view", ()))
        if len(view) != 3 or view[0].casefold() != "axial":
            continue
        try:
            has_axial_target = (
                int(own.series.row.fat_suppression) == 1
                and int(own.series.row.fluid_sensitive) == 1
            )
        except (AttributeError, TypeError, ValueError, OverflowError):
            continue
        if has_axial_target:
            break
    if not has_axial_target:
        return {
            orientation: {
                "status": "no_axial_fs_fluid_sensitive_target",
                "points": np.empty((0, 3), dtype=np.float64),
                "entries": [],
                "point_count": 0,
            }
            for orientation in collected
        }
    for own, (rows, _) in zip(measured, companions, strict=True):
        view = tuple(own.record.get("view", ()))
        uid = str(own.record.get("series_uid", ""))
        artifact = str(artifact_of(study_uid, own.record))
        if len(view) == 3 and view[0].casefold() == "sagittal":
            for observation in rows:
                if (
                    observation.object != "femoral_cartilage"
                    or observation.provenance != "native"
                    or observation.kind != "resolved"
                    or observation.code != "identified"
                    or observation.support != "a3_joint_plane_reading"
                    or observation.series_uid != uid
                    or tuple(observation.view) != view
                    or observation.artifact != artifact
                    or observation.label != OBJECT_CODES["femoral_cartilage"]
                    or observation.row is None
                    or len(observation.slices) != 1
                ):
                    continue
                z = int(observation.slices[0])
                stack = own.arrays.get("a3_joint_plane_reading")
                slices = np.asarray(own.arrays.get("a3_joint_plane_slices", ()))
                row = int(observation.row)
                if (
                    not isinstance(stack, np.ndarray)
                    or stack.ndim != 3
                    or not 0 <= row < len(stack)
                    or row >= len(slices)
                    or int(slices[row]) != z
                ):
                    continue
                mask = stack[row] == observation.label
                count = int(np.count_nonzero(mask))
                if not count or observation.count != count:
                    continue
                frame = plane_frame(own.series, z)
                if isinstance(frame, str):
                    continue
                try:
                    points = np.asarray(
                        frame.to_patient(np.argwhere(mask).astype(float)), dtype=float
                    )
                except (
                    AttributeError,
                    FloatingPointError,
                    TypeError,
                    ValueError,
                    np.linalg.LinAlgError,
                ):
                    continue
                if points.shape != (count, 3) or not np.isfinite(points).all():
                    continue
                metadata = {
                    "series_uid": uid,
                    "view": list(view),
                    "slice": z,
                    "support": observation.support,
                    "row": row,
                    "label": observation.label,
                    "count": count,
                    "artifact": artifact,
                    "provenance": observation.provenance,
                    "code": observation.code,
                }
                collected["sagittal"].append((own, points, metadata))
        elif (
            len(view) == 3
            and view[0].casefold() == "coronal"
            and view[1:] == ("1", "1")
            and own.record.get("assignments", {}).get("codes", {}).get("cartilage")
            == "identified"
        ):
            objects = own.arrays.get("a1_objects")
            if not isinstance(objects, np.ndarray) or objects.ndim != 2:
                continue
            mask = objects == OBJECT_CODES["femoral_cartilage"]
            count = int(np.count_nonzero(mask))
            if not count:
                continue
            z = int(own.record["slice_index"])
            frame = plane_frame(own.series, z)
            if isinstance(frame, str):
                continue
            try:
                points = np.asarray(
                    frame.to_patient(np.argwhere(mask).astype(float)), dtype=float
                )
            except (
                AttributeError,
                FloatingPointError,
                TypeError,
                ValueError,
                np.linalg.LinAlgError,
            ):
                continue
            if points.shape != (count, 3) or not np.isfinite(points).all():
                continue
            metadata = {
                "series_uid": uid,
                "view": list(view),
                "slice": z,
                "support": "a1_objects",
                "row": None,
                "label": OBJECT_CODES["femoral_cartilage"],
                "count": count,
                "artifact": artifact,
                "provenance": "native",
                "code": "identified",
            }
            collected["coronal"].append((own, points, metadata))

    sources: dict[str, dict[str, Any]] = {}
    for orientation, entries in collected.items():
        by_owner: dict[int, list[tuple[Measured, np.ndarray, dict[str, Any]]]] = {}
        for entry in entries:
            by_owner.setdefault(id(entry[0]), []).append(entry)
        for owner_entries in by_owner.values():
            owner = owner_entries[0][0]
            offsets = [0]
            points_rows = []
            metadata_rows = []
            for _, points, metadata in owner_entries:
                points_rows.append(points)
                metadata_rows.append({**metadata, "point_offset": offsets[-1]})
                offsets.append(offsets[-1] + len(points))
            owner.arrays[f"a4_femoral_cartilage_{orientation}_source_lps"] = (
                np.concatenate(points_rows, axis=0)
            )
            owner.arrays[f"a4_femoral_cartilage_{orientation}_source_offsets"] = (
                np.asarray(offsets, dtype=np.int64)
            )
            owner.record.setdefault("a4_femoral_cartilage_sources", {})[orientation] = (
                metadata_rows
            )
            handed(
                "native_femoral_cartilage_sources",
                ("points_lps", "offsets", "metadata"),
            )
        all_points = (
            np.concatenate([points for _, points, _ in entries], axis=0)
            if entries
            else np.empty((0, 3), dtype=np.float64)
        )
        sources[orientation] = {
            "status": "selected" if len(all_points) else "unavailable",
            "points": all_points,
            "entries": [metadata for _, _, metadata in entries],
            "point_count": len(all_points),
        }
    return sources


def native_femoral_cartilage_profiles(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    mapping: MapContext | None,
) -> dict[str, Any] | None:
    """Project both source groups through actual axial half-slabs and retain their profiles."""
    view = tuple(own.record.get("view", ()))
    if len(view) != 3 or view[0].casefold() != "axial":
        return None
    if any(
        sources.get(name, {}).get("status") != "selected"
        for name in ("sagittal", "coronal")
    ):
        own.record["a4_femoral_cartilage_profile_status"] = (
            "source_locations_unavailable"
        )
        return None
    series = own.series
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        own.record["a4_femoral_cartilage_profile_status"] = "native_volume_unavailable"
        return None
    depth, rows, cols = np.shape(volume)
    try:
        thicknesses = tuple(
            None if value is None else float(value)
            for value in series.slice_thickness_mm
        )
    except (AttributeError, TypeError, ValueError, OverflowError):
        thicknesses = ()
    if len(thicknesses) != depth:
        thicknesses = (None,) * depth

    guide = None if mapping is None else mapping.guide("femoral_cartilage", own)
    profiles: dict[str, dict[str, Any]] = {}
    for orientation in ("sagittal", "coronal"):
        points = np.asarray(sources[orientation]["points"], dtype=float)
        reads(
            "native_femoral_cartilage_sources",
            ("points_lps", "offsets", "metadata"),
            "native_femoral_cartilage_profiles",
        )
        counts = np.full(depth, np.nan, dtype=np.float64)
        map_counts = np.full(depth, np.nan, dtype=np.float64)
        unique_counts = np.full(depth, np.nan, dtype=np.float64)
        statuses = np.zeros(depth, dtype=np.int8)
        complete = np.zeros(depth, dtype=bool)
        per_slice: dict[int, dict[str, np.ndarray]] = {}
        for z in range(depth):
            frame = plane_frame(series, z)
            if isinstance(frame, str):
                statuses[z] = 1
                continue
            thickness = thicknesses[z]
            if thickness is None or not np.isfinite(thickness) or thickness <= 0.0:
                statuses[z] = 6
                continue
            unique_rc, sample_rc, slab_count, whole, failure = (
                _extensor_source_projection(points, frame, thickness, (rows, cols))
            )
            if failure is not None:
                statuses[z] = 7
                continue
            if slab_count == 0:
                counts[z] = map_counts[z] = unique_counts[z] = 0.0
                statuses[z] = 2
                complete[z] = True
                per_slice[z] = {
                    "unique_rc": unique_rc,
                    "sample_rc": sample_rc,
                    "in_map": np.zeros(0, dtype=bool),
                }
                continue
            counts[z] = float(len(sample_rc))
            unique_counts[z] = float(len(unique_rc))
            complete[z] = whole
            in_map = np.zeros(len(sample_rc), dtype=bool)
            if guide is not None and guide.status == "guided" and z in guide.slices:
                half = np.asarray(guide.half_px or (0.0, 0.0), dtype=float)
                for placement in guide.placements:
                    point = placement.get("point_lps")
                    if placement.get("status") != "ok" or point is None:
                        continue
                    try:
                        center = np.asarray(
                            frame.to_native(np.asarray([point], dtype=float)),
                            dtype=float,
                        )
                    except (
                        TypeError,
                        ValueError,
                        OverflowError,
                        np.linalg.LinAlgError,
                    ):
                        continue
                    if center.shape == (1, 2) and np.isfinite(center).all():
                        in_map |= np.all(
                            np.abs(sample_rc - center[0]) <= half + 0.5, axis=1
                        )
            map_counts[z] = float(np.count_nonzero(in_map))
            statuses[z] = 3 if whole else 4
            per_slice[z] = {
                "unique_rc": unique_rc,
                "sample_rc": sample_rc,
                "in_map": in_map,
            }
        prefix = f"a4_axial_femoral_cartilage_{orientation}_source_profile"
        own.arrays[f"{prefix}_slices"] = np.arange(depth, dtype=np.int32)
        own.arrays[f"{prefix}_count"] = counts
        own.arrays[f"{prefix}_map_count"] = map_counts
        own.arrays[f"{prefix}_unique_count"] = unique_counts
        own.arrays[f"{prefix}_status"] = statuses
        own.arrays[f"{prefix}_complete"] = complete
        offsets = [0]
        unique_offsets = [0]
        sample_rows: list[np.ndarray] = []
        unique_rows: list[np.ndarray] = []
        map_rows: list[np.ndarray] = []
        for z in range(depth):
            item = per_slice.get(z, {})
            samples = item.get("sample_rc", np.empty((0, 2), dtype=np.int32))
            unique_rc = item.get("unique_rc", np.empty((0, 2), dtype=np.int32))
            in_map = item.get("in_map", np.zeros(len(samples), dtype=bool))
            sample_rows.append(samples)
            unique_rows.append(unique_rc)
            map_rows.append(in_map)
            offsets.append(offsets[-1] + len(samples))
            unique_offsets.append(unique_offsets[-1] + len(unique_rc))
        own.arrays[f"{prefix}_offsets"] = np.asarray(offsets, dtype=np.int64)
        own.arrays[f"{prefix}_rc"] = (
            np.concatenate(sample_rows, axis=0)
            if sample_rows
            else np.empty((0, 2), dtype=np.int32)
        )
        own.arrays[f"{prefix}_in_map"] = (
            np.concatenate(map_rows) if map_rows else np.empty(0, dtype=bool)
        )
        own.arrays[f"{prefix}_unique_offsets"] = np.asarray(
            unique_offsets, dtype=np.int64
        )
        own.arrays[f"{prefix}_unique_rc"] = (
            np.concatenate(unique_rows, axis=0)
            if unique_rows
            else np.empty((0, 2), dtype=np.int32)
        )
        profiles[orientation] = {
            "counts": counts,
            "map_counts": map_counts,
            "unique_counts": unique_counts,
            "statuses": statuses,
            "complete": complete,
            "per_slice": per_slice,
        }

    sagittal = profiles["sagittal"]
    coronal = profiles["coronal"]
    complete = sagittal["complete"] & coronal["complete"]
    counts = np.where(complete, sagittal["counts"] + coronal["counts"], np.nan)
    map_counts = np.where(
        complete, sagittal["map_counts"] + coronal["map_counts"], np.nan
    )
    unique_counts = np.full(depth, np.nan, dtype=np.float64)
    for z in range(depth):
        if not complete[z]:
            continue
        sagittal_rc = (
            sagittal["per_slice"]
            .get(z, {})
            .get("unique_rc", np.empty((0, 2), dtype=np.int32))
        )
        coronal_rc = (
            coronal["per_slice"]
            .get(z, {})
            .get("unique_rc", np.empty((0, 2), dtype=np.int32))
        )
        union = np.unique(np.concatenate((sagittal_rc, coronal_rc), axis=0), axis=0)
        unique_counts[z] = float(len(union))

    def maxima(values: np.ndarray) -> list[int]:
        finite = np.isfinite(values)
        if not finite.any():
            return []
        maximum = float(np.max(values[finite]))
        if maximum <= 0.0:
            return []
        return [int(z) for z in np.flatnonzero(finite & (values == maximum))]

    guided = (
        maxima(map_counts) if guide is not None and guide.status == "guided" else []
    )
    source_peaks = sorted(set(maxima(counts)) | set(maxima(unique_counts)))
    own.arrays["a4_axial_femoral_cartilage_profile_slices"] = np.arange(
        depth, dtype=np.int32
    )
    own.arrays["a4_axial_femoral_cartilage_profile_count"] = counts
    own.arrays["a4_axial_femoral_cartilage_profile_map_count"] = map_counts
    own.arrays["a4_axial_femoral_cartilage_profile_unique_pixels"] = unique_counts
    own.arrays["a4_axial_femoral_cartilage_profile_complete"] = complete
    profile_record = {
        "sources": {
            orientation: {
                "point_count": int(sources[orientation]["point_count"]),
                "entries": sources[orientation]["entries"],
            }
            for orientation in ("sagittal", "coronal")
        },
        "guide": None
        if guide is None
        else {
            "status": guide.status,
            "slices": list(guide.slices),
            "placements": list(guide.placements),
            "half_px": guide.half_px,
            "anchors": list(guide.anchors),
        },
        "candidate_order": {
            "map_guided_first": guided,
            "source_profile_maxima": source_peaks,
        },
    }
    own.record["a4_axial_femoral_cartilage_profile"] = profile_record
    handed(
        "native_femoral_cartilage_profiles",
        ("on_slab_counts", "map_counts", "unique_pixels", "candidate_order"),
    )
    return {
        "groups": profiles,
        "counts": counts,
        "map_counts": map_counts,
        "unique_counts": unique_counts,
        "complete": complete,
        "guide": guide,
        "guided": guided,
        "source_peaks": source_peaks,
    }


def native_femoral_cartilage_candidates(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    mapping: MapContext | None,
    leg: "Leg | None",
    study_uid: str,
) -> dict[str, Any]:
    """Read only map-guided and source-profile maxima on the axial native series."""
    uid = str(own.record["series_uid"])
    view = tuple(own.record.get("view", ()))
    if len(view) != 3 or view[0].casefold() != "axial":
        return {"status": "not_axial_series", "rows": []}
    try:
        sequence = (
            int(own.series.row.fluid_sensitive),
            int(own.series.row.fat_suppression),
        )
    except (AttributeError, TypeError, ValueError, OverflowError):
        return {"status": "sequence_unavailable", "rows": []}
    if sequence != (1, 1):
        return {"status": "unsupported_sequence", "rows": []}
    profiles = native_femoral_cartilage_profiles(own, sources, mapping)
    if profiles is None:
        return {
            "status": str(
                own.record.get(
                    "a4_axial_femoral_cartilage_profile_status",
                    "source_or_profile_unavailable",
                )
            ),
            "rows": [],
        }
    reads(
        "native_femoral_cartilage_profiles",
        ("on_slab_counts", "map_counts", "unique_pixels", "candidate_order"),
        "native_femoral_cartilage_candidates",
    )
    volume = own.series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return {"status": "native_volume_unavailable", "rows": []}
    shape = tuple(np.shape(volume[0]))
    if len(shape) != 2:
        return {"status": "native_plane_shape_unavailable", "rows": []}
    group_rows = profiles["groups"]
    candidate_order = list(profiles["guided"])
    evaluated: dict[int, dict[str, Any]] = {}
    context_fields = (
        "available",
        "femur_core",
        "positive_enclosure",
        "enclosure_labels",
        "touched_labels",
        "touched_sizes",
        "selected_enclosure",
        "filled_enclosure",
        "fill_difference",
        "distance_from_enclosure",
        "candidate",
        "candidate_labels",
        "sagittal_target",
        "coronal_target",
        "sagittal_contact_distance_mm",
        "coronal_contact_distance_mm",
        "selected",
        "depth_input",
        "enclosed_depth",
        "femur_seed",
        "tibia_seed",
        "femur_blocks",
        "tibia_blocks",
        "coarse_block_median",
        "coarse_section_depth",
        "coarse_section_body",
    )
    scalar_fields = (
        "depth_input_open_value",
        "marrow_median",
        "brightness_level",
        "fluid_level",
        "coarse_section_area_mm2",
        "coarse_section_level",
    )

    def measure_slice(z: int) -> dict[str, Any]:
        series = own.series
        raw_value = np.asarray(volume[z])
        if raw_value.ndim != 2 or raw_value.shape != shape:
            return {"status": "native_plane_shape_unavailable", "slice": z}
        raw = np.asarray(raw_value, dtype=np.float64)
        frame = plane_frame(series, z)
        if isinstance(frame, str):
            return {"status": "native_frame_unavailable", "slice": z, "reason": frame}
        try:
            thicknesses = series.slice_thickness_mm
            raw_thickness = thicknesses[z]
            if raw_thickness is None:
                raise ValueError("slice_thickness_unavailable")
            thickness = float(raw_thickness)
        except (AttributeError, IndexError, TypeError, ValueError, OverflowError):
            return {"status": "slice_thickness_unavailable", "slice": z}
        if not np.isfinite(thickness) or thickness <= 0.0:
            return {"status": "slice_thickness_unavailable", "slice": z}
        finite = np.asarray(finite_of(series)[z])
        margin = np.asarray(margin_of(uid, z, raw))
        if (
            finite.shape != shape
            or finite.dtype.kind != "b"
            or margin.shape != shape
            or margin.dtype.kind != "b"
        ):
            return {"status": "native_availability_unavailable", "slice": z}
        available = finite & np.isfinite(raw) & ~margin
        if not available.any():
            return {"status": "native_availability_empty", "slice": z}
        profile_items = {
            orientation: group_rows[orientation]["per_slice"].get(z, {})
            for orientation in ("sagittal", "coronal")
        }
        targets: dict[str, np.ndarray] = {}
        for orientation in ("sagittal", "coronal"):
            target = np.zeros(shape, dtype=bool)
            unique_rc = profile_items[orientation].get(
                "unique_rc", np.empty((0, 2), dtype=np.int32)
            )
            if len(unique_rc):
                target[unique_rc[:, 0], unique_rc[:, 1]] = True
            targets[orientation] = target
        core_context = native_femur_coarse_context(own, z, raw, frame, leg)
        if core_context.get("block_reading") is None:
            return {
                "status": f"native_femur_core_{core_context.get('status', 'unavailable')}",
                "slice": z,
                "available": available,
                "sagittal_target": targets["sagittal"],
                "coronal_target": targets["coronal"],
                "core_context": core_context,
            }
        reads(
            "coarse_axial_blocks",
            ("median",),
            "native_femoral_cartilage_native_context",
        )
        reads(
            "coarse_axial_depth",
            ("depth",),
            "native_femoral_cartilage_native_context",
        )
        reads(
            "native_femur_coarse_context",
            ("block_reading", "native_core", "status"),
            "native_femoral_cartilage_native_context",
        )
        base = {
            "slice": z,
            "available": available,
            "sagittal_target": targets["sagittal"],
            "coronal_target": targets["coronal"],
            "core_context": core_context,
        }
        core = np.asarray(core_context["native_core"], dtype=bool)
        if core.shape != shape or not core.any():
            return {
                **base,
                "status": "native_femur_core_empty",
                "femur_core": core,
            }
        if not available[core].all():
            return {
                **base,
                "status": "native_femur_core_incomplete",
                "femur_core": core,
            }
        open_value = float(np.min(raw[available]))
        depth_plane = np.where(available, raw, open_value)
        base["depth_input_open_value"] = open_value
        base["depth_input"] = depth_plane
        depth = np.asarray(enclosed_depth_of(depth_plane, uid, z), dtype=float)
        base["enclosed_depth"] = depth
        if depth.shape != shape or not np.isfinite(depth).all():
            return {**base, "status": "native_enclosed_depth_unavailable"}
        positive = (depth > 0) & available
        measures = measures_of(uid, z, raw, frame)
        # The band's marrow light is read over the native component the core selects (the bone's
        # places as the native lens draws them), inside `femoral_cartilage_on_plane`; the coarse core
        # is a coarse enclosure that only selects it (FULL_BUILD_PLAN 1.2).
        result = femoral_cartilage_on_plane(
            raw,
            available,
            core,
            positive,
            targets["sagittal"],
            targets["coronal"],
            measures.light,
            frame.spacing_rc,
            measures.distance,
        )
        return {
            **result,
            **base,
            "femur_core": core,
            "source_projection_complete": bool(
                group_rows["sagittal"]["complete"][z]
                and group_rows["coronal"]["complete"][z]
            ),
            "source_profile_count": int(profiles["counts"][z])
            if np.isfinite(profiles["counts"][z])
            else None,
            "source_profile_map_count": int(profiles["map_counts"][z])
            if np.isfinite(profiles["map_counts"][z])
            else None,
            "source_profile_unique_pixels": int(profiles["unique_counts"][z])
            if np.isfinite(profiles["unique_counts"][z])
            else None,
        }

    for z in candidate_order:
        evaluated[z] = measure_slice(z)
    guided_selected = any(
        item.get("status") == "selected_native_component" for item in evaluated.values()
    )
    if not guided_selected:
        fallback = [z for z in profiles["source_peaks"] if z not in evaluated]
        candidate_order.extend(fallback)
        for z in fallback:
            evaluated[z] = measure_slice(z)
    context_rows = [evaluated[z] for z in candidate_order]
    output_fields: list[str] = []

    def context_array(row: dict[str, Any], key: str) -> np.ndarray | None:
        value = row.get(key)
        if isinstance(value, np.ndarray):
            return value
        context = row.get("core_context")
        if not isinstance(context, dict):
            return None
        if key in ("femur_seed", "tibia_seed", "femur_blocks", "tibia_blocks"):
            value = context.get(key)
        elif key == "coarse_block_median":
            reading = context.get("block_reading")
            value = None if reading is None else reading.median
        elif key == "coarse_section_depth":
            value = context.get("depth")
        elif key == "coarse_section_body":
            section = context.get("section")
            value = None if section is None else section.body
        return value if isinstance(value, np.ndarray) else None

    for key in context_fields:
        present = [
            (int(row["slice"]), np.asarray(value))
            for row in context_rows
            if (value := context_array(row, key)) is not None
        ]
        if not present:
            continue
        value_name = f"a4_axial_femoral_cartilage_context_{key}_values"
        base_name = f"a4_axial_femoral_cartilage_context_{key}"
        arrays = [value.ravel() for _, value in present]
        offsets = np.concatenate(
            ([0], np.cumsum([len(value) for value in arrays]))
        ).astype(np.int64)
        own.arrays[value_name] = np.concatenate(arrays)
        own.arrays[f"{base_name}_offsets"] = offsets
        own.arrays[f"{base_name}_shapes"] = np.asarray(
            [value.shape for _, value in present], dtype=np.int32
        )
        own.arrays[f"{base_name}_slices"] = np.asarray(
            [z for z, _ in present], dtype=np.int32
        )
        output_fields.extend(
            (
                f"{key}_values",
                f"{key}_offsets",
                f"{key}_shapes",
                f"{key}_slices",
            )
        )

    def context_scalar(row: dict[str, Any], key: str) -> float | None:
        value = row.get(key)
        if value is not None:
            return float(value)
        context = row.get("core_context")
        section = context.get("section") if isinstance(context, dict) else None
        if section is None:
            return None
        if key == "coarse_section_area_mm2":
            return float(section.area_mm2)
        if key == "coarse_section_level":
            return float(section.level)
        return None

    for key in scalar_fields:
        present = [
            (int(row["slice"]), value)
            for row in context_rows
            if (value := context_scalar(row, key)) is not None
        ]
        if not present:
            continue
        base_name = f"a4_axial_femoral_cartilage_context_{key}"
        own.arrays[f"{base_name}_values"] = np.asarray(
            [value for _, value in present], dtype=np.float64
        )
        own.arrays[f"{base_name}_slices"] = np.asarray(
            [z for z, _ in present], dtype=np.int32
        )
        output_fields.extend((f"{key}_values", f"{key}_slices"))
    coarse_details = []
    for row in context_rows:
        context = row.get("core_context")
        if not isinstance(context, dict):
            continue
        z = int(row["slice"])
        block_reading = context.get("block_reading")
        section = context.get("section")
        detail = {"slice": z, "status": context.get("status")}
        if block_reading is not None:
            for key in ("femur_seed", "tibia_seed", "femur_blocks", "tibia_blocks"):
                value = context.get(key)
                if isinstance(value, np.ndarray):
                    detail[key] = int(np.count_nonzero(value))
            detail.update(
                {
                    "block_window_rc": list(block_reading.window_rc),
                    "block_px": list(block_reading.block_px),
                    "block_mm": list(block_reading.block_mm),
                    "block_shape": list(block_reading.median.shape),
                    "section_status": section.status if section is not None else None,
                    "section_area_mm2": section.area_mm2
                    if section is not None
                    else None,
                    "section_level": section.level if section is not None else None,
                }
            )
        coarse_details.append(detail)
    if coarse_details:
        own.record["a4_axial_femoral_cartilage_coarse_context"] = [
            {
                key: value
                for key, value in detail.items()
                if not isinstance(value, np.ndarray)
            }
            for detail in coarse_details
        ]
    own.record["a4_axial_femoral_cartilage_candidates"] = [
        {
            "slice": z,
            "status": str(evaluated[z].get("status", "native_candidate_unavailable")),
            "profile_count": evaluated[z].get("source_profile_count"),
            "map_count": evaluated[z].get("source_profile_map_count"),
            "unique_source_pixels": evaluated[z].get("source_profile_unique_pixels"),
            "projection_complete": bool(
                evaluated[z].get("source_projection_complete", False)
            ),
            "depth_input_open_value": evaluated[z].get("depth_input_open_value"),
            "depth_boundary_policy": "minimum_of_available_at_unavailable_pixels",
            "marrow_median": evaluated[z].get("marrow_median"),
            "brightness_level": evaluated[z].get("brightness_level"),
            "fluid_level": evaluated[z].get("fluid_level"),
            "candidate_count": int(np.count_nonzero(evaluated[z].get("candidate", ()))),
            "contact_labels": np.asarray(
                evaluated[z].get("contact_labels", ())
            ).tolist(),
            "contact_sizes": np.asarray(evaluated[z].get("contact_sizes", ())).tolist(),
            "selected_count": int(np.count_nonzero(evaluated[z].get("selected", ()))),
        }
        for z in candidate_order
    ]
    if output_fields:
        handed("native_femoral_cartilage_context", output_fields)

    support_slices: list[int] = []
    support_masks: list[np.ndarray] = []
    support_status: list[str] = []
    found: list[Observation] = []
    unresolved: list[Unresolved] = []
    artifact = str(artifact_of(study_uid, own.record))
    for z in candidate_order:
        item = evaluated[z]
        status = str(item.get("status", "native_candidate_unavailable"))
        selected = item.get("selected")
        if status == "selected_native_component" and isinstance(selected, np.ndarray):
            support = np.asarray(selected, dtype=bool)
            support_status.append(status)
            support_slices.append(z)
            row_index = len(support_masks)
            support_masks.append(support)
            found.append(
                Observation(
                    "femoral_cartilage",
                    "native",
                    "resolved",
                    uid,
                    view,
                    (z,),
                    "identified",
                    int(support.sum()),
                    0.0,
                    "a4_axial_femoral_cartilage_support",
                    "the native bright surface component outside the hole-filled femur enclosure, in the existing cartilage reach and below the same-core fluid level, touching both sagittal and coronal native source locations; local description, not a full-surface boundary",
                    artifact,
                    row_index,
                    None,
                )
            )
        elif status in (
            "measured_empty_brightness_band",
            "no_candidate_component_contacts_both_sources",
        ) and item.get("source_projection_complete", False):
            support = np.zeros(shape, dtype=bool)
            support_status.append(status)
            support_slices.append(z)
            row_index = len(support_masks)
            support_masks.append(support)
            found.append(
                Observation(
                    "femoral_cartilage",
                    "native",
                    "reading",
                    uid,
                    view,
                    (z,),
                    status,
                    0,
                    0.0,
                    "a4_axial_femoral_cartilage_support",
                    "complete native measurement returned no component satisfying the existing relation at this candidate slice; this is local and is not absence of cartilage elsewhere",
                    artifact,
                    row_index,
                    None,
                )
            )
        else:
            unresolved.append(
                Unresolved(
                    "femoral_cartilage",
                    "native",
                    uid,
                    view,
                    f"native_slice_{z}:{status}",
                )
            )
    if support_masks:
        own.arrays["a4_axial_femoral_cartilage_support_slices"] = np.asarray(
            support_slices, dtype=np.int32
        )
        own.arrays["a4_axial_femoral_cartilage_support"] = np.stack(support_masks)
        own.arrays["a4_axial_femoral_cartilage_support_status"] = np.asarray(
            support_status, dtype="U64"
        )
    if mapping is not None:
        mapping.smap.note_use(
            "femoral_cartilage",
            uid,
            "map_guided_native_candidate"
            if guided_selected
            else "map_candidate_miss_source_profile_checked"
            if profiles["guided"]
            else "source_profile_native_candidate",
            question="native_femoral_cartilage_candidates",
            candidate_slices=candidate_order,
            resolved_slices=[
                item.slices[0] for item in found if item.kind == "resolved"
            ],
        )
    if found:
        handed(
            "native_femoral_cartilage_support",
            ("support", "slices", "status"),
        )
    return {
        "status": "measured" if found or unresolved else "no_candidate_slices",
        "rows": found,
        "unresolved": unresolved,
    }


def name_femoral_cartilage(
    measured: list[Measured],
    sources: dict[str, dict[str, Any]],
    study_uid: str,
    mapping: MapContext | None,
    leg: "Leg | None",
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Add the femoral cartilage's axial native description from its existing source locations."""
    output: list[tuple[list[Observation], list[Unresolved]]] = []
    source_status = {
        orientation: str(sources.get(orientation, {}).get("status", "unavailable"))
        for orientation in ("sagittal", "coronal")
    }
    for own in measured:
        view = tuple(own.record.get("view", ()))
        if len(view) != 3 or view[0].casefold() != "axial":
            output.append(([], []))
            continue
        result = native_femoral_cartilage_candidates(
            own, sources, mapping, leg, study_uid
        )
        if result["status"] == "not_axial_series":
            output.append(([], []))
            continue
        if result["status"] in ("unsupported_sequence", "sequence_unavailable"):
            output.append(
                (
                    [],
                    [
                        Unresolved(
                            "femoral_cartilage",
                            "native",
                            own.record["series_uid"],
                            view,
                            str(result["status"]),
                        )
                    ],
                )
            )
            continue
        if result["status"] in (
            "source_or_profile_unavailable",
            "source_locations_unavailable",
        ):
            reason = "native_source_unavailable:" + ":".join(
                f"{name}={source_status[name]}" for name in ("sagittal", "coronal")
            )
            output.append(
                (
                    [],
                    [
                        Unresolved(
                            "femoral_cartilage",
                            "native",
                            own.record["series_uid"],
                            view,
                            reason,
                        )
                    ],
                )
            )
            continue
        rows = result.get("rows", [])
        unresolved = result.get("unresolved", [])
        if not rows and not unresolved:
            status = str(result["status"])
            unresolved = [
                Unresolved(
                    "femoral_cartilage",
                    "native",
                    own.record["series_uid"],
                    view,
                    status if status.startswith("native_") else f"native_{status}",
                )
            ]
        output.append((rows, unresolved))
    return output


def native_fat_plane_context(
    own: Measured,
    z: int,
    profiles: dict[str, dict[str, Any]],
    leg: "Leg | None",
) -> dict[str, Any]:
    """Read one candidate plane's existing lens and, where Q/P seeds exist, shared basins."""
    product = "native_fat_native_context"
    series = own.series
    uid = str(own.record["series_uid"])
    volume = series.volume
    if volume is None or np.ndim(volume) != 3 or not 0 <= z < len(volume):
        return {"status": "native_plane_unavailable"}
    raw = np.asarray(volume[z])
    if raw.ndim != 2:
        return {"status": "native_plane_unavailable"}
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return {"status": "native_frame_unavailable", "reason": frame}
    _, reading, _ = lens_of(
        series, z, raw, frame, float(own.record["background_split"]), product
    )
    field = field_of(series, z, raw, frame, reading)
    lens_available = np.asarray(reading.available)
    field_available = np.asarray(field.leg)
    finite = np.asarray(finite_of(series)[z])
    margin = np.asarray(margin_of(uid, z, raw))
    if any(
        item.shape != raw.shape or item.dtype.kind != "b"
        for item in (lens_available, field_available, finite, margin)
    ):
        return {"status": "native_availability_unavailable"}
    available = lens_available & field_available & finite & ~margin
    targets: dict[str, np.ndarray] = {}
    marker_groups: dict[str, np.ndarray] = {}
    for name in (
        "hoffa_fat_pad",
        "quadriceps_fat_pad",
        "prefemoral_fat_pad",
        "suprapatellar_fat",
    ):
        source_profile = profiles.get(name)
        per_slice = (
            {} if source_profile is None else source_profile.get("per_slice", {})
        )
        samples = per_slice.get(z, {}).get(
            "sample_rc", np.empty((0, 2), dtype=np.int32)
        )
        target = np.zeros(raw.shape, dtype=bool)
        if len(samples):
            target[samples[:, 0], samples[:, 1]] = True
        targets[name] = target
        if len(samples) and name != "suprapatellar_fat":
            marker_groups[name] = target
    q_or_p_present = any(
        targets[name].any() for name in ("quadriceps_fat_pad", "prefemoral_fat_pad")
    )
    gradient = None
    coarse = {"status": "not_needed_without_qp_gradient"}
    if q_or_p_present:
        for marker_id in np.unique(reading.markers):
            code = int(marker_id)
            if code <= 0:
                continue
            marker_groups[f"native_lens_peak_{code}"] = reading.markers == code
        if int(own.record.get("slice_index", -1)) == z:
            codes = own.record.get("assignments", {}).get("codes", {})
            objects = own.arrays.get("a1_objects")
            if isinstance(objects, np.ndarray) and objects.shape == raw.shape:
                tendon = np.zeros(raw.shape, dtype=bool)
                for name in ("patellar_tendon", "quadriceps_tendon"):
                    if codes.get(name) == "identified":
                        tendon |= objects == OBJECT_CODES[name]
                if tendon.any():
                    marker_groups["native_extensor_tendon"] = tendon
        marker_groups["frame_margin"] = margin
        coarse = native_fat_coarse_femur_context(own, z, raw, frame, leg)
        native_core = coarse.get("native_core")
        if (
            isinstance(native_core, np.ndarray)
            and native_core.shape == raw.shape
            and native_core.dtype.kind == "b"
            and native_core.any()
        ):
            marker_groups["coarse_femur_core"] = native_core
        gradient = native_gradient_territories(
            raw,
            available,
            frame.spacing_rc,
            marker_groups,
        )
    context: dict[str, Any] = {
        "status": "measured",
        "z": z,
        "raw": raw,
        "frame": frame,
        "available": available,
        "lens_available": lens_available,
        "margin": margin,
        "lens_markers": np.asarray(reading.markers),
        "lens_labels": np.asarray(reading.labels),
        "targets": targets,
        "gradient": gradient,
        "coarse_femur": coarse,
    }
    context_fields = ["lens_context", "targets"]
    if q_or_p_present:
        context["gradient_marker_groups"] = marker_groups
        context_fields.extend(("gradient_context", "marker_groups"))
    handed(product, context_fields)
    return context


def native_fat_pad_candidate(
    own: Measured, name: str, context: dict[str, Any]
) -> dict[str, Any]:
    """Select the native lens holder for H or that pad's basin in the shared Q/P watershed."""
    if context.get("status") != "measured":
        return {"status": context.get("status", "native_context_unavailable")}
    context_fields = ["lens_context", "targets"]
    if context.get("gradient") is not None:
        context_fields.extend(("gradient_context", "marker_groups"))
    reads("native_fat_native_context", context_fields, "native_fat_candidate_selection")
    target = context["targets"].get(name)
    if not isinstance(target, np.ndarray) or target.dtype.kind != "b":
        return {"status": "source_target_unavailable"}
    if not target.any():
        return {"status": "no_source_location_on_slab", "target": target}
    raw = context["raw"]
    frame = context["frame"]
    if name == "hoffa_fat_pad":
        labels = context["lens_labels"]
        touched = np.unique(labels[target])
        touched = touched[touched > 0]
        if not len(touched):
            return {
                "status": "no_lens_territory_at_source_location",
                "target": target,
                "touched_ids": touched.astype(np.int32),
            }
        sizes = measures_of(
            own.record["series_uid"],
            int(context["z"]),
            raw,
            frame,
        ).sizes(labels)
        winner = unique_largest(sizes[touched])
        if winner is None:
            return {
                "status": "tied_largest_lens_territories_at_source_location",
                "target": target,
                "touched_ids": touched.astype(np.int32),
                "sizes": sizes,
            }
        selected_id = int(touched[winner])
        candidate = labels == selected_id
        return {
            "status": "selected_native_lens_territory",
            "candidate": candidate,
            "target": target,
            "selected_id": selected_id,
            "touched_ids": touched.astype(np.int32),
            "sizes": sizes,
            "frame": frame,
            "raw": raw,
        }
    gradient = context.get("gradient")
    if gradient is None:
        return {
            "status": "native_gradient_unavailable",
            "target": target,
        }
    marker_id = gradient.marker_codes.get(name)
    if marker_id is None:
        return {"status": "source_marker_unavailable", "target": target}
    candidate = gradient.labels == marker_id
    conflicts = gradient.conflicts & target
    if not candidate.any():
        status = (
            "source_marker_conflict"
            if conflicts.any()
            else "no_seeded_native_gradient_territory"
        )
        return {
            "status": status,
            "candidate": candidate,
            "target": target,
            "marker_id": marker_id,
            "conflict_target": conflicts,
            "gradient": gradient,
            "frame": frame,
            "raw": raw,
        }
    return {
        "status": "selected_native_gradient_territory",
        "candidate": candidate,
        "target": target,
        "marker_id": marker_id,
        "conflict_target": conflicts,
        "gradient": gradient,
        "frame": frame,
        "raw": raw,
    }


def native_fat_pad_candidates(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    mapping: MapContext | None,
    leg: "Leg | None",
) -> dict[str, list[dict[str, Any]]]:
    """Read map-guided and all tied source-profile maxima; retain native holders and context."""
    try:
        sequence = (
            int(own.series.row.fluid_sensitive),
            int(own.series.row.fat_suppression),
        )
    except (AttributeError, TypeError, ValueError, OverflowError):
        return {}
    if sequence != (1, 1):
        return {}
    profiles = native_fat_source_profiles(own, sources, mapping)
    if not profiles:
        return {}
    reads(
        "native_fat_source_profiles",
        ("profiles", "candidate_order"),
        "native_fat_candidate_selection",
    )
    view = str(own.record["view"][0]).casefold()
    uid = str(own.record["series_uid"])
    volume = own.series.volume
    if volume is None or np.ndim(volume) != 3 or not len(volume):
        return {}
    native_shape = tuple(np.shape(volume[0]))
    context_cache: dict[int, dict[str, Any]] = {}
    result_by_name: dict[str, list[dict[str, Any]]] = {}
    all_contexts: dict[int, dict[str, Any]] = {}

    def context_at(z: int) -> dict[str, Any]:
        if z not in context_cache:
            context_cache[z] = native_fat_plane_context(own, z, profiles, leg)
        return context_cache[z]

    for name, profile in profiles.items():
        if name == "suprapatellar_fat":
            continue
        composite_profile = (
            profiles.get("suprapatellar_fat", {})
            if name in ("quadriceps_fat_pad", "prefemoral_fat_pad")
            else {}
        )
        composite_counts = composite_profile.get(
            "counts", np.full_like(profile["counts"], np.nan)
        )
        guided = sorted(
            set(profile["guided"]) | set(composite_profile.get("guided", ()))
        )
        source_peak_sources = {z: [name] for z in profile["source_peaks"]}
        for z in composite_profile.get("source_peaks", ()):
            source_peak_sources.setdefault(z, []).append("suprapatellar_fat")
        source_peaks = sorted(source_peak_sources)
        candidate_order = list(guided)
        evaluated: dict[int, dict[str, Any]] = {}
        for z in guided:
            context = context_at(z)
            all_contexts[z] = context
            evaluated[z] = native_fat_pad_candidate(own, name, context)
        guided_candidate_counts = [
            int(profile["counts"][z])
            for z, item in evaluated.items()
            if item.get("candidate") is not None
            and np.asarray(item["candidate"]).any()
            and np.isfinite(profile["counts"][z])
        ]
        strongest_guided = (
            max(guided_candidate_counts) if guided_candidate_counts else None
        )
        fallback = sorted(set(source_peaks) - set(guided))
        # These are candidate geometries only.  Their opposed readings are measured below;
        # until those exist, a holder cannot establish compatible native fat support.
        to_check = fallback
        checked_source_peaks = [
            {
                "slice": z,
                "sources": source_peak_sources.get(z, [name]),
                "profile_count": None
                if not np.isfinite(profile["counts"][z])
                else int(profile["counts"][z]),
                "composite_profile_count": None
                if not np.isfinite(composite_counts[z])
                else int(composite_counts[z]),
            }
            for z in to_check
        ]
        for z in to_check:
            context = context_at(z)
            all_contexts[z] = context
            evaluated[z] = native_fat_pad_candidate(own, name, context)
            candidate_order.append(z)
        candidate_rows: list[dict[str, Any]] = []
        for z in candidate_order:
            item = evaluated[z]
            candidate = item.get("candidate")
            candidate_count = (
                int(np.count_nonzero(candidate))
                if isinstance(candidate, np.ndarray)
                else 0
            )
            candidate_rows.append(
                {
                    "slice": int(z),
                    "status": str(item.get("status", "native_candidate_unavailable")),
                    "candidate_count": candidate_count,
                    "target_count": int(
                        np.count_nonzero(item.get("target", np.zeros((0,), dtype=bool)))
                    ),
                    "source_profile_count": None
                    if not np.isfinite(profile["counts"][z])
                    else int(profile["counts"][z]),
                    "composite_profile_count": None
                    if not np.isfinite(composite_counts[z])
                    else int(composite_counts[z]),
                    "map_profile_count": None
                    if not np.isfinite(profile["map_counts"][z])
                    else int(profile["map_counts"][z]),
                    "projection_complete": bool(profile["complete"][z]),
                    "marker_id": item.get("marker_id", item.get("selected_id")),
                    "touched_ids": item.get(
                        "touched_ids", np.empty(0, dtype=np.int32)
                    ).tolist()
                    if isinstance(item.get("touched_ids"), np.ndarray)
                    else [],
                    "conflict_target_count": int(
                        np.count_nonzero(
                            item.get("conflict_target", np.zeros((0,), dtype=bool))
                        )
                    ),
                }
            )
        result_by_name[name] = [
            {
                **item,
                "slice": z,
                "profile_count": profile["counts"][z],
                "profile_map_count": profile["map_counts"][z],
                "projection_complete": bool(profile["complete"][z]),
            }
            for z, item in evaluated.items()
            if isinstance(item.get("candidate"), np.ndarray) and item["candidate"].any()
        ]
        own.record["a4_native_fat_profiles"][name]["candidate_order"].update(
            {
                "strongest_guided_candidate_profile_count": strongest_guided,
                "source_profile_peaks_checked_after_guidance": checked_source_peaks,
                "candidate_slices_read": candidate_order,
            }
        )
        own.record.setdefault("a4_native_fat_candidates", {})[name] = {
            "candidate_rows": candidate_rows,
            "measured_candidate_slices": [
                item["slice"] for item in result_by_name[name]
            ],
        }
        if mapping is not None:
            any_hit = any(row["candidate_count"] > 0 for row in candidate_rows)
            outcome = (
                "guided_geometry_candidate_source_peaks_checked"
                if any_hit and checked_source_peaks
                else "guided_geometry_candidate"
                if any_hit
                else "guided_geometry_miss_then_source_profile"
                if profile["guide"] is not None and profile["guide"].status == "guided"
                else "source_profile_only"
            )
            mapping.smap.note_use(
                name,
                uid,
                outcome,
                question="native_fat_pad_candidates",
                candidate_slices=[item["slice"] for item in candidate_rows],
                source_profile_peaks_checked=checked_source_peaks,
            )
    fluid_level: float | None = None
    recess = own.record.get("recess")
    raw_level = recess.get("level") if isinstance(recess, dict) else None
    try:
        if isinstance(raw_level, (tuple, list, np.ndarray)) and len(raw_level):
            candidate_level = float(raw_level[0])
            if np.isfinite(candidate_level) and candidate_level > 0.0:
                fluid_level = candidate_level
    except (TypeError, ValueError, OverflowError, IndexError):
        fluid_level = None
    same_series_white_by_slice: dict[int, np.ndarray] = {}
    candidate_slices = sorted(
        {int(row["slice"]) for rows in result_by_name.values() for row in rows}
    )
    if fluid_level is not None:
        for z in candidate_slices:
            context = all_contexts[z]
            same_series_white_by_slice[z] = (
                np.asarray(context["raw"]) > fluid_level
            ) & np.asarray(context["available"], dtype=bool)
    native_slices = sorted(
        z for z, context in all_contexts.items() if context.get("status") == "measured"
    )
    if native_slices:
        for suffix, key in (
            ("lens_labels", "lens_labels"),
            ("lens_markers", "lens_markers"),
            ("available", "available"),
            ("margin", "margin"),
        ):
            rows = [np.asarray(all_contexts[z][key]) for z in native_slices]
            own.arrays[f"a4_{view}_native_fat_context_{suffix}"] = np.stack(rows)
        core_status = [
            str(all_contexts[z].get("coarse_femur", {}).get("status", "not_read"))
            for z in native_slices
        ]
        own.arrays[f"a4_{view}_native_fat_context_coarse_status"] = np.asarray(
            core_status, dtype="U64"
        )
        coarse_slices = [
            z
            for z in native_slices
            if all_contexts[z].get("coarse_femur", {}).get("block_reading") is not None
        ]
        coarse_rows = [
            all_contexts[z]["coarse_femur"]["block_reading"] for z in coarse_slices
        ]
        if coarse_rows and all(item is not None for item in coarse_rows):
            own.arrays[f"a4_{view}_native_fat_context_coarse_slices"] = np.asarray(
                coarse_slices, dtype=np.int32
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_windows_rc"] = np.asarray(
                [item.window_rc for item in coarse_rows], dtype=np.int32
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_block_px"] = np.asarray(
                [item.block_px for item in coarse_rows], dtype=np.int32
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_block_mm"] = np.asarray(
                [item.block_mm for item in coarse_rows], dtype=np.float64
            )
            section_rows = [
                all_contexts[z]["coarse_femur"]["section"] for z in coarse_slices
            ]
            own.arrays[f"a4_{view}_native_fat_context_coarse_section_status"] = (
                np.asarray([item.status for item in section_rows], dtype="U32")
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_section_area_mm2"] = (
                np.asarray([item.area_mm2 for item in section_rows], dtype=np.float64)
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_section_level"] = (
                np.asarray([item.level for item in section_rows], dtype=np.float64)
            )
            own.arrays[f"a4_{view}_native_fat_context_coarse_section_present"] = (
                np.asarray([item.body is not None for item in section_rows], dtype=bool)
            )
            for suffix, key in (
                ("femur_core", "native_core"),
                ("femur_seed", "femur_seed"),
                ("tibia_seed", "tibia_seed"),
            ):
                masks = [
                    np.asarray(all_contexts[z]["coarse_femur"][key], dtype=bool)
                    for z in coarse_slices
                ]
                if all(mask.shape == native_shape for mask in masks):
                    own.arrays[f"a4_{view}_native_fat_context_{suffix}"] = np.stack(
                        masks
                    )
            shapes = [item.median.shape for item in coarse_rows]
            if all(shape == shapes[0] for shape in shapes):
                own.arrays[f"a4_{view}_native_fat_context_coarse_median"] = np.stack(
                    [item.median for item in coarse_rows]
                )
                own.arrays[f"a4_{view}_native_fat_context_coarse_depth"] = np.stack(
                    [all_contexts[z]["coarse_femur"]["depth"] for z in coarse_slices]
                )
                empty_blocks = np.zeros(shapes[0], dtype=bool)
                for suffix, key in (
                    ("femur_seed_blocks", "femur_blocks"),
                    ("tibia_seed_blocks", "tibia_blocks"),
                ):
                    own.arrays[f"a4_{view}_native_fat_context_coarse_{suffix}"] = (
                        np.stack(
                            [
                                np.asarray(
                                    all_contexts[z]["coarse_femur"].get(
                                        key, empty_blocks
                                    ),
                                    dtype=bool,
                                )
                                for z in coarse_slices
                            ]
                        )
                    )
                own.arrays[f"a4_{view}_native_fat_context_coarse_femur_body_blocks"] = (
                    np.stack(
                        [
                            empty_blocks
                            if item.body is None
                            else np.asarray(item.body, dtype=bool)
                            for item in section_rows
                        ]
                    )
                )
        for name in (
            "hoffa_fat_pad",
            "quadriceps_fat_pad",
            "prefemoral_fat_pad",
            "suprapatellar_fat",
        ):
            rows = [
                np.asarray(all_contexts[z]["targets"][name], dtype=bool)
                for z in native_slices
            ]
            own.arrays[f"a4_{view}_native_fat_context_target_{name}"] = np.stack(rows)
        marker_names = sorted(
            {
                marker_name
                for z in native_slices
                for marker_name in all_contexts[z].get("gradient_marker_groups", {})
            }
        )
        if marker_names:
            marker_presence = np.zeros(
                (len(native_slices), len(marker_names)), dtype=bool
            )
            for marker_index, marker_name in enumerate(marker_names):
                marker_rows = []
                for row_index, z in enumerate(native_slices):
                    groups = all_contexts[z].get("gradient_marker_groups", {})
                    marker = groups.get(marker_name)
                    marker_presence[row_index, marker_index] = marker is not None
                    marker_rows.append(
                        np.zeros_like(all_contexts[z]["available"], dtype=bool)
                        if marker is None
                        else np.asarray(marker, dtype=bool)
                    )
                own.arrays[f"a4_{view}_native_fat_context_marker_{marker_name}"] = (
                    np.stack(marker_rows)
                )
            own.arrays[f"a4_{view}_native_fat_context_marker_names"] = np.asarray(
                marker_names, dtype="U64"
            )
            own.arrays[f"a4_{view}_native_fat_context_marker_presence"] = (
                marker_presence
            )
        own.arrays[f"a4_{view}_native_fat_context_slices"] = np.asarray(
            native_slices, dtype=np.int32
        )
        gradient_slices = [
            z for z in native_slices if all_contexts[z].get("gradient") is not None
        ]
        own.arrays[f"a4_{view}_native_fat_gradient_slices"] = np.asarray(
            gradient_slices, dtype=np.int32
        )
        if gradient_slices:
            for suffix, key, dtype in (
                ("gradient_magnitude", "gradient_magnitude", np.float64),
                ("gradient_u16", "gradient_u16", np.uint16),
                ("gradient_valid", "gradient_valid", bool),
                ("marker_ids", "marker_ids", np.int32),
                ("conflicts", "conflicts", bool),
                ("labels", "labels", np.int32),
                ("unknown", "unknown", bool),
            ):
                rows = [
                    np.asarray(getattr(all_contexts[z]["gradient"], key), dtype=dtype)
                    for z in gradient_slices
                ]
                own.arrays[f"a4_{view}_native_fat_gradient_{suffix}"] = np.stack(rows)
    for name, rows in result_by_name.items():
        for row in rows:
            context = all_contexts[int(row["slice"])]
            coarse = context.get("coarse_femur", {})
            row["available"] = context["available"]
            row["same_series_white"] = (
                same_series_white_by_slice[int(row["slice"])]
                if fluid_level is not None
                else None
            )
            row["coarse_femur_core"] = coarse.get("native_core")
            row["coarse_femur_status"] = coarse.get("status", "not_read")
        prefix = f"a4_{view}_{name}"
        slices = [int(row["slice"]) for row in rows]
        own.arrays[f"{prefix}_slices"] = np.asarray(slices, dtype=np.int32)
        for suffix, key in (("candidate", "candidate"), ("source_target", "target")):
            masks = [np.asarray(row[key], dtype=bool) for row in rows]
            own.arrays[f"{prefix}_{suffix}"] = (
                np.stack(masks) if masks else np.empty((0, *native_shape), dtype=bool)
            )
        own.arrays[f"{prefix}_candidate_codes"] = np.asarray(
            [row["status"] for row in rows], dtype="U64"
        )
        if fluid_level is not None:
            own.arrays[f"{prefix}_same_series_white"] = (
                np.stack(
                    [same_series_white_by_slice[int(row["slice"])] for row in rows]
                )
                if rows
                else np.empty((0, *native_shape), dtype=bool)
            )
    own.record["a4_native_fat_candidate_context"] = {
        "status": "measured" if native_slices else "no_native_candidate_frame_read",
        "view": view,
        "context_slices": native_slices,
        "gradient_slices": [
            int(z) for z in native_slices if all_contexts[z].get("gradient") is not None
        ],
        "same_series_fluid_level": fluid_level,
        "candidate_slices": {
            name: [int(row["slice"]) for row in rows]
            for name, rows in result_by_name.items()
        },
    }
    if any(result_by_name.values()):
        handed(
            "native_fat_candidate_regions",
            (
                "candidate",
                "target",
                "frame",
                "raw",
                "available",
                "same_series_white",
                "coarse_femur_core",
            ),
        )
    return result_by_name


def native_fat_opposed_samples(
    own: Measured,
    candidates: dict[str, list[dict[str, Any]]],
    calibrations: dict[str, dict[str, Any]],
    measured: list[Measured],
) -> None:
    """Sample every selected native candidate once in each calibrated non-FS series."""
    product = "native_fat_opposed_sampling"
    if not any(candidates.values()):
        return
    reads(
        "native_fat_candidate_regions",
        ("candidate", "target", "frame", "raw"),
        product,
    )
    view = str(own.record["view"][0]).casefold()
    native_volume = own.series.volume
    if native_volume is None or np.ndim(native_volume) != 3 or not len(native_volume):
        return
    native_shape = tuple(np.shape(native_volume[0]))
    by_uid = {str(item.record["series_uid"]): item for item in measured}
    usable_sources = [
        (source_uid, calibration, by_uid.get(source_uid))
        for source_uid, calibration in calibrations.items()
        if calibration.get("status") == "calibrated"
        and by_uid.get(source_uid) is not None
    ]
    source_metadata = [
        {key: value for key, value in calibration.items() if key != "threshold"}
        | {"threshold": float(calibration["threshold"])}
        for _, calibration, _ in usable_sources
    ]
    if usable_sources:
        reads("native_fat_opposed_calibration", ("threshold", "source"), product)
    slices = sorted(
        {
            int(row["slice"])
            for rows in candidates.values()
            for row in rows
            if isinstance(row.get("candidate"), np.ndarray) and row["candidate"].any()
        }
    )
    own.record["a4_native_fat_opposed_sources"] = source_metadata
    sample_rows: list[np.ndarray] = []
    sample_lps: list[np.ndarray] = []
    sample_signals: list[np.ndarray] = []
    sample_selected: list[np.ndarray] = []
    sample_native_rc: list[np.ndarray] = []
    sample_signed_distance: list[np.ndarray] = []
    sample_status: list[np.ndarray] = []
    sample_offsets = [0]
    for z in slices:
        frame_context = next(
            row
            for rows in candidates.values()
            for row in rows
            if int(row["slice"]) == z
        )
        frame = frame_context["frame"]
        group_coords: dict[str, np.ndarray] = {}
        all_coords: list[np.ndarray] = []
        for name, rows in candidates.items():
            matching = [row for row in rows if int(row["slice"]) == z]
            if not matching:
                continue
            coords = np.argwhere(
                np.asarray(matching[0]["candidate"], dtype=bool)
            ).astype(np.int32)
            group_coords[name] = coords
            if len(coords):
                all_coords.append(coords)
        if not all_coords:
            continue
        coords = np.unique(np.concatenate(all_coords, axis=0), axis=0)
        try:
            points_lps = np.asarray(frame.to_patient(coords.astype(float)), dtype=float)
        except (
            AttributeError,
            FloatingPointError,
            TypeError,
            ValueError,
            np.linalg.LinAlgError,
        ):
            points_lps = np.full((len(coords), 3), np.nan, dtype=float)
        field_count = len(usable_sources)
        signals = np.full((len(coords), field_count), np.nan, dtype=np.float64)
        selected_z = np.full((len(coords), field_count), -1, dtype=np.int32)
        native_rc = np.full((len(coords), field_count, 2), -1, dtype=np.int32)
        signed_distance = np.full((len(coords), field_count), np.nan, dtype=np.float64)
        statuses = np.full((len(coords), field_count), "unread", dtype="U32")
        for field_index, (_, _, source) in enumerate(usable_sources):
            if source is None:
                statuses[:, field_index] = "source_series_unavailable"
                continue
            volume = source.series.volume
            if volume is None or np.ndim(volume) != 3 or not len(volume):
                statuses[:, field_index] = "source_volume_unavailable"
                continue
            source_depth, source_rows, source_cols = np.shape(volume)
            frames: list[PlaneFrame] = []
            geometry_failure = None
            for source_z in range(source_depth):
                source_frame = plane_frame(source.series, source_z)
                if isinstance(source_frame, str):
                    geometry_failure = source_frame
                    break
                frames.append(source_frame)
            if geometry_failure is not None:
                statuses[:, field_index] = "source_geometry_unavailable"
                continue
            try:
                thicknesses = tuple(source.series.slice_thickness_mm)
            except (AttributeError, TypeError):
                thicknesses = ()
            if len(thicknesses) != source_depth:
                statuses[:, field_index] = "source_thickness_unavailable"
                continue

            def read_plane(
                source_z: int, source_series: Series = source.series
            ) -> tuple[np.ndarray, np.ndarray]:
                return seen_native(source_series, source_z, product)

            samples = sample_native_points(
                points_lps,
                frames,
                thicknesses,
                (source_rows, source_cols),
                read_plane,
            )
            signals[:, field_index] = samples.signal
            selected_z[:, field_index] = samples.selected_z
            native_rc[:, field_index] = samples.native_rc
            signed_distance[:, field_index] = samples.signed_distance_mm
            statuses[:, field_index] = np.asarray(samples.status, dtype="U32")
        coord_flat = coords[:, 0].astype(np.int64) * int(
            frame_context["raw"].shape[1]
        ) + coords[:, 1].astype(np.int64)
        for name, group in group_coords.items():
            row = next(item for item in candidates[name] if int(item["slice"]) == z)
            positive_fields: list[np.ndarray] = []
            available_fields: list[np.ndarray] = []
            group_flat = group[:, 0].astype(np.int64) * int(
                frame_context["raw"].shape[1]
            ) + group[:, 1].astype(np.int64)
            sample_indices = np.searchsorted(coord_flat, group_flat)
            if np.any(sample_indices >= len(coord_flat)) or not np.array_equal(
                coord_flat[sample_indices], group_flat
            ):
                row["fat_classes"] = {
                    key: np.zeros(np.shape(row["candidate"]), dtype=bool)
                    for key in (
                        "positive",
                        "negative",
                        "disagreement",
                        "positive_without_known_negative",
                        "negative_without_known_positive",
                        "known",
                    )
                }
                row["fat_classes"]["unknown"] = np.ones(
                    np.shape(row["candidate"]), dtype=bool
                )
                row["opposed_source_status_counts"] = {}
                continue
            source_status_counts: dict[str, dict[str, int]] = {}
            for field_index, (source_uid, calibration, _) in enumerate(usable_sources):
                compatible = np.zeros(np.shape(row["candidate"]), dtype=bool)
                available = np.zeros(np.shape(row["candidate"]), dtype=bool)
                field_status = statuses[sample_indices, field_index]
                valid = field_status == "valid"
                available[group[:, 0], group[:, 1]] = valid
                compatible[group[:, 0], group[:, 1]] = valid & (
                    signals[sample_indices, field_index]
                    >= float(calibration["threshold"])
                )
                positive_fields.append(compatible)
                available_fields.append(available)
                status_values, status_counts = np.unique(
                    field_status, return_counts=True
                )
                source_status_counts[source_uid] = {
                    str(status): int(count)
                    for status, count in zip(status_values, status_counts, strict=True)
                }
            if positive_fields:
                classes = fat_compatibility_sets(positive_fields, available_fields)
            else:
                candidate_mask = np.asarray(row["candidate"], dtype=bool)
                empty = np.zeros(candidate_mask.shape, dtype=bool)
                classes = {
                    "positive": empty.copy(),
                    "negative": empty.copy(),
                    "unknown": np.ones(candidate_mask.shape, dtype=bool),
                    "disagreement": empty.copy(),
                    "positive_without_known_negative": empty.copy(),
                    "negative_without_known_positive": empty.copy(),
                    "known": empty.copy(),
                }
            row["fat_classes"] = classes
            row["opposed_source_status_counts"] = source_status_counts
        sample_rows.append(coords)
        sample_lps.append(points_lps)
        sample_signals.append(signals)
        sample_selected.append(selected_z)
        sample_native_rc.append(native_rc)
        sample_signed_distance.append(signed_distance)
        sample_status.append(statuses)
        sample_offsets.append(sample_offsets[-1] + len(coords))
    offsets = np.asarray(sample_offsets, dtype=np.int64)
    own.arrays[f"a4_{view}_fat_opposed_slices"] = np.asarray(slices, dtype=np.int32)
    own.arrays[f"a4_{view}_fat_opposed_offsets"] = offsets
    own.arrays[f"a4_{view}_fat_opposed_rc"] = (
        np.concatenate(sample_rows, axis=0)
        if sample_rows
        else np.empty((0, 2), dtype=np.int32)
    )
    own.arrays[f"a4_{view}_fat_opposed_points_lps"] = (
        np.concatenate(sample_lps, axis=0)
        if sample_lps
        else np.empty((0, 3), dtype=np.float64)
    )
    for suffix, items, dtype in (
        ("signal", sample_signals, np.float64),
        ("selected_z", sample_selected, np.int32),
        ("native_rc", sample_native_rc, np.int32),
        ("signed_distance_mm", sample_signed_distance, np.float64),
        ("status", sample_status, "U32"),
    ):
        own.arrays[f"a4_{view}_fat_opposed_{suffix}"] = (
            np.concatenate(items, axis=0)
            if items
            else np.empty(
                (0, len(usable_sources), 2)
                if suffix == "native_rc"
                else (0, len(usable_sources)),
                dtype=dtype,
            )
        )
    for name, rows in candidates.items():
        prefix = f"a4_{view}_{name}"
        for suffix in (
            "positive",
            "negative",
            "unknown",
            "disagreement",
            "positive_without_known_negative",
            "negative_without_known_positive",
            "known",
        ):
            masks = [
                np.asarray(row["fat_classes"][suffix], dtype=bool)
                for row in rows
                if "fat_classes" in row
            ]
            own.arrays[f"{prefix}_fat_{suffix}"] = (
                np.stack(masks) if masks else np.empty((0, *native_shape), dtype=bool)
            )
    if slices:
        handed(product, ("samples", "compatibility_classes"))


def native_fat_pad_observations(
    own: Measured,
    sources: dict[str, dict[str, Any]],
    candidates: dict[str, list[dict[str, Any]]],
    study_uid: str,
) -> tuple[list[Observation], list[Unresolved]]:
    """Describe native compatible pad support, keeping the Q/P union a separate composite."""
    uid = str(own.record["series_uid"])
    view = tuple(own.record["view"])
    orientation = view[0].casefold()
    if orientation not in ("axial", "coronal"):
        return [], []
    try:
        sequence = (
            int(own.series.row.fluid_sensitive),
            int(own.series.row.fat_suppression),
        )
    except (AttributeError, TypeError, ValueError, OverflowError):
        sequence_status = "sequence_unavailable"
    else:
        sequence_status = "unsupported_sequence" if sequence != (1, 1) else None
    if sequence_status is not None:
        return [], [
            Unresolved(name, "native", uid, view, sequence_status)
            for name in (
                "hoffa_fat_pad",
                "quadriceps_fat_pad",
                "prefemoral_fat_pad",
                "suprapatellar_fat",
            )
        ]
    if any(candidates.values()):
        reads(
            "native_fat_candidate_regions",
            ("candidate", "available", "same_series_white", "coarse_femur_core"),
            "native_fat_support",
        )
        reads(
            "native_fat_opposed_sampling",
            ("compatibility_classes",),
            "native_fat_support",
        )
    artifact = str(artifact_of(study_uid, own.record))
    found: list[Observation] = []
    unresolved: list[Unresolved] = []
    component_rows: dict[str, dict[int, tuple[dict[str, Any], Any, int | None]]] = {}
    saved: dict[str, list[dict[str, Any]]] = {}

    for name in (
        "hoffa_fat_pad",
        "quadriceps_fat_pad",
        "prefemoral_fat_pad",
    ):
        source = sources.get(name, {})
        if source.get("status") != "selected":
            detail = source.get("detail", {})
            source_code = detail.get("code", source.get("status", "unavailable"))
            unresolved.append(
                Unresolved(name, "native", uid, view, f"native_source_{source_code}")
            )
            continue
        rows = candidates.get(name, [])
        component_rows[name] = {}
        attempted = (
            own.record.get("a4_native_fat_candidates", {})
            .get(name, {})
            .get("candidate_rows", [])
        )
        candidate_slices = {int(row["slice"]) for row in rows}
        for item in attempted:
            z = int(item["slice"])
            if z not in candidate_slices and int(item.get("candidate_count", 0)) == 0:
                unresolved.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"native_slice_{z}:{item.get('status', 'native_candidate_unavailable')}",
                    )
                )
        support_masks: list[np.ndarray] = []
        support_slices: list[int] = []
        support_statuses: list[str] = []
        support_counts: list[int] = []
        support_details: list[dict[str, Any]] = []
        for row in rows:
            z = int(row["slice"])
            candidate = row.get("candidate")
            available = row.get("available")
            classes = row.get("fat_classes")
            if not isinstance(candidate, np.ndarray) or not isinstance(classes, dict):
                unresolved.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"native_slice_{z}:compatibility_measurement_unavailable",
                    )
                )
                continue
            if not isinstance(available, np.ndarray):
                unresolved.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"native_slice_{z}:native_availability_unavailable",
                    )
                )
                continue
            coarse = row.get("coarse_femur_core")
            support = native_fat_support(
                candidate,
                available,
                row.get("same_series_white"),
                classes,
                coarse if isinstance(coarse, np.ndarray) else None,
            )
            address_row: int | None = None
            if support.status in (
                "native_support_selected",
                "measured_empty_native_support",
            ):
                support_masks.append(support.mask)
                support_slices.append(z)
                support_statuses.append(support.status)
                support_counts.append(support.support_count)
                address_row = len(support_masks) - 1
                kind = (
                    "resolved"
                    if support.status == "native_support_selected"
                    else "reading"
                )
                found.append(
                    Observation(
                        name,
                        "native",
                        kind,
                        uid,
                        view,
                        (z,),
                        support.status,
                        support.support_count,
                        0.0,
                        f"a4_{orientation}_{name}_support",
                        (
                            "the measured compatible part of this native candidate region, "
                            "outside same-series white-fluid support and the measured coarse "
                            "femur core where present; local support only, not the pad's whole "
                            "course or boundary"
                        ),
                        artifact,
                        address_row,
                        None,
                    )
                )
            else:
                unresolved.append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        f"native_slice_{z}:{support.status}",
                    )
                )
            row["native_support_mask"] = support.mask
            row["native_support_status"] = support.status
            row["native_support_count"] = support.support_count
            component_rows[name][z] = (row, support, address_row)
            support_details.append(
                {
                    "slice": z,
                    "status": support.status,
                    "candidate_count": support.candidate_count,
                    "support_count": support.support_count,
                    "known_count": support.known_count,
                    "unknown_count": support.unknown_count,
                    "disagreement_count": support.disagreement_count,
                    "complete": support.complete,
                    "coarse_femur_status": row.get("coarse_femur_status", "not_read"),
                }
            )
        if support_masks:
            prefix = f"a4_{orientation}_{name}_support"
            own.arrays[f"{prefix}_slices"] = np.asarray(support_slices, dtype=np.int32)
            own.arrays[prefix] = np.stack(support_masks)
            own.arrays[f"{prefix}_status"] = np.asarray(support_statuses, dtype="U64")
            own.arrays[f"{prefix}_count"] = np.asarray(support_counts, dtype=np.int64)
        elif not rows and not attempted:
            unresolved.append(
                Unresolved(
                    name,
                    "native",
                    uid,
                    view,
                    "no_native_candidate_profile_rows",
                )
            )
        saved[name] = support_details

    composite_slices = sorted(
        set(component_rows.get("quadriceps_fat_pad", {}))
        | set(component_rows.get("prefemoral_fat_pad", {}))
    )
    composite_masks: list[np.ndarray] = []
    composite_saved_slices: list[int] = []
    composite_statuses: list[str] = []
    composite_counts: list[int] = []
    composite_detail: list[dict[str, Any]] = []
    for z in composite_slices:
        q = component_rows.get("quadriceps_fat_pad", {}).get(z)
        p = component_rows.get("prefemoral_fat_pad", {}).get(z)
        q_support = None if q is None else q[1]
        p_support = None if p is None else p[1]
        q_mask = None if q_support is None else q_support.mask
        p_mask = None if p_support is None else p_support.mask
        shape_source = q_mask if q_mask is not None else p_mask
        if not isinstance(shape_source, np.ndarray):
            continue
        union = np.zeros(shape_source.shape, dtype=bool)
        if isinstance(q_mask, np.ndarray) and q_mask.shape == union.shape:
            union |= q_mask
        if isinstance(p_mask, np.ndarray) and p_mask.shape == union.shape:
            union |= p_mask
        q_selected = (
            q_support is not None and q_support.status == "native_support_selected"
        )
        p_selected = (
            p_support is not None and p_support.status == "native_support_selected"
        )
        q_measured = q_support is not None and q_support.status in (
            "native_support_selected",
            "measured_empty_native_support",
        )
        p_measured = p_support is not None and p_support.status in (
            "native_support_selected",
            "measured_empty_native_support",
        )
        if q_selected and p_selected:
            status, kind = "native_support_selected", "resolved"
        elif q_measured and p_measured and not union.any():
            status, kind = "measured_empty_native_union", "reading"
        elif union.any():
            status, kind = "partial_component_support", "reading"
        else:
            status, kind = "component_support_unavailable", "unresolved"
        details = {
            "slice": z,
            "status": status,
            "quadriceps": "unavailable" if q_support is None else q_support.status,
            "prefemoral": "unavailable" if p_support is None else p_support.status,
            "count": int(union.sum()),
        }
        composite_detail.append(details)
        if kind == "unresolved":
            unresolved.append(
                Unresolved(
                    "suprapatellar_fat",
                    "native",
                    uid,
                    view,
                    f"native_slice_{z}:component_support_unavailable",
                )
            )
            continue
        composite_masks.append(union)
        composite_saved_slices.append(z)
        composite_statuses.append(status)
        composite_counts.append(int(union.sum()))
        found.append(
            Observation(
                "suprapatellar_fat",
                "native",
                kind,
                uid,
                view,
                (z,),
                status,
                int(union.sum()),
                0.0,
                f"a4_{orientation}_suprapatellar_fat_support",
                (
                    "the union of separately measured quadriceps and prefemoral native support; "
                    "resolved only when both component supports are usable on this slice, "
                    "otherwise a partial composite reading"
                ),
                artifact,
                len(composite_masks) - 1,
                None,
            )
        )
    if composite_masks:
        prefix = f"a4_{orientation}_suprapatellar_fat_support"
        own.arrays[f"{prefix}_slices"] = np.asarray(
            composite_saved_slices, dtype=np.int32
        )
        own.arrays[prefix] = np.stack(composite_masks)
        own.arrays[f"{prefix}_status"] = np.asarray(composite_statuses, dtype="U64")
        own.arrays[f"{prefix}_count"] = np.asarray(composite_counts, dtype=np.int64)
    own.record["a4_native_fat_composition"] = {
        "status": "measured" if composite_detail else "no_native_component_candidates",
        "composed_from": ["quadriceps_fat_pad", "prefemoral_fat_pad"],
        "not_a_gradient_seed": True,
        "slices": composite_detail,
    }
    if not composite_detail:
        unresolved.append(
            Unresolved(
                "suprapatellar_fat",
                "native",
                uid,
                view,
                "no_native_qp_component_candidates",
            )
        )
    own.record.setdefault("a4_native_fat_support", {}).update(saved)
    return found, unresolved


def axial_joint_fluid(
    own: Measured,
    record: dict,
    arrays: dict[str, np.ndarray],
    study_uid: str,
    mapping: MapContext | None = None,
    *,
    pointed: bool,
) -> tuple[list[Observation], list[Unresolved]]:
    """The patellofemoral recess fluid the retinacular rule already selected, said as joint fluid.

    No image is read again. `pointed=True`: `record`/`arrays` are the axial series' own after
    `name_the_recess` (rows are its retained nonmiddle `a3_recess_plane_*` planes). `pointed=False`:
    the original retinacula main record, before its save (the one `slice_index`). Each row's two
    selected pockets (`..._medial_recess` / `..._lateral_recess`, or the `a2_retinacula_*_selected_recess`
    pair) are united as a set of pixels and stored as the boolean `a4_axial_joint_fluid` (a stack with
    the same rows, or the 2D slice), beside both unchanged side masks; the record gains the small
    diagnostic `a4_axial_joint_fluid` (per row: status, code, pixels, each side's state). The union is
    set membership of two pockets of one joint's fluid: no connected body, centroid, boundary or volume.

    A readable row whose union is non empty is a native resolved `joint_fluid` observation (support the
    union, a row on the pointed path, no label), valid even when a wall code is
    `abstain_no_outboard_wall_minimum`. A row both of whose sides were read and found no recess is a
    measured-empty reading; a row whose source reading was unavailable (a prerequisite refusal, a missing
    or malformed array or record) is an `Unresolved` carrying that reason, never an empty measurement. If one
    side is readable and selected while the other side is unavailable or contradicts its mask, the readable
    side remains a partial observation and the other side's named refusal is also returned.
    Series that are not axial say nothing. With a `mapping`, every competent row's actual plane is offered
    once to `joint_fluid` (support the pixel count times the plane's pixel area), the map keeping ties.
    Nothing is merged or saved here: the caller appends the rows and saves the arrays."""
    owner_uid = own.record.get("series_uid")
    uid = owner_uid if isinstance(owner_uid, str) else str(owner_uid)
    view = tuple(own.record.get("view", ()))
    if not view or str(view[0]).lower() != "axial":
        return [], []
    found: list[Observation] = []
    missing: list[Unresolved] = []

    def refuse(code: str) -> None:
        missing.append(Unresolved("joint_fluid", "native", uid, view, code))

    plane = arrays.get("acquired_plane")
    if not isinstance(plane, np.ndarray) or plane.ndim != 2:
        refuse("acquired_plane_unavailable")
        return found, missing
    shape = (int(plane.shape[0]), int(plane.shape[1]))

    if (
        not isinstance(owner_uid, str)
        or not owner_uid
        or not isinstance(record.get("series_uid"), str)
        or record.get("series_uid") != owner_uid
    ):
        refuse("source_record_uid_mismatch")
        return found, missing
    try:
        depth = len(own.series.slices)
    except (AttributeError, TypeError):
        refuse("source_depth_unavailable")
        return found, missing

    def checked_slice(value: Any) -> tuple[int | None, str | None]:
        if isinstance(value, (bool, np.bool_)) or not isinstance(
            value, int | np.integer
        ):
            return None, "source_slice_invalid"
        index = int(value)
        if index < 0 or index >= depth:
            return None, "source_slice_out_of_range"
        return index, None

    keys = (
        ("a3_recess_plane_medial_recess", "a3_recess_plane_lateral_recess")
        if pointed
        else (
            "a2_retinacula_positive_inner_selected_recess",
            "a2_retinacula_negative_inner_selected_recess",
        )
    )
    # the rows: (slice, the plane's own code, the wall codes by name)
    rows: list[tuple[int, str, Any]] = []
    if pointed:
        recess = record.get("recess")
        if not isinstance(recess, dict):
            refuse("recess_not_read")
            return found, missing
        planes = recess.get("pointed_planes")
        if planes is None:
            said = recess.get("code")
            refuse(said if isinstance(said, str) else "recess_record_unavailable")
            return found, missing
        if recess.get("kind") != "retinacula":
            refuse("recess_kind_not_retinacula")
            return found, missing
        retained = (
            [p for p in planes if not p.get("middle")]
            if isinstance(planes, list) and all(isinstance(p, dict) for p in planes)
            else None
        )
        slices = arrays.get("a3_recess_plane_slices")
        if retained is None:
            refuse("recess_plane_rows_disagree")
            return found, missing
        if not isinstance(slices, np.ndarray):
            refuse("source_slice_unavailable")
            return found, missing
        if slices.ndim != 1 or len(slices) != len(retained):
            refuse("recess_plane_rows_disagree")
            return found, missing
        if not np.issubdtype(slices.dtype, np.integer):
            refuse("source_slice_invalid")
            return found, missing
        retained_indices: list[int] = []
        for p, s in zip(retained, slices, strict=True):
            if "slice" not in p:
                refuse("source_slice_unavailable")
                return found, missing
            index, issue = checked_slice(p["slice"])
            if issue is not None:
                refuse(issue)
                return found, missing
            if index != int(s):
                refuse("recess_plane_rows_disagree")
                return found, missing
            retained_indices.append(index)
        if not retained:
            refuse("no_axial_plane_pointed_to_read_it")
            return found, missing
        rows = [
            (index, str(p.get("code")), p.get("codes"))
            for p, index in zip(retained, retained_indices, strict=True)
        ]
    else:
        index = record.get("slice_index")
        assigned = record.get("assignments")
        if not isinstance(assigned, dict):
            refuse("retinacula_record_unavailable")
            return found, missing
        if "slice_index" not in record:
            refuse("source_slice_unavailable")
            return found, missing
        checked_index, issue = checked_slice(index)
        if issue is not None:
            refuse(issue)
            return found, missing
        rows = [(cast(int, checked_index), "read", assigned.get("codes"))]

    def side_mask(key: str, row: int) -> np.ndarray | None:
        held = arrays.get(key)
        if not isinstance(held, np.ndarray) or held.dtype != np.bool_:
            return None
        if pointed:
            return held[row] if held.shape == (len(rows), *shape) else None
        return held if held.shape == shape else None

    union = np.zeros((len(rows), *shape) if pointed else shape, dtype=bool)
    diagnostics: list[dict[str, Any]] = []
    artifact = str(artifact_of(study_uid, record))
    offers: list[tuple[rel.KeyPlane, float | None, str]] = []
    read_masks = False
    for row, (z, row_code, codes) in enumerate(rows):
        entry: dict[str, Any] = {"row": row if pointed else None, "slice": z}
        if row_code != "read":
            refuse(row_code)
            diagnostics.append({**entry, "status": "not_read", "code": row_code})
            continue
        if not isinstance(codes, dict):
            refuse("wall_codes_unavailable")
            diagnostics.append(
                {**entry, "status": "unavailable", "code": "wall_codes_unavailable"}
            )
            continue
        read_masks = True
        selected: list[np.ndarray] = []
        states: dict[str, str] = {}
        side_reasons: dict[str, str] = {}
        for name, key in zip(RETINACULA, keys, strict=True):
            code = codes.get(name)
            mask = side_mask(key, row)
            if mask is None:
                state, why = "unavailable", "selected_recess_mask_unavailable"
            elif not isinstance(code, str):
                state, why = "unavailable", "wall_code_unavailable"
            elif code in ("identified", "abstain_no_outboard_wall_minimum"):
                state, why = (
                    ("selected", "")
                    if mask.any()
                    else ("unavailable", "wall_code_disagrees_with_selected_recess")
                )
            elif code == "abstain_no_fluid_recess_at_the_patella":
                state, why = (
                    ("empty", "")
                    if not mask.any()
                    else ("unavailable", "wall_code_disagrees_with_selected_recess")
                )
            else:
                state, why = "unavailable", code
            states[name] = state
            if why:
                side_reasons[name] = why
            if state == "selected" and mask is not None:
                selected.append(mask)
        entry["sides"] = states
        if side_reasons:
            entry["side_reasons"] = side_reasons
        if selected:
            here = (
                np.logical_or(selected[0], selected[1])
                if len(selected) == 2
                else selected[0].copy()
            )
            count = int(np.count_nonzero(here))
            union[row if pointed else slice(None)] = here
            diagnostics.append(
                {**entry, "status": "fluid", "code": "identified", "pixels": count}
            )
            found.append(
                observe_in(
                    own.record,
                    "joint_fluid",
                    "native",
                    "resolved",
                    (z,),
                    "identified",
                    count,
                    0.0,
                    "a4_axial_joint_fluid",
                    "the union of the selected patellofemoral recess pockets on this actual axial section (set membership of the medial and lateral pockets, not one connected body; overlapping pixels count once); these descriptions overlap the joint fluid other views describe, so no full volume or additive amount is claimed, and this is not a maximum over unread slices; valid whether or not a wall minimum was found",
                    artifact,
                    row if pointed else None,
                    None,
                )
            )
            for side, why in side_reasons.items():
                refuse(f"{side}:{why}")
            if mapping is not None and "joint_fluid" in mapping.smap.names:
                reason = (
                    f"strongest native-resolved section of the object on this series ({'identified'}); "
                    "a pointer, not a definition of where the anatomy is most obvious"
                )
                provenance = "observations.native_resolved"
                try:
                    key_plane = map_plane(
                        own,
                        "joint_fluid",
                        z,
                        reason,
                        provenance,
                    )
                    frame = plane_frame(own.series, z)
                except (IndexError, TypeError, KeyError, AttributeError):
                    key_plane = rel.invalid_plane(
                        "joint_fluid",
                        "axial",
                        "frame_unavailable",
                        series_uid=uid,
                        slice=z,
                        reason=reason,
                        provenance=provenance,
                    )
                    frame = "geometry_unreadable"
                support = (
                    None
                    if isinstance(frame, str)
                    else float(count) * float(np.prod(frame.spacing_rc))
                )
                offers.append((key_plane, support, f"native:{uid}"))
        elif side_reasons:
            code = "|".join(sorted(set(side_reasons.values())))
            refuse(code)
            diagnostics.append(
                {**entry, "status": "unavailable", "code": code, "pixels": None}
            )
        else:
            code = "abstain_no_joint_fluid_in_patellofemoral_recesses"
            diagnostics.append(
                {**entry, "status": "measured_empty", "code": code, "pixels": 0}
            )
            found.append(
                observe_in(
                    own.record,
                    "joint_fluid",
                    "native",
                    "reading",
                    (z,),
                    code,
                    0,
                    0.0,
                    "a4_axial_joint_fluid",
                    "both selected recess sides were read here and no patellofemoral fluid recess lies in the interval: a measured empty union on this section only, never an absence elsewhere",
                    artifact,
                    row if pointed else None,
                    None,
                )
            )
    if pointed and read_masks:
        reads("recess_plane", ("masks",), "axial_joint_fluid")
    arrays["a4_axial_joint_fluid"] = union
    record["a4_axial_joint_fluid"] = {
        "path": "pointed" if pointed else "main",
        "sources": list(keys),
        "rows": diagnostics,
    }
    if any(d["status"] == "fluid" for d in diagnostics):
        handed("axial_joint_fluid", ("union",))
        reads("axial_joint_fluid", ("union",), "joint_fluid_observation")
    if offers and mapping is not None:
        reads("axial_joint_fluid", ("union",), "study_map_offer")
        mapping.smap.refine("joint_fluid", offers)
    return found, missing


def anterior_recess_from_axial_pockets(
    found: list[Observation], missing: list[Unresolved]
) -> tuple[list[Observation], list[Unresolved]]:
    """Describe the same native axial fluid-pocket support as anterior recess.

    This is a second description of the already saved union, not a new mask or
    measurement. Resolved pixels localize a fluid-filled anterior patellofemoral
    cavity on that section; they do not describe its full envelope or its
    suprapatellar extent. A measured-empty source remains a reading and does not
    say the cavity is absent elsewhere.
    """
    observations: list[Observation] = []
    unresolved: list[Unresolved] = []
    for source in found:
        if (
            source.object != "joint_fluid"
            or source.provenance != "native"
            or source.kind not in ("resolved", "reading")
            or source.view[0].casefold() != "axial"
            or source.support != "a4_axial_joint_fluid"
        ):
            continue
        if source.kind == "resolved":
            reads("axial_joint_fluid", ("union",), "anterior_recess_observation")
            note = (
                "The same saved native fluid-pocket support also describes the "
                "fluid-filled anterior patellofemoral cavity on this section; "
                "a partial description, not its full envelope or suprapatellar extent."
            )
        else:
            note = (
                "The native fluid-union reading was measured empty on this section; "
                "it does not say the cavity is absent elsewhere or describe its full "
                "envelope or suprapatellar extent."
            )
        observations.append(
            replace(source, object="anterior_synovial_recess", note=note)
        )
    for source in missing:
        if (
            source.object == "joint_fluid"
            and source.provenance == "native"
            and source.view is not None
            and source.view[0].casefold() == "axial"
        ):
            unresolved.append(
                replace(
                    source,
                    object="anterior_synovial_recess",
                    code=f"axial_anterior_recess:{source.code}",
                )
            )
    return observations, unresolved


def axial_capsule_observations(
    found: list[Observation], missing: list[Unresolved]
) -> tuple[list[Observation], list[Unresolved]]:
    """Use the existing axial retinacular outer-wall observations to localize capsule.

    These are the same saved wall bands beside the joint recess, described as capsule
    localization at that recess. They do not describe an envelope, thickness, or full course.
    No mask is constructed and every source address and measurement is retained.
    """
    wall_supports = {
        RETINACULA[0]: {
            f"a2_{RETINACULA[0]}",
            "a3_recess_plane_medial_wall",
        },
        RETINACULA[1]: {
            f"a2_{RETINACULA[1]}",
            "a3_recess_plane_lateral_wall",
        },
    }
    observations: list[Observation] = []
    unresolved: list[Unresolved] = []

    def capsule_unresolved(
        name: str,
        series_uid: str | None,
        view: tuple[str, str, str] | None,
        reasons: list[str],
    ) -> None:
        unresolved.append(
            Unresolved(
                "joint_capsule",
                "native",
                series_uid,
                view,
                f"{name}:{'|'.join(reasons)}",
            )
        )

    for source in found:
        if source.object not in RETINACULA:
            continue
        if source.provenance != "native" or source.kind != "resolved":
            continue
        view = cast(Any, source.view)
        if (
            not isinstance(view, tuple)
            or len(view) != 3
            or not all(isinstance(part, str) for part in view)
        ):
            capsule_unresolved(
                source.object,
                source.series_uid,
                source.view if isinstance(view, tuple) else None,
                ["source_view_invalid"],
            )
            continue
        if view[0].casefold() != "axial":
            continue
        reasons: list[str] = []
        if source.code not in NAMED:
            reasons.append("source_code_unavailable")
        if (
            len(source.slices) != 1
            or isinstance(source.slices[0], (bool, np.bool_))
            or not isinstance(source.slices[0], int | np.integer)
            or int(source.slices[0]) < 0
        ):
            reasons.append("source_slice_invalid")
        if (
            isinstance(source.count, (bool, np.bool_))
            or not isinstance(source.count, int | np.integer)
            or int(source.count) <= 0
        ):
            reasons.append("source_count_invalid")
        if (
            not isinstance(source.support, str)
            or source.support not in wall_supports[source.object]
        ):
            reasons.append("source_support_unavailable")
        elif source.support == f"a2_{source.object}":
            if source.row is not None:
                reasons.append("source_row_invalid")
        elif (
            isinstance(source.row, (bool, np.bool_))
            or not isinstance(source.row, int | np.integer)
            or int(source.row) < 0
        ):
            reasons.append("source_row_invalid")
        if source.label is not None:
            reasons.append("source_label_unexpected")
        if not source.artifact:
            reasons.append("source_artifact_unavailable")
        if not source.series_uid:
            reasons.append("source_series_unavailable")
        if reasons:
            capsule_unresolved(
                source.object,
                source.series_uid,
                source.view,
                reasons,
            )
            continue
        observations.append(
            replace(
                source,
                object="joint_capsule",
                note=(
                    f"The existing native axial outer-wall band of {source.object} beside "
                    "the joint recess also localizes capsule at this recess; this does not "
                    "describe an envelope, thickness, or full course."
                ),
            )
        )

    for source in missing:
        if source.object not in RETINACULA or source.provenance != "native":
            continue
        view = cast(Any, source.view)
        if (
            not isinstance(view, tuple)
            or len(view) != 3
            or not all(isinstance(part, str) for part in view)
        ):
            capsule_unresolved(
                source.object,
                source.series_uid,
                view if isinstance(view, tuple) else None,
                ["source_view_invalid"],
            )
            continue
        if view[0].casefold() == "axial":
            unresolved.append(
                Unresolved(
                    "joint_capsule",
                    source.provenance,
                    source.series_uid,
                    source.view,
                    f"{source.object}:{source.code}",
                )
            )
    return observations, unresolved


def cavity_lining_observations(
    walls: list[Observation],
    missing: list[Unresolved],
    arrays: dict[str, np.ndarray],
) -> tuple[list[Observation], list[Unresolved]]:
    """Address the cavity-side edge retained by each already validated capsule wall.

    The wall loop measures this edge on the fluid side in its existing native
    section. Capsule observations supply the validated series/slice/row address,
    not a lining mask or count. Missing support is unknown; an actually empty
    saved edge is a measured reading, never a claim that synovium is absent.
    """
    supports = {
        "a3_recess_plane_medial_wall": ("a3_recess_plane_medial_lining", "medial_edge"),
        "a3_recess_plane_lateral_wall": (
            "a3_recess_plane_lateral_lining",
            "lateral_edge",
        ),
        f"a2_{RETINACULA[0]}": ("a2_retinacula_positive_inner_lining", "medial_edge"),
        f"a2_{RETINACULA[1]}": ("a2_retinacula_negative_inner_lining", "lateral_edge"),
        "a2_joint_capsule": ("a4_coronal_lining", "side_edge"),
        "a3_recess_plane_capsule": ("a3_recess_plane_side_lining", "side_edge"),
    }
    found: list[Observation] = []
    unresolved = [
        replace(
            reason,
            object="synovium",
            code=(
                f"coronal_cavity_face:{reason.code}"
                if reason.view is not None and reason.view[0].casefold() == "coronal"
                else f"axial_cavity_face:{reason.code}"
            ),
        )
        for reason in missing
    ]
    for wall in walls:
        if (
            wall.object != "joint_capsule"
            or wall.provenance != "native"
            or wall.kind != "resolved"
        ):
            continue
        address = supports.get(wall.support) if isinstance(wall.support, str) else None
        coronal = wall.view[0].casefold() == "coronal"
        product = "coronal_lining" if coronal else "axial_lining"
        prefix = "coronal_cavity_face" if coronal else "axial_cavity_face"
        reason = ""
        if address is None:
            reason = "source_wall_support_invalid"
        else:
            support, field = address
            edge = arrays.get(support)
            if edge is None:
                reason = "source_lining_support_missing"
            elif not isinstance(edge, np.ndarray) or edge.dtype != np.bool_:
                reason = "source_lining_support_invalid"
            elif wall.row is None:
                if edge.ndim != 2 or support not in {
                    "a4_coronal_lining",
                    "a2_retinacula_positive_inner_lining",
                    "a2_retinacula_negative_inner_lining",
                }:
                    reason = "source_lining_address_invalid"
            elif (
                isinstance(wall.row, (bool, np.bool_))
                or not isinstance(wall.row, int | np.integer)
                or edge.ndim != 3
                or not 0 <= int(wall.row) < edge.shape[0]
                or not support.startswith("a3_")
            ):
                reason = "source_lining_address_invalid"
            else:
                slices = arrays.get("a3_recess_plane_slices")
                if (
                    not isinstance(slices, np.ndarray)
                    or slices.ndim != 1
                    or slices.dtype.kind not in "iu"
                    or int(wall.row) >= len(slices)
                    or tuple(wall.slices) != (int(slices[int(wall.row)]),)
                ):
                    reason = "source_lining_slice_mismatch"
            if not reason:
                assert isinstance(edge, np.ndarray)
                mask = edge if wall.row is None else edge[int(wall.row)]
                reads(product, (field,), "lining_observations")
                count = int(np.count_nonzero(mask))
                found.append(
                    replace(
                        wall,
                        object="synovium",
                        kind="resolved" if count else "reading",
                        code=wall.code
                        if count
                        else "observed_empty_cavity_facing_edge",
                        count=count,
                        support=support,
                        label=None,
                        note=(
                            "The cavity-side fluid edge facing this recess's accepted "
                            "outer wall, sampled in the wall's native sections; surface "
                            "location only, not membrane signal, thickness or full course."
                        ),
                    )
                )
        if reason:
            unresolved.append(
                Unresolved(
                    "synovium",
                    "native",
                    wall.series_uid,
                    wall.view,
                    f"{prefix}:{reason}",
                )
            )
    return found, unresolved


def recess_existing(
    measured: list[Measured],
    found: list[tuple[dict, dict[str, np.ndarray]]],
    study_uid: str,
) -> tuple[
    list[tuple[list[Observation], list[Unresolved]]],
    list[tuple[list[Observation], list[Unresolved]]],
]:
    """Keep native walls; return capsule and separately measured cavity-side descriptions.

    The bootstrap remains beside the pointed planes. Each wall is observed once from
    its existing saved support; the same observation also describes the local capsule
    outside that recess. Capsule additions are returned for the later append point so
    earlier observations retain their order.
    """
    by_uid = {m.record["series_uid"]: m for m in measured}
    capsule_said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    lining_said: list[tuple[list[Observation], list[Unresolved]]] = [
        ([], []) for _ in measured
    ]
    capsule_by_uid = {
        own.record["series_uid"]: said
        for own, said in zip(measured, capsule_said, strict=True)
    }
    lining_by_uid = {
        own.record["series_uid"]: said
        for own, said in zip(measured, lining_said, strict=True)
    }
    for record, arrays in found:
        own = by_uid.get(record["series_uid"])
        if own is None:
            continue
        for name in RETINACULA:
            code = record["assignments"]["codes"].get(name)
            mask = arrays.get(f"a2_{name}")
            if code not in NAMED or mask is None or not mask.any():
                continue
            count = int(np.count_nonzero(mask))
            wall = observe(
                name,
                "native",
                "resolved",
                own,
                (int(record["slice_index"]),),
                str(code),
                count,
                0.0,
                f"a2_{name}",
                "the retinacula stage's own slice (the main run's record): the wall's section on this slice, not its course",
                str(artifact_of(study_uid, record)),
            )
            keep_observations(own, [wall], [])
            here, missing = axial_capsule_observations([wall], [])
            kept, refused = capsule_by_uid[record["series_uid"]]
            kept.extend(here)
            refused.extend(missing)
            lining_here, lining_missing = cavity_lining_observations(
                here, missing, arrays
            )
            lining_kept, lining_refused = lining_by_uid[record["series_uid"]]
            lining_kept.extend(lining_here)
            lining_refused.extend(lining_missing)
            if isinstance(own.record.get("recess"), dict):
                own.record["recess"].setdefault("existing_slices", []).append(
                    {
                        "part": name,
                        "slice": int(record["slice_index"]),
                        "code": str(code),
                        "pixels": count,
                    }
                )
    return capsule_said, lining_said


def acl_slice(own: Measured) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The ACL's slice of one series, read (the ACL's paragraph in `knee.objects.assignments`): the
    middle slice's neighbour on the knee's outer side, chosen by place from the header and not read
    off the squint, with the femur and the tibia carried there from the middle slice, and the ACL
    named where fat is suppressed; or why it was not read."""
    series, record = own.series, own.record
    knee = record["assignments"]["knee"]
    reads("naming", ("in_plane",), "acl")
    front_in_plane = own.assignment.in_plane[1]
    reads("partner", ("objects",), "acl")
    before = own.arrays["a1_objects"]
    femur_before = before == OBJECT_CODES["femur"]
    tibia_before = before == OBJECT_CODES["tibia"]
    bones = bool(femur_before.any() and tibia_before.any())
    code = acl_code(front_in_plane, knee, bones, True, True)
    if code != "identified":
        return code
    reads("series", ("volume",), "acl")
    volume = series.volume
    if volume is None or len(volume) < 2:
        return "no_slice_beside_the_middle"
    middle = record["slice_index"]
    step = 1 if middle + 1 < len(volume) else -1
    neighbour = plane_frame(series, middle + step)
    if isinstance(neighbour, str):
        return neighbour
    toward_left = step * float(neighbour.origin_lps[0] - own.frame.origin_lps[0])
    z = middle + outer_step(knee, toward_left)
    if not 0 <= z < len(volume):
        return "no_slice_on_the_outer_side"
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return frame
    reads("background", ("split",), "acl")
    plane = volume[z]
    acl_record, arrays, field = read_part_slice(
        series, z, plane, frame, record["background_split"], knee, "acl"
    )
    labels = arrays["b1_labels"]
    measures = measures_of(series.row.series_uid, z, plane, frame)
    femur = carried_bone(labels, femur_before, measures)
    tibia = carried_bone(labels, tibia_before, measures)
    carried = bool(femur.any() and tibia.any())
    fat_suppressed = int(series.row.fat_suppression) == 1  # the tag is stored as text
    acl = np.zeros(labels.shape, dtype=bool)
    if carried and fat_suppressed:
        reads("field", ("peaks",), "acl")
        acl = acl_on_slice(
            labels,
            field.peaks,
            femur,
            tibia,
            frame.basis_lps,
            margin_of(series.row.series_uid, z, plane),
        )
    # On its slice only the ACL is named, between the bones it was found between; the middle
    # slice's other objects are not named here: their rules belong to the middle slice.
    objects = np.zeros(labels.shape, dtype=np.int8)
    objects[femur] = OBJECT_CODES["femur"]
    objects[tibia] = OBJECT_CODES["tibia"]
    objects[acl] = OBJECT_CODES["acl"]
    arrays["a1_objects"] = objects
    assigned = acl_record["assignments"]
    codes = assigned["codes"]
    codes["femur"] = codes["tibia"] = "carried_from_the_middle_slice"
    codes["acl"] = acl_code(True, knee, carried, fat_suppressed, bool(acl.any()))
    assigned.update(acl=int(labels[acl].max()) if acl.any() else None)
    acl_record["main_slice"] = {"object": "ACL"}
    return acl_record, arrays, frame


def lcl_slice(
    own: Measured, fibula_lps: np.ndarray | None
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The LCL's slice of one series, read (the LCL's paragraph in `knee.objects.assignments`): the
    slice through the place on the fibula's head where the LCL attaches, the fibula being the one
    its own rule named on its main slice, carried by place; the femur carried there from the middle
    slice; and the LCL named where fat is not suppressed; or why it was not read."""
    series, record = own.series, own.record
    assigned = record["assignments"]
    reads("naming", ("in_plane",), "lcl")
    sides_in_plane = own.assignment.in_plane[0]
    reads("partner", ("objects",), "lcl")
    femur_before = own.arrays["a1_objects"] == OBJECT_CODES["femur"]
    bones = bool(femur_before.any()) and assigned["tibia"] is not None
    named = fibula_lps is not None
    code = lcl_code(sides_in_plane, named, bones, True, False, True, True)
    if code != "identified" or fibula_lps is None:
        return code
    reads("fibula", ("places",), "lcl")
    reads("series", ("geometry", "slice_thickness_mm", "volume"), "lcl")
    geometry, volume, thicknesses = (
        series.geometry,
        series.volume,
        series.slice_thickness_mm,
    )
    if geometry is None or volume is None:
        return "geometry_unreadable"
    known = [float(t) for t in thicknesses if t is not None]
    if len(known) != len(thicknesses):
        return "no_slice_thickness"
    origins = np.asarray([np.asarray(p, dtype=float) for p in geometry.position])
    z = slice_through(lcl_attachment(fibula_lps), origins, own.frame.normal(), known)
    if z is None:
        return lcl_code(True, True, True, False, False, True, True)
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return frame
    reads("background", ("split",), "lcl")
    lcl_record, arrays, _ = read_part_slice(
        series,
        z,
        volume[z],
        frame,
        record["background_split"],
        assigned["knee"],
        "lcl",
    )
    labels = arrays["b1_labels"]
    measures = measures_of(series.row.series_uid, z, arrays["acquired_plane"], frame)
    femur = carried_bone(labels, femur_before, measures)
    fibula_places = places_on_slice(fibula_lps, frame, labels.shape, known[z])
    fibula = region_holding(labels, fibula_places)
    fat_suppressed = int(series.row.fat_suppression) == 1  # the tag is stored as text
    reads("naming", ("tibia", "peaks"), "lcl")
    peak = next(p for p in assigned["peaks"] if p["territory"] == assigned["tibia"])
    tibia_middle = own.frame.to_patient(np.asarray([peak["peak_rc"]], dtype=float))[0]
    lcl = np.zeros(labels.shape, dtype=bool)
    if femur.any() and fibula.any() and not fat_suppressed:
        rows, cols = np.indices(labels.shape)
        across = (
            frame.origin_lps[0]
            + frame.basis_lps[0, 0] * rows
            + frame.basis_lps[0, 1] * cols
        )
        lcl = lcl_on_slice(
            labels,
            femur,
            fibula,
            across,
            float(tibia_middle[0]),
            float(fibula_lps[:, 0].mean()),
            np.asarray(frame.spacing_rc),
            measures,
        )
    # On its slice only the LCL is named, with the fibula's own places carried from its main slice;
    # the regions of the femur and of the fibula are its targets, never its names, since on a T1
    # the fibula's head may share a region with the tibia.
    objects = np.zeros(labels.shape, dtype=np.int8)
    objects[fibula_places] = OBJECT_CODES["fibula"]
    objects[lcl] = OBJECT_CODES["lcl"]
    arrays["a1_objects"] = objects
    lcl_assigned = lcl_record["assignments"]
    codes = lcl_assigned["codes"]
    codes["fibula"] = "carried_from_its_main_slice"
    codes["lcl"] = lcl_code(
        True,
        True,
        bool(femur.any()),
        True,
        fat_suppressed,
        bool(fibula.any()),
        bool(lcl.any()),
    )
    arrays["a2_lcl_carried_femur"] = femur
    if fat_suppressed:
        arrays["a2_popliteus_tendon"] = np.zeros(labels.shape, dtype=bool)
        codes["popliteus_tendon"] = "abstain_requires_the_nonfs_notch_view"
    else:
        reads("lcl", ("region",), "popliteus_tendon")
        popliteus, notch_readings, popliteus_code = popliteus_in_notch(femur, lcl)
        arrays["a2_popliteus_tendon"] = popliteus
        for name, value in notch_readings.items():
            arrays[f"a2_popliteus_{name}"] = value
        codes["popliteus_tendon"] = popliteus_code
        if popliteus.any():
            handed("popliteus_tendon", ("region",))
    lcl_assigned.update(lcl=int(labels[lcl].max()) if lcl.any() else None)
    lcl_record["main_slice"] = {"object": "LCL"}
    return lcl_record, arrays, frame


def seen_native(
    series: Series, z: int, stage: str = BICEPS
) -> tuple[np.ndarray, np.ndarray]:
    """One native slice's stored light and the places it has none for (not finite, or the black
    margin the reconstruction never filled), read once per slice and handed to every stage that
    asks: the fibula's cheap profile, the head's body, the reference light, the biceps femoris
    tendon's rule (`stage` is the asker, whose read the ledger records when it is the first). The
    rule is given the light with the unseen places NaN, so no place it never saw reads as
    darkness."""

    def read() -> tuple[np.ndarray, np.ndarray]:
        reads("series", ("volume",), stage)
        uid = series.row.series_uid
        raw = np.asarray(series.volume[z], dtype=np.float64)
        return handed_on(raw), handed_on(~np.isfinite(raw) | margin_of(uid, z, raw))

    return once("biceps_native_light", (series.row.series_uid, z), read)


def biceps_twin(
    native: Measured, twin: Measured, z: int, stage: str = BICEPS
) -> tuple[np.ndarray, int] | str:
    """The fat-suppressed twin's light laid onto the pixels of the native slice `z`, NaN where the
    twin has no say (outside its picture or in its black margin), and the twin's own slice index;
    or why not. The twin's slice is the one whose plane passes through the native slice's place,
    found by the scanner's millimetres and never by equal indices (`slice_through`); the pair is
    matched once, native pixels onto the twin's (`matched`)."""

    def read() -> tuple[np.ndarray, int] | str:
        series, other = native.series, twin.series
        frame = plane_frame(series, z)
        reads("series", ("geometry", "slice_thickness_mm", "volume"), stage)
        if isinstance(frame, str) or other.geometry is None or other.volume is None:
            return "geometry_unreadable"
        known = [float(t) for t in other.slice_thickness_mm if t is not None]
        if len(known) != len(other.slice_thickness_mm):
            return "abstain_no_slice_thickness"
        origins = np.asarray(
            [np.asarray(p, dtype=float) for p in other.geometry.position]
        )
        index = slice_through(frame.origin_lps, origins, twin.frame.normal(), known)
        if index is None:
            return "abstain_twin_has_no_slice_at_this_place"
        twin_frame = plane_frame(other, index)
        if isinstance(twin_frame, str):
            return twin_frame
        plane = other.volume[index]
        raw, _ = seen_native(series, z, stage)
        source = matched(
            series,
            {"series_uid": series.row.series_uid, "slice_index": z},
            frame,
            raw.shape,
            {"series_uid": other.row.series_uid, "slice_index": index},
            twin_frame,
            plane,
        )
        if isinstance(source, str):
            return f"abstain_{source}"
        laid = laid_by(np.asarray(plane, dtype=np.float64), source)
        handed("biceps_twin", ("laid",))
        return handed_on(np.where(source >= 0, laid, np.nan)), index

    return once("biceps_twin", (native.series.row.series_uid, z), read)


def biceps_native(
    own: Measured,
    twin: Measured | None,
    fibula_lps: np.ndarray | None,
    fibula: FibulaFound | None = None,
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame, str, int] | str:
    """The biceps femoris tendon's slice on a fat-bright series, read (its paragraph in
    `knee.objects.assignments`), with its twin's series and slice: from the fibula already found
    (`find_fibula`), whose places recover its main slice here, and whose marrow light there, in both
    acquisitions, is read once and handed on when `fibula` is the shared value of this very series
    and twin (`FibulaFound`), else read here (once); the head's body on each slice is the shared
    reading (`fibula_head`), made once for the fibula's continuation and this walk alike; then the
    walk outward to the head's lateral face
    (`lateral_to_the_head`), which asks for a slice's head only when it reaches it, each kept; and
    on the slice it chooses, the lens and field once (`read_part_slice`) and the rule
    (`proximal_biceps_on_slice`) with that same head. Or why it was not read. Every head the walk
    measured, its areas and status per slice (NaN and unread where the walk never went), the lights
    and the twin as laid are kept in the arrays beside the rule's own readings."""
    series, record = own.series, own.record
    uid = series.row.series_uid
    knee = record["assignments"]["knee"]
    reads("fibula", ("places",), BICEPS)
    if fibula_lps is None:
        return "abstain_no_fibula"
    if twin is None:
        return "abstain_no_fat_suppressed_twin"
    reads("series", ("geometry", "slice_thickness_mm", "volume"), BICEPS)
    geometry, volume = series.geometry, series.volume
    thicknesses = series.slice_thickness_mm
    if geometry is None or volume is None:
        return "geometry_unreadable"
    origins = np.asarray([np.asarray(p, dtype=float) for p in geometry.position])
    if (
        origins.ndim != 2
        or origins.shape[1] != 3
        or not np.all(np.isfinite(origins))
        or len(thicknesses) != len(origins)
        or len(volume) != len(origins)
    ):
        return "geometry_unreadable"
    normal = own.frame.normal()
    places = np.asarray(fibula_lps, dtype=np.float64)
    other = twin

    def reference() -> tuple[int | None, float, float, str | None]:
        """The fibula's native main slice, its marrow light there in both acquisitions and, if the
        twin could not be read there, why: made once, when the walk first asks for a head."""

        def read() -> tuple[int | None, float, float, str | None]:
            none = float("nan")
            if (
                fibula is not None
                and fibula.places is places
                and fibula.series_uid == uid
                and fibula.twin_uid == other.series.row.series_uid
                and np.isfinite(fibula.twin_light)
            ):
                # the fibula's own stage read both lights on its main slice: not read again
                reads("fibula", ("slice_index", "light", "twin_light"), BICEPS)
                return fibula.slice_index, fibula.light, fibula.twin_light, None
            main = slice_through(
                places.mean(axis=0), origins, normal, [float(t) for t in thicknesses]
            )
            if main is None:
                return main, none, none, "abstain_no_slice_holds_the_fibula"
            frame = plane_frame(series, main)
            if isinstance(frame, str):
                return main, none, none, frame
            plane, unseen = seen_native(series, main)
            support = projected_places(places, frame, plane.shape) & ~unseen
            light = (
                float(measures_of(uid, main, plane, frame).light(support))
                if support.any()
                else none
            )
            laid = biceps_twin(own, other, main)
            if isinstance(laid, str):
                return main, light, none, laid
            reads("biceps_twin", ("laid",), "biceps_reference")
            return main, light, twin_marrow_light(laid[0], support), None

        return once("biceps_reference", uid, read)

    # The walk is the fibula's own (`fibula_support`) when it is the same measurement: the same
    # series, places, knee, geometry and marrow light. It is handed here whole, every head it measured
    # included; the light is asked of the reference only when the walk reaches a head.
    walk = head_walk(
        series, places, knee, origins, normal, thicknesses, lambda: reference()[1]
    )
    reads("head_walk", ("face", "areas", "status", "heads"), BICEPS)
    z, areas, status, law = walk.face, walk.areas, walk.status, walk.code
    heads = dict(zip(walk.walked, walk.heads, strict=True))
    ledger.record(f"{BICEPS}.head_readings", planes=len(heads))
    if z is None:
        if law == "abstain_head_unreadable_on_the_way" and heads:
            return list(heads.values())[-1][2]  # why the head could not be read there
        return law
    main, light, twin_light, why = reference()
    frame = plane_frame(series, z)
    if isinstance(frame, str):
        return frame
    laid = biceps_twin(own, other, z)
    if isinstance(laid, str):
        return laid
    if why is not None or main is None:
        return why or "abstain_no_slice_holds_the_fibula"
    twin_light_map, twin_index = laid
    reads("background", ("split",), BICEPS)
    part_record, arrays, _ = read_part_slice(
        series, z, volume[z], frame, record["background_split"], knee, BICEPS
    )
    plane, unseen = seen_native(series, z)
    body = heads[z][0]
    reads("fibula_head", ("body",), BICEPS)
    reads("biceps_twin", ("laid",), BICEPS)
    mask, readings, code = proximal_biceps_on_slice(
        np.where(unseen, np.nan, plane),
        twin_light_map,
        frame.basis_lps,
        light,
        twin_light,
        body,
        int(series.row.fat_suppression) == 1,
        measures_of(uid, z, plane, frame),
    )
    walked = list(heads)
    arrays["a1_objects"] = np.zeros(plane.shape, dtype=np.int8)
    arrays["a2_biceps_femoris_tendon"] = mask
    for name, value in readings.items():
        arrays[f"a2_biceps_{name}"] = value
    arrays.update(
        a2_biceps_head_slices=np.asarray(walked, dtype=np.int32),
        a2_biceps_head_bodies=np.stack([heads[w][0] for w in walked]),
        a2_biceps_head_targets=np.stack([heads[w][1] for w in walked]),
        a2_biceps_head_areas_mm2=np.asarray(areas, dtype=np.float64),
        a2_biceps_head_slice_status=np.asarray(status, dtype=np.int8),
        a2_biceps_fibula_main_slice=np.asarray(main, dtype=np.int32),
        a2_biceps_selected_slice=np.asarray(z, dtype=np.int32),
        a2_biceps_twin_slice=np.asarray(twin_index, dtype=np.int32),
        a2_biceps_reference_light=np.asarray(light, dtype=np.float64),
        a2_biceps_reference_twin_light=np.asarray(twin_light, dtype=np.float64),
        a2_biceps_fibula_places_lps=places,
        a2_biceps_twin_laid=twin_light_map,
        a2_biceps_native_unseen=unseen,
    )
    part_record["assignments"]["codes"][BICEPS] = code
    part_record["main_slice"] = {
        "object": BICEPS,
        "fibula_main_slice": int(main),
        "selected_slice": int(z),
        "twin_series_uid": other.series.row.series_uid,
        "twin_slice_index": int(twin_index),
        "head_codes": {str(w): heads[w][2] for w in walked},
    }
    return part_record, arrays, frame, other.series.row.series_uid, twin_index


def biceps_femoris_slice(
    own: Measured,
    measured: list[Measured],
    fibula_lps: np.ndarray | None,
    fibula: FibulaFound | None = None,
) -> tuple[dict, dict[str, np.ndarray], PlaneFrame] | str:
    """The biceps femoris tendon's slice of one series, read once for the pair: on the fat-bright
    series by `biceps_native` (kept for its twin, made by whichever of the two asks first), and on
    its fat-suppressed twin the slice of the same place in the scanner's millimetres, read for its
    lens and field only, to which `find_part` lays the native mask (`lay_parts`); or why it was not
    read: no fibula, no twin, no view, no head, no tendon."""
    reads("series", ("row",), BICEPS)
    fat_suppressed = (
        int(own.series.row.fat_suppression) == 1
    )  # the tag is stored as text
    if fat_suppressed:
        native_at = partner_of(
            measured, next(i for i, m in enumerate(measured) if m is own)
        )
        if native_at is None:
            return "abstain_no_fat_bright_native_view"
    else:
        native_at = own
    twin = partner_of(
        measured, next(i for i, m in enumerate(measured) if m is native_at)
    )
    native = once(
        "biceps_native",
        native_at.series.row.series_uid,
        lambda: biceps_native(native_at, twin, fibula_lps, fibula),
    )
    if isinstance(native, str):
        return native
    record, arrays, frame, twin_uid, twin_index = native
    if not fat_suppressed:
        return record, arrays, frame
    if twin_uid != own.series.row.series_uid:
        return "abstain_the_native_view_has_another_twin"
    volume = own.series.volume
    twin_frame = plane_frame(own.series, twin_index)
    if volume is None or isinstance(twin_frame, str):
        return "geometry_unreadable"
    reads("background", ("split",), BICEPS)
    twin_record, twin_arrays, _ = read_part_slice(
        own.series,
        twin_index,
        volume[twin_index],
        twin_frame,
        own.record["background_split"],
        own.record["assignments"]["knee"],
        BICEPS,
    )
    # on this slice the mask is the native one's, laid; until then nothing is named
    twin_arrays["a1_objects"] = np.zeros(twin_arrays["acquired_plane"].shape, np.int8)
    twin_arrays["a2_biceps_femoris_tendon"] = np.zeros(
        twin_arrays["acquired_plane"].shape, dtype=bool
    )
    twin_record["assignments"]["codes"][BICEPS] = BICEPS_LAID_WHEN
    twin_record["main_slice"] = {
        "object": BICEPS,
        "native_series_uid": record["series_uid"],
        "native_slice_index": int(record["slice_index"]),
    }
    return twin_record, twin_arrays, twin_frame


# -- THE POSTERIOR FAMILY: what the views say of the back of the knee's parts --------------------
# The two gastrocnemius heads, the popliteal lumens, the three hamstring tendons, the sartorius and
# the bursa are named by their own rules on the axial slices (`name_the_back_of_the_knee`,
# `semimembranosus_slice`, `name_sartorius`), the popliteus tendon and the biceps femoris tendon
# on their own slices, the iliotibial band on the middle coronal. Those rules and their slices
# are untouched. This is the one place that says what each of them made, by where the saying
# comes from (`knee.collapse.observations`), and asks the one cheap question the data can
# answer about the others' continuation (`knee.collapse.posterior`).
#
# What is read and what is not. A tube (a tendon or a vessel: dark; the bursa's fluid: bright on a
# fluid-sensitive fat-suppressed view) is followed along the leg on the nearest slice of every
# series the leg runs through, from where its cross-section projects, on the light already read
# for the biceps femoris tendon (`seen_native`: made once per slice), with no lens or field. A
# muscle belly (the heads, the sartorius) and the iliotibial band, the popliteus and the biceps
# femoris tendon, which already are longitudinal on their own slices, get their native, laid and
# projected observations and no continuation: nothing here claims one.
#
# Two passes. The first runs before the middle records and the semimembranosus group's are
# saved (the trace arrays are kept in the record that holds the cross-section's mask and are saved
# with it); the second runs after the lateral parts are found and adds rows only.

# the product and field the ledger knows a part's mask by (`handed` where the part was made)
POSTERIOR_PRODUCT = {
    "medial_gastrocnemius": ("gastrocnemius", "region"),
    "lateral_gastrocnemius": ("gastrocnemius", "region"),
    "popliteal_artery": ("popliteal_lumens", "artery"),
    "popliteal_vein": ("popliteal_lumens", "vein"),
    "sartorius": ("sartorius", "region"),
    "iliotibial_band": ("iliotibial_band", "region"),
    "semimembranosus": ("semimembranosus", "region"),
    "semitendinosus": ("semitendinosus", "region"),
    "gracilis": ("gracilis", "region"),
    "gastrocnemius_semimembranosus_bursa": ("bursa", "region"),
    "popliteus_tendon": ("popliteus_tendon", "region"),
    BICEPS: (BICEPS, "region"),
}
# (part, the array of a record that holds its places, whether that array is coded by OBJECT_CODES)
EARLY_MIDDLE_PARTS = (
    ("medial_gastrocnemius", "a1_objects", True),
    ("lateral_gastrocnemius", "a1_objects", True),
    ("popliteal_artery", "a2_popliteal_artery", False),
    ("popliteal_vein", "a2_popliteal_vein", False),
    ("sartorius", "a2_sartorius", False),
)
LATE_MIDDLE_PARTS = (("iliotibial_band", "a2_iliotibial_band", False),)
# The context the middle slices already name (`a1_objects`): said natively or laid, where named, as
# the middle slice's own naming and no more: no slice is claimed ideal for them, they are not
# projected onto other series, and nothing is followed. Bone marrow is a property of each named
# bone's interior, not an object here.
CONTEXT_MIDDLE_PARTS = (
    ("joint", "a1_objects", True),
    ("meniscus", "a1_objects", True),
    ("air", "a1_objects", True),
    ("skin", "a1_objects", True),
    ("subcutaneous_fat", "a1_objects", True),
    ("muscle", "a1_objects", True),
)
CONTEXT_PARTS = frozenset(name for name, _, _ in CONTEXT_MIDDLE_PARTS)
# a part's own slice's record, by the part it is the main slice of
MAIN_RECORD_PARTS = {
    "semimembranosus": (
        ("semimembranosus", "a1_objects", True),
        ("semitendinosus", "a2_semitendinosus", False),
        ("gracilis", "a2_gracilis", False),
        (
            "gastrocnemius_semimembranosus_bursa",
            "a2_gastrocnemius_semimembranosus_bursa",
            False,
        ),
    ),
    "lcl": (("popliteus_tendon", "a2_popliteus_tendon", False),),
    BICEPS: ((BICEPS, "a2_biceps_femoris_tendon", False),),
}
# what `find_part` already keeps as a silence, by series, when these parts abstain on a main slice
SILENT_BY_FIND_PART = frozenset(
    ("semimembranosus", "semitendinosus", "gracilis", "popliteus_tendon", BICEPS)
)
POSTERIOR_PARTS = frozenset(
    name
    for parts in (EARLY_MIDDLE_PARTS, LATE_MIDDLE_PARTS, *MAIN_RECORD_PARTS.values())
    for name, _, _ in parts
)
# the tubes that are followed, and whether each is dark (a tendon, an enclosed lumen) or bright
POSTERIOR_TUBES = {
    "semimembranosus": True,
    "semitendinosus": True,
    "gracilis": True,
    "popliteal_artery": True,
    "popliteal_vein": True,
    "gastrocnemius_semimembranosus_bursa": False,
}


@dataclass(frozen=True)
class PosteriorSource:
    """One native saying of a part, to project and to follow from: the record and arrays that hold
    its places, their slice's frame, the places, which array and label say them, the artifact
    that will hold them and how many there are."""

    name: str
    record: dict
    arrays: dict[str, np.ndarray]
    frame: PlaneFrame
    mask: np.ndarray
    support: str
    label: int | None
    artifact: str
    pixels: int


def posterior_sayings(
    record: dict,
    arrays: dict[str, np.ndarray],
    frame: PlaneFrame | str,
    parts: tuple[tuple[str, str, bool], ...],
    study_uid: str,
    by_silence: bool,
) -> tuple[list[Observation], list[Unresolved], list[PosteriorSource], set[str]]:
    """What one record says of each of `parts`, from its own codes and masks and counting nothing
    again: a part its rule named on this slice is native and resolved, one laid from its
    partner is laid and resolved, one the rule was asked and refused is an `Unresolved` with its
    code (kept as the refusal `find_part` already holds where `by_silence`, so it is said once).
    Returns the observations, the unresolved, the native sources, and the parts laid here."""
    codes = record["assignments"]["codes"]
    artifact = str(artifact_of(study_uid, record))
    uid, view, index = (
        record["series_uid"],
        tuple(record["view"]),
        record["slice_index"],
    )
    seen: list[Observation] = []
    unplaced: list[Unresolved] = []
    sources: list[PosteriorSource] = []
    laid: set[str] = set()
    for name, support, coded in parts:
        code = codes.get(name)
        if code is None or code == "not_named_on_this_slice":
            continue  # the rule was never asked of this record: nothing to say
        if code not in NAMED:
            if not by_silence:
                unplaced.append(Unresolved(name, "native", uid, view, str(code)))
            continue
        if name in POSTERIOR_PRODUCT:
            product, field = POSTERIOR_PRODUCT[name]
            reads(product, (field,), "posterior_index")
        array = arrays[support]
        mask = array == OBJECT_CODES[name] if coded else np.asarray(array, dtype=bool)
        pixels = int(np.count_nonzero(mask))
        if not pixels:
            unplaced.append(
                Unresolved(name, "native", uid, view, "named_without_a_place_on_it")
            )
            continue
        label = OBJECT_CODES[name] if coded else None
        if code == "laid_from_its_partner":
            laid.add(name)
            seen.append(
                observe_in(
                    record,
                    name,
                    "laid",
                    "resolved",
                    (index,),
                    str(code),
                    pixels,
                    None,
                    support,
                    "laid from the other sequence's slice of the same place by the pair's "
                    "match; the places the match cannot map are left out",
                    artifact,
                    None,
                    label,
                )
            )
            continue
        seen.append(
            observe_in(
                record,
                name,
                "native",
                "resolved",
                (index,),
                str(code),
                pixels,
                0.0,
                support,
                "the middle slice's own naming of this context, with no claim that this "
                "slice is its best: what the slice shows of it, not the whole"
                if name in CONTEXT_PARTS
                else "the established rule names it on this slice: its section here, not its "
                "whole extent or boundary",
                artifact,
                None,
                label,
            )
        )
        if not isinstance(frame, str) and name not in CONTEXT_PARTS:
            sources.append(
                PosteriorSource(
                    name, record, arrays, frame, mask, support, label, artifact, pixels
                )
            )
    return seen, unplaced, sources, laid


def read_trace(
    other: Measured, z: int, physical: np.ndarray, dark: bool
) -> tuple[Trace, np.ndarray] | str | None:
    """The tube whose cross-section lies at `physical` (scanner millimetres), followed along the
    leg on slice `z` of another series (`knee.collapse.posterior.trace_tube`), with the traced
    places in millimetres; None where the leg does not run in that slice (an axial one: nothing
    to ask there), or why it cannot be read (an unreadable frame, no width). The light is the
    slice's own, the places it never saw NaN (`seen_native`, made once)."""
    frame = plane_frame(other.series, z)
    if isinstance(frame, str):
        return frame
    along = leg_axis(frame.basis_lps)
    if along is None:
        return None
    axis, toward_head = along
    width = cross_extent_mm(physical, frame.basis_lps, axis)
    if width is None:
        return "target_has_no_finite_place"
    spacing = float(np.linalg.norm(frame.basis_lps[:, 1 - axis]))
    half = max(1, round(width / 2.0 / spacing))
    raw, unseen = seen_native(other.series, z, "posterior")
    reads("series", ("volume", "geometry"), "posterior")
    start = frame.to_native(physical).mean(axis=0)
    got = trace_tube(
        np.where(unseen, np.nan, raw),
        axis,
        toward_head,
        (float(start[0]), float(start[1])),
        half,
        dark,
    )
    ledger.record("posterior.trace_readings", planes=1)
    return got, (
        frame.to_patient(got.points_rc) if len(got.points_rc) else np.empty((0, 3))
    )


def trace_rows(
    source: PosteriorSource,
    leg: Leg | None,
    traces: list[tuple[Measured, int, float, Trace, np.ndarray]],
) -> list[tuple[Measured, Observation]]:
    """Keep every trace of one part in the arrays of the record that holds its cross-section (flat
    packed: `..._offsets` cuts trace i's places out of `..._points_lps`, `..._light`, `..._flank`;
    `..._slices`, `..._starts` and `..._stops` are per trace, the integers named by
    `START_NAMES` and `STOP_NAMES`), and say each as a native reading on the slice it was read on."""
    name = source.name
    prefix = f"a3_posterior_trace_{name}"
    sizes = [len(t[4]) for t in traces]
    arrays = source.arrays
    arrays[f"{prefix}_points_lps"] = np.concatenate([t[4] for t in traces])
    arrays[f"{prefix}_light"] = np.concatenate([t[3].light for t in traces])
    arrays[f"{prefix}_flank"] = np.concatenate([t[3].flank for t in traces])
    arrays[f"{prefix}_offsets"] = np.concatenate(([0], np.cumsum(sizes))).astype(
        np.int64
    )
    arrays[f"{prefix}_slices"] = np.asarray([t[1] for t in traces], dtype=np.int32)
    arrays[f"{prefix}_starts"] = np.asarray(
        [START_NAMES.index(t[3].start) for t in traces], dtype=np.int8
    )
    arrays[f"{prefix}_stops"] = np.asarray(
        [
            [
                STOP_NAMES.index(t[3].toward_head or STOP_NAMES[0]),
                STOP_NAMES.index(t[3].toward_feet or STOP_NAMES[0]),
            ]
            for t in traces
        ],
        dtype=np.int8,
    )
    top = (
        float(leg.tibia_lps[:, 2].max())
        if leg is not None and len(leg.tibia_lps)
        else np.nan
    )
    low = (
        float(leg.femur_lps[:, 2].min())
        if leg is not None and len(leg.femur_lps)
        else np.nan
    )
    arrays.setdefault("a3_posterior_context_up_mm", np.asarray([top, low]))
    handed(
        "posterior_trace",
        ("points", "light", "flank", "offsets", "slices", "starts", "stops", "context"),
    )
    reads("posterior_trace", ("points", "starts", "stops"), "posterior_index")
    out: list[tuple[Measured, Observation]] = []
    dark = POSTERIOR_TUBES[name]
    for k, (other, z, distance, got, points) in enumerate(traces):
        if got.start == FOLLOWED:
            height = f"z {points[:, 2].min():.1f} to {points[:, 2].max():.1f} mm"
            stops = f"toward the head it {got.toward_head}, toward the feet it {got.toward_feet}"
        else:
            height = "no place held"
            stops = "the relation did not hold at the projected place (the tube may lie off this slice)"
        out.append(
            (
                other,
                observe_in(
                    other.record,
                    name,
                    "native",
                    "reading",
                    (z,),
                    "tube_followed" if got.start == FOLLOWED else got.start,
                    len(points),
                    distance,
                    f"{prefix}_points_lps",
                    f"a cheap ridge followed along the leg from the cross-section's projected place "
                    f"({'darker' if dark else 'brighter'} than an equally wide strip on each side): "
                    f"{stops}; {height}; a pointer, not the part's boundary or full course; "
                    f"row {k} is points_lps[offsets[{k}]:offsets[{k + 1}]] of {prefix}_*; "
                    "a3_posterior_context_up_mm holds the tibia's top and the femur's lowest place",
                    source.artifact,
                    k,
                ),
            )
        )
    return out


def index_posterior(
    measured: list[Measured],
    middle_parts: tuple[tuple[str, str, bool], ...],
    main_records: list[tuple[dict, dict[str, np.ndarray]]],
    study_uid: str,
    leg: Leg | None,
    traced: bool,
) -> None:
    """Say, for each of the posterior family's parts, what every view of the study says of it: its
    native and laid sayings (`posterior_sayings`) on the middle records (`middle_parts`) and on the
    part's own slices (`main_records`), a projected target on every other series' nearest slice from
    its largest native section (a location to ask, never a boundary; skipped on the series that
    hold it laid), and, for a tube where `traced`, the continuation read on each series the leg runs
    through (`read_trace`). The rows are appended to the records of the series they are about."""
    by_uid = {m.record["series_uid"]: m for m in measured}
    sources: dict[str, list[PosteriorSource]] = {}
    laid_on: dict[str, set[str]] = {}

    def take(record, arrays, frame, parts, by_silence):
        seen, unplaced, native, laid = posterior_sayings(
            record, arrays, frame, parts, study_uid, by_silence
        )
        keep_on_record(record, seen, unplaced)
        for source in native:
            sources.setdefault(source.name, []).append(source)
        for name in laid:
            laid_on.setdefault(name, set()).add(record["series_uid"])

    for own in measured:
        take(own.record, own.arrays, own.frame, middle_parts, False)
    for record, arrays in main_records:
        parts = MAIN_RECORD_PARTS.get(str(record["main_slice"]["object"]).lower())
        own = by_uid.get(record["series_uid"])
        if parts is None or own is None:
            continue
        frame = plane_frame(own.series, record["slice_index"])
        take(
            record,
            arrays,
            frame,
            tuple(
                p
                for p in parts
                if p[0] not in SILENT_BY_FIND_PART
                or record["assignments"]["codes"].get(p[0]) in NAMED
            ),
            True,
        )

    def slot(added, other):
        return added.setdefault(other.record["series_uid"], (other, [], []))

    for name, found in sources.items():
        best = max(found, key=lambda s: s.pixels)
        physical = best.frame.to_patient(np.argwhere(best.mask).astype(float))
        dark = POSTERIOR_TUBES.get(name)
        traces: list[tuple[Measured, int, float, Trace, np.ndarray]] = []
        added: dict[str, tuple[Measured, list[Observation], list[Unresolved]]] = {}

        for other in measured:
            uid = other.record["series_uid"]
            if uid == best.record["series_uid"] or uid in laid_on.get(name, ()):
                continue
            view = tuple(other.record["view"])
            target = bone_target(physical, other)
            if isinstance(target, str):
                slot(added, other)[2].append(
                    Unresolved(name, "projected", uid, view, target)
                )
                continue
            nearest, place, distance, count = target
            slot(added, other)[1].append(
                observe_in(
                    other.record,
                    name,
                    "projected",
                    "target",
                    (nearest,),
                    place,
                    count,
                    distance,
                    best.support,
                    f"a location target projected from {name} on slice "
                    f"{best.record['slice_index']} of series {best.record['series_uid'][-8:]}: where "
                    "a native question may be asked, not a boundary seen on this slice",
                    best.artifact,
                    None,
                    best.label,
                )
            )
            if not traced or dark is None:
                continue
            if not dark and not (
                int(other.series.row.fat_suppression) == 1
                and int(other.series.row.fluid_sensitive) == 1
            ):
                slot(added, other)[2].append(
                    Unresolved(
                        name,
                        "native",
                        uid,
                        view,
                        "fluid_is_not_bright_in_this_sequence",
                    )
                )
                continue
            if place == "beyond_the_scan":
                slot(added, other)[2].append(
                    Unresolved(name, "native", uid, view, "target_beyond_the_scan")
                )
                continue
            got = read_trace(other, nearest, physical, dark)
            if isinstance(got, str):
                slot(added, other)[2].append(Unresolved(name, "native", uid, view, got))
            elif got is not None:
                traces.append((other, nearest, distance, got[0], got[1]))
        if traces:
            for other, row in trace_rows(best, leg, traces):
                slot(added, other)[1].append(row)
        for other, here, missing in added.values():
            keep_observations(other, here, missing)


def posterior_silences(measured: list[Measured], silences: dict[str, str]) -> None:
    """The posterior parts a series was asked and refused on a slice of their own, said as
    unresolved on that series: the silences `find_part` kept, by `<series uid>:<part>`, are
    the refusals; nothing is added to them and the part is not called absent."""
    by_uid = {m.record["series_uid"]: m for m in measured}
    for key, code in silences.items():
        uid, _, name = key.rpartition(":")
        own = by_uid.get(uid)
        if own is None or name not in POSTERIOR_PARTS:
            continue
        keep_observations(
            own,
            [],
            [Unresolved(name, "native", uid, tuple(own.record["view"]), str(code))],
        )


def lay_parts(
    own: Measured,
    read: tuple[dict, dict[str, np.ndarray], PlaneFrame],
    partner: tuple[dict, dict[str, np.ndarray], PlaneFrame],
    parts: tuple[str, ...],
    yields: tuple[int, ...] = (),
    onto_borders: bool = False,
    *,
    product: str,
) -> dict[str, str | None]:
    """Lay the parts the other sequence's slice of the same place names onto this series' slice,
    by the pair's one match (`matched`), onto this slice's own regions that nothing else holds but
    the parts in `yields`, and with `onto_borders` onto the places between its regions too, where
    its lens leaves a thin dark band out of every region: for each part, "laid_from_its_partner",
    why it was not laid, or None when nothing was laid. Once the places match, the region laid is
    read here: `<product>.region`, read by the partner."""
    record, arrays, frame = read
    partner_record, partner_arrays, partner_frame = partner
    source = matched(
        own.series,
        record,
        frame,
        arrays["acquired_plane"].shape,
        partner_record,
        partner_frame,
        partner_arrays["acquired_plane"],
    )
    if isinstance(source, str):
        return dict.fromkeys(parts, source)
    reads(product, ("region",), "partner")
    laid = laid_by(partner_arrays["a1_objects"], source)
    # a copy: a slice's objects may still be the names it made alone
    objects = arrays["a1_objects"].copy()
    open_to_them = np.isin(objects, (0, *yields))
    if not onto_borders:
        open_to_them &= arrays["b1_labels"] > 0
    codes: dict[str, str | None] = {}
    for part in parts:
        mask = partner_arrays.get(f"a2_{part}")
        if mask is not None:
            reads(part, ("region",), "partner")
            placed = (source >= 0) & laid_by(mask, source) & arrays["b1_available"]
            arrays[f"a2_{part}"] = placed
            codes[part] = "laid_from_its_partner" if placed.any() else None
            continue
        code = OBJECT_CODES[part]
        placed = (laid == code) & open_to_them
        objects[placed] = code
        codes[part] = "laid_from_its_partner" if placed.any() else None
    arrays["a1_objects"] = objects
    return codes


def find_part(
    measured: list[Measured],
    part: str,
    read_slice: Callable[
        [Measured], tuple[dict, dict[str, np.ndarray], PlaneFrame] | str
    ],
    laid_when: str | None,
) -> tuple[list[tuple[dict, dict[str, np.ndarray]]], dict[str, str]]:
    """A part named on its own slice in each series (`read_slice`: `acl_slice`, `lcl_slice`), and
    laid from the sequence that names it onto the other sequence's slice of the same place where
    that one abstains with `laid_when` (`lay_part`): the slices that name it, each record with its
    arrays, and every other series' silence, keyed `<series uid>:<part>`."""
    read: dict[int, tuple[dict, dict[str, np.ndarray], PlaneFrame]] = {}
    silences: dict[str, str] = {}
    companions = MAIN_COMPANIONS.get(part, ())
    for index, own in enumerate(measured):
        result = read_slice(own)
        if isinstance(result, str):
            for name in (part, *companions):
                silences[f"{own.record['series_uid']}:{name}"] = result
        else:
            read[index] = result
    found = []
    for index, (record, arrays, _) in read.items():
        own = measured[index]
        codes = record["assignments"]["codes"]
        if codes[part] == laid_when:
            partner = partner_of(measured, index)
            at = next((i for i, m in enumerate(measured) if m is partner), None)
            if at in read and read[at][0]["assignments"]["codes"][part] == "identified":
                laid = lay_parts(
                    own, read[index], read[at], (part, *companions), product=part
                )
                for name, code in laid.items():
                    codes[name] = code or codes[name]
        for name in companions:
            if codes[name] not in NAMED:
                # This tendon requires the semimembranosus; retain the upstream reason when
                # that reference fails. The two retinacula have independent decisions.
                silences[f"{record['series_uid']}:{name}"] = (
                    codes[part]
                    if part == "semimembranosus" and codes[part] not in NAMED
                    else codes[name]
                )
        if codes[part] in NAMED:
            handed(part, ("main_slice", "region"))
            found.append((record, arrays))
        else:
            silences[f"{own.record['series_uid']}:{part}"] = codes[part]
    return found, silences


def artifact_of(study_uid: str, record: dict) -> Path:
    """Where `save` puts one record's arrays, relative to its run: the study's folder and the series'
    uid, with the part's name when it is a main slice's. Known before the save, so an observation can
    name the artifact that will hold its places."""
    part = record.get("main_slice", {}).get("object")
    name = record["series_uid"] if part is None else f"{record['series_uid']}-{part}"
    return Path(study_uid) / f"{name}.npz"


def save(run_dir: Path, study_uid: str, record: dict, arrays: dict) -> dict:
    """Save one record's arrays in the run and note them, with their digests, on the record. A main
    slice's arrays are named for its part as well, since one series may hold several. Saving is not
    reading: what is kept here declares no read, so a value no stage reads stays on the list of
    what no stage reads (the module note, TELEMETRY)."""
    artifact = artifact_of(study_uid, record)
    np.savez_compressed(run_dir / artifact, allow_pickle=False, **arrays)
    record["study_uid"] = study_uid
    record["artifact"] = str(artifact)
    record["arrays"] = {name: {"digest": digest(a)} for name, a in arrays.items()}
    return record


def plain(value: object) -> object:
    """A NumPy number as the plain number JSON holds; anything else is refused by name."""
    if isinstance(value, np.generic):
        return value.item()
    raise TypeError(f"not_json_serializable: {type(value).__name__}")


def write_receipt(
    run_dir: Path,
    study_uid: str,
    series_uids: list[str],
    records: list[dict],
    unread: dict[str, str],
    telemetry: dict | None,
    objects: dict | None = None,
) -> None:
    """Merge one study into the run's receipt (`knee.receipt.merged_receipt`): its records,
    silences and telemetry replace what the receipt held for it, and every other study's stay."""
    path = run_dir / "receipt.json"
    old = json.loads(path.read_text()) if path.exists() else None
    receipt = merged_receipt(
        old, REQUEST, study_uid, series_uids, records, unread, telemetry, objects
    )
    path.write_text(json.dumps(receipt, indent=2, default=plain) + "\n")


def ledger_reading(events: Sequence[Event], totals: dict[str, int]) -> dict:
    """One study's telemetry: each event's name with how often it came and its summed counted
    work, the run's totals, every product produced and read by no stage, and, kind by kind, how
    many values were made once (`knee.telemetry.once`) and how often a made one was handed on."""
    by_name: dict[str, dict[str, int]] = {}
    computed: dict[str, dict[str, int]] = {}
    for event in events:
        entry = by_name.setdefault(event.name, {"times": 0})
        entry["times"] += 1
        for key, value in event.counts.items():
            entry[key] = entry.get(key, 0) + value
        for ending in ("made", "handed_on"):
            if event.name.endswith(f".{ending}"):
                kind = event.name[: -len(ending) - 1]
                tally = computed.setdefault(kind, {"made": 0, "handed_on": 0})
                tally[ending] += 1
    return {
        "events": by_name,
        "totals": totals,
        "read_by_no_stage": list(unread_products(event.name for event in events)),
        "computed_once": computed,
    }


def named_parts(records: list[dict], main_records: list[dict]) -> dict[str, int]:
    """How many of the study's series named each object, on its middle slice or on the object's own
    main slice."""
    named: dict[str, int] = {}
    for record in records + main_records:
        for name, code in record["assignments"]["codes"].items():
            if code in NAMED or code == "from_the_header":
                named[name] = named.get(name, 0) + 1
    return named


_PCL_LOCAL = {"partial_reading", "tied_largest_components", "measured_empty"}


def native_pcl_sources(
    measured: list[Measured],
    study_uid: str,
    *,
    orientation: str = "sagittal",
    pending: list[tuple[list[Observation], list[Unresolved]]] | None = None,
) -> dict[str, dict[str, Any]]:
    """Collect native sagittal label support or identified axial PCL evidence.

    Both orientations use the actual physical area of a saved, addressed support. The axial
    branch consumes only the aligned native resolved observations emitted by the axial PCL
    reader and validates their full-frame support address before opening the volume.
    """
    if orientation not in ("sagittal", "axial"):
        raise ValueError("unsupported_pcl_source_orientation")
    if orientation == "axial" and pending is None:
        return {
            "pcl": {
                "status": "unavailable",
                "selected": None,
                "entries": [],
                "point_count": 0,
                "largest_physical_area_mm2": None,
                "product": "native_axial_pcl_sources",
            }
        }
    if orientation == "axial":
        assert pending is not None
    axial_pending = pending if pending is not None else []
    if orientation == "axial" and len(axial_pending) != len(measured):
        raise ValueError("unaligned_axial_pcl_source_rows")

    label = OBJECT_CODES["pcl"]
    product = (
        "native_axial_pcl_sources" if orientation == "axial" else "native_pcl_sources"
    )
    entries: list[tuple[Measured, np.ndarray, dict[str, Any]]] = []
    aligned = (
        zip(measured, axial_pending, strict=True)
        if orientation == "axial"
        else ((own, None) for own in measured)
    )
    for own, result in aligned:
        record = own.record
        view = tuple(record.get("view", ()))
        expected_plane = orientation
        expected_sequence = ("1", "1") if orientation == "axial" else None
        if len(view) != 3 or view[0].casefold() != expected_plane:
            continue

        candidates: list[
            tuple[np.ndarray, np.ndarray, str, int, dict[str, Any] | None]
        ] = []
        if orientation == "sagittal":
            if (
                view[2] != "0"
                or getattr(own.series.row, "fat_suppression", None) != "0"
            ):
                continue
            objects = own.arrays.get("a1_objects")
            if (
                not isinstance(objects, np.ndarray)
                or objects.ndim != 2
                or objects.dtype.kind not in "iu"
            ):
                continue
            support = objects == label
            z_value = record.get("slice_index")
            if isinstance(z_value, bool) or z_value is None:
                continue
            z = int(z_value)
            support_name = "a1_objects"
            support_array = objects
            saved_rows = record.get("observations", ())
            candidates.append((support, support_array, support_name, z, None))
        else:
            if view[1:] != expected_sequence:
                continue
            if (
                getattr(own.series.row, "fluid_sensitive", None) != "1"
                or getattr(own.series.row, "fat_suppression", None) != "1"
            ):
                continue
            if result is None:
                continue
            observations, _ = result
            if not observations:
                continue
            reads("axial_pcl_said", ("observations",), product)
            saved_rows = observations
            artifact = str(artifact_of(study_uid, record))
            uid = str(record.get("series_uid", ""))
            for saved_row in saved_rows:
                fields = saved_row if isinstance(saved_row, dict) else asdict(saved_row)
                slices = tuple(fields.get("slices") or ())
                if (
                    fields.get("object") != "pcl"
                    or fields.get("provenance") != "native"
                    or fields.get("kind") != "resolved"
                    or fields.get("code") != "identified"
                    or fields.get("series_uid") != uid
                    or tuple(fields.get("view") or ()) != view
                    or fields.get("artifact") != artifact
                    or len(slices) != 1
                    or isinstance(slices[0], bool)
                    or fields.get("row") is not None
                    or fields.get("label") is not None
                ):
                    continue
                try:
                    candidate_z = int(slices[0])
                    candidate_count = int(fields.get("count", -1))
                except (TypeError, ValueError, OverflowError):
                    continue
                candidate_support = fields.get("support")
                candidate_array = (
                    own.arrays.get(candidate_support)
                    if isinstance(candidate_support, str)
                    else None
                )
                candidate_slices = (
                    own.arrays.get(f"{candidate_support}_slices")
                    if isinstance(candidate_support, str)
                    else None
                )
                if (
                    candidate_support != f"a4_axial_pcl_z{candidate_z}_support"
                    or not isinstance(candidate_array, np.ndarray)
                    or candidate_array.ndim != 2
                    or candidate_array.dtype.kind != "b"
                    or not isinstance(candidate_slices, np.ndarray)
                    or candidate_slices.shape != (1,)
                    or candidate_slices.dtype.kind not in "iu"
                    or int(candidate_slices[0]) != candidate_z
                    or candidate_count != int(candidate_array.sum())
                    or int(candidate_array.sum()) <= 0
                ):
                    continue
                candidates.append(
                    (
                        candidate_array,
                        candidate_array,
                        candidate_support,
                        candidate_z,
                        fields,
                    )
                )
            if not candidates:
                continue

        for support, support_array, support_name, z, fields_for_support in candidates:
            count = int(support.sum())
            if not count:
                continue
            uid = str(record.get("series_uid", ""))
            artifact = str(artifact_of(study_uid, record))
            if orientation == "sagittal":
                middle = z
                saved = False
                for row in saved_rows:
                    fields = row if isinstance(row, dict) else asdict(row)
                    saved = saved or (
                        fields.get("object") == "pcl"
                        and fields.get("provenance") == "native"
                        and fields.get("kind") == "resolved"
                        and fields.get("code") == "identified"
                        and fields.get("series_uid") == uid
                        and tuple(fields.get("view") or ()) == view
                        and tuple(fields.get("slices") or ()) == (middle,)
                        and fields.get("support") == "a1_objects"
                        and fields.get("artifact") == artifact
                        and fields.get("row") is None
                        and fields.get("label") == label
                        and fields.get("count") == count
                    )
                if not saved:
                    continue
            elif fields_for_support is None:
                continue
            else:
                reads("axial_pcl_said", ("support",), product)

            volume = own.series.volume
            if (
                volume is None
                or np.ndim(volume) != 3
                or not 0 <= z < len(volume)
                or support_array.shape != np.shape(volume[z])
            ):
                continue
            frame = plane_frame(own.series, z)
            if isinstance(frame, str):
                continue
            try:
                points = np.asarray(
                    frame.to_patient(np.argwhere(support).astype(np.float64)),
                    np.float64,
                )
                pixel_area = float(np.prod(frame.spacing_rc))
            except (AttributeError, TypeError, ValueError, np.linalg.LinAlgError):
                continue
            if (
                points.shape != (count, 3)
                or not np.isfinite(points).all()
                or not np.isfinite(pixel_area)
                or pixel_area <= 0
            ):
                continue
            meta = {
                "series_uid": uid,
                "view": list(view),
                "slice": z,
                "support": support_name,
                "row": None,
                "label": label if orientation == "sagittal" else None,
                "count": count,
                "pixel_area_mm2": pixel_area,
                "physical_area_mm2": count * pixel_area,
                "artifact": artifact,
                "provenance": "native",
                "code": "identified",
                "kind": "resolved",
            }
            if orientation == "sagittal":
                own.arrays["a4_pcl_source_lps"] = points
                record["a4_pcl_source"] = meta
            else:
                own.arrays[f"a4_axial_pcl_z{z}_source_lps"] = points
                record.setdefault("a4_axial_pcl_sources", []).append(meta)
            handed(product, ("points_lps", "metadata"))
            entries.append((own, points, meta))

    areas = [float(entry[2]["physical_area_mm2"]) for entry in entries]
    largest: float | None = max(areas, default=None)
    winners = [entry for entry in entries if entry[2]["physical_area_mm2"] == largest]
    return {
        "pcl": {
            "status": "selected"
            if len(winners) == 1
            else "tied"
            if winners
            else "unavailable",
            "selected": None
            if len(winners) != 1
            else {
                "owner": winners[0][0],
                "points_lps": winners[0][1],
                "metadata": winners[0][2],
            },
            "entries": [entry[2] for entry in entries],
            "point_count": sum(len(entry[1]) for entry in entries),
            "largest_physical_area_mm2": largest,
            "product": product,
        }
    }


def _peak_slices(values: np.ndarray) -> list[int]:
    finite = np.isfinite(values)
    if not finite.any() or float(np.max(values[finite])) <= 0.0:
        return []
    return [int(z) for z in np.flatnonzero(finite & (values == np.max(values[finite])))]


def name_native_pcl_sections(
    measured: list[Measured],
    sources: dict[str, dict[str, Any]],
    study_uid: str,
    mapping: MapContext | None,
    *,
    orientation: str = "axial",
    other_sources: dict[str, dict[str, Any]] | None = None,
) -> list[tuple[list[Observation], list[Unresolved]]]:
    """Measure local PCL sections from native source half-slab profiles.

    Axial remains the original one-source path. Coronal candidates must reach both the selected
    sagittal and selected axial source locations through the same local component measurement.
    """
    if orientation not in ("axial", "coronal"):
        raise ValueError("unsupported_pcl_target_orientation")
    name = "pcl"
    source = sources["pcl"]
    other_source = (other_sources or {}).get("pcl", {})
    product = "axial_pcl_said" if orientation == "axial" else "coronal_pcl_said"
    candidate_field = (
        "a4_axial_native_pcl_candidates"
        if orientation == "axial"
        else "a4_coronal_native_pcl_candidates"
    )
    aligned: list[tuple[list[Observation], list[Unresolved]]] = []

    for own in measured:
        here: list[Observation] = []
        missing: list[Unresolved] = []
        aligned.append((here, missing))
        record, series = own.record, own.series
        uid, view = str(record["series_uid"]), tuple(record["view"])
        if len(view) != 3 or view[0].casefold() != orientation:
            continue
        if view[1:] != ("1", "1"):
            missing.append(
                Unresolved(name, "native", uid, view, "unsupported_target_sequence")
            )
            continue
        if source.get("status") != "selected":
            code = (
                "source_tied"
                if source.get("status") == "tied"
                else "source_unavailable"
            )
            missing.append(Unresolved(name, "native", uid, view, code))
            continue
        if orientation == "coronal" and other_source.get("status") != "selected":
            code = (
                "other_source_tied"
                if other_source.get("status") == "tied"
                else "other_source_unavailable"
            )
            missing.append(Unresolved(name, "native", uid, view, code))
            continue

        volume = series.volume
        if volume is None or np.ndim(volume) != 3:
            missing.append(
                Unresolved(name, "native", uid, view, "native_volume_unavailable")
            )
            continue

        if orientation == "axial":
            profiles = native_meniscus_profiles(
                own,
                sources,
                mapping,
                orientation="axial",
                names=(name,),
                profile_product="native_axial_pcl_profiles",
                sources_product="native_pcl_sources",
            )
            profile = (profiles or {}).get(name, {})
            other_profile = None
            primary_product = "native_axial_pcl_profiles"
            secondary_product = None
        else:
            profiles = native_meniscus_profiles(
                own,
                sources,
                mapping,
                orientation="coronal",
                source_tag="sagittal",
                names=(name,),
                profile_product="native_coronal_pcl_sagittal_profiles",
                sources_product="native_pcl_sources",
            )
            other_profiles = native_meniscus_profiles(
                own,
                other_sources or {},
                None,
                orientation="coronal",
                source_tag="axial",
                names=(name,),
                profile_product="native_coronal_pcl_axial_profiles",
                sources_product="native_axial_pcl_sources",
            )
            profile = (profiles or {}).get(name, {})
            other_profile = (other_profiles or {}).get(name, {})
            primary_product = "native_coronal_pcl_sagittal_profiles"
            secondary_product = "native_coronal_pcl_axial_profiles"

        if profile.get("status") != "measured":
            missing.append(
                Unresolved(name, "native", uid, view, "source_profile_unavailable")
            )
            continue
        if other_profile is not None and other_profile.get("status") != "measured":
            missing.append(
                Unresolved(
                    name, "native", uid, view, "other_source_profile_unavailable"
                )
            )
            continue

        primary_reads = (
            "counts",
            "unique_counts",
            "map_counts",
            "statuses",
            "guide",
            "unique_rc",
        )
        reads(primary_product, primary_reads, product)
        if secondary_product is None:
            reads("native_pcl_sources", ("metadata",), product)
        else:
            reads("native_pcl_sources", ("metadata",), product)
            reads("native_axial_pcl_sources", ("metadata",), product)
            reads(
                secondary_product,
                ("counts", "unique_counts", "statuses", "unique_rc"),
                product,
            )

        meta = source["selected"]["metadata"]
        other_meta = (
            other_source["selected"]["metadata"] if orientation == "coronal" else None
        )
        guide = profile.get("guide")
        guided = (
            _peak_slices(profile["map_counts"])
            if guide is not None and guide.status == "guided"
            else []
        )
        peaks = sorted(
            set(_peak_slices(profile["counts"]))
            | set(_peak_slices(profile["unique_counts"]))
        )
        if other_profile is not None:
            peaks = sorted(
                set(peaks)
                | set(_peak_slices(other_profile["counts"]))
                | set(_peak_slices(other_profile["unique_counts"]))
            )
        order = list(dict.fromkeys(guided + peaks))
        profile_field = (
            "a4_axial_pcl_profile"
            if orientation == "axial"
            else "a4_coronal_pcl_profile"
        )
        refusal_field = (
            "a4_axial_pcl_profile_refusals"
            if orientation == "axial"
            else "a4_coronal_pcl_profile_refusals"
        )
        record[profile_field] = {
            "guide_status": None if guide is None else guide.status,
            "map_guided_first": guided,
            "source_profile_maxima": peaks,
        }
        record[refusal_field] = [
            {"slice": int(z), "status": int(status)}
            for z, status in enumerate(profile["statuses"])
            if int(status) not in (3, 4)
        ]
        if other_profile is not None:
            record[refusal_field].extend(
                {"slice": int(z), "status": int(status), "source": "axial"}
                for z, status in enumerate(other_profile["statuses"])
                if int(status) not in (3, 4)
            )
        if not order:
            missing.append(
                Unresolved(name, "native", uid, view, "no_positive_candidate_profile")
            )
            continue

        span_mm = anatomy_map.target_span_mm(
            name, mapping.smap.scale.mm if mapping is not None else None
        )
        artifact = str(artifact_of(study_uid, record))
        codes: list[str] = []
        for z in order:
            part = profile["per_slice"].get(z)
            other_part = (
                other_profile["per_slice"].get(z) if other_profile is not None else None
            )
            candidate: dict[str, Any] = {
                "slice": int(z),
                "source": meta,
            }
            if other_meta is not None:
                candidate["other_source"] = other_meta
            record.setdefault(candidate_field, []).append(candidate)

            if part is None or len(part["unique_rc"]) == 0:
                code = "source_not_in_slab"
            elif other_profile is not None and (
                other_part is None or len(other_part["unique_rc"]) == 0
            ):
                code = "other_source_not_in_slab"
            else:
                code = ""
            frame = plane_frame(series, z)
            if not code and not isinstance(frame, PlaneFrame):
                code = "geometry_unreadable"
            if not code and span_mm is None:
                code = "anatomical_extent_unavailable"
            if code:
                candidate["status"] = code
                codes.append(code)
                if orientation == "coronal":
                    missing.append(
                        Unresolved(
                            name,
                            "native",
                            uid,
                            view,
                            "local_body_unavailable:" + code,
                        )
                    )
                continue

            assert isinstance(frame, PlaneFrame)
            assert span_mm is not None
            primary_rc = part["unique_rc"].astype(np.float64)
            secondary_rc = (
                other_part["unique_rc"].astype(np.float64)
                if other_part is not None
                else np.empty((0, 2), dtype=np.float64)
            )
            source_rc = (
                np.concatenate((primary_rc, secondary_rc), axis=0)
                if len(secondary_rc)
                else primary_rc
            )
            full_span_mm: tuple[float, float, float] = (
                2.0 * float(span_mm[0]),
                2.0 * float(span_mm[1]),
                2.0 * float(span_mm[2]),
            )
            window = source_window(
                source_rc,
                full_span_mm,
                frame,
                tuple(np.shape(volume[z])),
            )
            candidate["window"] = window
            if window.get("status") not in {"present", "window_clipped_to_image"}:
                code = "source_window_" + str(window.get("status", "unavailable"))
                candidate["status"] = code
                codes.append(code)
                continue
            r0, r1, c0, c1 = window["window_rc_exclusive"]
            full = np.asarray(volume[z])
            raw = full[r0:r1, c0:c1]
            available = np.asarray(
                (finite_of(series)[z] & ~margin_of(uid, z, full))[r0:r1, c0:c1],
                dtype=bool,
            ) & np.isfinite(raw)

            def target_crop(
                points: np.ndarray,
                raw_shape: tuple[int, ...] = raw.shape,
                row0: int = r0,
                col0: int = c0,
            ) -> np.ndarray:
                target = np.zeros(raw_shape, dtype=bool)
                local = np.rint(points).astype(int) - np.asarray([row0, col0])
                inside = (
                    (local[:, 0] >= 0)
                    & (local[:, 0] < raw_shape[0])
                    & (local[:, 1] >= 0)
                    & (local[:, 1] < raw_shape[1])
                )
                target[local[inside, 0], local[inside, 1]] = True
                return target

            target = target_crop(primary_rc)
            other_target = (
                target_crop(secondary_rc) if other_profile is not None else None
            )
            if not target.any():
                code = "source_target_outside_window"
            elif other_target is not None and not other_target.any():
                code = "other_source_target_outside_window"
            else:
                code = ""
            if code:
                candidate["status"] = code
                codes.append(code)
                continue

            def select(
                raw=raw,
                available=available,
                target=target,
                other_target=other_target,
                frame=frame,
                orientation=orientation,
            ):
                ledger.record(
                    "native_pcl.window_pixels", pixels=int(raw.size), frames=1
                )
                if orientation == "coronal":
                    return enclosed_body_at_sources(
                        raw,
                        available,
                        target,
                        frame,
                        thickness_mm=LIGAMENT_THICK_MM,
                        other_target=other_target,
                    )
                return enclosed_body_at_sources(
                    raw,
                    available,
                    target,
                    frame,
                    thickness_mm=LIGAMENT_THICK_MM,
                )

            cache_name = (
                "native_pcl_local_body"
                if orientation == "axial"
                else "native_pcl_coronal_local_body"
            )
            cache_key = (
                uid,
                int(z),
                tuple(window["window_rc_exclusive"]),
                tuple(primary_rc.reshape(-1)),
                *((tuple(secondary_rc.reshape(-1)),) if len(secondary_rc) else ()),
                float(LIGAMENT_THICK_MM),
                float(SHELL_MM),
                tuple(float(value) for value in frame.spacing_rc),
            )
            result = once(cache_name, cache_key, select)
            code = str(result.get("status", "selector_status_missing"))
            selection = result.get("selection_status")
            codes.append(code)
            prefix = f"a4_{orientation}_pcl_z{int(z)}"
            own.arrays[f"{prefix}_raw_crop"] = raw
            own.arrays[f"{prefix}_available_crop"] = available
            own.arrays[f"{prefix}_target_crop"] = target
            if other_target is not None:
                own.arrays[f"{prefix}_other_target_crop"] = other_target
            for key, value in result.items():
                if isinstance(value, np.ndarray):
                    own.arrays[f"{prefix}_{key}"] = value
            candidate.update(
                status=code,
                selection_status=selection,
                target_pixel_count=int(target.sum()),
                result_fields={
                    key: value
                    for key, value in result.items()
                    if not isinstance(value, np.ndarray)
                },
            )
            if other_target is not None:
                candidate["other_target_pixel_count"] = int(other_target.sum())
            selected = result.get("selected")
            if not isinstance(selected, np.ndarray) or selected.shape != raw.shape:
                selected = np.zeros(raw.shape, dtype=bool)
            support = f"{prefix}_support"
            if selected.any() or code == "measured_empty":
                supported = np.zeros(tuple(np.shape(volume[z])), dtype=bool)
                supported[r0:r1, c0:c1] = selected
                own.arrays[support] = supported
                own.arrays[f"{support}_slices"] = np.asarray([z], dtype=np.int32)
            if (
                code in {"identified", "partial_reading"}
                and selection == "identified"
                and selected.any()
            ):
                here.append(
                    observe(
                        name,
                        "native",
                        "resolved",
                        own,
                        (int(z),),
                        "identified",
                        int(selected.sum()),
                        0.0,
                        support,
                        "identified local PCL body reaches both native source regions"
                        if orientation == "coronal"
                        else "identified body on available samples in the bounded native window; "
                        "window completeness is retained separately in the crop measurements; "
                        "a local cross-section, not the full course",
                        artifact,
                    )
                )
                continue
            if selected.any() or code == "measured_empty":
                here.append(
                    observe(
                        name,
                        "native",
                        "reading",
                        own,
                        (int(z),),
                        code,
                        int(selected.sum()),
                        0.0,
                        support,
                        "local reading retained without a native resolution",
                        artifact,
                    )
                )
            missing.append(
                Unresolved(
                    name,
                    "native",
                    uid,
                    view,
                    ("local_body_" if code in _PCL_LOCAL else "local_body_unavailable:")
                    + code,
                )
            )
        if not here and not missing:
            missing.append(
                Unresolved(
                    name,
                    "native",
                    uid,
                    view,
                    "candidate_readings_unresolved:" + "|".join(codes),
                )
            )

    if any(rows or gaps for rows, gaps in aligned):
        handed(product, ("observations", "unresolved"))
        if orientation == "axial" and any(
            any(
                key.startswith("a4_axial_pcl_z") and key.endswith("_support")
                for key in own.arrays
            )
            for own in measured
        ):
            handed(product, ("support",))
    return aligned


def measure_study(
    corpus: Corpus, study_uid: str, run_dir: Path, main_run: Path, drawn: bool
) -> dict:
    """Measure every series of one study with the ledger on and save its arrays; return what the
    receipts take (its records, silences and telemetry) and what it named. Writes no receipt, so
    studies can be measured side by side. `drawn` says whether its pictures will be drawn, since
    only then do the renderers read what they read. Within the study a value two stages need is
    made once and handed on (`knee.telemetry.once`), and released when the study is done."""
    (run_dir / study_uid).mkdir(parents=True, exist_ok=True)
    (main_run / study_uid).mkdir(parents=True, exist_ok=True)
    with recording() as led, computing():
        study = read_study(corpus, study_uid)
        ledger.record(
            "study.produced",
            series=len(study.series),
            slices=sum(len(series.slices) for series in study.series),
        )
        records, unread = [], {}
        main_records, main_unread = [], {}
        measured: list[Measured] = []
        for series in study.series:
            handed("series", field_names(series))
            reading = measure(series, drawn)
            if isinstance(reading, str):
                unread[series.row.series_uid] = reading
            else:
                measured.append(reading)
        # Each middle slice is read with its partner's, the other sequence's slice of the same
        # place, on the names each made alone (`Measured.assignment`, which this never changes);
        # then saved.
        partners = [partner_of(measured, index) for index in range(len(measured))]
        for own, partner in zip(measured, partners, strict=True):
            own.record["assignments"]["partner"] = (
                "none_of_the_other_sequence"
                if partner is None
                else read_with_partner(own, partner)
            )
        # The extensor tendons, on the sagittal slice without fat suppression, from the bands its
        # PCL was read from and the patella its partner laid on; then laid onto that partner. Then
        # the rest of the field on each slice without fat suppression: the fat under the skin where
        # its partner laid the skin on, and muscle, outside every part named and the white its
        # partner sees as fluid where that partner is fat-suppressed and fluid-sensitive; each laid
        # onto that partner.
        for own, partner in zip(measured, partners, strict=True):
            name_the_extensor_tendons(own, partner)
        for own, partner in zip(measured, partners, strict=True):
            name_the_rest_of_the_field(own, partner)
        # Fat-suppressed sources locate the recess and its lining; transfer after each
        # target has its own abstention, so a later target cannot overwrite a transferred mask.
        for own, partner in sorted(
            zip(measured, partners, strict=True),
            key=lambda pair: int(pair[0].series.row.fat_suppression),
        ):
            name_joint_boundaries(own, partner)
            name_suprapatellar_pads(own, partner)
        # Initialize FS refusals before a non-FS source lays its separate ITB mask onto them.
        for own, partner in sorted(
            zip(measured, partners, strict=True),
            key=lambda pair: int(pair[0].series.row.fat_suppression),
            reverse=True,
        ):
            name_iliotibial_band(own, partner)
        # The back of the knee, on the series the leg runs through: the study's leg, its bones in
        # the scanner's millimetres, made once where the header names the knee there, and carried
        # onto the slices its parts are named on; both heads on the middle slice, from the
        # lens already read there, before the records are saved, so it is saved and drawn.
        leg = None
        reads("naming", ("in_plane",), "leg")
        if any(
            not own.assignment.in_plane[2]
            and own.record["assignments"]["knee"] in ("R", "L")
            for own in measured
        ):
            leg = leg_of(measured)
        patella_centre = None
        if leg is not None and len(leg.patella_lps):
            reads("leg", ("patella_lps",), "patella_centre")
            patella_centre = leg.patella_lps.mean(axis=0)
            handed("patella", ("centre_lps",))
        for own in measured:
            own.record["assignments"]["codes"].update(
                name_the_back_of_the_knee(own, leg)
            )
        # The semimembranosus group (the tendon, the semitendinosus and the gracilis) is resolved
        # once here, ahead of the middle slices' save below, since the sartorius on a middle axial
        # reads the gracilis's physical places from it: its records are saved and its silences
        # kept exactly as the later main parts' are, and it is not read again after them.
        found, silences = find_part(
            measured,
            "semimembranosus",
            lambda own: semimembranosus_slice(own, leg),
            "abstain_no_tendon_at_the_back_inner_corner",
        )
        # kept in order but written once, after the posterior family has added what it keeps in
        # their arrays (`index_posterior`)
        group_found = found
        for part_record, _ in group_found:
            main_records.append(part_record)
        main_unread.update(silences)
        source = gracilis_source(measured, found)
        for own in measured:
            name_sartorius(own, source)
        # The one physical map below supplies every production search guide. The withdrawn
        # single-bone/cohort reference is not computed: no map-guided consumer reads it.
        carried = leg if leg is not None else leg_of(measured)
        reference = "legacy_single_bone_reference_not_used_by_the_physical_map"
        # The femur and the tibia through the stacks, pointed planes only, kept in the middle records.
        name_the_bones(measured, partners, carried, study_uid)
        # The bones' later native sections, published once (`refine_leg`) as location priors for the
        # coarse readers that follow: the bones' own axial key planes (inside the map below), the
        # native fat and cartilage contexts and the fibula's axial key plane. The readers before the
        # bones keep the early leg, since no refined leg exists for them, and so does every other
        # reader after them (the patella, joint, recess, posterior and retinacula readers).
        refined = refine_leg(carried, measured)
        # THE STUDY MAP, before any other family searches: the bones' selected planes (sagittal and
        # coronal from their own cheap profiles, axial from the scale-filtered section estimate of
        # the enclosed bodies, seeded by the refined leg's places) make each bone's position; every
        # object has a record, every ordered pair a vector or a named unresolved end; the
        # anatomical reference's ideal gives each complete anchor's expectation of every other
        # object, which the families below read where to look first (and fall back from).
        mapping = build_study_map(measured, refined, anatomical_reference())
        # The patella through the stacks, searched first where the reference says it lies, with
        # the extensor tendons and the fat pads on the planes it names, kept beside the bones'
        # records and observations.
        name_the_patella(measured, partners, carried, study_uid, reference, mapping)
        patella_key_planes(measured, mapping, study_uid)
        refine_map(mapping, measured)

        # Completed native families become guidance before the next family asks for a map guide.
        # Keep these returned rows pending for their original append point below. The later
        # combined offer is an idempotent closure over the same evidence.
        pending_map_families: list[tuple[str, list[dict]]] = []

        def offer_completed_family(
            family: str, said: list[tuple[list[Observation], list[Unresolved]]]
        ) -> None:
            product, map_rows, _ = offer_native_family(mapping, measured, family, said)
            if map_rows:
                pending_map_families.append((product, map_rows))

        # The joint (the sided menisci, the cartilage, the cruciates and the MCL) through the
        # stacks, from the bones' carried places, searched for each question the view admits
        # (where the reference's measured range points first, where one is supported), kept
        # beside the bones' and the patella's records.
        name_the_joint(measured, partners, leg, study_uid, reference, mapping)
        pcl_sources = native_pcl_sources(measured, study_uid)
        cartilage_companions = [
            (
                sagittal_cartilage_observations(
                    {
                        **own.record,
                        "artifact": str(artifact_of(study_uid, own.record)),
                    }
                ),
                [],
            )
            for own in measured
        ]
        cartilage_sources = native_femoral_cartilage_sources(
            measured, cartilage_companions, study_uid
        )
        offer_completed_family("cartilage_companions", cartilage_companions)
        meniscus_sources = native_meniscus_sources(measured, study_uid)
        refine_map(mapping, measured)
        # The recesses, their lining and fluid, the side recesses' capsule and the retinacula through
        # the stacks, from the compartments those families located, kept beside their records.
        recess_said = name_the_recess(
            measured, partners, leg, patella_centre, study_uid, mapping
        )
        offer_completed_family("recess_said", recess_said)
        native_fat_sources = native_fat_pad_sources(measured, study_uid)
        native_fat_candidates: list[dict[str, list[dict[str, Any]]]] = []
        for own in measured:
            candidates = native_fat_pad_candidates(
                own, native_fat_sources, mapping, refined
            )
            native_fat_candidates.append(candidates)
        needs_opposed_calibration = any(
            any(rows for rows in candidates.values())
            for candidates in native_fat_candidates
        )
        native_fat_calibrations = (
            native_fat_opposed_calibrations(measured)
            if needs_opposed_calibration
            else {}
        )
        for own, candidates in zip(measured, native_fat_candidates, strict=True):
            native_fat_opposed_samples(
                own, candidates, native_fat_calibrations, measured
            )
        native_fat_said = [
            native_fat_pad_observations(own, native_fat_sources, candidates, study_uid)
            for own, candidates in zip(measured, native_fat_candidates, strict=True)
        ]
        offer_completed_family("native_fat_said", native_fat_said)
        coronal_anterior_said = name_coronal_anterior_recess(
            measured, recess_said, study_uid, mapping
        )
        offer_completed_family("coronal_anterior_said", coronal_anterior_said)
        sagittal_capsule_said = name_sagittal_capsule(
            measured, recess_said, study_uid, mapping
        )
        offer_completed_family("sagittal_capsule_said", sagittal_capsule_said)
        # The same native outer walls also describe capsule beside the recess.
        # Keep their addresses; no second mask or image measurement is made.
        capsule_said = [
            axial_capsule_observations(here, missing) for here, missing in recess_said
        ]
        lining_said = [
            cavity_lining_observations(
                [*here, *recess_here],
                [
                    *missing,
                    *(
                        reason
                        for reason in recess_missing
                        if reason.object == "joint_capsule"
                        and reason.provenance == "native"
                        and reason.view is not None
                        and reason.view[0].casefold() == "coronal"
                    ),
                ],
                own.arrays,
            )
            for own, (here, missing), (recess_here, recess_missing) in zip(
                measured, capsule_said, recess_said, strict=True
            )
        ]
        offer_completed_family("capsule_said", capsule_said)
        offer_completed_family("lining_said", lining_said)
        recess_fluid_said = [
            axial_joint_fluid(
                own, own.record, own.arrays, study_uid, mapping, pointed=True
            )
            for own in measured
        ]
        anterior_axial_said = [
            anterior_recess_from_axial_pockets(here, missing)
            for here, missing in recess_fluid_said
        ]
        offer_completed_family("recess_fluid_said", recess_fluid_said)
        offer_completed_family("anterior_axial_said", anterior_axial_said)
        axial_joint_said = name_axial_joint_compartment(measured, study_uid, mapping)
        offer_completed_family("axial_joint_said", axial_joint_said)
        axial_extensor_said = name_axial_extensor_sections(measured, study_uid, mapping)
        offer_completed_family("axial_extensor_said", axial_extensor_said)
        coronal_extensor_said = name_coronal_extensor_sections(
            measured, axial_extensor_said, study_uid, mapping
        )
        offer_completed_family("coronal_extensor_said", coronal_extensor_said)
        axial_femoral_cartilage_said = name_femoral_cartilage(
            measured, cartilage_sources, study_uid, mapping, refined
        )
        offer_completed_family(
            "axial_femoral_cartilage_said", axial_femoral_cartilage_said
        )
        sagittal_menisci_said = name_native_menisci(
            measured, meniscus_sources, study_uid, mapping
        )
        offer_completed_family("sagittal_menisci_said", sagittal_menisci_said)
        sagittal_meniscus_sources = native_meniscus_sources(
            measured,
            study_uid,
            orientation="sagittal",
            pending=sagittal_menisci_said,
        )
        axial_menisci_said = name_native_menisci(
            measured,
            meniscus_sources,
            study_uid,
            mapping,
            orientation="axial",
            other_sources=sagittal_meniscus_sources,
        )
        # The axial menisci are the last family before the posterior searches.
        offer_completed_family("axial_menisci_said", axial_menisci_said)
        axial_pcl_said = name_native_pcl_sections(
            measured, pcl_sources, study_uid, mapping, orientation="axial"
        )
        offer_completed_family("axial_pcl_said", axial_pcl_said)
        axial_pcl_sources = native_pcl_sources(
            measured, study_uid, orientation="axial", pending=axial_pcl_said
        )
        coronal_pcl_said = name_native_pcl_sections(
            measured,
            pcl_sources,
            study_uid,
            mapping,
            orientation="coronal",
            other_sources=axial_pcl_sources,
        )
        offer_completed_family("coronal_pcl_said", coronal_pcl_said)
        # Re-offer the saved map rows as one idempotent closure before the next search.
        for product, _ in pending_map_families:
            reads(product, ("observations",), "refine_map")
        refine_map(
            mapping,
            measured,
            [rows for _, family_rows in pending_map_families for rows in family_rows],
        )
        # The posterior family: what the views say of the heads, the lumens, the sartorius and the
        # semimembranosus group with the bursa, and each tube's continuation along the leg; then
        # the group's records are written once, with the arrays that continuation added.
        index_posterior(measured, EARLY_MIDDLE_PARTS, group_found, study_uid, leg, True)
        for part_record, part_arrays in group_found:
            save(main_run, study_uid, part_record, part_arrays)
        # The fibula, found on its main slice from the profile's pointed planes.
        found_fibulas: list[tuple[Measured, FibulaFound]] = []
        for own in measured:
            fibula = find_fibula(own.series, own.record, own.arrays, own.stack, mapping)
            # Retain the live record here; all anatomical families finish before its one write.
            records.append(own.record)
            if isinstance(fibula, str):
                main_unread[f"{own.record['series_uid']}:fibula"] = fibula
            else:
                # written once, whole, after its twin, axial and consumer fields are complete;
                # the artifact is known before the write, so observations can name it
                fibula.record["artifact"] = str(artifact_of(study_uid, fibula.record))
                main_records.append(fibula.record)
                found_fibulas.append((own, fibula))
        # It is one leg: the fibula found in one sequence is laid onto the same place of the other,
        # and every view's saying of it is kept by where it comes from. Then the fibula, one value,
        # is handed to the LCL and the biceps femoris tendon: the first series, in the study's
        # order, to name it where its front edge can be read.
        # The axial image supplies its own key plane. Native fibula sections only point
        # where to read; the shared coarse bone enclosure decides the supported section, and the
        # refined leg's tibia marks the blocks it must not be attributed to.
        # Its evidence lives in a fibula main record, still unsaved at this point.
        fibula_key_planes(measured, mapping, found_fibulas, refined, study_uid)
        shared_fibulas: list[FibulaFound] = []
        for own, fibula in found_fibulas:
            partner = partner_of(
                measured, next(i for i, m in enumerate(measured) if m is own)
            )
            twin = None if partner is None else fibula_twin(own, partner, fibula)
            if isinstance(twin, tuple) and partner is not None:
                twin_record, twin_arrays, twin_index, twin_light, _ = twin
                main_records.append(save(main_run, study_uid, twin_record, twin_arrays))
                main_unread.pop(f"{partner.record['series_uid']}:fibula", None)
                fibula = replace(
                    fibula,
                    twin_uid=partner.record["series_uid"],
                    twin_index=twin_index,
                    twin_light=twin_light,
                )
                handed("fibula", ("twin_light",))
            elif isinstance(twin, str):
                fibula.record["main_slice"]["transfer"] = twin
            seen, unplaced = fibula_observations(own, fibula, partner, twin, measured)
            keep_on_record(fibula.record, seen, unplaced)
            save(main_run, study_uid, fibula.record, fibula.arrays)
            shared_fibulas.append(fibula)
        shared = next((f for f in shared_fibulas if f.places is not None), None)
        fibula_lps = None if shared is None else shared.places
        existing: dict[str, list[tuple[dict, dict[str, np.ndarray]]]] = {}
        for part, read_slice, laid_when in (
            ("acl", acl_slice, "abstain_not_walled_off_without_fat_suppression"),
            (
                "lcl",
                lambda own: lcl_slice(own, fibula_lps),
                "abstain_not_parted_from_the_fat_with_fat_suppression",
            ),
            (
                "patellar_retinacula",
                lambda own: retinacula_slice(
                    own, leg, retinacula_centre(measured, patella_centre)
                ),
                None,
            ),
            (
                BICEPS,
                lambda own: biceps_femoris_slice(own, measured, fibula_lps, shared),
                BICEPS_LAID_WHEN,
            ),
        ):
            found, silences = find_part(measured, part, read_slice, laid_when)
            existing[part] = found
            for part_record, part_arrays in found:
                if part == "patellar_retinacula":
                    fluid_source = next(
                        own
                        for own in measured
                        if own.record["series_uid"] == part_record["series_uid"]
                    )
                    fluid_here, fluid_missing = axial_joint_fluid(
                        fluid_source,
                        part_record,
                        part_arrays,
                        study_uid,
                        mapping,
                        pointed=False,
                    )
                    keep_on_record(part_record, fluid_here, fluid_missing)
                    anterior_here, anterior_missing = (
                        anterior_recess_from_axial_pockets(fluid_here, fluid_missing)
                    )
                    keep_on_record(part_record, anterior_here, anterior_missing)
                main_records.append(save(main_run, study_uid, part_record, part_arrays))
            main_unread.update(silences)
        # The ACL's and the LCL's own slices stay observations beside the joint's pointed planes.
        joint_existing(
            measured,
            {part: existing[part] for part in ("acl", "lcl") if part in existing},
            study_uid,
        )
        # The recess family's observations follow every earlier family's, then the retinacula's own
        # slice, which stays an observation beside the recess family's planes.
        keep_recess(measured, recess_said)
        keep_recess(measured, recess_fluid_said)
        existing_boundary_said = recess_existing(
            measured, existing.get("patellar_retinacula", []), study_uid
        )
        # The lateral parts found after the middle records were written (the iliotibial band, the
        # popliteus tendon, the biceps femoris tendon), and every refusal of the posterior family.
        index_posterior(
            measured,
            (*LATE_MIDDLE_PARTS, *CONTEXT_MIDDLE_PARTS),
            [*existing.get("lcl", []), *existing.get(BICEPS, [])],
            study_uid,
            leg,
            False,
        )
        posterior_silences(measured, main_unread)
        # Append new capsule descriptions after the earlier families' observations.
        keep_recess(measured, capsule_said)
        if existing_boundary_said is not None:
            keep_recess(measured, existing_boundary_said[0])
        # The new lining rows follow the complete earlier capsule observation prefix.
        keep_recess(measured, lining_said)
        if existing_boundary_said is not None:
            keep_recess(measured, existing_boundary_said[1])
        # The axial cavity descriptions follow all previously emitted observations.
        keep_recess(measured, anterior_axial_said)
        keep_recess(measured, coronal_anterior_said)
        keep_recess(measured, sagittal_capsule_said)
        keep_recess(measured, axial_joint_said)
        keep_recess(measured, axial_extensor_said)
        keep_recess(measured, coronal_extensor_said)
        retinacular_cross_said = name_cross_view_retinacula(
            measured,
            recess_said,
            existing.get("patellar_retinacula", []),
            study_uid,
            mapping,
        )
        keep_recess(measured, retinacular_cross_said)
        # Existing sagittal bone-facing cartilage supplies native descriptions;
        # append addressed companions after every earlier observation, without a new mask.
        keep_recess(
            measured,
            cartilage_companions,
        )
        keep_recess(measured, native_fat_said)
        keep_recess(measured, axial_femoral_cartilage_said)
        if any(rows or missing for rows, missing in sagittal_menisci_said):
            reads(
                "sagittal_menisci_said",
                ("observations", "unresolved"),
                "keep_recess",
            )
        keep_recess(measured, sagittal_menisci_said)
        if any(rows or missing for rows, missing in axial_menisci_said):
            reads(
                "axial_menisci_said",
                ("observations", "unresolved"),
                "keep_recess",
            )
        keep_recess(measured, axial_menisci_said)
        if any(rows or missing for rows, missing in axial_pcl_said):
            reads("axial_pcl_said", ("observations", "unresolved"), "keep_recess")
        keep_recess(measured, axial_pcl_said)
        if any(rows or missing for rows, missing in coronal_pcl_said):
            reads("coronal_pcl_said", ("observations", "unresolved"), "keep_recess")
        keep_recess(measured, coronal_pcl_said)
        # Write each middle artifact once, after every family has supplied its evidence.
        # Native main-slice results can now feed later middle-record descriptions in memory.
        for own in measured:
            save(run_dir, study_uid, own.record, own.arrays)
        # every family's resolved sections have entered the map: its last version, whole
        refine_map(mapping, measured, main_records)
        study_map = finish_map(mapping, run_dir, study_uid)
        if records:
            records[0]["study_map"] = study_map
        # The renderers read the saved run, when they draw it: their reads are its last.
        if drawn and records:
            reads("interiors", DRAWN_INTERIORS, "draw")
            reads("naming", DRAWN_NAMES, "draw")
            # what a slice read with its partner keeps, in place of its own objects and codes
            reads("partner", ("objects", "codes"), "draw")
            # the back of the knee's part, which a middle slice the leg runs through names
            if any(
                r["assignments"]["codes"].get(name) == "identified"
                for r in records
                for name in ("medial_gastrocnemius", "lateral_gastrocnemius")
            ):
                reads("gastrocnemius", ("region",), "draw")
            # the lumens between the heads, which that slice names
            if any(
                r["assignments"]["codes"].get(name) == "identified"
                for r in records
                for name in ("popliteal_artery", "popliteal_vein")
            ):
                reads("popliteal_lumens", ("artery", "vein"), "draw")
            # the joint's boundaries, each where a slice names it
            boundaries = tuple(
                field
                for field, name in JOINT_BOUNDARIES
                if any(r["assignments"]["codes"].get(name) in NAMED for r in records)
            )
            if boundaries:
                reads("joint_boundaries", boundaries, "draw")
            if any(
                r["assignments"]["codes"].get("quadriceps_fat_pad") in NAMED
                for r in records
            ):
                reads(
                    "suprapatellar_pads",
                    (
                        "quadriceps_fat_pad",
                        "prefemoral_fat_pad",
                        "suprapatellar_recess_ridge",
                    ),
                    "draw",
                )
            if any(
                r["assignments"]["codes"].get("iliotibial_band") in NAMED
                for r in records
            ):
                reads("iliotibial_band", ("region",), "draw")
            # the sartorius, which a middle axial names from the gracilis's places
            if any(
                r["assignments"]["codes"].get("sartorius") in NAMED for r in records
            ):
                reads("sartorius", ("region",), "draw")
            # the extensor tendons, which the sagittal middle slices name
            if any(
                r["assignments"]["codes"].get(name) in NAMED
                for r in records
                for name in ("patellar_tendon", "quadriceps_tendon")
            ):
                reads("tendons", ("region",), "draw")
            # the rest of the field, the fat under the skin and muscle, which a slice without fat
            # suppression names
            if any(
                r["assignments"]["codes"].get(name) in NAMED
                for r in records
                for name in ("subcutaneous_fat", "muscle")
            ):
                reads("rest_of_the_field", ("region",), "draw")
        if drawn:
            for part in sorted(
                {r["main_slice"]["object"].lower() for r in main_records}
            ):
                reads(part, ("main_slice", "region"), "draw")
            if any(
                r["assignments"]["codes"].get("semitendinosus") in NAMED
                for r in main_records
            ):
                reads("semitendinosus", ("region",), "draw")
            if any(
                r["assignments"]["codes"].get("popliteus_tendon") in NAMED
                for r in main_records
            ):
                reads("popliteus_tendon", ("region",), "draw")
            if any(
                r["assignments"]["codes"].get("gracilis") in NAMED for r in main_records
            ):
                reads("gracilis", ("region",), "draw")
            # the bursa, which the semimembranosus tendon's slice names
            if any(
                r["assignments"]["codes"].get("gastrocnemius_semimembranosus_bursa")
                == "identified"
                for r in main_records
            ):
                reads("bursa", ("region",), "draw")
        telemetry = ledger_reading(led.events(), led.totals())
    series_uids = [series.row.series_uid for series in study.series]
    return {
        "study_uid": study_uid,
        "series_uids": series_uids,
        "records": records,
        "unread": unread,
        "main_records": main_records,
        "main_unread": main_unread,
        # the main receipt's own keys, so a part's old silence goes when the study is read again;
        # a bare series uid clears what was kept before the silences were kept per part
        "main_keys": series_uids
        + [f"{uid}:{part}" for uid in series_uids for part in MAIN_PARTS],
        "telemetry": telemetry,
        "named": named_parts(records, main_records),
        "study_map": study_map["counts"],
        # what the views say of each object, grouped by object, provenance and property: the
        # operation's output of anatomy, kept in the interiors receipt beside its records
        "objects": describe_objects(records + main_records, MAP_NAMES, main_unread),
    }


@cache
def opened(root: Path) -> Corpus:
    """The corpus at `root`, opened once per process, its decoders checked and its tables read
    once, for every study the process measures."""
    return open_corpus(root)


def measure_study_at(
    root: Path, study_uid: str, run_dir: Path, main_run: Path, drawn: bool
) -> dict:
    """`measure_study` in a worker process, from the corpus it opened once (`opened`)."""
    return measure_study(opened(root), study_uid, run_dir, main_run, drawn)


def keep(result: dict, run_dir: Path, main_run: Path) -> None:
    """Merge one study's result into the run's two receipts: the one writer of either."""
    uid, series_uids = result["study_uid"], result["series_uids"]
    write_receipt(
        run_dir,
        uid,
        series_uids,
        result["records"],
        result["unread"],
        result["telemetry"],
        result["objects"],
    )
    write_receipt(
        main_run,
        uid,
        result["main_keys"],
        result["main_records"],
        result["main_unread"],
        None,
    )


def draw_study(
    result: dict,
    run_dir: Path,
    out: Path,
    assignments_out: Path,
    main_run: Path,
    main_out: Path,
    root: Path,
) -> list[Path]:
    """Draw one study from the saved run, once it is in the receipts; return its pictures. The
    renderers are imported here, so a run that draws nothing never loads the drawing layer."""
    import object_assignments
    import object_bones
    import object_interiors
    import object_joint
    import object_patella
    import object_recess

    uid = result["study_uid"]
    pictures: list[Path] = []
    if result["records"]:
        object_interiors.draw(run_dir, uid, out)
        object_assignments.draw(run_dir, uid, assignments_out)
        pictures += [out / "series.png", assignments_out / "series.png"]
        # the femur's and the tibia's profile and pointed planes, from the series' own pixels
        volumes = {
            x.row.series_uid: x.volume for x in read_study(opened(root), uid).series
        }
        pictures += object_bones.draw(run_dir, uid, out / "bones", lambda u: volumes[u])
        # the patella's profile and pointed planes, and the tendons and pads read beside them
        pictures += object_patella.draw(
            run_dir, uid, out / "patella", lambda u: volumes[u]
        )
        # the joint's four profiles, its pointed planes and what the existing rules read on them
        pictures += object_joint.draw(run_dir, uid, out / "joint", lambda u: volumes[u])
        # the fluid pointer's profile, its pointed planes and what the existing rules read on them
        pictures += object_recess.draw(
            run_dir, uid, out / "recess", lambda u: volumes[u]
        )
    if result["main_records"]:
        object_assignments.draw(main_run, uid, main_out)
        pictures.append(main_out / "series.png")
    return pictures


def on_disk(corpus: Corpus, uids: Iterable[str]) -> list[str]:
    """The given studies whose series are all on disk, in the order given."""
    found = []
    for uid in uids:
        study = corpus.tables.studies[uid]
        if all(series_directory(corpus, study, s).is_dir() for s in study.series):
            found.append(uid)
    return found


def report(result: dict, args: argparse.Namespace) -> None:
    """Keep one study in the receipts, draw it when asked, and say what it named and what no
    stage read."""
    keep(result, args.run, args.main_run)
    uid = result["study_uid"]
    parts = ", ".join(f"{name} {count}" for name, count in result["named"].items())
    unread = ", ".join(result["telemetry"]["read_by_no_stage"])
    shared = ", ".join(
        f"{kind} {tally['made']} made, {tally['handed_on']} handed on"
        for kind, tally in result["telemetry"]["computed_once"].items()
    )
    print(uid, flush=True)
    print(f"  named, by series: {parts or 'nothing'}", flush=True)
    print(f"  produced and read by no stage: {unread or 'none'}", flush=True)
    seen = ", ".join(
        f"{name} {len(entry['native_series'])}/"
        f"{sum(len(v) for kinds in entry['observations'].values() for v in kinds.values())}"
        for name, entry in result["objects"].items()
    )
    print(
        f"  objects (series that resolved it natively/properties kept): {seen}",
        flush=True,
    )
    print(f"  computed once and handed on: {shared or 'nothing'}", flush=True)
    counts = result["study_map"]
    print(
        "  study map: "
        + ", ".join(f"{k} {v}" for k, v in counts.items() if k != "uses")
        + f"; uses {counts['uses']}",
        flush=True,
    )
    if args.draw:
        for picture in draw_study(
            result,
            args.run,
            args.out / uid,
            args.assignments_out / uid,
            args.main_run,
            args.main_out / uid,
            args.root,
        ):
            print(f"  {picture}", flush=True)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    which = parser.add_mutually_exclusive_group(required=True)
    which.add_argument("--study-uid", nargs="+")
    which.add_argument(
        "--labeled",
        action="store_true",
        help="every labelled study whose series are all on disk",
    )
    which.add_argument(
        "--split",
        choices=sorted(SPLIT_FOLDER),
        help="every study of one split whose series are all on disk; a kernel is given the test split",
    )
    parser.add_argument(
        "--root",
        type=Path,
        default=KAGGLE_ROOT if KAGGLE_ROOT.is_dir() else ROOT / LOCAL_ROOT,
        help="the competition's files: where a kernel mounts them when that exists, else data/raw",
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=os.cpu_count() or 1,
        help="studies measured side by side, one process each",
    )
    parser.add_argument(
        "--draw",
        action="store_true",
        help="development only: draw each study's pictures, and read what only they read (each "
        "middle slice's border readings); off by default, as in competition, where a run reads "
        "no border",
    )
    parser.add_argument(
        "--run", type=Path, default=ROOT / "data/measurements/interiors"
    )
    parser.add_argument("--out", type=Path, default=ROOT / "data/pictures/interiors")
    parser.add_argument(
        "--assignments-out", type=Path, default=ROOT / "data/pictures/assignments"
    )
    parser.add_argument(
        "--main-run", type=Path, default=ROOT / "data/measurements/main-slices"
    )
    parser.add_argument(
        "--main-out", type=Path, default=ROOT / "data/pictures/main-slices"
    )
    args = parser.parse_args()
    corpus = opened(args.root)
    if args.labeled:
        uids = on_disk(corpus, labeled_uids(corpus.tables))
    elif args.split:
        uids = on_disk(corpus, split_uids(corpus.tables, args.split))
    else:
        uids = args.study_uid
    workers = max(1, min(args.workers, len(uids)))
    if workers == 1:
        for uid in uids:
            report(measure_study(corpus, uid, args.run, args.main_run, args.draw), args)
        return
    with ProcessPoolExecutor(max_workers=workers) as pool:
        results = pool.map(
            measure_study_at,
            repeat(args.root),
            uids,
            repeat(args.run),
            repeat(args.main_run),
            repeat(args.draw),
        )
        # In the order asked; this process alone writes the receipts.
        for result in results:
            report(result, args)


if __name__ == "__main__":
    main()
